/**
 * Headless smoke + playability check for Kaasuvoima.
 *
 *   npm i -D playwright && npx playwright install chromium
 *   node tools/verify.mjs
 *
 * Serves the repo itself, drives the game in Chromium and reports:
 *   - page/console errors
 *   - every level loading with a sane spawn and an exit
 *   - a bot playthrough of each level (how far it gets, and why it stopped)
 *   - power-ups, ummetus, save states
 *
 * Exits non-zero on hard failures. Bot deaths are reported, not failed —
 * the bot only runs right and jumps, so it dies to things a human wouldn't.
 *
 * Env: PW_BROWSER=/path/to/chromium  PORT=8123  HEADED=1
 */
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const PORT = Number(process.env.PORT || 8123);

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
};

function serve() {
  const server = createServer(async (req, res) => {
    const url = decodeURIComponent(req.url.split('?')[0]);
    const rel = normalize(url === '/' ? '/index.html' : url).replace(/^(\.\.[/\\])+/, '');
    try {
      const body = await readFile(join(ROOT, rel));
      res.writeHead(200, { 'Content-Type': MIME[extname(rel)] || 'application/octet-stream' });
      res.end(body);
    } catch {
      res.writeHead(404).end('not found');
    }
  });
  return new Promise((resolve) => server.listen(PORT, '127.0.0.1', () => resolve(server)));
}

/**
 * WHAT COUNTS AS "the overworld".
 *
 * There are two of them since 19.8.2026 — the globe is the default and the
 * flat map is the fallback — and three checks below care that a level, a
 * continue or a challenge link lands you on one, not which one. Naming the
 * pair once keeps that from decaying into "some scene appeared", which is
 * what each of those checks would have become if it had been relaxed on its
 * own.
 */
const OVERWORLDS = ['GlobeScene', 'WorldMapScene'];
const isOverworld = (name) => OVERWORLDS.includes(name);

let chromium;
let devices;
try {
  // PW_MODULE lets a global install be used instead of a local devDependency.
  ({ chromium, devices } = await import(process.env.PW_MODULE || 'playwright'));
} catch {
  console.error('playwright is missing. Run:  npm i -D playwright && npx playwright install chromium');
  process.exit(2);
}

const server = await serve();
const browser = await chromium.launch({
  headless: !process.env.HEADED,
  ...(process.env.PW_BROWSER ? { executablePath: process.env.PW_BROWSER } : {}),
});
const page = await browser.newPage();

/* Pages julkaisee repon nimen alle, joten tämä on repon nimi eikä maku. */
const REPO_SLUG = 'kaasuvoima';

const errors = [];
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
page.on('console', (m) => {
  const text = m.text();
  if (m.type() === 'error' && !text.includes('favicon')) errors.push(`[console] ${text}`);
});

await page.goto(`http://127.0.0.1:${PORT}`, { waitUntil: 'networkidle' });
await page.waitForTimeout(400);

const booted = await page.evaluate(() => !!window.sfb3);

const report = await page.evaluate(async (OVERWORLDS) => {
  /* Handed in rather than written twice: this body runs in the page and the
   * challenge-link check below runs in node, and two lists of what an
   * overworld is are two lists that can disagree. */
  const isOverworld = (name) => OVERWORLDS.includes(name);
  const { LevelScene } = await import('/src/scenes/level.js');
  const { PLAYER_SIZES, FLOOR_REACH } = await import('/src/gfx/sprites.js');
  const { isSolid, isSemi } = await import('/src/gfx/tiles.js');
  const { levelIds, getLevel: getLevelDef } = await import('/src/data/levels.js');
  const { captureState, restoreState } = await import('/src/core/savestate.js');
  const { WORLDS } = await import('/src/data/worlds.js');
  const { DEFAULT_SAVE } = await import('/src/core/save.js');
  const game = window.sfb3;

  const blank = () => ({
    left: false, right: false, up: false, down: false, jump: false, run: false,
    start: false, mute: false, quicksave: false, quickload: false, slot: false,
  });
  const mkInput = () => ({
    held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
  });
  /*
   * Pelitila rakennetaan `DEFAULT_SAVE`sta eikä käsin, ja se on korjaus.
   *
   * Tässä lueteltiin kentät nimeltä, eli portti piti **omaa kopiotaan
   * tallennuksen muodosta**. Seuraus ei ole että testi kaatuu vaan että se ei
   * näe uutta kenttää lainkaan: `secrets`, `continues`, `bestTimes` ja nyt
   * `doors` puuttuivat jokaisesta testistä, ja koodi joka lukee niitä sai
   * `undefined`in siellä missä pelaajalla on `{}`. Ero on juuri se jossa
   * puuttuvan kentän käsittely jää testaamatta.
   *
   * Ylikirjoitukset ovat testiharnessin omia: enemmän elämiä kuin oletus, ja
   * solmu jotta karttaan palaaminen ei ole erikoistapaus.
   */
  const reset = (power = { type: null, level: 0 }) => {
    game.state = {
      ...DEFAULT_SAVE(),
      lives: 5, power, world: 0, node: 'w1-1', cards: [],
    };
    game.finishLevel = () => {};
  };

  const levels = [];
  const failures = [];
  const checks = [];
  let ruleReport = [];

  /* ------------------------------- levels ------------------------------ */
  for (const id of levelIds()) {
    const entry = { id };
    try {
      reset();
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const scene = new LevelScene(game, id);
      entry.width = scene.w;
      entry.entities = scene.entities.length;

      const hasExit = !!scene.goal || scene.entities.some((e) => e.constructor.name === 'Boss');
      if (!hasExit) failures.push(`${id}: no goal and no boss`);

      const sx = Math.floor(scene.player.x / 16);
      const sy = Math.floor((scene.player.y + scene.player.h - 1) / 16);
      if (isSolid(scene.tileAt(sx, sy))) failures.push(`${id}: spawn inside a solid tile`);

      const stuck = scene.entities.filter((e) => {
        if (e.constructor.name === 'Plant' || e.kind === 'hazard') return false;
        return isSolid(scene.tileAt(Math.floor(e.cx / 16), Math.floor((e.y + e.h - 1) / 16)));
      });
      if (stuck.length) {
        const where = stuck.slice(0, 4)
          .map((e) => `${e.constructor.name}@${Math.floor(e.cx / 16)},${Math.floor(e.y / 16)}`)
          .join(' ');
        failures.push(`${id}: ${stuck.length} enemies inside walls — ${where}`);
      }

      // dumb bot: run right, jump over walls, gaps, enemies; wait out fire jets
      const input = mkInput();
      let prevJump = false; let hold = 0; let maxX = 0; let cause = null;
      for (let frame = 0; frame < 7000 && !finished; frame++) {
        const p = scene.player;
        const footY = Math.floor((p.y + p.h) / 16);
        const aheadX = Math.floor((p.x + p.w + 6) / 16);
        const solid = (tx, ty) => isSolid(scene.tileAt(tx, ty));
        const hazardTile = (tx, ty) => '^W'.includes(scene.tileAt(tx, ty));
        const wall = solid(aheadX, footY - 1) || solid(aheadX, footY - 2);
        const gap = !solid(aheadX, footY) && !solid(aheadX + 1, footY);
        const burn = hazardTile(aheadX, footY) || hazardTile(aheadX, footY - 1);
        const foe = scene.entities.some((e) => e.kind === 'enemy' && !e.dying
          && e.cx > p.cx && e.cx - p.cx < 48 && Math.abs(e.cy - p.cy) < 40);
        const jet = scene.entities.some((e) => e.kind === 'hazard'
          && e.phase !== 'idle' && e.x > p.x - 8 && e.x - p.x < 44);
        const takeOff = p.onGround && (wall || gap || foe || burn);
        if (takeOff) hold = 16;
        const wantJump = takeOff || (hold > 0 && p.vy < 0);
        if (hold > 0) hold--;
        input.held = blank();
        input.held.right = !jet;
        input.held.run = true;
        input.held.jump = wantJump;
        input.pressed = blank();
        input.pressed.jump = takeOff && !prevJump;
        prevJump = wantJump;
        const beforeY = p.y;
        scene.update(input);
        maxX = Math.max(maxX, p.x);
        if (scene.state === 'dead' && !cause) {
          cause = beforeY > scene.heightPx - 40 ? 'pit' : 'hit';
        }
      }
      entry.result = finished ? (finished.cleared ? 'CLEARED' : 'DIED') : 'TIMEOUT';
      entry.progress = Math.round((maxX / (scene.w * 16)) * 100);
      entry.cause = cause;
    } catch (err) {
      entry.result = 'ERROR';
      failures.push(`${id}: ${err.message}`);
    }
    levels.push(entry);
  }

  /* ------------------------------ mechanics ---------------------------- */
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  {
    reset();
    const s = new LevelScene(game, '1-1');
    const sizes = [];
    for (let i = 0; i < 5; i++) { sizes.push(s.player.h); s.player.collect('shroom'); }
    sizes.push(s.player.h);
    const grows = sizes.every((h, i) => i === 0 || h > sizes[i - 1]);
    expect('power levels 1-5 grow the body', s.player.powerLevel === 5 && grows, sizes.join('/'));
  }

  {
    reset({ type: 'shroom', level: 2 });
    const s = new LevelScene(game, '1-1');
    const i = mkInput();
    for (let f = 0; f < 5; f++) s.update(i);
    const ground = s.player.y;
    i.pressed.jump = true; i.held.jump = true;
    s.update(i); i.pressed = blank();
    for (let f = 0; f < 22; f++) s.update(i);
    const h1 = ground - s.player.y;
    i.pressed.jump = true; s.update(i); i.pressed = blank();
    for (let f = 0; f < 18; f++) s.update(i);
    const h2 = ground - s.player.y;
    expect('fart mushroom double jump climbs higher', h2 > h1 + 20, `${Math.round(h1)} -> ${Math.round(h2)}`);
  }

  {
    reset({ type: 'shroom', level: 3 });
    const s = new LevelScene(game, '1-1');
    const before = s.player.airJumpsMax;
    s.player.cork(300);
    const during = s.player.airJumpsMax;
    s.player.collect('soup');
    expect('ummetus blocks the gas, soup cures it',
      before === 3 && during === 0 && s.player.corked === 0);
  }

  {
    reset({ type: 'leaf', level: 3 });
    const s = new LevelScene(game, '1-1');
    game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-1');
    game.setScene(s);
    const i = mkInput();
    i.held.right = true; i.held.run = true;
    for (let f = 0; f < 120; f++) { s.update(i); i.pressed = blank(); }
    const snap = captureState(game);
    const before = `${Math.round(s.player.x)}|${s.time}|${s.entities.length}`;
    s.player.x += 400; s.time = 5; s.entities = []; game.state.coins = 999;
    restoreState(game, JSON.parse(JSON.stringify(snap)));
    const r = game.scene;
    const after = `${Math.round(r.player.x)}|${r.time}|${r.entities.length}`;
    for (let f = 0; f < 30; f++) r.update(mkInput());
    expect('save state restores the level exactly', before === after, `${before} vs ${after}`);
    expect('restored level keeps running', r.player.x > 0 && !!r.player.update);
  }

  /* Landing on two enemies at once must not stomp one and kill you on the
   * other: the stomp test has to use the fall speed the player arrived with,
   * not the bounce speed the first stomp just gave them. */
  {
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const { Walker } = await import('/src/entities/enemies.js');
    const i = mkInput();
    for (let f = 0; f < 4; f++) s.update(i);

    const groundY = s.player.y + s.player.h;
    const px = s.player.cx;
    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    const a = new Walker(s, px - 8, groundY - 16);
    const b = new Walker(s, px + 8, groundY - 16);
    for (const e of [a, b]) { e.active = true; e.alwaysActive = true; e.vx = 0; s.entities.push(e); }

    // Drop the player onto the pair from just above them.
    s.player.y = groundY - 16 - s.player.h - 6;
    s.player.vy = 4;
    s.player.onGround = false;
    const powerBefore = s.player.powerLevel;
    for (let f = 0; f < 6 && !s.player.dying; f++) s.update(i);

    const squashed = [a, b].filter((e) => e.dying || e.remove || !e.stompable).length;
    const unhurt = !s.player.dying && s.player.powerLevel === powerBefore;
    expect('stomping two enemies at once does not hurt the player',
      unhurt && s.state === 'play' && squashed >= 1,
      `power ${powerBefore}->${s.player.powerLevel}, ${squashed}/2 squashed`
      + `${s.player.dying ? ', died' : ''}`);
  }

  /* ------------------------------ maahanisku ---------------------------- */
  /*
   * Maahanisku on tasapainoväite ennen kuin se on mekaniikka, ja väite on se
   * mikä voi mennä rikki. "Liike on olemassa" menisi läpi myös silloin kun
   * liike on korvannut tallauksen, joten alla mitataan hintaa ja rajoja:
   * montako framea ohjausta menetetään, tainnuttaako tavallisen hypyn mittainen
   * isku vai tappaako se, voittavatko piikit, ja mihin korkeusasteikko on
   * normalisoitu.
   *
   * Koko lohko on try/catchissa siksi että ensimmäinen ajo on tarkoituksella
   * punainen: puuttuva nimetty vienti kaataisi dynaamisen importin ja sen
   * mukana kaikki tämän jälkeen tulevat tarkistukset, jolloin punaisesta ei
   * näkisi mitään.
   */
  try {
    const { SpikeGuy, Walker, Shockwave } = await import('/src/entities/enemies.js');
    const { poundScale, POUND_CHARGE, POUND_SPEED } = await import('/src/entities/player.js');
    const { PoundWave } = await import('/src/entities/effects.js');

    /**
     * Korkein y johon pelaajan pää yltää siinä sarakkeessa jossa hän seisoo.
     * Katto (`ty < 0` on kiinteä) on 0, joten tyhjässä sarakkeessa tämä on
     * täsmälleen se suurin mahdollinen pudotus jota vastaan asteikko
     * normalisoidaan — mitattuna kentästä eikä arvattuna vakiona.
     */
    const roomAbove = (s, p) => {
      const tx0 = Math.floor(p.x / 16);
      const tx1 = Math.floor((p.x + p.w - 1) / 16);
      const blocked = (ty) => {
        for (let tx = tx0; tx <= tx1; tx++) if (s.solidAt(tx, ty)) return true;
        return false;
      };
      let ty = Math.floor(p.y / 16);
      while (ty - 1 >= 0 && !blocked(ty - 1)) ty--;
      return ty * 16;
    };

    /** Kenttä pystyyn, viholliset pois, pelaaja seisomaan omalle lattialleen. */
    const setup = (opts = {}) => {
      const { id = '1-1', power = { type: null, level: 0 } } = opts;
      reset(power);
      const s = new LevelScene(game, id);
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      return { s, i, standY: s.player.y };
    };

    const lift = (s, y) => {
      s.player.y = y;
      s.player.vy = 0;
      s.player.onGround = false;
    };

    /** Painaa alas + hyppy ja ajaa kunnes isku on osunut maahan. */
    const pound = (s, i, cap = 400) => {
      i.held.down = true;
      i.pressed.jump = true;
      i.held.jump = true;
      s.update(i);
      i.pressed = blank();
      i.held.jump = false;
      let f = 1;
      while (f < cap && !s.lastPound) { s.update(i); f++; }
      return f;
    };

    /* 1. Perusliikkeen pitää toimia voimatasolla 0. Tehostus avaa paikkoja,
     *    ei kenttää — ja siksi ei myöskään liikettä. */
    {
      const { s, i, standY } = setup();
      lift(s, standY - 70);
      const frames = pound(s, i);
      const lp = s.lastPound;
      expect('maahanisku toimii voimatasolla 0',
        !!lp && s.player.powerLevel === 0 && lp.reach > 0 && lp.strength > 0,
        lp ? `voimataso 0, pudotus ${Math.round(lp.fall)}/${Math.round(lp.room)} px`
          + `, voima ${lp.strength.toFixed(2)}, säde ${lp.reach} px, ${frames} framea`
          : `iskua ei tullut ${frames} framessa`);
    }

    /* 2. Hinta numeroina: syöksy ei ohjaudu, ja siihen menee aikaa. Sama
     *    korkeus, sama nappi pohjassa, kaksi eri tapaa tulla alas. */
    {
      const free = setup();
      lift(free.s, free.standY - 70);
      free.i.held.right = true;
      const freeX = free.s.player.x;
      let freeFrames = 0;
      while (freeFrames < 400 && !free.s.player.onGround) { free.s.update(free.i); freeFrames++; }
      const freeDrift = free.s.player.x - freeX;

      const dive = setup();
      lift(dive.s, dive.standY - 70);
      dive.i.held.right = true;
      const diveX = dive.s.player.x;
      let diveFrames = pound(dive.s, dive.i);
      // ...ja maassa vielä se hetki jona ei pääse mihinkään.
      while (diveFrames < 400 && dive.s.player.poundPhase !== '') {
        dive.s.update(dive.i);
        diveFrames++;
      }
      const diveDrift = dive.s.player.x - diveX;

      expect('maahanisku maksaa ohjaamattoman ajan, tavallinen putoaminen ei',
        diveDrift < 1 && freeDrift > 10 && diveFrames > freeFrames + 20,
        `vapaa pudotus ${freeFrames} framea ja ${Math.round(freeDrift)} px sivuun`
        + `, maahanisku ${diveFrames} framea ja ${Math.round(diveDrift)} px`
        + ` (lataus ${POUND_CHARGE} framea, syöksy ${POUND_SPEED} px/frame)`);
    }

    /* 3. Eikä se korvaa tallausta. Sama korkeus, sama kävelijä, ja kumpikin
     *    liike saa oman parhaan tapauksensa: tallaus laskeutuu vihollisen
     *    päälle, maahanisku maahan sen viereen — päälle syöksyminen olisi
     *    tallaus eikä maahanisku, koska `bounce` peruu iskun. Mitataan kaksi
     *    asiaa: montako framea pelaaja on ilman ohjausta, ja kuoleeko vihollinen
     *    vai jääkö se henkiin tainnutettuna. */
    {
      const stomp = setup({ power: { type: 'shroom', level: 1 } });
      const feetY = stomp.standY + stomp.s.player.h;
      const walkerA = new Walker(stomp.s, stomp.s.player.x + 2, feetY - 16);
      walkerA.active = true; walkerA.alwaysActive = true; walkerA.vx = 0; walkerA.speed = 0;
      stomp.s.entities.push(walkerA);
      lift(stomp.s, stomp.standY - 70);
      stomp.i.held.right = true;
      let stompStill = 0;
      for (let f = 0; f < 120; f++) {
        stomp.s.update(stomp.i);
        stomp.i.pressed = blank();
        if (stomp.s.player.vx === 0) stompStill++;
      }

      const slam = setup({ power: { type: 'shroom', level: 1 } });
      const walkerB = new Walker(slam.s, slam.s.player.x + 22, slam.standY + slam.s.player.h - 16);
      walkerB.active = true; walkerB.alwaysActive = true; walkerB.vx = 0; walkerB.speed = 0;
      slam.s.entities.push(walkerB);
      lift(slam.s, slam.standY - 70);
      slam.i.held.right = true;
      slam.i.held.down = true;
      slam.i.pressed.jump = true;
      slam.i.held.jump = true;
      let slamStill = 0;
      /* Iskun lopputulos luetaan siltä framelta jolla isku osui, ei lopusta:
       * pelaaja kävelee oikealle vielä kymmeniä frameja sen jälkeen ja
       * puhkaisisi kuplan itse, mikä näyttäisi siltä että isku tappoi. */
      let outcome = null;
      let gap = 0;
      for (let f = 0; f < 120; f++) {
        slam.s.update(slam.i);
        slam.i.pressed = blank();
        slam.i.held.jump = false;
        // Alas irti heti käskyn jälkeen: kyykky pysäyttäisi pelaajan omasta
        // syystään, ja silloin mittari laskisi kyykkyä eikä maahaniskua.
        slam.i.held.down = false;
        if (slam.s.player.vx === 0) slamStill++;
        if (slam.s.lastPound && !outcome) {
          outcome = {
            killed: walkerB.remove || walkerB.dying,
            stunned: walkerB.bubbled || walkerB.harmless,
          };
          gap = Math.round(walkerB.cx - slam.s.player.cx);
        }
      }

      const lp = slam.s.lastPound;
      const stompKilled = walkerA.remove || walkerA.dying || walkerA.squash > 0;
      const slamKilled = !!outcome && outcome.killed;
      const slamStunned = !!outcome && outcome.stunned;
      expect('maahanisku ei korvaa tallausta: se maksaa ohjaamattomia frameja',
        slamStill - stompStill >= 24,
        `tallaus ${stompStill} framea ilman ohjausta, maahanisku ${slamStill}`
        + ` (ero ${slamStill - stompStill})`);
      expect('tavallisen hypyn korkeudelta isku tainnuttaa, tallaus tappaa',
        !!lp && stompKilled && !slamKilled && slamStunned,
        `voima ${lp ? lp.strength.toFixed(2) : 'ei iskua'}`
        + `, säde ${lp ? lp.reach : '-'} px ja kävelijä ${gap} px sivussa`
        + `, tallaus tappoi ${stompKilled}, isku tappoi ${slamKilled}`
        + `, isku tainnutti ${slamStunned}`);
    }

    /* 4. PIIKIT JA MAAHANISKU, ja tässä sääntö kääntyi 17.8.2026.
     *
     *    Ennen: isku ohitti jokaisen piikikkään kokonaan. Nyt: shokkiaalto
     *    kulkee maata pitkin eikä välitä siitä mitä vihollisella on päässään,
     *    joten piikkiukko **kaatuu kumoon** siinä missä muutkin — ja kumossa
     *    se on ylösalaisin eli ensimmäistä kertaa tallattavissa.
     *
     *    Piikikkyys ei silti lakkaa tarkoittamasta mitään, ja se on tämän
     *    väitteen b-puoli: jaloilleen seisovan piikkiukon **päälle** syöksyvä
     *    pelaaja häviää yhä täsmälleen kuten tallaajakin. Piikit ovat suoja
     *    päältä, eivät suoja kaikelta. */
    {
      /* a) Säteen sisällä mutta ei alla. Isku osuu maahan asti, joten säde on
       *    mitattavissa, ja piikkiukon pitää seistä siinä ehjänä vaikka aalto
       *    yltää sen yli. */
      const beside = setup({ power: { type: 'shroom', level: 3 } });
      const bp = beside.s.player;
      const guard = new SpikeGuy(beside.s, bp.x + 30, beside.standY + bp.h - 16);
      guard.active = true; guard.alwaysActive = true; guard.speed = 0; guard.vx = 0;
      beside.s.entities.push(guard);
      lift(beside.s, roomAbove(beside.s, bp));
      pound(beside.s, beside.i, 400);
      const lp = beside.s.lastPound;
      const gap = Math.round(guard.cx - bp.cx);
      expect('maahaniskun aalto kaataa piikkiukon kumoon eikä tapa sitä',
        !!lp && lp.reach >= gap && guard.flipped && !guard.remove && !guard.dying
        && !guard.bubbled && guard.harmless && !guard.dangerousTop,
        lp ? `säde ${lp.reach} px, piikkiukko ${gap} px päässä, voima`
          + ` ${lp.strength.toFixed(2)}, kumossa ${guard.flipped}, hengissä`
          + ` ${!guard.remove && !guard.dying}, vaarallinen päältä`
          + ` ${guard.dangerousTop}`
          : 'iskua ei tullut');

      /* b) Ja suoraan piikkien päälle syöksyminen häviää täsmälleen kuten
       *    tallaus häviää. `sawDive` on siksi että pelkkä "pelaaja sattui" olisi
       *    yhtä hyvin voinut tarkoittaa että hän käveli päin. */
      const onto = setup({ power: { type: 'shroom', level: 3 } });
      const op = onto.s.player;
      const target = new SpikeGuy(onto.s, op.x, onto.standY + op.h - 16);
      target.active = true; target.alwaysActive = true; target.speed = 0; target.vx = 0;
      onto.s.entities.push(target);
      const levelBefore = op.powerLevel;
      lift(onto.s, onto.standY - 70);
      onto.i.held.down = true;
      onto.i.pressed.jump = true;
      onto.i.held.jump = true;
      let sawDive = false;
      for (let f = 0; f < 90; f++) {
        onto.s.update(onto.i);
        onto.i.pressed = blank();
        onto.i.held.jump = false;
        if (op.poundPhase === 'dive') sawDive = true;
      }
      /* Suoraan piikkien **päälle** syöksyminen häviää yhä, ja se on tämän
       * muutoksen raja: aalto lähtee vasta laskeutumisesta, ja keho ehtii
       * koskettaa piikkejä ennen sitä. Piikikkään yli pääsee siis iskemällä
       * sen *viereen* (a-kohta yllä) — ei sen päälle. Piikit ovat yhä suoja
       * päältä, ja se on niiden koko merkitys. */
      expect('piikit voittavat päälle syöksymisen täsmälleen kuten ne voittavat tallauksen',
        sawDive && !target.remove && !target.dying && !target.bubbled
        && op.powerLevel === levelBefore - 1,
        `syöksy nähtiin ${sawDive}, piikkiukko hengissä`
        + ` ${!target.remove && !target.dying}, voimataso ${levelBefore}->${op.powerLevel}`);
    }

    /* 5. Korkeusasteikko. Katto on `ty < 0`, joten suurin mahdollinen pudotus
     *    on laskeutumiskohdan oma y — mitattu luku, ei arvattu vakio. Kaksi
     *    kenttää joissa se luku on eri, ja molemmista katosta tehty isku on
     *    täydet 1,00. Vakioon sidottu asteikko ei voi antaa kumpaakin. */
    {
      const ceiling = [];
      for (const id of levelIds()) {
        if (ceiling.length >= 2 && Math.abs(ceiling[0].fall - ceiling[1].fall) > 60) break;
        let probe;
        try { probe = setup({ id }); } catch { continue; }
        const { s, i } = probe;
        if (roomAbove(s, s.player) !== 0) continue;
        lift(s, 0);
        pound(s, i, 400);
        if (!s.lastPound) continue;
        const row = { id, fall: s.lastPound.fall, room: s.lastPound.room, t: s.lastPound.strength };
        if (ceiling.length < 2) ceiling.push(row);
        else if (Math.abs(row.fall - ceiling[0].fall) > Math.abs(ceiling[1].fall - ceiling[0].fall)) {
          ceiling[1] = row;
        }
      }
      const both = ceiling.length === 2;
      const spread = both ? Math.abs(ceiling[0].fall - ceiling[1].fall) : 0;
      const full = ceiling.every((c) => c.t > 0.995);
      expect('korkeusasteikko on normalisoitu mitattuun kattoon eikä vakioon',
        both && full && spread > 40,
        ceiling.map((c) => `${c.id} pudotus ${Math.round(c.fall)}/${Math.round(c.room)} px`
          + ` = ${c.t.toFixed(3)}`).join(', ') + ` — ero ${Math.round(spread)} px`);
      // Ja sama väite puhtaana laskutoimituksena, ilman kenttää välissä.
      /*
       * Ja sama väite puhtaana laskutoimituksena — mutta **uudella väitteellä**,
       * koska mitta vaihtui: asteikko oli osuus huoneen korkeudesta ja on nyt
       * pudotus pikseleinä (`POUND_FULL_FALL`, mitattu 174 px = pelin pisin
       * hyppy). Vanha kaava teki samasta hypystä eri iskun sen mukaan missä
       * päin kenttää seisoi — 100 px lattialle y=208 antoi 0,48 ja sama hyppy
       * luolassa y=650 antoi 0,15 — ja juuri se on se mitä omistaja pyysi
       * korjattavaksi. Tämä rivi mittaa sen: **sama pudotus, sama luku,
       * riippumatta siitä mihin se päättyy.**
       */
      const sameFall = poundScale(0, 100) === poundScale(500, 600);
      expect('sama pudotus antaa saman iskun riippumatta siitä missä maa on',
        sameFall && poundScale(0, 174) === 1 && poundScale(0, 400) === 1
        && poundScale(87, 174) === 0.5 && poundScale(176, 176) === 0,
        `100px matalalla ${poundScale(0, 100).toFixed(3)} ja syvällä `
        + `${poundScale(500, 600).toFixed(3)}, täysi ${poundScale(0, 174)}, `
        + `puolikas ${poundScale(87, 174)}, nolla ${poundScale(176, 176)}`);
    }

    /* 6. Mitä korkeammalta, sitä kovempaa — sekä vahingoltaan että ruudulla. */
    {
      const low = setup();
      lift(low.s, low.standY - 40);
      pound(low.s, low.i, 200);
      const a = low.s.lastPound;

      const high = setup();
      lift(high.s, roomAbove(high.s, high.s.player));
      pound(high.s, high.i, 400);
      const b = high.s.lastPound;

      expect('isku kovenee korkeuden mukana: säde, tärinä ja vahinko',
        !!a && !!b && b.strength > a.strength && b.reach > a.reach && b.shake > a.shake
        && !a.kills && b.kills,
        a && b ? `matala ${a.strength.toFixed(2)}: säde ${a.reach} tärinä ${a.shake.toFixed(1)}`
          + ` tappaa ${a.kills} — korkea ${b.strength.toFixed(2)}: säde ${b.reach}`
          + ` tärinä ${b.shake.toFixed(1)} tappaa ${b.kills}`
          : 'iskuja ei tullut');
    }

    /* 7. Iskuaalto on voimatason vahvistama eikä avaama: voimatasolla 0
     *    ylimmästä mahdollisesta korkeudesta se syntyy, ja voimataso vain
     *    laskee kynnystä. */
    {
      const bare = setup();
      lift(bare.s, roomAbove(bare.s, bare.s.player));
      pound(bare.s, bare.i, 400);
      const top = bare.s.lastPound;

      const mid = setup();
      lift(mid.s, mid.standY - 70);
      pound(mid.s, mid.i, 200);
      const weak = mid.s.lastPound;

      const strong = setup({ power: { type: 'shroom', level: 5 } });
      lift(strong.s, strong.standY - 70);
      pound(strong.s, strong.i, 200);
      const boosted = strong.s.lastPound;

      expect('iskuaalto: voimataso 0 saa sen korkeudella, voimataso 5 halvemmalla',
        !!top && top.wave && !!weak && !weak.wave && !!boosted && boosted.wave,
        top && weak && boosted
          ? `voima 0 katosta ${top.strength.toFixed(2)} aalto ${top.wave}`
          + `, voima 0 hypystä ${weak.strength.toFixed(2)} aalto ${weak.wave}`
          + `, voima 5 hypystä ${boosted.strength.toFixed(2)} aalto ${boosted.wave}`
          : 'iskuja ei tullut');
    }

    /* 8. Ummetus tukkii kaasun, ja maahanisku on kaasua. Sama sääntö kuin
     *    pieruhypyllä, tehostushyökkäyksellä ja lennolla. */
    {
      const { s, i, standY } = setup({ power: { type: 'shroom', level: 2 } });
      lift(s, standY - 60);
      s.player.cork(300);
      i.held.down = true; i.pressed.jump = true; i.held.jump = true;
      s.update(i); i.pressed = blank();
      const corkedPhase = s.player.poundPhase;
      s.player.collect('soup');
      for (let f = 0; f < 24; f++) { s.update(i); i.pressed = blank(); }
      lift(s, standY - 60);
      i.pressed.jump = true; i.held.jump = true;
      s.update(i); i.pressed = blank();
      expect('ummetus tukkii maahaniskun, hernekeitto avaa sen',
        corkedPhase === '' && s.player.poundPhase !== '',
        `tukossa "${corkedPhase}", keiton jälkeen "${s.player.poundPhase}"`);
    }

    /* 9. Pikatallennus kesken syöksyn palaa kesken syöksyn — muuten
     *    savestate.js:n REGISTRY pudottaa liikkeen hiljaa pois. */
    {
      const { s, i, standY } = setup();
      game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-1');
      lift(s, standY - 90);
      i.held.down = true; i.pressed.jump = true; i.held.jump = true;
      s.update(i); i.pressed = blank(); i.held.jump = false;
      let guard = 0;
      while (guard < 60 && s.player.poundPhase !== 'dive') { s.update(i); guard++; }
      for (let f = 0; f < 3; f++) s.update(i);
      const phase = s.player.poundPhase;
      const fromY = s.player.poundFromY;
      const midY = Math.round(s.player.y);
      const snap = captureState(game);
      restoreState(game, JSON.parse(JSON.stringify(snap)));
      const r = game.scene;
      const kept = r.player.poundPhase === phase && r.player.poundFromY === fromY
        && Math.round(r.player.y) === midY;
      let f = 0;
      while (f < 200 && !r.lastPound) { r.update(mkInput()); f++; }
      expect('pikatallennus kesken syöksyn palaa kesken syöksyn ja laskeutuu loppuun',
        kept && !!r.lastPound,
        `vaihe "${phase}" y ${midY} lähtö ${Math.round(fromY)}`
        + ` -> "${r.player.poundPhase}" y ${Math.round(r.player.y)}`
        + `, laskeutui ${f} framessa voimalla`
        + ` ${r.lastPound ? r.lastPound.strength.toFixed(2) : '-'}`);
    }

    /* 10. Pomon piikkisykli voittaa maahaniskun täsmälleen kuten tallauksen —
     *     ja avoimena ottaa osuman täsmälleen kuten tallauksesta.
     *
     *     Kahdella pomolla eikä yhdellä, ja jälkimmäinen on tässä siksi että
     *     luurankopomo (6-F, variantti 4) on ensimmäinen uusi pomo maahaniskun
     *     jälkeen. Sääntö "piikit voittavat senkin" on kirjoitettu
     *     `poundImpact`iin `e.spiky`-lipun varaan eikä varianttiluetteloon, eli
     *     sen *pitäisi* päteä uuteen pomoon ilmaiseksi — ja juuri sellainen
     *     väite kannattaa mitata, koska se on se joka rapautuu hiljaa. */
    for (const bossLevel of ['1-F', '6-F']) {
      const bossDive = (spiky) => {
        reset({ type: 'shroom', level: 3 });
        const s = new LevelScene(game, bossLevel);
        game.setScene(s);
        const i = mkInput();
        const boss = s.entities.find((e) => e.constructor.name === 'Boss');
        boss.speed = 0;
        boss.jumpTimer = 1e6;
        boss.chargeTimer = 1e6;
        boss.spikePhase = spiky ? 'spiky' : 'open';
        const p = s.player;
        p.x = boss.cx - p.w / 2;
        p.y = boss.y - p.h - 56;
        p.vy = 0;
        p.onGround = false;
        const hp0 = boss.hp;
        const lvl0 = p.powerLevel;
        i.held.down = true; i.pressed.jump = true; i.held.jump = true;
        s.update(i); i.pressed = blank(); i.held.jump = false;
        for (let f = 0; f < 90; f++) {
          boss.spikeTimer = 1e6;
          boss.doffTimer = 0;
          s.update(i);
        }
        return { hits: hp0 - boss.hp, lost: lvl0 - p.powerLevel };
      };
      const spikyRun = bossDive(true);
      const openRun = bossDive(false);
      expect(`${bossLevel}: pomon piikit voittavat maahaniskun, avoin pomo ottaa siitä osuman`,
        spikyRun.hits === 0 && spikyRun.lost === 1 && openRun.hits >= 1 && openRun.lost === 0,
        `piikeissä osumia ${spikyRun.hits} ja pelaaja menetti ${spikyRun.lost} tasoa`
        + `, avoinna osumia ${openRun.hits} ja menetti ${openRun.lost}`);
    }

    /* 11. DESIGN.md kohta 8: iskuaalto ei saa näyttää pomon iskuaallolta.
     *     Väri ja rytmi mitataan pikseleistä, koska "eri väriä" on väite jonka
     *     voi tarkistaa ja "näyttää erilaiselta" ei ole. */
    {
      const stage = setup();
      const c = document.createElement('canvas');
      c.width = 96;
      c.height = 40;
      const g = c.getContext('2d');
      const shot = (entity, tick) => {
        g.clearRect(0, 0, 96, 40);
        entity.tick = tick;
        if (entity instanceof PoundWave) entity.life = entity.maxLife - tick;
        entity.draw(g);
        return g.getImageData(0, 0, 96, 40).data;
      };
      const mean = (px) => {
        let r = 0; let gg = 0; let b = 0; let n = 0;
        for (let q = 0; q < px.length; q += 4) {
          if (px[q + 3] < 8) continue;
          r += px[q]; gg += px[q + 1]; b += px[q + 2]; n++;
        }
        return n ? [Math.round(r / n), Math.round(gg / n), Math.round(b / n)] : [0, 0, 0];
      };
      const distinct = (entity) => {
        const seen = new Set();
        for (let t = 0; t < 12; t++) seen.add([...shot(entity, t)].join(','));
        return seen.size;
      };

      const wave = new PoundWave(stage.s, 48, 24, 30);
      const boss = new Shockwave(stage.s, 42, 18, 1);
      const waveColor = mean(shot(wave, 3));
      const bossColor = mean(shot(boss, 3));
      const waveFrames = distinct(wave);
      const bossFrames = distinct(boss);
      // Kaasu on vihreää, pomon aalto ruskeaa: vihreän ja punaisen erotus on
      // se yksi luku joka erottaa ne toisistaan katsomatta kuvaa.
      const waveTilt = waveColor[1] - waveColor[0];
      const bossTilt = bossColor[1] - bossColor[0];
      expect('maahaniskun aalto on eri väriä ja eri rytmiä kuin pomon aalto',
        waveTilt > 20 && bossTilt < 0 && waveFrames >= 8 && bossFrames <= 3,
        `isku rgb(${waveColor.join(',')}) vihreä-punainen ${waveTilt}`
        + `, pomo rgb(${bossColor.join(',')}) ${bossTilt}`
        + `; eri ruutuja 12 framessa: isku ${waveFrames}, pomo ${bossFrames}`);
    }

    /* 12. MAAHANISKU RIKKOO LATTIAN, ja neljä asiaa siinä voi mennä rikki:
     *     liike joka ei riko mitään, liike joka rikkoo aina, liike joka rikkoo
     *     sen mitä se ei saa rikkoa, ja — 16.8.2026 alkaen — liike joka on
     *     eri mieltä päänpuskun kanssa siitä kuka tiilen rikkoo.
     *
     *     Koekenttä on tässä eikä oikea kenttä, koska ehto on korkeus JA keho,
     *     ja se vaatii tiiliriviä täsmälleen jalkojen alla. Riviä ei valita
     *     silmällä vaan mitataan: `brickSecret` päättää salaisuuden paikan
     *     hajautuksesta, joten koe etsii sarakkeen jossa yksikään tiili ei
     *     piilota mitään — muuten kokeen tulos riippuisi siitä mihin kohtaan
     *     ruudukkoa se sattui kirjoittamaan.
     */
    {
      const W = 48;
      const floorRows = (bricksAt) => {
        const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
        const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
        put(14, 0, '#'.repeat(W));
        put(15, 0, '#'.repeat(W));
        put(13, 1, '1');
        put(10, 6, '!');
        put(13, 44, 'F');
        // Tiililattia keskelle, ja sen alle kuilu johon läpi mennään.
        put(14, bricksAt, 'B'.repeat(6));
        return rows;
      };
      const brickDef = (bricksAt) => ({
        id: 'bFix', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows: floorRows(bricksAt),
      });

      /* Sarake jossa kuudesta lattiatiilestä yksikään ei piilota mitään. */
      let at = 20;
      {
        const probe = new LevelScene(game, 'bFix', brickDef(20));
        for (let x = 20; x < 34; x++) {
          let clean = true;
          for (let i = 0; i < 6; i++) if (probe.brickSecret(x + i, 13)) clean = false;
          if (clean) { at = x; break; }
        }
      }

      const dive = (power, fromAbove) => {
        reset(power);
        const s = new LevelScene(game, 'bFix', brickDef(at));
        game.setScene(s);
        const i = mkInput();
        for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
        s.entities = s.entities.filter((e) => e.kind !== 'enemy');
        // Jalat tiilirivin päälle ja sieltä ylös se korkeus jota kokeillaan.
        s.player.x = (at + 2) * 16;
        s.player.y = 14 * 16 - s.player.h - fromAbove;
        s.player.vy = 0;
        s.player.onGround = false;
        i.held.down = true; i.pressed.jump = true; i.held.jump = true;
        s.update(i); i.pressed = blank(); i.held.jump = false;
        let f = 1;
        while (f < 400 && !s.lastPound) { s.update(i); f++; }
        return s;
      };

      const weak = dive({ type: 'shroom', level: 5 }, 24);
      /* Tappava muttei rikkova. Tämä on se väli jonka `POUND_BREAK_AT`
       * `POUND_KILL_AT`in yläpuolella tarkoittaa, ja ilman tätä riviä koko
       * väite "lattian rikkominen on tiukempi vaatimus kuin tappaminen" ei ole
       * mitattu vaan kirjoitettu. */
      const lethal = dive({ type: 'shroom', level: 1 }, 110);
      const strongLow = dive({ type: 'shroom', level: 1 }, 150);
      const strong = dive({ type: 'shroom', level: 5 }, 150);

      expect('maahanisku rikkoo tiilen vain kyllin korkealta, ja se raja on tappamisen rajaa ylempänä',
        !!weak.lastPound && !weak.lastPound.broke
        && !!lethal.lastPound && lethal.lastPound.kills && !lethal.lastPound.broke
        && !!strongLow.lastPound && strongLow.lastPound.broke > 0
        && !!strong.lastPound && strong.lastPound.broke > 0,
        `matala voima 5: ${weak.lastPound && weak.lastPound.broke} tiiltä`
        + ` (voima ${weak.lastPound && weak.lastPound.strength.toFixed(2)})`
        + `, tappava voima 1: ${lethal.lastPound && lethal.lastPound.broke} tiiltä`
        + ` (voima ${lethal.lastPound && lethal.lastPound.strength.toFixed(2)}`
        + `, tappaa ${lethal.lastPound && lethal.lastPound.kills})`
        + `, korkea voima 1: ${strongLow.lastPound && strongLow.lastPound.broke} tiiltä`
        + ` (voima ${strongLow.lastPound && strongLow.lastPound.strength.toFixed(2)})`
        + `, korkea voima 5: ${strong.lastPound && strong.lastPound.broke} tiiltä`);

      /*
       * JA SE ON KATON EHTO YLÖSALAISIN, eli sama vastaus kuin päänpuskulla.
       *
       * Sama tiilirivi, sama pudotus, kaksi kehoa: pieni ei riko sitä altakaan
       * (`bumpTile` vaatii `player.big`), joten se ei saa rikkoa sitä
       * päältäkään. Mitattuna molemmat suunnat samassa kokeessa, koska väite ei
       * ole "pieni ei riko" vaan "**nämä kaksi ovat sama sääntö**" — ja se
       * hajoaa hiljaa sinä päivänä kun jompaakumpaa säädetään yksin.
       */
      {
        /* Puskukoe tarvitsee oman kenttänsä: iskukokeen tiilirivi on lattiassa
         * ja lattian alla on lattiaa, eli sen alle ei mahdu päätä. Tässä sama
         * tiili on ilmassa rivillä 10 — kolme tyhjää riviä lattian yllä, eli
         * tasan se bumppirivi johon peli muutenkin panee lohkonsa. */
        const bumpAt = 20;
        const bumpDef = () => {
          const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
          const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
          put(14, 0, '#'.repeat(W));
          put(15, 0, '#'.repeat(W));
          put(13, 1, '1');
          put(10, 6, '!');
          put(13, 44, 'F');
          put(10, bumpAt, 'B'.repeat(4));
          return {
            id: 'bBump', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
            boss: false, bossVariant: 0, bands: null, rows,
          };
        };
        const bump = (power) => {
          reset(power);
          const s = new LevelScene(game, 'bBump', bumpDef());
          game.setScene(s);
          const i = mkInput();
          for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
          s.entities = s.entities.filter((e) => e.kind !== 'enemy');
          // Suoraan tiilen alle lattialle, ja hyppy pohjaan.
          const p = s.player;
          p.x = (bumpAt + 1) * 16;
          p.y = 14 * 16 - p.h;
          p.vy = 0;
          p.onGround = true;
          i.pressed.jump = true;
          i.held.jump = true;
          let f = 0;
          while (f < 60 && s.tileAt(bumpAt + 1, 10) === 'B') { s.update(i); i.pressed = blank(); f++; }
          return s.tileAt(bumpAt + 1, 10) !== 'B';
        };
        const smallDive = dive({ type: null, level: 0 }, 150);
        const smallBump = bump({ type: null, level: 0 });
        const bigBump = bump({ type: 'shroom', level: 1 });
        expect('lattian rikkoo se keho joka rikkoo katon: pieni kumpaakaan, kasvanut molemmat',
          !smallBump && !smallDive.lastPound.broke && bigBump && strongLow.lastPound.broke > 0,
          `pieni: puskee ${smallBump}, iskee ${smallDive.lastPound.broke} tiiltä`
          + ` (voima ${smallDive.lastPound.strength.toFixed(2)}, eli korkeus riitti)`
          + ` — kasvanut: puskee ${bigBump}, iskee ${strongLow.lastPound.broke} tiiltä`);
      }

      /* Ja se ei saa syödä salaisuutta. Sama sopimus kuin puskulla ja
       * hännällä — `LevelScene.burstBricks` — mitattuna eikä luvattuna.
       *
       * Oikeasta kentästä eikä koekentästä, ja se on ehto: `brickSecret` on
       * paikan hajautus, joten koekentän tiilirivistä tulee salainen vain
       * sattumalta — ensimmäinen versio tästä kaatui juuri siihen, kuudessa
       * tiilessä ei ollut yhtään. Peli piilottaa satoja, joten kysytään
       * peliltä. */
      {
        reset({ type: 'shroom', level: 5 });
        let hidden = [];
        let where = null;
        for (const id of levelIds()) {
          const s = new LevelScene(game, id);
          const found = [];
          for (let x = 0; x < s.w && found.length < 8; x++) {
            for (let y = 0; y < s.h; y++) {
              if (s.rawTileAt(x, y) === 'B' && s.brickSecret(x, y)) found.push([x, y]);
            }
          }
          if (found.length) { hidden = found; where = { id, s }; break; }
        }
        const kept = where
          && where.s.burstBricks(hidden) === 0
          && hidden.every(([x, y]) => where.s.tileAt(x, y) === 'B');
        expect('mikään isku ei riko tiiltä joka piilottaa jotain', !!kept,
          where ? `${where.id}: ${hidden.length} piilottavaa tiiltä jäi paikalleen`
            : 'yhdessäkään kentässä ei ollut salaista tiiltä');
      }
    }

    /* 13. HÄNNÄNPYÖRÄHDYS RIKKOO TIILEN KYLJESTÄ, ja vain kyljestä johon
     *     häntä osoittaa. Suunta on koko väite: seinä selän takana ei saa
     *     hajota, koska muuten liike ei ole isku vaan säde.
     */
    {
      const W = 48;
      const wallRows = () => {
        const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
        const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
        put(14, 0, '#'.repeat(W));
        put(15, 0, '#'.repeat(W));
        put(13, 1, '1');
        put(10, 6, '!');
        put(13, 44, 'F');
        /* Rivit 12 ja 13, koska juuri ne kaksi häntä yltää: pelaajan jalat
         * ovat rivin 14 päällä ja `tailBox` on koko vartalon korkuinen, eli
         * voimatasolla 2 (h 30 px) se kattaa y 194…223 = rivit 12 ja 13.
         * Rivi 11 olisi väite hännästä joka yltää pään yli. */
        for (const y of [12, 13]) { put(y, 20, 'B'); put(y, 16, 'B'); }
        return rows;
      };
      const tailDef = () => ({
        id: 'tFix', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows: wallRows(),
      });

      const swipe = (facing) => {
        reset({ type: 'leaf', level: 2 });
        const s = new LevelScene(game, 'tFix', tailDef());
        game.setScene(s);
        const i = mkInput();
        for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
        s.entities = s.entities.filter((e) => e.kind !== 'enemy');
        /* Kylki kiinni siinä seinässä johon häntä osoittaa, ja toinen seinä
         * neljän sarakkeen päässä — kauempana kuin hännän ulottuvuus (14 px)
         * kummallakaan puolella. */
        s.player.x = facing > 0 ? 20 * 16 - s.player.w : 17 * 16;
        s.player.y = 14 * 16 - s.player.h;
        s.player.vy = 0;
        s.player.facing = facing;
        // Juoksunappi pyöräyttää hännän; suunta pidetään käsin, koska
        // kävelemään lähtevä pelaaja kääntyisi ja koe mittaisi kävelyä.
        i.pressed.run = true;
        for (let f = 0; f < 24; f++) {
          s.player.facing = facing;
          s.update(i);
          i.pressed = blank();
        }
        return s;
      };

      const right = swipe(1);
      const left = swipe(-1);
      const gone = (s, x) => [12, 13].filter((y) => s.tileAt(x, y) !== 'B').length;
      /* Salaiset tiilet eivät hajoa, joten mittari on "vähintään yksi hajosi
       * sillä puolella jonne häntä osoitti, eikä yhtään toisella" — ja
       * salaisten määrä luetaan kentästä, jotta koe ei vaadi kuutta hajonnutta
       * tiiltä silloin kun yksi niistä on pyhä. */
      const holy = (s, x) => [12, 13].filter((y) => s.brickSecret(x, y)).length;
      expect('hännänpyörähdys rikkoo tiilen siltä puolelta jonne häntä osoittaa',
        gone(right, 20) === 2 - holy(right, 20) && gone(right, 16) === 0
        && gone(left, 16) === 2 - holy(left, 16) && gone(left, 20) === 0,
        `oikealle: ${gone(right, 20)}/${2 - holy(right, 20)} oikealta, ${gone(right, 16)} vasemmalta`
        + `; vasemmalle: ${gone(left, 16)}/${2 - holy(left, 16)} vasemmalta, ${gone(left, 20)} oikealta`);
    }
  } catch (e) {
    expect('maahanisku-testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* -------------------------- ponnahduslauta ----------------------------- */
  /*
   * PONNAHDUSLAUTA MYY KORKEUTTA VAUHDISTA, ja se on väite mittarista.
   *
   * IDEAS-synteesi H: rinteitä ei ole eikä niitä kannata rakentaa, mutta täysi
   * vauhtimittari voi ostaa korkeutta. Väitteessä on kolme osaa ja jokainen
   * niistä voi mennä rikki yksin:
   *
   *   1. **Tyhjällä mittarilla lauta antaa jotain.** Laatta joka ei tee mitään
   *      ilman mittaria olisi pelaajalle rikki eikä ehdollinen.
   *   2. **Täysi mittari antaa enemmän.** Ilman tätä koko laatta on
   *      tallauspomppu jolla on hieno piirros.
   *   3. **Ja enemmän kuin mikään muu.** Mitattu paras nousu tässä pelissä on
   *      juoksu + pieruhyppy, 174 px. Jos lauta jää sen alle, se ei osta mitään
   *      jota ei jo saa — ja koko synteesin peruste oli että mittarille pitää
   *      saada kolmas käyttötapa.
   *
   * Mitataan kentästä eikä vakioista: koe täyttää mittarin juoksemalla, ei
   * asettamalla.
   */
  try {
    const { P_METER_MAX } = await import('/src/entities/player.js');
    const { T } = await import('/src/gfx/tiles.js');

    /** Koekenttä: pitkä lattia ja yksi lauta, ei muuta. */
    const springDef = () => {
      const W = 60;
      const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
      const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
      put(14, 0, '#'.repeat(W));
      put(15, 0, '#'.repeat(W));
      put(13, 1, '1');
      put(10, 4, '!');
      put(14, 40, T.SPRING);   // lattiariviin, ks. `grass_jet`
      put(13, 58, 'F');
      return {
        id: 'jFix', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows,
      };
    };

    /** Juoksee laudalle ja kertoo kuinka korkealle se heitti. */
    const launch = (runUp) => {
      reset({ type: null, level: 0 });
      const s = new LevelScene(game, 'jFix', springDef());
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 6; f++) { s.update(i); i.pressed = blank(); }
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      const p = s.player;
      // Lähtöpaikka valitaan vauhdinoton mukaan: pitkä matka täyttää mittarin,
      // lyhyt ei ehdi. Mittaria ei aseteta käsin — se on se asia jota mitataan.
      p.x = (40 - runUp) * 16;
      p.y = 14 * 16 - p.h;
      p.vx = 0;
      p.vy = 0;
      p.onGround = true;
      s.centerCamera();
      /* Mittari luetaan **maasta**, eli siitä hetkestä jolla lauta lukee sen.
       * Ensimmäinen versio otti suurimman arvon koko ajolta, ja se raportoi
       * molemmille tapauksille 100 % — koska kun lauta ei laukea, pelaaja
       * juoksee sen ohi ja täyttää mittarin myöhemmin. Mittaus kertoi siis
       * mittarista eikä laudasta. */
      let meter = 0;
      let peak = 0;
      const floor = p.y;
      for (let f = 0; f < 400; f++) {
        i.held = blank();
        i.held.right = true;
        i.held.run = true;
        i.held.jump = true;
        i.pressed = blank();
        if (p.onGround) meter = p.pMeter;
        s.update(i);
        peak = Math.max(peak, floor - p.y);
        if (peak > 4 && p.onGround) break;
      }
      return { peak: Math.round(peak), fill: Math.round((meter / P_METER_MAX) * 100) };
    };

    const empty = launch(3);
    const full = launch(38);
    expect('ponnahduslauta myy korkeutta vauhdista, ja täysi mittari ostaa eniten',
      empty.peak > 60 && full.peak > empty.peak + 60 && full.peak > 174,
      `tyhjä mittari (${empty.fill} %) nosti ${empty.peak} px, `
      + `täysi (${full.fill} %) nosti ${full.peak} px `
      + '— vertailuna mitattu paras hyppy 174 px (juoksu + pieruhyppy)');
  } catch (e) {
    expect('ponnahduslaudan testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ----------------------------- kaasulyhty ------------------------------ */
  /*
   * TARKISTUSPISTE ON TAPAHTUMA, EI ESINE, ja siksi tässä mitataan neljä eri
   * asiaa eikä yhtä. Jokainen niistä voi mennä rikki yksin, ja kolme neljästä
   * menee rikki hiljaa — peli näyttää oikealta ja pelaaja huomaa vasta
   * kuollessaan:
   *
   *   1. **Pitkä kenttä saa lyhdyn ja lyhyt ei.** Raja on `LAMP_MIN_COLS`, ja
   *      sen perustelu on ajassa (ks. `plantLamp`). Ilman alarajaa jokainen
   *      kenttä olisi puolitettu.
   *   2. **Ohi kävely sytyttää sen** ja kirjoittaa sarakkeen `game.state`iin.
   *      Tämä on ainoa osa jonka pelaaja näkee heti.
   *   3. **Uusi yritys alkaa lyhdyltä**, ja lyhty palaa jo valmiiksi. Sammunut
   *      lyhty herätyspaikan kohdalla olisi kutsu sytyttää se uudelleen.
   *   4. **Vaikeustason vaihto unohtaa pisteen** eikä herätä pelaajaa väärään
   *      sarakkeeseen. `scale.js` venyttää kenttää, joten sarake 190 on eri
   *      paikka eri levyisessä kentässä — ja tämä on se kohta jossa
   *      tarkistuspiste voisi tappaa pelaajan seinän sisällä.
   */
  try {
    const { T } = await import('/src/gfx/tiles.js');
    const { Sfx } = await import('/src/core/audio.js');

    /** Koekenttä, jonka leveys annetaan: tasainen lattia ja maali lopussa. */
    const lampDef = (W) => {
      const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
      const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
      put(14, 0, '#'.repeat(W));
      put(15, 0, '#'.repeat(W));
      put(13, 1, '1');
      put(13, W - 2, 'F');
      return {
        id: 'lFix', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows,
      };
    };
    const build = (W) => {
      const s = new LevelScene(game, 'lFix', lampDef(W));
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      return s;
    };
    const lampsIn = (s) => {
      const at = [];
      for (let ty = 0; ty < s.h; ty++) {
        for (let tx = 0; tx < s.w; tx++) {
          const ch = s.grid[ty][tx];
          if (ch === T.LAMP || ch === T.LAMP_LIT) at.push({ tx, ty, lit: ch === T.LAMP_LIT });
        }
      }
      return at;
    };

    reset();
    const long = build(400);
    const longLamps = lampsIn(long);
    reset();
    const short = build(300);
    const shortLamps = lampsIn(short);
    const off = longLamps.length === 1 ? Math.abs(longLamps[0].tx - 200) : -1;
    expect('pitkä kenttä saa yhden lyhdyn puolivälistä, lyhyt ei yhtään',
      longLamps.length === 1 && shortLamps.length === 0 && off <= 4,
      `400 saraketta: ${longLamps.length} lyhtyä (sarake ${longLamps.length ? longLamps[0].tx : '-'}, `
      + `${off} päässä puolivälistä), 300 saraketta: ${shortLamps.length} — raja on 340`);

    // 2. Kävele lyhdyn ohi ja katso mitä tapahtui.
    reset();
    const walk = build(400);
    const lamp = lampsIn(walk)[0];
    const p = walk.player;
    p.x = (lamp.tx - 3) * 16;
    p.y = (lamp.ty - 1) * 16;
    walk.centerCamera();
    const i2 = mkInput();
    let sfx = 0;
    const realPlay = Sfx.play;
    Sfx.play = (n) => { if (n === 'lamp') sfx++; return realPlay.call(Sfx, n); };
    for (let f = 0; f < 90; f++) {
      i2.held = blank();
      i2.held.right = true;
      i2.pressed = blank();
      walk.update(i2);
    }
    Sfx.play = realPlay;
    const litNow = walk.grid[lamp.ty][lamp.tx] === T.LAMP_LIT;
    const saved = game.state.checks ? game.state.checks.lFix : undefined;
    expect('lyhdyn ohi käveleminen sytyttää sen ja merkitsee sarakkeen muistiin',
      litNow && saved === lamp.tx && sfx === 1,
      `laatta ${litNow ? 'palaa' : 'on sammunut'}, muistiin jäi ${saved} `
      + `(lyhty on sarakkeessa ${lamp.tx}), sytytysääni soi ${sfx} kertaa`);

    // 3. Sama kenttä uudelleen, samalla tallennuksella: mistä se alkaa?
    const again = build(400);
    const startCol = Math.floor(again.player.cx / 16);
    const againLamp = lampsIn(again)[0];
    expect('kuoleman jälkeen kenttä alkaa lyhdyltä, ja lyhty palaa jo',
      Math.abs(startCol - lamp.tx) <= 1 && againLamp && againLamp.lit
        && again.player.y < 14 * 16,
      `pelaaja aloitti sarakkeesta ${startCol} (lyhty ${lamp.tx}), `
      + `lyhty ${againLamp && againLamp.lit ? 'palaa' : 'on sammunut'}, `
      + `rivillä ${Math.round(again.player.y / 16)}`);

    // 4. Sama muisti, eri levyinen kenttä: piste unohdetaan.
    const stretched = build(420);
    const stretchedCol = Math.floor(stretched.player.cx / 16);
    expect('venytetty kenttä unohtaa tarkistuspisteen eikä herätä väärään sarakkeeseen',
      stretchedCol <= 4,
      `muistissa sarake ${saved}, 420 sarakkeen kentässä lyhty on `
      + `${lampsIn(stretched)[0].tx}, ja pelaaja aloitti sarakkeesta ${stretchedCol}`);
  } catch (e) {
    expect('kaasulyhdyn testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ---------------------------- ilmahypyt -------------------------------- */
  /*
   * PIERUPOMPUISTA TULI PANOKSIA, JA SE ON KAKSI VÄITETTÄ EIKÄ YKSI.
   *
   * Omistajan päätös 16.8.2026. Vika oli mitattu: kenttägeometria on
   * hinnoiteltu yhtä hyppyä vasten (kuilubudjetti 6 ruutua = 96 px, mitattu
   * juoksuhypyn kantama 155 px), ja viisi peräkkäistä ponnistusta teki pelin
   * levimmästä kuilusta lyhyemmän kuin yksi ponnistus.
   *
   * Korjaus ei saa mennä liian pitkälle kumpaankaan suuntaan, joten molemmat
   * reunat mitataan:
   *
   *   1. **Panoksia ei voi ladata yhdeksi kaareksi.** Sama napinhakkaus samalta
   *      lattialta, yksi panos vastaan viisi: korkeuseron on oltava pieni.
   *      Vertailu eikä vakio — koe ei tiedä mitään lukua jonka se tarkistaa,
   *      joten se ei voi hyväksyä sitä mitä koodissa sattuu lukemaan.
   *   2. **Panokset ovat yhä olemassa.** Pitkässä pudotuksessa niitä on
   *      käytettävissä useampi kuin yksi, koska juuri se on se mitä
   *      voimatasosta ostetaan: pelastuksia, ei lentoa.
   */
  try {
    const { PLAYER_SIZES: SZ } = await import('/src/gfx/sprites.js');

    /** Napinhakkaus paikaltaan: montako pikseliä ylös päästään yhdellä kaarella. */
    const mash = (level) => {
      reset({ type: 'shroom', level });
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      const p = s.player;
      /* Vauhtiin ensin: kantama mitataan juoksusta, koska juuri sitä vasten
       * kuilubudjetti on hinnoiteltu. */
      i.held = blank();
      i.held.right = true;
      i.held.run = true;
      for (let f = 0; f < 90; f++) { s.update(i); i.pressed = blank(); }
      const y0 = p.y;
      const x0 = p.x;
      let peak = 0;
      let spent = 0;
      let air = 0;
      for (let f = 0; f < 400; f++) {
        i.held = blank();
        i.held.right = true;
        i.held.run = true;
        i.held.jump = true;
        i.pressed = blank();
        i.pressed.jump = true;
        s.update(i);
        peak = Math.max(peak, y0 - p.y);
        spent = Math.max(spent, p.airJumps);
        air = f;
        if (f > 4 && p.onGround) break;
      }
      return {
        peak: Math.round(peak), reach: Math.round(p.x - x0), frames: air,
        spent, max: p.airJumpsMax,
      };
    };

    const one = mash(1);
    const five = mash(5);
    /* Kaksi lukua eikä yksi, ja **kantama on se tärkeämpi**: kuilubudjetti on
     * hinnoiteltu vaakasuoraan (`softGapTiles` 9 = 144 px, johdettu mitatusta
     * juoksu + pieruhyppy 285 px:stä), joten korkeuden kesyttäminen ei auta
     * mitään jos panokset venyttävät kaarta sivusuunnassa.
     *
     * Rajat ovat kaksi ja neljä ruutua, ja ne on asetettu mitattuun eikä
     * toivottuun: korjauksen jälkeen erot ovat 10 px ja 45 px. Ennen sitä ne
     * olivat 41 px ja **197 px**, eli kaksitoista ruutua kantamaa siinä missä
     * koko kuilubudjetti on kuusi — se on se luku jonka tämä rivi estää
     * palaamasta. */
    expect('viisi pierupanosta ei nosta eikä kanna kauemmas kuin yksi',
      five.max === 5 && one.max === 1
      && five.peak - one.peak < 32 && five.reach - one.reach < 64,
      `yksi panos: ${one.peak} px ylös, ${one.reach} px sivuun, ${one.frames} framea`
      + ` — viisi panosta: ${five.peak} px ylös, ${five.reach} px sivuun,`
      + ` ${five.frames} framea (käytti ${five.spent})`
      + ` — erot ${five.peak - one.peak} px ja ${five.reach - one.reach} px`);

    /* Ja toinen reuna: pitkä pudotus, jossa panoksia ehtii käyttää useampi.
     * Kenttä on 1-2, koska se on pelin korkein (katto 432 px). */
    {
      reset({ type: 'shroom', level: 5 });
      const s = new LevelScene(game, '1-2');
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      const p = s.player;
      p.y = 8;
      p.vy = 0;
      p.onGround = false;
      let spent = 0;
      for (let f = 0; f < 400 && !p.dying; f++) {
        i.held = blank();
        i.held.jump = true;
        i.pressed = blank();
        i.pressed.jump = true;
        s.update(i);
        spent = Math.max(spent, p.airJumps);
        if (f > 4 && p.onGround) break;
      }
      expect('pitkässä pudotuksessa panoksia ehtii käyttää useampi',
        spent >= 3,
        `käytti ${spent} panosta viidestä pudotessaan`);
    }
  } catch (e) {
    expect('ilmahyppytestit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* --------------------------- neljä uutta lajia ------------------------ */
  /*
   * NELJÄ UUTTA VIHOLLISTA, JA SE MITÄ NIISTÄ VOI MENNÄ RIKKI.
   *
   * "Laji on olemassa" ei todista mitään — spriteportit yllä todistavat jo
   * että ne on piirretty, ja `ENEMY_CHARS` että ne syntyvät. Tässä mitataan se
   * lupaus jonka kukin laji antaa pelaajalle, koska juuri se on se osa joka
   * voi kadota yhdellä vakion muutoksella ilman että mikään muu näkyy:
   *
   *   TÖRÄHDYSTORVI  ampuu vaakasuoraan ja ammuksen **päälle voi hypätä**
   *   PAARMA         ampuu suoraan alas sen päälle joka pysähtyy sen alle
   *   YÖKKI          lähettää pallon joka kulkee lattiaa pitkin ja kiihtyy
   *   PAUKKUPÖHÖ     ei kuole tallauksesta vaan syttyy siitä
   *
   * Koekenttä on tässä eikä oikea kenttä, samasta syystä kuin maahaniskun
   * tiilikokeessa: nämä ovat väitteitä lajista, ja oikeasta kentästä mitattuna
   * ne olisivat väitteitä siitä kentästä.
   */
  try {
    const E = await import('/src/entities/enemies.js');
    const W = 40;
    const testDef = (put) => {
      const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
      const set = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
      set(14, 0, '#'.repeat(W));
      set(15, 0, '#'.repeat(W));
      set(13, 1, '1');
      set(10, 4, '!');
      set(13, 38, 'F');
      if (put) put(set);
      return {
        id: 'zoo', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows,
      };
    };
    /** Kenttä pystyyn, vanhat viholliset pois, pelaaja haluttuun sarakkeeseen. */
    const zoo = (opts = {}) => {
      const { power = { type: 'shroom', level: 1 }, put = null, at = 20 } = opts;
      reset(power);
      const s = new LevelScene(game, 'zoo', testDef(put));
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 6; f++) { s.update(i); i.pressed = blank(); }
      /* Vihollisia EI siivota pois, toisin kuin muissa koekentissä: tässä
       * kentässä ei ole muita kuin se yksi joka on tarkoituskin mitata, ja
       * siivous poistaisi juuri sen. */
      const p = s.player;
      p.x = at * 16;
      p.y = 14 * 16 - p.h;
      p.vx = 0;
      p.vy = 0;
      p.onGround = true;
      s.centerCamera();
      return { s, i, p };
    };
    const run = (s, i, n) => {
      for (let f = 0; f < n; f++) { s.update(i); i.pressed = blank(); }
    };
    const of = (s, name) => s.entities.filter((e) => e.constructor.name === name && !e.remove);
    /**
     * Aja `n` framea ja **nappaa ensimmäinen** halutun lajin olio sillä
     * framella jolla se on olemassa.
     *
     * Lopputilan lukeminen ei kelpaa näille lajeille, ja se on mittausvirhe
     * joka tehtiin kerran: happopisara elää noin kolmekymmentä framea ennen
     * kuin se roiskahtaa, joten sadan framen jälkeen niitä on nolla riippumatta
     * siitä montako niistä putosi. Tapahtuma on nähtävä silloin kun se
     * tapahtuu.
     */
    const watch = (s, i, n, name, stopOnFirst = false) => {
      let seen = 0;
      let first = null;
      const known = new Set();
      for (let f = 0; f < n; f++) {
        s.update(i);
        i.pressed = blank();
        for (const e of s.entities) {
          if (e.constructor.name !== name || known.has(e.id)) continue;
          known.add(e.id);
          seen++;
          if (!first) first = e;
        }
        // `stopOnFirst` on kiihtyvyyden mittausta varten: pysähdytään sillä
        // framella jolla olio syntyi, tai sen alkuvauhti on jo loppuvauhti.
        if (stopOnFirst && first) break;
      }
      return { seen, first };
    };

    /* 1. TORVI AMPUU SINNE MISSÄ PELAAJA ON, JA AMMUS ON ASKELMA.
     *
     * Kolme väitettä yhdessä kokeessa, koska ne ovat sama lupaus kolmesta
     * suunnasta: ammus syntyy, se kulkee **vaakasuoraan** (ei putoa), ja sen
     * päälle laskeutuminen on tallaus eikä osuma. Se kolmas on koko lajin
     * tasapaino — vaakalento jonka päälle ei voi hypätä olisi seinä. */
    {
      /* Kahdeksan ruutua väliä: yli `TORVI_NEAR`in (40 px) ja reilusti alle
       * `TORVI_RANGE`n (200 px). Ensimmäinen versio tästä kokeesta pani
       * pelaajan kuudentoista ruudun päähän, eli rajan ulkopuolelle, ja mittasi
       * torvea joka toimi täsmälleen oikein olemalla ampumatta. */
      const { s, i, p } = zoo({ at: 18, put: (set) => set(12, 10, 'T') });
      const torvi = of(s, 'Torvi')[0];
      torvi.alwaysActive = true;
      torvi.active = true;
      const shot = watch(s, i, 200, 'Torahdys');
      const slug = shot.first;
      const y0 = slug ? slug.y : 0;
      const x0 = slug ? slug.x : 0;
      run(s, i, 20);
      const drop = slug ? Math.abs(slug.y - y0) : 999;
      const moved = slug ? slug.x - x0 : 0;

      /* Ja sitten sen päälle, ylhäältä ja putoavana.
       *
       * Jäädytys ja kuolemattomuusframet nollataan ensin, ja se on kokeen
       * hygieniaa eikä kikkailua: ammus on saattanut ehtiä osua kylkeen näiden
       * kahdenkymmenen framen aikana, ja jäädytetty pelaaja ei tallaa mitään —
       * silloin koe mittaisi osumaa jonka se itse aiheutti. */
      p.frozen = 0;
      p.invuln = 0;
      const level0 = p.powerLevel;
      p.x = slug ? slug.cx - p.w / 2 : 0;
      p.y = slug ? slug.y - p.h - 4 : 0;
      p.vy = 3;
      p.onGround = false;
      run(s, i, 8);
      expect('törähdystorvi ampuu vaakasuoraan, ja ammuksen päälle voi hypätä',
        !!slug && drop === 0 && moved !== 0 && (slug.remove || slug.dying)
        && p.powerLevel === level0 && !p.dying,
        slug ? `ammuksia ${shot.seen}, putosi ${drop} px, kulki ${Math.round(moved)} px`
          + `, tallaus poisti ${slug.remove || slug.dying}, voimataso ${level0}->${p.powerLevel}`
          : 'torvi ei ampunut 200 framessa');
    }

    /* 2. PAARMA AMPUU SEN PÄÄLLE JOKA PYSÄHTYY SEN ALLE, EI MUUTEN.
     *
     * Kaksi ajoa samasta kentästä: pelaaja sen alla ja pelaaja kaukana. Pelkkä
     * "pisara syntyi" menisi läpi myös silloin kun laji ampuu koko ajan, ja se
     * on eri laji — se olisi kello eikä tähtäin. */
    {
      const under = zoo({ at: 20, put: (set) => set(5, 20, 'Z') });
      const bug = of(under.s, 'Paarma')[0];
      bug.alwaysActive = true;
      bug.active = true;
      const dropped = watch(under.s, under.i, 120, 'Happopisara').seen;

      const away = zoo({ at: 4, put: (set) => set(5, 20, 'Z') });
      const far = of(away.s, 'Paarma')[0];
      far.alwaysActive = true;
      far.active = true;
      const idle = watch(away.s, away.i, 120, 'Happopisara').seen;

      // Ja pisara satuttaa: se on vaara eikä koriste.
      const hurt = zoo({ at: 20, put: (set) => set(5, 20, 'Z') });
      const hp0 = hurt.p.powerLevel;
      const hbug = of(hurt.s, 'Paarma')[0];
      hbug.alwaysActive = true;
      hbug.active = true;
      run(hurt.s, hurt.i, 240);
      expect('paarma pudottaa pisaran vain sen päälle joka on sen alla',
        dropped > 0 && idle === 0 && hurt.p.powerLevel < hp0,
        `alla ${dropped} pisaraa, kaukana ${idle}, voimataso ${hp0}->${hurt.p.powerLevel}`);
    }

    /* 3. YÖKIN PALLO KULKEE LATTIAA PITKIN, KIIHTYY, EIKÄ SITÄ TALLOTA.
     *
     * Vauhti mitataan kahdesta kohdasta eikä yhdestä: pallo joka lähtee
     * nopeana ja pysyy nopeana on ammus, ja tämän lajin koko luettavuus on
     * siinä että kaukainen pallo on hidas ja lähellä oleva nopea. */
    {
      /* Kahdeksan ruutua väliä, eli `YOKKI_RANGE`n (180 px) sisällä. Sama
       * mittausvirhe kuin torvella oli kerran jo tehty, ja se on tässä
       * korjattuna eikä kommentoituna. */
      const { s, i, p } = zoo({ at: 18, put: (set) => set(12, 14, 'Y') });
      const yokki = of(s, 'Yokki')[0];
      yokki.alwaysActive = true;
      yokki.active = true;
      /* Neljä ruutua väliä ja 400 framea, ja molemmat luvut ovat mitattuja.
       * `YOKKI_PERIOD` (210) + `YOKKI_WARN` (45) on 255 framea *tähdättynä*, ja
       * ajastin juoksee vain kun pelaaja on `YOKKI_RANGE`n sisällä — mutta
       * yökki itse kävelee 0,3 px/frame, ja kolmessasadassa framessa se
       * kävelee yhdeksänkymmentä pikseliä. Kahdeksan ruudun päästä aloitettuna
       * se ehti rajan ulkopuolelle ennen kuin ajastin oli valmis, ja koe
       * mittasi kävelynopeutta luullen mittaavansa yökkäystä. */
      const ball = watch(s, i, 400, 'Karvapallo', true).first;
      const early = ball ? Math.abs(ball.vx) : 0;
      const bx = ball ? ball.x : 0;
      run(s, i, 60);
      const late = ball ? Math.abs(ball.vx) : 0;
      const toward = ball ? ball.x - bx : 0;
      const onFloor = ball ? Math.floor((ball.y + ball.h) / 16) : -1;

      /* Sama hygienia kuin torvella: pallo on saattanut jo osua, ja jäädytetty
       * pelaaja ei tallaa. */
      p.frozen = 0;
      p.invuln = 0;
      const level0 = p.powerLevel;
      if (ball) {
        p.x = ball.cx - p.w / 2;
        p.y = ball.y - p.h - 4;
        p.vy = 3;
        p.onGround = false;
        run(s, i, 8);
      }
      const cost = p.powerLevel < level0 || p.dying;
      expect('yökin karvapallo vierii lattiaa pitkin, kiihtyy, eikä sitä voi tallata',
        !!ball && onFloor === 14 && toward > 0 && late > early
        && ball.spiky && cost && !ball.remove,
        ball ? `vauhti ${early.toFixed(2)} -> ${late.toFixed(2)}, kulki ${Math.round(toward)} px`
          + ` rivillä ${onFloor}, piikikäs ${ball.spiky}`
          + `, tallaus maksoi ${level0}->${p.powerLevel}${p.dying ? ' (kuoli)' : ''}`
          + `, pallo jäi ${!ball.remove}`
          : 'yökki ei yökännyt 400 framessa');
    }

    /* 4. PAUKKUPÖHÖ EI KUOLE TALLAUKSESTA VAAN SYTTYY SIITÄ.
     *
     * Neljä väitettä, ja ne ovat sen koko sopimus: tallaus ei poista sitä,
     * pelaaja pomppaa (eli hänellä on se hetki jona lähteä), räjähdys rikkoo
     * tiilen `burstBricks`in säännöillä, ja se satuttaa myös sitä joka jäi
     * katsomaan. */
    {
      const { s, i, p } = zoo({
        at: 18,
        put: (set) => {
          set(12, 22, 'm');
          set(12, 24, 'BBB');
        },
      });
      const bomb = of(s, 'Paukkupoho')[0];
      bomb.alwaysActive = true;
      bomb.active = true;
      bomb.x = 22 * 16;
      const level0 = p.powerLevel;
      // Päälle ylhäältä.
      p.x = bomb.cx - p.w / 2;
      p.y = bomb.y - p.h - 4;
      p.vy = 3;
      p.onGround = false;
      run(s, i, 6);
      const survived = !bomb.remove && !bomb.dying && bomb.fuse > 0;
      const bounced = p.vy < 0;
      const bricks0 = [24, 25, 26].filter((x) => s.tileAt(x, 12) === 'B').length;
      // Ja jäädään paikalle katsomaan.
      p.x = bomb.cx - p.w / 2;
      run(s, i, 90);
      const bricks1 = [24, 25, 26].filter((x) => s.tileAt(x, 12) === 'B').length;
      expect('paukkupöhö syttyy tallauksesta, ja räjähdys rikkoo tiilen ja satuttaa',
        survived && bounced && bomb.remove && bricks1 < bricks0 && p.powerLevel < level0,
        `tallaus jätti sen henkiin ${survived} ja pomppasi ${bounced}`
        + `, tiiliä ${bricks0} -> ${bricks1}, voimataso ${level0} -> ${p.powerLevel}`);
    }
  } catch (e) {
    expect('uusien lajien testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ------------------------------ hyppysarjat --------------------------- */
  /*
   * HYPPYSARJAT: TODISTUS AJETAAN UUDESTAAN, EI USKOTA TIEDOSTOA.
   *
   * `src/data/chunks/jumps.js` on generoitu tiedosto ja sen kommenteissa lukee
   * jokaisen loikan ikkuna. Kommentti on kuitenkin muistiinpano, ja
   * muistiinpano vanhenee: **fysiikan muutos ei kaataisi sitä vaan tekisi siitä
   * hiljaa väärän.** Siksi tämä lohko ajaa saman ratkaisijan samoille
   * palikoille joka ajolla — sama moduuli jolla ne tehtiin, ei kopio siitä.
   *
   * Kaksi väitettä, ja ne ovat toistensa vastakohdat:
   *
   *   **Ei mahdoton.** Jokainen loikka ratkeaa ja koko sarja kulkee yhtenä
   *   juoksuna, voimatasolla 0 ja pelkällä juoksulla ja hypyllä. Tämä on sama
   *   lupaus jonka `level-bot.js` antaa kentistä (DESIGN.md kohta 5) — ja se on
   *   näille palikoille tiukempi, koska tyhmä botti ei osaisi näitä lainkaan.
   *
   *   **Vaikea.** Kapein ikkuna koko sarjastossa on `TIGHTEST`in ja
   *   `LOOSEST`in välissä. Alaraja on se jonka alle mennessä sarja on
   *   hyväksytty vain siksi että ratkaisija on tarkempi kuin ihminen; yläraja
   *   on se jonka yli mentäessä koko tiedosto on käytävä eikä hyppysarja.
   *
   * Molemmat mitataan uudelleen, ja molempien luvut tulostetaan.
   */
  try {
    const { JUMP_CHUNKS } = await import('/src/data/chunks/jumps.js');
    const { solveSequence } = await import('/tools/jump-solver.js');
    /** Kaksi framea juoksukatolla (2,5 px/frame) pyöristettynä ylös. */
    const TIGHTEST = 5;
    /** Reilu puolitoista ruutua: sitä väljempi loikka ei enää kysy ajoitusta. */
    const LOOSEST = 26;

    const rows = [];
    const broken = [];
    const narrow = [];
    for (const [name, chunk] of Object.entries(JUMP_CHUNKS)) {
      const mkScene = () => {
        reset({ type: null, level: 0 });
        const s = new LevelScene(game, name, {
          id: name, theme: 'grass', bg: 'hills', music: 'level', time: 9999,
          boss: false, bossVariant: 0, bands: null, rows: chunk.rows,
        });
        s.entities = s.entities.filter((e) => e.kind === 'player');
        s.goal = null;
        return s;
      };
      const got = solveSequence(mkScene);
      const wins = got.hops.map((h) => h.window);
      const lo = wins.length ? Math.min(...wins) : 0;
      rows.push(`${name} ${wins.join('/')} px${got.walked ? '' : ' — EI KULKENUT'}`);
      narrow.push(lo);
      if (!got.ok || !got.walked) broken.push(`${name}: ratkesi ${got.ok}, kulki ${got.walked}`);
      else if (lo < TIGHTEST) broken.push(`${name}: kapein ikkuna ${lo} px, alaraja ${TIGHTEST}`);
    }
    const tight = narrow.length ? Math.min(...narrow) : 0;
    expect('jokainen hyppysarja on hypättävissä voimatasolla 0, ja tiukin niistä on tiukka',
      broken.length === 0 && tight >= TIGHTEST && tight <= LOOSEST,
      broken.length ? broken.join('; ')
        : `${rows.join(' · ')} — tiukin ${tight} px `
          + `(sallittu ${TIGHTEST}–${LOOSEST}, eli ${(tight / 2.5).toFixed(1)} framea juoksuvauhdilla)`);
  } catch (e) {
    expect('hyppysarjojen testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ------------------------------ juoksuhiekka -------------------------- */
  /*
   * JUOKSUHIEKKA, ja se mitä siitä voi mennä rikki.
   *
   * Omistajan päätös 9.8.2026: "hiekka vetää hitaasti alas, mutta reagoimiseen
   * jää useita sekunteja". Se on **mitattava väite** eikä tunnelma, joten koko
   * lohko on rakennettu numeroiden ympärille: montako framea ensimmäisestä
   * kosketuksesta kuolemaan pienimmällä keholla, montako framea ulospääsy
   * maksaa voimatasolla 0, ja paljonko maahanisku syö varoajasta.
   *
   * "Juoksuhiekka on olemassa" ei todista mitään. Nämä ovat ne väitteet jotka
   * voi rikkoa yhdellä vakion muutoksella eikä huomata pelatessa:
   *
   *   - varoaika lyhenee tai katoaa (uhkasta tulee ansa)
   *   - matalasta kuopasta tulee tappava (ensimmäinen kohtaaminen ei enää opeta)
   *   - jostain kuopasta ei pääse ulos pienimmällä koolla (DESIGN.md kohta 5)
   *   - tähti alkaa kantaa hiekan yli (lupaus muuttuu vahingossa)
   *   - maahanisku ei tee hiekassa mitään (kaksi samana päivänä tullutta
   *     mekaniikkaa jotka eivät tiedä toisistaan)
   *
   * Koko lohko on try/catchissa samasta syystä kuin maahaniskun lohko: ensi
   * ajolla vienti puuttuu, ja kaatuva importti veisi mukanaan kaikki tämän
   * jälkeiset tarkistukset.
   */
  try {
    const { T } = await import('/src/gfx/tiles.js');
    const {
      QUICKSAND_GRACE, QUICKSAND_SINK, QUICKSAND_PLUNGE_FRAMES, QUICKSAND_WADE, MAX_WALK,
    } = await import('/src/entities/player.js');
    const { PLAYER_SIZES: SIZES } = await import('/src/gfx/sprites.js');

    /**
     * Kentän juoksuhiekkalammikot, vierekkäiset sarakkeet yhtenä. `top` on
     * pinta ja `bottom` alin hiekkarivi — syvyys on se luku josta koko
     * hukkumisväite riippuu, joten se luetaan kentästä eikä muisteta.
     */
    const poolsOf = (s) => {
      const cols = [];
      for (let tx = 0; tx < s.w; tx++) {
        let top = -1; let bottom = -1;
        for (let ty = 0; ty < s.h; ty++) {
          if (s.rawTileAt(tx, ty) !== T.QUICKSAND) continue;
          if (top < 0) top = ty;
          bottom = ty;
        }
        cols.push(top < 0 ? null : { top, bottom });
      }
      const pools = [];
      let run = null;
      for (let tx = 0; tx <= s.w; tx++) {
        const c = tx < s.w ? cols[tx] : null;
        if (c) {
          if (!run) run = { tx0: tx, tx1: tx, ...c };
          else {
            run.tx1 = tx;
            run.top = Math.min(run.top, c.top);
            run.bottom = Math.max(run.bottom, c.bottom);
          }
        } else if (run) { pools.push(run); run = null; }
      }
      return pools;
    };

    /** Kaikki kentät joissa on hiekkaa, lammikoineen. */
    const sandLevels = [];
    for (const id of levelIds()) {
      reset();
      const s = new LevelScene(game, id);
      const pools = poolsOf(s);
      if (pools.length) sandLevels.push({ id, pools });
    }

    /** Pelaaja lammikon keskelle, jalat täsmälleen pinnalla. */
    const dropInto = (s, pool) => {
      const p = s.player;
      p.x = Math.round(((pool.tx0 + pool.tx1 + 1) / 2) * 16 - p.w / 2);
      p.y = pool.top * 16 - p.h;
      p.vx = 0;
      p.vy = 0;
      p.onGround = false;
      p.sunk = 0;
      s.centerCamera();
    };

    /** Kenttä pystyyn ilman vihollisia ja ilman kelloa. */
    const sandScene = (id, power = { type: null, level: 0 }) => {
      reset(power);
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };

    /**
     * Framet ensimmäisestä hiekkakosketuksesta kuolemaan, tai null jos ei kuole.
     * `press` saa painaa hyppyä; oletuksena pelaaja ei tee mitään, mikä on se
     * tapaus jota omistajan lause koskee.
     */
    const untilDeath = (s, i, cap = 900) => {
      let contact = -1;
      for (let f = 0; f < cap; f++) {
        s.update(i);
        i.pressed = blank();
        if (contact < 0 && s.player.inQuicksand) contact = f;
        if (s.player.dying) return contact < 0 ? f : f - contact;
      }
      return null;
    };

    const deepest = sandLevels
      .flatMap((l) => l.pools.map((p) => ({ id: l.id, pool: p })))
      .sort((a, b) => (b.pool.bottom - b.pool.top) - (a.pool.bottom - a.pool.top))[0];
    const shallowest = sandLevels
      .flatMap((l) => l.pools.map((p) => ({ id: l.id, pool: p })))
      .sort((a, b) => (a.pool.bottom - a.pool.top) - (b.pool.bottom - b.pool.top))[0];

    expect('aavikossa on juoksuhiekkaa, mutta ei joka kentässä',
      sandLevels.length >= 2 && sandLevels.length < levelIds().length,
      `${sandLevels.length}/${levelIds().length} kenttää: `
      + sandLevels.map((l) => `${l.id} ${l.pools.length} kpl`).join(', '));

    /* 1. "Useita sekunteja" numeroina. Pienin keho uppoaa ensimmäisenä, joten
     *    se on pahin tapaus, ja mittaus alkaa ensimmäisestä kosketuksesta. */
    {
      const s = sandScene(deepest.id);
      const i = mkInput();
      dropInto(s, deepest.pool);
      const frames = untilDeath(s, i);
      expect('syvä hiekka tappaa vasta useiden sekuntien kuluttua, ei heti',
        frames !== null && frames >= 150 && frames <= 250,
        frames === null
          ? `${deepest.id} ${(deepest.pool.bottom - deepest.pool.top + 1)} ruutua syvä: ei tappanut`
          : `${deepest.id}, keho ${SIZES[0].h} px, kuoppa `
            + `${(deepest.pool.bottom - deepest.pool.top + 1) * 16} px: ${frames} framea `
            + `(${(frames / 60).toFixed(2)} s), vajoamisnopeus ${QUICKSAND_SINK} px/frame, `
            + `varoaika ${QUICKSAND_GRACE} framea`);
    }

    /* 2. Ensimmäinen kohtaaminen ei saa tappaa. Matala kuoppa on pohjaa myöten
     *    matalampi kuin pienin keho, joten pää ei mene alle — ja se on
     *    geometriaa eikä ajastin, joten se pitää mitata eikä luvata. */
    {
      const s = sandScene(shallowest.id);
      const i = mkInput();
      dropInto(s, shallowest.pool);
      const frames = untilDeath(s, i, 900);
      const p = s.player;
      expect('matala kuoppa opettaa eikä tapa: pää ei mene pinnan alle',
        frames === null && !p.dying,
        `${shallowest.id}, kuoppa ${(shallowest.pool.bottom - shallowest.pool.top + 1) * 16} px, `
        + `keho ${SIZES[0].h} px: 900 framea, uppoama ${p.sunk} framea, `
        + `pää ${Math.round(shallowest.pool.top * 16 - p.y)} px pinnan yläpuolella`);
    }

    /* 3. DESIGN.md kohta 5 kuopittain. Ei abstraktisti vaan jokaisesta
     *    lammikosta erikseen: hiekka jonka reunalle ei pääse on ansa, ja
     *    varoaika tekee sijoittelusta koko työn. */
    {
      const stuck = [];
      let worst = 0;
      for (const { id, pools } of sandLevels) {
        for (const pool of pools) {
          const s = sandScene(id);
          const i = mkInput();
          dropInto(s, pool);
          /* From the FLOOR of the pool and not from the rim. Falling in is the
           * easy case — a kick on the first frame barely enters — and the case
           * that matters is the one the several seconds are spent reaching:
           * standing on the bottom with the whole depth to climb. */
          s.player.y = (pool.bottom + 1) * 16 - s.player.h;
          let out = -1;
          for (let f = 0; f < 600 && out < 0; f++) {
            const p = s.player;
            // Rimpuilu on hyppynapin hakkaamista, ja mitään muuta bottikaan ei
            // osaa: oikealle ja hyppy.
            i.held.right = true;
            i.held.jump = f % 4 < 2;
            i.pressed.jump = f % 4 === 0;
            s.update(i);
            i.pressed = blank();
            if (p.dying) break;
            if (!p.inQuicksand && p.onGround && p.y + p.h <= pool.top * 16 + 1) out = f;
          }
          if (out < 0) stuck.push(`${id} ${pool.tx0}-${pool.tx1}`);
          else worst = Math.max(worst, out);
        }
      }
      expect('jokaisesta hiekkakuopasta pääsee ulos voimatasolla 0',
        stuck.length === 0,
        stuck.length ? `jumissa: ${stuck.join(', ')}`
          : `${sandLevels.reduce((n, l) => n + l.pools.length, 0)} kuoppaa, hitain `
            + `${worst} framea (${(worst / 60).toFixed(2)} s)`);
      /* 3 b. Ja mitä se maksaa kellossa. Kello tikittää 24 framen välein, joten
       *      hitain ulospääsy on tämän verran aikayksiköitä — hinta on tarkoitus,
       *      mutta se ei saa olla merkittävä osa kentän kellosta. */
      const worstUnits = Math.ceil(worst / 24);
      const clocks = sandLevels.map((l) => {
        reset();
        return new LevelScene(game, l.id).time;
      });
      const tightest = Math.min(...clocks);
      expect('rimpuilu maksaa kelloa mutta ei kenttää',
        worstUnits < tightest * 0.05,
        `hitain ulospääsy ${worstUnits} aikayksikköä, tiukin kello ${tightest} `
        + `(${((worstUnits / tightest) * 100).toFixed(1)} %)`);
    }

    /* 4. Kaksi samana päivänä tullutta mekaniikkaa. Maahanisku ajaa alaspäin
     *    kovaa, joten hiekassa sen pitää haudata syvemmälle — ja siitä seuraa
     *    että se syö varoajan. Mitataan molemmat samasta kuopasta. */
    {
      const plain = (() => {
        const s = sandScene(deepest.id);
        const i = mkInput();
        dropInto(s, deepest.pool);
        return untilDeath(s, i);
      })();
      const s = sandScene(deepest.id);
      const i = mkInput();
      dropInto(s, deepest.pool);
      s.player.y = deepest.pool.top * 16 - s.player.h - 40;   // tilaa syöksylle
      i.held.down = true;
      i.pressed.jump = true;
      i.held.jump = true;
      s.update(i);
      i.pressed = blank();
      i.held.jump = false;
      const dived = untilDeath(s, i);
      expect('maahanisku hiekkaan hautaa syvemmälle ja syö varoajan',
        plain !== null && dived !== null && dived < plain * 0.8 && !s.lastPound,
        `pudotus ${plain} framea, maahanisku ${dived} framea `
        + `(${Math.round((1 - dived / plain) * 100)} % pois), painallusaalto: `
        + `${s.lastPound ? 'tuli' : 'ei tullut'}, syöksyn lisäuppoama `
        + `${QUICKSAND_PLUNGE_FRAMES} framea`);
    }

    /* 5. …ja matalassa kuopassa senkään ei pidä tappaa. Sama sääntö kuin
     *    kohdassa 2: ensimmäinen kohtaaminen opettaa, se ei rankaise. */
    {
      const s = sandScene(shallowest.id);
      const i = mkInput();
      dropInto(s, shallowest.pool);
      s.player.y = shallowest.pool.top * 16 - s.player.h - 40;
      i.held.down = true;
      i.pressed.jump = true;
      i.held.jump = true;
      s.update(i);
      i.pressed = blank();
      i.held.jump = false;
      const frames = untilDeath(s, i, 600);
      expect('maahanisku matalaan kuoppaan ei tapa',
        frames === null && !s.player.dying,
        `${shallowest.id}: 600 framea, uppoama ${s.player.sunk} framea`);
    }

    /* 6. Tähden lupaus, tarkalleen sellaisena kuin se on kirjattu: se suojaa
     *    vihollisilta ja piikeiltä, ei kentältä itseltään. Hiekka on kenttä. */
    {
      const s = sandScene(deepest.id);
      const i = mkInput();
      dropInto(s, deepest.pool);
      s.player.collect('star');
      const frames = untilDeath(s, i);
      expect('supertähti ei kanna juoksuhiekan yli',
        frames !== null,
        frames === null ? 'tähdellä ei kuollut lainkaan'
          : `tähti päällä ${s.player.star} framea jäljellä, kuoli ${frames} framessa`);
    }

    /* 7. Isompi keho pitää päänsä pinnalla. Tämä ei ole armo vaan geometria,
     *    ja se on kirjattava numerona: kuoppa on matalampi kuin keho. */
    {
      const depth = (deepest.pool.bottom - deepest.pool.top + 1) * 16;
      const drowns = [];
      for (let lvl = 0; lvl <= 5; lvl++) {
        const s = sandScene(deepest.id, { type: 'shroom', level: lvl });
        const i = mkInput();
        dropInto(s, deepest.pool);
        if (untilDeath(s, i) !== null) drowns.push(lvl);
      }
      const tall = SIZES.map((z, n) => (z.h >= depth ? n : -1)).filter((n) => n >= 0);
      expect('hiekka ei hukuta kehoa joka on kuoppaa pidempi',
        drowns.length > 0 && !drowns.some((n) => tall.includes(n)),
        `kuoppa ${depth} px, kehot ${SIZES.map((z) => z.h).join('/')} px — `
        + `hukkuvat voimatasot ${drowns.join(',') || 'ei yksikään'}`);
    }

    /* 8. Hiekka on hidas, ja se mitataan kuljettuna matkana eikä pelkkänä
     *    nopeuslukuna: seinään puskeva pelaaja näyttää hitaalta myös silloin
     *    kun hiekka ei hidasta mitään. Siksi lähtö on lammikon vasemmasta
     *    reunasta, jotta 40 framen matka mahtuu lammikkoon. */
    {
      const s = sandScene(deepest.id);
      const i = mkInput();
      dropInto(s, deepest.pool);
      s.player.x = deepest.pool.tx0 * 16;
      for (let f = 0; f < 20; f++) { s.update(i); i.pressed = blank(); }
      const from = s.player.x;
      i.held.right = true;
      i.held.run = true;
      for (let f = 0; f < 40; f++) { s.update(i); i.pressed = blank(); }
      const inSand = Math.abs(s.player.vx);
      const sandRun = s.player.x - from;
      const s2 = sandScene(deepest.id);
      const i2 = mkInput();
      const from2 = s2.player.x;
      i2.held.right = true;
      i2.held.run = true;
      for (let f = 0; f < 40; f++) { s2.update(i2); i2.pressed = blank(); }
      const onSand = Math.abs(s2.player.vx);
      const groundRun = s2.player.x - from2;
      /* Väite on sidottu olemassa olevaan vakioon eikä valittuun suhdelukuun:
       * kahlauskaton pitää olla alle puolet kävelykatosta, eli hiekassa
       * liikkuminen on hitaampaa kuin hitain tapa liikkua maalla. Kuljettu
       * matka on mukana siksi, ettei katto jäisi pelkäksi luvuksi jota kukaan
       * ei koskaan saavuta. */
      expect('hiekassa kahlataan, päällä juostaan',
        inSand > 0.1 && inSand <= QUICKSAND_WADE + 0.01
        && QUICKSAND_WADE < MAX_WALK / 2 && sandRun < groundRun,
        `hiekassa ${inSand.toFixed(2)} px/frame ja ${Math.round(sandRun)} px 40 framessa, `
        + `maalla ${onSand.toFixed(2)} px/frame ja ${Math.round(groundRun)} px; `
        + `kahlauskatto ${QUICKSAND_WADE} vastaan kävelykatto ${MAX_WALK}`);
    }

    /* 9. Pikatallennus keskellä uppoamista. `savestate.js` sarjallistaa jokaisen
     *    oman kentän, joten tämä on ilmaista — mutta juuri siksi se on myös se
     *    joka rikkoutuu hiljaa, jos uppoaminen joskus siirretään kohtaukseen. */
    {
      const s = sandScene(deepest.id);
      const i = mkInput();
      dropInto(s, deepest.pool);
      for (let f = 0; f < 140; f++) { s.update(i); i.pressed = blank(); }
      const before = { sunk: s.player.sunk, y: Math.round(s.player.y) };
      const snap = captureState(game);
      restoreState(game, snap);
      const p2 = game.scene.player;
      expect('pikatallennus kesken uppoamisen palaa kesken uppoamista',
        before.sunk > 0 && p2.sunk === before.sunk && Math.round(p2.y) === before.y,
        `ennen uppoama ${before.sunk} framea y=${before.y}, `
        + `jälkeen ${p2.sunk} framea y=${Math.round(p2.y)}`);
    }

    /* ------------------- 10. hiekka ja se mikä siihen kävelee ------------ */
    /*
     * Punainen ennen vihreää (DESIGN.md kohta 7) toiselle puoliskolle:
     * **hiekka ei tiennyt vihollisista mitään.**
     *
     * Hiekka on ruutu eikä osuma, joten se koskee kaikkea mikä seisoo lattialla
     * — ja siihen asti se koski vain pelaajaa. Kävelijä joka päätyi lammikkoon
     * putosi sen pohjalle ja jatkoi kävelyä siellä, koko keho pinnan alla,
     * näkymättömänä. Se ei näyttänyt bugilta vaan vitsiltä, ja tänään sen esti
     * pelkkä sijoittelu: 2-1:n ja 2-3:n penkat aitaavat kävelijät lammikoiden
     * ulkopuolelle. Sijoittelurajoite on rajoite vain niin kauan kuin kukaan ei
     * siirrä mitään, ja juuri se on se laji jota testi on olemassa varten.
     *
     * Mitattavat väitteet, ja jokainen niistä on päätös eikä sivutuote:
     *
     *   a. syvässä lammikossa vihollinen uppoaa ja katoaa — samalla kellolla
     *      kuin pelaaja, koska se on sama hiekka
     *   b. matalassa se ei voi hukkua, koska geometria on sama molemmille
     *   c. hukkuminen ei maksa pisteitä (ks. kuilu: sekään ei maksa)
     *   d. pikatallennus kesken vihollisen uppoamista palaa kesken uppoamista
     *   e. merkkinä on hiekan oma pöly, ei pelaajan hukkumisääni
     *   f. jokainen painovoiman varassa liikkuva vihollinen on **päättänyt**
     *      uppoamisestaan — sama portti kuin `ENEMY_COST`
     *   g. ja koko kauppa on tavoitettavissa julkaistussa kentässä eikä vain
     *      koeasetelmassa: 2-1:n kuori potkaistuna vasemmalle
     */
    {
      const enemies = await import('/src/entities/enemies.js');
      const { Sfx } = await import('/src/core/audio.js');

      /** Kaikki neljä lattiakävelijää ja lentäjä, merkkeineen. */
      const species = [['g', enemies.Walker], ['k', enemies.ShellGuy],
        ['x', enemies.SpikeGuy], ['c', enemies.CorkGuy], ['f', enemies.Flyer]];

      /**
       * Yksi vihollinen lammikon keskelle, jalat täsmälleen pinnalla — sama
       * lähtöasento kuin `dropInto` antaa pelaajalle, jotta luvut ovat
       * vertailukelpoisia sen kanssa.
       */
      const dropEnemy = (s, pool, Ctor) => {
        const mid = Math.round(((pool.tx0 + pool.tx1 + 1) / 2) * 16);
        const e = new Ctor(s, mid, pool.top * 16);
        e.x = mid - e.w / 2;
        e.y = pool.top * 16 - e.h;
        e.vx = 0;
        e.vy = 0;
        e.active = true;
        e.alwaysActive = true;
        s.add(e);
        return e;
      };

      /** Ajaa lammikkoa kunnes vihollinen katoaa, ja kertoo mitä matkalla tapahtui. */
      const sinkRun = (id, pool, Ctor, cap = 900) => {
        const s = sandScene(id);
        s.player.x = 16;
        s.player.y = 8 * 16;
        const e = dropEnemy(s, pool, Ctor);
        const i = mkInput();
        const startX = e.x;
        let buried = 0;
        let gone = null;
        for (let f = 0; f < cap; f++) {
          s.update(i);
          if (e.y >= pool.top * 16 + 1) buried++;
          if (e.remove || !s.entities.includes(e)) { gone = f; break; }
        }
        return { gone, buried, dx: Math.round(e.x - startX), e, s };
      };

      /* a. Syvä lammikko: uppoaa ja katoaa, eikä kävele pohjalla. Yläraja on
       *    pelaajan oma lukema — sama hiekka, sama kello — ja alaraja on se
       *    että uppoaminen on uppoamista eikä katoamista kosketuksesta. */
      {
        const rows = [];
        for (const [ch, Ctor] of species) {
          const r = sinkRun(deepest.id, deepest.pool, Ctor);
          rows.push({ ch, gone: r.gone, buried: r.buried });
        }
        expect('syvä hiekka ottaa myös vihollisen, eikä se jää kävelemään pohjalle',
          rows.every((r) => r.gone !== null && r.gone > 60 && r.gone < 400),
          rows.map((r) => `${r.ch}: ${r.gone === null ? 'ei koskaan' : `${r.gone} framea`}`
            + `, ${r.buried} framea pinnan alla`).join(', '));
      }

      /* b. Matala lammikko ei hukuta ketään, ja se on sama geometria jolla se
       *    ei hukuta pelaajaakaan: keho on kuoppaa pidempi. Tämä on vihreä jo
       *    ennen korjausta ja on se puoli jota korjaus ei saa rikkoa. */
      {
        const rows = [];
        for (const [ch, Ctor] of species) {
          const r = sinkRun(shallowest.id, shallowest.pool, Ctor, 600);
          rows.push({ ch, gone: r.gone, top: Math.round(r.e.y - shallowest.pool.top * 16) });
        }
        const depth = (shallowest.pool.bottom - shallowest.pool.top + 1) * 16;
        expect('matala hiekka ei hukuta vihollista sen enempää kuin pelaajaa',
          rows.every((r) => r.gone === null),
          `kuoppa ${depth} px — ` + rows.map((r) => `${r.ch} ${r.gone === null ? 'jäi' : 'katosi'}`
            + ` (pää ${r.top > 0 ? '+' : ''}${r.top} px pinnasta)`).join(', '));
      }

      /* c. Hiekkaan hukkunut vihollinen ei maksa mitään. Ennakkotapaus on
       *    kuilu: kentän pohjan läpi pudonnut vihollinen katoaa ilmaiseksi jo
       *    nyt, ja hukkuminen on sama tapahtuma kansi päällä. Piste maksetaan
       *    tässä pelissä siitä mitä pelaaja teki, ei siitä mitä huone teki. */
      {
        reset();
        const r = sinkRun(deepest.id, deepest.pool, enemies.Walker);
        expect('hiekkaan hukkunut vihollinen ei maksa pisteitä',
          r.gone !== null && game.state.score === 0,
          `kävelijä katosi ${r.gone === null ? 'ei koskaan' : `${r.gone} framessa`}, `
          + `pisteet ${game.state.score}`);
      }

      /* d. Pikatallennus kesken vihollisen uppoamista. Sama väite kuin
       *    kohdassa 9 pelaajalle, ja samasta syystä: uppoaminen on tavallisia
       *    lukuja oliossa, joten `REGISTRY` kantaa sen ilman tallennuskoodia. */
      {
        const s = sandScene(deepest.id);
        game.setScene(s);
        s.player.x = 16;
        s.player.y = 8 * 16;
        const e = dropEnemy(s, deepest.pool, enemies.Walker);
        const i = mkInput();
        for (let f = 0; f < 140; f++) { s.update(i); i.pressed = blank(); }
        const before = { sunk: e.sunk, y: Math.round(e.y) };
        const snap = captureState(game);
        restoreState(game, snap);
        const e2 = game.scene.entities.find((z) => z.constructor.name === 'Walker');
        expect('pikatallennus kesken vihollisen uppoamista palaa kesken uppoamista',
          before.sunk > 0 && !!e2 && e2.sunk === before.sunk && Math.round(e2.y) === before.y,
          `ennen uppoama ${before.sunk} framea y=${before.y}, jälkeen `
          + `${e2 ? `${e2.sunk} framea y=${Math.round(e2.y)}` : 'ei kävelijää'}`);
      }

      /* e. Kuva ja ääni (DESIGN.md kohta 8). Uppoava vihollinen tarvitsee
       *    merkin, mutta se ei saa olla **pelaajan oma** merkki: `upota` ja
       *    `kahlaa` ovat lauseita "sinut sai kiinni", ja aavikossa lammikko voi
       *    olla ruudun ulkopuolella. Ääni ilman näkyvää syytä opettaisi
       *    katsomaan alas silloin kun mitään ei ole. Jäljelle jää hiekan oma
       *    pöly, joka on sama pöly kummalle tahansa keholle. */
      {
        const heard = [];
        const realPlay = Sfx.play;
        Sfx.play = function (name, ...rest) { heard.push(name); return realPlay.call(this, name, ...rest); };
        let puffs = 0;
        try {
          const s = sandScene(deepest.id);
          s.player.x = 16;
          s.player.y = 8 * 16;
          const e = dropEnemy(s, deepest.pool, enemies.Walker);
          const i = mkInput();
          const seen = new Set();
          for (let f = 0; f < 400; f++) {
            s.update(i);
            for (const z of s.entities) {
              if (z.constructor.name === 'Puff' && !seen.has(z.id)) { seen.add(z.id); puffs++; }
            }
            if (e.remove) break;
          }
        } finally {
          Sfx.play = realPlay;
        }
        const borrowed = heard.filter((n) => n === 'upota' || n === 'kahlaa');
        expect('uppoavan vihollisen merkki on hiekan pöly, ei pelaajan hukkumisääni',
          puffs >= 8 && borrowed.length === 0,
          `${puffs} pölyhiukkasta, pelaajan ääniä ${borrowed.length}`
          + `${heard.length ? ` (kuultiin: ${[...new Set(heard)].join(',') || 'ei mitään'})` : ''}`);
      }

      /* f. Portti, ja se on sama portti kuin `ENEMY_COST`.
       *
       * Vihollinen joka putoaa painovoiman varassa on vihollinen joka voi
       * päätyä hiekkaan, joten sen on **sanottava** kumpaa se on. Oletusarvoa
       * ei ole kummallakaan puolella: `true` oletuksena upottaisi hiljaa
       * seuraavan lentävän, `false` oletuksena jättäisi seuraavan kävelijän
       * kävelemään pohjalla — ja juuri jälkimmäinen on se bugi jota tämä lohko
       * korjaa. Kysymys esitetään vain niiltä joita se koskee: luokan oma
       * `update` kertoo lähdetekstissään käyttääkö se `applyGravity`ä, ja koodi
       * on ajossa sellaisenaan (ei käännösvaihetta, DESIGN.md kohta 7).
       */
      {
        const classes = Object.entries(enemies)
          .filter(([, v]) => typeof v === 'function' && v.prototype instanceof enemies.Enemy);
        const undecided = [];
        const silent = [];
        for (const [name, Ctor] of classes) {
          const src = String(Ctor.prototype.update || '');
          const owns = Object.prototype.hasOwnProperty.call(Ctor.prototype, 'sinks');
          if (/applyGravity\(/.test(src) && !owns) undecided.push(name);
          if (owns && Ctor.prototype.sinks && !/this\.sink\(\)/.test(src)) silent.push(name);
        }
        const sinkers = classes.filter(([, C]) => C.prototype.sinks).map(([n]) => n);
        expect('jokainen painovoiman varassa oleva vihollinen on päättänyt hiekasta',
          undecided.length === 0 && silent.length === 0 && sinkers.length >= 4,
          undecided.length || silent.length
            ? `päättämättä: ${undecided.join(',') || '-'}; ilmoittaa uppoavansa muttei kysy `
              + `hiekalta: ${silent.join(',') || '-'}`
            : `${classes.length} luokkaa, uppoavat: ${sinkers.join(' ')}`);
      }

      /* g. Ja se että tämä on tavoitettavissa oikeassa kentässä eikä vain
       *    koeasetelmassa. 2-1:n ainoa kuori seisoo lammikon oikealla puolella,
       *    joten vasemmalle potkaistu kuori päätyy hiekkaan — ja se on koko
       *    kauppa jonka mekaniikka tarjoaa: väline vaihtuu roskikseen. Jos
       *    joku joskus siirtää kumpaa tahansa palikkaa, tämä kertoo sen. */
      {
        reset({ type: 'leaf', level: 3 });
        const s = new LevelScene(game, '2-1');
        game.setScene(s);
        s.time = 9999;
        s.clockStopped = true;
        const shell = s.entities.find((e) => e.constructor.name === 'ShellGuy');
        /* Sarakkeesta eikä riviltä 13: 2-1 sai maastoa (`data/terrain.js`), ja
         * sen lammikko on nyt kolme laattaa ylempänä. Se on yhä sama lammikko
         * samassa sarakkeessa, ja juuri saraketta tämä testi kysyy. */
        const sand = [];
        for (let tx = 0; tx < s.w; tx++) {
          for (let ty = 0; ty < s.h; ty++) {
            if (s.rawTileAt(tx, ty) === T.QUICKSAND) { sand.push(tx); break; }
          }
        }
        let gone = null;
        let col = null;
        if (shell && sand.length) {
          shell.alwaysActive = true;
          shell.active = true;
          shell.toShell();
          shell.kick(-1);
          s.player.x = shell.x + 60;
          s.player.y = shell.y - 40;
          const i = mkInput();
          for (let f = 0; f < 600; f++) {
            s.update(i);
            if (shell.remove) { gone = f; break; }
          }
          col = Math.floor(shell.cx / 16);
        }
        expect('2-1:ssä vasemmalle potkaistu kuori päätyy hiekkaan eikä ohi',
          gone !== null && sand.includes(col),
          `kuori sarakkeessa ${col}, hiekka ${sand[0]}–${sand[sand.length - 1]}, `
          + `katosi ${gone === null ? 'ei koskaan' : `${gone} framessa`}`);
      }
    }
  } catch (e) {
    expect('juoksuhiekan testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ------------------------------ KURNUTTAJA ---------------------------- */
  /*
   * KUILUSTA LOIKKAAVA — ja se mitä siitä pitää todistaa.
   *
   * Kuilu on tähän asti ollut binäärinen: joko ylität sen tai kuolet. Kun
   * kuiluun pannaan olento, vaaralliseksi muuttuu **ilma kuilun yllä** — juuri
   * se paikka jossa pelaajalla on vähiten ohjausta, kesken hyppyä ja sidottuna,
   * pelkkä vauhti jäljellä. Huolimattomasti tehtynä se muuttaa hypyn, jonka
   * pelaaja itse valitsi, kuolemaksi jota hän ei voinut välttää. Siksi
   * "vihollinen on olemassa" ei todista tästä mitään, ja alla mitataan viisi
   * asiaa jotka voivat mennä pieleen:
   *
   *   1. varoitus ehtii ennen kuin hyppy on sidottu
   *   2. sykli on deterministinen — myös pikatallennuksen yli
   *   3. loikka pysyy omassa sarakkeessaan, eli maassa seisova on turvassa
   *   4. tapposäännöt: ei tallausta, mutta pierupallo ja tähti purevat
   *   5. maahanisku ei yletä kuiluun, eikä kuiluun sukeltaminen ole vastaus
   *
   * Koko lohko on try/catchissa samasta syystä kuin maahanisku-lohko: puuttuva
   * vienti kaataisi dynaamisen importin ja veisi mukanaan kaiken tämän
   * jälkeisen, jolloin punaisesta ei näkisi mitään.
   */
  try {
    const { Kurnuttaja, KURN_WAIT, KURN_WARN } = await import('/src/entities/enemies.js');
    const budget = await (await fetch('/tools/jump-budget.json')).json();

    /** Yksi kurnuttaja tyhjiössä: oma kenttä, ei muita vihollisia häiritsemässä. */
    const lone = (power = { type: null, level: 0 }, lipY = 208) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      const k = new Kurnuttaja(s, 40 * 16, lipY);
      k.active = true;
      k.alwaysActive = true;
      s.entities.push(k);
      return { s, k };
    };

    /**
     * Yhden syklin muoto frameina: milloin varoitus alkaa, milloin ruumis voi
     * satuttaa, milloin loikka on ohi. Luetaan olion omasta tilasta eikä
     * vakioista, koska juuri vakion ja käytöksen ero on se mikä rapautuu.
     */
    const cycle = (k, frames = 1200) => {
      const out = [];
      let warnAt = -1;
      let hurtAt = -1;
      for (let f = 0; f < frames; f++) {
        const wasWarn = k.warning > 0;
        const wasHurt = !k.harmless;
        k.update();
        if (!wasWarn && k.warning > 0) warnAt = f;
        if (!wasHurt && !k.harmless) hurtAt = f;
        if (wasHurt && k.harmless && warnAt >= 0 && hurtAt >= 0) {
          out.push({ warnAt, hurtAt, doneAt: f, lead: hurtAt - warnAt });
          warnAt = -1;
          hurtAt = -1;
        }
      }
      return out;
    };

    /*
     * 1. VAROITUS ENNEN SITOUTUMISTA, MITATTUNA LENNON PITUUTTA VASTAAN.
     *
     * Väite on tämä: jos varoitus kestää vähintään yhtä kauan kuin pisin
     * voimatason 0 hyppy on ilmassa, niin **jokainen loikka joka voi osua
     * lentävään pelaajaan oli varoitettu ennen kuin hän lähti maasta**. Todistus
     * on kolme riviä: varoitus alkaa framella t, loikka framella t+W, pelaaja
     * lähtee framella u ja laskeutuu framella u+A. Osuma edellyttää t+W < u+A,
     * eli t < u + (A-W); jos W >= A, niin t < u.
     *
     * A luetaan mitatusta hyppybudjetista (`tools/measure-jump.mjs`) eikä
     * arvata. Pieruhypyn tapaus jätetään ulos tarkoituksella: se on pelin ainoa
     * hyppy jonka voi *muuttaa kesken kaiken*, eli se ei ole sitoutuminen samalla
     * tavalla — ja DESIGN.md kohta 5 sanoo muutenkin että tehostus avaa
     * paikkoja, ei kenttää, joten lupaus mitataan voimatasolta 0.
     */
    {
      const power0 = budget.cases.filter((c) => !/fart|pieru/i.test(c.label));
      const airborne = Math.max(...power0.map((c) => c.frames));
      const longest = power0.find((c) => c.frames === airborne);
      const { k } = lone();
      const laps = cycle(k);
      const leads = laps.map((l) => l.lead);
      const minLead = leads.length ? Math.min(...leads) : -1;
      expect('kurnuttajan varoitus kestää pidempään kuin pisin voimatason 0 hyppy on ilmassa',
        laps.length >= 3 && minLead >= airborne,
        `varoitus ${minLead} framea (vakio ${KURN_WARN}), pisin hyppy ilmassa ${airborne}`
        + ` framea ("${longest ? longest.label : '?'}"), pelivara ${minLead - airborne}`
        + ` framea; juoksuvauhdilla 2,5 px/frame varoitus on ${Math.round(minLead * 2.5)} px`
        + ` eli ${(minLead * 2.5 / 16).toFixed(1)} ruutua lähestymistä`);
    }

    /*
     * 2. SYKLI ON DETERMINISTINEN. Pomon piikkisykli on, ja tiekartta nimeää sen
     *    hyveeksi. Kaksi oliota jotka heräsivät samalla framella ovat framen
     *    tarkkuudella samassa tahdissa, ja peräkkäiset kierrokset ovat yhtä
     *    pitkiä — jälkimmäinen on se joka kaatuisi jos syklissä olisi
     *    `Math.random()`.
     */
    {
      const a = lone();
      const b = lone();
      const one = cycle(a.k);
      const two = cycle(b.k);
      const same = JSON.stringify(one) === JSON.stringify(two);
      const lengths = one.slice(1).map((l, i) => l.warnAt - one[i].warnAt);
      const steady = lengths.length > 0 && lengths.every((v) => v === lengths[0]);
      expect('kurnuttajan sykli on deterministinen ja joka kierros yhtä pitkä',
        same && steady,
        `${one.length} kierrosta, pituudet ${lengths.join('/')} framea`
        + ` (odotus ${KURN_WAIT} + varoitus ${KURN_WARN} + loikka)`
        + `, kaksi oliota samassa tahdissa: ${same}`);
    }

    /* 3. Ja pikatallennus palaa samaan rytmiin. `savestate.js` sarjallistaa
     *    entiteetin omat kentät, joten tämä kaatuu jos luokka puuttuu
     *    REGISTRYstä — silloin kurnuttaja katoaa tallennuksesta kokonaan. */
    {
      const { s, k } = lone();
      game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-1');
      while (k.phase !== 'warn') k.update();
      for (let f = 0; f < 20; f++) k.update();
      const before = { phase: k.phase, timer: k.timer, y: Math.round(k.y) };
      const snap = captureState(game);
      restoreState(game, JSON.parse(JSON.stringify(snap)));
      const r = game.scene;
      const back = r.entities.find((e) => e.constructor.name === 'Kurnuttaja');
      const after = back
        ? { phase: back.phase, timer: back.timer, y: Math.round(back.y) } : null;
      let mine = -1;
      let theirs = -1;
      for (let f = 0; f < 400; f++) {
        if (mine < 0 && !k.harmless) mine = f;
        if (after && theirs < 0 && !back.harmless) theirs = f;
        k.update();
        if (back) back.update();
      }
      expect('pikatallennus palauttaa kurnuttajan samaan kohtaan sykliä',
        !!after && JSON.stringify(before) === JSON.stringify(after) && mine === theirs && mine > 0,
        `ennen ${JSON.stringify(before)}, jälkeen ${JSON.stringify(after)}`
        + `, loikka ${mine} vs ${theirs} framen päästä`);
    }

    /*
     * 4. LOIKKA PYSYY OMASSA SARAKKEESSAAN.
     *
     * Tämä on se sääntö joka tekee tästä ajoitustehtävän eikä ansan: vaara on
     * täsmälleen kuilun yllä oleva ilma, eikä koskaan sen reunalla oleva maa.
     * Mitataan molemmat päät — että x ei liiku lainkaan, ja että reunalla
     * seisova pelaaja selviää kahdesta kokonaisesta kierroksesta ehjin nahoin.
     */
    {
      const { s, k } = lone();
      const x0 = k.x;
      let drift = 0;
      let top = k.y;
      for (let f = 0; f < 600; f++) {
        k.update();
        drift = Math.max(drift, Math.abs(k.x - x0));
        top = Math.min(top, k.y);
      }
      const rise = Math.round(k.lipY - top);

      const stage = lone();
      const p = stage.s.player;
      const i = mkInput();
      for (let f = 0; f < 4; f++) { stage.s.update(i); i.pressed = blank(); }
      // Pelaaja seisomaan täsmälleen kuilun reunalle, olennon viereen.
      stage.k.x = p.cx + 48 - 8;
      stage.k.lipY = p.y + p.h;
      stage.k.restY = stage.k.lipY + 32;
      stage.k.y = stage.k.restY;
      const level0 = p.powerLevel;
      for (let f = 0; f < 600; f++) { stage.s.update(i); i.pressed = blank(); }
      expect('loikka pysyy kuilun sarakkeessa: reunalla seisova ei voi jäädä alle',
        drift === 0 && rise > 32 && !p.dying && p.powerLevel === level0,
        `x liikkui ${drift} px, loikka nousi ${rise} px reunan yli`
        + `, reunalla seisonut voimataso ${level0}->${p.powerLevel}`);
    }

    /*
     * 5. TAPPOSÄÄNNÖT.
     *
     * Tallaus ei käy, ja syy on se että kuilun yllä olevaan olentoon
     * laskeutuminen tarkoittaa kuilun ylle laskeutumista: peli tarjoaisi
     * vastauksen joka tappaa vastaajan. "Odota" on jo pelin opettama laillinen
     * vastaus (närästyssuihkuun ei voi hypätä lainkaan). Kaikki muu puree kuten
     * putkikasviin: pierupallo, häntä ja liukuva kuori.
     */
    {
      const { s, k } = lone({ type: 'shroom', level: 1 });
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 4; f++) { s.update(i); i.pressed = blank(); }
      k.lipY = p.y + p.h;
      k.restY = k.lipY + 32;
      k.phase = 'leap';
      k.y = k.lipY - 24;
      k.vy = -2;
      k.x = p.cx - 8;
      const level0 = p.powerLevel;
      p.y = k.y - p.h - 2;
      p.vy = 4;
      p.onGround = false;
      for (let f = 0; f < 4 && !p.dying; f++) s.update(i);
      const stompedIt = k.remove || k.dying;

      const shot = lone();
      shot.k.phase = 'leap';
      shot.k.y = shot.k.lipY - 24;
      shot.k.hitByProjectile(1);

      expect('kurnuttajaa ei voi tallata, mutta pierupallo kaataa sen',
        k.stompable === false && !stompedIt && p.powerLevel === level0 - 1
        && (shot.k.dying || shot.k.remove),
        `tallattava ${k.stompable}, tallaus tappoi ${stompedIt}`
        + `, pelaajan voimataso ${level0}->${p.powerLevel}`
        + `, pierupallo tappoi ${shot.k.dying || shot.k.remove}`);
    }

    /*
     * 6. SUPERTÄHTI. Se suojaa kentän asukeilta ja nimenomaan ei kentältä
     *    itseltään — kuilu, laava ja kello ovat sen ulkopuolella. Kurnuttaja on
     *    asukki kuilun yllä, joten se on tähden puolella rajaa; kuilu sen alla
     *    ei ole, ja tämä mittaa molemmat samassa testissä.
     */
    {
      const { s, k } = lone();
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 4; f++) { s.update(i); i.pressed = blank(); }
      p.collect('star');
      k.lipY = p.y + p.h;
      k.restY = k.lipY + 32;
      k.phase = 'leap';
      k.y = k.lipY - 20;
      k.vy = -2;
      k.x = p.cx - 8;
      const level0 = p.powerLevel;
      s.collisions();
      const killed = k.dying || k.remove;
      const unhurt = !p.dying && p.powerLevel === level0;

      // ...ja sama tähti ei kanna kuilun yli. Syy luetaan siitä mitä kohtaus
      // kirjaa, koska pelkkä "kuoli" ei erottaisi kuilua vihollisesta.
      let cause = '';
      s.onPlayerDied = (why) => { cause = why; };
      p.y = s.heightPx + 40;
      s.playerTiles();
      expect('supertähti kantaa kurnuttajan yli mutta ei kuilun yli',
        killed && unhurt && p.dying && cause === 'pit',
        `tähti tappoi olennon ${killed}, pelaaja ehjä ${unhurt}`
        + `, kuiluun pudonnut kuoli syystä "${cause}"`);
    }

    /*
     * 7. MAAHANISKU (v26.08.09.31), ja vastaus tulee geometriasta eikä lipusta.
     *
     * Iskuaalto juoksee lattiaa pitkin, ja lattia loppuu kuilun reunaan. Se ei
     * ole erikoistapaus koodissa vaan mitattava luku: iskun säde voimatasolla 0
     * vastaan matka reunalta kuilun keskelle. Kurnuttaja EI ole piikikäs — jos
     * se olisi, "piikit" lakkaisi tarkoittamasta piikkejä — vaan isku ei
     * yksinkertaisesti ulotu sinne. Ja kuiluun sukeltaminen on jo kuolema.
     */
    {
      const half = (budget.gapTiles * 16) / 2;
      const { s } = lone();
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 8; f++) { s.update(i); i.pressed = blank(); }
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      const standY = p.y;
      p.y = standY - 90;
      p.vy = 0;
      p.onGround = false;
      i.held.down = true;
      i.pressed.jump = true;
      i.held.jump = true;
      s.update(i);
      i.pressed = blank();
      i.held.jump = false;
      i.held.down = false;
      let f = 1;
      while (f < 400 && !s.lastPound) { s.update(i); f++; }
      const lp = s.lastPound;
      const probe = new Kurnuttaja(s, 0, 208);
      expect('maahanisku ei yletä kuilun keskelle, eikä kurnuttaja ole piikikäs',
        !!lp && lp.reach < half && probe.spiky === false,
        `iskun säde ${lp ? lp.reach : '-'} px voimatasolla ${p.powerLevel}`
        + `, matka reunalta ${budget.gapTiles} ruudun kuilun keskelle ${half} px`
        + `, piikikäs ${probe.spiky}`);
    }

    /*
     * 8. KUVA JA ÄÄNI SAMASSA TAHDISSA (DESIGN.md kohta 8), ja kumpikaan ei saa
     *    olla vanha merkki. Varoituksella on oma äänensä ja loikalla omansa, ja
     *    kumpikin soi samalla framella kuin sen kuva alkaa.
     */
    {
      const { s, k } = lone();
      const { Sfx } = await import('/src/core/audio.js');
      const realPlay = Sfx.play;
      const heard = [];
      Sfx.play = function spy(name) { heard.push({ name, f: s.tick }); };
      let warnFrame = -1;
      let leapFrame = -1;
      let warnHeard = null;
      let leapHeard = null;
      try {
        for (let f = 0; f < 600; f++) {
          const before = heard.length;
          k.update();
          const fresh = heard.slice(before).map((h) => h.name);
          if (warnFrame < 0 && k.warning > 0) { warnFrame = f; warnHeard = fresh; }
          if (leapFrame < 0 && k.phase === 'leap') { leapFrame = f; leapHeard = fresh; }
        }
      } finally {
        Sfx.play = realPlay;
      }
      const OLD = ['jump', 'bigjump', 'fart', 'squeak', 'pop', 'kick', 'spikes', 'boss',
        'stomp', 'slam', 'dive', 'sprout', 'bump', 'timewarn', 'pipe', 'cork'];
      const warnSound = warnHeard && warnHeard[0];
      const leapSound = leapHeard && leapHeard[0];
      expect('varoituksella ja loikalla on omat äänensä, samalla framella kuin kuva',
        warnHeard && warnHeard.length === 1 && leapHeard && leapHeard.length === 1
        && !OLD.includes(warnSound) && !OLD.includes(leapSound) && warnSound !== leapSound
        && Sfx.has(warnSound) && Sfx.has(leapSound),
        `varoitus framella ${warnFrame} soitti "${warnSound}"`
        + `, loikka framella ${leapFrame} soitti "${leapSound}"`);
    }

    /*
     * 9. MIHIN KUILUIHIN SE PANNAAN. Ei jokaiseen: vaara joka on jokaisessa
     *    kolossa on maastoa, ja maasto ei ole vaara. Sääntö on että kurnuttaja
     *    asuu kuilussa jonka pelaaja jo osaa ylittää — mitatun hyppybudjetin
     *    sisällä ja ilman astinkiveä — ja kentässä on niitä enintään yksi.
     */
    {
      const { getLevel, levelIds } = await import('/src/data/levels.js');
      const homes = [];
      const bad = [];
      for (const id of levelIds()) {
        const rows = getLevel(id).rows;
        for (let y = 0; y < rows.length; y++) {
          for (let x = 0; x < rows[y].length; x++) {
            if (rows[y][x] !== 'U') continue;
            // Kuinka leveä kuilu sen ympärillä on, ja onko se koko kuilu.
            const solid = (c) => '#XB?!*uN[]{}%()S'.includes(c);
            let from = x;
            let to = x;
            while (from > 0 && !solid(rows[y][from - 1])) from--;
            while (to < rows[y].length - 1 && !solid(rows[y][to + 1])) to++;
            homes.push({ id, x, span: to - from + 1 });
          }
        }
      }
      const perLevel = {};
      for (const h of homes) perLevel[h.id] = (perLevel[h.id] || 0) + 1;
      for (const h of homes) {
        if (h.span > budget.gapTiles) bad.push(`${h.id} @${h.x}: kuilu ${h.span} ruutua > ${budget.gapTiles}`);
      }
      for (const [id, n] of Object.entries(perLevel)) {
        if (n > 1) bad.push(`${id}: ${n} kurnuttajaa samassa kentässä`);
      }
      expect('kurnuttaja asuu vain hyppybudjettiin mahtuvassa kuilussa, yksi per kenttä',
        homes.length >= 2 && bad.length === 0,
        bad.length ? bad.join('; ')
          : `${homes.length} kpl: ${homes.map((h) => `${h.id} sarake ${h.x} kuilu ${h.span}`).join(', ')}`);

      /*
       * JARRUTUSIKKUNA ON KOKONAAN MAATA.
       *
       * Ylempi väite mittaa kuilun leveyden, eli sen pääseekö yli. Se ei mittaa
       * pääseekö **pysähtymään**, ja juuri se oli rikki: merkki oli kuilun
       * keskellä kolmessa palikassa, ja voimatason 0 jarrutusmatka on 4 laattaa,
       * joten ikkunan `[merkki−4, merkki−1]` kaksi viimeistä saraketta olivat jo
       * ilman päällä. Pelaaja joka näki olennon ja päästi napista irti oikealla
       * hetkellä ei silti ehtinyt pysähtyä.
       *
       * Se oli tosi kuudessa kentässä ja löytyi vasta kun opetusmittari sai
       * kurnuttajalle rivin — eli **kertaalleen, vahingossa, kolmannen työkalun
       * sivutuotteena**. Tämä väite tekee siitä pysyvän: se ei kysy mistä
       * palikasta kuoppa tuli, vaan mittaa jokaisen merkin oman ympäristön.
       * Korjaus joka ei kanna mukanaan väitettä ehtii regressoitua ennen kuin
       * kukaan huomaa.
       */
      const BRAKE = 4;                       // laattaa, voimataso 0 (PHYSICS.md)
      const solid = (c) => '#XB?!*uN[]{}%()S'.includes(c);
      const shortWindow = [];
      for (const id of levelIds()) {
        const rows = getLevel(id).rows;
        for (let y = 0; y < rows.length; y++) {
          for (let x = 0; x < rows[y].length; x++) {
            if (rows[y][x] !== 'U') continue;
            let ground = 0;
            for (let c = x - BRAKE; c <= x - 1; c++) {
              if (c >= 0 && solid(rows[y][c])) ground++;
            }
            if (ground < BRAKE) {
              shortWindow.push(`${id} @${x}: ikkuna [${x - BRAKE}, ${x - 1}] ${ground}/${BRAKE} maata`);
            }
          }
        }
      }
      expect('kurnuttajan eteen mahtuu koko jarrutusmatka maata',
        homes.length >= 2 && shortWindow.length === 0,
        shortWindow.length ? shortWindow.join('; ')
          : `${homes.length} kuoppaa, jokaisen edessä ${BRAKE}/${BRAKE} laattaa maata`);
    }
  } catch (e) {
    expect('kurnuttaja-testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* A piranha hidden inside its pipe must not hurt anybody. Its box collapses
   * to zero height while it is down, but a zero-height box still straddles the
   * player's, so standing on the pipe mouth used to be lethal. */
  {
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-2');
    game.setScene(s);
    const { Plant } = await import('/src/entities/enemies.js');
    const i = mkInput();
    for (let f = 0; f < 8; f++) s.update(i);

    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    const feet = s.player.y + s.player.h;
    const plant = new Plant(s, s.player.cx - 8, feet - 33);
    plant.active = true;
    plant.alwaysActive = true;
    plant.phase = 'hidden';
    plant.timer = 999;
    plant.offset = 32;
    plant.y = plant.pipeTopY + 32;
    s.entities.push(plant);

    const powerBefore = s.player.powerLevel;
    s.collisions();
    expect('a piranha hidden in its pipe cannot hurt the player',
      !s.player.dying && s.player.powerLevel === powerBefore,
      `power ${powerBefore}->${s.player.powerLevel}, plant box h=${plant.box.h}`);
  }

  /* The piranha's hitbox must be exactly the part of it sticking out of the
   * pipe, at every point of its animation, and a sliver too small to see must
   * not be able to hurt anyone. */
  {
    reset();
    const s = new LevelScene(game, '1-2');
    const { Plant } = await import('/src/entities/enemies.js');
    const plant = new Plant(s, 100, 112);
    const mouth = 112 + 32;
    const bad = [];
    for (let offset = 0; offset <= 32; offset++) {
      plant.offset = offset;
      plant.y = plant.pipeTopY + offset;
      const box = plant.box;
      if (box.y + box.h !== mouth) bad.push(`offset ${offset}: box ends at ${box.y + box.h}, not ${mouth}`);
      if (box.y < plant.pipeTopY) bad.push(`offset ${offset}: box starts above the sprite`);
      const visible = mouth - box.y;
      if (!plant.harmless && visible < 8) bad.push(`offset ${offset}: ${visible}px sliver still hurts`);
      if (plant.harmless && visible >= 12) bad.push(`offset ${offset}: ${visible}px visible but harmless`);
    }
    expect('the piranha hitbox is exactly what sticks out of the pipe',
      bad.length === 0, bad.slice(0, 3).join('; '));
  }

  /* A standing player must never be a still image: there is always a breath,
   * and after a few seconds the idle performance kicks in. */
  {
    const { drawPlayer } = await import('/src/gfx/sprites.js');
    const canvas = document.createElement('canvas');
    canvas.width = 40;
    canvas.height = 48;
    const g = canvas.getContext('2d');
    const shot = (tick, idle) => {
      g.clearRect(0, 0, 40, 48);
      drawPlayer(g, 12, 10, {
        type: 'shroom', level: 1, facing: 1, frame: 0, state: 'idle',
        ducking: false, running: false, tick, idle,
      });
      return [...g.getImageData(0, 0, 40, 48).data].join(',');
    };
    const breathing = new Set([shot(0, 30), shot(13, 43), shot(26, 56), shot(152, 182)]);
    const performing = new Set();
    for (let beat = 0; beat < 4; beat++) performing.add(shot(300 + beat * 90, 240 + beat * 90));
    expect('a standing player breathes and then finds something to do',
      breathing.size >= 2 && performing.size >= 3,
      `${breathing.size} breathing frames, ${performing.size} idle poses`);
  }

  /* A tap that goes down and up inside one frame must still register: the
   * event handler latches it, so the poll cannot look at an already-released
   * key and drop the press. */
  {
    const { Input } = await import('/src/core/input.js');
    Input.install();
    Input.poll();
    window.dispatchEvent(new KeyboardEvent('keydown', { code: 'KeyZ' }));
    window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyZ' }));
    Input.poll();
    const sawIt = Input.pressed.jump;
    Input.poll();
    expect('a tap shorter than one frame still registers',
      sawIt && !Input.pressed.jump && !Input.held.jump,
      `pressed ${sawIt}, still held after ${Input.held.jump}`);
  }

  /* The world map has to look alive, not printed. */
  {
    const { WorldMapScene } = await import('/src/scenes/worldmap.js');
    reset();
    const map = new WorldMapScene(game);
    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const g = canvas.getContext('2d');
    const frames = new Set();
    for (const t of [0, 20, 45, 70]) {
      map.tick = t;
      g.clearRect(0, 0, 320, 240);
      map.draw(g);
      const d = g.getImageData(0, 0, 320, 240).data;
      let hash = 0;
      for (let i = 0; i < d.length; i += 4 * 37) hash = (hash * 31 + d[i] + d[i + 1] * 3) | 0;
      frames.add(hash);
    }
    expect('the world map animates', frames.size >= 3, `${frames.size} distinct frames`);
  }

  /* ------------------- haarautuva kartta ja mitattu vaikeus ---------------- */

  /*
   * The map's shape rules. These are the ROADMAP's branch conditions turned
   * into something the data cannot get around: every level lies on a way from
   * the start to the fortress, every fork is described, and blocking every
   * rewarded route still leaves a way through.
   *
   * Red before green (DESIGN.md 7): the six broken worlds below come first, and
   * every one of them was checked to be reported before the real map was
   * changed to satisfy the same rules. The one that matters most is the second
   * — a level hanging off the road with no way back is exactly what 2-N was,
   * and it is the shape a half-finished branch has.
   */
  {
    const worlds = await import('/src/data/worlds.js');
    const real = WORLDS.flatMap((w) => worlds.worldProblems(w));
    expect('every world map is a shape the game can actually be played through',
      real.length === 0, real.slice(0, 4).join(' / '));

    /* 1-2 scores 122.8 and 1-3 scores 101.2, so `b` is the harder road. Reusing
     * real levels keeps the fixture honest about the measured table. */
    const mk = (over) => ({
      id: 'wT',
      name: 'TESTI',
      theme: 'grass',
      terrain: [],
      nodes: [
        { id: 's', tx: 0, ty: 0, type: 'start', name: 'ALKU' },
        { id: 'a', tx: 1, ty: 0, type: 'level', level: '1-1', name: 'A' },
        { id: 'b', tx: 2, ty: 0, type: 'level', level: '1-2', name: 'B' },
        { id: 'c', tx: 2, ty: 1, type: 'level', level: '1-3', name: 'C' },
        { id: 'f', tx: 3, ty: 0, type: 'fortress', level: '1-F', name: 'F' },
      ],
      links: [
        { a: 's', b: 'a' }, { a: 'a', b: 'b' }, { a: 'a', b: 'c' },
        { a: 'b', b: 'f' }, { a: 'c', b: 'f' },
      ],
      branches: [{
        from: 'a',
        to: 'f',
        routes: [
          { name: 'HELPPO', via: ['c'] },
          { name: 'VAIKEA', via: ['b'], reward: 'break' },
        ],
      }],
      ...over,
    });

    expect('a well-formed branching world reports nothing',
      worlds.worldProblems(mk({})).length === 0,
      worlds.worldProblems(mk({})).join(' / '));

    const cases = [
      ['umpikuja', 'umpikuja', mk({
        nodes: [...mk({}).nodes, { id: 'd', tx: 4, ty: 2, type: 'level', level: '2-N', name: 'D' }],
        links: [...mk({}).links, { a: 'b', b: 'd' }],
      })],
      ['ilmoittamaton haara', 'haarautuu ilmoittamatta', mk({ branches: [] })],
      ['reitti ilman linkkiä', 'puuttuu linkki', mk({
        links: mk({}).links.filter((l) => !(l.a === 'b' && l.b === 'f')),
      })],
      ['palkinto helpolla reitillä', 'ei ole vaikeampi', mk({
        branches: [{
          from: 'a',
          to: 'f',
          routes: [
            { name: 'HELPPO', via: ['c'], reward: 'break' },
            { name: 'VAIKEA', via: ['b'] },
          ],
        }],
      })],
      ['kaikki reitit palkittuja', 'helppo reitti ei vie linnakkeeseen', mk({
        branches: [{
          from: 'a',
          to: 'f',
          routes: [
            { name: 'HELPPO', via: ['c'], reward: 'break' },
            { name: 'VAIKEA', via: ['b'], reward: 'break' },
          ],
        }],
      })],
      ['tuntematon palkinto', 'tuntematon palkinto', mk({
        branches: [{
          from: 'a',
          to: 'f',
          routes: [
            { name: 'HELPPO', via: ['c'] },
            { name: 'VAIKEA', via: ['b'], reward: 'kultaharkko' },
          ],
        }],
      })],
    ];
    const missed = cases.filter(([, needle, world]) =>
      !worlds.worldProblems(world).some((p) => p.includes(needle)));
    expect('a broken map is reported rather than drawn',
      missed.length === 0, missed.map(([name]) => name).join(', ') || `${cases.length} tapausta`);
  }

  /* Every string the map data asks the map to print has to exist in the font.
   * A missing glyph does not throw — it leaves a hole and moves the cursor on —
   * so this draws each character alone and looks for ink, the same way the
   * challenge link's address box is checked. */
  {
    const worlds = await import('/src/data/worlds.js');
    const font = await import('/src/gfx/font.js');
    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 12;
    const g = canvas.getContext('2d');
    const missing = new Set();
    for (const s of WORLDS.flatMap((w) => worlds.mapStrings(w))) {
      for (const ch of String(s).toUpperCase()) {
        if (ch === ' ') continue;
        g.clearRect(0, 0, 16, 12);
        font.drawText(g, ch, 2, 2, { color: '#ffffff' });
        const d = g.getImageData(0, 0, 16, 12).data;
        let ink = 0;
        for (let i = 3; i < d.length; i += 4) if (d[i] > 0) ink++;
        if (!ink) missing.add(ch);
      }
    }
    expect('every name the map prints is spellable in the font',
      missing.size === 0, missing.size ? `puuttuu: ${[...missing].join('')}` : '');
  }

  /* The measured difficulty has to reach the screen, not just the data file. */
  {
    const { WorldMapScene } = await import('/src/scenes/worldmap.js');
    const worlds = await import('/src/data/worlds.js');
    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const g = canvas.getContext('2d');
    const shot = (nodeId, cleared = {}) => {
      reset();
      game.state.world = 1;
      game.state.node = nodeId;
      game.state.cleared = cleared;
      const map = new WorldMapScene(game);
      map.mode = 'idle';
      map.tick = 30;
      g.clearRect(0, 0, 320, 240);
      map.draw(g);
      return g.getImageData(0, 0, 320, 240).data;
    };
    const count = (data, [r, gg, b], y0, y1) => {
      let n = 0;
      for (let y = y0; y < y1; y++) {
        for (let x = 0; x < 320; x++) {
          const i = (y * 320 + x) * 4;
          if (data[i] === r && data[i + 1] === gg && data[i + 2] === b) n++;
        }
      }
      return n;
    };

    const w2 = WORLDS[1];
    const branch = worlds.branchAt(w2, 'w2-2');
    const easy = branch && branch.easiest;
    const hard = branch && branch.hardest;
    expect('world 2 forks, and the two roads measure differently',
      !!branch && easy.pips !== hard.pips && hard.score > easy.score,
      branch ? `${easy.name} ${easy.score.toFixed(1)} (${easy.pips}) vs `
        + `${hard.name} ${hard.score.toFixed(1)} (${hard.pips})` : 'ei haaraa');

    /* Tier 2 is #c8e048 and belongs to nothing else on this map, so its pixels
     * are the gentler road's own: its path dots and the bars under 2-N. */
    const atFork = shot('w2-2', { 'w2-2': true });
    expect('the gentler road is drawn in its measured tier colour',
      count(atFork, [200, 224, 72], 14, 158) > 30,
      `${count(atFork, [200, 224, 72], 14, 158)} px`);

    /* The board only exists where the roads part. Off the fork the same band is
     * the ordinary panel, so the difference is the board itself. */
    const off = shot('w2-1', { 'w2-2': true });
    const goldHere = count(atFork, [255, 208, 72], 200, 226);
    const goldThere = count(off, [255, 208, 72], 200, 226);
    expect('standing on the fork spells out both roads and what they pay',
      goldHere > 100 && goldThere === 0,
      `palkintotekstiä haarassa ${goldHere} px, muualla ${goldThere} px`);

    /*
     * And the branch has to be walkable in both directions, or it is a picture
     * of a choice rather than one.
     *
     * **Kävely luetaan nyt haarailmoituksesta eikä muistista, ja se kävellään
     * linnakkeeseen asti.** Vanha muoto oli kolme nimettyä askelta — alas
     * `w2-n`, oikealle `w2-f`, oikealle `w2-3` — ja se oli sekä liian vähän
     * että liian paljon. Liian vähän, koska otsikko lupaa että molemmat tiet
     * *päätyvät linnakkeeseen* eikä testi kävellyt laavatietä pidemmälle kuin
     * ensimmäiseen solmuun. Liian paljon, koska nuolet ja solmutunnukset olivat
     * kirjoitettuna tähän: kun tiet 10.8.2026 alkoivat yhtyä kenttään 2-4
     * linnakkeen sijaan, testi punastui kartasta joka on kunnossa — se mittasi
     * vanhaa karttaa eikä nykyistä lupausta.
     *
     * Nyt jono johdetaan datasta (`branch.routes`, `routeChain` ja loppupää
     * linkkejä seuraten) ja suunta etsitään kokeilemalla kaikki neljä nuolta,
     * kuten linkkiportti tekee. Testi ei siis tiedä kartasta mitään paitsi sen
     * mitä kartta itse sanoo, ja se kestää seuraavankin muutoksen.
     */
    const fortId = (worlds.fortressNode(w2) || {}).id;
    const tail = [];
    for (let cur = branch.to; cur && cur !== fortId;) {
      const next = w2.links.filter((l) => l.a === cur).map((l) => l.b)[0];
      if (!next) break;
      tail.push(next);
      cur = next;
    }
    const walkRoute = (route) => {
      const want = [...route.via, branch.to, ...tail];
      const seen = [];
      let at = branch.from;
      for (const id of want) {
        let arrived = null;
        for (const dir of ['left', 'right', 'up', 'down']) {
          reset();
          game.state.world = 1;
          game.state.node = at;
          game.state.cleared = Object.fromEntries(w2.nodes.map((n) => [n.id, true]));
          const map = new WorldMapScene(game);
          map.mode = 'idle';
          map.tryMove(dir);
          if (map.mode !== 'walk' || !map.targetNode || map.targetNode.id !== id) continue;
          for (let f = 0; f < 4000 && map.mode === 'walk'; f++) map.update({
            pressed: blank(), held: blank(), released: blank(), consume() {},
          });
          arrived = map.node.id;
          break;
        }
        if (arrived !== id) { seen.push(`✗${id}`); break; }
        seen.push(id);
        at = id;
      }
      return seen;
    };
    const routes = (branch.routes || []).map((r) => ({ name: r.name, seen: walkRoute(r) }));
    const arrives = routes.every((r) => r.seen[r.seen.length - 1] === fortId);
    expect('both roads out of the fork are walkable and both reach the fortress',
      routes.length >= 2 && arrives,
      routes.map((r) => `${r.name}: ${r.seen.join(' → ')}`).join(' | '));
  }

  /* ------------- kartan luettavuus: polku, kalusto ja vaikeuslaatta -------- */
  /*
   * Kolme valitusta, yksi kuva. Omistaja pelasi kartan läpi ja sanoi kolme
   * asiaa: puut seisovat polun päällä, kentän numerolaatta on ahdettu täyteen,
   * ja linkit on vedetty viivaimella. Ne ovat sama kuva ja siksi sama testi.
   *
   * Kaikki kolme mitataan pikseleistä eikä katsota silmällä, koska "näyttää
   * ahtaalta" ei ole luku jonka voi rikkoa vahingossa uudestaan. Jokainen alla
   * oleva väite nähtiin punaisena ennen kuin mitään korjattiin, ja rivikommentit
   * kertovat mitä se mittasi silloin.
   */
  {
    const worlds = await import('/src/data/worlds.js');
    const { WorldMapScene, TIER_COLORS, PIP_OFF } = await import('/src/scenes/worldmap.js');
    const cv = document.createElement('canvas');
    cv.width = 320;
    cv.height = 240;
    const g = cv.getContext('2d');

    /*
     * Se kalusto joka nousee maasta ylös ja siksi tukkii polun. Lista on tässä
     * testissä käsin kirjoitettuna eikä luettuna `worlds.js`:stä tarkoituksella:
     * jos sääntö ja sen tarkistus lukevat saman muuttujan, merkin poistaminen
     * listalta korjaa molemmat ja testi lakkaa olemasta testi. Luvut ovat
     * `drawTerrain`in omista suorakulmioista, ruudun yläreunasta laskien:
     *   T puu     y+1..y+14   P mänty  y+1..y+14   M vuori  y+3..y+15
     *   C kaktus  y+3..y+14   R kivi   y+8..y+13   " pensas y+6..y+13
     *   E koneisto y+1..y+14  K kallo  y+4..y+14
     * Polun pisteen oma muste on y+5..y+10 ruudun sisällä, joten jokainen näistä
     * osuu siihen suoraan jos se seisoo samassa ruudussa.
     */
    const TALL = 'TPMCR"EK';
    const bare = new RegExp(`[${TALL}]`, 'g');

    const rgbaOf = (paint) => {
      g.clearRect(0, 0, 320, 240);
      paint(g);
      return g.getImageData(0, 0, 320, 240).data;
    };
    const inkOf = (paint) => {
      const d = rgbaOf(paint);
      const m = new Uint8Array(320 * 240);
      for (let i = 0; i < m.length; i++) if (d[i * 4 + 3] > 8) m[i] = 1;
      return m;
    };
    const hueOf = (d, hex) => {
      const r = parseInt(hex.slice(1, 3), 16);
      const gg = parseInt(hex.slice(3, 5), 16);
      const b = parseInt(hex.slice(5, 7), 16);
      const m = new Uint8Array(320 * 240);
      for (let i = 0; i < m.length; i++) {
        if (d[i * 4] === r && d[i * 4 + 1] === gg && d[i * 4 + 2] === b && d[i * 4 + 3] > 200) m[i] = 1;
      }
      return m;
    };
    const count = (m) => { let n = 0; for (let i = 0; i < m.length; i++) n += m[i]; return n; };

    /* Chebyshev-etäisyysmuunnos kahdella pyyhkäisyllä. Chebyshev eikä euklidinen
     * siksi, että kysymys on "montako tyhjää pikseliä väliin jää" — vinottain
     * naapuri on yhtä lähellä kuin suoraan sivulla oleva, kun molemmat peittyvät
     * saman kokoisen pisteen alle. */
    const distFrom = (m) => {
      const d = new Int32Array(320 * 240).fill(1 << 20);
      for (let i = 0; i < d.length; i++) if (m[i]) d[i] = 0;
      for (let y = 0; y < 240; y++) {
        for (let x = 0; x < 320; x++) {
          const i = y * 320 + x;
          let v = d[i];
          if (x > 0) v = Math.min(v, d[i - 1] + 1);
          if (y > 0) v = Math.min(v, d[i - 320] + 1);
          if (x > 0 && y > 0) v = Math.min(v, d[i - 321] + 1);
          if (x < 319 && y > 0) v = Math.min(v, d[i - 319] + 1);
          d[i] = v;
        }
      }
      for (let y = 239; y >= 0; y--) {
        for (let x = 319; x >= 0; x--) {
          const i = y * 320 + x;
          let v = d[i];
          if (x < 319) v = Math.min(v, d[i + 1] + 1);
          if (y < 239) v = Math.min(v, d[i + 320] + 1);
          if (x < 319 && y < 239) v = Math.min(v, d[i + 321] + 1);
          if (x > 0 && y < 239) v = Math.min(v, d[i + 319] + 1);
          d[i] = v;
        }
      }
      return d;
    };
    /** Tyhjiä pikseleitä kahden piirroksen väliin: 0 = koskettavat, -1 = päällekkäin. */
    const clearance = (a, b) => {
      const d = distFrom(a);
      let best = 1 << 20;
      for (let i = 0; i < b.length; i++) if (b[i] && d[i] < best) best = d[i];
      return best - 1;
    };

    const mapOf = (wi) => {
      reset();
      game.state.world = wi;
      game.state.node = WORLDS[wi].nodes[0].id;
      game.state.cleared = Object.fromEntries(WORLDS[wi].nodes.map((n) => [n.id, true]));
      const m = new WorldMapScene(game);
      m.tick = 30;
      return m;
    };

    /* --- 1. kalusto ei seiso polulla eikä sen vieressä --- */

    /* Sama polun geometria kuin `worldProblems`illa, mutta laskettuna tässä
     * uudelleen: sääntö ja sen todiste eivät saa jakaa samaa koodia. */
    const zoneOf = (w) => {
      const path = new Set(w.nodes.map((n) => `${n.tx},${n.ty}`));
      for (const l of w.links) {
        const pts = worlds.linkPoints(w, l);
        for (let i = 0; i < pts.length - 1; i++) {
          let { tx, ty } = pts[i];
          const dx = Math.sign(pts[i + 1].tx - tx);
          const dy = Math.sign(pts[i + 1].ty - ty);
          path.add(`${tx},${ty}`);
          while (tx !== pts[i + 1].tx || ty !== pts[i + 1].ty) {
            if (tx !== pts[i + 1].tx) tx += dx;
            if (ty !== pts[i + 1].ty) ty += dy;
            path.add(`${tx},${ty}`);
          }
        }
      }
      const zone = new Set(path);
      for (const k of path) {
        const [tx, ty] = k.split(',').map(Number);
        for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) zone.add(`${tx + dx},${ty + dy}`);
      }
      return zone;
    };

    const planted = [];
    for (const w of WORLDS) {
      const zone = zoneOf(w);
      for (let ty = 0; ty < w.terrain.length; ty++) {
        for (let tx = 0; tx < w.terrain[ty].length; tx++) {
          if (TALL.includes(w.terrain[ty][tx]) && zone.has(`${tx},${ty}`)) {
            planted.push(`${w.id} ${w.terrain[ty][tx]}@${tx},${ty}`);
          }
        }
      }
    }
    expect('yksikään puu, kivi tai koneisto ei seiso polulla eikä sen vieressä',
      planted.length === 0, planted.length ? `${planted.length}: ${planted.slice(0, 6).join(' ')}` : `${WORLDS.length} maailmaa`);

    /* Ja sama pikseleinä: piirretään maasto kahdesti, kerran oikeana ja kerran
     * ilman korkeaa kalustoa, ja erotus ON kaluston muste. Sitten mitataan
     * paljonko tyhjää jää polun ja lähimmän kalusteen väliin. */
    let worstScenery = { d: 1 << 20, id: '?' };
    for (let wi = 0; wi < WORLDS.length; wi++) {
      const m = mapOf(wi);
      const w = m.world;
      const full = rgbaOf((c) => m.drawTerrain(c));
      m.world = { ...w, terrain: w.terrain.map((r) => r.replace(bare, '.')) };
      const flat = rgbaOf((c) => m.drawTerrain(c));
      m.world = w;
      const scenery = new Uint8Array(320 * 240);
      for (let i = 0; i < scenery.length; i++) {
        if (full[i * 4] !== flat[i * 4] || full[i * 4 + 1] !== flat[i * 4 + 1]
          || full[i * 4 + 2] !== flat[i * 4 + 2]) scenery[i] = 1;
      }
      const path = inkOf((c) => m.drawLinks(c));
      const d = count(scenery) ? clearance(path, scenery) : 1 << 20;
      if (d < worstScenery.d) worstScenery = { d, id: w.id, px: count(scenery) };
    }
    expect('polun ja lähimmän kaluston väliin jää tyhjää joka maailmassa',
      worstScenery.d >= 4, `tiukin ${worstScenery.id}: ${worstScenery.d} px`);

    /*
     * Ja tässä se vastaesimerkki jonka takia sääntö raivaa myös naapuriruudut.
     * Kartta jossa vain polun omat ruudut ovat tyhjiä ja vuorijono seisoo rivin
     * ylä- ja alapuolella on täsmälleen se mitä heikompi sääntö sallisi.
     * Mitataan paljonko tilaa siihen jää — jos luku on sama kuin oikeilla
     * kartoilla, naapuriruutujen raivaaminen ei osta mitään ja sen voi perua.
     */
    const strip = {
      id: 'wS',
      name: 'KAISTA',
      theme: 'grass',
      terrain: [0, 1, 2, 3, 4, 5, 6, 7, 8]
        .map((r) => (r === 3 || r === 5 ? 'M'.repeat(20) : '.'.repeat(20))),
      nodes: [
        { id: 'p', tx: 2, ty: 4, type: 'start', name: 'A' },
        { id: 'q', tx: 14, ty: 4, type: 'level', level: '1-1', name: 'B' },
      ],
      links: [{ a: 'p', b: 'q' }],
    };
    const ms = mapOf(0);
    const keepW = ms.world;
    const keepR = ms.routeLinks;
    ms.routeLinks = new Map();
    ms.world = strip;
    const stripFull = rgbaOf((c) => ms.drawTerrain(c));
    ms.world = { ...strip, terrain: strip.terrain.map((r) => r.replace(bare, '.')) };
    const stripFlat = rgbaOf((c) => ms.drawTerrain(c));
    ms.world = strip;
    const stripPath = inkOf((c) => ms.drawLinks(c));
    ms.world = keepW;
    ms.routeLinks = keepR;
    const stripScenery = new Uint8Array(320 * 240);
    for (let i = 0; i < stripScenery.length; i++) {
      if (stripFull[i * 4] !== stripFlat[i * 4] || stripFull[i * 4 + 1] !== stripFlat[i * 4 + 1]
        || stripFull[i * 4 + 2] !== stripFlat[i * 4 + 2]) stripScenery[i] = 1;
    }
    const weak = clearance(stripPath, stripScenery);
    expect('pelkkien polkuruutujen raivaaminen ei olisi riittänyt',
      weak < worstScenery.d - 2,
      `vain polkuruudut ${weak} px, polkuruudut ja naapurit ${worstScenery.d} px`);

    /* Ja säännön pitää olla mahdoton rikkoa, ei vain rikkomatta jätetty. */
    const mkT = (terrain) => ({
      id: 'wT',
      name: 'TESTI',
      theme: 'grass',
      terrain: terrain.map((r) => r.padEnd(6, '.')),
      nodes: [
        { id: 's', tx: 0, ty: 1, type: 'start', name: 'ALKU' },
        { id: 'a', tx: 2, ty: 1, type: 'level', level: '1-1', name: 'A' },
        { id: 'f', tx: 4, ty: 1, type: 'fortress', level: '1-F', name: 'F' },
      ],
      links: [{ a: 's', b: 'a' }, { a: 'a', b: 'f' }],
    });
    const clean = mkT(['......', '......', '......', '...T..']);
    const onPath = mkT(['......', '.T....', '......', '......']);
    const beside = mkT(['...T..', '......', '......', '......']);
    const sceneryCases = [
      ['puhdas kartta', clean, false],
      ['puu polulla', onPath, true],
      ['puu polun vieressä', beside, true],
    ];
    const sceneryMissed = sceneryCases.filter(([, world, shouldFail]) =>
      worlds.worldProblems(world).some((p) => p.includes('polun')) !== shouldFail);
    expect('polulle istutettua puuta ei voi committoida',
      sceneryMissed.length === 0,
      sceneryMissed.map(([n]) => n).join(', ') || `${sceneryCases.length} tapausta`);

    /* --- 2. laatan sisällä on väljyyttä --- */

    /*
     * Numero, salaisuusmerkki ja vaikeuspalkki kilpailevat samasta ruudusta.
     * Mitataan ne erikseen väristä: selvitetyllä solmulla numero on #8fe04a,
     * löytymätön salaisuus #ffd048, laatan reunus #202038 ja palkin oma tausta
     * (16,14,20). Neljä eri väriä, joten jokainen osa saa oman maskin.
     */
    const plaqueNode = WORLDS[0].nodes.find((n) => n.level === '1-2');
    const mp = mapOf(0);
    mp.game.state.secrets = { '1-2': [] };      // viisi salaisuutta, yhtään ei löytynyt
    const w1 = mp.world;
    mp.world = { ...w1, nodes: [plaqueNode] };
    const plaque = rgbaOf((c) => mp.drawNodes(c));
    mp.world = w1;
    const gNum = hueOf(plaque, '#8fe04a');
    const gMark = hueOf(plaque, '#ffd048');
    const gEdge = hueOf(plaque, '#202038');
    /* Palkki on kolmea eri väriä: läpikuultava tausta, sammunut pykälä ja
     * palanut pykälä sen tason värissä. Ne ovat sama esine, joten sama maski. */
    const litPip = TIER_COLORS[worlds.nodePips(plaqueNode)];
    const gOff = hueOf(plaque, PIP_OFF);
    const gLit = hueOf(plaque, litPip);
    const gBar = new Uint8Array(320 * 240);
    for (let i = 0; i < gBar.length; i++) {
      const a = plaque[i * 4 + 3];
      if (gOff[i] || gLit[i] || (a > 100 && a < 250)) gBar[i] = 1;
    }
    const drawn = count(gNum) && count(gMark) && count(gEdge) && count(gBar);
    const gaps = {
      numMark: clearance(gNum, gMark),
      numEdge: clearance(gNum, gEdge),
      markEdge: clearance(gMark, gEdge),
      edgeBar: clearance(gEdge, gBar),
    };
    expect('laatan numero, salaisuusmerkki ja vaikeuspalkki eivät hengitä toistensa niskaan',
      !!drawn && Math.min(...Object.values(gaps)) >= 2,
      `numero-merkki ${gaps.numMark}, numero-reunus ${gaps.numEdge}, `
      + `merkki-reunus ${gaps.markEdge}, reunus-palkki ${gaps.edgeBar} px`);

    /* Väljyys maksaa tilaa, ja se hinta mitataan: kahden vierekkäisen solmun
     * piirrosten väliin pitää jäädä tyhjää, tai laatta on kasvanut naapurinsa
     * päälle. Tiukin pari kartalla on kaksi ruutua eli 32 px erillään. */
    let worstNodes = { d: 1 << 20 };
    let worstLinkNode = { d: 1 << 20 };
    let worstLinks = { d: 1 << 20 };
    for (let wi = 0; wi < WORLDS.length; wi++) {
      const m = mapOf(wi);
      const w = m.world;
      const keep = m.routeLinks;
      const nodeInk = w.nodes.map((n) => {
        m.world = { ...w, nodes: [n] };
        const ink = inkOf((c) => m.drawNodes(c));
        m.world = w;
        return ink;
      });
      const linkInk = w.links.map((l) => {
        m.world = { ...w, links: [l] };
        m.routeLinks = new Map();
        const ink = inkOf((c) => m.drawLinks(c));
        m.world = w;
        m.routeLinks = keep;
        return ink;
      });
      for (let i = 0; i < w.nodes.length; i++) {
        for (let j = i + 1; j < w.nodes.length; j++) {
          const d = clearance(nodeInk[i], nodeInk[j]);
          if (d < worstNodes.d) worstNodes = { d, id: `${w.nodes[i].id}/${w.nodes[j].id}` };
        }
        for (let k = 0; k < w.links.length; k++) {
          const l = w.links[k];
          if (l.a === w.nodes[i].id || l.b === w.nodes[i].id) continue;
          const d = clearance(nodeInk[i], linkInk[k]);
          if (d < worstLinkNode.d) worstLinkNode = { d, id: `${w.nodes[i].id}/${l.a}-${l.b}` };
        }
      }
      for (let i = 0; i < w.links.length; i++) {
        for (let j = i + 1; j < w.links.length; j++) {
          const A = w.links[i];
          const B = w.links[j];
          if (A.a === B.a || A.a === B.b || A.b === B.a || A.b === B.b) continue;
          const d = clearance(linkInk[i], linkInk[j]);
          if (d < worstLinks.d) worstLinks = { d, id: `${A.a}-${A.b} / ${B.a}-${B.b}` };
        }
      }
    }
    expect('kaksi solmua ei kasva kiinni toisiinsa',
      worstNodes.d >= 8, `tiukin ${worstNodes.id}: ${worstNodes.d} px`);
    expect('polku ei kulje sellaisen solmun läpi johon se ei liity',
      worstLinkNode.d >= 8, `tiukin ${worstLinkNode.id}: ${worstLinkNode.d} px`);
    expect('kaksi linkkiä joilla ei ole yhteistä solmua eivät kosketa',
      worstLinks.d >= 8, `tiukin ${worstLinks.id}: ${worstLinks.d} px`);

    /* --- 3. polut mutkittelevat, ja pelinappula kulkee samaa mutkaa --- */

    /*
     * Mutkan pitää olla datassa eikä piirtokoodissa, koska kaksi eri paikkaa
     * jotka laskevat "saman" mutkan eri kaavalla on juuri se ero jota DESIGN.md
     * 8 tarkoittaa: kuva ja liike kertoisivat eri tarinaa. Siksi tässä kysytään
     * käyrä `worlds.js`:ltä ja verrataan siihen sekä piirrosta että kävelyä.
     * Jos käyrää ei ole olemassa, tämä lukee suoran — ja mutkan mitta on 0.
     */
    const curveOf = (w, link) => (worlds.linkCurve
      ? worlds.linkCurve(w, link)
      : worlds.linkPoints(w, link).map((p) => ({ x: p.tx * 16 + 8, y: p.ty * 16 + 8 })));
    const segDist = (p, a, b) => {
      const vx = b.x - a.x;
      const vy = b.y - a.y;
      const L2 = vx * vx + vy * vy;
      const t = L2 ? Math.max(0, Math.min(1, ((p.x - a.x) * vx + (p.y - a.y) * vy) / L2)) : 0;
      return Math.hypot(p.x - (a.x + vx * t), p.y - (a.y + vy * t));
    };
    const polyDist = (p, line) => {
      let best = 1e9;
      for (let i = 0; i < line.length - 1; i++) best = Math.min(best, segDist(p, line[i], line[i + 1]));
      return best;
    };

    let bendMin = 1e9;
    let bendMax = 0;
    let offCurve = 0;
    for (const w of WORLDS) {
      for (const link of w.links) {
        const straight = worlds.linkPoints(w, link)
          .map((p) => ({ x: p.tx * 16 + 8, y: p.ty * 16 + 8 }));
        const curve = curveOf(w, link);
        let deep = 0;
        for (const p of curve) deep = Math.max(deep, polyDist(p, straight));
        bendMin = Math.min(bendMin, deep);
        bendMax = Math.max(bendMax, deep);
        /* Kävelijä kulkee tismalleen sitä samaa murtoviivaa. */
        reset();
        game.state.world = WORLDS.indexOf(w);
        game.state.node = link.a;
        game.state.cleared = Object.fromEntries(w.nodes.map((n) => [n.id, true]));
        const m = new WorldMapScene(game);
        const pts = worlds.linkPoints(w, link);
        const dx = Math.sign(pts[1].tx - pts[0].tx);
        const dy = Math.sign(pts[1].ty - pts[0].ty);
        m.mode = 'idle';
        m.tryMove(dx > 0 ? 'right' : dx < 0 ? 'left' : dy > 0 ? 'down' : 'up');
        if (m.mode === 'walk' && m.targetNode && m.targetNode.id === link.b) {
          for (let f = 0; f < 4000 && m.mode === 'walk'; f++) {
            offCurve = Math.max(offCurve, polyDist(m.pos, curve));
            m.update({
              pressed: blank(), held: blank(), released: blank(), consume() {},
            });
          }
        }
      }
    }
    expect('jokainen linkki mutkittelee, mutta pysyy omassa ruudussaan',
      bendMin >= 2 && bendMax <= 4,
      `pienin mutka ${bendMin.toFixed(1)} px, suurin ${bendMax.toFixed(1)} px `
      + `(ruudun keskeltä reunaan 8, pisteen puolikas 3)`);
    expect('kävelijä kulkee sitä mutkaa joka on piirretty',
      offCurve <= 0.5, `suurin poikkeama piirretystä käyrästä ${offCurve.toFixed(3)} px`);

    /*
     * JOKAISELTA SOLMULTA PÄÄSEE POIS JOLLAKIN NUOLELLA.
     *
     * Ylempi lohko ajaa jo `tryMove`n joka linkille — mutta se päättelee suunnan
     * linkin omasta askeleesta ja kääri tuloksen `if (m.mode === 'walk')`:iin.
     * Linkki jota **mikään nuoli ei osu** ei siis kaada mitään: `tryMove` palaa
     * hiljaa, `if` ei aukea, eikä yksikään väite jää kertomatta. Testi mittasi
     * mutkan syvyyden niistä linkeistä joita pitkin pääsi kulkemaan, ja oli
     * täysin sokea niille joita pitkin ei päässyt.
     *
     * Ja juuri se osui pelaajaan: `tryMove` vaatii että askeleen (dx, dy) on
     * tasan yksi nuolista, eli toisen komponentin on oltava nolla. Kun maailmat
     * 1 ja 3 kasvatettiin kahdeksaan kenttään, solmut aseteltiin siksakkiin
     * ilman kulmapistettä — jolloin joka linkin ensimmäinen askel on
     * **vinottain**, eikä yksikään nuoli osu siihen. Maailmassa 1 pääsi siis
     * ensimmäiselle kentälle ja siihen se loppui.
     *
     * Kaksi väitettä, koska kaksi eri tapaa mennä rikki:
     *   1. jokaiselta linkiltä, kummastakin päästä, JOKIN nuoli vie perille
     *   2. eikä kaksi linkkiä samalta solmulta vaadi SAMAA nuolta — muuten
     *      "oikealle" tarkoittaisi kahta paikkaa ja valinta olisi kirjoitusjärjestys
     */
    const ARROWS = ['left', 'right', 'up', 'down'];
    const stranded = [];
    const collisions = [];
    let claimedTotal = 0;
    for (const w of WORLDS) {
      const claimed = new Map();
      for (const link of w.links) {
        for (const [from, to] of [[link.a, link.b], [link.b, link.a]]) {
          const hits = ARROWS.filter((arrow) => {
            reset();
            game.state.world = WORLDS.indexOf(w);
            game.state.node = from;
            game.state.cleared = Object.fromEntries(w.nodes.map((n) => [n.id, true]));
            const m = new WorldMapScene(game);
            m.mode = 'idle';
            m.tryMove(arrow);
            return m.mode === 'walk' && m.targetNode && m.targetNode.id === to;
          });
          if (!hits.length) {
            const pts = worlds.linkPoints(w, link);
            const head = link.a === from ? pts : [...pts].reverse();
            stranded.push(`${w.id} ${from}->${to} askel `
              + `(${Math.sign(head[1].tx - head[0].tx)},${Math.sign(head[1].ty - head[0].ty)})`);
          }
          for (const arrow of hits) {
            const key = `${from}|${arrow}`;
            if (claimed.has(key)) collisions.push(`${w.id} ${from} ${arrow}: ${claimed.get(key)} ja ${to}`);
            else { claimed.set(key, to); claimedTotal++; }
          }
        }
      }
    }
    const linkEnds = WORLDS.reduce((n, w) => n + w.links.length * 2, 0);
    expect('jokaiselta solmulta pääsee jokaista linkkiä pitkin jollakin nuolella',
      stranded.length === 0,
      stranded.length ? `${stranded.length}/${linkEnds} umpikujaa: ${stranded.join(', ')}`
        : `${linkEnds} linkinpäätä, kaikki nuolen päässä`);
    expect('kaksi linkkiä samalta solmulta ei vaadi samaa nuolta',
      collisions.length === 0,
      collisions.length ? collisions.join(' / ') : `${claimedTotal} suuntaa, ei päällekkäisyyksiä`);
  }

  /* ------------- kartta joka on näkymää leveämpi, ja sen kamera ------------ */
  /*
   * KAHDEKSAN KENTTÄÄ EI MAHDU KAHTEENKYMMENEEN SARAKKEESEEN.
   *
   * Kartan ruudukko on ollut tasan näkymän kokoinen (20x9 laattaa = 320x144 px),
   * joten se ei ole koskaan joutunut vierimään. Kahdeksan solmua, niiden polut
   * ja säännön 8 raivaama väljyys eivät mahdu kahteenkymmeneen sarakkeeseen, eli
   * ruudukon on saatava olla näkymää leveämpi ja näkymän on seurattava nappulaa.
   *
   * Testimaailma eikä levennetty oikea maailma, kahdesta syystä. Toinen on
   * työnjako — maailmadata on toisen käsissä juuri nyt — ja toinen on että
   * *kuvitteellinen* leveä maailma on parempi testi kuin oikea: se saa olla
   * 30 saraketta leveä ja siinä saa olla solmu kohdassa 25, eli kaukana sen
   * takana mihin näkymä yltää, ilman että kukaan joutuu pelaamaan sitä.
   *
   * Punainen ennen vihreää (DESIGN.md 7). Ennen korjausta nämä sanoivat:
   *   - kaukainen solmu ei piirtynyt lainkaan: 0 pikseliä mustetta, kun leima
   *     on kohdassa x=400..419 ja näkymä on 0..319
   *   - nappula käveli ulos ruudusta: suurin x näkymässä 456 px (raja 320)
   *   - näkymän ulkopuolinen solmu ja linkki piirrettiin silti: 14 ja 20
   *     fillRect-kutsua, jokainen kokonaan ruudun ulkopuolelle
   *   - kaksinkertaisen levyinen maasto maksoi kaksinkertaisesti: 918 vs 1794
   *     fillRect-kutsua samasta näkymästä
   *   - leima ei liikkunut vieritettäessä: vasen reuna pysyi x=207:ssä kun sen
   *     olisi pitänyt olla 47
   */
  {
    const worlds = await import('/src/data/worlds.js');
    const { WorldMapScene } = await import('/src/scenes/worldmap.js');
    const cv = document.createElement('canvas');
    cv.width = 320;
    cv.height = 240;
    const g = cv.getContext('2d');

    /*
     * Laskuri piirtokutsuille. Kello on huono mittari portissa — se heittelee
     * koneen mukaan ja punainen joka johtuu naapuriprosessista ei ole punainen —
     * mutta `fillRect`-kutsujen määrä on täsmälleen sama joka ajolla ja mittaa
     * sitä samaa asiaa: montako laattaa, solmua ja pistettä koodi vaivautui
     * piirtämään. Kellotettu luku on raportissa, tämä on portissa.
     */
    const counting = (target) => {
      let n = 0;
      const ctx = new Proxy(target, {
        get(o, k) {
          const v = o[k];
          if (typeof v !== 'function') return v;
          if (k === 'fillRect') return (...a) => { n++; return v.apply(o, a); };
          return v.bind(o);
        },
        set(o, k, v) { o[k] = v; return true; },
      });
      return { ctx, calls: () => n };
    };

    /*
     * PITKÄ LAAKSO: 30 saraketta, kahdeksan kenttää, linnake sarakkeessa 28.
     * Kalusto on riveillä 0, 7 ja 8, eli säännön 8 raivaaman käytävän (rivit
     * 1..6) ulkopuolella — testimaailmakin on maailma, ja rikkinäinen maailma
     * mittaisi rikkinäisyyttään eikä vierimistä.
     */
    const WIDE = {
      id: 'wL',
      name: 'PITKA LAAKSO',
      theme: 'grass',
      terrain: [
        'T..T...T..T...T..T...T..T...T.',
        '..............................',
        '..............................',
        '..............................',
        '..............................',
        '..............................',
        '..............................',
        '.T...T...T...T...T...T...T...T',
        'T..T...T..T...T..T...T..T...T.',
      ],
      nodes: [
        { id: 'wL-s', tx: 1, ty: 4, type: 'start', name: 'ALKU' },
        { id: 'wL-1', tx: 4, ty: 4, type: 'level', level: '1-1', name: 'YKSI' },
        { id: 'wL-2', tx: 7, ty: 2, type: 'level', level: '1-2', name: 'KAKSI' },
        { id: 'wL-3', tx: 10, ty: 5, type: 'level', level: '1-3', name: 'KOLME' },
        { id: 'wL-4', tx: 13, ty: 2, type: 'level', level: '2-1', name: 'NELJA' },
        { id: 'wL-5', tx: 16, ty: 5, type: 'level', level: '2-2', name: 'VIISI' },
        { id: 'wL-6', tx: 19, ty: 2, type: 'level', level: '2-3', name: 'KUUSI' },
        { id: 'wL-7', tx: 22, ty: 5, type: 'level', level: '3-1', name: 'SEITSEMAN' },
        { id: 'wL-8', tx: 25, ty: 2, type: 'level', level: '3-2', name: 'KAHDEKSAN' },
        { id: 'wL-f', tx: 28, ty: 4, type: 'fortress', level: '1-F', name: 'LINNAKE' },
      ],
      links: [
        { a: 'wL-s', b: 'wL-1' },
        { a: 'wL-1', b: 'wL-2', path: [[7, 4]] },
        { a: 'wL-2', b: 'wL-3', path: [[10, 2]] },
        { a: 'wL-3', b: 'wL-4', path: [[13, 5]] },
        { a: 'wL-4', b: 'wL-5', path: [[16, 2]] },
        { a: 'wL-5', b: 'wL-6', path: [[19, 5]] },
        { a: 'wL-6', b: 'wL-7', path: [[22, 2]] },
        { a: 'wL-7', b: 'wL-8', path: [[25, 5]] },
        { a: 'wL-8', b: 'wL-f', path: [[28, 2]] },
      ],
    };

    expect('leveä testimaailma on itsekin kelvollinen kartta',
      worlds.worldProblems(WIDE).length === 0, worlds.worldProblems(WIDE).join(' / '));

    /* Kohtaus osoitetaan testimaailmaan käsin sen sijaan että se työnnettäisiin
     * `WORLDS`iin: taulukkoa kiertävät kaikki tämän tiedoston muut karttatestit,
     * ja globaalia listaa mutatoiva testi rikkoisi ne. */
    const keepPersist = game.persist.bind(game);
    game.persist = () => {};
    const wideAt = (nodeId) => {
      reset();
      game.state.cleared = Object.fromEntries(WIDE.nodes.map((n) => [n.id, true]));
      const m = new WorldMapScene(game);
      m.world = WIDE;
      m.routeLinks = new Map();
      m.node = worlds.findNode(WIDE, nodeId);
      m.pos = { x: m.node.tx * 16 + 8, y: m.node.ty * 16 + 8 };
      m.mode = 'idle';
      m.tick = 30;
      if (m.snapCamera) m.snapCamera();
      return m;
    };
    const camOf = (m) => (m.camX ? m.camX() : 0);
    const inkOf2 = (paint) => {
      g.clearRect(0, 0, 320, 240);
      paint(g);
      const d = g.getImageData(0, 0, 320, 240).data;
      let n = 0;
      for (let i = 3; i < d.length; i += 4) if (d[i] > 8) n++;
      return n;
    };
    /** Piirretyn musteen vasen reuna, tai -1 jos mustetta ei ole. */
    const leftEdge = (paint) => {
      g.clearRect(0, 0, 320, 240);
      paint(g);
      const d = g.getImageData(0, 0, 320, 240).data;
      for (let x = 0; x < 320; x++) {
        for (let y = 0; y < 240; y++) if (d[(y * 320 + x) * 4 + 3] > 8) return x;
      }
      return -1;
    };

    /* --- 1. kartan toinen pää on olemassa ruudulla --- */

    const far = worlds.findNode(WIDE, 'wL-8');
    const mFar = wideAt('wL-8');
    const keepNodes = mFar.world;
    mFar.world = { ...WIDE, nodes: [far] };
    const farInk = inkOf2((c) => mFar.drawNodes(c));
    mFar.world = keepNodes;
    expect('kartan kaukaisin solmu näkyy kun sen päällä seisotaan',
      farInk > 0,
      `solmu wL-8 laattasarakkeessa ${far.tx} (x=${far.tx * 16}), näkymä `
      + `${camOf(mFar)}..${camOf(mFar) + 320}, mustetta ${farInk} px`);

    /* --- 2. nappula ei kävele ulos ruudusta --- */

    /* Koko matka alusta linnakkeeseen, joka linkki kerrallaan, ja nappulan
     * paikka näkymässä joka framella. Tämä on se testi joka kaatuu heti jos
     * kamera unohtuu jostain tilasta: kävelystä, saapumisesta tai lopusta. */
    const chain = ['wL-s', 'wL-1', 'wL-2', 'wL-3', 'wL-4', 'wL-5', 'wL-6', 'wL-7', 'wL-8', 'wL-f'];
    const mWalk = wideAt('wL-s');
    let minView = 1e9;
    let maxView = -1e9;
    let worstStep = 0;
    let reversals = 0;
    let arrived = 'wL-s';
    const idle = () => ({ pressed: blank(), held: blank(), released: blank(), consume() {} });
    for (let i = 0; i < chain.length - 1; i++) {
      const a = worlds.findNode(WIDE, chain[i]);
      const b = worlds.findNode(WIDE, chain[i + 1]);
      const dx = Math.sign((WIDE.links[i].path ? WIDE.links[i].path[0][0] : b.tx) - a.tx);
      const dy = Math.sign((WIDE.links[i].path ? WIDE.links[i].path[0][1] : b.ty) - a.ty);
      mWalk.mode = 'idle';
      mWalk.tryMove(dx > 0 ? 'right' : dx < 0 ? 'left' : dy > 0 ? 'down' : 'up');
      let prev = camOf(mWalk);
      let dir = 0;
      for (let f = 0; f < 4000 && mWalk.mode === 'walk'; f++) {
        mWalk.update(idle());
        const cam = camOf(mWalk);
        const view = mWalk.pos.x - cam;
        minView = Math.min(minView, view);
        maxView = Math.max(maxView, view);
        const step = cam - prev;
        worstStep = Math.max(worstStep, Math.abs(step));
        if (step && dir && Math.sign(step) !== dir) reversals++;
        if (step) dir = Math.sign(step);
        prev = cam;
      }
      arrived = mWalk.node.id;
    }
    expect('nappula pysyy ruudulla koko matkan kartan päästä päähän',
      arrived === 'wL-f' && minView >= 4 && maxView <= 316,
      `pääty ${arrived}, nappula näkymässä ${minView.toFixed(1)}..${maxView.toFixed(1)} px (0..320)`);

    /* --- 3. kamera ei tärise eikä ryntää --- */

    /* Nappula kulkee 1.4 px/frame, joten kameran on kuljettava korkeintaan
     * saman verran: sitä nopeampi liike olisi kameran omaa vauhtia eikä
     * seuraamista. Ja suunnanvaihto kesken yhden linkin on juuri se tärinä joka
     * syntyy kun mutka heiluttaa nappulan x:ää ja kamera seuraa heilahdusta. */
    expect('kamera seuraa nappulaa eikä liiku omin päin',
      worstStep <= 2 && reversals === 0,
      `pahin askel ${worstStep} px/frame (nappula 1.4), suunnanvaihtoja ${reversals}`);

    /* --- 4. näkymän ulkopuolista ei piirretä --- */

    const mCull = wideAt('wL-s');
    const nodeCull = counting(g);
    const keepW = mCull.world;
    mCull.world = { ...WIDE, nodes: [far] };
    g.clearRect(0, 0, 320, 240);
    mCull.drawNodes(nodeCull.ctx);
    const linkCull = counting(g);
    mCull.world = { ...WIDE, nodes: WIDE.nodes, links: [WIDE.links[8]] };
    mCull.drawLinks(linkCull.ctx);
    mCull.world = keepW;
    expect('näkymän ulkopuolelle jäävää solmua tai linkkiä ei piirretä lainkaan',
      nodeCull.calls() === 0 && linkCull.calls() === 0,
      `solmu wL-8 ${nodeCull.calls()} kutsua, linkki wL-8→wL-f ${linkCull.calls()} kutsua `
      + `(näkymä ${camOf(mCull)}..${camOf(mCull) + 320})`);

    /* Ja sama maastolle: kartan leventäminen ei saa maksaa mitään, koska
     * näkymä on yhtä leveä kuin ennenkin. Sama kartta kahtena levyisenä, sama
     * näkymä, ja piirtokutsujen pitää olla luku luvulta sama. */
    const mTer = wideAt('wL-s');
    const narrow = counting(g);
    g.clearRect(0, 0, 320, 240);
    mTer.drawTerrain(narrow.ctx);
    const doubled = counting(g);
    mTer.world = { ...WIDE, terrain: WIDE.terrain.map((r) => r + r) };
    g.clearRect(0, 0, 320, 240);
    mTer.drawTerrain(doubled.ctx);
    mTer.world = WIDE;
    expect('kaksi kertaa leveämpi maasto ei maksa piirtoaikaa yhtään enempää',
      narrow.calls() === doubled.calls() && narrow.calls() > 0,
      `30 saraketta ${narrow.calls()} fillRect, 60 saraketta ${doubled.calls()}`);

    /* --- 5. leima mitataan vieritettynäkin oikein --- */

    /*
     * Laatan sisäiset raot mitattiin tänään pikseleistä (2 px joka saumaan) ja
     * ne ovat portti. Vieritys ei saa muuttaa niitä — ja se muuttaisi, jos
     * kameran siirtymä olisi murtoluku: puolen pikselin translaatio pehmentäisi
     * jokaisen reunan ja mitatut raot kutistuisivat sitä myöten. Siksi tässä
     * mitataan sama leima neljästä eri vierityksestä ja vaaditaan sekä että
     * se on *liikkunut* oikeaan kohtaan että että se on mitattavissa samana.
     */
    const stamp = worlds.findNode(WIDE, 'wL-4');
    const stampInk = (m) => {
      const keep = m.world;
      m.world = { ...WIDE, nodes: [stamp] };
      const out = { left: leftEdge((c) => m.drawNodes(c)), ink: inkOf2((c) => m.drawNodes(c)) };
      m.world = keep;
      return out;
    };
    /* Mitta on suhteellinen eikä ennustettu: leiman vasen reuna on vaikeuspalkin
     * tumma reunus kaksi pikseliä ruudun vasemmalta puolen, ja sen absoluuttinen
     * arvo on `drawPips`in asia. Väite on että se *siirtyy* vierityksen verran ja
     * että mustetta on yhtä paljon — eli leima liikkui eikä sumentunut. */
    const base = stampInk(wideAt('wL-s'));
    const edges = [];
    const inks = [];
    for (const scroll of [0, 37, 96, 160]) {
      const m = wideAt('wL-s');
      m.scroll = scroll;
      const got = stampInk(m);
      edges.push(`${got.left}/${base.left - camOf(m)}`);
      inks.push(got.ink);
    }
    expect('solmun leima liikkuu vierityksen mukana ja mittautuu samana',
      edges.every((e) => e.split('/')[0] === e.split('/')[1])
      && new Set(inks).size === 1 && base.ink > 0,
      `vasen reuna (mitattu/odotettu) ${edges.join(' ')}, mustetta ${inks.join('/')} px`);

    /* --- 6. ja kaikki tämä on nolla-muutos kapealle kartalle --- */

    /*
     * Jokainen laivattu maailma on yhä 20 laattaa leveä eli tasan näkymän
     * kokoinen, joten kameran pitää olla nollassa joka framella: alussa, joka
     * solmulla ja keskellä kävelyä. Se on se väite jonka nojalla kapean kartan
     * kuva on pikselilleen sama kuin ennen — siirtymä on 0, eikä 0 px:n
     * translaatio muuta yhtään pikseliä.
     */
    let drift = 0;
    let widest = 0;
    for (let wi = 0; wi < WORLDS.length; wi++) {
      const w = WORLDS[wi];
      widest = Math.max(widest, WorldMapScene.mapWidthPx ? WorldMapScene.mapWidthPx(w) : 320);
      for (const link of w.links) {
        reset();
        game.state.world = wi;
        game.state.node = link.a;
        game.state.cleared = Object.fromEntries(w.nodes.map((n) => [n.id, true]));
        const m = new WorldMapScene(game);
        drift = Math.max(drift, Math.abs(camOf(m)));
        const pts = worlds.linkPoints(w, link);
        m.mode = 'idle';
        m.tryMove(Math.sign(pts[1].tx - pts[0].tx) > 0 ? 'right'
          : Math.sign(pts[1].tx - pts[0].tx) < 0 ? 'left'
            : Math.sign(pts[1].ty - pts[0].ty) > 0 ? 'down' : 'up');
        for (let f = 0; f < 4000 && m.mode === 'walk'; f++) {
          m.update(idle());
          drift = Math.max(drift, Math.abs(camOf(m)));
        }
      }
    }
    expect('kapea kartta ei vieri pikseliäkään, eli sen kuva on ennallaan',
      drift === 0 && widest === 320,
      `suurin siirtymä ${drift} px, levein laivattu kartta ${widest} px (näkymä 320)`);

    game.persist = keepPersist;
  }

  /* Standing still on solid ground must read as grounded on EVERY frame. If it
   * flickers, jumps silently vanish: the press lands on a frame where the game
   * thinks the player is in mid-air. */
  {
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-1');
    const i = mkInput();
    for (let f = 0; f < 30; f++) s.update(i);        // settle on the floor
    let airborne = 0;
    for (let f = 0; f < 60; f++) {
      s.update(i);
      if (!s.player.onGround) airborne++;
    }
    expect('standing on the ground reads as grounded every frame',
      airborne === 0, `${airborne}/60 frames airborne while standing still`);

    // ...and the player must not sink and pop back either: that reads on screen
    // as the character vibrating even when the game says it is grounded.
    const heights = new Set();
    for (let f = 0; f < 60; f++) { s.update(i); heights.add(Math.round(s.player.y * 100)); }
    expect('a standing player does not drift up and down',
      heights.size === 1, `${heights.size} eri y-arvoa paikallaan seistessä`);

    // And a jump has to fire on any frame the player asks for one.
    let missed = 0;
    for (let attempt = 0; attempt < 12; attempt++) {
      for (let f = 0; f < 24; f++) { s.update(i); i.pressed = blank(); }
      i.pressed.jump = true; i.held.jump = true;
      s.update(i);
      i.pressed = blank();
      if (s.player.vy >= 0) missed++;
      i.held.jump = false;
    }
    expect('every jump press launches a jump', missed === 0, `${missed}/12 presses ignored`);
  }

  /* Running past the boss must not delete it. The fortress door only opens on
   * `bossDefeated`, so a despawned boss is an unwinnable level.
   *
   * KAADETTU POMO EI OLE KADONNUT POMO (10.8.2026). Tämä testi ei osannut
   * erottaa niitä toisistaan, ja se paljastui vasta kun 1-F:n palikat
   * vaihtuivat: uudella käytävällä sokeasti oikealle juokseva pelaaja ehtii
   * tallata pomon framella 1310, ja `Boss.stomp` antaa kaadetulle `noclip`in ja
   * pudottaa sen ruudun ali — eli **voittoanimaatio täytti tarkalleen sen
   * ehdon jolla testi tunnisti karanneen pomon**, `boss.y > heightPx`.
   *
   * Ehto oli väärä eikä kenttä, ja väitteessä oli sen todiste: `!s.bossDefeated
   * === !s.bossDefeated` on aina tosi, eli rivi näytti tarkistavan voiton
   * mutta ei tarkistanut mitään. Väite on nyt se mitä se on aina yrittänyt
   * sanoa — **pomo ei saa kadota elossa**, ja kaatuminen on hyväksytty
   * lopputulos. Se kaataa yhä alkuperäisen vian: karkaava pomo katoaa
   * `bossDefeated`in ollessa epätosi.
   */
  {
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-F');
    game.setScene(s);
    const boss = s.entities.find((e) => e.constructor.name === 'Boss');
    const i = mkInput();
    // Put the player at the far end of the arena, where the door is, and let
    // the camera settle there — the boss is now way behind.
    // Run the level the way a player does. The boss chases, so it will follow
    // the player out of its arena if nothing stops it.
    i.held.right = true;
    i.held.run = true;
    let lost = null;
    for (let f = 0; f < 1500; f++) {
      i.pressed = blank();
      if (f % 35 === 0) { i.pressed.jump = true; i.held.jump = true; } else if (f % 35 > 12) i.held.jump = false;
      s.player.invuln = Math.max(s.player.invuln, 4);      // survive long enough to watch
      s.update(i);
      if (!lost && !s.bossDefeated
        && (!s.entities.includes(boss) || boss.remove || boss.y > s.heightPx)) {
        lost = { f, x: Math.round(boss.x), y: Math.round(boss.y), hp: boss.hp };
      }
    }
    expect('the boss cannot leave its arena and fall out of the level',
      !lost && (s.entities.includes(boss) || !!s.bossDefeated),
      lost ? `pomo katosi framella ${lost.f} kohdassa ${lost.x},${lost.y} hp ${lost.hp}`
        : `1500 framea, pomo ${s.bossDefeated ? 'kaadettu' : 'elossa'}`);

    /* The save state has to bring the boss back too, or the door never opens.
     * Oma kohtauksensa eikä edellisen jäännös: tallennus jossa pomo on jo
     * kaadettu ei voi väittää mitään pomon palaamisesta. */
    reset({ type: 'shroom', level: 1 });
    const sSave = new LevelScene(game, '1-F');
    game.setScene(sSave);
    game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-f');
    game.slot = 2;
    game.quickSave();
    game.quickLoad();
    const after = game.scene;
    const bossBack = after.entities.filter((e) => e.constructor.name === 'Boss').length;
    expect('a save state in the fortress keeps the boss',
      bossBack === 1 && after.entities.length > 0,
      `${bossBack} pomoa, ${after.entities.length} entiteettiä`);

    // And with the boss down, the door has to actually let you out.
    reset({ type: 'shroom', level: 1 });
    const s2 = new LevelScene(game, '1-F');
    game.setScene(s2);
    s2.bossDefeated = true;
    let finished = null;
    game.finishLevel = (r) => { finished = r; };
    const door = [];
    for (let ty = 0; ty < s2.h; ty++) {
      for (let tx = 0; tx < s2.w; tx++) if (s2.grid[ty][tx] === 'D') door.push({ tx, ty });
    }
    if (door.length) {
      s2.player.x = door[0].tx * 16;
      s2.player.y = door[0].ty * 16;
      // 300 and not 200: going in is a walk now, and the clear sequence that
      // used to start on contact starts when the body is gone. See below. The
      // walk itself grew from 14 frames to 32 on 20.8.2026, when it became a
      // crossing of the whole doorway rather than a step into its near jamb.
      for (let f = 0; f < 300 && !finished; f++) { s2.update(i); i.pressed = blank(); }
    }
    /* The door is several tiles now — big enough that the largest power level
     * walks through it rather than steps over it — so what matters is that it
     * exists, that it is tall enough for that player, and that touching it
     * ends the level. */
    const doorH = door.length ? Math.max(...door.map((d) => d.ty))
      - Math.min(...door.map((d) => d.ty)) + 1 : 0;
    expect('the fortress door opens once the boss is beaten',
      door.length > 0 && doorH * 16 >= 43 && !!finished && finished.cleared,
      `${door.length} ruutua, ${doorH} korkea, finished ${JSON.stringify(finished)}`);

    /*
     * Red before green (DESIGN.md §7) for the three ways the door did not work.
     *
     * 1. It never opened. `drawDoor` took an `open` parameter and spent it on a
     *    blinking handle and a faint halo — the leaves themselves never moved,
     *    so the one promise the whole fortress is built around was plumbed all
     *    the way to the drawing code and dropped there.
     * 2. Touching it ended the level on the same frame, and `completeLevel`
     *    sets `autoWalk`, so the player walked *past* the door he had just
     *    finished the game by entering.
     * 3. `TILE_INFO`'s `door` flag was read nowhere.
     */
    {
      const { drawTile } = await import('/src/gfx/tiles.js');
      reset({ type: 'shroom', level: 1 });
      const s3 = new LevelScene(game, '1-F');
      // The boss is not what this is about.
      s3.entities = s3.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s3.time = 9999;
      s3.clockStopped = true;
      game.setScene(s3);
      let done = null;
      game.finishLevel = (r) => { done = r; };

      // The swing is a picture, so it is measured as one. Three moments of the
      // same door tile have to be three different pictures.
      const shots = [0, 0.5, 1].map((o) => {
        const c = document.createElement('canvas');
        c.width = 16; c.height = 16;
        const g = c.getContext('2d');
        g.imageSmoothingEnabled = false;
        g.fillStyle = '#000';
        g.fillRect(0, 0, 16, 16);
        drawTile(g, 'D', 0, 0, 'fortress', 4, 6, 0,
          ' ', { doorOpen: o, doorEdges: { l: true, r: false, t: false, b: false } });
        return [...g.getImageData(0, 0, 16, 16).data].join(',');
      });
      expect('the fortress door visibly swings instead of only glowing',
        shots[0] !== shots[1] && shots[1] !== shots[2] && shots[0] !== shots[2],
        `kiinni=puoliauki ${shots[0] === shots[1]}, puoliauki=auki ${shots[1] === shots[2]}`);

      // A door that has only just been unlocked is not a door you can walk
      // into: the leaves are still moving.
      s3.bossDefeated = s3.tick + 1;
      const shut = s3.doorOpen;
      for (let f = 0; f < 40; f++) s3.tick++;
      expect('the door takes a moment to swing and then stays open',
        shut < 0.2 && s3.doorOpen === 1, `${shut} -> ${s3.doorOpen}`);

      // Walking in: the level must not end on contact, the body must go out of
      // sight, and the clear sequence must land on the frame it does.
      const cells = [];
      for (let ty = 0; ty < s3.h; ty++) {
        for (let tx = 0; tx < s3.w; tx++) if (s3.grid[ty][tx] === 'D') cells.push({ tx, ty });
      }
      const left = Math.min(...cells.map((c) => c.tx));
      const bottom = Math.max(...cells.map((c) => c.ty));
      s3.player.x = left * 16 - s3.player.w + 2;
      s3.player.y = (bottom + 1) * 16 - s3.player.h;
      s3.player.onGround = true;
      s3.centerCamera();
      const walk = mkInput();
      walk.held.right = true;
      let contactAt = -1;
      let clearAt = -1;
      let hidden = 0;
      for (let f = 0; f < 120 && clearAt < 0; f++) {
        walk.pressed = blank();
        s3.update(walk);
        if (contactAt < 0 && s3.player.transit) contactAt = f;
        if (s3.player.transit && s3.player.transit.phase === 'hold') hidden++;
        if (s3.state === 'clear' && clearAt < 0) clearAt = f;
      }
      /* The body is drawn clipped to the near side of `transit.hide`, so by the
       * end of the walk-in it is entirely on the far side of that line — which
       * is what "the player disappears" means when tiles draw before entities
       * and there is no depth buffer.
       *
       * Still 'gone' after the level has cleared, and still on the far side of
       * the line it disappeared behind: `completeLevel` sets `autoWalk`, and a
       * player who reappeared and strolled back out of the door would be the
       * original complaint with an animation in front of it. */
      const t = s3.player.transit;
      const gone = !!t && t.phase === 'gone'
        && (t.hideDir > 0 ? s3.player.x >= t.hide : s3.player.x + s3.player.w <= t.hide);
      let strolled = 0;
      const x0 = s3.player.x;
      for (let f = 0; f < 60; f++) { s3.update(walk); walk.pressed = blank(); }
      strolled = Math.abs(s3.player.x - x0);
      expect('walking into the door takes the player in before the level ends',
        contactAt >= 0 && clearAt > contactAt + 10 && hidden >= 3
        && s3.state === 'clear' && gone && strolled < 0.001,
        `kosketus ${contactAt}, selvä ${clearAt}, piilossa ${hidden} framea, `
        + `poissa ${gone}, käveli vielä ${strolled.toFixed(1)} px`);
      /* And where the clear sequence sits: on the frame the body is gone, not
       * on the frame it touched the door. Measured 20.8.2026: 32 frames of
       * walking across the doorway plus 5 of empty doorway, so 36 from contact
       * (the window used to be 15…25, for a 14-frame step into the near jamb —
       * widened here honestly, because the walk-in got longer on purpose and
       * not because the assertion was wrong). It is still a window, because
       * the exact number is a tuning constant and the ordering is the
       * decision. */
      expect('and the clear jingle waits for the picture, not the other way round',
        contactAt >= 0 && clearAt - contactAt >= 30 && clearAt - contactAt <= 45
        && done === null,
        `kosketuksesta selväksi ${clearAt - contactAt} framea, finished ${JSON.stringify(done)}`);

      /*
       * WHERE HE GOES BEHIND THE DOOR, MEASURED IN PIXELS.
       *
       * Omistaja, 20.8.2026: *"make sure they seem to ENTER the door, ie. go
       * behind it only AFTER they start hitting the right border of the
       * door."* Red before green: the clip line used to be `p.x + p.w` on the
       * frame of contact, and this check measured the old code losing its
       * first pixels **on frame 0 at x 2755.3** — 3 px past the near jamb of a
       * doorway that runs 2752…2784, i.e. at the wrong end of the door and
       * before the walk had started. Green: frame 18, x 2782.5.
       *
       * Measured from rendered pixels rather than from the transit's fields,
       * because the claim is about the picture: paint the frame, paint it
       * again with the player suppressed, and the pixels that differ are the
       * body as the screen actually shows it. A third paint with `hide` lifted
       * gives what an unclipped body would have covered, so "is he whole" is a
       * comparison of two numbers from the same frame and needs no reference
       * image.
       *
       * And it is the door's border and not a frame number: the same walk is
       * run twice from two different starting distances, and the assertion is
       * that the flip lands on the same **x** while landing on a different
       * **frame**. A fixed-frame implementation passes the first half of that
       * and fails the second.
       */
      const doorRun = (backOff) => {
        reset({ type: 'shroom', level: 1 });
        const s4 = new LevelScene(game, '1-F');
        s4.entities = s4.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s4.time = 9999;
        s4.clockStopped = true;
        game.setScene(s4);
        game.finishLevel = () => {};
        s4.bossDefeated = s4.tick + 1;
        for (let f = 0; f < 40; f++) s4.tick++;      // let the leaves finish swinging
        const px = [];
        for (let ty = 0; ty < s4.h; ty++) {
          for (let tx = 0; tx < s4.w; tx++) if (s4.grid[ty][tx] === 'D') px.push({ tx, ty });
        }
        const l = Math.min(...px.map((c) => c.tx));
        const r = Math.max(...px.map((c) => c.tx));
        const bot = Math.max(...px.map((c) => c.ty));
        const p = s4.player;
        p.x = l * 16 - p.w + 2 - backOff;
        p.y = (bot + 1) * 16 - p.h;
        p.onGround = true;
        s4.centerCamera();
        const go = mkInput();
        go.held.right = true;
        const canvas = document.createElement('canvas');
        canvas.width = 320;
        canvas.height = 240;
        const g = canvas.getContext('2d');
        const paint = () => {
          g.clearRect(0, 0, 320, 240);
          s4.draw(g);
          return g.getImageData(0, 0, 320, 240).data;
        };
        const differing = (a, b) => {
          let n = 0;
          for (let q = 0; q < a.length; q += 4) {
            if (a[q] !== b[q] || a[q + 1] !== b[q + 1] || a[q + 2] !== b[q + 2]) n++;
          }
          return n;
        };
        const realDraw = s4.drawPlayerInto.bind(s4);
        const out = {
          doorR: (r + 1) * 16, flipAt: -1, flipNose: 0, wholeUntil: -1, endVisible: -1,
        };
        for (let f = 0; f < 160 && s4.state !== 'clear'; f++) {
          go.pressed = blank();
          s4.update(go);
          const t = p.transit;
          const shown = paint();
          s4.drawPlayerInto = () => {};
          const bare = paint();
          s4.drawPlayerInto = realDraw;
          const visible = differing(shown, bare);
          let whole = visible;
          if (t && t.hide !== null && t.hide !== undefined) {
            const keep = t.hide;
            t.hide = null;
            whole = differing(paint(), bare);
            t.hide = keep;
          }
          if (out.flipAt < 0 && visible < whole) {
            out.flipAt = f;
            /* The sprite is allowed to overhang its 14 px box by a pixel, so
             * the border is crossed by the *drawing* a frame before the box
             * reaches it. Recording the box edge keeps the number readable;
             * the tolerance below is what pays for the overhang. */
            out.flipNose = p.x + p.w;
          } else if (out.flipAt < 0) out.wholeUntil = f;
          out.endVisible = visible;
        }
        return out;
      };
      const near = doorRun(0);
      const far = doorRun(12);
      const atBorder = (run) => Math.abs(run.flipNose - run.doorR) <= 2;
      expect('the body goes behind the door at its far border, not on contact',
        near.flipAt > 0 && atBorder(near) && near.wholeUntil === near.flipAt - 1
        && near.endVisible === 0,
        `flip framella ${near.flipAt} kohdassa ${near.flipNose.toFixed(1)}, `
        + `ovi ${near.doorR}, kokonaisena ${near.wholeUntil} asti, `
        + `lopussa ${near.endVisible} px näkyvissä`);
      expect('and it is the door that decides that, not the frame counter',
        far.flipAt > 0 && atBorder(far) && far.flipAt !== near.flipAt
        && Math.abs(far.flipNose - near.flipNose) <= 2,
        `12 px kauempaa: flip framella ${far.flipAt} (lähempää ${near.flipAt}), `
        + `kohdassa ${far.flipNose.toFixed(1)} (lähempää ${near.flipNose.toFixed(1)})`);
    }
  }

  /*
   * A CLEARED LEVEL ENDS WITH HIM OUT OF THE PICTURE.
   *
   * Omistaja, 20.8.2026: *"after a normal level, the character should walk out
   * the right hand side."*
   *
   * Red before green, measured on 1-1 before the change: the flagpole is at
   * x 5696, the level ends at 6112, and 170 frames after the grab the scene
   * cut with the body at x 5931 — **screen column 142 of 320**, dead centre,
   * 349 painted pixels of him still on the glass, walking on the spot. All
   * fifty flagpole levels failed this the same way. Two things stood in the
   * way and both are asserted here rather than remembered: the clear sequence
   * ended on a frame count that knew nothing about where he was, and `moveX`
   * treats every column past the grid as `T.HARD`, so the last 14 px of the
   * walk were into a wall that is not in any level's data.
   *
   * Every level with a flagpole is run, because "he leaves the frame" is a
   * claim about the *level's* last stretch — how much ground there is past the
   * goal, and whether it is walkable — and one level cannot answer it for
   * fifty. The fortresses have no flagpole and are the block above.
   */
  {
    const { VIEW_W } = await import('/src/scenes/level.js');
    const rows = [];
    for (const id of levelIds()) {
      reset({ type: 'shroom', level: 1 });
      const s = new LevelScene(game, id);
      if (!s.goal) continue;                     // fortress: its exit is a door
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      game.setScene(s);
      let fin = null;
      game.finishLevel = (r) => { fin = r; };
      const p = s.player;
      /* Stood at the pole's foot on whatever the level put under it, then
       * cleared outright: this measures the walk-out, and the climb to the
       * pole is `grabGoal`'s own business and its own check. */
      let ty = s.goal.ty;
      while (ty < s.h && !isSolid(s.tileAt(s.goal.tx, ty))) ty++;
      p.x = s.goal.x - 2;
      p.y = ty * 16 - p.h;
      p.vx = 0;
      p.vy = 0;
      p.onGround = true;
      s.centerCamera();
      s.completeLevel('star');
      const idle = mkInput();
      let f = 0;
      for (; f < 900 && !fin; f++) { idle.pressed = blank(); s.update(idle); }
      rows.push({
        id,
        f,
        cleared: !!fin && !!fin.cleared,
        // Not "he moved right" but "he is not in shot": the left edge of the
        // box past the right edge of the view, which is the only reading of
        // "walks out the right hand side" that a screenshot could confirm.
        out: p.x >= s.cam.x + VIEW_W,
        col: Math.round(p.x - s.cam.x),
      });
      game.finishLevel = () => {};
    }
    const stuck = rows.filter((r) => !r.cleared || !r.out);
    const slowest = rows.reduce((a, b) => (b.f > a.f ? b : a), rows[0] || { f: 0, id: '-' });
    expect('a cleared level ends with the player walked out of the view',
      rows.length > 20 && stuck.length === 0,
      stuck.length
        ? `${stuck.length}/${rows.length} jäi kuvaan: `
          + stuck.slice(0, 6).map((r) => `${r.id} sarake ${r.col} (${r.f} framea)`).join(', ')
        : `${rows.length} kenttää, pisin ${slowest.id} ${slowest.f} framea`);
    /* The fuse (`WALKOUT_MAX`) exists so a level whose ground ends at the goal
     * cannot hang the scene, and a fuse that fires in normal play is a fuse
     * that has become the rule. It burns at `CLEAR_HOLD` + 240 = 410 frames;
     * the longest real walk-out measured over the levels above is 320, so 400
     * is a ceiling that a genuine walk clears and the fuse does not. */
    expect('and the walk-out is a walk, not the safety fuse firing',
      rows.every((r) => r.f < 400),
      `pisin ${slowest.id} ${slowest.f} framea`);
    /* And the picture agrees with the number. 1-1 because that is the level
     * the complaint was measured on: it is where "he stops dead centre" was
     * read off the screen, so it is where "there is nothing of him left" has
     * to be read off it too. */
    {
      reset({ type: 'shroom', level: 1 });
      const s = new LevelScene(game, '1-1');
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      game.setScene(s);
      let fin = null;
      game.finishLevel = (r) => { fin = r; };
      const p = s.player;
      let ty = s.goal.ty;
      while (ty < s.h && !isSolid(s.tileAt(s.goal.tx, ty))) ty++;
      p.x = s.goal.x - 2;
      p.y = ty * 16 - p.h;
      p.onGround = true;
      s.centerCamera();
      s.completeLevel('star');
      const idle = mkInput();
      for (let f = 0; f < 900 && !fin; f++) { idle.pressed = blank(); s.update(idle); }
      const canvas = document.createElement('canvas');
      canvas.width = 320;
      canvas.height = 240;
      const g = canvas.getContext('2d');
      const paint = () => {
        g.clearRect(0, 0, 320, 240);
        s.draw(g);
        return g.getImageData(0, 0, 320, 240).data;
      };
      const shown = paint();
      const real = s.drawPlayerInto.bind(s);
      s.drawPlayerInto = () => {};
      const bare = paint();
      s.drawPlayerInto = real;
      let left = 0;
      for (let q = 0; q < shown.length; q += 4) {
        if (shown[q] !== bare[q] || shown[q + 1] !== bare[q + 1]
          || shown[q + 2] !== bare[q + 2]) left++;
      }
      expect('and on the last frame of 1-1 there is nothing of him left on screen',
        !!fin && fin.cleared && left === 0,
        `${left} px näkyvissä, x ${Math.round(p.x)}, kamera ${Math.round(s.cam.x)}`);
      game.finishLevel = () => {};
    }
  }

  /*
   * The jump budget must be reproducible from the engine that is in the tree.
   *
   * This is the one bug in this project's history that nothing could catch.
   * `tools/jump-budget.json` claimed a 121 px rise and a 200 px carry from the
   * commit that wrote it until 9.8.2026 — the physics change and the budget
   * file landed together and the budget was never re-measured, so the file was
   * wrong on arrival rather than gone stale. Nothing failed: the validator
   * reads the same file, so a too-generous budget makes every level *pass*, and
   * `difficulty.mjs` reads it too, so the curve looked fine as well. Both
   * gates were measuring against the claim instead of against the game.
   *
   * So this asserts the claim itself. It re-runs the two headline cases of
   * `measure-jump.mjs` — the standing held jump's rise and the running jump's
   * carry — and compares them with what the file says. It does NOT write the
   * file: `measure-jump.mjs` does that as a side effect, which is exactly why
   * a read-only check has to exist somewhere else.
   *
   * The tolerance is ±3 px. The measurement is deterministic (fixed 60 Hz
   * steps, no randomness), so anything beyond a rounding difference means the
   * constants moved and the file did not follow.
   */
  {
    const budget = await (await fetch('/tools/jump-budget.json')).json();
    const runway = (power) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      for (let y = 0; y < s.h - 2; y++) s.grid[y] = s.grid[y].map(() => ' ');
      for (let y = s.h - 2; y < s.h; y++) s.grid[y] = s.grid[y].map(() => '#');
      s.entities = s.entities.filter((e) => e.kind === 'player');
      s.goal = null;
      return s;
    };
    /** One held jump on clear floor; `runFrames` of held right first. */
    const arc = (runFrames, run) => {
      const s = runway({ type: 'shroom', level: 1 });
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 40; f++) { s.update(i); i.pressed = blank(); }
      i.held.right = runFrames > 0;
      i.held.run = run;
      for (let f = 0; f < runFrames; f++) { s.update(i); i.pressed = blank(); }
      const x0 = p.x; const y0 = p.y;
      let peak = 0; let air = 0;
      i.pressed.jump = true; i.held.jump = true;
      s.update(i); i.pressed = blank();
      while (air < 400) {
        air++;
        i.held.jump = p.vy < 0;
        s.update(i);
        i.pressed = blank();
        peak = Math.max(peak, y0 - p.y);
        if (p.onGround && air > 4) break;
      }
      return { pFull: p.pFull, height: Math.round(peak), distance: Math.round(p.x - x0) };
    };

    const stand = arc(0, false);
    const runJump = arc(90, true);
    const claimed = (label) => budget.cases.find((c) => c.label === label) || {};
    const near = (a, b) => Math.abs(a - b) <= 3;
    const standClaim = claimed('standing, held');
    const runClaim = claimed('running, held');
    expect('the stored jump budget is reproducible from the current physics',
      !runJump.pFull
      && near(stand.height, standClaim.height) && near(runJump.height, runClaim.height)
      && near(runJump.distance, runClaim.distance),
      `paikaltaan ${stand.height}px (tiedostossa ${standClaim.height}), `
      + `juosten ${runJump.height}px / ${runJump.distance}px `
      + `(tiedostossa ${runClaim.height} / ${runClaim.distance})`);

    /* And that the design budget the validator uses is the one those numbers
     * imply. Same formula and same margin as measure-jump.mjs — duplicated on
     * purpose, so that editing the file by hand is caught rather than blessed. */
    const gap = Math.max(3, Math.floor((runJump.distance * 0.7) / 16));
    const wall = Math.max(2, Math.floor((runJump.height * 0.8) / 16));
    expect('the design budget follows from the measured jump',
      budget.margin === 0.7 && budget.gapTiles === gap && budget.wallTiles === wall,
      `kuilu ${budget.gapTiles} (mitattu ${gap}), seinä ${budget.wallTiles} (mitattu ${wall})`);
  }

  /* The design rules, applied to EVERY level in the game rather than only the
   * generated ones. Worlds 1-4 predate the current jump budget, so their
   * violations are reported as a work list, not as a build failure. */
  {
    const { validateLevel } = await import('/src/data/rules.js');
    const { getLevel, levelIds } = await import('/src/data/levels.js');
    const budget = await (await fetch('/tools/jump-budget.json')).json();
    const perLevel = [];
    for (const id of levelIds()) {
      /* Akseli luetaan kentän omasta lipusta eikä ruudukon muodosta: korkea
       * kenttä on kolme huonetta päällekkäin ja pystykenttä on yksi korkea
       * huone, eikä ruudukko erota niitä. Ilman tätä `6-K` ja `7-T` luettaisiin
       * vaakasäännöillä, jotka lukevat rivin 13 ja raportoivat seitsemän
       * ongelmaa joista yksikään ei ole totta (mitattu koekentällä lohkossa
       * "PYSTYKENTTÄ, JA KOLME TYÖKALUA…"). */
      const level = getLevel(id);
      const problems = validateLevel(level.rows, budget,
        { vertical: !!level.vertical, segments: level.segments, gates: level.gates });
      if (problems.length) perLevel.push({ id, problems });
    }
    // Every level is clean as of v26.08.08.15, so any violation from here on is
    // a regression and fails the run — hand-made levels included.
    const generatedBad = perLevel;
    checks.push({
      name: 'design rules across every level',
      ok: generatedBad.length === 0,
      detail: perLevel.length
        ? `${perLevel.length}/${levelIds().length} kenttää rikkoo sääntöjä`
        : 'kaikki kentät sääntöjen mukaisia',
    });
    if (generatedBad.length) {
      failures.push(...generatedBad.flatMap((l) => l.problems.map((p) => `${l.id}: ${p}`)));
    }
    ruleReport = perLevel;

    /* The band split is load-bearing and silent when it breaks. Before it
     * existed, a 45-row level came back with zero problems — not because it was
     * sound, but because the rules read the sky band's empty floor rows, never
     * found ground, and never flushed the gap counter. Every geometry rule was
     * switched off and nothing said so. This asserts the one case that cannot
     * be guessed around: a tall level with no start marker is an error. */
    const tall = levelIds().map((id) => getLevel(id)).find((d) => d.rows.length > 16);
    if (tall) {
      const stripped = tall.rows.map((row) => row.replace('1', ' '));
      const problems = validateLevel(stripped, budget);
      expect('a tall level with no start marker is reported, not silently skipped',
        problems.some((p) => p.includes('no player start')), problems.slice(0, 2).join(' / '));
    }
    expect('at least one level is tall enough to have a hidden band', !!tall,
      tall ? `${tall.rows.length} riviä` : 'ei korkeita kenttiä');

    /* ---------------------------- vaikeustasot --------------------------- */
    /*
     * VAIKEUSTASOT, ks. `src/data/scale.js`.
     *
     * Kolme väitettä, ja ensimmäinen on niistä tärkein: **HELPPO on merkilleen
     * se peli joka datatiedostoissa lukee.** Kaikki mitattu — `difficulty.js`,
     * `curriculum.mjs`, `variety.mjs` ja jokainen tämän tiedoston 60 kentän
     * kierros — koskee sitä kenttää, joten jos oletustaso poikkeaisi siitä
     * yhdenkin merkin verran, jokainen niistä luvuista olisi mitattu kentästä
     * jota kukaan ei pelaa. Vertailu on tehty rivi riviltä eikä leveyksinä.
     *
     * Loput kaksi ovat se mitä venytys lupaa (`stretch`, `crowd`) ja se mitä se
     * ei saa rikkoa. Jälkimmäinen on lista koska juuri niin nämä viat
     * ilmenisivät: kaksi lippua, kadonnut aloitusruutu, nelinumeroinen kello
     * joka ei mahdu nauhaan, venynyt kiipeily, vihollinen seinän sisällä. Ne
     * ovat kaikki hiljaisia — peli käynnistyy ja näyttää oikealta.
     */
    {
      const { MODES } = await import('/src/data/scale.js');
      const foes = (rows) => (rows.join('').match(/[gkfprcxAOPH]/g) || []).length;
      const marks = (rows, re) => (rows.join('').match(re) || []).length;

      expect('HELPPO on merkilleen se kenttä joka datatiedostossa lukee',
        levelIds().every((id) => getLevel(id, 'easy').rows.join('\n') === getLevel(id).rows.join('\n')),
        `${levelIds().length} kenttää`);

      const broken = [];
      const shape = [];
      const savedMode = game.state.mode;
      for (const m of MODES) {
        let base = 0; let grown = 0; let crowdBase = 0; let crowd = 0;
        for (const id of levelIds()) {
          const b = getLevel(id);
          const l = getLevel(id, m.id);
          const say = (why) => broken.push(`${m.id} ${id}: ${why}`);
          /* Akseli kentän omasta lipusta, osiot mukana — sama kutsu kuin
           * "design rules across every level" -lohkossa yllä ja samasta syystä.
           * Ilman `segments`ia 7-P luetaan yhtenä vaakakenttänä, ja sen ensimmäinen
           * käänne mitataan kahdenkymmenen laatan kuiluna joka ei ole kuilu. */
          const problems = validateLevel(l.rows, budget,
            { vertical: !!l.vertical, segments: l.segments, gates: l.gates });
          if (problems.length) say(problems[0]);
          const starts = marks(l.rows, /1/g);
          const exits = marks(l.rows, /F/g) + marks(l.rows, /b/g);
          if (starts !== 1) say(`${starts} aloitusruutua`);
          if (exits !== 1) say(`${exits} uloskäyntiä`);
          if (!(l.time > 0) || l.time > 999) say(`kello ${l.time} ei mahdu nauhaan`);
          if (l.vertical && l.rows[0].length !== b.rows[0].length) say('kiipeily venyi');
          base += b.rows[0].length; grown += l.rows[0].length;
          crowdBase += foes(b.rows); crowd += foes(l.rows);

          /* Ja se rakentuu kohtaukseksi. Samat kaksi tarkistusta kuin tämän
           * tiedoston 60 kentän kierroksella, koska juuri ne kaksi ovat se mitä
           * ruudukon liittäminen väärästä kohdasta tuottaisi. */
          reset();
          game.state.mode = m.id;
          const scene = new LevelScene(game, id);
          const sx = Math.floor(scene.player.x / 16);
          const sy = Math.floor((scene.player.y + scene.player.h - 1) / 16);
          if (isSolid(scene.tileAt(sx, sy))) say('aloitus kiinteän laatan sisällä');
          const stuck = scene.entities.filter((e) => {
            if (e.constructor.name === 'Plant' || e.kind === 'hazard') return false;
            return isSolid(scene.tileAt(Math.floor(e.cx / 16), Math.floor((e.y + e.h - 1) / 16)));
          });
          if (stuck.length) say(`${stuck.length} vihollista seinän sisällä`);
        }
        shape.push({ id: m.id, stretch: grown / base, crowd: crowd / crowdBase });
      }
      game.state.mode = savedMode;

      expect('jokainen kenttä jokaisella vaikeustasolla on sääntöjen mukainen ja pelattavissa',
        broken.length === 0,
        broken.length ? broken.slice(0, 4).join(' / ') : `${MODES.length * levelIds().length} kenttää`);

      /* Toleranssi on ±10 %, ja se on venytyksen oma rakenne eikä löysyys:
       * pätkiä lisätään kokonaisina, joten tavoitteen viimeinen askel ylittää
       * sen aina yhden pätkän verran. Mitattu tälle datalle 2,03x ja 3,01x. */
      const wants = { easy: 1, normal: 2, hard: 3 };
      const off = shape.filter((r) => Math.abs(r.stretch - wants[r.id]) > wants[r.id] * 0.1);
      expect('venytys osuu siihen pituuteen jonka taso lupaa', off.length === 0,
        shape.map((r) => `${r.id} ${r.stretch.toFixed(2)}x`).join('  '));

      /* Vihollisia tulee lisää **enemmän kuin venytys yksin toisi**, eli
       * tiheys kasvaa. Ilman tätä ehtoa 3x pituus ja 3x vihollisia olisi
       * täsmälleen sama peli kolmesti, ja omistaja pyysi kahta asiaa. */
      const denser = shape.every((r) => (r.id === 'easy' ? r.crowd === 1 : r.crowd > r.stretch * 1.2));
      expect('vihollisia tulee tiheämpään eikä vain pidemmälle matkalle', denser,
        shape.map((r) => `${r.id} ${r.crowd.toFixed(2)}x vihollisia / ${r.stretch.toFixed(2)}x pituutta`).join('  '));
    }

    /* Red before green (DESIGN.md 7), for the two ways a hidden room turns into
     * a trap. Both are built here rather than borrowed from a real level,
     * because a rule proved only against content that happens to be correct is
     * a rule proved against nothing: the fixture is broken on purpose, one
     * fault at a time, and the same fixture with the fault taken out has to
     * come back silent.
     *
     * The shape is the shape every hidden area in the game has: a flat route
     * band with two warp pipes, a sealed room in the sky over one of them and a
     * sealed room in the cave under the other. Each room holds a power-up,
     * which is the whole reason the way out is measured at the tallest size —
     * you arrive small and you grow in there. */
    const tallFixture = ({ skyCeiling = 5, ledgeOverCaveExit = false } = {}) => {
      const W = 64;
      /* Kolme kaistaa, kuusitoista riviä kukin (18.8.2026, `SKY_PAD`): kaistojen
       * ylälaidat ovat 0, 16 ja 32, ja kaistan sisällä kaikki on siirtynyt
       * yhden rivin alaspäin. Luvut ovat tässä kirjoitettuina eivätkä
       * johdettuina, koska koekentän koko tehtävä on olla se ruudukko jonka
       * mitat on tarkistettu käsin. */
      const g = Array.from({ length: 48 }, () => ' '.repeat(W));
      const put = (y, x, s) => { g[y] = g[y].slice(0, x) + s + g[y].slice(x + s.length); };
      const room = (top, ceiling, left, width, floorChar) => {
        put(top + ceiling + 1, left, 'X'.repeat(width));
        for (let y = top + ceiling + 2; y <= top + 13; y++) {
          put(y, left, 'X'); put(y, left + width - 1, 'X');
        }
        put(top + 14, left, floorChar.repeat(width));
        put(top + 15, left, floorChar.repeat(width));
      };

      // Route band: flat ground, a start, a power-up inside the first quarter,
      // a flag, and the two warp pipes.
      put(30, 0, '#'.repeat(W)); put(31, 0, '#'.repeat(W));
      put(29, 2, '1');
      put(26, 8, '!');
      put(29, 60, 'F');
      put(29, 20, '()');   // down into the cave room: a pipe you stand on
      /* Up into the sky loft, and therefore a pipe that hangs. Row 26 is the
       * mouth because it leaves the three clear rows the tallest body needs
       * between it and the ground at row 30 — see `WARP_UP_REACH`. */
      put(26, 40, '()');
      for (let y = 20; y < 26; y++) put(y, 40, '{}');
      // The fault: two tiles of ground on the surface right over the cave
      // room's exit, so the warp back up has nowhere to put a 21x43 body.
      if (ledgeOverCaveExit) { put(28, 23, '####'); put(29, 23, '####'); }

      // Sky loft over the pipe at column 40. `skyCeiling` is its ceiling row:
      // 5 leaves the tallest size three clear rows over the floor, 10 leaves
      // two, which is the one-row-too-low fault.
      room(0, skyCeiling, 36, 14, '#');
      put(10, 42, '!');
      put(13, 46, '()');   // the way back down

      // Cave room under the pipe at column 20. The way back up hangs from its
      // ceiling, three clear rows over the floor at row 46.
      room(32, 5, 14, 14, 'X');
      put(42, 18, '!');
      for (let y = 39; y < 42; y++) put(y, 24, '{}');
      put(42, 24, '()');   // the way back up
      return g;
    };

    const sound = validateLevel(tallFixture(), budget);
    const lowCeiling = validateLevel(tallFixture({ skyCeiling: 10 }), budget);
    const sealedIn = validateLevel(tallFixture({ ledgeOverCaveExit: true }), budget);

    expect('a bonus room with a ceiling one row too low is reported',
      lowCeiling.length > 0 && lowCeiling.every((p) => p.startsWith('no headroom') && p.includes('sky band')),
      lowCeiling.slice(0, 3).join(' / ') || 'ei yhtään');
    expect('a bonus room whose exit pipe has nowhere to land is reported',
      sealedIn.length > 0 && sealedIn.every((p) => p === 'no way out of the cave band at the tallest size'),
      sealedIn.slice(0, 3).join(' / ') || 'ei yhtään');
    expect('the same tall fixture without the faults passes',
      sound.length === 0, sound.slice(0, 3).join(' / '));

    /*
     * And red before green for the thing the growing beanstalk added to the
     * argument.
     *
     * The validator reads the level data, and the level data is the GROWN
     * level — the vine is in it from floor to sky, which is what makes
     * `vineCrossings` able to say the sky band is reachable. The player is
     * handed the ungrown one, with a `?` on the vine's bump row instead. That
     * is only honest while the growing is guaranteed, so the guarantee is
     * checked rather than assumed: the vine stands on a floor (which is where
     * the bean lands, and also the only place a player can take hold of the
     * finished stalk), it is tall enough for the block to hang in it, and that
     * height is one a jump can reach.
     *
     * Three faults, one at a time, and the same fixture with none of them has
     * to come back silent — otherwise this proves nothing about the rule and
     * only that some level somewhere is unusual.
     */
    const vineFixture = ({ endsAt = 29, pit = false, pillar = false } = {}) => {
      const W = 32;
      /* Kolme kuudentoista rivin kaistaa, ks. `tallFixture` yllä. */
      const g = Array.from({ length: 48 }, () => ' '.repeat(W));
      const put = (y, x, s) => { g[y] = g[y].slice(0, x) + s + g[y].slice(x + s.length); };

      // Route band: flat ground, a start, an early power-up, a flag.
      put(30, 0, '#'.repeat(W)); put(31, 0, '#'.repeat(W));
      put(29, 2, '1');
      put(26, 5, '!');
      put(29, 28, 'F');
      /* The vine, from the floor up through the seam into the sky band. A
       * pillar raises the floor under it so the run is only three tiles long
       * on this side of the seam — too short to hang a block in. */
      const top = pillar ? 15 : 7;
      if (pillar) for (let y = 18; y <= 31; y++) put(y, 16, 'X');
      for (let y = top; y <= endsAt; y++) put(y, 16, 'v');
      /* A pit right under the vine, lidded with lava the way `assembleTall`
       * lids one: the stalk has nothing to stand in and the bean nowhere to
       * land. */
      if (pit) { put(30, 15, '   '); put(31, 15, '   '); put(32, 15, 'WWW'); }

      // The sky garden the vine arrives in, shaped like the shipped one: the
      // vine runs three rows past the planks so you step off sideways, the
      // planks start in the column beside it so nothing solid is ever next to
      // the vine, and the open bottom edge is how you get home.
      put(10, 17, '--------');
      put(9, 18, 'ooo');
      put(7, 19, '!');
      return g;
    };

    const grown = validateLevel(vineFixture(), budget);
    const hanging = validateLevel(vineFixture({ endsAt: 26 }), budget);
    const overPit = validateLevel(vineFixture({ pit: true }), budget);
    const stumpy = validateLevel(vineFixture({ endsAt: 17, pillar: true }), budget);

    expect('a beanstalk that stops in mid-air instead of reaching the floor is reported',
      hanging.some((p) => p.includes('instead of standing on the floor')),
      hanging.slice(0, 3).join(' / ') || 'ei yhtään');
    expect('a beanstalk rooted over a pit is reported',
      overPit.some((p) => p.includes('instead of standing on the floor')),
      overPit.slice(0, 3).join(' / ') || 'ei yhtään');
    expect('a beanstalk too short to hang a bean block in is reported',
      stumpy.some((p) => p.includes('too short to hang a bean block')),
      stumpy.slice(0, 3).join(' / ') || 'ei yhtään');
    expect('the same beanstalk fixture with none of the faults passes',
      grown.length === 0, grown.slice(0, 3).join(' / '));
  }

  /* ------------------------------ maastopassi ----------------------------- */
  /*
   * MAASTOPASSI, ja se yksi väite jonka varassa koko toteutus lepää.
   *
   * `src/data/terrain.js` nostaa palikoiden lattiatasoa ja kirjoittaa
   * siirtymät rinteinä. Se on halpa vain siksi että se **ei siirrä maata vaan
   * nostaa pintaa ja jättää kiven alle**: rivit 13-14 pysyvät kiinteinä, joten
   * `floorProfile`in siemen, `checkGaps`in pohjattomuustesti ja
   * `difficulty.mjs`:n `lethalCol` lukevat yhä sitä mitä ne ovat aina lukeneet.
   * Jos joku joskus toteuttaa noston toisin — siirtämällä — jokainen niistä
   * alkaa lukea nostettua saraketta kuiluna, eikä yksikään sano sitä ääneen.
   * Siksi tämä on portti eikä kommentti.
   *
   * Neljä väitettä:
   *
   *   1  pohja      maasto ei muuta yhtäkään saraketta kuiluksi
   *   2  vauhti     rinteen kummallakin puolella on `RUNWAY` saraketta lattiaa
   *   3  ankkurit   aloitus ja lippu ovat maan tasalla
   *   4  poikkeus   kenttä joka ei voi saada maastoa sanoo sen ääneen
   *
   * Väite 2 on se joka on jo kerran ollut punaisena, eikä arvaamalla: yhden
   * sarakkeen reunaehdolla 1-1 sai rinteen kolme saraketta ennen `pit_plat`in
   * kymmenen sarakkeen kuilua, ja `tools/playable.mjs` kuoli sarakkeeseen 290.
   * `validateLevel` oli tyytyväinen koko ajan, koska se mittaa kuilun leveyden
   * eikä sitä paljonko vauhtia sen eteen mahtuu — sama sokea piste kuin
   * vaikeustason venytyksellä oli, ja siksi sama luku (`RUNWAY`).
   */
  {
    const { getLevel, levelIds, terrainSeedOf } = await import('/src/data/levels.js');
    const { CHUNKS, assemble } = await import('/src/data/chunks.js');
    const { LOOSE, MAX_LIFT, RUNWAY, RUN_ROWS, applyTerrain, liftCap, seamReady, terrainProfile }
      = await import('/src/data/terrain.js');
    const FLOOR = 14;
    const SLOPE = '/\\';

    const withTerrain = levelIds().filter((id) => getLevel(id).terrain);
    expect('maastopassi on käytössä useammassa kuin yhdessä kentässä',
      withTerrain.length >= 2, `${withTerrain.length} kenttää: ${withTerrain.join(' ')}`);

    /* Kummankin väitteen pohja: sama palikkalista kahdesti, ja tieto siitä
     * mihin rinteet syntyivät. `shift[i]` on montako saraketta palikan i eteen
     * on työnnetty, joten sen kasvu kahden palikan välillä **on** se rinne. */
    const built = withTerrain.map((id) => {
      const def = getLevel(id);
      const chunks = def.chunks.map((n) => CHUNKS[n]);
      /* The seed comes from `terrainSeedOf` and not from the id, because
       * `terrain:` may name a seed instead of saying `true` — a level that
       * could not clear its own id's ramps picks a different string. Rebuilding
       * with the id would then produce a different `shift` than the level
       * actually has, and every claim below compares that shift against the
       * real grid: the whole gate would report holes that are not there.
       *
       * The definition is handed over without its `rows`, because `getLevel`
       * has already built them and `terrainSeedOf` refuses a level that writes
       * its own — the seed rule is read from the one function that owns it
       * rather than copied here. */
      const { shift } = applyTerrain(chunks,
        terrainProfile(chunks, terrainSeedOf(id, { terrain: def.terrain, chunks: def.chunks })));
      const starts = [];
      let flatCol = 0;
      chunks.forEach((chunk, i) => { starts.push({ flat: flatCol, at: flatCol + shift[i] }); flatCol += chunk.w; });
      return { id, def, chunks, shift, starts, flat: assemble(def.chunks), rows: def.rows };
    });

    /* 1. POHJA. Jokainen sarake joka oli maata on yhä maata. Sarakkeet
     *    verrataan *sisällöltään* eikä numeroltaan, koska rinne työntää
     *    numeroita eteenpäin. */
    const holes = [];
    for (const b of built) {
      b.chunks.forEach((chunk, i) => {
        for (let x = 0; x < chunk.w; x++) {
          const from = b.starts[i].flat + x;
          const to = b.starts[i].at + x;
          for (const y of [FLOOR, FLOOR + 1]) {
            if (b.flat[y][from] === '#' && b.rows[y][to] !== '#') {
              holes.push(`${b.id} sarake ${to} rivi ${y}: "${b.rows[y][to]}"`);
            }
          }
        }
      });
    }
    expect('nostettu maasto ei jätä yhtäkään saraketta ilman pohjaa',
      holes.length === 0, holes.length ? holes.slice(0, 3).join(' / ')
        : `${withTerrain.length} kenttää, rivit 13-14 ennallaan`);

    /* 2. VAUHTI. Mitataan **passin omista rinteistä** eikä ruudukon jokaisesta
     *    vinosta merkistä: `kumpare` ja `pitkarinne` ovat käsintehtyä sanastoa
     *    ja niiden tasanne on kentän tekijän päätös. Se mitä tämä portti
     *    vahtii on kokoajan kirjoittama siirtymä — ja sen kummallakin puolella
     *    on oltava `RUNWAY` saraketta tasaista maata *samalla korkeudella*,
     *    koska porras portaan perään on jalansijaa muttei vauhdinottoa. */
    const surfaceOf = (rows, x) => {
      if (rows[FLOOR + 1][x] !== '#') return -1;
      let y = FLOOR + 1;
      while (y > 0 && rows[y - 1][x] === '#') y--;
      return y;
    };
    /* Jalansija luetaan pinnasta eikä rivistä 13, ja juuri se on koko passin
     * idea: nostetussa sarakkeessa rivi 13 on kiveä maan alla, ja se mitä
     * juoksija tarvitsee on vapaat rivit sen pinnan yllä jolla hän seisoo. */
    const plainFeet = (rows, x) => {
      const top = surfaceOf(rows, x);
      if (top < 0) return false;
      for (let y = top - (RUN_ROWS - 2); y < top; y++) {
        const ch = y < 0 ? ' ' : rows[y][x];
        if (ch !== ' ' && !LOOSE.has(ch)) return false;
      }
      return true;
    };
    const runway = (rows, from, step) => {
      const top = surfaceOf(rows, from);
      if (top < 0 || !plainFeet(rows, from)) return 0;
      let n = 0;
      for (let x = from; x >= 0 && x < rows[0].length; x += step) {
        if (surfaceOf(rows, x) !== top || !plainFeet(rows, x)) break;
        n++;
      }
      return n;
    };
    const tight = [];
    let ramps = 0;
    for (const b of built) {
      b.chunks.forEach((chunk, i) => {
        if (!i) return;
        const width = b.shift[i] - b.shift[i - 1];
        if (!width) return;
        ramps++;
        const end = b.starts[i].at - 1;
        const start = end - width + 1;
        const before = runway(b.rows, start - 1, -1);
        const after = runway(b.rows, end + 1, +1);
        if (before < RUNWAY || after < RUNWAY) {
          tight.push(`${b.id} rinne ${start}-${end}: ${before} ennen, ${after} jälkeen`);
        }
        if (width > MAX_LIFT) tight.push(`${b.id} rinne ${start}-${end} on ${width} saraketta`);
      });
    }
    expect('jokaisen maastorinteen kummallakin puolella on täysi vauhdinotto',
      ramps > 0 && tight.length === 0,
      tight.length ? tight.slice(0, 3).join(' / ')
        : `${ramps} rinnettä, kaikilla vähintään ${RUNWAY} saraketta samaa korkeutta kumpaankin suuntaan`);

    /* 3. ANKKURIT. Aloitusruutu ja lippu ovat samalla rivillä kuin tasamaalla —
     *    ne ovat ne kaksi kohtaa joista kaikki muu on mitattu. Vertailu on
     *    tasamaahan eikä riviin 12, koska 1-3 alkaa hyllyltä (`start_high`)
     *    rivillä 9 ja on tehnyt niin ennen maastoa: väite on "maasto ei
     *    siirtänyt", ei "kaikki alkavat samalta korkeudelta". */
    const rowOf = (rows, mark) => rows.findIndex((row) => row.includes(mark));
    const drifted = [];
    for (const b of built) {
      for (const mark of '1F') {
        const was = rowOf(b.flat, mark);
        const now = rowOf(b.rows, mark);
        if (was !== now) drifted.push(`${b.id} "${mark}" rivi ${was} → ${now}`);
      }
    }
    expect('maasto ei siirrä aloitusruutua eikä lippua',
      drifted.length === 0, drifted.length ? drifted.join(' / ')
        : `${withTerrain.length} kenttää, "1" ja "F" ennallaan`);

    /* 4. POIKKEUS, punaisena ensin. Kenttä joka laskee sarakkeita numeroina ei
     *    voi saada maastoa, ja hiljaa jätetty tasamaa olisi juuri se vika jota
     *    etsittäisiin väärästä tiedostosta. Kolme muotoa, kolme heittoa. */
    const refused = [];
    const shapes = [
      ['korkea kenttä', { sky: [[0, 'flat']] }],
      ['luolakaista', { cave: [[0, 'flat']] }],
      ['osioitu kenttä', { segments: [{ toCol: 32 }] }],
      ['pomoareena', { boss: true }],
      ['omat rivit', { rows: ['#'] }],
    ];
    for (const [what, extra] of shapes) {
      try {
        terrainSeedOf('koe', { terrain: true, chunks: ['start', 'flat'], ...extra });
        refused.push(`${what}: ei heittänyt`);
      } catch {
        // odotettu
      }
    }
    /* Ja vihreä sen vieressä: tavallinen kenttä saa siemenekseen tunnuksensa,
     * eikä maastoa pyytämätön saa mitään. */
    const seeded = terrainSeedOf('2-9', { terrain: true, chunks: ['start'] });
    const unseeded = terrainSeedOf('2-9', { chunks: ['start'] });
    expect('maastoa pyytävä kenttä saa siemenekseen tunnuksensa, muut eivät mitään',
      seeded === '2-9' && unseeded === null, `${seeded} / ${unseeded}`);
    expect('kenttä joka ei voi saada maastoa sanoo sen heittona eikä tasamaana',
      refused.length === 0, refused.length ? refused.join(' / ')
        : `${shapes.length} muotoa, jokainen heittää`);

    /* Ja sanasto itse: nostoa on rajallisesti, eikä sauma ole ilmainen. */
    const names = Object.keys(CHUNKS);
    const liftable = names.filter((n) => liftCap(CHUNKS[n]) > 0).length;
    const seamable = names.filter((n) => seamReady(CHUNKS[n], 'left')
      && seamReady(CHUNKS[n], 'right')).length;
    expect('sanastosta osa nousee ja osa ei — portti erottaa ne',
      liftable > 20 && liftable < names.length && seamable > 10 && seamable < names.length,
      `${names.length} palikkaa: ${liftable} nousee (kattona ${MAX_LIFT}), ${seamable} kelpaa saumaksi`);
  }

  /* ------------------------------ luumaailma ------------------------------ */
  /*
   * Maailma 6, ja kolme väitettä joita se ei saa rikkoa. Ne ovat tässä eikä
   * hajallaan siksi että ne ovat sama väite kolmesta suunnasta: luumaailma on
   * oma maailmansa eikä toisen maailman uudelleenmaalaus.
   */
  {
    const { BONE_CHUNKS } = await import('/src/data/chunks/bone.js');
    const { FACTORY_CHUNKS } = await import('/src/data/chunks/factory.js');

    /*
     * 1. LUUPALIKOIDEN EHTO, ja se on tehtaan ehdon peilikuva.
     *
     * `chunks/factory.js` perustelee olemassaolonsa yhdellä lauseella: jokaisella
     * sen palikalla on katto, koska tehdas on sisätila, ja avotaivaan kenttään
     * pudotettu tehdaspalikka jättäisi katon roikkumaan tyhjän päälle. Luumaailma
     * on tehtaan jälkeen ja sen sääntö kulkee toiseen suuntaan:
     *
     *   **luulaaksossa ei ole kattoa, eikä siellä roiku mikään.**
     *
     * Kaksi puoliskoa, ja molemmat mitataan alla:
     *
     *   - **taivas on auki**: rivit 0..4 ovat tyhjiä jokaisessa luupalikassa.
     *     Se on se puolisko joka kieltää lainaamisen: `fac_*` ei kelpaa tänne,
     *     koska sen katto peittäisi juuri sen kuun ja tähdet joiden takia tämä
     *     maailma näyttää keskiyöltä. Sääntö on siis aita edellisen maailman
     *     ympärillä eikä tämän — ja se on tarkoituksellisesti eri asia kuin
     *     tehtaan aita, koska kysymys "kummasta suunnasta lainataan" on eri
     *     kysymys kuin "saako lainata".
     *   - **luu seisoo**: jokainen `X` ja jokainen `#` lattiarivien yläpuolella
     *     nojaa johonkin suoraan allaan. Luuranko on määritelmän mukaan asia
     *     joka kannattaa itsensä, joten luulaakson pystysuunta tulee maasta
     *     ylöspäin eikä katosta alaspäin. Lohkot, laudat ja kolikot leijuvat
     *     kuten kaikkialla muualla — ne eivät ole luuta.
     *
     * Molemmat ovat rikottavissa yhdellä huolimattomalla rivillä, ja kumpikaan
     * ei näkyisi missään muussa testissä: kattopalikka luukentässä on täysin
     * kelvollinen kenttä `rules.js`:n mielestä.
     */
    const SKY_ROWS = 5;
    const STRUCTURE = '#X';
    const noSky = [];
    const floating = [];
    for (const [name, chunk] of Object.entries(BONE_CHUNKS)) {
      for (let y = 0; y < SKY_ROWS; y++) {
        if (/\S/.test(chunk.rows[y])) noSky.push(`${name} rivi ${y}`);
      }
      for (let y = 0; y < 13; y++) {
        for (let x = 0; x < chunk.w; x++) {
          if (!STRUCTURE.includes(chunk.rows[y][x])) continue;
          if (!STRUCTURE.includes(chunk.rows[y + 1][x])) floating.push(`${name} ${x},${y}`);
        }
      }
    }
    /* Tehtaan puoli luetaan kuudelta ylimmältä riviltä eikä pelkältä rivi
     * nollalta: `fac_cellar` ja `fac_loft` ovat kellari ja ullakko, ja niiden
     * katto on rivillä 5. Ne ovat yhtä lailla sisätilaa — mitattuna 10/12
     * roikkuisi rivillä 0 ja 12/12 roikkuu kuuden ylimmän sisällä. */
    const ceilinged = Object.values(FACTORY_CHUNKS)
      .filter((c) => c.rows.slice(0, 6).some((row) => /\S/.test(row))).length;
    expect('luupalikoissa on taivas auki ja tehdaspalikoissa katto',
      noSky.length === 0 && ceilinged === Object.keys(FACTORY_CHUNKS).length,
      `${Object.keys(BONE_CHUNKS).length} luupalikkaa, kattoja ${noSky.length}`
      + ` — tehtaassa katto ${ceilinged}/${Object.keys(FACTORY_CHUNKS).length}:ssa`);
    expect('luumaailmassa mikään luu ei roiku ilmassa',
      floating.length === 0,
      floating.length ? `${floating.length}: ${floating.slice(0, 5).join(' ')}` : 'kaikki nojaa maahan');
  }

  /*
   * 2. JOKAISEN MAAILMAN KÄYRÄ NOUSEE, HENGÄHTÄÄ, EIKÄ KIIPEÄ KOLMEA PIDEMPÄÄN.
   *
   * `tools/difficulty.mjs` on tulostanut tämän rivin pitkään, mutta tulostus ei
   * ole portti: uuden maailman voisi committoida suoraviivaisena tai laskevana
   * eikä mikään sanoisi mitään ennen kuin joku katsoo. Nyt sanoo.
   *
   * **TÄMÄ SÄÄNTÖ MUUTTUI 9.8.2026, ja se on tarkoituksellinen muutos eikä
   * löysennys.** Vanha muoto oli `dips !== 1` — "tasan yksi notko" — ja se on
   * nyt jaettu neljään väitteeseen. Syy on mittaus, ei maku:
   *
   *   **"Tasan yksi" ei sanonut mitään kolmen askelen maailmasta.** Kolmen
   *   askelen kävelyssä on kaksi siirtymää, joten notkoja voi olla 0, 1 tai 2.
   *   Kaksi notkoa tarkoittaa että molemmat siirtymät laskevat, eli viimeinen
   *   luku on ensimmäistä pienempi — jonka `rises` hylkää jo. Eli maailmoissa
   *   1–7 ehto `dips === 1` oli **täsmälleen sama ehto** kuin `dips >= 1`, ja
   *   se ero näkyy vasta kun maailmassa on enemmän askelia. Sanan "tasan"
   *   ainoa oikea kohde oli maailma 8 (viisi askelta), jossa se sattui
   *   pitämään.
   *
   *   **Ja kahdeksan kentän maailmassa "tasan yksi" olisi väärä sääntö.**
   *   Seitsemän askelta yhdellä hengähdyksellä on kuuden nousun putki jossa on
   *   yksi tauko; ROADMAP pyytää kahdeksalta kentältä nimenomaan tilaa
   *   hengähdyskentälle, eikä yhtä.
   *
   * Tilalle neljä väitettä, ja jokainen on mitattu tästä pelistä:
   *
   *   1  käyrä nousee kokonaisuutena           (ennallaan)
   *   2  vähintään yksi notko                  (vanhan sisältö kolmella askelella)
   *   3  ei kahta notkoa peräkkäin             — pelissä 0 tapausta tänään
   *   4  ei yli kolmen nousun putkea           — pelin pisin on tasan 3 (maailma
   *                                              8: 117→302→378→386)
   *
   * Kolme ja nolla ovat siis pelin omia lukuja eivätkä valittuja kattoja: sääntö
   * kieltää sen mitä peli ei jo tee, ja päästää läpi kaiken minkä se tekee.
   * Maailmoissa 1–7 uusi sääntö on merkki merkiltä sama kuin vanha (ks. todistus
   * yllä), maailmassa 8 se sallii toisen hengähdyksen jos joku sellaisen joskus
   * haluaa. Se on ainoa kohta jossa sääntö on väljempi, ja se on sanottu ääneen.
   */
  {
    const { tiersOf, tierScore, walksOf } = await import('/src/data/worlds.js');
    const { DIFFICULTY } = await import('/src/data/difficulty.js');
    /*
     * MUOTO ON KÄVELYN OMINAISUUS, EI KARTAN.
     *
     * Tämä luki `tiersOf`illa 10.8.2026 asti, ja se oli oikein niin kauan kuin
     * jokainen maailma oli yksi jono: `tiersOf` litistää haaran yhdeksi
     * askeleeksi, joten haarautuvasta maailmasta se mittasi rivin **jota
     * kukaan ei kävele** — maailman 2 luku `[124|159]` on kahden vaihtoehdon
     * pienempi eikä kummankaan reitin oma kokemus.
     *
     * Nyt jokainen väite tässä lohkossa mitataan kävelystä (`walksOf`), ja
     * haarautuvassa maailmassa niitä on kaksi. Seitsemälle maailmalle
     * kahdeksasta se on merkki merkiltä sama jono kuin ennen — yksi haaraton
     * maailma on tasan yksi kävely — joten muutos ei löysennä eikä kiristä
     * niitä lainkaan. Maailmassa 2 se kiristää, ja se on koko pointti: väite
     * jonka haara pääsee ohi ei ole väite haarautuvasta maailmasta.
     */
    const shapes = WORLDS.flatMap((w) => walksOf(w).map((walk) => {
      const seq = walk.nodes.filter((n) => n.type !== 'fortress').map((n) => DIFFICULTY[n.level] || 0);
      const steps = seq.slice(1).map((v, i) => (v < seq[i] ? -1 : 1));
      const dips = steps.filter((s) => s < 0).length;
      const twice = steps.some((s, i) => i > 0 && s < 0 && steps[i - 1] < 0);
      let climb = 0;
      let longest = 0;
      for (const s of steps) {
        climb = s > 0 ? climb + 1 : 0;
        longest = Math.max(longest, climb);
      }
      return {
        id: w.id,
        route: walk.name,
        seq,
        dips,
        twice,
        longest,
        walked: walk.nodes.length,
        levels: w.nodes.filter((n) => n.level).length,
        rises: seq[seq.length - 1] > seq[0],
      };
    }));
    const say = (s) => `${s.id}${s.route === 'SUORA' ? '' : ` ${s.route}`} `
      + `${s.seq.map((v) => v.toFixed(0)).join('→')} ${s.dips} notkoa, pisin nousu ${s.longest}`;
    const bad = shapes.filter((s) => !s.rises || s.dips < 1 || s.twice || s.longest > 3);
    expect('jokainen kävely nousee, hengähtää, eikä kiipeä kolmea pidempään',
      bad.length === 0,
      shapes.map(say).join(', '));

    /*
     * KAHDEKSAN KENTÄN MAAILMAN MUOTO, ja se on tämän päivän päätös kirjoitettuna
     * porttiin eikä roadmapiin.
     *
     * ROADMAP piti kysymystä auki näin: *"Kahdeksan kenttää maailmassa on eri
     * muoto kuin neljä. Nykyinen kaava on kolme kenttää ja linnake. Kahdeksan ei
     * ole 'sama kaksi kertaa' vaan tila välipomolle, haaralle ja
     * hengähdyskentälle."*
     *
     * Päätetty muoto: **seitsemän numeroitua kenttää ja linnake, ja kävelyssä
     * kaksi hengähdystä.** Perustelu kolmessa osassa, ja kaikki kolme ovat
     * mitattavissa:
     *
     *   **Miksi ei kahta kaarta.** "Sama kaksi kertaa" tarkoittaisi kahta
     *   huippua, ja kahden huipun maailma on kaksi maailmaa joiden välistä
     *   puuttuu linnake — pelaaja lukee toisen huipun lopuksi ja saa jatkoa.
     *   Yksi maailma on yksi kaari yhteen huippuun, ja se huippu on linnake.
     *   Kahdeksan kenttää ei siis muuta kaarta vaan venyttää sitä.
     *
     *   **Miksi kaksi hengähdystä eikä yksi.** Venytetty kaari on kuuden nousun
     *   putki, ja sääntö 4 yllä sanoo pelin oman mittauksen: pisin kiipeäminen
     *   jonka tämä peli on koskaan pyytänyt on kolme askelta. Kaksi notkoa on se
     *   pienin määrä joka pitää seitsemän askelta sen mitan sisällä ilman että
     *   ne ovat peräkkäin (3 + 2 + 1 tai 2 + 3 + 1 ja niin edelleen).
     *
     *   **Miksi ei haaraa ja välipomoa jokaiseen maailmaan**, vaikka ROADMAP
     *   ne mainitsee: molemmat ovat jo sidottuja päätöksiä muualla. Haaran pitää
     *   olla eriarvoinen ja vaikeamman haaran pitää maksaa jotain jota ei saa
     *   muualta (omistajan päätös 9.8.2026), ja koko pelissä on **yksi** sellainen
     *   palkinto (`REWARDS.break`), jonka ainoa lähde on maailman 2 välipomo.
     *   Seitsemän uutta samanarvoista palkintoa keksittäisiin tässä vain muodon
     *   täytteeksi, ja se on väärin päin. Haara ja välipomo pysyvät siis
     *   **maailman ominaisuutena eivätkä muodon osana** — maailma 2 on
     *   haarautuva kahdeksankin kentän mitassa, koska kahdeksan kentän muoto ei
     *   sano mitään siitä montako askelta on haaroja.
     *
     * Väite on siksi askelina eikä kenttinä: kahdeksan kentän maailmassa on
     * seitsemän askelta *jos* mikään niistä ei ole haara, ja maailma 2 saa olla
     * kuusi askelta samalla kahdeksalla kentällä. Notkojen määrä on kaksi
     * kummassakin tapauksessa — ja koska muoto mitataan nyt kävelystä, se on
     * kaksi **kummallakin reitillä** eikä kaksi litistetyllä rivillä.
     */
    const eight = shapes.filter((s) => s.levels === 8);
    const wrong = eight.filter((s) => s.dips !== 2);
    expect('kahdeksan kentän maailmassa on kaksi hengähdystä',
      eight.length >= 2 && wrong.length === 0,
      `${eight.length} kävelyä kahdeksan kentän maailmoissa `
      + `(${eight.map((s) => `${s.id}${s.route === 'SUORA' ? '' : ` ${s.route}`} `
        + `${s.seq.length} askelta, ${s.dips} notkoa`).join('; ') || '—'})`);

    /*
     * JA KUKA ON JO SIINÄ MITASSA — nimeltä, eikä lukumääränä.
     *
     * Yllä oleva väite on ehdollinen: *jos* maailmassa on kahdeksan kenttää,
     * siinä on kaksi hengähdystä. Se on oikea muoto sille väitteelle, mutta se
     * ei sano mitään siitä kuinka moni maailma on siinä mitassa — eli maailman
     * voisi jättää neljään kenttään ikuisiksi ajoiksi eikä mikään sanoisi
     * mitään. ROADMAP sanoo, mutta ROADMAP ei ole portti.
     *
     * Lista on nimiä eikä lukua kahdesta syystä. Ensinnäkin `>= 6` menisi läpi
     * millä tahansa kuudella maailmalla, eli se ei erottaisi "maailma 4 on
     * täytetty" ja "maailma 2 on täytetty kahdesti" -tapauksia toisistaan.
     * Toiseksi **maailmat 2 ja 8 ovat tarkoituksella poissa**: maailmassa 2 on
     * haara ja maailmassa 8 pomo joka kentässä, eli kummankin kahdeksan kenttää
     * on eri työ eri ehdoilla (ks. v26.08.09.46), ja portti joka vaatii niitä
     * nyt olisi punainen työstä jota ei ole vielä tehty. Kun ne valmistuvat,
     * niiden tunnukset lisätään tähän listaan — se on yhden rivin muutos ja se
     * on tarkoitus.
     *
     * **`w8` lisättiin 10.8.2026**, ja se oli täsmälleen se yhden rivin muutos:
     * seitsemän uusintaa ja kuningas, kahdeksan kenttää ja kaksi hengähdystä
     * (245 → 117 → 302 → 169 → 368 → 378 → 386).
     *
     * **JA `w2` LISÄTTIIN SAMANA PÄIVÄNÄ, MUTTA SE EI OLLUT YHDEN RIVIN
     * MUUTOS.** Lista on nyt täysi, joten tämä on se kohta johon seuraava
     * lukija tulee kysymään mitä "kahdeksan kenttää" tarkoittaa maailmassa
     * jossa on haara — ja vastaus ei ole "sama kuin muissa", joten se lukee
     * tässä eikä muutoslokissa.
     *
     * Ehdokkaita oli kolme, ja kaksi hylättiin mittaamalla:
     *
     *   **kahdeksan kenttää jokaisella reitillä.** Hylättiin aritmetiikalla,
     *   ei mausta. Jos runko on `t` kenttää (linnake mukaan lukien) ja
     *   molemmilla reiteillä on omansa, kahdeksan kentän kävely vaatii
     *   `8 − t` omaa kenttää **kummallekin**, eli kartalle `15 − t` solmua:
     *   maailma 2 olisi 12 kenttää sillä rungolla joka sillä on. Se olisi puolta
     *   isompi kuin yksikään toinen maailma, eikä pelin summa olisi 64 vaan 68.
     *   Ehto joka on määritelmällisesti saavuttamaton ei ole ankara vaan väärä.
     *
     *   **kahdeksan solmua, eikä muuta.** Se on projektin oma laskuyksikkö (8 x
     *   8 = 64) ja se mitä kartta näyttää, mutta yksinään se on liian löysä:
     *   sen läpäisisi maailma jonka rungolla on kolme kenttää ja jonka toisella
     *   haaralla on neljä, eli kahdeksan kentän maailma josta yksi kävely näkee
     *   viisi. Haaran hinta ei saa olla se että puolet maailmasta katoaa
     *   valinnan taakse.
     *
     *   **valittu: kahdeksan solmua JA kävelyn alaraja.** Kartalla on kahdeksan
     *   kenttää kuten kaikissa muissakin maailmoissa, ja lisäksi väitetään mitä
     *   yksi kävely niistä näkee: **vähintään kuusi, eikä reittien ero ole yhtä
     *   suurempi**. Kuusi ei ole valittu luku vaan sama luku toisin päin —
     *   kahdeksasta kentästä korkeintaan kaksi saa olla yhden reitin omia, eli
     *   valinta saa piilottaa neljänneksen maailmasta muttei enempää. Mitattuna
     *   HIEKKATIE kävelee kuusi ja LAAVATIE seitsemän.
     *
     * Ja se mitä tämä *ei* sano, koska sitä ei voi luvata: reitit eivät ole yhtä
     * pitkiä. Kahdeksan solmua ja kaksi eripituista reittiä on sama epäsuhta
     * joka haarassa on ollut alusta asti — ero on yksi kenttä ennen ja jälkeen —
     * mutta suhteessa kävelyyn se **pieneni**, 1/4:sta 1/6:een. Haara on siis
     * tasapainoisempi kahdeksan kentän mitassa kuin kuuden, mikä oli se riski
     * jonka takia tämä maailma jätettiin viimeiseksi.
     */
    const EIGHT_DONE = ['w1', 'w2', 'w3', 'w4', 'w5', 'w6', 'w7', 'w8'];
    const shortOf = (id) => (shapes.find((s) => s.id === id) || { levels: 0 }).levels;
    const short = EIGHT_DONE.filter((id) => shortOf(id) !== 8);
    expect('jokainen kahdeksasta maailmasta on kahdeksan kentän mittainen',
      short.length === 0,
      EIGHT_DONE.map((id) => `${id} ${shortOf(id)}`).join(', ')
      + ` — vajaana ${short.length}`);

    /*
     * JA HAARAUTUVASSA MAAILMASSA MYÖS SE MITÄ YKSI KÄVELY NÄKEE.
     *
     * Yllä oleva väite laskee solmuja, eli sen minkä kartta näyttää. Tämä
     * laskee kenttiä yhden pelaajan matkalla, eli sen minkä hän pelaa, ja ne
     * ovat eri luku vain haarautuvassa maailmassa. Väite on tyhjä siellä missä
     * haaraa ei ole, joten se vaatii vähintään yhden haarautuvan maailman
     * ollakseen mitattu eikä vain läpäisty.
     */
    const branched = WORLDS.filter((w) => (w.branches || []).length);
    const walked = branched.map((w) => {
      const lens = walksOf(w).map((walk) => ({ name: walk.name, n: walk.nodes.length }));
      const min = Math.min(...lens.map((l) => l.n));
      const max = Math.max(...lens.map((l) => l.n));
      return { id: w.id, lens, min, max };
    });
    const lopsided = walked.filter((x) => x.min < 6 || x.max - x.min > 1);
    expect('haarautuvassa maailmassa jokainen reitti kävelee vähintään kuusi kenttää, eikä ero ole yhtä suurempi',
      branched.length >= 1 && lopsided.length === 0,
      walked.map((x) => `${x.id}: ${x.lens.map((l) => `${l.name} ${l.n}`).join(', ')}`).join(' — ')
      || 'ei yhtään haarautuvaa maailmaa');

    /*
     * Ja maailmasta maailmaan käyrä nousee myös, mikä on eri väite kuin
     * yllä oleva. Muototesti katsoo yhtä maailmaa kerrallaan, joten uusi
     * maailma voisi olla sisäisesti moitteeton ja silti helpompi kuin
     * edellinen — pelaajan kannalta juuri se on se vika joka tuntuu.
     * `difficulty.mjs` on tulostanut tämän rivin pitkään ("Käyrä nousee joka
     * maailmassa"), ja tulostus ei ole portti.
     *
     * Luku on maailman tasojen keskiarvo linnake mukaan lukien, sama kuin
     * työkalussa. Askelten koot vaihtelevat rajusti (+8,0 maailmaan 6, +66,8
     * maailmaan 5) eikä sitä yritetä tasoittaa: askelen koko on toimituksellinen
     * päätös, sen etumerkki ei ole.
     */
    const means = WORLDS.map((w) => {
      const tiers = tiersOf(w);
      const sum = tiers.reduce((s, t) => s + tierScore(w, t, DIFFICULTY), 0);
      return { id: w.id, mean: sum / (tiers.length || 1) };
    });
    const falls = means.filter((m, i) => i > 0 && m.mean <= means[i - 1].mean);
    expect('vaikeus nousee maailmasta maailmaan',
      falls.length === 0,
      means.map((m, i) => `${m.id} ${m.mean.toFixed(1)}`
        + (i ? ` (${m.mean > means[i - 1].mean ? '+' : ''}${(m.mean - means[i - 1].mean).toFixed(1)})` : ''))
        .join(', '));
  }

  /*
   * 3. MAAILMOJEN 6–8 MAAREITTI AUKEAA PIENIMMÄLLÄ KOOLLA.
   *
   * **Otsikossa luki "uusien käsintehtyjen maailmojen", ja se sana on nyt
   * poissa.** Maailmat 6 ja 7 ovat kahdeksan kentän mittaisia ja niiden kentät
   * 6-4…6-7 ja 7-4…7-7 ovat generoituja, joten "käsintehty" ei enää kuvaa tätä
   * joukkoa. Väite ei silti muuttunut vaan **vahvistui**: se koskee edelleen
   * jokaista kenttää joka näissä kolmessa maailmassa on, ja niitä on nyt 22
   * eikä 14. Generoitu kenttä on juuri se tapaus jota tämä portti eniten
   * tarvitaan — käsi katsoo kentän, generaattori ei katso mitään.
   *
   * DESIGN.md kohta 5 sanoo sen näin: tehostus avaa paikkoja, ei kenttää.
   * `tools/playable.mjs` mittaa juuri tätä koko pelistä, mutta se on raportti
   * eikä portti, ja siinä on jo kolme tunnettua nimeä. Uusi maailma ei saa
   * liittyä siihen listaan huomaamatta, joten sen kolme numeroitua kenttää ja
   * linnake ajetaan täällä ja tulos on kaatava.
   *
   * **Maailmat 6, 7 ja 8 samassa silmukassa, ja se on väite eikä säästö.**
   * Lupaus koskee koko peliä, mutta portiksi se voidaan nostaa vain siellä
   * missä lähtötaso on puhdas: maailmoissa 1–5 on kolme tunnettua nimeä (4-3,
   * ja 2-1 / 3-F / 5-F tuplahypyllä), ja niiden korjaaminen on eri työ kuin
   * uuden maailman tekeminen. Käsintehdyt maailmat luulaaksosta eteenpäin
   * eivät saa kasvattaa tuota listaa, ja tässä se on ajettavassa muodossa.
   *
   * Ovi avataan **kentän omasta `boss`-lipusta** eikä tunnisteen viimeisestä
   * kirjaimesta. Se oli sama asia niin kauan kuin pomoja oli vain
   * linnakkeissa; viimeisessä linnakkeessa jokainen kenttä päättyy oveen, ja
   * nimestä päättelevä testi olisi raportoinut kuusi kenttää umpikujina
   * mittaamatta niiden maastosta mitään.
   *
   * Botti on sama tyhmä botti: juoksee oikealle ja hyppää. Viholliset ja
   * vaarat poistetaan, koska kysymys on maastosta — vihollisen alle jääminen on
   * eri testi ja se on jo olemassa. Tehostuksia ei anneta yhtään: voimataso 0
   * on se koko jolle lupaus on annettu. Se on samalla toinen puoli maahaniskun
   * lupauksesta: botti ei osaa maahaniskua eikä sitä pyydetä siltä, joten
   * kenttä joka vaatisi sitä jäisi tähän kiinni.
   */
  {
    /* Pystykentät jäävät pois, eivätkä vapautuksena vaan siksi että tämä botti
     * mittaisi niistä väärää asiaa: se juoksee oikealle, ja kahdenkymmenen
     * sarakkeen kentässä se on seinään käveleminen kahdessa sekunnissa. Sama
     * lupaus — maareitti aukeaa voimatasolla 0, `finishLevel` laukeaa — pätee
     * niihin täsmälleen yhtä kaatavana, ja se ajetaan kiipeilijällä lohkossa
     * "pystykentät kentissä". Yksikään kenttä ei siis putoa listalta. */
    const { getLevel: levelDef } = await import('/src/data/levels.js');
    const { isClimb } = await import('/tools/climb-bot.js');
    const { runGround } = await import('/tools/level-bot.js');
    /* `isClimb` eikä `.vertical`, ja se on korjaus eikä siistiminen: osioitu
     * kenttä (`7-P`) ei ole pystykenttä mutta sen toinen osio on nousu, ja
     * oikealle juokseva botti kävelee sen juurelle ja raportoi kentän
     * loppuneen sinne. Sama yksi rivi päättää asian täällä ja
     * `playable.mjs`:ssä, koska kaksi mielipidettä siitä kumpi botti ajaa
     * kenttää on juuri se vika jota tässä tiedostossa on nyt useasti
     * korjattu. */
    const handmade = levelIds().filter((id) => /^[678]-/.test(id) && !isClimb(levelDef(id)));
    const rows = [];
    for (const id of handmade) {
      reset({ type: null, level: 0 });
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      if (s.def.boss) s.bossDefeated = true;      // ovi on maali; tappelu on eri testi
      s.time = 9999;
      s.clockStopped = true;
      /*
       * `runGround` eikä oma botti, ja tämä on korjaus eikä siistiminen.
       *
       * Tässä oli kopio botista — yksinkertaisempi kuin `tools/level-bot.js`:n
       * oma — ja se tarkoitti kahta mielipidettä siitä mitä "läpäistävissä"
       * tarkoittaa. Ero näkyi ensimmäisen kerran sinä päivänä jona botille
       * kirjoitettiin uusi taito (lankkureitin ylitys, ks. `plankBridges`):
       * yksi portti kertoi kentän aukeavan ja toinen ettei se aukea, samasta
       * kentästä samana ajona. Se on tasan se vika jota tässä tiedostossa on
       * korjattu jo kahdesti muissa kohdissa.
       *
       * Sama botti, sama kehysbudjetti, sama lupaus. Ainoa asia joka tästä
       * lohkosta jää omaksi on **mitkä kentät ajetaan** ja **mitä siitä
       * raportoidaan**, ja ne ovat tämän lohkon oma kysymys.
       */
      const got = runGround(s, isSolid, 7000, () => finished);
      rows.push({
        id,
        cleared: got.cleared,
        reach: got.reach,
        bridged: got.bridged,
        stopped: got.died ? `kuoli sarakkeessa ${Math.floor(s.player.cx / 16)}`
          : `jumissa ${got.reach} %`,
      });
    }
    const stuck = rows.filter((r) => !r.cleared);
    /*
     * Luku johdetaan kentistä eikä kirjoiteta käsin, ja lattia on erikseen.
     *
     * Tässä luki `rows.length === 14`, joka oli maailmojen 6, 7 ja 8 yhteinen
     * kenttämäärä sinä päivänä kun se kirjoitettiin (4 + 4 + 6). Se kaatui
     * ensimmäisenä päivänä jona joku teki sitä työtä jota ROADMAP pyytää —
     * mitattuna **22 kenttää, odotettiin 14** — eikä yhdellekään kentälle
     * tapahtunut mitään. Portti joka kaatuu oikeasta työstä sammutetaan.
     *
     * Ehto on siksi kaksiosainen: **jokainen löydetty kenttä ajettiin** (eli
     * silmukka ei pudottanut yhtään hiljaa) ja **niitä on vähintään se määrä
     * mikä pelissä tänään on**. Jälkimmäinen on lattia eikä yhtäsuuruus, joten
     * maailman 8 neljä puuttuvaa kenttää nostavat sitä eivätkä kaada tätä.
     *
     * **Ja lattia lasketaan kaikista kentistä, ei vain tässä ajetuista.**
     * Pystykentät ajetaan kiipeilijällä ("pystykentät kentissä"), koska tämä
     * botti juoksee oikealle; jos ne vain putoaisivat tästä silmukasta, lattia
     * laskisi kahdella ja väite kattaisi hiljaa kaksi kenttää vähemmän. Luku 22
     * on siis edelleen se mitä maailmoissa 6–8 on, ja jakauma sanotaan ääneen.
     */
    const climbers = levelIds().filter((id) => /^[678]-/.test(id) && isClimb(levelDef(id)));
    expect('maailmojen 6–8 jokainen kenttä on läpäistävissä voimatasolla 0',
      rows.length === handmade.length && rows.length + climbers.length >= 22
      && stuck.length === 0,
      rows.length
        ? `${rows.length} vaakakenttää: ${rows.map((r) => `${r.id} ${r.cleared ? 'läpi' : r.stopped}`
          + (r.bridged ? ` (${r.bridged} lankkureittiä ratkaisijan todistamana)` : '')).join(', ')}`
          + ` — ja ${climbers.length} pystykenttää kiipeilijällä (${climbers.join(' ') || '—'})`
        : 'ei 6-, 7- eikä 8-kenttiä lainkaan');
  }

  /* --------------------- kaasulyhty oikeissa kentissä -------------------- */
  /*
   * TARKISTUSPISTE ON UUSI LÄHTÖRUUTU, JA SIITÄ ON PÄÄSTÄVÄ MAALIIN.
   *
   * Tämä on se ainoa tapa jolla lyhty voi rikkoa kentän, ja se rikkoisi sen
   * pahimmalla mahdollisella tavalla: pelaaja kuolee, herää lyhdyltä, eikä
   * pääse siitä eteenpäin — eli kenttä on umpikuja jonka kaikki *muut* portit
   * kertovat läpäistäväksi, koska ne mittaavat sitä alusta.
   *
   * `plantLamp` yrittää estää sen etukäteen (tasainen lattia, kolme riviä
   * ilmaa, ei vaaroja vieressä), mutta se on paikallinen ehto. Reitti eteenpäin
   * on kentän mittainen kysymys, ja kentän mittaiseen kysymykseen vastaa botti.
   * Sama botti, sama lupaus voimatasolla 0 kuin kentän alussa — vain lähtöruutu
   * on eri.
   */
  {
    const { runGround } = await import('/tools/level-bot.js');
    const rows = [];
    for (const id of levelIds()) {
      reset({ type: null, level: 0 });
      // Ensin kenttä sellaisenaan: onko siinä lyhtyä, ja missä.
      const probe = new LevelScene(game, id);
      if (probe.lampCol === null) continue;
      // Ja sitten sama kenttä niin kuin se avataan kuoleman jälkeen.
      game.state.checks[id] = probe.lampCol;
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      if (s.def.boss) s.bossDefeated = true;
      s.time = 9999;
      s.clockStopped = true;
      const startCol = Math.floor(s.player.cx / 16);
      /* Puolet kentästä on jäljellä, joten puolet kehysbudjetista: 4000 framea
       * on 67 s, ja mitattu koko kentän juoksu on ~36 s. */
      const got = runGround(s, isSolid, 4000, () => finished);
      rows.push({ id, col: startCol, w: s.w, cleared: got.cleared, reach: got.reach });
      game.finishLevel = () => {};
    }
    const stuck = rows.filter((r) => !r.cleared);
    expect('jokaisesta kaasulyhdystä pääsee maaliin voimatasolla 0',
      rows.length > 0 && stuck.length === 0,
      rows.length
        ? `${rows.length} kenttää lyhdyllä: `
          + rows.map((r) => `${r.id} ${r.col}/${r.w}${r.cleared ? '' : ` JUMISSA ${r.reach} %`}`).join(', ')
        : 'yhdessäkään kentässä ei ole lyhtyä — raja LAMP_MIN_COLS on liian korkea');
  }

  /* ------------------ putkesta tullaan ulos putkesta --------------------- */
  /*
   * OMISTAJAN HAVAINTO 16.8.2026: luolasta noustessa hahmo ilmestyy tyhjästä.
   *
   * Se oli totta, ja se oli mitattavissa: pelin **jokainen kymmenestä
   * kaistamatkasta päättyi paljaaseen ilmaan**, pahimmillaan neljä ruutua
   * lattian yläpuolelle. `tryWarp` säilytti suhteellisen korkeuden ja tarkisti
   * vain että keho mahtuu ja että jotain kiinteää on jossain alla — kumpikaan
   * ei ole väärin, mutta yhdessä ne tarkoittivat että matkan pää on se kohta
   * johon lähtökorkeus sattuu osoittamaan.
   *
   * Tämä portti mittaa tapahtumaa eikä ruudukkoa: **matkustetaan oikeasti** ja
   * katsotaan mitä jalkojen alla on perillä. Kaksi ehtoa, ja molemmat ovat
   * pelaajan näkemiä asioita: jalat ovat sen putken päällä joka matkan päähän
   * pystytettiin, ja siitä noustaan (`farHide`) eikä pudota siihen.
   */
  {
    const { T, info } = await import('/src/gfx/tiles.js');
    const { getLevel: levelDefOf } = await import('/src/data/levels.js');
    const trips = [];
    for (const id of levelIds()) {
      if (!levelDefOf(id).bands) continue;
      reset({ type: null, level: 0 });
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      for (const [key, exitRow] of s.warpExits) {
        const [tx, ty] = key.split(',').map(Number);
        if (info(s.grid[ty][tx - 1]).warp) continue;   // sama suu vain kerran
        const down = s.grid[ty - 1][tx] === T.EMPTY;   // ilmaa päällä = matka alas
        const p = s.player;
        p.x = tx * 16;
        if (down) p.y = ty * 16 - p.h;
        else {
          let f = ty + 1;
          while (f < s.h && !isSolid(s.grid[f][tx])) f++;
          p.y = f * 16 - p.h;
        }
        p.vx = 0; p.vy = 0; p.onGround = true; p.warpLock = 0; p.transit = null;
        s.centerCamera();
        const i = mkInput();
        i.held = blank();
        i.held[down ? 'down' : 'up'] = true;
        let travelled = false;
        let rose = false;
        for (let f = 0; f < 200; f++) {
          s.update(i);
          i.pressed = blank();
          if (p.transit) {
            travelled = true;
            // Noustaanko perillä ylös? Kaukopään leikkuri on se joka sen tekee.
            if (p.transit.phase === 'out' && p.y > p.transit.arriveY) rose = true;
          } else if (travelled) break;
        }
        const feet = Math.floor((p.y + p.h) / 16);
        const under = s.grid[Math.min(s.h - 1, feet)][Math.floor(p.cx / 16)];
        trips.push({
          id, tx, ty, down, exitRow, feet, rose, travelled,
          onPipe: info(under).pipe,
          ok: travelled && rose && info(under).pipe && feet === exitRow,
        });
      }
    }
    const bad = trips.filter((t) => !t.ok);
    expect('jokainen kaistamatka päättyy putkeen, ja siitä noustaan ylös',
      trips.length >= 10 && bad.length === 0,
      bad.length
        ? bad.map((t) => `${t.id} ${t.tx},${t.ty}: jalat ${t.feet} (pari ${t.exitRow}), `
          + `putki ${t.onPipe}, nousi ${t.rose}`).join('; ')
        : `${trips.length} matkaa, jokainen päättyi putken suulle `
          + `(${trips.filter((t) => t.down).length} alas, ${trips.filter((t) => !t.down).length} ylös)`);
  }

  /* ----------------------------- pilvimaailma ---------------------------- */
  /*
   * Maailma 7, KAASUKEHÄ, ja kaksi ongelmaa jotka se on olemassa ratkaistakseen.
   * Molemmat ovat sellaisia joihin maailma voi vastata väärin *ja silti näyttää
   * valmiilta*, joten molemmat mitataan tässä eikä perustella kommentissa.
   *
   * ONGELMA 1: PELISSÄ ON JO TAIVAS. Jokaisen korkean kentän yllä on
   * taivaskaista, ja `sky_garden` on jo paikka joka on tehty lavoista ilmassa.
   * Jos kokonainen pilvimaailma lukee samalta, se ei ole uusi maailma vaan
   * venytetty bonushuone — ja pahempaa, se halventaa salaisuuden jonka
   * löydettäväksi tekeminen oli oikeaa työtä. Ero on tehty **lattiasta** ja se
   * on siksi mitattavissa: bonushuoneessa ei ole lattiaa lainkaan, ja kaikki
   * mille siellä voi astua on lautaa. Testi 3 laskee molemmat luvut molemmista.
   *
   * ONGELMA 2: PILVISTÄ TEHTY MAAILMA ON KUOPPA KOKO PITUUDELTAAN. Vastaus on
   * kirjoitettu palikoihin ja tarkistetaan testeissä 1 ja 2: **tiivistynyt
   * pilvi on maata**, eli lattia on tavallista `#`:ää, ja **ohut pilvi (`-`) ei
   * ole koskaan tyhjän päällä**. Jälkimmäinen on se puolisko joka ostaa
   * puoliläpäisevän lavan tähän maailmaan ilman sen omaa ansaa — alas
   * painaminen vahingossa ei voi pudottaa tyhjään, koska tässä maailmassa
   * lavan alla on aina pilveä.
   */
  {
    const { CLOUD_CHUNKS } = await import('/src/data/chunks/cloud.js');
    const { BONE_CHUNKS } = await import('/src/data/chunks/bone.js');
    const { CHUNKS } = await import('/src/data/chunks.js');

    /*
     * 1. EI JALKOJA, ja se on luumaailman ehdon peilikuva.
     *
     * `chunks/bone.js` perustelee itsensä yhdellä lauseella: luu seisoo, eli
     * jokainen `X` ja `#` lattian yläpuolella nojaa johonkin suoraan allaan,
     * koska luuranko on määritelmän mukaan asia joka kannattaa itsensä. Pilvi
     * on määritelmän mukaan asia joka **ei** kannata itseään, joten sääntö
     * kulkee tässä täsmälleen toisin päin:
     *
     *   **mikään ei seiso maassa — kaikki pystysuunta leijuu.**
     *
     * Ei kukkuloita, ei portaita, ei hautakiviä: lattian yläpuolella ei ole
     * yhtään `#`:ää eikä `X`:ää. Se maksaa saman kuin luumaailman sääntö maksoi
     * — koko `steps_up`/`ledge`-sanasto on poissa käytöstä, ja korkeus on
     * ostettava laudalla ja lohkolla — ja se on juuri se hinta jonka takia
     * sääntö kannattaa kirjoittaa: se pakottaa maailman siluetin erilaiseksi
     * kuin yhdenkään edellisen.
     *
     * Luumaailma mitataan tässä vastapariksi eikä kohteliaisuudesta: jos
     * molemmat luvut olisivat nollia, sääntö ei erottaisi mitään.
     */
    const STANDS = '#X';
    const legsIn = (chunks) => {
      const out = [];
      for (const [name, chunk] of Object.entries(chunks)) {
        for (let y = 0; y < 13; y++) {
          for (let x = 0; x < chunk.w; x++) {
            if (STANDS.includes(chunk.rows[y][x])) out.push(`${name} ${x},${y}`);
          }
        }
      }
      return out;
    };
    const cloudLegs = legsIn(CLOUD_CHUNKS);
    const boneLegs = legsIn(BONE_CHUNKS);
    expect('pilvimaailmassa mikään ei seiso maassa, luumaailmassa kaikki seisoo',
      cloudLegs.length === 0 && boneLegs.length > 0,
      `${Object.keys(CLOUD_CHUNKS).length} pilvipalikkaa, maasta nousevia ruutuja `
      + `${cloudLegs.length} — luussa ${boneLegs.length}`
      + (cloudLegs.length ? `: ${cloudLegs.slice(0, 5).join(' ')}` : ''));

    /*
     * 2. OHUT PILVI EI OLE KOSKAAN TYHJÄN PÄÄLLÄ.
     *
     * Puoliläpäisevä lava on ollut pelissä alusta asti ja siinä on yksi ansa,
     * joka on aina ollut siedettävä siksi että lavoja on ollut vähän: alas
     * painaminen pudottaa lävitse, ja jos lavan alla ei ole mitään, se pudottaa
     * kuoppaan. Maailma jonka koko pystysuunta on lautaa moninkertaistaa sen
     * ansan — joten tässä maailmassa jokaisen `-`:n alla on samassa sarakkeessa
     * kiinteää pilveä.
     *
     * Sääntö on ehdoton eikä ohje, ja sillä on hintansa: **tässä maailmassa
     * yksikään lauta ei ylitä kuoppaa.** Jokainen reikä pilvessä hypätään.
     * Muualla pelissä lauta kuopan yllä on tavallinen ja hyvä ratkaisu
     * (`pit_l`, `sky_run`, `bone_ribs`, `sky_garden`), ja alla oleva luku
     * mittaa juuri ne — jos se olisi nolla, sääntö ei kieltäisi mitään.
     */
    const hanging = (chunks) => {
      let count = 0;
      const where = [];
      for (const [name, chunk] of Object.entries(chunks)) {
        for (let y = 0; y < 15; y++) {
          for (let x = 0; x < chunk.w; x++) {
            if (chunk.rows[y][x] !== '-') continue;
            let held = false;
            for (let below = y + 1; below < 15; below++) {
              if (STANDS.includes(chunk.rows[below][x])) { held = true; break; }
            }
            if (!held) { count++; if (where.length < 5) where.push(`${name} ${x},${y}`); }
          }
        }
      }
      return { count, where };
    };
    const cloudHang = hanging(CLOUD_CHUNKS);
    const elsewhere = hanging(Object.fromEntries(
      Object.entries(CHUNKS).filter(([name]) => !name.startsWith('cloud_'))));
    expect('pilvimaailmassa yksikään ohut pilvi ei leiju tyhjän päällä',
      cloudHang.count === 0 && elsewhere.count > 0,
      `pilvimaailma ${cloudHang.count}, muu peli ${elsewhere.count}`
      + (cloudHang.count ? `: ${cloudHang.where.join(' ')}` : ` (esim. ${elsewhere.where.join(' ')})`));
  }

  /*
   * 3. TÄMÄ EI OLE VENYTETTY BONUSHUONE, JA SE ON MITATTU.
   *
   * Kaksi lukua per kenttä, ja ne ovat kaksi eri kysymystä:
   *
   *   **maaosuus** — kuinka monessa sarakkeessa on kiinteää lattiaa. Se on
   *   vastaus kysymykseen "onko täällä lattia": paikassa on lattia, huoneessa
   *   ei ole.
   *   **lautaosuus astuttavasta** — kuinka suuri osa kaikesta mille voi astua
   *   on ohutta pilveä. Se on vastaus kysymykseen "mistä täällä kuljetaan":
   *   bonushuoneessa vastaus on sata prosenttia, koska siellä ei ole muuta.
   *
   * `sky_garden` mitataan samoilla riveillä ja se antaa 0 % ja 100 %. Jos
   * pilvimaailman luvut lähestyvät noita, maailma on muuttunut siksi
   * bonushuoneeksi jota se ei saa olla, ja se näkyy tässä ennen kuin se näkyy
   * kenessäkään pelaajassa.
   *
   * Linnake 7-F jätetään pois tarkoituksella: se on jaettu `fort_*`-käytävä
   * niin kuin joka maailman linnake, ja sen lattiassa on laavaa. Väite koskee
   * niitä kolmea kenttää jotka ovat tämän maailman omia.
   */
  {
    const { getLevel } = await import('/src/data/levels.js');
    const { CHUNKS } = await import('/src/data/chunks.js');
    const SOLIDF = '#X';
    const shares = (rows, floorRow) => {
      const w = rows[0].length;
      let ground = 0;
      let planks = 0;
      let groundTiles = 0;
      for (let x = 0; x < w; x++) {
        const solid = SOLIDF.includes(rows[floorRow][x]) || SOLIDF.includes(rows[floorRow + 1][x]);
        if (solid) ground++;
        for (let y = 0; y < rows.length; y++) {
          if (rows[y][x] === '-') planks++;
          else if (SOLIDF.includes(rows[y][x])) groundTiles++;
        }
      }
      const footing = planks + groundTiles;
      return {
        ground: (ground / w) * 100,
        plank: footing ? (planks / footing) * 100 : 100,
        w,
      };
    };
    /* Kaksi eikä kolme, ja se on rajaus eikä löysennys: `7-2`:n paikalla on
     * nyt pystykenttä `7-T`, jossa ei ole riviä 13 sen enempää kuin
     * lattiariviäkään — `shares` lukisi siitä mielivaltaisen rivin ja
     * raportoisi luvun joka ei mittaa mitään. Sama väite tehdään sille omalla
     * akselillaan lohkossa "pystykentät kentissä": puolet sen jalansijasta on
     * pakattua pilveä, bonushuoneen nollaa vastaan. Väite koskee siis edelleen
     * jokaista tämän maailman omaa kenttää. */
    const levels = ['7-1', '7-3'].map((id) => ({ id, ...shares(getLevel(id).rows, 14) }));
    const garden = shares(CHUNKS.sky_garden.rows, 13);
    const worstGround = levels.reduce((m, l) => Math.min(m, l.ground), 100);
    const worstPlank = levels.reduce((m, l) => Math.max(m, l.plank), 0);
    expect('pilvimaailmassa on lattia, bonushuoneessa ei — mitattuna molemmat',
      levels.length === 2 && worstGround >= 80 && worstPlank <= 25
      && garden.ground === 0 && garden.plank === 100,
      `${levels.map((l) => `${l.id} maata ${l.ground.toFixed(0)} % / lautaa `
        + `${l.plank.toFixed(0)} % (${l.w} saraketta)`).join(', ')}`
      + ` — sky_garden maata ${garden.ground.toFixed(0)} % / lautaa ${garden.plank.toFixed(0)} %`);
  }

  /*
   * 4. MAAHANISKULLA ON TÄSSÄ MAAILMASSA TILAA, MUTTEI VALTAA.
   *
   * Maahanisku (v26.08.09.31) normalisoi voimansa kentän omaa kattoa vasten,
   * joten se on sitä kovempi mitä korkeammalta se aloitetaan — ja kerroksittain
   * ladottu pilvimaailma on ainoa paikka pelissä jossa korkeutta on tarjolla
   * ilman että sitä pitää erikseen rakentaa. Väite on kaksiosainen ja
   * molemmat puolet mitataan:
   *
   *   - **alasimelta pudotettuna isku tappaa.** Maailman ylin lauta on
   *     `cloud_anvil`in kansi, ja siltä alkava sukellus ylittää
   *     POUND_KILL_AT-rajan (0,5) mitattuna eikä laskettuna.
   *   - **lattialta hypättynä se ei tapa.** Sama liike tavallisen seisonnasta
   *     tehdyn hypyn huipulta jää rajan alle, eli korkeus on se mikä ostaa
   *     tappavuuden — ei tehostus eikä tämä maailma.
   *
   * Ja kolmas puoli on jo tarkistettu muualla: kohdan 3 botti ei osaa
   * maahaniskua lainkaan ja läpäisee silti jokaisen 7-kentän voimatasolla 0,
   * eli liike avaa paikkoja eikä kenttää (DESIGN.md kohta 5).
   */
  {
    const { getLevel } = await import('/src/data/levels.js');
    /* Ylin lauta koko maailmassa, ja siitä se sarake jonka vierestä pääsee
     * putoamaan lattiaan asti — sukellus jonka jalat ovat jo kannen päällä ei
     * mittaa mitään, koska se laskeutuu sille kannelle. */
    let top = null;
    /* Sama rajaus kuin kohdassa 3 ja samasta syystä: pystykentässä `7-T`:ssä
     * rivit 0..13 eivät ole taivas vaan kiipeilyä, ja tämä silmukka etsii
     * maailman ylintä *lautaa lattian yläpuolelta*. Se löytäisi sieltä lavan
     * riviltä 5 ja mittaisi sukelluksen kentässä jossa ei ole lattiaa mihin
     * sukeltaa. `cloud_anvil` on edelleen `7-3`:ssa, eli väite mittaa saman
     * kannen kuin ennen. */
    for (const id of ['7-1', '7-3']) {
      const rows = getLevel(id).rows;
      for (let y = 0; y < 14 && (!top || y < top.y); y++) {
        for (let x = 0; x < rows[y].length - 1; x++) {
          if (rows[y][x] !== '-' || rows[y][x + 1] === '-') continue;
          let clear = true;
          for (let d = y; d <= 13; d++) if (rows[d][x + 1] !== ' ') clear = false;
          if (!clear || rows[14][x + 1] !== '#') continue;
          top = { id, x: x + 1, y };
          break;
        }
      }
    }
    const dive = (id, place) => {
      reset({ type: null, level: 0 });
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      const i = mkInput();
      const step = (held = {}, pressed = {}) => {
        i.held = { ...blank(), ...held };
        i.pressed = { ...blank(), ...pressed };
        s.update(i);
      };
      place(s.player, step);
      step({ down: true, jump: true }, { down: true, jump: true });
      for (let f = 0; f < 240 && !s.lastPound; f++) step({ down: true });
      return s.lastPound;
    };
    const fromDeck = top && dive(top.id, (p) => {
      p.x = top.x * 16 + 1;
      p.y = top.y * 16 - p.h;
      p.vx = 0;
      p.vy = 0;
      p.onGround = false;
    });
    const fromFloor = top && dive(top.id, (p, step) => {
      p.x = top.x * 16 + 1;
      p.y = 14 * 16 - p.h;
      for (let f = 0; f < 20; f++) step();
      step({ jump: true }, { jump: true });
      for (let f = 0; f < 60 && p.vy < 0; f++) step({ jump: true });
    });
    /* Rivi 6 on `cloud_anvil`in kansi, ja se on osa väitettä eikä sen kuvaus:
     * maailma jonka ylin lauta valuisi alaspäin lakkaisi olemasta se paikka
     * jossa liikkeellä on tilaa, ja tekisi sen huomaamatta. */
    expect('pilvimaailman ylimmältä laudalta maahanisku tappaa, lattiahypystä ei',
      !!fromDeck && !!fromFloor && top.y <= 6 && fromDeck.kills && !fromFloor.kills,
      top
        ? `ylin lauta ${top.id} rivi ${top.y}: voima ${fromDeck ? fromDeck.strength.toFixed(2) : '—'}`
        + ` (${fromDeck && fromDeck.kills ? 'tappaa' : 'ei tapa'}), lattiahypystä `
        + `${fromFloor ? fromFloor.strength.toFixed(2) : '—'}`
        + ` (${fromFloor && fromFloor.kills ? 'tappaa' : 'ei tapa'})`
        : 'yhtään lautaa ei löytynyt maailmasta 7');
  }

  /* --------------------------- viimeinen linnake -------------------------- */
  /*
   * MAAILMA 8, VIIMEINEN LINNAKE, ja se yksi väite jonka takia se on olemassa:
   * **finaali on eri muotoinen kuin maailma jonka perässä on linnake.**
   *
   * Tämä on eri testijoukko kuin luulaakson ja pilvimaailman omat, ja se on
   * eri asiasta. Maailmoilla 6 ja 7 oli uusi teema, ja niiden mittaukset
   * kysyivät onko teema oikeasti oma (lattia, siluetti, palikoiden ehdot).
   * Maailmalla 8 ei ole uutta teemaa eikä saa olla — teemalista on täysi
   * (ROADMAP 9.8.2026) — joten sen ero on **rakenteessa**, ja rakenne on
   * mitattavissa täsmälleen samalla ankaruudella.
   *
   * Kuusi mittausta, ja jokainen on sellainen jonka maailma voi rikkoa *ja
   * silti näyttää valmiilta*:
   *
   *   1  muoto     kuusi askelta neljän sijaan
   *   2  katto     ei ulkopuolta: joka sarakkeen yllä on kiveä
   *   3  ovi       ei yhtään lippua, kuusi ovea
   *   4  pomot     jokainen pelin pomo, eikä yksikään kahdesti
   *   5  tiili     tiili ei kosketa kiveä, koska paletti ei erota niitä
   *   6  vauhti    jokaisen kuilun edessä on täysi vauhdinotto
   *
   * Nollatestinä on aina muu peli. Jos maailma 8 on ainoa jossa luku on se mikä
   * se on, väite erottaa jotain; jos kaikki maailmat antavat saman luvun, väite
   * ei sano mitään ja testi on koriste.
   */
  {
    const { getLevel, levelIds } = await import('/src/data/levels.js');
    const { tiersOf } = await import('/src/data/worlds.js');
    const { THEMES, T, drawTile } = await import('/src/gfx/tiles.js');

    /* Pystykentät pois vertailuluvusta, ja se on rajaus eikä vapautus: jokainen
     * väite alla lukee riviä 13 ("lattia") ja kysyy mitä sen edessä on
     * *sivusuunnassa*. Kiipeilyssä ei ole riviä 13 sen enempää kuin
     * lattiariviäkään, ja `routeOf` palauttaisi sille viisi riviä ruudukon
     * pohjalta — vertailuluku laskettaisiin siis ruudukosta jota ei ole. Väite
     * on vaakakenttien väite ja mitataan vaakakentistä. */
    const ids = levelIds().filter((id) => !getLevel(id).vertical);
    const inWorld = (n) => ids.filter((id) => id.startsWith(`${n}-`));
    const w8 = inWorld(8);
    const FLOOR = 14;
    const STONE = '#X';
    /* Sama kaistasääntö kuin `rules.js`:llä ja vaikeusmittarilla: reitti on se
     * viisitoista riviä joilla pelaaja aloittaa. Ilman tätä korkean kentän
     * ylimmät rivit olisivat taivaskaistan omia, ja "katto" mitattaisiin
     * bonushuoneen katosta. Maailmassa 8 ei ole yhtään korkeaa kenttää, joten
     * tämä koskee pelkästään vertailulukua — ja vertailuluku on tässä koko
     * väitteen toinen puolisko. */
    const routeOf = (id) => {
      const rows = getLevel(id).rows;
      if (rows.length <= 16) return rows;
      const start = rows.findIndex((row) => row.includes('1'));
      /* Kiinni ruudukon pohjaan, ja se on korjaus eikä varovaisuutta: kaista on
       * 16 riviä mutta jokainen korkea kenttä ei ole kaistojen monikerta —
       * osioitu 7-P on 45 riviä, ja sen aloitusmerkki on niin alhaalla että
       * `top + 16` menisi ruudukon yli. Ennen 18.8.2026 sitä ei voinut
       * huomata, koska 45 on tasan kolme viidentoista kaistaa. */
      const top = Math.min(Math.floor(Math.max(start, 0) / 16) * 16, rows.length - 16);
      return rows.slice(top, top + 16);
    };

    /*
     * 1. JOKAINEN ASKEL ON TAPPELU, EIKÄ VAIN VIIMEINEN.
     *
     * **Tässä luki 9.8.2026 asti "viimeinen maailma on kuusi askelta, muut
     * neljä", ja se väite jouduttiin vaihtamaan.** Syy kannattaa lukea, koska se
     * on esimerkki portista joka mittasi oikein mutta väitti väärää asiaa.
     *
     * Väite oli **kahden luvun erotus**: kuusi vastaan neljä. Toinen puolisko
     * niistä luvuista — muiden maailmojen neljä — ei ollut maailman 8
     * ominaisuus lainkaan vaan sen ajan hetken ominaisuus jolloin jokainen muu
     * maailma oli kolme kenttää ja linnake. ROADMAPin oma tavoite (kahdeksan
     * kenttää joka maailmaan) tekee siitä epätoden ensimmäisenä päivänä jona
     * joku alkaa tehdä sitä työtä, eikä maailmalle 8 tapahdu silloin mitään.
     * Portti olisi siis kaatunut oikeasta työstä, ja portti joka kaatuu
     * oikeasta työstä sammutetaan.
     *
     * Tilalle väite joka kestää minkä tahansa kenttämäärän, koska se on
     * **osuus eikä lukumäärä**: viimeisessä linnakkeessa jokainen askel päättyy
     * tappeluun, muualla vain viimeinen. Mitattuna maailma 8 on 6/6 = 100 % ja
     * jokainen muu 1/n — ja kun maailmat kasvavat kahdeksaan kenttään, tämä
     * väite **vahvistuu** eikä heikkene: nimittäjä kasvaa, osuus pienenee.
     *
     * Nollatestinä yhä muu peli, samalla koodilla. Jos jokainen maailma antaisi
     * saman osuuden, väite ei erottaisi mitään.
     */
    const steps = WORLDS.map((w) => {
      const tiers = tiersOf(w);
      const fights = tiers.filter((t) => t.levels.some((id) => getLevel(id).boss)).length;
      return { id: w.id, n: tiers.length, fights, share: (fights / tiers.length) * 100 };
    });
    const last = steps[steps.length - 1];
    const rest = steps.slice(0, -1);
    expect('viimeisessä maailmassa jokainen askel on tappelu, muualla vain viimeinen',
      steps.length === 8 && last.id === 'w8' && last.share === 100 && last.n >= 6
      && rest.every((s) => s.fights === 1 && s.share <= 25),
      steps.map((s) => `${s.id} ${s.fights}/${s.n} = ${s.share.toFixed(0)} %`).join(', '));

    /*
     * 2. EI ULKOPUOLTA.
     *
     * Luumaailman ehto oli "taivas on auki", pilvimaailman "mikään ei seiso
     * maassa". Viimeisen linnakkeen ehto on se kolmas, ja se on molempien
     * vastakohta: **kaikkien yllä on kiveä.** Jokaisessa sarakkeessa,
     * jokaisessa kentässä, ensimmäisestä ruudusta viimeiseen.
     *
     * Se on myös syy siihen miksi maailmalla on oma `keep_start`: pelin
     * jokainen linnake alkaa jaetulla `start`-palikalla, jonka kaksi ylintä
     * riviä ovat tyhjiä, eli jokaisen linnakkeen ensimmäiset kuusitoista
     * saraketta ovat tähän asti olleet taivasta katon sijaan. Yhden kentän
     * huoneessa sitä ei huomaa; maailmassa joka väittää olevansa sisätila se on
     * reikä väitteen läpi.
     *
     * Muu peli mitataan samalla koodilla, koska ilman sitä tämä luku olisi vain
     * sata prosenttia jostakin — ja vertailuluku sanoo tässä jotain mitä ei
     * osannut odottaa: **tehdas on 57 %.** Maailma 4 on sisätila kolmessa
     * kentässä neljästä, eli "katto" ei yksin erota mitään. Väite on siksi
     * sata vastaan viisikymmentäseitsemän eikä sata vastaan nolla: maailma 8
     * on ainoa jossa ei ole yhtään saraketta taivasta, ja lähin kilpailija on
     * kahden kentän päässä siitä.
     */
    const roofShare = (id) => {
      const rows = routeOf(id);
      const w = rows[0].length;
      let roofed = 0;
      for (let x = 0; x < w; x++) {
        /*
         * Rivit 0-1, ja ne pysyivät siellä vaikka kaikki muu siirtyi rivin
         * alaspäin 18.8.2026. Tämä oli hetken 1-2, ja se oli väärin tavalla
         * joka kannattaa lukea: kokoajan lisäämä taivasrivi on **kopio
         * ylimmästä**, joten linnakkeen kansi näkyy riveillä 0 ja 1 kuten
         * ennenkin — mutta tehtaan kansi asuu riveillä 2-3, ja rivin 2
         * lukeminen laski senkin katoksi. Maailma 4 hyppäsi 56,6 %:sta 78
         * %:iin ja vertailu lakkasi erottamasta mitään.
         *
         * Väite on "ylimmässä kahdessa rivissä on kiveä", ja ylimmät kaksi
         * riviä ovat 0 ja 1 riippumatta siitä montako rivejä kentässä on.
         */
        if (STONE.includes(rows[0][x]) || STONE.includes(rows[1][x])) roofed++;
      }
      return (roofed / w) * 100;
    };
    const roofOf = (n) => {
      const levels = inWorld(n);
      const tot = levels.reduce((s, id) => s + getLevel(id).rows[0].length, 0);
      const roofed = levels.reduce((s, id) => s + (roofShare(id) / 100)
        * getLevel(id).rows[0].length, 0);
      return (roofed / tot) * 100;
    };
    const roofs = [1, 2, 3, 4, 5, 6, 7, 8].map((n) => ({ n, share: roofOf(n) }));
    const w8roof = roofs[7];
    const runnerUp = roofs.slice(0, 7).reduce((m, r) => (r.share > m.share ? r : m), roofs[0]);
    const openest = w8.map((id) => ({ id, share: roofShare(id) }))
      .sort((a, b) => a.share - b.share)[0] || { id: '—', share: 0 };
    expect('viimeisessä linnakkeessa ei ole ulkopuolta: joka sarakkeen yllä on kiveä',
      w8.length > 0 && w8roof.share === 100 && openest.share === 100
      && runnerUp.share <= 60,
      roofs.map((r) => `w${r.n} ${r.share.toFixed(0)} %`).join(', ')
      + ` — avoimin 8-kenttä ${openest.id} ${openest.share.toFixed(0)} %,`
      + ` seuraavaksi suljetuin maailma w${runnerUp.n} ${runnerUp.share.toFixed(0)} %`);

    /*
     * 2 b. JA SE MIKÄ SEN VÄITTEEN VOI RIKKOA ILMAN ETTÄ MAAILMA 8 MUUTTUU:
     * **GENEROITU TEHDASKENTTÄ.**
     *
     * Yllä oleva portti on `runnerUp.share <= 60`, ja lähin kilpailija on
     * maailma 4 (mitattuna 56,6 %). Se on neljän kentän päässä katosta ja
     * neljä uutta kenttää on tulossa. Generaattorin `ceilingPass(c, 3)` maalasi
     * `X`:n riville 3 **ja jokaiselle riville sen yläpuolella**, eli myös
     * riveille 0 ja 1 — täsmälleen ne kaksi riviä joilta tämä osuus mitataan.
     * Neljä sellaista kenttää nostaa maailman 4 osuuden kohti sataa, ja
     * finaalin väite lakkaa erottamasta mitään ilman että maailmaan 8 on
     * koskettu.
     *
     * Generaattorin oma kommentti sanoi jo oikean säännön — *"tehtaan kansi
     * roikkuu rivillä 2 ja alempana: sisätila jonka koneiston näkee"* — mutta
     * koodi teki toisin, eikä mikään mitannut kumpaa se teki. Tässä se
     * mitataan: **yksikään generoitu kenttä joka ei ole linnake ei kata
     * rivejä 0–1.** Linnake on nimetty poikkeus eikä aukko, koska sen oma ehto
     * (`ruleKeepRoof`) vaatii täsmälleen päinvastaista.
     *
     * Väite on generoiduista kentistä eikä maailmasta 4, ja se on tahallista:
     * sama kansi tulisi maailman 5 tehdaskenttään ja maailman 8 kenttiin
     * samalla rivillä koodia, joten portti joka katsoo vain maailmaa 4
     * huomaisi vian vasta siinä maailmassa jossa se sattui ensin näkymään.
     */
    const { GENERATED_LEVELS } = await import('/src/data/generated.js');
    const genRoofed = Object.entries(GENERATED_LEVELS)
      .filter(([, def]) => def.theme !== 'fortress')
      .map(([id]) => ({ id, share: roofShare(id) }))
      .filter((r) => r.share > 0);
    const genFactory = Object.entries(GENERATED_LEVELS)
      .filter(([, def]) => def.theme === 'factory').map(([id]) => id);
    expect('generoitu kenttä ei kata rivejä 0–1, eli tehdas ei nosta maailman 4 katto-osuutta',
      genRoofed.length === 0,
      `${Object.keys(GENERATED_LEVELS).length} generoitua kenttää, niistä `
      + `${genFactory.length} tehdaskenttää (${genFactory.join(' ') || '—'}); `
      + `katettuja ${genRoofed.length}`
      + (genRoofed.length ? `: ${genRoofed.map((r) => `${r.id} ${r.share.toFixed(0)} %`).join(', ')}` : '')
      + ` — w4 ${roofOf(4).toFixed(1)} %`);

    /*
     * 3. EI LIPPUA, VAAN OVI.
     *
     * Lippu on se merkki jolla tämä peli sanoo "kenttä loppui"; ovi on se jolla
     * se sanoo "pomo kaatui". Jokaisessa maailmassa on tähän asti ollut kolme
     * lippua ja yksi ovi, ja se järjestys *on* se kaava jonka finaalin pitää
     * rikkoa: viimeisessä linnakkeessa ei ole yhtään lippua, koska siellä ei
     * ole yhtään huonetta josta pääsee ulos kävelemällä.
     */
    const flagsIn = (id) => getLevel(id).rows
      .reduce((s, row) => s + [...row].filter((ch) => ch === T.GOAL).length, 0);
    const worldFlags = [1, 2, 3, 4, 5, 6, 7, 8].map((n) => ({
      n,
      flags: inWorld(n).reduce((s, id) => s + flagsIn(id), 0),
      doors: inWorld(n).filter((id) => getLevel(id).boss).length,
    }));
    /*
     * **Luku oli "kuusi ovea" 10.8.2026 asti, ja se vaihtui osuudeksi samasta
     * syystä kuin askelten luku vaihtui kohdassa 1.** Kuusi ei ollut maailman
     * ominaisuus vaan sen hetken, jolloin maailmassa oli kuusi kenttää, joten
     * portti olisi kaatunut siitä oikeasta työstä joka kasvatti maailman
     * kahdeksaan (ROADMAPin avoin kysymys 1). Väite on nyt **ovi joka
     * kentässä**, ja se vahvistuu kun maailma kasvaa: nimittäjä kasvaa
     * mukana.
     */
    const w8flags = worldFlags[7];
    const w8levels = inWorld(8).length;
    expect('viimeisessä maailmassa ei ole yhtään lippua vaan ovi joka kentässä',
      !!w8flags && w8flags.flags === 0 && w8levels >= 6 && w8flags.doors === w8levels
      && worldFlags.slice(0, 7).every((r) => r.flags >= 3 && r.doors === 1),
      worldFlags.map((r) => `w${r.n} ${r.flags} lippua / ${r.doors} ovea`).join(', ')
      + ` — w8 ${w8levels} kenttää`);

    /*
     * 4. JOKAINEN POMO JONKA LINNA ON LÄHETTÄNYT.
     *
     * `bossVariant` on ainoa kohta jossa pomot oikeasti eroavat toisistaan —
     * osumat, nopeus ja liikesarja tulevat siitä — ja finaali kerää ne kaikki.
     *
     * **Tässä luki "kerran kukin" 10.8.2026 asti, ja se ehto oli tosi vain
     * sattumalta.** Peli kuluttaa kuusi varianttia seitsemään linnakkeeseen,
     * koska jättiläinen on kahden linnakkeen pomo (4-F ja 5-F), joten
     * *varianttien* joukko ja *linnakkeiden* jono ovat eri asioita. Niin kauan
     * kuin maailma 8 oli kuusi kenttää ne sattuivat mahtumaan päällekkäin;
     * seitsemän uusinnan jälkeen eivät mahdu, ja "kerran kukin" olisi kieltänyt
     * juuri sen toiston joka on maailman koko lause.
     *
     * Joukko-oppi jää siis tähän vain siltä osin kuin se erottaa jotain —
     * **maailma 8 sisältää jokaisen pomon jonka peli tuntee, eikä yksikään muu
     * maailma sisällä kahta** — ja jonon oikeellisuus (mikä uusinta on missä
     * järjestyksessä) mitataan omassa lohkossaan, ks. `maailma 8 kahdeksaan`.
     */
    const variantsIn = (n) => new Set(inWorld(n).filter((id) => getLevel(id).boss)
      .map((id) => getLevel(id).bossVariant));
    const allVariants = new Set(ids.filter((id) => getLevel(id).boss)
      .map((id) => getLevel(id).bossVariant));
    const w8v = variantsIn(8);
    const others = [1, 2, 3, 4, 5, 6, 7].map((n) => ({ n, v: variantsIn(n) }));
    expect('viimeisessä linnakkeessa on jokainen pelin pomo',
      w8v.size === allVariants.size && [...allVariants].every((v) => w8v.has(v))
      && others.every((o) => o.v.size <= 1),
      `w8 ${[...w8v].sort().join(' ')} (${w8v.size} kpl), koko peli `
      + `${[...allVariants].sort().join(' ')} — muissa maailmoissa `
      + others.map((o) => `w${o.n} ${o.v.size}`).join(', '));

    /*
     * 5. TIILI EI KOSKETA KIVEÄ.
     *
     * Tämä on se velka jonka ROADMAP kirjasi maailmaa 8 varten: linnaketeeman
     * tiilen ja maan ero on koko pelin toiseksi huonoin heti yön jälkeen, ja
     * maailma joka on kokonaan linnaketta joutuu tekemään sille jotain. Uusi
     * paletti ei ole vaihtoehto — teemalista on täysi ja `THEMES.fortress` on
     * seitsemän maailman viimeisen kentän ulkonäkö, eli sen muuttaminen
     * muuttaisi valmiita kenttiä.
     *
     * Jäljelle jää rakenne, ja vastaus on rakenteellinen: **tässä maailmassa
     * tiili ei koskaan kosketa kiveä.** Kun kaksi lähes samanväristä ruutua
     * eivät ole vierekkäin, silmän ei tarvitse erottaa niitä toisistaan — ero
     * luetaan siitä että tiili leijuu ja kivi ei. Hinta on todellinen ja se on
     * se joka tekee tästä säännön: `brick_wall`in kaltainen lattialta nouseva
     * tiilipino on tässä maailmassa kielletty rakenne.
     *
     * Kontrasti mitataan tässä eikä muisteta, ja muu peli mitataan
     * kosketuksista samalla koodilla — jos sielläkin olisi nolla, sääntö ei
     * kieltäisi mitään.
     */
    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 64;
    const g8 = canvas.getContext('2d');
    const meanTile = (ch, theme) => {
      g8.clearRect(0, 0, 64, 64);
      drawTile(g8, ch, 0, 16, theme, 3, 5, 0, ' ', {});
      const d = g8.getImageData(0, 16, 16, 16).data;
      let r = 0; let gg = 0; let b = 0; let n = 0;
      for (let q = 0; q < d.length; q += 4) {
        if (d[q + 3] < 8) continue;
        r += d[q]; gg += d[q + 1]; b += d[q + 2]; n++;
      }
      return n ? [r / n, gg / n, b / n] : null;
    };
    const contrast = (theme) => {
      const a = meanTile(T.GROUND, theme);
      const b = meanTile(T.BRICK, theme);
      if (!a || !b) return 0;
      return ((Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2])) / 3 / 255)
        * 100;
    };
    const touches = (levels) => {
      let n = 0;
      const where = [];
      for (const id of levels) {
        const rows = getLevel(id).rows;
        for (let y = 0; y < rows.length; y++) {
          for (let x = 0; x < rows[y].length; x++) {
            if (rows[y][x] !== T.BRICK) continue;
            const near = [[1, 0], [-1, 0], [0, 1], [0, -1]]
              .some(([dx, dy]) => STONE.includes((rows[y + dy] || '')[x + dx] || ' '));
            if (near) { n++; if (where.length < 4) where.push(`${id} ${x},${y}`); }
          }
        }
      }
      return { n, where };
    };
    const w8touch = touches(w8);
    const gameTouch = touches(ids.filter((id) => !id.startsWith('8-')));
    const fortGap = contrast('fortress');
    const worstGap = Object.keys(THEMES)
      .map((th) => ({ th, gap: contrast(th) })).sort((a, b) => a.gap - b.gap);
    expect('viimeisessä linnakkeessa tiili ei kosketa kiveä, koska paletti ei erota niitä',
      w8.length > 0 && w8touch.n === 0 && gameTouch.n > 0 && fortGap < 10,
      `linnaketeema ${fortGap.toFixed(1)} % (huonoin ${worstGap[0].th} `
      + `${worstGap[0].gap.toFixed(1)} %, toiseksi huonoin ${worstGap[1].th} `
      + `${worstGap[1].gap.toFixed(1)} %) — kosketuksia maailmassa 8 ${w8touch.n}, `
      + `muualla ${gameTouch.n}${gameTouch.where.length ? ` (esim. ${gameTouch.where.join(' ')})` : ''}`
      + `${w8touch.where.length ? `: ${w8touch.where.join(' ')}` : ''}`);

    /*
     * 6. JOKAISEN KUILUN EDESSÄ ON TÄYSI VAUHDINOTTO.
     *
     * Luulaakso mittasi tämän ja kirjoitti sen kommenttiin: seisova hyppy
     * kantaa **0 px** sivusuunnassa, joten laskeutuminen on täsmälleen niin
     * hyvä kuin se vauhdinotto jonka se jättää. Maailma jonka jokainen kenttä
     * on käytävä ja jonka jokainen kuilu on laavaa on juuri se paikka jossa
     * tuo asia lakkaa olemasta ohje ja alkaa olla kentän rikkova virhe: jaettu
     * `fort_gap` tuo mukanaan vain neljä saraketta lattiaa, joten kaksi
     * peräkkäistä palikkaa voi tuottaa laavan jonka eteen ei ehdi kiihtyä.
     *
     * Sääntö on siis mitta eikä maku: **yhdenkään kuilun edessä ei ole alle
     * yhdeksää saraketta yhtenäistä lattiaa.** Yhdeksän on `keep_hole`in oma
     * profiili, sama jota pilvimaailma käyttää, ja se on tässä koko maailman
     * sävellyssääntö — se sanelee palikkajärjestyksen kaikissa kuudessa
     * kentässä.
     *
     * `%` eli murenevaa lavaa ei lasketa kuiluksi: se on jalansijaa siihen
     * asti kunnes sille astuu, ja sen oma vaikeus on eri kysymys.
     */
    const runUps = (levels) => {
      const out = [];
      for (const id of levels) {
        const rows = routeOf(id);
        const w = rows[0].length;
        const footing = [];
        for (let x = 0; x < w; x++) {
          footing.push([FLOOR, FLOOR + 1].some((y) => STONE.includes(rows[y][x])
            || rows[y][x] === T.CRUMBLE));
        }
        let run = 0;
        for (let x = 0; x < w; x++) {
          if (footing[x]) { run++; continue; }
          if (x && footing[x - 1] === false) continue;   // sama kuilu, jo kirjattu
          out.push({ id, x, run });
          run = 0;
        }
      }
      return out;
    };
    const w8runs = runUps(w8);
    const worstRun = w8runs.reduce((m, r) => (r.run < m.run ? r : m), { id: '—', run: 99 });
    const elsewhereRun = runUps(ids.filter((id) => !id.startsWith('8-')))
      .reduce((m, r) => (r.run < m.run ? r : m), { id: '—', run: 99 });
    expect('viimeisessä linnakkeessa jokaisen kuilun edessä on yhdeksän saraketta lattiaa',
      w8runs.length > 0 && worstRun.run >= 9 && elsewhereRun.run < 9,
      `${w8runs.length} kuilua, ahtain ${worstRun.id} sarakkeessa ${worstRun.x} `
      + `(${worstRun.run} saraketta vauhtia) — muun pelin ahtain ${elsewhereRun.id} `
      + `${elsewhereRun.run}`);
  }

  /* ---- maailma 8 kahdeksaan ---- */
  /*
   * SEITSEMÄN UUSINTAA JA MEGAPOMO.
   *
   * Maailma 8 oli kuusi kenttää ja kuusi tappelua, ja se oli oikea muoto niin
   * kauan kuin sen väite oli "jokainen pomo kerran". Omistajan päätös vaihtoi
   * väitteen: linnakkeita on seitsemän (maailmat 1–7), joten uusintoja on
   * **seitsemän** — yksi jokaista linnaketta kohti, siinä järjestyksessä kuin
   * linna ne lähetti — ja kahdeksas ovi on kuningas itse.
   *
   * Erotus vanhaan on se että roolitus luetaan nyt **datasta eikä listasta**.
   * Vanha ehto oli "jokainen variantti kerran", ja se piti paikkansa vain
   * sattumalta: jättiläinen on kahden linnakkeen pomo (4-F ja 5-F), joten
   * seitsemän uusintaa sisältää hänet kahdesti eikä joukko-oppi enää kelpaa
   * väitteeksi. Uusi väite on jono jonoa vasten, ja se rikkoutuu jos jonkin
   * maailman linnakkeen pomo vaihtuu ilman että maailma 8 seuraa perässä.
   *
   * Neljä mittausta, ja jokainen on sellainen jonka maailma voi rikkoa ja
   * silti näyttää valmiilta:
   *
   *   1  jono      8-1…8-7 kantavat maailmojen 1–7 linnakepomot samassa
   *                järjestyksessä, ja 8-F kantaa variantin jota ei ole muualla
   *   2  verbi     kuningas ei kiihdy vaan vaihtuu — muut kiihtyvät
   *   3  koko      kuningas ei lainaa jättiläisen kokoa, koska koko on se
   *                ainoa asia joka vaatii toisen huoneen
   *   4  lupaus    voimataso 0 kaataa kuninkaan, ja kellossa on ikkunoita
   *                enemmän kuin hänellä osumia
   *
   * Nollatestinä on muu peli, kuten viereisessä lohkossa: jos jokainen pomo
   * antaisi saman luvun, väite ei erottaisi mitään.
   */
  {
    const K = await import('/src/entities/enemies.js');
    const kLevels = await import('/src/data/levels.js');
    const kGet = kLevels.getLevel;
    const kIds = kLevels.levelIds();

    /* 1. JONO JONOA VASTEN. */
    const FORTS = ['1-F', '2-F', '3-F', '4-F', '5-F', '6-F', '7-F'];
    const rematchIds = kIds.filter((id) => /^8-[1-7]$/.test(id))
      .sort((a, b) => a.localeCompare(b));
    const wanted = FORTS.map((id) => kGet(id).bossVariant);
    const got = rematchIds.map((id) => kGet(id).bossVariant);
    const kingVariant = kGet('8-F').bossVariant;
    const elsewhereKing = kIds.filter((id) => id !== '8-F' && kGet(id).boss
      && kGet(id).bossVariant === kingVariant);
    /*
     * Jono on sama kuin linnakkeiden, **paitsi siinä yhdessä kohdassa jossa
     * linnakkeiden oma jono toistaa itseään.**
     *
     * Jättiläinen on sekä 4-F että 5-F, joten suora uusinta antoi hänet myös
     * kahdesti maailmassa 8 — ja koko maailman väite on "jokainen pomo kerran".
     * Se oli siis totta vain jos pöhöä ei laske kahdesti (mitattu: neljä
     * esiintymää, kun jokainen muu esiintyy kaksi). Toinen osuma korvattiin
     * kahdeksannella variantilla, ja tämä rivi tarkistaa nyt kaksi asiaa
     * yhden sijaan: **järjestys pitää** ja **uusinnassa ei ole kahta samaa**.
     * Jälkimmäinen on se joka vasta tekee väitteestä mitattavan.
     */
    const dup = got.filter((v, i) => got.indexOf(v) !== i);
    const order = got.filter((v, i) => v === wanted[i]).length;
    expect('maailma 8 uusii linnakkeet järjestyksessä, eikä yhtäkään kahdesti',
      rematchIds.length === 7 && order === wanted.length - 1 && dup.length === 0
      && elsewhereKing.length === 0,
      `linnakkeet ${wanted.join(' ')} — uusinnat ${got.join(' ')} `
      + `(${rematchIds.join(' ')}), samassa kohdassa ${order}/7, toistoja ${dup.length}`
      + `, 8-F variantti ${kingVariant} muualla ${elsewhereKing.length} kertaa`);

    /* Kuninkaan tappelu ajetaan kerran ja kaikki neljä väitettä lukevat samaa
     * ajoa. Osumat annetaan `stomp()`illa suoraan: kysymys on siitä mitä pomo
     * vastaa osumaan, ei siitä osuuko pelaaja — se on kohta 4. */
    const fightOf = (id) => {
      reset();
      const s = new LevelScene(game, id);
      game.setScene(s);
      const boss = s.entities.find((e) => e instanceof K.Boss);
      const forms = [];
      const speeds = [];
      const scales = [];
      for (let hit = 0; hit < boss.maxHp; hit++) {
        forms.push(boss.form === undefined ? boss.variant : boss.form);
        speeds.push(Math.round(boss.speed * 100) / 100);
        scales.push(boss.targetScale);
        boss.invuln = 0;
        boss.stomp();
      }
      scales.push(boss.targetScale);
      return { boss, forms, speeds, scales };
    };

    /*
     * 2. VERBI, ja se on kirjoitettu tähän muotoon vasta mittauksen jälkeen.
     *
     * Ensimmäinen versio väitti että *kuningas ei kiihdy* — että hänen
     * nopeutensa on viimeisellä osumalla sama kuin ensimmäisellä. Mittaus
     * kaatoi sen kahdesti ja molemmat kaatumiset opettivat jotain. Ensin
     * nollatesti: **jättiläinen ei kiihdy sekään** (1,2 → 1,2), koska hänen
     * vastauksensa on koko eikä nopeus, joten "muut kiihtyvät" oli epätosi
     * kahdesta seitsemästä. Ja sitten väite itse: kuninkaan muotojono on
     * linnakkeiden järjestys, ja `speed = 0,75 + variantti · 0,15`, joten
     * järjestys **on** nopeusjärjestys — hänen nopeutensa nousee väistämättä.
     *
     * Oikea väite on siksi toinen ja se on tarkempi: **yksikään numero jonka
     * kuningas kantaa ei ole hänen omansa.** Jokainen muu pomo vastaa osumaan
     * kasvattamalla yhtä omaa lukuaan (nopeus +0,35 / +0,2, tai koko +0,5);
     * kuningas vaihtaa koko lukusarjan jonkun toisen sarjaksi, ja jokainen
     * nopeus jonka hän ottaa on jonkin linnakkeen oma aloitusnopeus. Muoto on
     * se numero joka hänellä muuttuu, eikä yksikään muu pomo vaihda sitä
     * kertaakaan.
     */
    const king = fightOf('8-F');
    const others = FORTS.map((id) => ({ id, ...fightOf(id) }));
    const baseSpeeds = new Set(others.map((o) => o.speeds[0]));
    const borrowed = king.speeds.every((v) => baseSpeeds.has(v));
    const steady = others.filter((o) => new Set(o.forms).size === 1);
    const ownNumber = others.filter((o) => o.speeds[o.speeds.length - 1] > o.speeds[0]
      || o.scales[o.scales.length - 1] > o.scales[0]);
    expect('kuningas vastaa osumaan vaihtamalla muotoa, muut omalla numerollaan',
      king.forms.join(',') === wanted.join(',') && borrowed
      && new Set(king.forms).size > 1
      && steady.length === FORTS.length && ownNumber.length === FORTS.length,
      `kuningas muodot ${king.forms.join(' ')}, nopeudet ${king.speeds.join(' ')} `
      + `(lainattuja ${borrowed ? 'kaikki' : 'ei kaikkia'}, linnakkeiden omat `
      + `${[...baseSpeeds].sort((a, b) => a - b).join('/')}) — muut `
      + `${others.map((o) => `${o.id} muoto ${[...new Set(o.forms)].join('+')} `
        + `${o.speeds[0]}→${o.speeds[o.speeds.length - 1]} koko `
        + `${o.scales[0]}→${o.scales[o.scales.length - 1]}`).join(', ')}`);

    /* 3. KOKO. */
    const giant = others.find((o) => o.id === '4-F');
    expect('kuningas ei lainaa jättiläisen kokoa, vaikka lainaa hänen liikkeensä',
      king.forms.includes(3) && king.scales.every((v) => v === 1)
      && Math.max(...giant.scales) > 1,
      `kuningas ${king.scales.join('/')} (muodot ${king.forms.join(' ')}), `
      + `jättiläinen ${giant.scales.join('/')}`);

    /* Ja koska kasvaminen on se ainoa asia joka vaatii toisen huoneen: jokainen
     * kenttä jonka pomo kasvaa loppuu kannelliseen areenaan. Väite on datasta
     * eikä nimistä, joten uusi kasvava pomo pienessä huoneessa jää tähän. */
    const growers = kIds.filter((id) => kGet(id).boss && kGet(id).bossVariant === 3);
    const smallRoom = growers.filter((id) => {
      const chunks = kGet(id).chunks || [];
      return chunks[chunks.length - 1] !== 'boss_arena_big';
    });
    expect('jokainen kasvava pomo tappelee kannellisessa areenassa',
      growers.length >= 3 && smallRoom.length === 0,
      `${growers.length} kasvavaa pomoa (${growers.join(' ')}), ilman kansia ${smallRoom.length}`);

    /* 4. LUPAUS, ja se on sama simulaatio kuin muillakin pomoilla: kävele ja
     * tallaa yhden ikkunan sisällä voimatasolla 0. */
    {
      reset();
      const s = new LevelScene(game, '8-F');
      game.setScene(s);
      const boss = s.entities.find((e) => e instanceof K.Boss);
      const idle = mkInput();
      /* Settle him rather than let him pace — see the same loop in the
       * `BOSS_LEVELS` sweep for what the other seventy-five frames were doing
       * to where the player got put down. */
      for (let f = 0; f < 90 && !(boss.onGround && f > 2); f++) s.update(idle);
      boss.hp = 1;
      boss.spikePhase = 'open';
      const openWindow = boss.openFrames;
      boss.spikeTimer = openWindow;
      const p = s.player;
      p.y = boss.y + boss.h - p.h;
      /* Approach measured from the boss's **edge and top**, not from a constant.
       * The numbers here were tuned when every boss was 30x32, and per-boss
       * sizes broke both halves: 40 px from a wide boss's centre is inside his
       * flank, and a tall boss needs a boss-height of extra run-up or the
       * player arrives over him still rising, which is a collision and not a
       * stomp. Derived in full at the `BOSS_LEVELS` sweep. */
      const clearance = boss.w / 2 + 25 + boss.h;
      p.x = boss.cx - (clearance + 50);
      p.vx = 0; p.vy = 0;
      s.centerCamera();
      const i = mkInput();
      let hitAt = -1;
      for (let f = 0; f < openWindow && hitAt < 0; f++) {
        boss.jumpTimer = 999; boss.chargeTimer = 999; boss.charging = 0;
        const dx = boss.cx - p.cx;
        const adx = Math.abs(dx);
        i.held = blank();
        i.pressed = blank();
        if (!p.onGround) {
          const want = Math.sign(dx) * Math.min(2.2, adx / 8);
          if (p.vx < want - 0.15) i.held.right = true;
          else if (p.vx > want + 0.15) i.held.left = true;
          if (p.vy < 0) i.held.jump = true;
        } else if (adx > clearance + Math.abs(boss.vx) * 12) {
          i.held[dx > 0 ? 'right' : 'left'] = true;
          i.held.run = true;
        } else {
          i.pressed.jump = true;
          i.held.jump = true;
        }
        s.update(i);
        if (boss.hp < 1 || s.bossDefeated) hitAt = f;
      }
      expect('8-F: voimataso 0 tallaa kuningasta yhden ikkunan sisällä',
        hitAt >= 0, `osui framella ${hitAt}/${openWindow}`);
    }

    {
      reset();
      const s = new LevelScene(game, '8-F');
      const boss = s.entities.find((e) => e instanceof K.Boss);
      boss.hp = 1;
      const cycle = boss.openFrames + 48 + 132;
      const windows = Math.floor((s.time * 24) / cycle);
      expect('kuninkaan kellossa on ikkunoita enemmän kuin hänellä osumia',
        windows / boss.maxHp >= 4,
        `${boss.maxHp} osumaa, ${windows} ikkunaa (${(windows / boss.maxHp).toFixed(1)} per osuma), `
        + `kello ${s.time}, sykli ${cycle} framea`);
    }
  }
  /* ---- maailma 8 kahdeksaan loppuu ---- */

  /* Picking up a different power-up swaps: the one you were wearing goes into
   * the reserve box rather than evaporating. */
  {
    reset({ type: 'leaf', level: 3 });
    const s = new LevelScene(game, '1-1');
    game.state.reserve = null;
    s.player.collect('shroom');
    expect('a different power-up swaps the old one into the box',
      game.state.reserve === 'leaf' && s.player.type === 'shroom',
      `varasto ${game.state.reserve}, voima ${s.player.type} ${s.player.powerLevel}`);

    // Same type just levels up; nothing to bank.
    reset({ type: 'shroom', level: 2 });
    const s2 = new LevelScene(game, '1-1');
    game.state.reserve = null;
    s2.player.collect('shroom');
    expect('the same power-up just levels up',
      game.state.reserve === null && s2.player.powerLevel === 3,
      `varasto ${game.state.reserve}, taso ${s2.player.powerLevel}`);
  }

  /* Every character the game puts on screen must have a glyph. A missing one
   * shows as a hole, and Finnish is full of letters ASCII does not have. */
  {
    const font = await import('/src/gfx/font.js');
    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 16;
    const g = canvas.getContext('2d');
    const missing = [];
    for (const ch of 'ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖ0123456789 .,:!?*()=/+<>%\'-') {
      g.clearRect(0, 0, 64, 16);
      font.drawText(g, ch, 2, 2, { color: '#ffffff' });
      const data = g.getImageData(0, 0, 64, 16).data;
      let ink = 0;
      for (let i = 3; i < data.length; i += 4) if (data[i] > 0) ink++;
      if (ch !== ' ' && ink === 0) missing.push(ch);
    }
    expect('the font can draw every letter the game uses',
      missing.length === 0, missing.length ? `puuttuu: ${missing.join('')}` : '');
  }

  /* Taking a hit drops the reserve item, and that item must not land straight
   * back in the player's hands — otherwise a hit silently swaps your power
   * instead of costing you one. */
  {
    reset({ type: 'shroom', level: 3 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    game.state.reserve = 'leaf';
    const i = mkInput();
    for (let f = 0; f < 6; f++) s.update(i);

    const before = s.player.powerLevel;
    s.player.hurt();
    for (let f = 0; f < 20; f++) { s.update(i); i.pressed = blank(); }
    const p = s.player;
    expect('a hit costs a power level instead of swapping your power',
      p.type === 'shroom' && p.powerLevel === before - 1,
      `${p.type} ${p.powerLevel}, odotettiin shroom ${before - 1}`);
  }

  /* ----------------------------- high scores --------------------------- */
  {
    const scores = await import('/src/core/scores.js');
    scores.clearScores();
    expect('an empty board takes any score', scores.qualifies(10) && !scores.qualifies(0));

    for (let i = 0; i < scores.MAX_ENTRIES; i++) {
      scores.addScore({ name: `P${i}`, score: 1000 + i * 100, world: 1 });
    }
    const full = scores.loadScores();
    const sorted = full.every((e, i) => i === 0 || full[i - 1].score >= e.score);
    expect('the board keeps the best ten in order',
      full.length === scores.MAX_ENTRIES && sorted && full[0].score === 1900,
      `${full.length} rows, top ${full[0].score}`);

    expect('a score below the board is turned away', !scores.qualifies(500));
    const idx = scores.addScore({ name: 'STAR', score: 5000, world: 3, assisted: true });
    const board = scores.loadScores();
    expect('a new best lands on top and keeps its star',
      idx === 0 && board[0].name === 'STAR' && board[0].assisted && board.length === 10,
      `index ${idx}, assisted ${board[0].assisted}`);

    // A tie must not push the older entry down: you beat a score, not match it.
    scores.addScore({ name: 'TIE', score: 5000, world: 1 });
    expect('a tie stays behind the entry that got there first',
      scores.loadScores()[0].name === 'STAR');

    // The board should say which level the run reached, not just which world.
    scores.clearScores();
    scores.addScore({ name: 'LVL', score: 4242, world: 2, level: '2-3' });
    const withLevel = scores.loadScores()[0];
    scores.addScore({ name: 'OLD', score: 4000, world: 2 });
    const withoutLevel = scores.loadScores()[1];
    expect('a score remembers the level it reached, and old rows still load',
      withLevel.level === '2-3' && withoutLevel.level === '',
      `${withLevel.level} / "${withoutLevel.level}"`);
    scores.clearScores();
  }

  {
    // Loading a save state has to mark the run, or the star means nothing.
    reset();
    const s = new LevelScene(game, '1-1');
    game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-1');
    game.setScene(s);
    game.state.usedSaveState = false;
    game.slot = 3;
    game.quickSave();
    game.quickLoad();
    expect('loading a save state marks the run as assisted', game.state.usedSaveState === true);
  }

  /* ------------------------------- jakoruutu ---------------------------- */
  /* Jakoruudulla on neljä maailmaa — jako + leikepöytä, pelkkä jako, pelkkä
   * leikepöytä, ei kumpaakaan — eikä yhteenkään niistä voi luottaa selaimen
   * oletuksena, joten jokainen pakotetaan tyngällä. Kolme asiaa jotka tämä
   * vahtii: peruutus ei ole virhe, mikään ei lähde palvelimelle, eikä ruudulle
   * jää jumiin missään yhdistelmässä. */
  {
    const share = await import('/src/scenes/share.js');
    const scores = await import('/src/core/scores.js');
    const { HighScoreScene } = await import('/src/scenes/scores.js');
    const { Input } = await import('/src/core/input.js');
    const { textWidth, drawText: drawTextFn } = await import('/src/gfx/font.js');

    const settle = () => new Promise((r) => setTimeout(r, 0));
    const stub = (shareFn, clipFn) => {
      Object.defineProperty(navigator, 'share', {
        value: shareFn || undefined, configurable: true, writable: true,
      });
      Object.defineProperty(navigator, 'clipboard', {
        value: clipFn ? { writeText: clipFn } : undefined, configurable: true, writable: true,
      });
    };
    const unstub = () => {
      delete navigator.share;
      delete navigator.clipboard;
    };
    /* Yhden framen napautus kosketuksen tietä. Sama polku kuin puhelimessa,
     * eli myös nousureuna syntyy siellä missä oikeastikin. */
    const tap = (action) => {
      Input.setAction(action, true);
      game.step();
      Input.setAction(action, false);
      game.step();
    };

    stub(null, null);
    scores.clearScores();
    scores.addScore({ name: 'TESTI', score: 12345, world: 2, level: '2-3' });

    /* Reitti sisään ja ulos. Se on jakoruudun ensimmäinen vaatimus: sinne pitää
     * päästä ja sieltä pitää päästä pois, riippumatta siitä mitä jako teki. */
    reset();
    game.toHighScores(0);
    const board = game.scene;
    tap('run');
    const openedFromBoard = game.scene.constructor.name;
    for (let f = 0; f < 8; f++) game.step();
    tap('start');
    expect('pistetaulusta pääsee jakoruutuun ja ENTER tuo takaisin samaan tauluun',
      openedFromBoard === 'ShareScene' && game.scene === board,
      `${openedFromBoard} -> ${game.scene.constructor.name}`);

    game.toTitle();
    tap('run');
    const openedFromTitle = game.scene.constructor.name;
    for (let f = 0; f < 8; f++) game.step();
    tap('run');
    expect('alkuruudusta pääsee jakoruutuun ja X tuo takaisin',
      openedFromTitle === 'ShareScene' && game.scene.constructor.name === 'TitleScene',
      `${openedFromTitle} -> ${game.scene.constructor.name}`);

    // Juoksunappi on kentässä juoksu. Kohtauksen vaihto kesken hypyn tappaisi
    // kierroksen, joten jako ei ole siellä.
    reset();
    const midLevel = new LevelScene(game, '1-1');
    game.setScene(midLevel);
    tap('run');
    expect('kentästä ei voi avata jakoruutua juoksunapilla',
      game.scene === midLevel, game.scene.constructor.name);
    game.toTitle();

    /* Osoite on se jonka og:tagi ilmoittaa, ei sivun oma. Testipalvelin ajaa
     * 127.0.0.1:ssä, joten tämä testi erottaa ne kaksi toisistaan. */
    const meta = document.querySelector('meta[property="og:url"]').getAttribute('content');
    expect('jaettava osoite on og:url eikä sivun oma osoite',
      share.shareUrl() === meta && !share.shareUrl().includes('127.0.0.1'), share.shareUrl());

    const brag = share.shareText({ name: 'TESTI', score: 12345, world: 2, level: '2-3' });
    const plain = share.shareText(null);
    /* Pelin nimi luetaan `share.js`:stä eikä kirjoiteta tähän uudelleen.
     * Kirjoitettuna se olisi kolmas paikka jossa nimi lukee — index.html ja
     * alkuruutu ovat kaksi muuta — ja nimenvaihdon jälkeen portti kaatuisi
     * väittäen että jakorivi on rikki, vaikka rikki olisi portin oma muisti
     * vanhasta nimestä. Testi kysyy siis "kantaako rivi pelin nimen", joka on
     * se asia jonka se on aina tarkoittanut. */
    const title = share.SHARE_TITLE;
    expect('jaettava rivi kertoo pisteet, kentän ja pelin nimen, ja tyhjä taulu ei keksi tulosta',
      !!title && brag.includes('12345') && brag.includes('2-3') && brag.includes(title)
      && plain.includes(title) && !/\d{3}/.test(plain), `${brag} | ${plain}`);

    const combos = [
      [() => Promise.resolve(), () => Promise.resolve(), 'share'],
      [() => Promise.resolve(), null, 'share'],
      [null, () => Promise.resolve(), 'clipboard'],
      [null, null, 'none'],
    ];
    const detected = combos.map(([s, c, want]) => {
      stub(s, c);
      return share.shareCapability() === want;
    });
    expect('selaimen kyvyt tunnistetaan kaikissa neljässä yhdistelmässä',
      detected.every(Boolean), detected.join(','));

    /**
     * Avaa jakoruudun annetuilla tyngillä, painaa ja päästää jakonapin, odottaa
     * lupaukset ja poistuu. Palauttaa mitä tyngät näkivät ja mihin tilaan ruutu
     * jäi. Nousureuna on tässä olennainen: jako lähtee siitä eikä painalluksesta.
     */
    const runShare = async (shareFn, clipFn) => {
      const saw = { share: null, clip: null };
      stub(shareFn && ((d) => { saw.share = d; return shareFn(d); }),
        clipFn && ((t) => { saw.clip = t; return clipFn(t); }));
      const back = new HighScoreScene(game, 0);
      const scene = new share.ShareScene(game, back);
      game.setScene(scene);
      const i = mkInput();
      for (let f = 0; f < 8; f++) scene.update(i);
      i.pressed = blank();
      i.pressed.jump = true;
      scene.update(i);
      const armed = scene.armed;
      i.pressed = blank();
      i.released = blank();
      i.released.jump = true;
      scene.update(i);
      await settle();
      await settle();
      const status = scene.status;
      const j = mkInput();
      j.pressed.start = true;
      scene.update(j);
      return { saw, armed, status, left: game.scene === back, scene };
    };

    const abort = () => Promise.reject(Object.assign(new Error('cancel'), { name: 'AbortError' }));
    const denied = () => Promise.reject(Object.assign(new Error('nope'), { name: 'NotAllowedError' }));
    const ok = () => Promise.resolve();

    const both = await runShare(ok, ok);
    expect('jako ja leikepöytä: jakovalikko saa otsikon, rivin ja osoitteen',
      both.status === 'shared' && both.armed && both.left
      && both.saw.share && both.saw.share.url.startsWith(meta)
      && both.saw.share.text.includes('12345') && both.saw.clip === null,
      `${both.status}, leikepöytä ${both.saw.clip === null ? 'koskematta' : 'kosketettu'}`);

    const cancelled = await runShare(abort, ok);
    expect('peruutettu jako ei ole virhe eikä valu leikepöydälle',
      cancelled.status === 'cancelled' && cancelled.saw.clip === null && cancelled.left,
      `${cancelled.status}, leikepöytä ${cancelled.saw.clip === null ? 'koskematta' : 'kosketettu'}`);

    const fellBack = await runShare(denied, ok);
    expect('kaatunut jako putoaa leikepöydälle osoitteen kanssa',
      fellBack.status === 'copied' && typeof fellBack.saw.clip === 'string'
      && fellBack.saw.clip.includes(meta) && fellBack.left,
      `${fellBack.status}, ${fellBack.saw.clip}`);

    const shareOnly = await runShare(denied, null);
    expect('ilman leikepöytää kaatunut jako jättää osoitteen ruudulle',
      shareOnly.status === 'manual' && shareOnly.scene.url.startsWith(meta) && shareOnly.left,
      `${shareOnly.status}, ${shareOnly.scene.url}`);

    const clipOnly = await runShare(null, ok);
    expect('pelkkä leikepöytä kopioi rivin ja osoitteen',
      clipOnly.status === 'copied' && clipOnly.saw.clip.includes(meta)
      && clipOnly.saw.clip.includes('12345') && clipOnly.left,
      `${clipOnly.status}, ${clipOnly.saw.clip}`);

    const clipDenied = await runShare(null, denied);
    expect('kieltäytynyt leikepöytä ei jätä ruutua roikkumaan',
      clipDenied.status === 'manual' && !clipDenied.scene.busy && clipDenied.left,
      `${clipDenied.status}, busy ${clipDenied.scene.busy}`);

    const nothing = await runShare(null, null);
    expect('ilman jakoa ja leikepöytää ruutu näyttää osoitteen eikä lupaa nappia',
      nothing.status === 'manual' && nothing.scene.how === 'none'
      && nothing.scene.url.startsWith(meta) && nothing.left,
      `${nothing.status}, ${nothing.scene.how}`);

    const threw = await runShare(() => { throw new Error('synkroninen'); }, ok);
    expect('synkronisesti heittävä jako kaatuu leikepöydälle eikä sivulle',
      threw.status === 'copied' && threw.left, threw.status);

    /* Nousureuna ilman painallusta ei saa laukaista mitään. Edellisestä
     * ruudusta roikkuva nappi tuottaa juuri sellaisen. */
    let ghost = null;
    stub((d) => { ghost = d; return Promise.resolve(); }, null);
    const loose = new share.ShareScene(game, null);
    const li = mkInput();
    for (let f = 0; f < 8; f++) loose.update(li);
    li.released = blank();
    li.released.jump = true;
    loose.update(li);
    await settle();
    expect('pelkkä napin nousu ilman painallusta ei jaa mitään',
      ghost === null && loose.status === 'idle', `${loose.status}`);

    /* Mikään tässä ruudussa ei saa ottaa yhteyttä mihinkään. Sama peruste kuin
     * telemetrian palvelinlähetyksen jättämisessä tekemättä. */
    const shareSrc = await (await fetch('/src/scenes/share.js')).text()
      + await (await fetch('/src/core/challenge.js')).text();
    const net = ['fetch(', 'XMLHttpRequest', 'sendBeacon', 'WebSocket', 'EventSource', 'img.src']
      .filter((n) => shareSrc.includes(n));
    expect('jakoruutu ei lähetä mitään minnekään', net.length === 0, net.join(', ') || 'ei verkkokutsuja');

    // Pisin mahdollinen kehu: kuusi kirjainta, seitsemän numeroa, linnake.
    const widest = share.wrapText(
      share.shareText({ name: 'ÄÄKKÖS', score: 9999999, world: 5, level: '5-F' }), 46,
    );
    const tooWide = widest.filter((l) => textWidth(l) > 300);
    expect('pisin mahdollinen kehu rivittyy ruudun leveyteen',
      tooWide.length === 0 && widest.length <= 3, `${widest.length} riviä, ${tooWide.length} yli`);

    {
      const c = document.createElement('canvas');
      c.width = 320;
      c.height = 240;
      const g = c.getContext('2d');
      g.globalAlpha = 1;
      g.globalCompositeOperation = 'source-over';
      const leaks = [];
      let flat = 0;
      for (const st of ['idle', 'busy', 'shared', 'copied', 'cancelled', 'manual']) {
        for (const how of ['share', 'clipboard', 'none']) {
          const scene = new share.ShareScene(game, null);
          scene.how = how;
          scene.status = st;
          g.clearRect(0, 0, 320, 240);
          scene.draw(g);
          if (g.globalAlpha !== 1) leaks.push(`${how}/${st} alpha ${g.globalAlpha}`);
          if (g.globalCompositeOperation !== 'source-over') leaks.push(`${how}/${st} ${g.globalCompositeOperation}`);
          if (g.filter && g.filter !== 'none') leaks.push(`${how}/${st} filter ${g.filter}`);
          const px = g.getImageData(0, 0, 320, 240).data;
          const seen = new Set();
          for (let p = 0; p < px.length; p += 4 * 37) {
            seen.add((px[p] << 16) | (px[p + 1] << 8) | px[p + 2]);
          }
          if (seen.size < 5) flat++;
        }
      }
      expect('jakoruudun piirto jättää canvasin tilan ennalleen ja piirtää jotain',
        leaks.length === 0 && flat === 0, leaks.join(', ') || `${flat} tyhjää`);
    }

    /* ---------------------------- haastelinkki -------------------------- */
    /* Tulos kulkee osoiteparametreissa (`?s=45200&n=OLLI&l=2-3`). Tässä
     * lohkossa testataan luku, kirjoitus ja mitat; sivunlatauksen vaativat
     * asiat — osoiterivin siivous ja "mitään ei kirjoiteta" — ovat omassa
     * selainkontekstissaan tämän tiedoston lopussa. */
    {
      const ch = await import('/src/core/challenge.js');
      const { TitleScene } = await import('/src/scenes/title.js');

      const link = ch.appendChallenge(meta, { name: 'OLLI', score: 45200, level: '2-3' });
      expect('jakolinkki kantaa tuloksen, nimen ja kentän',
        link === `${meta}?s=45200&n=OLLI&l=2-3`, link);

      /* Tyhjä taulu ei saa tuottaa `?s=0`. Nollan kehuminen on huonompi kuin
       * kehumatta jättäminen, ja vastaanottaja saisi haasteen jonka voittaa
       * kävelemällä ensimmäisen kolikon ohi. */
      const bare = [
        ch.appendChallenge(meta, null),
        ch.appendChallenge(meta, { name: 'OLLI', score: 0, level: '1-1' }),
        ch.appendChallenge(meta, { name: 'OLLI', score: -5 }),
      ];
      expect('tyhjä taulu jakaa pelkän osoitteen eikä nollatulosta',
        bare.every((u) => u === meta), bare.join(' | '));

      const round = ch.parseChallenge(new URL(
        ch.appendChallenge(meta, { name: 'ÄÄKKÖS', score: 9999999, level: '5-F' }),
      ).search);
      expect('linkin tulos luetaan takaisin sellaisenaan, ääkkösineen',
        round && round.score === 9999999 && round.name === 'ÄÄKKÖS' && round.level === '5-F',
        JSON.stringify(round));

      /* Roskaa parametreissa. Sääntö on yksi: haaste on väite ajosta jonka
       * *tämä peli* olisi voinut tuottaa, ja jos väite ei ole sellainen, ei ole
       * haastetta. Puolikas haaste ruudulla olisi pahempi kuin ei haastetta. */
      const junk = ['', '?', '?n=OLLI&l=2-3', '?s=', '?s=abc', '?s=-5', '?s=1e999',
        '?s=0', '?s=0000000', '?s=45200.5', '?s=45200x', '?s=+45200', '?s=%2045200',
        '?s=99999999', '?s=NaN', '?s=Infinity', '?s=١٢٣'];
      const wrong = junk.filter((q) => ch.parseChallenge(q) !== null);
      expect('roska osoiteparametreissa ei tuota haastetta lainkaan',
        wrong.length === 0, wrong.join(' ') || `${junk.length} roskatapausta`);

      /* Nimi on ainoa vapaa teksti linkissä. Se piirretään pelin omalla
       * fontilla, joten injektiopintaa ei ole — mutta 500 merkkiä levittäisi
       * rivin ruudun ulkopuolelle, ja fontin tuntematon merkki vie leveyttä
       * piirtämättä mitään. Siksi nimi sekä suodatetaan että katkaistaan. */
      const longName = ch.parseChallenge(`?s=1000&n=${'A'.repeat(500)}`);
      const emoji = ch.parseChallenge('?s=1000&n=%F0%9F%92%A9%F0%9F%92%A9');
      const mixed = ch.parseChallenge('?s=1000&n=%F0%9F%92%A9olli%F0%9F%92%A9');
      const rtl = ch.parseChallenge('?s=1000&n=%D9%85%D8%B1%D8%AD%D8%A8%D8%A7');
      expect('pitkä tai piirtokelvoton nimi katkaistaan ja suodatetaan',
        longName && longName.name === 'AAAAAA'
        && emoji && emoji.name === 'KAVERI'
        && mixed && mixed.name === 'OLLI'
        && rtl && rtl.name === 'KAVERI',
        [longName, emoji, mixed, rtl].map((c) => c && c.name).join(' | '));

      /* Kenttätunnus on kuvateksti eikä haasteen ehto, joten tuntematon tunnus
       * jätetään pois eikä koko haastetta hylätä. */
      const ghostLevel = ch.parseChallenge('?s=1000&n=OLLI&l=9-9');
      const realLevel = ch.parseChallenge('?s=1000&n=OLLI&l=2-3');
      expect('tuntematon kenttätunnus jätetään pois mutta haaste jää voimaan',
        ghostLevel && ghostLevel.score === 1000 && ghostLevel.level === ''
        && realLevel && realLevel.level === '2-3',
        `${ghostLevel && ghostLevel.level}|${realLevel && realLevel.level}`);

      /* Sama sääntö kuin pistetaululla: pisteet pitää *voittaa*, ei tasata. */
      const target = ch.parseChallenge('?s=45200&n=OLLI&l=2-3');
      expect('haasteen voittaa vain suuremmalla tuloksella',
        ch.beats(45201, target) && !ch.beats(45200, target) && !ch.beats(0, target)
        && !ch.beats(-1, target) && !ch.beats(999999, null),
        `${ch.beats(45201, target)}/${ch.beats(45200, target)}`);

      // Pisin mahdollinen haasterivi: kuusi kirjainta, seitsemän numeroa, linnake.
      const widestCh = { name: 'ÄÄKKÖS', score: 9999999, level: '5-F' };
      const lines = [
        ch.challengeLine({ ...widestCh, beaten: false }),
        ch.challengeLine({ ...widestCh, beaten: true }),
        ch.challengeLine({ ...longName, name: 'AAAAAA' }),
      ];
      const over = lines.filter((l) => textWidth(l) > 300);
      expect('pisin mahdollinen haasterivi mahtuu 320 pikselin ruudulle',
        over.length === 0 && lines.every((l) => l.length > 0),
        over.map((l) => `${textWidth(l)}px ${l}`).join(', ') || lines[0]);

      /* Jokainen merkki haasterivillä pitää löytyä pelin fontista. Puuttuva
       * glyyfi ei kaada mitään — `drawText` hyppää sen yli mutta siirtää silti
       * kohdistinta — joten virhe olisi aukko tekstissä eikä poikkeus, ja se
       * huomattaisiin vasta ruutukaappauksesta. Sen takia se mitataan
       * musteesta eikä luetella käsin. */
      {
        const ink = document.createElement('canvas');
        ink.width = 16;
        ink.height = 12;
        const ig = ink.getContext('2d');
        const blank = new Set();
        const board = [
          `VOITIT HAASTEEN! ${widestCh.name} SAI 9 999 999`,
          `${widestCh.name} JOHTAA YHÄ: 9 999 999`,
          `HAASTE: ${widestCh.name} 9 999 999`,
        ];
        for (const text of [...lines, ...board]) {
          for (const chr of new Set(text.toUpperCase())) {
            if (chr === ' ') continue;
            ig.clearRect(0, 0, 16, 12);
            drawTextFn(ig, chr, 1, 1, { color: '#ffffff' });
            const px = ig.getImageData(0, 0, 16, 12).data;
            let lit = 0;
            for (let p = 3; p < px.length; p += 4) if (px[p] > 0) lit++;
            if (!lit) blank.add(chr);
          }
        }
        const wideBoard = board.filter((l) => textWidth(l) > 300);
        expect('haaste- ja pistetaulurivit piirtyvät kokonaan pelin omalla fontilla',
          blank.size === 0 && wideBoard.length === 0,
          blank.size ? `fontista puuttuu: ${[...blank].join(' ')}`
            : `${lines.length + board.length} riviä, levein ${Math.max(...[...lines, ...board].map((l) => textWidth(l)))}px`);
      }

      // 45 200 eikä 45200: kolmen ryhmät ovat ainoa syy siihen että ruudulta
      // näkee yhdellä silmäyksellä onko luku kymmeniä vai satojatuhansia.
      expect('haasteen pisteet ryhmitellään luettavaan muotoon',
        ch.groupThousands(45200) === '45 200' && ch.groupThousands(999) === '999'
        && ch.groupThousands(9999999) === '9 999 999',
        ch.groupThousands(45200));

      /* Alkuruutu piirtää haasteen omalla fontillaan. Seisova peli saa oman
       * seisojan (`Object.create`) samasta syystä kuin esittelytila: testin ei
       * pidä jättää haastetta oikeaan peliin roikkumaan. */
      {
        const c = document.createElement('canvas');
        c.width = 320;
        c.height = 240;
        const g = c.getContext('2d');
        const leaks = [];
        /* Sama ruutu samalla tikillä, haasteella ja ilman: erotus on juuri se
         * mitä haaste piirtää. Pelkkä "onko tuolla jotain" ei erottaisi
         * haastetta taivaan liukuväristä, ja se testi menisi läpi tyhjänäkin. */
        const shot = (ch) => {
          const stand = Object.create(game);
          if (ch) stand.challenge = ch;
          const title = new TitleScene(stand);
          title.enter();
          title.tick = 40;
          title.puffs = [];
          g.clearRect(0, 0, 320, 240);
          title.draw(g);
          if (g.globalAlpha !== 1) leaks.push(`alpha ${g.globalAlpha}`);
          if (g.globalCompositeOperation !== 'source-over') leaks.push(g.globalCompositeOperation);
          return new Uint8ClampedArray(g.getImageData(0, 0, 320, 240).data);
        };
        const diff = (a, b) => {
          let n = 0;
          let outside = 0;
          for (let p = 0; p < a.length; p += 4) {
            if (a[p] === b[p] && a[p + 1] === b[p + 1] && a[p + 2] === b[p + 2]) continue;
            n++;
            // Alkuruudun logolaatikko alkaa riviltä 26; haaste ei saa peittää
            // sitä eikä valikkoa, joten muutoksen pitää mahtua taivaskaistaan.
            if (Math.floor(p / 4 / 320) >= 26) outside++;
          }
          return { n, outside };
        };
        const plain = shot(null);
        const openPx = shot({ ...widestCh, beaten: false });
        const wonPx = shot({ ...widestCh, beaten: true });
        const open = diff(plain, openPx);
        const won = diff(plain, wonPx);
        /* Kolmas vertailu on se joka oikeasti mittaa tekstin: taustapalkki
         * muuttaa koko kaistan kummassakin tapauksessa, joten pelkkä "erosi
         * tyhjästä" saturoituu palkkiin eikä näkisi tekstiä lainkaan. */
        const wording = diff(openPx, wonPx);
        expect('alkuruutu näyttää haasteen omalla rivillään eikä muuten muutu',
          leaks.length === 0 && open.n > 200 && won.n > 200 && wording.n > 100
          && open.outside === 0 && won.outside === 0 && wording.outside === 0
          && !game.challenge,
          leaks.join(', ')
          || `avoin ${open.n}px, voitettu ${won.n}px, sanamuotoero ${wording.n}px`
             + ` (väärässä paikassa ${open.outside}/${won.outside}/${wording.outside})`);
      }

      /* Pistetaulu on se ruutu joka kertoo voitosta: kierros päättyy sinne aina.
       * Ilman tätä haaste on pelkkä kuvateksti. */
      {
        const stand = Object.create(game);
        stand.challenge = { score: 45200, name: 'OLLI', level: '2-3', beaten: false };
        const lost = new HighScoreScene(stand, -1, null, 45200);
        const lostFlag = lost.beat;
        const won = new HighScoreScene(stand, -1, null, 45201);
        expect('pistetaulu kertoo kun haaste on voitettu, ja vasta silloin',
          lostFlag === false && won.beat === true && stand.challenge.beaten === true,
          `tasapeli ${lostFlag}, voitto ${won.beat}`);
      }

      /* …ja sama koko kierroksen mitalta, `finishRun`in kautta. Ero edelliseen
       * on olennainen: yllä testattiin että ruutu osaa kertoa, tässä että
       * tulos ylipäätään päätyy sinne. Kolme reittiä, ja ne menevät eri kautta:
       * listalle päässyt kierros käy nimikysymyksen läpi, listan ulkopuolelle
       * jäänyt ei, ja warpattu kierros ei saa voittaa haastetta lainkaan. */
      {
        const target = { score: 45200, name: 'OLLI', level: '2-3', beaten: false };
        const finish = (score, extra = {}) => {
          const stand = Object.create(game);
          stand.challenge = { ...target };
          stand.state = {
            ...game.state, score, world: 1, continues: 0, usedSaveState: false, ...extra,
          };
          stand.pendingNode = { level: '2-3' };
          stand.finishRun();
          if (stand.scene.constructor.name === 'NameEntryScene') stand.scene.submit();
          return stand.scene;
        };

        // Täysi taulu, jotta listan ulkopuolelle jäävä kierros on saatavissa.
        scores.clearScores();
        for (let i = 0; i < 10; i++) {
          scores.addScore({ name: 'HUIPPU', score: 9999999 - i, world: 5, level: '5-F' });
        }
        const offBoard = finish(45201);
        scores.clearScores();
        const onBoard = finish(45201);
        scores.clearScores();
        const short = finish(45200);
        scores.clearScores();
        const warped = finish(9999999, { debugWarped: true });
        scores.clearScores();

        expect('haasteen voitto kerrotaan myös listan ulkopuolelle jääneelle kierrokselle',
          offBoard.constructor.name === 'HighScoreScene' && offBoard.beat === true
          && onBoard.constructor.name === 'HighScoreScene' && onBoard.beat === true
          && short.beat === false && warped.beat === false,
          `ulkona ${offBoard.beat}, listalla ${onBoard.beat}, tasapeli ${short.beat}, warpattu ${warped.beat}`);

        scores.addScore({ name: 'TESTI', score: 12345, world: 2, level: '2-3' });
      }

      /* Tämä on koko ominaisuuden vaarallisin kohta: jos vastaanottaja jakaa
       * omasta jakoruudustaan, lähtevän linkin pitää kantaa *hänen* tuloksensa.
       * Muuten linkki muuttuu matkalla ja kaveripiiri jakaa yhtä ja samaa
       * pistemäärää ristiin. */
      {
        const stand = Object.create(game);
        stand.challenge = { score: 45200, name: 'OLLI', level: '2-3', beaten: false };
        const scene = new share.ShareScene(stand, null);
        expect('vastaanotettu haaste ei matkusta eteenpäin omassa jakolinkissä',
          scene.url.includes('s=12345') && !scene.url.includes('45200')
          && !scene.url.includes('OLLI'), scene.url);
      }

      /* Osoitelaatikko on porras 3: se osoite jonka pelaaja kirjoittaa ylös kun
       * jakovalikkoa ja leikepöytää ei ole. Jaettu linkki kantaa tuloksen,
       * mutta laatikossa lukee perusosoite — koska pelin 5x7-fontissa **ei ole
       * et-merkkiä**, ja kyselymerkkijono piirtyisi ilman sitä rikkinäisenä.
       *
       * Se ei ole mielipide vaan mitattavissa: piirretään jokainen laatikon
       * merkki yksinään ja katsotaan jäikö mustetta. Puuttuva glyyfi jättää
       * tyhjää mutta siirtää silti kohdistinta, eli virhe olisi näkymätön
       * kaikille paitsi sille joka yrittää kirjoittaa osoitteen ylös. */
      {
        scores.clearScores();
        scores.addScore({ name: 'ÄÄKKÖS', score: 9999999, world: 5, level: '5-F' });
        const scene = new share.ShareScene(game, null);
        const ink = document.createElement('canvas');
        ink.width = 16;
        ink.height = 12;
        const ig = ink.getContext('2d');
        const blank = [];
        for (const chr of new Set(scene.shown.toUpperCase())) {
          if (chr === ' ') continue;
          ig.clearRect(0, 0, 16, 12);
          drawTextFn(ig, chr, 1, 1, { color: '#ffffff' });
          const px = ig.getImageData(0, 0, 16, 12).data;
          let lit = 0;
          for (let p = 3; p < px.length; p += 4) if (px[p] > 0) lit++;
          if (!lit) blank.push(chr);
        }
        expect('osoitelaatikon osoite on kokonaan piirtokelpoinen ja mahtuu laatikkoon',
          blank.length === 0 && textWidth(scene.shown) <= 268
          && scene.shown === meta && scene.url !== scene.shown
          && scene.carries === true && scene.url.includes('s=9999999'),
          blank.length ? `fontista puuttuu: ${blank.join(' ')}`
            : `laatikko ${scene.shown} (${textWidth(scene.shown)}px), lähtee ${scene.url}`);
        scores.clearScores();
        scores.addScore({ name: 'TESTI', score: 12345, world: 2, level: '2-3' });
      }
    }

    unstub();
    scores.clearScores();
    reset();
    game.toTitle();
  }

  /* ------------------------------ telemetry ---------------------------- */
  {
    const tele = await import('/src/core/telemetry.js');
    tele.clearTelemetry();

    // A death has to land in the log with the right cause and the right column,
    // because a heatmap pointing at the wrong tile is worse than no heatmap.
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const i = mkInput();
    for (let f = 0; f < 4; f++) s.update(i);
    const column = Math.floor(s.player.cx / 16);
    s.player.die('pit');
    const deaths = tele.allEvents().filter((e) => e.e === 'die');
    expect('a death is logged with its cause and column',
      deaths.length === 1 && deaths[0].c === 'pit' && deaths[0].x === column
      && deaths[0].l === '1-1',
      JSON.stringify(deaths[0] || null));

    // …and only once. A rewind used to be able to log the same death twice,
    // which quietly doubled the weight of whatever spot someone was practising.
    s.player.dying = false;
    s.player.die('lava');
    expect('one attempt logs one death',
      tele.allEvents().filter((e) => e.e === 'die').length === 1);

    // Falling out of the world reports as a pit, not as an enemy.
    reset({ type: 'shroom', level: 1 });
    const s2 = new LevelScene(game, '1-1');
    game.setScene(s2);
    s2.update(i);
    s2.player.y = s2.heightPx + 200;
    s2.player.noclip = true;
    for (let f = 0; f < 3 && !s2.player.dying; f++) s2.update(i);
    const fell = tele.allEvents().filter((e) => e.e === 'die').at(-1);
    expect('falling out of the world is logged as a pit', fell && fell.c === 'pit',
      fell ? fell.c : 'ei tapahtumaa');

    // Standing still long enough is a stall, and it is logged once per column —
    // a player who wanders off for a minute must not fill the log by himself.
    tele.clearTelemetry();
    reset({ type: 'shroom', level: 1 });
    const s3 = new LevelScene(game, '1-1');
    game.setScene(s3);
    s3.entities = s3.entities.filter((e) => e.kind !== 'enemy');   // this is about standing, not dying
    const idle = mkInput();
    for (let f = 0; f < 1100; f++) { s3.update(idle); idle.pressed = blank(); }
    const stalls = tele.allEvents().filter((e) => e.e === 'stuck');
    expect('standing still is logged once as a stall',
      stalls.length === 1 && stalls[0].l === '1-1',
      `${stalls.length} kpl`);

    // Walking on must not count as stuck at all.
    tele.clearTelemetry();
    const s4 = new LevelScene(game, '1-1');
    game.setScene(s4);
    s4.entities = s4.entities.filter((e) => e.kind !== 'enemy');
    const walk = mkInput();
    walk.held.right = true;
    for (let f = 0; f < 600; f++) { s4.update(walk); walk.pressed = blank(); }
    expect('a player who keeps moving is never called stuck',
      tele.allEvents().filter((e) => e.e === 'stuck').length === 0);

    // Clearing a level records what it cost.
    tele.clearTelemetry();
    expect('the game counts attempts per level', !!game.attempts);
    if (game.attempts) game.attempts['1-1'] = 2;
    const s5 = new LevelScene(game, '1-1');
    game.setScene(s5);
    s5.update(mkInput());
    s5.completeLevel('shroom');
    const clear = tele.allEvents().find((e) => e.e === 'clear');
    expect('a cleared level records the attempts it took',
      clear && clear.d === 2 && clear.l === '1-1' && game.attempts && game.attempts['1-1'] === 0,
      JSON.stringify(clear || null));

    // The export has to be valid JSON with the events in it, or phase 2 is a lie.
    const dump = JSON.parse(tele.exportJSON());
    expect('the export is valid JSON carrying the events',
      dump.game === 'sfb3' && Array.isArray(dump.events) && dump.events.length > 0,
      `${dump.events ? dump.events.length : '?'} tapahtumaa`);

    // Nothing in this module may reach the network.
    const src = await (await fetch('/src/core/telemetry.js')).text();
    expect('telemetry never sends anything anywhere',
      !/fetch\s*\(|XMLHttpRequest|sendBeacon|WebSocket/.test(src));

    tele.clearTelemetry();
  }

  /* ------------------------- pavun istuttaminen ------------------------- */
  /*
   * Red before green (DESIGN.md §7) for the beanstalk that grows instead of
   * standing there.
   *
   * The whole point of the change is a gap between two pictures of the same
   * level: `getLevel('1-2').rows` is the GROWN level — that is what
   * `src/data/rules.js` validates and what proves the sky band can be reached —
   * and `LevelScene.grid` starts out as the UNGROWN one. So the assertions are
   * a comparison between those two, tile for tile, rather than a count somebody
   * typed in: the level data stays the single source of truth for where the
   * vine goes, and this is the test that the two ever agree.
   *
   * Nothing below names a column or a row: the vine's own position is read out
   * of the level data and the block's position is derived from it the way the
   * rule says it is, so this keeps testing the mechanic if the chunk moves.
   */
  {
    const { getLevel } = await import('/src/data/levels.js');
    const { Sfx } = await import('/src/core/audio.js');
    const { BEAN_BLOCK_OVER_FLOOR } = await import('/src/scenes/level.js');
    const { RULE_CONSTANTS } = await import('/src/data/rules.js');
    reset();
    const bean = new LevelScene(game, '1-2');
    bean.time = 9999;
    bean.clockStopped = true;
    game.scene = bean;
    const def = getLevel('1-2').rows;

    /* Where the block hangs is one number kept in two files — the validator may
     * not import a scene and the engine may not import the validator — so the
     * two copies are asserted against each other, exactly as the secret-brick
     * rates are. A drift here would let the gate bless a block the engine puts
     * somewhere else. */
    expect('the engine and the validator agree where a bean block hangs',
      BEAN_BLOCK_OVER_FLOOR === RULE_CONSTANTS.BEAN_BLOCK_OVER_FLOOR,
      `moottori ${BEAN_BLOCK_OVER_FLOOR}, säännöt ${RULE_CONSTANTS.BEAN_BLOCK_OVER_FLOOR}`);

    const wanted = [];
    for (let ty = 0; ty < def.length; ty++) {
      for (let tx = 0; tx < def[ty].length; tx++) if (def[ty][tx] === 'v') wanted.push([tx, ty]);
    }
    const foot = wanted.reduce((a, b) => (b[1] > a[1] ? b : a), wanted[0] || [0, 0]);
    const blockAt = [foot[0], foot[1] + 1 - BEAN_BLOCK_OVER_FLOOR];
    const liveVines = () => wanted.filter(([tx, ty]) => bean.rawTileAt(tx, ty) === 'v').length;

    expect('a beanstalk is not standing there when the level loads',
      wanted.length > 0 && liveVines() === 0
      && bean.rawTileAt(blockAt[0], blockAt[1]) === '?',
      `kentässä ${wanted.length} varsiruutua, ruudukossa ${liveVines()}, `
      + `lohko "${bean.rawTileAt(blockAt[0], blockAt[1])}" kohdassa `
      + `${blockAt[0]},${blockAt[1]} (jalka rivillä ${foot[1]})`);

    /* The sound comes with the picture (DESIGN.md §8), and it has to be its
     * own: the three payouts a block already has are a coin, a power-up and a
     * dead thud, and a fourth event wearing one of those is a fourth event the
     * player mis-reads. */
    const heard = [];
    const realPlay = Sfx.play;
    Sfx.play = function spy(name) { heard.push(name); return realPlay.call(this, name); };
    bean.bumpTile(blockAt[0], blockAt[1], bean.player);
    Sfx.play = realPlay;

    const grew = [];
    for (let f = 0; f < 400; f++) {
      bean.update(mkInput());
      if (f === 20 || f === 40 || f === 60) grew.push(liveVines());
    }
    const missing = wanted.filter(([tx, ty]) => bean.rawTileAt(tx, ty) !== 'v');

    expect('hitting the block grows exactly the beanstalk the rules validated',
      missing.length === 0 && liveVines() === wanted.length,
      `${liveVines()}/${wanted.length} ruutua, puuttuu ${missing.length}`
      + (missing.length ? ` (esim. ${missing[0]})` : ''));

    /* A tile at a time, not a vine that appears. Measured at three moments
     * rather than asserted as a constant, because the speed is a feel decision
     * and this test is about the growing. */
    expect('the vine grows a tile at a time rather than appearing',
      grew[0] > 0 && grew[0] < grew[1] && grew[1] < grew[2] && grew[2] < wanted.length,
      `20/40/60 framea: ${grew.join(' -> ')} / ${wanted.length}`);

    expect('the bean has a sound of its own and does not borrow another',
      heard.length === 1 && heard[0] === 'sprout' && Sfx.has('sprout'),
      `soi [${heard.join(', ')}]`);

    /* And it grows from the floor up: the tile the bean landed in is there long
     * before the one that crosses into the sky band. The spent block is one of
     * the tiles that gets written — the stalk grows through the block it came
     * out of — which is what lets a finished vine be climbed from the ground. */
    const order = new LevelScene(game, '1-2');
    order.time = 9999;
    order.clockStopped = true;
    game.scene = order;
    order.bumpTile(blockAt[0], blockAt[1], order.player);
    for (let f = 0; f < 24; f++) order.update(mkInput());
    const low = order.rawTileAt(foot[0], foot[1]) === 'v';
    const high = order.rawTileAt(wanted[0][0], wanted[0][1]) === 'v';
    expect('the beanstalk grows upward from the floor, not downward from the sky',
      low && !high,
      `24 framen jälkeen jalka ${low ? 'on' : 'ei ole'} (rivi ${foot[1]}), `
      + `latva ${high ? 'on' : 'ei ole'} (rivi ${wanted[0][1]})`);
    for (let f = 0; f < 400; f++) order.update(mkInput());
    expect('the grown stalk runs unbroken from the floor through the spent block',
      order.rawTileAt(blockAt[0], blockAt[1]) === 'v'
      && order.rawTileAt(foot[0], foot[1]) === 'v',
      `lohkon paikalla "${order.rawTileAt(blockAt[0], blockAt[1])}", `
      + `jalassa "${order.rawTileAt(foot[0], foot[1])}"`);

    /* A quicksave taken while the stalk is halfway up has to come back halfway
     * up and finish, which is the whole reason `Beanstalk` is in the REGISTRY
     * (DESIGN.md §6): the tiles it has already written are in the saved grid,
     * and the ones it has not written are nowhere but in the entity. Without
     * the entry the snapshot would restore a level with half a beanstalk in it
     * and nothing left alive to finish the job. */
    {
      reset();
      const half = new LevelScene(game, '1-2');
      half.entities = half.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      half.time = 9999;
      half.clockStopped = true;
      game.setScene(half);
      half.bumpTile(blockAt[0], blockAt[1], half.player);
      for (let f = 0; f < 40; f++) half.update(mkInput());
      const partway = wanted.filter(([tx, ty]) => half.rawTileAt(tx, ty) === 'v').length;
      const snap = JSON.parse(JSON.stringify(captureState(game)));
      const kinds = snap.level.entities.map((d) => d.t);
      restoreState(game, snap);
      const back = game.scene;
      for (let f = 0; f < 400; f++) back.update(mkInput());
      const done = wanted.filter(([tx, ty]) => back.rawTileAt(tx, ty) === 'v').length;
      expect('a beanstalk caught half-grown survives a save state — REGISTRY',
        kinds.includes('Beanstalk') && partway > 0 && partway < wanted.length
        && done === wanted.length,
        `tallennettaessa ${partway}/${wanted.length}, latauksen jälkeen `
        + `${done}/${wanted.length}, oliot [${kinds.join(' ')}]`);
    }
  }

  /* --------------------- pavunvarsi ja piilotettu alue ------------------ */
  {
    const mk = (power) => {
      reset(power);
      const s = new LevelScene(game, '1-2');
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      game.scene = s;
      return s;
    };
    const put = (s, tx, ty) => {
      s.player.x = tx * 16 + (16 - s.player.w) / 2;
      s.player.y = ty * 16 - s.player.h;
      s.player.vy = 0;
      s.player.climbing = false;
      s.player.warpLock = 0;
    };
    const hold = (s, i, keys, frames) => {
      for (let f = 0; f < frames; f++) {
        i.held = blank();
        for (const k of keys) i.held[k] = true;
        i.pressed = blank();
        s.update(i);
      }
    };
    /* A jump, held. The press has to be a press and not a hold — the engine
     * jumps off `pressed.jump` — which is the whole reason this is not `hold`
     * with 'jump' in the list. */
    const leap = (s, i, frames) => {
      for (let f = 0; f < frames; f++) {
        i.held = blank();
        i.held.jump = true;
        i.pressed = blank();
        if (f === 0) i.pressed.jump = true;
        s.update(i);
      }
    };

    /* Both ends of the size range. The widest body is three tiles across while
     * it hangs off a vine, so anything solid beside the vine is a ceiling only
     * the big player hits — exactly the sort of thing that ships unnoticed.
     *
     * And it starts from the block now, because that is the level: standing on
     * the floor under the bump row, a jump, the bean, and only then a vine. The
     * two halves of the trip are deliberately the same test — a beanstalk that
     * grows and cannot be climbed, or one that can be climbed at only some
     * sizes, is the same failure to the player either way. */
    for (const power of [{ type: null, level: 0 }, { type: 'leaf', level: 5 }]) {
      const s = mk(power);
      const i = mkInput();
      put(s, 150, 30);
      leap(s, i, 40);
      const planted = s.rawTileAt(150, 26) !== '?';
      hold(s, i, [], 140);
      hold(s, i, ['up'], 360);
      const up = s.player.y + s.player.h < 16 * 16;
      hold(s, i, ['right'], 60);
      const onPlatform = s.player.onGround && Math.round(s.player.y + s.player.h) === 10 * 16;
      const coins = game.state.coins;
      hold(s, i, ['right'], 180);          // walk off the edge and fall home
      expect(`power ${power.level} plants the bean, climbs it and gets back down`,
        planted && up && onPlatform && game.state.coins > coins && s.player.onGround
        && !s.player.dying && s.player.y + s.player.h > 29 * 16,
        `lohko ${planted}, taivaassa ${up}, lavalla ${onPlatform}, `
        + `jalat ${Math.round(s.player.y + s.player.h)}`);

      // Down the pipe, and — the part that matters — back out of it. A bonus
      // area you cannot leave is a trap, not a bonus.
      const c = mk(power);
      put(c, 229, 28);
      // 90 and not 40: going down a pipe is a slide now, and there is still a
      // drop to the cave floor at the end of it.
      hold(c, i, ['down'], 90);
      const inCave = c.player.y > 32 * 16 && c.player.onGround && !c.player.dying;
      /* Standing on the room's floor under the exit, not on top of a pipe: the
       * way out hangs from the ceiling now, and you leave the way you came —
       * facing the mouth you are about to travel through. */
      put(c, 250, 46);
      hold(c, i, [], 3);
      c.player.warpLock = 0;
      hold(c, i, ['up'], 90);
      hold(c, i, [], 20);
      expect(`the warp pipe takes power ${power.level} down and the cave lets it out`,
        inCave && c.player.y < 32 * 16 && c.player.onGround && !c.player.dying
        && c.state === 'play',
        `luolassa ${inCave}, paluu ${Math.round(c.player.y + c.player.h)}`);
    }

    const s = mk({ type: null, level: 0 });
    const i = mkInput();
    put(s, 229, 28);
    const y0 = s.player.y;
    hold(s, i, ['up'], 60);
    expect('a warp pipe will not throw you into empty sky',
      Math.abs(s.player.y - y0) < 1, `${Math.round(y0)} -> ${Math.round(s.player.y)}`);

    /* Stacking bands changes what a pit is: a bottomless column in the route
     * band now has a cellar under it. Falling in has to still kill, and kill at
     * the same moment, rather than become a scenic tour of the secret. */
    const pit = mk({ type: null, level: 0 });
    pit.player.x = 71 * 16;
    pit.player.y = 26 * 16;
    let frames = 0;
    while (pit.state === 'play' && frames < 200) { pit.update(i); frames++; }
    expect('falling into a pit still kills instead of touring the secret',
      pit.state === 'dead' && frames < 45 && pit.player.y < 32 * 16,
      `${frames} framea, y ${Math.round(pit.player.y)}`);

    // And walking the ordinary route must never show the band above or below.
    const run = mk({ type: 'shroom', level: 1 });
    let worst = 16 * 16;
    for (let f = 0; f < 900 && run.state === 'play'; f++) {
      i.held = blank(); i.held.right = true; i.held.run = true;
      i.pressed = blank();
      if (run.player.onGround && f % 27 === 0) { i.pressed.jump = true; i.held.jump = true; }
      run.update(i);
      worst = Math.max(worst, run.cam.y);
    }
    expect('the ground route never shows another band', worst <= 16 * 16 + 32,
      `cam.y ${Math.round(worst)}`);
  }

  /* ------------------- putken suunta ja putkessa kulkeminen -------------- */
  /*
   * Red before green (DESIGN.md §7) for the rule that the direction you travel
   * has to match the mouth you enter — and for the content that now obeys it.
   *
   * The fixture used to be two pipes pasted into a level, because no shipped
   * chunk had a ceiling pipe: every upward warp in the game stood on the floor,
   * which is what `WARP_COMPAT.upFromFloor` existed to keep working. The rooms
   * carry their own ceilings now, so the rule is proved against them directly.
   *
   * **Every hidden room, in and out, at all six body sizes.** That is the only
   * evidence that matters here. A room you can enter and not leave is the trap
   * `secrets.js` exists to prevent, and the body that gets stuck is the tallest
   * (21x43 px) — which is also the one that arrives last, because every one of
   * these rooms holds a power-up.
   */
  {
    const mk = (power, id = '1-2') => {
      reset(power);
      const s = new LevelScene(game, id);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      game.scene = s;
      return s;
    };
    /* `ty` is always the row the **feet** stand on — on a floor pipe's mouth,
     * or on the floor under a ceiling pipe's. That is one sentence for both
     * directions: stand where the pipe is and press the way it points. */
    const put = (s, tx, ty) => {
      s.player.x = tx * 16 + (16 - s.player.w) / 2;
      s.player.y = ty * 16 - s.player.h;
      s.player.vy = 0;
      s.player.onGround = true;
      s.player.climbing = false;
      s.player.warpLock = 0;
      s.centerCamera();
    };
    const hold = (s, i, keys, frames) => {
      for (let f = 0; f < frames; f++) {
        i.held = blank();
        for (const k of keys) i.held[k] = true;
        i.pressed = blank();
        s.update(i);
      }
    };
    const i = mkInput();
    const bandOf = (s) => Math.floor((s.player.y + s.player.h - 1) / (16 * 16));

    /* The five hidden rooms in the game, and the two journeys each one owes
     * the player. `into` is the band the way in arrives in: 0 is the sky, 2 is
     * the cave, and coming back always means band 1. */
    const ROOMS = [
      { room: 'cave_room (1-2)', id: '1-2', in: [229, 28, 'down'], out: [250, 46, 'up'], into: 2 },
      { room: 'tomb_cave (2-2)', id: '2-2', in: [229, 28, 'down'], out: [235, 46, 'up'], into: 2 },
      { room: 'cave_room (3-2)', id: '3-2', in: [233, 28, 'down'], out: [254, 46, 'up'], into: 2 },
      { room: 'fac_cellar (4-2)', id: '4-2', in: [133, 28, 'down'], out: [140, 46, 'up'], into: 2 },
      { room: 'fac_loft (4-2)', id: '4-2', in: [245, 30, 'up'], out: [252, 13, 'down'], into: 0 },
    ];

    for (const r of ROOMS) {
      const bad = [];
      for (let level = 0; level <= 5; level++) {
        const power = level === 0 ? { type: null, level: 0 } : { type: 'shroom', level };
        const into = mk(power, r.id);
        put(into, r.in[0], r.in[1]);
        hold(into, i, [r.in[2]], 120);
        hold(into, i, [], 30);
        if (!(bandOf(into) === r.into && into.player.onGround && !into.player.dying)) {
          bad.push(`koko ${level} ei päässyt sisään (kaista ${bandOf(into)})`);
        }
        const back = mk(power, r.id);
        put(back, r.out[0], r.out[1]);
        hold(back, i, [], 3);
        back.player.warpLock = 0;
        hold(back, i, [r.out[2]], 120);
        hold(back, i, [], 30);
        if (!(bandOf(back) === 1 && back.player.onGround && !back.player.dying
          && back.state === 'play')) {
          bad.push(`koko ${level} ei päässyt ulos (kaista ${bandOf(back)})`);
        }
      }
      expect(`${r.room} is enterable and leavable at all six sizes`,
        bad.length === 0, bad.join(', ') || 'kuusi kokoa sisään ja ulos');
    }

    /*
     * And the rule itself, stated as a refusal, because the room tests above
     * would still pass if `tryWarp` went back to reading one tile in both
     * directions.
     *
     * The pipe is pasted in rather than borrowed: no floor pipe in the shipped
     * game has a legal band above it any more, and a refusal that could be
     * blamed on the landing proves nothing about the direction. This one has a
     * landing — clear surface at columns 252-253 with the route's own ground
     * under it — and is refused anyway, because it is a pipe you are standing
     * on top of and the top of a pipe is capped.
     */
    const floorPipe = mk({ type: null, level: 0 });
    floorPipe.grid[45][252] = '(';
    floorPipe.grid[45][253] = ')';
    put(floorPipe, 252, 45);
    const stayY = floorPipe.player.y;
    hold(floorPipe, i, ['up'], 60);
    expect('pressing up on a pipe standing on the floor is not a way in',
      Math.abs(floorPipe.player.y - stayY) < 1 && !floorPipe.player.transit,
      `${Math.round(stayY)} -> ${Math.round(floorPipe.player.y)}`);

    /* …and the same pipe pressed downwards is refused too, for the other half
     * of the reason: below it is the bottom of the level. Nothing about the
     * fixture is a warp that happens to be broken. */
    const noBand = mk({ type: null, level: 0 });
    noBand.grid[45][252] = '(';
    noBand.grid[45][253] = ')';
    put(noBand, 252, 45);
    const downY = noBand.player.y;
    hold(noBand, i, ['down'], 60);
    expect('a warp with no band under it stays put',
      Math.abs(noBand.player.y - downY) < 1 && !noBand.player.transit,
      `${Math.round(downY)} -> ${Math.round(noBand.player.y)}`);

    /* ----------------------- putkessa kulkeminen ----------------------- */
    /*
     * The warp used to be `p.y += shift` on one frame. It is a slide now, and
     * the three things that must be true of any such slide: it takes time, the
     * player cannot act or be acted upon while it runs, and it ends exactly
     * where the instant version ended.
     */
    {
      const s = mk({ type: 'shroom', level: 1 });
      put(s, 229, 28);
      /* Measured at the feet, not at `y`. Pressing down ducks a big player on
       * the way in, and `applySize` pins the bottom of the body and moves `y`;
       * the feet are the thing that is actually one band lower afterwards. */
      const before = s.player.y + s.player.h;
      /*
       * Matkan pää luetaan parista eikä siirtymästä, ja tämä rivi on korjaus.
       *
       * Tässä luki `before + 15 * 16`, eli "liuku päättyy sinne mihin hetkessä
       * tapahtunut siirto päättyi". Se oli tosi niin kauan kuin matkan pää oli
       * lähtökorkeus siirrettynä — ja juuri se oli se vika jonka omistaja näki
       * (hahmo ilmestyi tyhjään ilmaan). Nyt pää on se putken suu jonka
       * `plantWarpExits` pystytti, ja koe kysyy sitä samasta paikasta kuin peli.
       */
      const exitRow = s.warpExits.get('229,28');
      const target = exitRow * 16;
      let frames = 0;
      let acted = 0;
      let hurtLanded = 0;
      i.held = blank(); i.held.down = true; i.pressed = blank();
      s.update(i);
      const started = !!s.player.transit;
      while (s.player.transit && frames < 200) {
        frames++;
        // Everything a player could try, every frame, plus an enemy's worth of
        // damage. None of it may reach him.
        i.held = blank();
        i.held.right = true; i.held.jump = true; i.held.run = true;
        i.pressed = blank(); i.pressed.jump = true; i.pressed.run = true;
        const px = s.player.x;
        if (s.player.hurt('enemy')) hurtLanded++;
        s.update(i);
        if (Math.abs(s.player.x - px) > 0.001 || s.player.vx !== 0 || s.player.vy !== 0) acted++;
      }
      // Measured where the slide left him and not a moment later: the arrival
      // is the mouth of the paired pipe, and he is standing on it.
      // `controllable` is in here because taking the controls away is easy and
      // giving them back is the half that gets forgotten.
      expect('entering a pipe is a slide, and nothing reaches the player during it',
        started && frames > 20 && frames < 60 && acted === 0 && hurtLanded === 0
        && s.player.powerLevel === 1 && s.player.controllable === true
        && Math.abs((s.player.y + s.player.h) - target) < 1,
        `${frames} framea, liikkui ${acted}, osumia ${hurtLanded}, `
        + `ohjattavissa ${s.player.controllable}, jalat `
        + `${Math.round(before)} -> ${Math.round(s.player.y + s.player.h)} `
        + `(odotus ${target}, eli putken suu rivillä ${exitRow})`);
    }

    /*
     * A quicksave taken mid-slide. The state is a plain object on the player,
     * so `savestate.js` carries it with no help; the load has to come back
     * inside the pipe and finish the journey at the right place. Refusing the
     * save was the alternative and it is worse — a quicksave key that silently
     * does nothing for half a second is a bug report, not a policy.
     */
    {
      const s = mk({ type: 'shroom', level: 1 });
      put(s, 229, 28);
      const target = s.warpExits.get('229,28') * 16;         // putken suu, ks. yllä
      game.setScene(s);
      i.held = blank(); i.held.down = true; i.pressed = blank();
      for (let f = 0; f < 8; f++) s.update(i);
      const midway = !!s.player.transit && s.player.transit.phase === 'in';
      game.slot = 3;
      game.quickSave();
      game.quickLoad();
      const back = game.scene;
      const restored = !!(back.player.transit && back.player.transit.phase === 'in');
      const idle = mkInput();
      for (let f = 0; f < 90 && back.player.transit; f++) back.update(idle);
      expect('a quicksave taken inside a pipe loads back inside it and finishes',
        midway && back !== s && restored && !back.player.transit
        && !back.player.dying
        && Math.abs((back.player.y + back.player.h) - target) < 1,
        `tallennettu ${midway}, palautettu ${restored}, jalat `
        + `${Math.round(back.player.y + back.player.h)} (odotus ${Math.round(target)})`);
      game.slot = 1;
    }

    /*
     * The scene stops updating 140 frames after a death (DESIGN.md §6), so a
     * transit that could outlive that would leave a body parked inside a pipe.
     * It cannot: the clock stops, the collisions stand aside and `hurt`
     * refuses, so nothing in the level can kill a travelling player — and a
     * death forced from outside drops the transit rather than racing it.
     */
    {
      const s = mk({ type: null, level: 0 });
      put(s, 229, 28);
      s.time = 1;
      s.timeSub = 20;      // four frames from zero, and the trip lasts thirty
      i.held = blank(); i.held.down = true; i.pressed = blank();
      s.update(i);
      let ticked = 0;
      while (s.player.transit && ticked < 200) { s.update(i); ticked++; }
      const clockHeld = s.time === 1 && s.state === 'play';
      const forced = mk({ type: null, level: 0 });
      put(forced, 229, 28);
      forced.update(i);
      const running = !!forced.player.transit;
      forced.player.die('debug');
      expect('nothing can kill a player inside a pipe, and a forced death ends the trip',
        clockHeld && running && forced.player.transit === null && forced.player.dying,
        `kello ${s.time}, tila ${s.state}, kesken ${running}`);
    }
  }

  /* ---------------- tilanvaihdos joka ei kuulunut eikä näkynyt ----------- */
  /*
   * DESIGN.md kohta 8, molemmat puolet: **kuva ja ääni yhdessä**, ja **kaksi
   * samaa sanovaa merkkiä opettaa lukemaan väärää**. Tämä lohko mittaa neljä
   * tilanvaihdosta joista jokainen muuttaa jotain minkä pelaaja sai tähän asti
   * selville kokeilemalla.
   *
   * Punainen ennen vihreää on tässä se hyödyllinen puoli. Jokainen alla oleva
   * väite kaatui ennen muutosta, ja **se kaatuminen on koko todiste siitä että
   * merkkiä ei ollut**: "mittari täyttyi framella 87, ääni '-', 0 px ruudusta
   * muuttui" on mittaus hiljaisuudesta, ei mielipide siitä että jotain pitäisi
   * ehkä lisätä.
   *
   * Kuva mitataan **pelialueesta eikä HUDista** (0…VIEW_H), ja se on väitteen
   * ydin eikä tekninen yksityiskohta: mittari vilkkuu HUDissa jo nyt, ja
   * HUD-palkki on 320x240-ruudun alalaidassa siinä missä pelaajan silmä on
   * kentässä. Merkki jonka näkee vain katsomalla muualle kuin siihen mitä
   * pelaa ei ole merkki.
   */
  {
    const { Sfx } = await import('/src/core/audio.js');

    /* Äänet jotka tarkoittavat jo jotain muuta. Uusi merkki ei saa olla
     * mikään näistä — ei siksi että uutuus olisi arvo sinänsä, vaan siksi
     * että lainattu ääni tarkoittaa sen jälkeen kahta asiaa. */
    const TAKEN = ['jump', 'bigjump', 'fart', 'bigfart', 'squeak', 'flight', 'coin',
      'stomp', 'bump', 'brick', 'burst', 'sprout', 'dive', 'slam', 'kurnutus',
      'loikka', 'kick', 'spikes', 'pop', 'upota', 'kahlaa', 'cork', 'soup', 'powerup',
      'yeah', 'oof', 'letsgo', 'powerdown', 'oneup', 'die', 'clear', 'cursor', 'select',
      'luuranko', 'boss', 'timewarn', 'door',
      /* `land` ja `card` olivat tässä ja ovat nyt poissa koko taulusta: molemmat
       * oli määritelty eikä kumpaakaan soitettu mistään. Kolme uutta ovat tässä
       * siksi että lista on "nämä tarkoittavat jo jotain", ja nyt ne
       * tarkoittavat. */
      'payout', 'kytkin', 'doorin',
      /* `saapuu` tarkoittaa nyt kuninkaan muodonvaihdosta, ks. lohko
       * "kuninkaan muodonvaihto". Lista on "nämä tarkoittavat jo jotain". */
      'saapuu'];

    const mk = (power, id = '1-1') => {
      reset(power);
      const s = new LevelScene(game, id);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      game.setScene(s);
      return s;
    };
    const put = (s, tx, ty) => {
      s.player.x = tx * 16 + (16 - s.player.w) / 2;
      s.player.y = ty * 16 - s.player.h;
      s.player.vy = 0;
      s.player.onGround = true;
      s.player.warpLock = 0;
      s.centerCamera();
    };
    /* Kuuntelija joka ei soita läpi: nämä väitteet koskevat sitä *mitä* peli
     * pyytää soittamaan ja millä framella, ja oikeasti soitetut äänet jäisivät
     * soimaan tämän tiedoston myöhempien tasomittausten päälle. */
    const listen = () => {
      const real = Sfx.play;
      const heard = [];
      Sfx.play = function tap(name) { heard.push(name); };
      return { heard, off() { Sfx.play = real; } };
    };

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const g = canvas.getContext('2d');
    const PLAY_PX = 320 * 208;
    /** Pelialue pikseleinä, HUD rajattuna pois. */
    const paint = (s) => {
      g.clearRect(0, 0, 320, 240);
      s.draw(g);
      return g.getImageData(0, 0, 320, 208).data;
    };
    const differing = (a, b) => {
      let n = 0;
      for (let p = 0; p < a.length; p += 4) {
        if (a[p] !== b[p] || a[p + 1] !== b[p + 1] || a[p + 2] !== b[p + 2]) n++;
      }
      return n;
    };
    /*
     * MITTARIN MERKKI ON KEHON YMPÄRILLÄ EIKÄ KOKO RUUDULLA (17.8.2026).
     *
     * Tässä luki `MOST = 0,6 × pelialue`, eli portti **vaati** että kolme
     * viidesosaa ruudusta muuttuu. Se oli oikea vaatimus silloin kun merkki oli
     * kokoruudun verho, ja se oli myös se vaatimus joka piti verhon pystyssä
     * pidempään kuin olisi pitänyt: omistaja 17.8.2026 *"koko ruudun välähdys
     * on huono, se tuntuu damagelta"*. Kokoruudun väri on tässä pelissä osuman
     * kieli, eikä etu saa puhua tappion äänensävyllä.
     *
     * Väite kääntyi siis ympäri ja siitä tuli kaksiosainen: merkin on
     * **näyttävä kehon lähellä** ja sen on **jätettävä ruudun toinen laita
     * rauhaan**. `NEAR` on ruutu pelaajan ympärillä (80 px säde) ja `FAR` on
     * kaista vastakkaisessa reunassa; ensimmäisessä on oltava muutosta, ja
     * jälkimmäisen on oltava koskematon sen jälkeen kun tavallinen vieritys on
     * otettu huomioon.
     */
    const boxDiff = (a2, b2, x0, x1) => {
      let n = 0;
      for (let y = 0; y < 208; y++) {
        for (let x = x0; x < x1; x++) {
          const p = (y * 320 + x) * 4;
          if (a2[p] !== b2[p] || a2[p + 1] !== b2[p + 1] || a2[p + 2] !== b2[p + 2]) n++;
        }
      }
      return n;
    };

    /*
     * 1. MITTARI TÄYTTYY. Kaksi asiaa muuttuu oikeasti — nopeuskatto 2,5 ->
     *    3,5 px/frame ja kaasulehdellä hypystä tulee lento — ja kumpikin oli
     *    tähän asti asia jonka sai tietää kokeilemalla.
     */
    let fullSound = null;
    let spentSound = null;
    {
      const s = mk({ type: 'leaf', level: 3 });
      const i = mkInput();
      const tap = listen();
      let fullAt = -1;
      let atFull = [];
      let before = null;
      let after = null;
      try {
        for (let f = 0; f < 300 && fullAt < 0; f++) {
          i.held = blank(); i.held.right = true; i.held.run = true;
          i.pressed = blank();
          before = paint(s);
          const n = tap.heard.length;
          s.update(i);
          if (s.player.pFull) { fullAt = f; atFull = tap.heard.slice(n); }
        }
        after = paint(s);
      } finally { tap.off(); }
      fullSound = atFull[0] || null;
      /* Sama kuva kahdesti samalta framelta: kerran sykäyksen kanssa ja kerran
       * ilman. Näin mittaus koskee **efektiä** eikä sitä että maailma ehti
       * liikkua kahden framen välissä — vieritys ja juokseva hahmo muuttavat
       * pikseleitä kummassakin laidassa ilman että kukaan välähtää. */
      const withPulse = paint(s);
      const keep = s.speedPulse;
      s.speedPulse = 0;
      const without = paint(s);
      s.speedPulse = keep;
      const px = Math.round(s.player.cx - s.cam.x);
      const near = boxDiff(withPulse, without, Math.max(0, px - 80), Math.min(320, px + 80));
      const far = px < 160
        ? boxDiff(withPulse, without, 240, 320)
        : boxDiff(withPulse, without, 0, 80);
      expect('täyttynyt vauhtimittari kuuluu ja näkyy kehon ympärillä — muttei koko ruudulla',
        fullAt >= 0 && atFull.length === 1 && Sfx.has(fullSound)
        && !TAKEN.includes(fullSound) && near > 40 && far === 0,
        `täyttyi framella ${fullAt}, ääni "${atFull.join('+') || '-'}", `
        + `kehon ympärillä ${near} px muuttui, vastakkaisessa laidassa ${far} px`);
      void differing;
      void PLAY_PX;
    }

    /*
     * 2. JA TYHJENEE, mikä on sama tapahtuma takaperin ja tarvitsee merkin
     *    kipeämmin: nopeuskatto putoaa takaisin ja lentäminen lakkaa olemasta
     *    mahdollista. Eri ääni kuin täyttyminen, tai pari ei ole pari vaan
     *    kaksi samaa merkkiä.
     */
    {
      const s = mk({ type: 'leaf', level: 3 });
      const i = mkInput();
      const tap = listen();
      let spentAt = -1;
      let atSpent = [];
      let before = null;
      let after = null;
      try {
        /* Täyteen, ja sitten kaksikymmentä framea täydellä vauhdilla lisää:
         * täyttymisen oma merkki on ohi ennen kuin tyhjenemisen merkkiä
         * mitataan, joten `before` on tavallinen ruutu eikä edellinen efekti. */
        for (let f = 0; f < 320; f++) {
          i.held = blank(); i.held.right = true; i.held.run = true;
          i.pressed = blank();
          s.update(i);
          if (s.player.pFull && f > 20 && !s.speedPulse) break;
        }
        for (let f = 0; f < 300 && spentAt < 0; f++) {
          i.held = blank(); i.pressed = blank();
          before = paint(s);
          const n = tap.heard.length;
          s.update(i);
          if (!s.player.pFull) { spentAt = f; atSpent = tap.heard.slice(n); }
        }
        after = paint(s);
      } finally { tap.off(); }
      [spentSound] = atSpent;
      /* Sama kaksiosainen mitta kuin täyttymisellä: näkyy kehon ympärillä,
       * ei kosketa vastakkaista laitaa. Menetyksen merkki on luhistuva rengas
       * eikä pimennys — ks. `drawSpeedPulse`. */
      const withPulse = paint(s);
      const keep = s.speedPulse;
      s.speedPulse = 0;
      const without = paint(s);
      s.speedPulse = keep;
      const px = Math.round(s.player.cx - s.cam.x);
      const near = boxDiff(withPulse, without, Math.max(0, px - 80), Math.min(320, px + 80));
      const far = px < 160
        ? boxDiff(withPulse, without, 240, 320)
        : boxDiff(withPulse, without, 0, 80);
      expect('tyhjentynyt vauhtimittari kuuluu, ja eri äänellä kuin täyttynyt',
        spentAt >= 0 && atSpent.length === 1 && Sfx.has(spentSound)
        && !TAKEN.includes(spentSound) && spentSound !== fullSound
        && near > 20 && far === 0,
        `tyhjeni framella ${spentAt}, ääni "${atSpent.join('+') || '-'}" `
        + `(täyttyminen "${fullSound || '-'}"), kehon ympärillä ${near} px,`
        + ` vastakkaisessa laidassa ${far} px`);
      void before;
      void after;
    }

    /*
     * 3. JA SE SAMA MERKKI LENNOSSA, joka on koko asian pahin tapaus.
     *
     * Kaasulehdellä täysi mittari on lentolupa, ja lento kuluttaa mittarin.
     * Kaksi asiaa on todistettava yhdessä eikä kumpaakaan yksin:
     *
     *   - **Nousu ei saa laukaista "meni"-merkkiä.** Mittari alkaa tyhjentyä
     *     samalla framella jolla siivet aukeavat, joten pelkkä `pFull`-reuna
     *     olisi huutanut menetystä juuri silloin kun etu otettiin käyttöön.
     *   - **Mittarin loppuminen ilmassa saa sen.** Se on se hetki jolla peli
     *     lakkaa kannattelemasta, eikä siitä ollut mitään merkkiä.
     */
    {
      const s = mk({ type: 'leaf', level: 3 });
      /* Tasainen koerata, sama temppu kuin hyppybudjetin mittauksessa: lento
       * kestää satakuusikymmentäkahdeksan framea ja kantaa pelaajan halki
       * puolen kentän, joten 1-1:n oma maasto olisi tässä satunnaismuuttuja
       * eikä mitattava asia. Mittarin käyttäytyminen ei ole kentän ominaisuus. */
      for (let y = 0; y < s.h - 2; y++) s.grid[y] = s.grid[y].map(() => ' ');
      for (let y = s.h - 2; y < s.h; y++) s.grid[y] = s.grid[y].map(() => '#');
      s.entities = s.entities.filter((e) => e.kind === 'player');
      s.goal = null;
      const i = mkInput();
      const tap = listen();
      let flewAt = -1;
      let endAt = -1;
      let endHeard = [];
      let endedInAir = false;
      let spentDuringFlight = 0;
      try {
        for (let f = 0; f < 40; f++) { i.held = blank(); i.pressed = blank(); s.update(i); }
        for (let f = 0; f < 300 && !s.player.pFull; f++) {
          i.held = blank(); i.held.right = true; i.held.run = true;
          i.pressed = blank();
          s.update(i);
        }
        for (let f = 0; f < 900 && endAt < 0; f++) {
          i.held = blank(); i.pressed = blank();
          /* Vauhti pidetään päällä kunnes siivet ovat auki. Mittari tyhjenee
           * maassa heti kun juoksunappi irtoaa, ja lentolupa *on* täysi
           * mittari — ilmassa mittari jäätyy, joten nousun ikkuna on juuri se
           * hyppy joka lähtee täydellä vauhdilla. */
          if (flewAt < 0) { i.held.right = true; i.held.run = true; }
          // Pohjahyppy ensin, sitten siiveniskut: lento alkaa vasta ilmassa.
          if (f === 0 || (flewAt >= 0 && (f - flewAt) % 8 === 0) || (flewAt < 0 && f === 6)) {
            i.pressed.jump = true; i.held.jump = true;
          }
          const wasFlying = s.player.flying;
          const n = tap.heard.length;
          s.update(i);
          const fresh = tap.heard.slice(n);
          if (flewAt < 0 && s.player.flying > 0) flewAt = f;
          if (flewAt >= 0 && wasFlying > 0 && s.player.flying === 0) {
            endAt = f;
            endHeard = fresh;
            endedInAir = !s.player.onGround;
          } else if (flewAt >= 0) {
            spentDuringFlight += fresh.filter((x) => x === spentSound).length;
          }
        }
      } finally { tap.off(); }
      /* Sama ääni kuin maassa mitattu, ei uusi: maassa hiipuva mittari ja
       * ilmassa loppuva lento ovat sama tilanvaihdos — etu meni — ja kaksi
       * merkkiä samalle asialle on juuri kohdan 8 virhe. */
      expect('lennon loppuminen ilmassa sanotaan, eikä nousu sano sitä',
        flewAt >= 0 && endAt > flewAt + 100 && endedInAir
        && !!spentSound && endHeard.includes(spentSound) && spentDuringFlight === 0,
        `nousu framella ${flewAt}, lento loppui framella ${endAt} `
        + `(ilmassa ${endedInAir}), ääni "${endHeard.join('+') || '-'}", `
        + `merkki lennon aikana ${spentDuringFlight} kertaa`);
    }

    /*
     * 4. PUTKESTA ULOS. Kuva on ollut olemassa koko ajan — keho nousee
     *    mahasta, kamera leikkaa ja neljä kaasupilveä jää jalkojen alle — ja
     *    ääni oli lainattu: `door`, sama jolla linnakkeen ovi aukeaa ja jolla
     *    siitä kävellään sisään. Yksi ääni kolmelle asialle on se merkki jonka
     *    pelaaja oppii lukemaan väärin.
     */
    {
      const s = mk({ type: 'shroom', level: 1 }, '1-2');
      put(s, 229, 28);
      const i = mkInput();
      const tap = listen();
      let inSound = null;
      let outSound = null;
      let puffs = 0;
      try {
        for (let f = 0; f < 200 && !outSound; f++) {
          i.held = blank(); i.held.down = f < 4; i.pressed = blank();
          const was = s.player.transit ? s.player.transit.phase : null;
          const n = tap.heard.length;
          s.update(i);
          const now = s.player.transit ? s.player.transit.phase : null;
          const fresh = tap.heard.slice(n);
          if (!inSound && !was && now) [inSound] = fresh;
          if (was === 'hold' && now === 'out') {
            [outSound] = fresh;
            puffs = s.entities.filter((e) => e.constructor.name === 'Puff').length;
          }
        }
      } finally { tap.off(); }
      expect('putkesta ulos on oma äänensä eikä oven laina',
        inSound === 'pipe' && !!outSound && outSound !== 'door'
        && outSound !== inSound && Sfx.has(outSound) && puffs >= 4,
        `sisään "${inSound || '-'}", ulos "${outSound || '-'}", `
        + `kaasupilviä ${puffs}`);
    }

    /*
     * 5. VARALOKERO. Täydellä voimatasolla poimittu tehostus ei muuta kehossa
     *    mitään — se menee lokeroon — ja silti soi `powerup`. Peli sanoi
     *    "kasvoit" hetkellä jolla mikään ei kasvanut, mikä on pahempi kuin
     *    hiljaisuus: valheellisen merkin oppii uskomaan.
     *
     *    Kuvaa ei lisätä eikä tarvitse: lokero on HUDissa juuri tätä varten ja
     *    esine ilmestyy siihen. Se mitataan tässä nimenomaan siksi, että
     *    todiste "kuva on jo olemassa" on se perustelu jolla toinen kuva
     *    jätetään lisäämättä.
     */
    {
      const tap = listen();
      let maxed = [];
      let grew = [];
      let stored = null;
      try {
        const s = mk({ type: 'shroom', level: 5 });
        s.player.collect('shroom');
        stored = game.state.reserve;
        maxed = tap.heard.slice();
        tap.heard.length = 0;
        const s2 = mk({ type: 'shroom', level: 1 });
        s2.player.collect('shroom');
        grew = tap.heard.slice();
      } finally { tap.off(); }

      const s3 = mk({ type: 'shroom', level: 5 });
      const box = () => {
        g.clearRect(0, 0, 320, 240);
        s3.draw(g);
        s3.drawOverlay(g);
        /* Lokero on oikeassa **alanurkassa** (`OVERLAY.box` = 294, y =
         * VIEW_H - 26): nauhaa ei enää ole, ks. `drawOverlay`. */
        return g.getImageData(294, 240 - 26, 20, 20).data;
      };
      game.state.reserve = null;
      const emptyBox = box();
      game.state.reserve = 'shroom';
      const fullBox = box();
      const boxPx = differing(emptyBox, fullBox);

      expect('varalokeron täyttyminen on oma tapahtumansa, ei tehostuksen ääni',
        stored === 'shroom' && maxed.length === 1 && grew.length === 1
        && grew[0] === 'powerup' && maxed[0] !== grew[0] && Sfx.has(maxed[0])
        && !TAKEN.includes(maxed[0]) && boxPx > 40,
        `lokeroon "${maxed.join('+') || '-'}", kasvuun "${grew.join('+') || '-'}", `
        + `lokeron kuva muuttui ${boxPx}/400 px`);
    }
  }

  /* ------------- luolakaistan musiikki: paikka, ei tapahtuma ------------- */
  /*
   * Punainen ennen vihreää (DESIGN.md kohta 7) sille päätökselle joka piti
   * tehdä ennen kuin yhtään säveltä kirjoitettiin: **löytyminen on tapahtuma,
   * musiikki on paikka.**
   *
   * Piilokaistalle saapumisella on jo merkkinsä — `noteSecret` kirjaa löydön
   * sillä framella jolla matka päätetään, putki soi, ja kartan salaisuuslaskuri
   * nousee. Jos musiikinvaihto osuisi samaan hetkeen, se olisi §8:n kieltämä
   * toinen samaa sanova merkki: kaksi "jotain tapahtui" -signaalia peräkkäin
   * opettaa lukemaan väärää asiaa. Siksi nämä tarkistukset eivät kysy *onko*
   * luolalla oma raita vaan **milloin** se tulee, **kuinka kauan** se pysyy ja
   * **mikä sen tuo takaisin** — eli juuri ne asiat joissa paikka ja tapahtuma
   * eroavat toisistaan.
   *
   * "Raita nimeltä cave on olemassa" ei todista mitään, joten sitä ei kysytä
   * kertaakaan yksinään.
   */
  {
    const { Music, audioTap } = await import('/src/core/audio.js');
    /*
     * `time` on nyt **polttoaine** eikä kello (18.8.2026: kolikot ovat aika).
     * Kutsupaikat lukevat sitä yhä nimellä "aika", ja se on oikein — se on
     * yhä se luku joka loppuu — mutta se asetetaan kolikkoina, koska kolikot
     * ovat se mistä kiire syntyy (`FUEL_HURRY`).
     */
    const mk = (id, power = { type: null, level: 0 }, time = 9999) => {
      reset(power);
      const s = new LevelScene(game, id);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      game.state.coins = Math.min(99, Math.max(1, Math.round(time / 6)));
      s.time = time;
      // setScene eikä sijoitus: `enter()` on se paikka jossa kohtaus valitsee
      // raitansa, ja puolet näistä tarkistuksista koskee juuri sitä.
      game.setScene(s);
      return s;
    };
    const put = (s, tx, ty) => {
      s.player.x = tx * 16 + (16 - s.player.w) / 2;
      s.player.y = ty * 16 - s.player.h;
      s.player.vy = 0;
      s.player.onGround = true;
      s.player.climbing = false;
      s.player.warpLock = 0;
      s.centerCamera();
    };
    const hold = (s, i, keys, frames) => {
      for (let f = 0; f < frames; f++) {
        i.held = blank();
        for (const k of keys) i.held[k] = true;
        i.pressed = blank();
        s.update(i);
      }
    };
    const i = mkInput();
    const bandOf = (s) => Math.floor((s.player.y + s.player.h - 1) / (16 * 16));
    const found = (id) => ((game.state.secrets || {})[id] || []).filter((k) => k === 'cave').length;

    /* 1. Raita vaihtuu kaistan mukaan ja vaihtuu takaisin. Molemmat suunnat
     * samassa tarkistuksessa siksi että pelkkä meno on helppo: paikka joka ei
     * lopu kun siitä lähtee ei ole paikka vaan tila johon jäätiin. */
    {
      const s = mk('1-2', { type: 'shroom', level: 1 });
      const own = Music.current;
      put(s, 229, 28);
      hold(s, i, ['down'], 120);
      hold(s, i, [], 60);
      const inCave = Music.current;
      const caveBand = bandOf(s);
      put(s, 250, 46);
      hold(s, i, [], 3);
      s.player.warpLock = 0;
      hold(s, i, ['up'], 120);
      hold(s, i, [], 90);
      expect('the cave band sounds like itself, and leaving gives the level back',
        own === 'level' && Music.has('cave') && inCave === 'cave'
        && caveBand === 2 && bandOf(s) === 1 && Music.current === 'level',
        `${own} -> ${inCave} (kaista ${caveBand}) -> ${Music.current} (kaista ${bandOf(s)})`);
    }

    /* 2. Taivaskaista pitää kentän oman musiikin. Päätös, ei unohdus: yksi
     * raita kahdelle vastakkaiselle paikalle sanoisi "salaisuus" eikä "luola",
     * ja silloin musiikki olisi taas löytymisen merkki. */
    {
      const s = mk('4-2', { type: 'shroom', level: 1 });
      const own = Music.current;
      put(s, 245, 30);
      hold(s, i, ['up'], 120);
      hold(s, i, [], 90);
      expect('the sky band keeps the level\'s own music',
        own === 'factory' && bandOf(s) === 0 && Music.current === 'factory',
        `${own} -> ${Music.current} (kaista ${bandOf(s)})`);
    }

    /* 3. Sama mitattuna framen tarkkuudella, ja kolme lukua eikä kahta.
     *
     * Saapumisella on kaksi hetkeä: löytö kirjataan sillä framella jolla matka
     * päätetään, ja matka päättyy sillä framella jolla ohjaus palaa. Musiikki
     * ei saa osua kumpaankaan. Pelkkä "putken jälkeen" ei riittäisi — vaihto
     * juuri sillä framella jolla pelaaja putkahtaa ulos olisi matkan viimeinen
     * isku, ja matka on tapahtuma. Siksi tässä mitataan myös se väli. */
    {
      const s = mk('1-2');
      put(s, 229, 28);
      let foundAt = -1;
      let controlAt = -1;
      let musicAt = -1;
      for (let f = 0; f < 240; f++) {
        i.held = blank();
        i.held.down = f < 4;
        i.pressed = blank();
        const traveling = !!s.player.transit;
        s.update(i);
        if (foundAt < 0 && found('1-2') > 0) foundAt = f;
        if (controlAt < 0 && traveling && !s.player.transit) controlAt = f;
        if (musicAt < 0 && Music.current === 'cave') musicAt = f;
      }
      expect('the music is not a second find-signal: the place arrives after the find',
        foundAt >= 0 && controlAt > foundAt && musicAt > controlAt + 20
        && bandOf(s) === 2,
        `löytö framella ${foundAt}, ohjaus takaisin framella ${controlAt}, `
        + `musiikki framella ${musicAt} (${musicAt - foundAt} framea löydöstä, `
        + `${musicAt - controlAt} ohjauksen palaamisesta)`);
    }

    /* 4. Ja toisinpäin: paikka kuulostaa toisella käynnillä samalta kuin
     * ensimmäisellä, vaikka löytö tapahtuu vain kerran. Löytymisen merkki
     * soisi kerran; paikan ääni soi joka kerta. */
    {
      const s = mk('1-2');
      put(s, 229, 28);
      hold(s, i, ['down'], 120);
      hold(s, i, [], 60);
      const first = Music.current;
      const firstFinds = found('1-2');
      put(s, 250, 46);
      hold(s, i, [], 3);
      s.player.warpLock = 0;
      hold(s, i, ['up'], 120);
      hold(s, i, [], 90);
      const between = Music.current;
      put(s, 229, 28);
      hold(s, i, ['down'], 120);
      hold(s, i, [], 60);
      expect('the music is a place: the second visit sounds like the first, the find does not',
        first === 'cave' && between === 'level' && Music.current === 'cave'
        && firstFinds === 1 && found('1-2') === 1,
        `1. käynti ${first}, välissä ${between}, 2. käynti ${Music.current}, `
        + `löytöjä ${found('1-2')}`);
    }

    /* 5. Pikatallennus luolassa. `enter()` ajetaan uudelleen latauksessa, joten
     * se ei saa lukea raitaa kenttädatasta vaan siitä missä jalat ovat. */
    {
      const s = mk('1-2');
      put(s, 229, 28);
      hold(s, i, ['down'], 120);
      hold(s, i, [], 60);
      const saved = Music.current;
      game.slot = 3;
      game.quickSave();
      Music.play('title');                     // jotain aivan muuta väliin
      const between = Music.current;
      game.quickLoad();
      const back = game.scene;
      expect('a quicksave taken in the cave loads back into the cave music',
        saved === 'cave' && between === 'title' && bandOf(back) === 2
        && Music.current === 'cave',
        `tallennus ${saved}, väliin ${between}, lataus ${Music.current} `
        + `(kaista ${bandOf(back)})`);
      game.slot = 1;
    }

    /* 6. Kuoppaan putoaminen käy luolakaistan puolella ennen laavaa. Se ei ole
     * käynti luolassa eikä siitä saa tulla ääntä. Tämän ei kaada odotusaika
     * vaan kuolemaportti — mitattuna sauman alla ollaan vain framen verran, ja
     * sillä framella kuolema on jo tapahtunut. Kaksi eri vartijaa, ja kumpikin
     * omalla testillään, ettei toinen pääse esittämään toista. */
    {
      const s = mk('1-2');
      s.player.x = 71 * 16;
      s.player.y = 26 * 16;
      let caveFrames = 0;
      let deepest = 0;
      let seam = 0;
      for (let f = 0; f < 200 && s.state === 'play'; f++) {
        i.held = blank();
        i.pressed = blank();
        s.update(i);
        deepest = Math.max(deepest, bandOf(s));
        if (bandOf(s) >= 2) seam++;
        if (Music.current === 'cave') caveFrames++;
      }
      expect('falling into a pit never sounds like the cave',
        caveFrames === 0 && deepest >= 2,
        `syvin kaista ${deepest}, sauman alla ${seam} framea, luolamusiikkia `
        + `${caveFrames} framea`);
    }

    /* 7. Kello ei nollaudu raidan mukana. `Music.play` aloittaa jokaisen raidan
     * rauhallisena, joten luolaan meno vähissä ajoissa veisi kiireen pois —
     * juuri sen signaalin joka on jo ansaittu. */
    {
      const s = mk('1-2', { type: null, level: 0 }, 90);
      put(s, 229, 28);
      hold(s, i, ['down'], 120);
      hold(s, i, [], 60);
      expect('entering the cave with the clock low keeps the hurry',
        Music.current === 'cave' && Music._hurry === true,
        `raita ${Music.current}, kiire ${Music._hurry}, kolikoita ${game.state.coins}`);
    }

    /* 8. Kiihtyvyys. Grieg valittiin rakenteensa takia — teos kiihtyy — joten
     * se on mitattava eikä uskottava. Askelen pituus samassa osiossa, ensin
     * heti alussa ja sitten kuuden kierroksen jälkeen, ja vertailuna raita
     * jonka ei kuulu kiihtyä lainkaan. */
    {
      const tap = audioTap();
      const stepMs = (name, pass) => {
        Music.play(name);
        // Raita jota ei ole ei tuota ääniä eikä siis askeleita: `play` asettaa
        // `current`in silti, joten tämä on ainoa kohta josta puuttuva raita
        // näkyy — ja se on syytä näkyä lukuna eikä poikkeuksena.
        if (!Music._voices) return NaN;
        Music._step = pass * Music._loopLen;
        Music._cycle = pass;
        Music._applyVariation();
        Music._nextTime = tap.ctx.currentTime + 0.005;
        const t0 = Music._nextTime;
        const s0 = Music._step;
        Music._tick();
        if (Music._timer) { clearTimeout(Music._timer); Music._timer = null; }
        return ((Music._nextTime - t0) / (Music._step - s0)) * 1000;
      };
      const caveEarly = tap ? stepMs('cave', 0) : 0;
      const caveLate = tap ? stepMs('cave', 6) : 0;
      Music.stop();
      const levelEarly = tap ? stepMs('level', 0) : 0;
      const levelLate = tap ? stepMs('level', 6) : 0;
      Music.stop();
      expect('the cave track accelerates the longer you stay, and only it does',
        !tap || (caveEarly > 0 && caveLate < caveEarly * 0.6
          && Math.abs(levelLate - levelEarly) < 0.5),
        tap ? `luola ${caveEarly.toFixed(1)} -> ${caveLate.toFixed(1)} ms `
          + `(${(caveEarly / caveLate).toFixed(2)}x), kenttä ${levelEarly.toFixed(1)} `
          + `-> ${levelLate.toFixed(1)} ms`
          : 'ei äänikontekstia — ohitettu');
    }

    /* 9. Ja kiihtyvyys nollautuu kun paikasta lähtee. Muuten toinen käynti
     * alkaisi siitä mihin ensimmäinen jäi, ja "älä jää tänne" muuttuisi
     * rangaistukseksi siitä että kävi kerran aiemmin. */
    {
      Music.play('cave');
      Music._step = 6 * Music._loopLen;
      const hot = Music.pace();
      Music.play('level');
      Music.play('cave');
      const cold = Music.pace();
      expect('leaving the cave winds the accelerando back to the start',
        hot >= 1.9 && cold < 1.05,
        `lähtiessä ${hot.toFixed(2)}x, palatessa ${cold.toFixed(2)}x `
        + `(askel ${Music._step})`);
      Music.stop();
      Music.current = null;
    }

    /*
     * 10. SUPERTÄHTI — pelin ainoa raita joka ei ole paikka.
     *
     * Kaikki yllä oleva mittaa sitä että raita seuraa jalkoja. Tämä mittaa
     * päinvastaista: raitaa joka ei välitä jaloista lainkaan, ja jonka koko
     * merkitys on siinä että se **loppuu**. Kolme väitettä, ja jokainen niistä
     * on sellainen jonka voi rikkoa vahingossa ilman että mikään muu näkyy:
     *
     *   a) tähti vaihtaa raidan sillä framella jolla se alkaa, ja **palauttaa
     *      sen huoneen raidan joka silloin kuuluu tähän paikkaan** — ei sitä
     *      jossa tähti alkoi. Mitataan luolassa, koska se on ainoa paikka jossa
     *      nuo kaksi voivat erota;
     *   b) tähti voittaa pomoraidan. Se on `trackFor`in ensimmäinen rivi ja
     *      samalla se rivi joka näyttää kyseenalaiselta, eli juuri se jonka joku
     *      joskus kääntää toisin päin;
     *   c) raita on datana se mitä siitä väitetään: pelin nopein. Tempo on luku
     *      taulussa, joten tämä on tarkistus eikä mielipide.
     */
    {
      const { STAR_FRAMES } = await import('/src/entities/player.js');
      const s = mk('1-1', { type: 'shroom', level: 1 });
      const own = Music.current;
      s.player.collect('star');
      s.update(i);
      const onStar = Music.current;
      // Loppuun asti, ja sitten muutama frame yli.
      s.player.star = 2;
      for (let f = 0; f < 6; f++) { i.pressed = blank(); s.update(i); }
      expect('supertähti soi omaa raitaansa ja antaa huoneen takaisin kun se loppuu',
        own === 'level' && Music.has('star') && onStar === 'star'
        && s.player.star === 0 && Music.current === 'level',
        `${own} -> ${onStar} -> ${Music.current} (tähteä jäljellä ${s.player.star},`
        + ` täysi mitta ${STAR_FRAMES} framea)`);

      const boss = mk('1-F', { type: 'shroom', level: 1 });
      const bossOwn = Music.current;
      boss.player.collect('star');
      boss.update(i);
      const bossStar = Music.current;
      boss.player.star = 1;
      for (let f = 0; f < 4; f++) { i.pressed = blank(); boss.update(i); }
      expect('tähti voittaa pomoraidan, ja pomo saa raitansa takaisin',
        bossOwn === 'boss' && bossStar === 'star' && Music.current === 'boss',
        `${bossOwn} -> ${bossStar} -> ${Music.current}`);

      const tempos = Music.names().map((n) => [n, Music.tempoOf(n)]);
      const fastest = tempos.reduce((a, b) => (b[1] > a[1] ? b : a));
      expect('tähtiraita on pelin nopein: kello on osa sen sisältöä',
        fastest[0] === 'star',
        tempos.sort((a, b) => b[1] - a[1]).map(([n, t]) => `${n} ${t}`).join(', '));
      Music.stop();
      Music.current = null;
    }
  }

  /* ------------------------------ valuva hiekka -------------------------- */
  /*
   * HIEKKA TOTTELEE PAINOVOIMAA, JA LOPPUTILA ON SE JOKA MITATAAN.
   *
   * IDEAS-synteesi E, tuomio 16.8.2026 "tee, ennen pomoa". Tämä on pelin
   * ensimmäinen laki jossa **kenttä jää toisenlaiseksi kuin se oli**: mureneva
   * lauta kasvaa takaisin, möykky palaa kotiruutuunsa, kytkin nollautuu — mutta
   * valunut hiekka jää sinne minne se valui. Siksi tämä lohko mittaa kaksi eri
   * asiaa, ja jälkimmäinen on se joka on oikeasti uusi:
   *
   *   1. **Hiekka valuu, sarake kerrallaan, ja pysähtyy pohjalle.** Yksi
   *      rikottu tiili tyhjentää täsmälleen oman sarakkeensa. Jos se
   *      tyhjentäisi koko lammikon, siilon pulma olisi olematon; jos se ei
   *      tyhjentäisi mitään, koko laki olisi olematon.
   *   2. **Lopputila on yhä kenttä.** `validateLevel` ja maabotti ajetaan
   *      *sille ruudukolle joka jäi jäljelle* eikä sille joka kirjoitettiin
   *      kenttädataan. Tämä on se portti jota IDEAS.md vaatii ehdolta
   *      "emergenssi saa koskea vain sitä mikä ei ole reitti", ja se on
   *      olemassa ennen ensimmäistä areenaa muokkaavaa pomoa nimenomaan siksi
   *      että se on halpa harjoitus samasta ongelmasta.
   */
  try {
    const { T } = await import('/src/gfx/tiles.js');
    const { validateLevel } = await import('/src/data/rules.js');
    const { JUMP_BUDGET } = await import('/src/data/pacing.js');
    const { runGround } = await import('/tools/level-bot.js');

    /** Koekenttä: neljän ruudun siilo neljän tiilen päällä, ja tasainen lattia. */
    const pourDef = () => {
      const W = 40;
      const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
      const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
      put(14, 0, '#'.repeat(W));
      put(15, 0, '#'.repeat(W));
      put(13, 1, '1');
      /* Tehostus ensimmäiseen neljännekseen, koska `validateLevel` vaatii sen
       * jokaiselta kentältä — myös koekentältä. Se kaatoi tämän kokeen kerran,
       * ja se on oikein: koekenttä jota säännöt eivät hyväksy ei ole se peli
       * jonka lopputilaa tässä mitataan. */
      put(10, 4, '!');
      put(7, 10, '~~~~');
      put(8, 10, 'BBBB');
      put(13, 38, 'F');
      return {
        id: 'sFix', theme: 'desert', bg: 'dunes', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows,
      };
    };
    const sandAt = (s, tx) => {
      const at = [];
      for (let ty = 0; ty < s.h; ty++) if (s.grid[ty][tx] === T.QUICKSAND) at.push(ty);
      return at;
    };
    const settle = (s, n = 240) => {
      const i = mkInput();
      for (let f = 0; f < n; f++) { i.pressed = blank(); s.update(i); }
    };

    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, 'sFix', pourDef());
    game.setScene(s);
    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    s.time = 9999;
    s.clockStopped = true;
    // Pelaaja pois siilon alta, jotta koe mittaa hiekkaa eikä uppoamista.
    s.player.x = 2 * 16;
    s.player.y = 14 * 16 - s.player.h;
    // Oikea reitti: iso pelaaja puskee tiilen, kuten pelissä.
    s.bumpTile(10, 8, s.player);
    settle(s);
    const drained = sandAt(s, 10);
    const kept = sandAt(s, 11);
    expect('rikottu tiili tyhjentää oman sarakkeensa hiekan, ja vain sen',
      drained.length === 1 && drained[0] === 13
      && kept.length === 1 && kept[0] === 7,
      `sarake 10: hiekka rivillä ${drained.join(',') || '–'} (odotus 13, lattia 14), `
      + `sarake 11: rivillä ${kept.join(',') || '–'} (odotus 7, koskematon)`);

    // Ja loput kolme perään: koko siilo alas.
    for (const tx of [11, 12, 13]) s.bumpTile(tx, 8, s.player);
    settle(s);
    const heap = [10, 11, 12, 13].map((tx) => sandAt(s, tx).join('') || '–').join(' ');
    const endRows = s.grid.map((row) => row.join(''));
    const problems = validateLevel(endRows, JUMP_BUDGET);
    expect('valuneen hiekan jälkeen kenttä läpäisee yhä omat sääntönsä',
      heap === '13 13 13 13' && problems.length === 0,
      `kasa sarakkeittain: ${heap}; säännöt: ${problems.slice(0, 2).join('; ') || 'ei huomautuksia'}`);

    /*
     * Ja botti lopputilalle. Uusi kohtaus samasta kentästä, jonka ruudukko
     * korvataan valuneella: botti aloittaa alusta ja juoksee sen läpi kenttänä
     * joka on jo muuttunut. Juuri tätä IDEAS.md tarkoittaa lopputilan
     * validoinnilla — lähtötila oli jo todistettu, ja se on eri kenttä.
     */
    reset({ type: null, level: 0 });
    let finished = null;
    game.finishLevel = (r) => { finished = r; };
    const after = new LevelScene(game, 'sFix', pourDef());
    game.setScene(after);
    after.grid = endRows.map((row) => row.split(''));
    after.entities = after.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
    after.time = 9999;
    after.clockStopped = true;
    const got = runGround(after, isSolid, 3000, () => finished);
    game.finishLevel = () => {};
    expect('valuneen hiekan läpi pääsee yhä maaliin voimatasolla 0',
      got.cleared, got.cleared ? `${after.w} saraketta läpi` : `eteni ${got.reach} %`);

    /*
     * Sama koe sillä kentällä joka tämän oikeasti sisältää. `dune_pour` on 2-4:n
     * palikka 16, ja se on pelin ainoa paikka jossa hiekka on rikottavan laatan
     * päällä — eli ainoa jossa tämä laki voi tapahtua pelaajalle.
     */
    reset({ type: 'shroom', level: 1 });
    const real = new LevelScene(game, '2-4');
    game.setScene(real);
    real.entities = real.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
    real.time = 9999;
    real.clockStopped = true;
    const silo = [];
    for (let ty = 0; ty < real.h; ty++) {
      for (let tx = 0; tx < real.w; tx++) {
        if (real.grid[ty][tx] === T.QUICKSAND && real.grid[ty + 1][tx] === T.BRICK) {
          silo.push([tx, ty + 1]);
        }
      }
    }
    for (const [tx, ty] of silo) real.bumpTile(tx, ty, real.player);
    settle(real, 400);
    const realRows = real.grid.map((row) => row.join(''));
    const realProblems = validateLevel(realRows, JUMP_BUDGET);
    reset({ type: null, level: 0 });
    let done = null;
    game.finishLevel = (r) => { done = r; };
    const realAfter = new LevelScene(game, '2-4');
    game.setScene(realAfter);
    realAfter.grid = realRows.map((row) => row.split(''));
    realAfter.entities = realAfter.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
    realAfter.time = 9999;
    realAfter.clockStopped = true;
    const realGot = runGround(realAfter, isSolid, 7000, () => done);
    game.finishLevel = () => {};
    expect('2-4:n hiekkasiilon voi kaataa, ja kenttä kelpaa yhä sen jälkeen',
      silo.length === 4 && realProblems.length === 0 && realGot.cleared,
      `siilossa ${silo.length} tiiltä (odotus 4), säännöt: `
      + `${realProblems.slice(0, 2).join('; ') || 'ei huomautuksia'}, `
      + `botti ${realGot.cleared ? 'läpi' : `jumissa ${realGot.reach} %`}`);
  } catch (e) {
    expect('valuvan hiekan testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ------------------------------- pieruhylly --------------------------- */
  /*
   * KUKALLA ON NYT RAKENNUSVERBI, ja tämä portti on se rajaus jonka se tarvitsee.
   *
   * IDEAS-synteesi A, tuomio 16.8.2026 "tee": seinään litistynyt laukaus jää
   * askelmaksi kahdeksi sekunniksi. Neljä väitettä, ja kolme niistä on kielto —
   * mikä on oikea suhde, koska ainoa tapa jolla tämä ominaisuus voi rikkoa
   * pelin on tekemällä *liikaa*:
   *
   *   1. **Seinäosuma jättää hyllyn, ja sen päällä seistään.** Hylly jonka
   *      päälle ei voi astua on kuvaefekti eikä verbi.
   *   2. **Lattiaosuma ei jätä mitään.** Pallo pomppii lattiaa pitkin koko
   *      matkansa, joten tämä on se toteutus joka täyttäisi kentän hyllyillä
   *      yhdestä laukauksesta.
   *   3. **Mitään ei kirjoiteta yli.** Tyhjä ruutu tai ei mitään.
   *   4. **Ja se katoaa.** Pysyvä hylly on maasto jonka pelaaja rakensi, ja
   *      silloin kenttä ei ole enää se kenttä jonka portit todistivat.
   */
  try {
    const { FartBall } = await import('/src/entities/items.js');
    const { T, isSemi } = await import('/src/gfx/tiles.js');

    /** Koekenttä: tasainen lattia ja yksi seinä sarakkeessa 30. */
    const shelfDef = (wall = true) => {
      const W = 60;
      const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
      const put = (y, x, str) => { rows[y] = rows[y].slice(0, x) + str + rows[y].slice(x + str.length); };
      put(14, 0, '#'.repeat(W));
      put(15, 0, '#'.repeat(W));
      put(13, 1, '1');
      if (wall) for (let y = 9; y <= 13; y++) put(y, 30, '#');
      put(13, 58, 'F');
      return {
        id: 'gFix', theme: 'grass', bg: 'hills', music: 'level', time: 9999,
        boss: false, bossVariant: 0, bands: null, rows,
      };
    };
    const shelvesIn = (s) => {
      const at = [];
      for (let ty = 0; ty < s.h; ty++) {
        for (let tx = 0; tx < s.w; tx++) if (s.grid[ty][tx] === T.SHELF) at.push({ tx, ty });
      }
      return at;
    };
    const shoot = (wall) => {
      reset({ type: 'flower', level: 2 });
      const s = new LevelScene(game, 'gFix', shelfDef(wall));
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      s.time = 9999;
      s.clockStopped = true;
      const p = s.player;
      p.x = 20 * 16;
      p.y = 14 * 16 - p.h;
      p.vx = 0; p.vy = 0; p.onGround = true;
      s.centerCamera();
      s.add(new FartBall(s, p.x + p.w, p.y + p.h * 0.45, 1));
      const i = mkInput();
      for (let f = 0; f < 120; f++) { i.pressed = blank(); s.update(i); }
      return s;
    };

    const hit = shoot(true);
    const made = shelvesIn(hit);
    const row = made.length ? made[0].ty : -1;
    const cols = made.map((m) => m.tx).sort((a, b) => a - b);
    expect('seinään osunut laukaus jättää kaasuhyllyn, seinän omalle puolelle',
      made.length >= 1 && made.length <= 3
      && made.every((m) => m.ty === row) && cols[cols.length - 1] === 29
      && cols[cols.length - 1] - cols[0] === made.length - 1
      && isSemi(T.SHELF),
      made.length
        ? `${made.length} ruutua rivillä ${row}, sarakkeet ${cols.join(',')} (seinä 30)`
        : 'ei yhtään hyllyä');

    // Sen päälle astuminen: ilmasta, putoavana, hyllyn keskimmäisen ruudun yllä.
    const stood = (() => {
      if (!made.length) return null;
      const p = hit.player;
      p.x = cols[0] * 16;
      p.y = row * 16 - p.h - 20;
      p.vx = 0; p.vy = 2; p.onGround = false;
      const i = mkInput();
      for (let f = 0; f < 40; f++) {
        i.pressed = blank();
        hit.update(i);
        if (p.onGround) return Math.round(p.y + p.h);
      }
      return null;
    })();
    expect('kaasuhyllyn päällä seistään',
      stood !== null && Math.abs(stood - row * 16) <= 1,
      stood === null ? 'ei kantanut' : `jalat ${stood}, hyllyn pinta ${row * 16}`);

    // Ja se haihtuu itsestään.
    const idle2 = mkInput();
    for (let f = 0; f < 140; f++) { idle2.pressed = blank(); hit.update(idle2); }
    expect('kaasuhylly haihtuu kahdessa sekunnissa eikä jää kentän maastoksi',
      shelvesIn(hit).length === 0 && hit.shelves.size === 0,
      `${shelvesIn(hit).length} ruutua jäljellä, kello ${hit.shelves.size}`);

    // Lattiaa pitkin pomppiva laukaus ei rakenna mitään.
    const floorOnly = shoot(false);
    expect('lattiaa pitkin pomppiva laukaus ei jätä hyllyjä perässään',
      shelvesIn(floorOnly).length === 0,
      `${shelvesIn(floorOnly).length} hyllyä ilman seinää — pallo pomppii lattiaa koko matkansa`);
  } catch (e) {
    expect('pieruhyllyn testit pääsevät ajoon asti', false, String(e && e.message));
  }

  /* ------------------------------ kuplaloukku -------------------------- */
  {
    const E = await import('/src/entities/enemies.js');
    const { FartBall } = await import('/src/entities/items.js');

    /** A scene with one enemy `dx` px to the player's right, on the same floor. */
    const setup = (dx = 60, Ctor = E.Walker) => {
      reset({ type: 'flower', level: 2 });
      const s = new LevelScene(game, '1-1');
      game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-1');
      game.setScene(s);
      s.entities = [];
      const p = s.player;
      const e = new Ctor(s, p.x + dx, p.y + p.h - 16);
      e.active = true;
      s.add(e);
      return { s, e, p };
    };
    const idle = mkInput();
    const run = (s, n) => { for (let f = 0; f < n; f++) s.update(idle); };

    {
      const { s, e, p } = setup(50);
      s.add(new FartBall(s, p.x + p.w, p.y + p.h * 0.45, 1));
      let f = 0;
      while (!e.bubbled && !e.dying && f < 90) { s.update(idle); f++; }
      expect('a fart ball bubbles an enemy instead of killing it',
        e.bubbled && !e.dying && !e.remove && game.state.score === 0,
        `bubbled ${e.bubbled}, dying ${e.dying}, pisteet ${game.state.score}`);
      expect('a bubbled enemy is harmless and a bigger target than the enemy in it',
        e.harmless === true && e.box.w > e.w && e.box.h > e.h,
        `${e.box.w}x${e.box.h} vs ${e.w}x${e.h}`);
    }

    /*
     * KUPLA KANTAA, JA SE ON ASKELMA EIKÄ HISSI.
     *
     * Kaksi väitettä samassa kokeessa, koska ne ovat saman säännön kaksi
     * puoliskoa eivätkä kaksi ominaisuutta:
     *
     *   **Se kantaa.** Kuplan päälle laskeutunut pelaaja ei putoa. Ilman tätä
     *   riviä "kupla kantaa" menisi läpi myös toteutuksella joka vain
     *   viivästää puhkeamista yhdellä framella.
     *
     *   **Eikä kanna kauan.** Kupla puhkeaa itsestään `BUBBLE_CARRY`n jälkeen
     *   vaikkei mihinkään koskettaisi. Yläraja mitataan siksi että juuri se
     *   erottaa askelman lautasta: kannettava kupla jolla voi odottaa on
     *   hissi, ja hissi on eri peli.
     *
     * Mitataan frameina eikä vakiota vastaan: koe ei saa tietää lukua jonka
     * se tarkistaa, tai se hyväksyy sen mitä koodissa sattuu lukemaan.
     */
    {
      const { s, e, p } = setup(40);
      e.trap();
      // Kuplan katolle ilmasta, putoavana. Sivulta tullut kosketus on eri
      // tapaus ja se on kokeessa alempana.
      const top = e.box.y;
      p.x = e.cx - p.w / 2;
      p.y = top - p.h - 6;
      p.vy = 3;
      p.onGround = false;
      let held = 0;
      let bounced = false;
      for (let f = 0; f < 90; f++) {
        s.update(idle);
        if (e.bubbled && !e.dying) { held++; continue; }
        bounced = p.vy < 0;
        break;
      }
      expect('kuplan päälle voi astua, ja se kantaa hetken ennen kuin puhkeaa',
        held >= 8 && held <= 40 && (e.dying || e.remove) && bounced,
        `kantoi ${held} framea, kupla ${e.dying || e.remove ? 'puhkesi' : 'jäi'}`
        + `, pomppu ${bounced} (vy ${p.vy.toFixed(2)})`);
    }

    /* Ja sivulta se on yhä se mitä se on aina ollut: koko kaato yhdestä
     * kosketuksesta. Tämä on regressio eikä uusi väite — astuminen ei saa
     * vievä pois sitä tapaa jolla kupla on tähän asti kaadettu. */
    {
      const { s, e, p } = setup(40);
      e.trap();
      p.x = e.box.x - p.w + 2;
      p.y = e.cy - p.h / 2;
      p.vy = 0;
      p.onGround = false;
      s.update(idle);
      expect('kuplaan kävelemällä se puhkeaa heti, kuten ennenkin',
        e.dying || e.remove,
        `kupla ${e.dying || e.remove ? 'puhkesi' : 'jäi'}, carried ${e.carried}`);
    }

    {
      const { s, e, p } = setup(50);
      e.trap();
      p.power = { type: null, level: 0 };
      p.applySize();
      const before = game.state.score;
      const walk = mkInput();
      walk.held.right = true;
      let f = 0;
      while (!e.dying && f < 200) {
        walk.pressed.jump = f % 24 === 0;
        walk.held.jump = f % 24 < 12;
        s.update(walk);
        f++;
      }
      expect('touching a bubble kills the enemy and never the player',
        e.dying && !p.dying && p.power.level === 0, `${f} framea`);
      expect('popping a bubble pays at least what the old instant kill did',
        game.state.score - before >= e.score, `${game.state.score - before} vs ${e.score}`);
    }

    {
      const { s, e } = setup(96);
      e.trap();
      run(s, E.BUBBLE_FRAMES - 100);
      const quiet = e.bursting;
      run(s, 60);
      expect('a bubble warns before it bursts', quiet === false && e.bursting === true,
        `100 jäljellä: ${quiet}, 40 jäljellä: ${e.bursting}`);
    }

    {
      const { s, e } = setup(96);
      const was = e.speed;
      e.trap();
      run(s, E.BUBBLE_FRAMES + 2);
      const x0 = e.x;
      run(s, 60);
      expect('an untouched bubble expires and lets an angry enemy out',
        !e.bubbled && !e.dying && !e.remove && e.angry && Math.abs(e.x - x0) > 6,
        `angry ${e.angry}, ${Math.round(x0)} -> ${Math.round(e.x)}`);
      expect('the escaped enemy is faster than it went in',
        Math.abs(e.speed - was * E.ANGRY_SPEED) < 1e-9, `${was} -> ${e.speed}`);
    }

    /* Nopeutuminen on sääntö jota pelaaja ei voi lukea mistään ellei naama
     * kerro sitä. `drawStinkCloud` osaa kaksi ilmettä ja piirsi vuosia vain
     * toista: molemmat kutsupaikat antoivat kirjaimellisen `true`:n, joten
     * rauhallinen pilvi näytti aivan yhtä vihaiselta kuin puolitoista kertaa
     * nopeampi karkulainen. Testi vertaa kahta muuten identtistä pilveä
     * pikseli pikseliltä, koska juuri se ero oli nolla.
     *
     * `tick = 0` ei ole makuasia: karkulainen myös vilkkuu (`get tint`), ja
     * vilkku on päällä joka toinen neljän framen jakso. Nollassa se on pois,
     * joten ainoa jäljelle jäävä ero on ilme. */
    {
      const faces = (angry) => {
        const cv = document.createElement('canvas');
        cv.width = 40; cv.height = 32;
        const g2 = cv.getContext('2d');
        const e2 = new E.StinkCloud(setup(96).s, 8, 8);
        e2.tick = 0;
        e2.facing = 1;
        e2.angry = angry;
        e2.x = 8; e2.y = 8;
        e2.draw(g2);
        return g2.getImageData(0, 0, 40, 32).data;
      };
      const calm = faces(false);
      const cross = faces(true);
      let diff = 0;
      for (let i = 0; i < calm.length; i += 4) {
        if (calm[i] !== cross[i] || calm[i + 1] !== cross[i + 1]
          || calm[i + 2] !== cross[i + 2] || calm[i + 3] !== cross[i + 3]) diff++;
      }
      expect('a stink cloud that escaped a bubble looks angrier than one that never was',
        diff > 0, `${diff} px eroa`);
    }

    /*
     * KUINKA SYVÄLLE PILVI YLTÄÄ, MITATTUNA EIKÄ LUETTUNA.
     *
     * `STINK_BOB_ROWS` (`src/data/rules.js`) on kopio kahdesta tämän luokan
     * luvusta — korkeudesta ja keinun amplitudista — ja kopio on turvallinen
     * vain niin kauan kuin joku vertaa sitä alkuperäiseen. Vertailu tehdään
     * ajamalla eikä lukemalla kenttiä: sääntöä kiinnostaa se alin ruutu johon
     * runko koskee, ja se on `update`in tulos eikä kahden vakion summa.
     *
     * Koko jakso ajetaan läpi, koska `phase` arvotaan. Yksi pilvi kertoo vain
     * oman vaiheensa; 300 framea on yli kaksi kierrosta (2π / 0,045 ≈ 140),
     * joten mitattu pohja on kaistan pohja riippumatta siitä mistä se lähti.
     *
     * Jos joku kasvattaa keinua tai pilveä, tämä kaatuu ja kertoo uuden luvun.
     * Se on tarkoitus: vaihtoehto on että sääntö jää kattamaan liian vähän ja
     * ensimmäinen liian matala pilvi löytyy tuotannosta.
     */
    {
      const { TILE } = await import('/src/gfx/tiles.js');
      const { RULE_CONSTANTS } = await import('/src/data/rules.js');
      const ty = 6;
      let deepest = ty;
      for (let trial = 0; trial < 8; trial++) {
        const s = setup(96).s;
        const e = new E.StinkCloud(s, 4 * TILE, ty * TILE);
        for (let f = 0; f < 300; f++) {
          e.update();
          deepest = Math.max(deepest, Math.floor((e.y + e.h - 1) / TILE));
        }
      }
      const measured = deepest - ty;
      expect('the validator knows how far below its marker a stink cloud reaches',
        measured === RULE_CONSTANTS.STINK_BOB_ROWS,
        `mitattu ${measured} riviä, säännöissä ${RULE_CONSTANTS.STINK_BOB_ROWS}`);
    }

    {
      const want = {
        Walker: true, ShellGuy: true, Flyer: true, StinkCloud: true, CorkGuy: true,
        Plant: false, AngrySun: false, Boss: false, Moon: false, Shockwave: false,
      };
      const bad = [];
      for (const [name, yes] of Object.entries(want)) {
        const s = setup(60).s;
        const e = new E[name](s, 64, 100, 0);
        e.active = true;
        s.add(e);
        e.hitByProjectile(1);
        if (!!e.bubbled !== yes) bad.push(`${name}: ${e.bubbled}`);
      }
      expect('only the wandering enemies can be bubbled', bad.length === 0, bad.join(' '));
    }

    {
      const { s, e } = setup(96);
      e.trap();
      run(s, 30);
      const snap = JSON.parse(JSON.stringify(captureState(game)));
      const before = `${e.constructor.name}|${e.bubbleTimer}|${Math.round(e.x)}|${Math.round(e.y)}`;
      s.entities = [];
      restoreState(game, snap);
      const r = game.scene;
      const back = r.entities.find((x) => x.bubbled);
      const after = back
        ? `${back.constructor.name}|${back.bubbleTimer}|${Math.round(back.x)}|${Math.round(back.y)}`
        : 'poissa';
      expect('a save state round-trips a bubbled enemy', before === after, `${before} vs ${after}`);
      for (let f = 0; f < E.BUBBLE_FRAMES; f++) r.update(idle);
      expect('a restored bubble still runs out and turns angry',
        !!back && !back.bubbled && back.angry, back ? `angry ${back.angry}` : 'poissa');
    }
  }

  /* ---------------------------- peli poikki ----------------------------- */
  /* It used to say "continue" and end the run regardless. Both options must
   * exist, the selection must be visible, and continuing must NOT bank the
   * score — the board is for finished runs. */
  {
    const { GameOverScene } = await import('/src/scenes/cards.js');
    const scores = await import('/src/core/scores.js');
    const i = mkInput();

    reset();
    scores.clearScores();
    game.state.score = 50000;
    game.setScene(new GameOverScene(game));
    for (let f = 0; f < 32; f++) game.scene.update(mkInput());
    const start = game.scene.choice;
    i.pressed.right = true;
    game.scene.update(i);
    const moved = game.scene.choice;
    i.pressed = blank();
    i.pressed.left = true;
    game.scene.update(i);
    const back = game.scene.choice;
    expect('the game over screen offers two choices and moves between them',
      start === 0 && moved === 1 && back === 0, `${start}/${moved}/${back}`);

    // Continue: back to the map, nothing banked.
    i.pressed = blank();
    i.pressed.jump = true;
    game.scene.update(i);
    expect('continuing resumes the run and banks nothing',
      isOverworld(game.scene.constructor.name) && scores.loadScores().length === 0,
      `${game.scene.constructor.name}, ${scores.loadScores().length} riviä`);

    // Start over: the run is finished, so the score goes to the board.
    reset();
    game.state.score = 50000;
    game.setScene(new GameOverScene(game));
    for (let f = 0; f < 32; f++) game.scene.update(mkInput());
    const j = mkInput();
    j.pressed.right = true;
    game.scene.update(j);
    j.pressed = blank();
    j.pressed.jump = true;
    game.scene.update(j);
    expect('starting over ends the run and offers the score to the board',
      ['NameEntryScene', 'HighScoreScene'].includes(game.scene.constructor.name),
      game.scene.constructor.name);
    scores.clearScores();

    /*
     * JATKO ON KOURALLINEN PUNAISIA KOLIKOITA, ei sana.
     *
     * Elämä on punainen kolikko (18.8.2026), ja jatko on täsmälleen "tässä on
     * lisää elämiä" — joten ruudun on annettava ne näkyvästi. Kaksi väitettä
     * yhdestä valinnasta, ja molemmat tarvitaan: kuolema tyhjentää pinon
     * (`Game.finishLevel`), joten pelkkä "elämiä on jäljellä" menisi läpi myös
     * silloin kun kukaan ei antanut mitään, ja piirretty kolikkomäärä ilman
     * tilatarkistusta olisi lupaus jota kukaan ei pidä.
     *
     * Luku luetaan `CONTINUE_LIVES`ista eikä kirjoiteta tähän uudestaan: koko
     * muutoksen pointti on, ettei aloituspinoa ja jatkon pinoa ole kahtena eri
     * lukuna kahdessa eri tiedostossa.
     */
    {
      const { Save, CONTINUE_LIVES, START_LIVES } = await import('/src/core/save.js');
      reset();
      game.state.lives = 0;          // kuten kuolema jättää pinon
      game.state.score = 50000;
      game.setScene(new GameOverScene(game));
      for (let f = 0; f < 32; f++) game.scene.update(mkInput());

      const canvas = document.createElement('canvas');
      canvas.width = 320;
      canvas.height = 240;
      const g = canvas.getContext('2d');
      game.scene.draw(g);
      /* JATKA-rivin kaista. Punainen tunnistetaan erotuksella eikä tarkalla
       * sävyllä, jotta kolikon kolme sävyä kelpaavat kaikki eikä ruudun
       * keltainen kehys (255,208,72) tai sininen tausta kelpaa yksikään. */
      const px = g.getImageData(0, 100, 320, 24).data;
      const cols = new Set();
      for (let y = 0; y < 24; y++) {
        for (let x = 0; x < 320; x++) {
          const o = ((y * 320) + x) * 4;
          const r = px[o];
          if (r > 120 && r - px[o + 1] > 60 && r - px[o + 2] > 60) cols.add(x);
        }
      }
      let coins = 0;
      for (const x of cols) if (!cols.has(x - 1)) coins++;
      expect('peli poikki tarjoaa jatkon elämät punaisina kolikkoina',
        coins === CONTINUE_LIVES && CONTINUE_LIVES > 0 && CONTINUE_LIVES <= START_LIVES,
        `${coins} kolikkoa rivillä, jatko antaa ${CONTINUE_LIVES}/${START_LIVES}`);

      const k = mkInput();
      k.pressed.jump = true;
      game.scene.update(k);
      expect('jatko antaa täsmälleen ne elämät jotka se näytti, ja ne säilyvät',
        game.state.lives === CONTINUE_LIVES && Save.load().lives === CONTINUE_LIVES,
        `elämät ${game.state.lives}, tallennuksessa ${Save.load().lives},`
        + ` luvattu ${CONTINUE_LIVES}`);
    }
  }

  /* ------------------------------ näppäimet ------------------------------ */
  /* No utility key may sit in the corner where the action keys live. `Backquote`
   * opened the developer overlay and on a Mac ISO board that is the key between
   * left Shift and Z — it was being hit mid-jump. `event.code` is a physical
   * position, but which one depends on ANSI vs ISO, and they disagree exactly
   * there. */
  {
    const src = await (await fetch('/src/core/input.js')).text();
    const map = src.slice(src.indexOf('const KEYMAP'), src.indexOf('const PADMAP'));
    const risky = ['Backquote', 'IntlBackslash', 'Backslash', 'IntlRo'];
    const found = risky.filter((k) => new RegExp(`^\\s*${k}:`, 'm').test(map));
    expect('no utility key sits next to the action keys',
      found.length === 0, found.length ? found.join(', ') : 'numerorivi vain');
  }

  /* ------------------------------- lentäjä ------------------------------- */
  /* Reported from play: stomp a flyer, it loses its wings, and the same jump
   * kills the walker underneath. `Flyer.stomp` appends the walker to the array
   * `collisions()` is iterating, so it is visited later in that same loop with
   * the same fall speed and stomped by a jump already spent. */
  {
    const { Flyer, Walker } = await import('/src/entities/enemies.js');
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const i = mkInput();
    for (let f = 0; f < 6; f++) s.update(i);
    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    const p = s.player;

    const groundY = p.y + p.h;
    const fly = new Flyer(s, p.cx - 8, groundY - 16);
    fly.active = true;
    fly.alwaysActive = true;
    fly.vx = 0;
    fly.vy = 0;
    s.add(fly);

    // Overlapping and arriving downwards, which is what a stomp is.
    p.y = fly.y - p.h + 4;
    p.vy = 4;
    p.onGround = false;
    s.collisions();

    const walker = s.entities.find((e) => e instanceof Walker);
    expect('stomping a flyer leaves a walker instead of killing it outright',
      !!walker && !walker.dying && !walker.remove && walker.squash === 0,
      walker ? `dying ${walker.dying} squash ${walker.squash}` : 'ei kävelijää');

    /* …and the grace has to actually end, or it would be immortal. The player
     * is parked out of the way first: left where he is, he lands on the walker
     * the moment it becomes vulnerable and squashes it, which measures the
     * stomp rather than the grace. */
    p.y = 32;
    p.x = s.spawn.x + 240;
    p.vy = 0;
    for (let f = 0; f < 20; f++) s.update(i);
    expect('the new walker becomes vulnerable again a moment later',
      !!walker && walker.spawnGrace === 0 && !walker.bubbled,
      walker ? `grace ${walker.spawnGrace}, squash ${walker.squash}, `
        + `remove ${walker.remove}` : 'ei kävelijää');
  }

  /* --------------------------------- kuu -------------------------------- */
  /* Bouncing off the moon drops a prize. It must fall *out* of the moon, not
   * bud out of its top the way a question block does — a moon hanging in the
   * night sky is not a brick, and the player is above it at that moment. */
  {
    const { Moon } = await import('/src/entities/enemies.js');
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '2-N');
    game.setScene(s);
    const m = s.entities.find((e) => e instanceof Moon) || s.add(new Moon(s, 100, 60));
    m.active = true;
    const before = s.entities.filter((e) => e.kind === 'item').length;
    m.stomp();
    const item = s.entities.filter((e) => e.kind === 'item').at(-1);
    expect('the moon drops a prize below itself, already falling',
      s.entities.filter((e) => e.kind === 'item').length === before + 1
      && !!item && item.emerging === 0 && item.y > m.y,
      item ? `emerge ${item.emerging}, kuu ${Math.round(m.y)} esine ${Math.round(item.y)}` : 'ei esinettä');

    // And only once — a trampoline that keeps paying is not a prize.
    m.stomp();
    expect('the moon pays exactly once',
      s.entities.filter((e) => e.kind === 'item').length === before + 1 && m.used);
  }

  /* ---------------------------- jatkolaskuri ----------------------------- */
  /* Continues are unlimited and cost no points — the third time this project
   * has answered "should the game stop them?" with "no, the board says so".
   * That only holds if the count is real: taken on every continue, carried to
   * the entry, absent from rows that predate it, and persisted. */
  {
    const scores = await import('/src/core/scores.js');
    const { GameOverScene } = await import('/src/scenes/cards.js');

    reset();
    scores.clearScores();
    game.state.score = 50000;
    game.state.continues = 0;
    for (let n = 1; n <= 2; n++) {
      game.setScene(new GameOverScene(game));
      for (let f = 0; f < 32; f++) game.scene.update(mkInput());
      const i = mkInput();
      i.pressed.jump = true;
      game.scene.update(i);
    }
    expect('continuing counts the continue, resumes the run and banks nothing',
      game.state.continues === 2
      && isOverworld(game.scene.constructor.name)
      && scores.loadScores().length === 0,
      `jatkot ${game.state.continues}, ${game.scene.constructor.name},`
      + ` ${scores.loadScores().length} riviä`);

    reset();
    scores.clearScores();
    game.state.score = 77000;
    game.state.continues = 4;
    game.pendingNode = { id: 'w2-3', level: '2-3' };
    game.finishRun();
    const offered = game.scene.constructor.name === 'NameEntryScene'
      && game.scene.result.continues === 4;
    if (game.scene.submit) game.scene.submit();
    const row = scores.loadScores()[0];
    expect('the continue count reaches the high score entry',
      offered && row && row.continues === 4 && row.score === 77000,
      `${game.scene.constructor.name}, ${JSON.stringify(row)}`);

    scores.clearScores();
    scores.addScore({ name: 'NEW', score: 3000, world: 1, continues: 7 });
    localStorage.setItem('sfb3.scores.v1', JSON.stringify([
      { name: 'RAW', score: 9000, world: 1, at: 1 },
      ...JSON.parse(localStorage.getItem('sfb3.scores.v1')),
    ]));
    const [raw, fresh] = scores.loadScores();
    expect('a row saved without a continue count still loads, as zero',
      raw.continues === 0 && fresh.continues === 7, `${raw.continues}/${fresh.continues}`);

    // It has to survive a reload, or the board would forget by morning.
    reset();
    game.state.continues = 5;
    game.persist();
    const { Save } = await import('/src/core/save.js');
    expect('the continue count is written to the save', Save.load().continues === 5,
      `${Save.load().continues}`);

    reset();
    game.state.continues = 6;
    game.newGame();
    expect('starting a new game resets the continue count',
      game.state.continues === 0, `${game.state.continues}`);
    scores.clearScores();
  }

  /* ----------------------------- pierupallo ------------------------------ */
  /* Reported from play: the player outruns their own shot. They did — the ball
   * moved at 3.2 px/frame and the P-meter top speed is 3.5. A projectile you
   * can beat in a footrace is not a weapon, so this is an invariant now. */
  {
    const { FartBall } = await import('/src/entities/items.js');
    const { MAX_RUN } = await import('/src/entities/player.js');
    reset({ type: 'flower', level: 2 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const ball = new FartBall(s, s.player.cx, s.player.cy, 1);
    // 3.5 is MAX_P, the P-meter cap, which is the fastest the player ever goes.
    expect('a fart ball outruns the fastest possible player',
      Math.abs(ball.vx) > 3.5 && Math.abs(ball.vx) > MAX_RUN,
      `pallo ${Math.abs(ball.vx)}, juoksu ${MAX_RUN}, P-katto 3.5`);
  }

  /* --------------------- pallo ei toimi ruudun ulkopuolella -------------- */
  /* Reported from play: the camera scrolls onto an enemy already sitting in a
   * bubble. At 5 px/frame with 200 frames of life the ball crossed three
   * screens, so it was trapping things the player never saw — the game playing
   * itself just out of sight. */
  {
    const { FartBall } = await import('/src/entities/items.js');
    reset({ type: 'flower', level: 2 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const ball = s.add(new FartBall(s, s.cam.x + 300, 100, 1));
    ball.active = true;
    let frames = 0;
    while (!ball.remove && frames < 200) { ball.update(); frames++; }
    expect('a fart ball is spent when it leaves the screen',
      ball.remove && frames < 30 && ball.x < s.cam.x + 400,
      `${frames} framea, x ${Math.round(ball.x)}, kamera ${Math.round(s.cam.x)}`);
  }

  /* ------------------------------- kuori -------------------------------- */
  /* Reported from play: stomp a shell walker, walk into the shell, lose a power
   * level. The kick landed — and then the shell, having moved 3.4 px out of a
   * box it overlapped by more, was still inside the player next frame, where a
   * sliding shell hurts. It hurt the one who had just kicked it. */
  {
    const { ShellGuy } = await import('/src/entities/enemies.js');
    reset({ type: 'shroom', level: 2 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const i = mkInput();
    for (let f = 0; f < 6; f++) s.update(i);
    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    const p = s.player;

    const e = new ShellGuy(s, p.x + p.w - 6, p.y + p.h - 24);
    e.active = true;
    e.alwaysActive = true;
    s.add(e);
    e.toShell();
    e.stompable = true;

    const before = p.powerLevel;
    let kicked = false;
    for (let f = 0; f < 30 && !p.dying; f++) {
      i.held = blank();
      i.held.right = true;
      i.pressed = blank();
      s.update(i);
      if (e.mode === 'sliding') kicked = true;
    }
    expect('kicking a shell you are standing in does not hurt you',
      kicked && p.powerLevel === before && !p.dying,
      `potkaistu ${kicked}, voima ${before}->${p.powerLevel}`);

    // But a shell that has been on its way for a while is still dangerous.
    e.kickGrace = 0;
    e.x = p.x + 2;
    p.invuln = 0;
    p.frozen = 0;
    const mid = p.powerLevel;
    s.collisions();
    expect('a shell already on its way still hurts', p.powerLevel < mid || p.dying,
      `voima ${mid}->${p.powerLevel}`);
  }

  /* --------------------------- piikit / spines -------------------------- */
  {
    const E = await import('/src/entities/enemies.js');
    /* Luettu kenttädatasta eikä kirjoitettu tähän. Käsin kirjoitettuna se
     * pysähtyi 7-F:ään, joten maailman 8 seitsemän pomokenttää olivat jokaisen
     * pomoportin ulkopuolella — ja juuri sinne jäi kaksi pomoa jotka kasvoivat
     * kannettoman areenan sisällä. Kuudes kerta tässä erässä sille että portin
     * oma kopio jostain luettavasta vanhenee. */
    const BOSS_LEVELS = levelIds().filter((id) => {
      try { return !!getLevelDef(id).boss; } catch { return false; }
    });

    const arena = (power) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 6; f++) s.update(i);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      return s;
    };
    const place = (s, Ctor) => {
      const groundY = s.player.y + s.player.h;
      const e = new Ctor(s, s.player.cx - 8, groundY - 16);
      e.active = true; e.alwaysActive = true; e.vx = 0;
      s.entities.push(e);
      return e;
    };
    const dropOn = (s, e) => {
      const p = s.player;
      p.x = e.cx - p.w / 2;
      p.y = e.y - p.h + 4;
      p.vy = 3; p.invuln = 0; p.frozen = 0;
      s.collisions();
    };

    expect("ENEMY_CHARS has the spiky enemy on 'x'",
      !!E.ENEMY_CHARS.x && E.ENEMY_CHARS.x(null, 0, 0) instanceof E.SpikeGuy);

    {
      const s = arena({ type: 'shroom', level: 1 });
      const e = place(s, E.SpikeGuy);
      dropOn(s, e);
      expect('stomping a spiky enemy hurts the player and leaves it standing',
        s.player.powerLevel === 0 && !e.remove && !e.dying, `power ${s.player.powerLevel}`);
    }
    {
      const s = arena({ type: 'leaf', level: 3 });
      const a = place(s, E.SpikeGuy);
      a.hitByProjectile(1);
      const bubbled = a.bubbled;
      a.popBubble(1);
      const b = place(arena({ type: 'leaf', level: 3 }), E.SpikeGuy);
      b.hitByTail(1);
      const c = place(arena({ type: 'leaf', level: 3 }), E.SpikeGuy);
      c.hitByShell(1);
      expect('a spiky enemy still dies to a fart ball, a tail whack and a shell',
        bubbled && a.dying && b.dying && c.dying);
    }
    {
      const s = arena({ type: 'shroom', level: 1 });
      const e = place(s, E.SpikeGuy);
      s.player.star = 300;
      dropOn(s, e);
      expect('the star beats the spines, as it beats every other inhabitant',
        e.dying && s.player.powerLevel === 1);
    }
    {
      const s = arena({ type: 'shroom', level: 1 });
      place(s, E.SpikeGuy);
      const snap = captureState(game);
      expect('a spiky enemy survives a save state — REGISTRY',
        !!snap && snap.level.entities.some((d) => d.t === 'SpikeGuy'));
    }

    {
      reset();
      const s = new LevelScene(game, '1-F');
      const trace = (b) => {
        const out = [];
        for (let f = 0; f < 1200; f++) { b.update(); out.push(b.spikePhase); }
        return out;
      };
      const a = trace(new E.Boss(s, 100, 100, 0));
      const b = trace(new E.Boss(s, 100, 100, 0));
      const seen = [];
      a.forEach((phase, f) => {
        if (!seen.length || seen[seen.length - 1].phase !== phase) seen.push({ phase, at: f });
      });
      const order = seen.slice(1).map((x) => x.phase);
      const cycle = ['open', 'telegraph', 'spiky'];
      const start = cycle.indexOf(order[0]);
      const ordered = order.every((phase, k) => phase === cycle[(start + k) % 3]);
      expect('the boss spine cycle is deterministic and always in the same order',
        ordered && a.join('') === b.join(''), order.slice(0, 4).join('>'));
    }

    {
      reset({ type: 'shroom', level: 1 });
      const s = new LevelScene(game, '1-F');
      game.setScene(s);
      const boss = s.entities.find((e) => e instanceof E.Boss);
      boss.spikePhase = 'spiky'; boss.spikeTimer = 100;
      const hp = boss.hp;
      dropOn(s, boss);
      const spikedHp = boss.hp;
      const spikedPower = s.player.powerLevel;
      boss.spikePhase = 'open'; boss.spikeTimer = 100; boss.invuln = 0;
      s.player.invuln = 0; s.player.frozen = 0;
      dropOn(s, boss);
      expect('stomping the spines hurts, stomping in the window damages',
        spikedHp === hp && spikedPower === 0 && boss.hp === hp - 1,
        `spiky hp ${hp}->${spikedHp}, open hp ${spikedHp}->${boss.hp}`);
    }

    {
      /*
       * VANHA PIKATALLENNUS, UUSI KOKOTAULUKKO.
       *
       * `entityToJSON` kopioi jokaisen oman kentän ja `entityFromJSON` herättää
       * olion ilman konstruktoria, joten tallennettu `w/h/baseW/baseH` palasi
       * sellaisenaan — ja kun `BOSS_SIZES` muuttui 30x32:sta seitsemään eri
       * kokoon, ennen päivitystä otettu tallennus herätti pomon **vanhalla
       * osumalaatikolla uuden piirroksen alla**. Tallennusversio on yhä `v: 1`,
       * joten mikään ei hylännyt sitä.
       *
       * Testi väärentää juuri sen: pakottaa tallennukseen vanhat mitat ja
       * vaatii että purku johtaa ne uudelleen taulukosta.
       */
      reset();
      const s0 = new LevelScene(game, '6-F');
      game.setScene(s0);
      const live = s0.entities.find((e) => e instanceof E.Boss);
      const want = { w: live.w, h: live.h };
      const snap = JSON.parse(JSON.stringify(captureState(game)));
      const saved = snap.level.entities.find((e) => e.t === 'Boss');
      /* Väärennös on uskottava vasta kun se on **johdonmukainen**: vanhassa
       * tallennuksessa oli vanha korkeus *ja* sitä vastaava `y`, eli jalat
       * samalla lattialla. Ensimmäinen yritys vaihtoi vain korkeuden ja jätti
       * uuden `y`:n, jolloin syntyi tila jota ei ole koskaan ollut olemassa —
       * ja testi kaatui siihen eikä korjaukseen. */
      const feet = saved.y + saved.h;
      saved.w = 30; saved.h = 32; saved.baseW = 30; saved.baseH = 32;
      saved.y = feet - 32;
      restoreState(game, snap);
      const back = game.scene.entities.find((e) => e.constructor.name === 'Boss');
      expect('vanhentunut pikatallennus ei tuo takaisin vanhaa osumalaatikkoa',
        !!back && back.w === want.w && back.h === want.h
        && back.y + back.h === live.y + live.h,
        back ? `${back.w}x${back.h}, odotettu ${want.w}x${want.h}` : 'ei pomoa');
    }

    {
      reset();
      const s = new LevelScene(game, '3-F');
      game.setScene(s);
      const boss = s.entities.find((e) => e instanceof E.Boss);
      boss.spikePhase = 'telegraph';
      boss.spikeTimer = 10;
      restoreState(game, JSON.parse(JSON.stringify(captureState(game))));
      const back = game.scene.entities.find((e) => e.constructor.name === 'Boss');
      expect('the boss keeps its place in the cycle across a save state',
        !!back && back.spikePhase === 'telegraph' && back.spikeTimer === 10,
        back ? `${back.spikePhase}/${back.spikeTimer}` : 'ei pomoa');
    }

    /*
     * LINNAKKEEN OVI: kuolema vie karttaan, ja karttaan palaaminen vie ovelle.
     *
     * Kolme väitettä, ja kolmas on se joka pitää sen rehellisenä:
     *   1. ovi avautuu kun areenalle astutaan, ei aiemmin,
     *   2. avattu ovi siirtää seuraavan yrityksen aloituspaikan sinne,
     *   3. **tavallinen kenttä ei saa ovea koskaan** — sääntö on linnakkeen
     *      toistolle eikä kentän pituudelle, ja jos se vuotaa muualle se on
     *      lakannut olemasta se sääntö.
     */
    {
      reset();
      const s0 = new LevelScene(game, '3-F');
      game.setScene(s0);
      const arena = s0.arenaCol;
      const idle = mkInput();
      for (let f = 0; f < 30; f++) s0.update(idle);
      const beforeWalk = !!game.state.doors['3-F'];

      // Walk in: put the body past the arena's first column and let it tick.
      s0.player.x = arena * 16 + 8;
      s0.update(idle);
      const afterWalk = !!game.state.doors['3-F'];

      // Re-enter: the next attempt starts at the door, not at the level start.
      const s1 = new LevelScene(game, '3-F');
      const spawnTile = Math.round(s1.spawn.x / 16);
      const freshStart = new LevelScene(game, '3-1').spawn.x;

      // An ordinary level has no arena and never records one.
      const plain = new LevelScene(game, '3-1');
      plain.player.x = plain.w * 16 - 32;
      plain.update(idle);
      const leaked = Object.keys(game.state.doors).filter((k) => !k.endsWith('-F'));

      expect('linnakkeen ovi avautuu areenalle astuttaessa ja siirtää aloituspaikan',
        !beforeWalk && afterWalk && spawnTile >= arena && spawnTile <= arena + 4
        && freshStart === 2 * 16 && leaked.length === 0,
        `ennen ${beforeWalk}, jälkeen ${afterWalk}, areena ${arena}, `
        + `aloitus ${spawnTile}, tavallinen ${freshStart / 16}, vuoto [${leaked}]`);
    }

    /**
     * Korkein kansi tai askelma pomon yläpuolella, pikseleinä. `null` jos
     * areenassa ei ole yhtään — ja se on nimenomaan se tapaus jonka alla oleva
     * portti kieltää korkealta pomolta.
     */
    const deckAbove = (scene, boss, below = 0) => {
      /* **Lankku, ei seinä.** Ensimmäinen versio hyväksyi minkä tahansa
       * kiinteän ruudun, ja areenan reunapilarit (`XX`) ovat kiinteitä — joten
       * portti löysi "kannen" jokaisesta areenasta ja hyväksyi myös sellaiset
       * joissa kantta ei ole. `isSemi` on se mitä kansi oikeasti on:
       * yksisuuntainen taso jolle pudotaan ylhäältä. */
      const col = Math.floor(boss.cx / 16);
      for (let row = Math.max(2, Math.ceil(below / 16)); row < 13; row++) {
        for (let c = Math.max(0, col - 16); c < Math.min(scene.w, col + 17); c++) {
          if (isSemi(scene.tileAt(c, row))) return { y: row * 16, col: c };
        }
      }
      return null;
    };

    /*
     * KORKEA POMO VAATII KANNEN, JA KANNELLE ON PÄÄSTÄVÄ.
     *
     * `FLOOR_REACH` (52 px) on se korkeus jonka yli voimataso 0 pääsee areenan
     * lattialta. Sen ylittävä pomo on tallottavissa vain ylhäältä, joten sen
     * areenassa **on oltava kansi** — ja kannen on oltava sekä pomon pään
     * yläpuolella että lattialta saavutettavissa.
     *
     * Ilman tätä sääntöä korkeuden nostaminen olisi yhden luvun muutos joka
     * tekee pomosta voittamattoman ilman että mikään sanoo mitään, ja se on
     * tasan se vika jonka `boss_arena_big` aikoinaan sai: kannet olivat
     * olemassa mutta niille ei päässyt, joten ne olivat lavasteita.
     */
    {
      const bad = [];
      for (const id of BOSS_LEVELS) {
        reset();
        const s2 = new LevelScene(game, id);
        game.setScene(s2);
        const boss = s2.entities.find((e) => e instanceof E.Boss);
        const idle = mkInput();
        for (let f = 0; f < 90 && !(boss.onGround && f > 2); f++) s2.update(idle);
        if (boss.h <= FLOOR_REACH) continue;
        const deck = deckAbove(s2, boss);
        if (!deck) { bad.push(`${id}: ${boss.h} px korkea eikä kantta`); continue; }
        if (deck.y > boss.y) bad.push(`${id}: kansi ${deck.y} on pään (${Math.round(boss.y)}) alapuolella`);
        /*
         * Saavutettavuus on **askelma**, ei summa.
         *
         * Ensimmäinen versio hyväksyi minkä tahansa kannen jonka kokonaisnousu
         * oli alle 128 px, eli myös 112 px korkean kannen jonka alla ei ole
         * mitään — ja 112 px on enemmän kuin 100 px juoksuhyppy. Se on tasan se
         * "kannet olivat lavasteita" -areena jonka tämä portti sanoo estävänsä.
         */
        const rise = 208 - deck.y;
        if (rise > 64) {
          const step = deckAbove(s2, boss, deck.y + 8);
          if (!step) bad.push(`${id}: kansi ${rise} px lattiasta ilman askelmaa alla`);
          else if (208 - step.y > 64) bad.push(`${id}: askelma ${208 - step.y} px lattiasta, yli hypyn`);
          else if (step.y - deck.y > 64) bad.push(`${id}: askelmalta kannelle ${step.y - deck.y} px`);
        }
      }
      expect('jokainen lattiaa korkeampi pomo tappelee areenassa jossa on kansi',
        bad.length === 0,
        bad.length ? bad.join(' | ') : `raja ${FLOOR_REACH} px, korkeat tarkistettu`);
    }

    /*
     * RAAJAT: LÄSNÄOLOA ILMAN ETTÄ TALLOTTAVA LAATIKKO KASVAA.
     *
     * Kolme väitettä, ja kaksi niistä on sellaisia jotka hiljaa pettäisivät:
     *   1. raaja **satuttaa** — piirretty raaja jonka läpi kävelee on sama
     *      valhe kuin piikki joka ei satuta,
     *   2. raaja **ei tule laskeutumiskaistalle** eli pään yläpuoliseen
     *      sarakkeeseen, joka on kruunun ja jolla saa olla yksi vastaus,
     *   3. raajat **kasvattavat läsnäoloa** — raaja joka ei muuta siluettia on
     *      koriste jolla on kello, mikä on huonompi kuin ei raajaa.
     */
    {
      /** Ks. alempaa: raajaton pomo on päätös, ja päätöksen nimi on tässä. */
      const LIMBLESS_ON_PURPOSE = [7];
      const kGetDef = (await import('/src/data/levels.js')).getLevel;
      const bad = [];
      const grew = [];
      for (const id of BOSS_LEVELS) {
        reset();
        const s3 = new LevelScene(game, id);
        game.setScene(s3);
        const boss = s3.entities.find((e) => e instanceof E.Boss);
        const idle = mkInput();
        for (let f = 0; f < 90 && !(boss.onGround && f > 2); f++) s3.update(idle);
        const boxes = boss.limbBoxes();
        /*
         * Raajaton pomo on **päätös jonka nimi on tässä**, ei unohdus.
         *
         * Suolimadolla (7) ei ole mitään mikä ei olisi runkoa: raaja on tässä
         * pelissä se osa joka ulottuu rungon ulkopuolelle ja jonka voi
         * katkaista, ja madolla sellaista ei ole. Poikkeuslista on yksi rivi ja
         * se vanhenee itsestään — jos madolle joskus piirretään raajat, alempi
         * `stale`-rivi kaatuu ja tämä poikkeus on poistettava.
         */
        if (!boxes.length) {
          if (!LIMBLESS_ON_PURPOSE.includes(kGetDef(id).bossVariant)) {
            bad.push(`${id}: ei raajoja lainkaan`);
          }
          continue;
        }

        // 2. landing strip: nothing may sit above the head inside its columns.
        for (const b of boxes) {
          const overX = b.x < boss.x + boss.w && b.x + b.w > boss.x;
          if (overX && b.y < boss.y + 4) {
            bad.push(`${id}: raaja laskeutumiskaistalla (y ${Math.round(b.y)} vs pää ${Math.round(boss.y)})`);
          }
        }

        // 3. presence: the union of body+limbs against the body alone.
        const bodyArea = boss.w * boss.h;
        const minX = Math.min(boss.x, ...boxes.map((b) => b.x));
        const maxX = Math.max(boss.x + boss.w, ...boxes.map((b) => b.x + b.w));
        const minY = Math.min(boss.y, ...boxes.map((b) => b.y));
        const maxY = Math.max(boss.y + boss.h, ...boxes.map((b) => b.y + b.h));
        const reach = (maxX - minX) * (maxY - minY);
        grew.push(`${id} ${(reach / bodyArea).toFixed(2)}x`);
        if (reach / bodyArea < 1.2) bad.push(`${id}: raajat kasvattavat vain ${(reach / bodyArea).toFixed(2)}x`);

        /* 1. raaja satuttaa — ja tämä on mitattava **kruunu päällä**, koska
         * kruunu pois päältä sama kosketus katkaisee raajan eikä satuta. Testi
         * oli oikea siihen asti kun katkaisu tuli, ja se on juuri se hetki
         * jolloin vanha testi alkaa mitata väärää asiaa. */
        boss.spikePhase = 'spiky';
        boss.spikeTimer = 999;
        const p = s3.player;
        const far = boxes.reduce((a, b) => (Math.abs(b.x - boss.cx) > Math.abs(a.x - boss.cx) ? b : a));
        p.x = far.x + far.w / 2 - p.w / 2;
        p.y = far.y + far.h / 2 - p.h / 2;
        p.vx = 0; p.vy = 0; p.invuln = 0; p.star = 0; p.dying = false;
        const power0 = s3.player.powerLevel;
        s3.update(idle);
        const hurt = p.dying || p.invuln > 0 || s3.player.powerLevel < power0;
        if (!hurt) bad.push(`${id}: raajan sisällä seisominen ei satuttanut`);
      }
      /*
       * JA JOKAISESSA OSUMALAATIKOSSA ON OLTAVA PIKSELEITÄ.
       *
       * Yllä oleva mittasi laatikoita, ja se päästi läpi tasan sen vian jonka
       * kuvalevy paljasti: nyrkkeilijä piirretään omalla funktiollaan eikä
       * `drawStandardBoss`in kautta, joten hänellä oli raajan **osumalaatikko
       * ilman raajaa**. Vahinko tyhjästä on sama valhe kuin raaja jonka läpi
       * kävelee, vain toisin päin.
       *
       * Laatikko ja piirros ovat kaksi eri asiaa, joten ne on mitattava
       * kahdesti — juuri se on tämän erän toistuva läksy.
       */
      const gfx = await import('/src/gfx/sprites.js');
      const drawn = gfx.BOSS_LIMBS.map((limbs, v) => {
        // Sama nimetty poikkeus kuin laatikkopuolella, ks. `LIMBLESS_ON_PURPOSE`.
        if (!limbs.length) return LIMBLESS_ON_PURPOSE.includes(v) ? null : `${v}: ei raajoja`;
        const M = 96;
        const size = gfx.bossSize(v);
        const c = document.createElement('canvas');
        c.width = size.w + M * 2;
        c.height = size.h + M * 2;
        const g = c.getContext('2d');
        gfx.drawBoss(g, M, M, 12, 1, false, v, 1, 0);
        const d = g.getImageData(0, 0, c.width, c.height).data;
        const empty = limbs.filter(([lx, ly, lw, lh]) => {
          let n = 0;
          for (let y = ly + M; y < ly + lh + M; y++) {
            for (let x = lx + M; x < lx + lw + M; x++) {
              if (x < 0 || y < 0 || x >= c.width || y >= c.height) continue;
              if (d[(y * c.width + x) * 4 + 3] > 8) n++;
            }
          }
          return n < lw * lh * 0.25;
        });
        return empty.length ? `${v}: ${empty.length} raajaa ilman pikseleitä` : null;
      }).filter(Boolean);
      drawn.forEach((d) => bad.push(d));
      /* Ja poikkeus joka ei ole enää poikkeus on virhe: jos raajattomaksi
       * merkitylle varianttille piirretään raajat, tämä rivi kaatuu ja lista
       * on siivottava. Sama sääntö kuin äänten `SILENT_ON_PURPOSE`illa. */
      const staleLimbless = LIMBLESS_ON_PURPOSE.filter((v) => (gfx.BOSS_LIMBS[v] || []).length > 0);
      if (staleLimbless.length) {
        bad.push(`vanhentunut poikkeus: variantilla ${staleLimbless.join(', ')} on raajat`);
      }

      expect('raajat kasvattavat läsnäoloa, satuttavat, näkyvät, eivätkä tule laskeutumiskaistalle',
        bad.length === 0, bad.length ? bad.join(' | ') : grew.join(', '));
    }

    /*
     * RAAJAN KATKAISU ON VALINTA, EI TIE.
     *
     * Kruunu vastaa koko koosteesta: päällä ollessaan mihinkään ei saa
     * koskea, pois ollessaan kaikki on tallottavissa. Yksi merkki, yksi
     * vastaus — ja siksi raajalla ei ole omaa varoitustaan. Kruunusääntö
     * ostettiin playtestillä jossa pelaajat eivät ehtineet erottaa kahta
     * piikkiriviä, eikä sitä makseta uudelleen.
     *
     * Kolme väitettä:
     *   1. avoimessa ikkunassa **päältä** tullessa raaja katkeaa,
     *   2. piikkivaiheessa sama kosketus satuttaa eikä katkaise,
     *   3. katkennut raaja **katoaa myös piirroksesta** — muuten jäisi kuva
     *      josta kävelee läpi, eli sama valhe kolmatta kertaa.
     *
     * Ettei se ole tie: talloportti käy kaikki pomot läpi pelkkää runkoa
     * tallomalla, eli lupaus voimatasosta 0 ei nojaa raajoihin lainkaan.
     */
    {
      /*
       * Kumpikin vaihe omassa kohtauksessaan, ja se on korjaus eikä varovaisuus.
       *
       * Ensimmäinen versio ajoi molemmat samassa: piikkivaiheen kosketus tappaa
       * voimatason 0 pelaajan, kohtaus siirtyy tilaan `dead`, eikä `collisions`
       * enää aja lainkaan — joten avoimen ikkunan koe ei mitannut katkaisua
       * vaan kuollutta kohtausta. Tulos oli uskottava epäonnistuminen.
       */
      const dropOnLimb = (phase) => {
        reset();
        const sc = new LevelScene(game, '8-F');
        game.setScene(sc);
        const boss = sc.entities.find((e) => e instanceof E.Boss);
        const idle = mkInput();
        for (let f = 0; f < 90 && !(boss.onGround && f > 2); f++) sc.update(idle);
        boss.spikePhase = phase;
        boss.spikeTimer = 999;
        boss.invuln = 0;
        /* Suunta lukitaan: `limbBoxes` peilaa `facing`in mukaan, ja jos pomo
         * kääntyy kokeen aikana, raajat vaihtavat puolta pelaajan alla. */
        boss.facing = 1;
        boss.vx = 0;
        const boxes = boss.limbBoxes();
        const i2 = boxes.findIndex((b) => b.w > 0);
        const b = boxes[i2];
        const p = sc.player;
        p.x = b.x + b.w / 2 - p.w / 2;
        p.y = b.y - p.h - 2;
        p.vx = 0; p.vy = 3; p.invuln = 0; p.star = 0; p.dying = false;
        const power0 = sc.player.powerLevel;
        for (let f = 0; f < 10 && !boss.brokenLimbs
          && !(p.dying || p.invuln > 0); f++) {
          boss.facing = 1;
          sc.update(idle);
        }
        return {
          broke: boss.brokenLimbs !== 0,
          hurt: p.dying || p.invuln > 0 || sc.player.powerLevel < power0,
          i: i2,
        };
      };

      const spiky = dropOnLimb('spiky');
      const open = dropOnLimb('open');

      const gfx2 = await import('/src/gfx/sprites.js');
      const pixelsIn = (mask, idx) => {
        const M = 96;
        const size = gfx2.bossSize(6);
        const c = document.createElement('canvas');
        c.width = size.w + M * 2; c.height = size.h + M * 2;
        const g = c.getContext('2d');
        gfx2.drawBoss(g, M, M, 12, 1, false, 6, 1, 0, mask);
        const [lx, ly, lw, lh] = gfx2.BOSS_LIMBS[6][idx];
        const d = g.getImageData(0, 0, c.width, c.height).data;
        let n = 0;
        for (let y = ly + M; y < ly + lh + M; y++) {
          for (let x = lx + M; x < lx + lw + M; x++) {
            if (d[(y * c.width + x) * 4 + 3] > 8) n++;
          }
        }
        return n;
      };
      const before = open.i >= 0 ? pixelsIn(0, open.i) : 0;
      const after = open.i >= 0 ? pixelsIn(1 << open.i, open.i) : 1;

      expect('avoimessa ikkunassa raaja katkeaa, piikeissä se satuttaa, ja katkennut katoaa myös kuvasta',
        open.broke && !spiky.broke && spiky.hurt && before > 0 && after === 0,
        `avoin katkesi ${open.broke}, piikeissä katkesi ${spiky.broke} satutti ${spiky.hurt}, `
        + `pikselit ${before} -> ${after}`);
    }

    /*
     * OSIOITU KENTTÄ: KAMERA VAIHTAA KIELTÄ, JA KÄÄNNE ON SIVUNVAIHDON LYÖNTI.
     *
     * Kaksi kameratilaa puhuvat tarkoituksella vastakkaista kieltä: vaaka
     * seuraa pehmeästi ja liikkuu koko ajan, pysty seisoo paikallaan ja
     * leikkaa. Yhdistäminen tuottaisi kameran joka liukuu sivulle ja nykii
     * ylös, mikä lukee rikkinäisenä. Osio kerrallaan kumpikin kieli säilyy
     * omanaan, ja **käänne saa sen beatin joka pystykentillä jo on**.
     *
     * Kolme väitettä:
     *   1. raja ylitettäessä `vertical` vaihtuu,
     *   2. vaihto laukaisee sivunvaihdon (`camPage` > 0), eli kello ja
     *      viholliset seisovat sen ajan — sama ele kuin sivunvaihdossa,
     *   3. osioitu kenttä **ei ole kaistoitettu**: kaistat ovat kolme erillistä
     *      huonetta joiden välillä kamera ei saa nähdä, ja se pysäyttäisi
     *      nousun ensimmäiseen saumaan.
     */
    {
      const levels = await import('/src/data/levels.js');
      levels.registerLevel({
        id: 'TEST-SEG',
        theme: 'grass',
        bg: 'none',
        time: 400,
        segments: [{ toCol: 20, vertical: false }, { toCol: 999, vertical: true }],
        rows: Array.from({ length: 48 }, (_, y) => (y === 14 || y === 30 || y === 46
          ? '#'.repeat(40) : ' '.repeat(40))),
      });
      reset();
      const sg = new LevelScene(game, 'TEST-SEG');
      game.setScene(sg);
      const idle = mkInput();
      const startVertical = sg.vertical;
      const banded = !!sg.bands;
      sg.camPageFrames = 60;
      sg.player.x = 30 * 16;
      sg.player.y = 29 * 16 - sg.player.h;
      sg.update(idle);
      const turned = sg.vertical;
      const paged = sg.camPage > 0;
      expect('osioitu kenttä vaihtaa kameran kielen rajalla, ja käänne on sivunvaihto',
        startVertical === false && turned === true && paged && !banded,
        `alku pysty=${startVertical}, rajan jälkeen pysty=${turned}, `
        + `sivunvaihto=${sg.camPage}, kaistat=${banded}`);
    }

    /* The promise the lead designer set himself: a powerless player can beat
     * every boss. Taken apart into the two things it needs — one window is long
     * enough to walk up and land a stomp at its tightest, and the clock holds
     * far more windows than the boss has health. */
    for (const id of BOSS_LEVELS) {
      reset();
      const s = new LevelScene(game, id);
      game.setScene(s);
      const boss = s.entities.find((e) => e instanceof E.Boss);
      const idle = mkInput();
      /*
       * Settle the boss, do not let him go for a walk.
       *
       * This was a flat 90 frames, which is about seventy more than the job
       * needs: a boss spawns a little above the floor and is standing on it
       * inside fifteen. The other seventy-five were him pacing, and at ~1.5 px
       * a frame that carried him a hundred and thirty pixels off his mark —
       * far enough that the player, who is placed *relative to him*, was being
       * set down outside the arena entirely. In 7-F that landed a power-0
       * player on the spike bed of the corridor before it, and the fortress
       * failed a test about stomping because of where the test stood him.
       *
       * `boss.onGround` is the actual precondition, so it is the actual loop.
       */
      for (let f = 0; f < 90 && !(boss.onGround && f > 2); f++) s.update(idle);

      boss.hp = 1;
      boss.spikePhase = 'open';
      const openWindow = boss.openFrames;
      boss.spikeTimer = openWindow;

      /*
       * Where a power-0 player has to leave the ground, and why it is measured
       * off **both** of the boss's dimensions.
       *
       * The old number was a bare 40 px from his centre. That was written when
       * every boss was 30x32, where it quietly meant "take off 25 px clear of
       * his flank, with a whole boss-height of air to climb". Per-boss sizes
       * broke both halves of that at once: 40 px from the centre of a 68-wide
       * storm is 6 px from his side, and a body twenty pixels taller needs the
       * extra time in the air to get over it.
       *
       * Measured, that second half is the one that actually failed. A stomp
       * only counts while descending, so arriving over a 52 px boss on the way
       * *up* is not a stomp, it is walking into him — which is exactly what the
       * trace showed at 8-F, contact at his flank with `vy` still negative.
       * At power 0 the rise and the run are within a factor of two of each
       * other in px/frame, so one boss-height of extra run-up is the honest
       * term, and adding it turns all seven fortresses green without touching
       * the power level, the window, or the boss.
       */
      const clearance = boss.w / 2 + 25 + boss.h;

      const p = s.player;
      /*
       * Matalalle pomolle lupaus on lattialta, korkealle kannelta.
       *
       * `FLOOR_REACH` on se raja, ja se on sama luku joka rajaa `BOSS_SIZES`ia
       * — luettuna sieltä eikä kirjoitettuna tänne, koska tässä tiedostossa on
       * tässä erässä neljä esimerkkiä siitä mitä oma kopio maksaa.
       *
       * Kannelta lähtevä ei ole löysempi testi vaan **toinen reitti samaan
       * lupaukseen**: pelaaja on yhä voimatasolla 0, ikkuna on yhä tiukin
       * mahdollinen, ja alla oleva erillinen portti vaatii että kannelle
       * ylipäänsä pääsee lattialta samalla voimatasolla.
       */
      const tall = boss.h > FLOOR_REACH;
      if (tall) {
        /* Kannen **päälle**, sen omaan sarakkeeseen. Ensimmäinen versio asetti
         * pelaajan pomon viereen kannen korkeudelle, eli ilmaan jossa kantta ei
         * ole — sama vika kuin kiipeilyaskelmakokeessa, ja kolmas kerta tässä
         * erässä. */
        const deck = deckAbove(s, boss);
        /* Ilman kantta tämä kaatoi koko `page.evaluate`n, eli yksi puuttuva
         * kansi vei mukanaan jokaisen muun tuloksen. Portin pitää raportoida
         * eikä räjähtää: kannen puuttumisen sanoo yllä oleva oma testinsä. */
        if (!deck) { expect(`${id}: korkealla pomolla on kansi jolta tulla`, false, 'ei kantta'); continue; }
        p.x = deck.col * 16 + 2;
        p.y = deck.y - p.h;
      } else {
        p.y = boss.y + boss.h - p.h;
        p.x = boss.cx - (clearance + 50);
      }
      p.vx = 0; p.vy = 0;
      s.centerCamera();

      const i = mkInput();
      let hitAt = -1;
      for (let f = 0; f < openWindow && hitAt < 0; f++) {
        boss.jumpTimer = 999; boss.chargeTimer = 999; boss.charging = 0;
        const dx = boss.cx - p.cx;
        const adx = Math.abs(dx);
        i.held = blank();
        i.pressed = blank();
        if (!p.onGround) {
          const want = Math.sign(dx) * Math.min(2.2, adx / 8);
          if (p.vx < want - 0.15) i.held.right = true;
          else if (p.vx > want + 0.15) i.held.left = true;
          if (p.vy < 0) i.held.jump = true;
        } else if (adx > clearance + Math.abs(boss.vx) * 12) {
          i.held[dx > 0 ? 'right' : 'left'] = true;
          i.held.run = true;
        } else {
          i.pressed.jump = true;
          i.held.jump = true;
        }
        s.update(i);
        if (boss.hp < 1 || s.bossDefeated) hitAt = f;
      }
      expect(`${id}: a power-0 stomp fits inside the tightest window`,
        hitAt >= 0, `osui framella ${hitAt}/${openWindow}`);
    }

    {
      const rows = [];
      let worst = Infinity;
      for (const id of BOSS_LEVELS) {
        reset();
        const s = new LevelScene(game, id);
        const boss = s.entities.find((e) => e instanceof E.Boss);
        boss.hp = 1;
        const cycle = boss.openFrames + 48 + 132;
        const windows = Math.floor((s.time * 24) / cycle);
        rows.push(`${id} ${boss.maxHp}hp/${windows}`);
        worst = Math.min(worst, windows / boss.maxHp);
      }
      expect('the level clock holds far more windows than the boss has health',
        worst >= 4, `${rows.join(' ')} — huonoin ${worst.toFixed(1)} per osuma`);
    }

    /* ------------------------------ luuranko ----------------------------- */
    /*
     * LUURANKOPOMO, 6-F, `bossVariant: 4`.
     *
     * Kaksi asiaa erottaa hänet muista pomoista, ja molemmat mitataan tässä
     * eikä uskota:
     *
     *   1. **Osuma hajottaa hänet.** Muut pomot ottavat osuman ja kiihtyvät;
     *      luuranko lentää palasiksi ja kokoaa itsensä, ja se näkyy kahtena
     *      iskuaaltona jotka lähtevät hänestä ulos. Aalto on olemassa oleva
     *      `Shockwave` — sama esine jonka pelaaja jo osaa lukea "väistä" —
     *      eikä uusi entiteetti, joten `REGISTRY` ja tilatallennus pysyvät
     *      koskemattomina. Nyrkkeilijä on verrokki: hän ei tee tätä.
     *   2. **Hänellä on oma ääni.** `VOICES` on ollut taulussa yhtä puhujaa
     *      varten siitä asti kun se kirjoitettiin, ja sen oma kommentti sanoo
     *      että ääni jota kukaan ei puhu on sama virhe kuin ääni jota mikään ei
     *      soita. Luuranko on luonteva ensimmäinen toinen puhuja: hän nauraa
     *      **silloin kun kruunu lähtee päästä**, eli täsmälleen sillä hetkellä
     *      kun häneen voi taas osua. Se on ilkkumista eikä varoitus, ja siksi
     *      se saa olla oma äänensä — varoitusäänet pysyvät jaettuina, kuten
     *      `VOICES`in kommentti vaatii.
     *
     * Naurun ajoitus mitataan soittolokista eikä lipusta: `Sfx.play` kääritään
     * hetkeksi, pomoa ajetaan monta piikkisykliä, ja lokista katsotaan että
     * ääni tuli kerran sykliä kohti ja tuli oikeassa vaiheessa.
     */
    {
      const { VOICES, Sfx: audio } = await import('/src/core/audio.js');
      reset();
      const s = new LevelScene(game, '6-F');
      game.setScene(s);
      const bone = s.entities.find((e) => e instanceof E.Boss);
      const boxerScene = new LevelScene(game, '1-F');
      const boxer = boxerScene.entities.find((e) => e instanceof E.Boss);

      const waves = (sc) => sc.entities.filter((e) => e instanceof E.Shockwave).length;
      const hit = (sc, b) => {
        b.spikePhase = 'open';
        b.spikeTimer = 1e6;
        b.invuln = 0;
        const before = waves(sc);
        b.stomp();
        return waves(sc) - before;
      };
      const boneWaves = hit(s, bone);
      const boxerWaves = hit(boxerScene, boxer);
      expect('luurankoon osuminen hajottaa hänet — kaksi aaltoa, nyrkkeilijällä ei yhtään',
        boneWaves === 2 && boxerWaves === 0 && bone.variant === 4,
        `luuranko ${boneWaves} aaltoa, nyrkkeilijä ${boxerWaves}, variantti ${bone.variant}`);

      /* Ja ääni: oma puhuja, matalampi kuin pelaaja, ja se kuuluu vasta kun
       * kruunu on pois — ei sitä laittaessa, koska silloin se olisi toinen
       * varoitus samasta asiasta (DESIGN.md kohta 8). */
      const log = [];
      const realPlay = audio.play;
      audio.play = (name) => { log.push({ name, phase: bone.spikePhase }); };
      /* Aloitus avoimesta vaiheesta, jotta laskurit ovat vertailukelpoiset:
       * yksi sykli on tasan yksi `spikes` (kruunu päähän) ja yksi nauru
       * (kruunu pois). Piikkivaiheesta aloittaminen antaisi yhden naurun
       * enemmän kuin syklejä, mikä olisi totta mutta mittaisi aloitusta. */
      bone.hp = bone.maxHp;
      bone.spikePhase = 'open';
      bone.spikeTimer = 2;
      bone.doffTimer = 0;
      for (let f = 0; f < 900; f++) bone.updateSpikes();
      audio.play = realPlay;
      const laughs = log.filter((e) => e.name === 'luuranko');
      /* Yksi nauru per kruunun riisuminen, ja riisuminen tunnistetaan siitä
       * äänestä joka sitä on aina merkinnyt (`pipe`). Näin luku ei riipu siitä
       * mihin kohtaan sykliä silmukan framebudjetti sattuu loppumaan. */
      const doffs = log.filter((e) => e.name === 'pipe').length;
      const donned = log.filter((e) => e.name === 'spikes').length;
      expect('luurangolla on oma ääni, ja hän nauraa vasta kun kruunu on pois',
        !!VOICES.luuranko && VOICES.luuranko.pitchScale < VOICES.player.pitchScale
        && laughs.length > 0 && laughs.length === doffs
        && laughs.every((e) => e.phase === 'open'),
        `naurua ${laughs.length}, kruunu pois ${doffs} kertaa, päähän ${donned}, vaiheet `
        + `${[...new Set(laughs.map((e) => e.phase))].join('/') || '-'}, `
        + `sävelkorkeus ${VOICES.luuranko ? VOICES.luuranko.pitchScale : 'ei ääntä'}`);
    }

    /* ------------------------------ sääherra ----------------------------- */
    /*
     * SÄÄHERRA, 7-F, `bossVariant: 5`, ja hän vastaa osumaan **nousemalla**.
     *
     * Kysymys on sama kuin luurangolla — mitä pomo tekee kun häneen osuu — ja
     * vastaus tulee tämän maailman aiheesta: sää väistää ylöspäin. Muut pomot
     * kiihtyvät, mikä on luku jonka pelaaja tuntee kolmen sekunnin päästä;
     * tämä lähtee ilmaan samalla framella ja tulee alas iskuaaltojen kanssa,
     * koska variantti >= 1 heittää ne kovasta laskeutumisesta. Yksi rivi
     * (`jumpTimer = 1`) tuottaa siis koko ketjun eikä `REGISTRY` muutu.
     *
     * Mitataan vertailuna eikä yksin: molempien pomojen oma hyppykello
     * asetetaan kauas, jotta ilmaan nouseminen ei voi olla sattumaa, ja
     * luuranko ajetaan samalla mitalla. Ilman vertailua testi menisi läpi
     * pelkästä siitä että pomot hyppivät muutenkin.
     */
    {
      const liftOff = (id) => {
        reset();
        const s = new LevelScene(game, id);
        game.setScene(s);
        const b = s.entities.find((e) => e instanceof E.Boss);
        const idle = mkInput();
        for (let f = 0; f < 60; f++) s.update(idle);   // anna hänen laskeutua
        b.spikePhase = 'open';
        b.spikeTimer = 1e6;
        b.invuln = 0;
        b.jumpTimer = 9999;                            // oma kello pois pelistä
        b.chargeTimer = 9999;
        b.stomp();
        for (let f = 0; f < 40; f++) {
          s.update(idle);
          if (!b.onGround) return { at: f, variant: b.variant };
        }
        return { at: -1, variant: b.variant };
      };
      const storm = liftOff('7-F');
      const skeleton = liftOff('6-F');
      expect('sääherra nousee ilmaan osumasta, luuranko ei',
        storm.variant === 5 && storm.at >= 0 && storm.at <= 3 && skeleton.at < 0,
        `sääherra (variantti ${storm.variant}) ilmassa framella ${storm.at}, `
        + `luuranko (variantti ${skeleton.variant}) framella ${skeleton.at} — 40 framen ikkuna`);
    }

    /* ------------------------ jättiläisen kannet ------------------------ */
    /*
     * THE GIANT AND HIS DECKS (4-F, 5-F, `bossVariant: 3`).
     *
     * The giant grows half a size with every stomp, so his head climbs away
     * from the floor as the fight goes on, and by the end of it no power-0 jump
     * reaches. That was ruled design and not a bug on 9.8.2026: the arena's
     * upper decks are the answer, and the decks are where the last hits come
     * from. Which turns the whole promise — every boss is beatable at the
     * smallest size — into one sentence that had never been checked:
     *
     *     a power-0 player must be able to GET ONTO a deck, and from a deck the
     *     stomp must land at every size he reaches.
     *
     * It was not true. A simulated climb over the arena found exactly one
     * standable height, the floor: the decks were 112 px up against an 85 px
     * best jump, with nothing in between. The fight's answer was scenery, which
     * is precisely why players read it as scenery.
     *
     * These four checks are that sentence, in the order a player meets it —
     * the head leaves reach, the climb exists, the drop connects, and the
     * steps stay the player's rather than his.
     */
    {
      const GIANT_LEVELS = ['4-F', '5-F'];
      const FLOOR_Y = 208;

      /* The measurement itself, kept as a check so that a later change to the
       * physics or to his growth says so instead of silently making the decks
       * pointless — or, worse, silently necessary at a size they were never
       * checked for. `budget` is the measured jump, not a remembered one. */
      {
        const budget = await (await fetch('/tools/jump-budget.json')).json();
        const stand = budget.cases.find((c) => c.label === 'standing, held').height;
        const run = budget.cases.find((c) => c.label === 'running, held').height;
        reset();
        const s = new LevelScene(game, '4-F');
        const boss = s.entities.find((e) => e instanceof E.Boss);
        // The rise the n-th stomp asks for is the boss's height when it lands.
        const rises = [];
        let scale = 1;
        for (let hit = 0; hit < boss.maxHp; hit++) {
          rises.push(Math.round(boss.baseH * scale));
          scale = Math.min(3, scale + 0.5);
        }
        const fromFloor = rises.filter((r) => r <= run).length;
        expect('the giant grows out of power-0 floor reach before he is down',
          boss.giant && fromFloor < boss.maxHp,
          `nousut ${rises.join('/')} px, seisova hyppy ${stand}, juoksuhyppy ${run}`
          + ` — lattialta ${fromFloor}/${boss.maxHp} osumaa`);
      }

      /*
       * Every height a power-0 player can stand at, found by simulation rather
       * than by reading the grid: from each place they have reached, jump
       * standing and jump in both directions with and without a run-up, and see
       * where they land. It over-reports nothing — every spot in the set was
       * arrived at by actually flying there — and it is the only honest way to
       * ask "is that platform reachable", because the grid cannot tell a ledge
       * you can just make from one you just cannot.
       */
      const standableHeights = (id) => {
        reset();
        const s = new LevelScene(game, id);
        game.setScene(s);
        s.entities = s.entities.filter((e) => e.kind !== 'enemy');
        s.time = 9999;
        s.clockStopped = true;
        const p = s.player;
        const x0 = (s.grid[0].length - 48) * 16;
        const i = mkInput();

        const hop = (x, feet, dir, runup) => {
          p.x = x; p.y = feet - p.h; p.vx = 0; p.vy = 0;
          p.onGround = true; p.invuln = 999; p.frozen = 0;
          s.centerCamera();
          for (let f = 0; f < runup; f++) {
            i.held = blank(); i.pressed = blank();
            i.held[dir > 0 ? 'right' : 'left'] = true; i.held.run = true;
            s.update(i);
            if (!p.onGround) break;
          }
          i.held = blank(); i.pressed = blank();
          if (dir) { i.held[dir > 0 ? 'right' : 'left'] = true; i.held.run = true; }
          i.pressed.jump = true; i.held.jump = true;
          s.update(i);
          for (let f = 0; f < 180 && !p.onGround; f++) {
            i.pressed = blank();
            i.held.jump = true;
            s.update(i);
          }
          return { x: p.x, feet: p.y + p.h, ok: p.onGround && !p.dying };
        };

        const seen = new Set();
        const spots = [];
        const push = (x, feet) => {
          if (x < x0 + 8 || x > x0 + 47 * 16) return;
          const k = `${Math.round(x / 8)},${Math.round(feet)}`;
          if (seen.has(k)) return;
          seen.add(k);
          spots.push({ x, feet });
        };
        for (let c = 2; c < 46; c += 2) push(x0 + c * 16, FLOOR_Y);

        const heights = new Set();
        for (let n = 0; n < spots.length && n < 400; n++) {
          heights.add(Math.round(spots[n].feet));
          for (const [dir, runup] of [[0, 0], [-1, 0], [1, 0], [-1, 45], [1, 45]]) {
            const r = hop(spots[n].x, spots[n].feet, dir, runup);
            if (r.ok) push(r.x, r.feet);
          }
        }
        return { heights: [...heights].sort((a, b) => a - b), x0 };
      };

      /* Where the decks are is read out of the level rather than written down,
       * so moving them moves the test with them. */
      const deckRows = (s) => {
        const out = new Set();
        const from = s.grid[0].length - 48;
        for (let y = 0; y < s.grid.length; y++) {
          for (let x = from; x < s.grid[y].length; x++) {
            if (s.grid[y][x] === '-') out.add(y);
          }
        }
        return [...out].sort((a, b) => a - b);
      };

      /* THE CENTRE OF ALL THIS. Red before green (DESIGN.md §7): against the
       * arena as it stood this reports one reachable height, 208, the floor. */
      for (const id of GIANT_LEVELS) {
        reset();
        const probe = new LevelScene(game, id);
        const decks = deckRows(probe);
        const { heights } = standableHeights(id);
        const reached = decks.filter((row) => heights.includes(row * 16));
        expect(`${id}: a power-0 player can climb onto the giant's decks`,
          decks.length > 0 && reached.length === decks.length,
          `kannet riveillä ${decks.join('/')}, seisottavat korkeudet ${heights.join('/')}`);
      }

      /* And from up there the stomp has to connect at every size he reaches,
       * including the one he is at when the fight ends. Dropping off a deck is
       * the whole move, so that is what is simulated: stand on the plank, press
       * down, fall. */
      for (const id of GIANT_LEVELS) {
        const misses = [];
        for (const scale of [1, 1.5, 2, 2.5, 3]) {
          reset();
          const s = new LevelScene(game, id);
          game.setScene(s);
          const boss = s.entities.find((e) => e instanceof E.Boss);
          const p = s.player;
          const x0 = (s.grid[0].length - 48) * 16;
          const deck = deckRows(s)[0];
          // The left deck, and the boss parked under the middle of it.
          let col = 0;
          for (let x = 0; x < 48; x++) if (s.grid[deck][x + (s.grid[0].length - 48)] === '-') { col = x + 2; break; }
          boss.scale = scale; boss.targetScale = scale; boss.applyScale();
          boss.x = x0 + col * 16 - boss.w / 2; boss.y = FLOOR_Y - boss.h;
          boss.vx = 0; boss.vy = 0; boss.invuln = 0;
          p.x = x0 + col * 16 - p.w / 2; p.y = deck * 16 - p.h;
          p.vx = 0; p.vy = 0; p.invuln = 0; p.frozen = 0;
          s.centerCamera();
          const hp0 = boss.hp;
          const i = mkInput();
          let hurt = false;
          for (let f = 0; f < 240 && boss.hp === hp0; f++) {
            i.held = blank(); i.pressed = blank();
            // Hold him still and open: this asks about geometry, not timing —
            // the window is already tested above, for every boss in the game.
            boss.jumpTimer = 999; boss.chargeTimer = 999; boss.charging = 0;
            boss.spikePhase = 'open'; boss.spikeTimer = 999;
            boss.vx = 0; boss.speed = 0;
            i.held.down = true;
            s.update(i);
            if (p.dying) hurt = true;
          }
          if (boss.hp === hp0 || hurt) misses.push(`${scale}x`);
        }
        expect(`${id}: a power-0 stomp off the deck lands on the giant at every size`,
          misses.length === 0, misses.length ? `ei osunut: ${misses.join(',')}` : 'kaikki koot');
      }

      /* The steps are at row 9 and not row 10 for one measured reason: his own
       * jump reaches y≈161 and a plank at row 10 tops out at 160, so he would
       * land on the player's staircase and stand there. Sixteen pixels is the
       * whole margin, so it gets a check rather than a comment. */
      for (const id of GIANT_LEVELS) {
        reset();
        const s = new LevelScene(game, id);
        game.setScene(s);
        const boss = s.entities.find((e) => e instanceof E.Boss);
        const p = s.player;
        boss.scale = 3; boss.targetScale = 3; boss.applyScale();
        boss.y = FLOOR_Y - boss.h;
        const i = mkInput();
        let top = Infinity;
        for (let f = 0; f < 900; f++) {
          p.invuln = 999;
          s.update(i);
          top = Math.min(top, boss.y + boss.h);
        }
        // The lowest plank in the arena is the step, and it is the only one he
        // could ever reach — so it is the only one worth measuring against.
        const step = Math.max(...deckRows(s)) * 16;
        expect(`${id}: the giant's own jump cannot put him on the player's steps`,
          top > step, `jalat ylimmillään y=${Math.round(top)}, alin lava y=${step}`);
      }

      /* The signal. A growth that changed nothing on screen would be a sound in
       * a noisy fight; this is the picture half (DESIGN.md §8), and it has to
       * come off the decks rather than off him or it points at the wrong thing. */
      {
        reset();
        const s = new LevelScene(game, '4-F');
        game.setScene(s);
        const boss = s.entities.find((e) => e instanceof E.Boss);
        const p = s.player;
        const deck = deckRows(s)[0];
        s.entities = s.entities.filter((e) => e.kind !== 'effect');
        boss.spikePhase = 'open'; boss.spikeTimer = 999; boss.invuln = 0;
        // He stays where he spawns — between the two decks, which is the point.
        const before = boss.targetScale;
        boss.stomp();
        const armed = boss.deckDust > 0;
        const i = mkInput();
        for (let f = 0; f < 12; f++) { p.invuln = 999; s.update(i); }
        const dust = s.entities.filter((e) => e.constructor.name === 'Puff'
          && e.y < (deck + 3) * 16);
        expect('growing shakes dust off the decks, not off the giant',
          boss.targetScale > before && armed && dust.length > 0,
          `pöly ${dust.length} hiukkasta kansien tasolla, koko ${before}->${boss.targetScale}`);
      }

      /* `boss_arena_big` is defined twice — the live one here, and a dead copy
       * left behind in `factory.js` where it used to live. `chunks.js` spreads
       * the fortress last, so the fortress copy wins. Shadowing is a trap when
       * it is silent, so this is the thing that stops being silent: edit the
       * factory copy and nothing happens, but the gate says why. */
      {
        const { CHUNKS } = await import('/src/data/chunks.js');
        const { FORTRESS_CHUNKS } = await import('/src/data/chunks/fortress.js');
        expect("the giant's arena is the fortress copy, not the dead one in factory.js",
          !!FORTRESS_CHUNKS.boss_arena_big
          && CHUNKS.boss_arena_big === FORTRESS_CHUNKS.boss_arena_big);
      }
    }
  }

  /* ------------------- murtava tehostus ja papuparoonit ------------------ */
  /*
   * The breaking power-up (PAUKKUPAPU) and its only source (PAPUPAROONI).
   *
   * Two halves of one feature, so they are tested together — and the thing
   * that ties them is the rule that has to be *proved* rather than intended:
   * nothing else in the game hands this power-up out. A second source would
   * not break anything visibly; it would only make the fight pointless, which
   * is exactly the kind of decay no crash ever reports.
   */
  {
    const P = await import('/src/entities/player.js');
    const E = await import('/src/entities/enemies.js');
    const { T } = await import('/src/gfx/tiles.js');

    /**
     * A flat corridor with a one-column wall of `ch` six tiles ahead, charged
     * into at a run. Everything about the corridor is written into the grid
     * rather than found in a level, so the test says what it means: the wall is
     * the only thing between the player and open ground.
     */
    const chargeInto = (power, ch, { cork = false, secret = false } = {}) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      const i = mkInput();
      for (let f = 0; f < 6; f++) s.update(i);
      const p = s.player;
      const foot = Math.floor((p.y + p.h) / 16);
      const x0 = Math.floor(p.x / 16);
      /*
       * A brick that is hiding something behaves like stone, so which columns
       * hide something is not a free choice — `brickSecret` is a pure function
       * of the tile's position. Pick the first column that is the case being
       * asked about, then build the corridor out to it. Which row is asked
       * about differs: a wall that must break has to be clear all the way up
       * (the body is more than one tile tall), a wall that must hold only has
       * to hide something in the row every size meets.
       */
      let wallX = -1;
      for (let dx = 6; dx <= 40 && wallX < 0; dx++) {
        const hides = secret
          ? !!s.brickSecret(x0 + dx, foot - 1)
          : [foot - 3, foot - 2, foot - 1].some((ty) => !!s.brickSecret(x0 + dx, ty));
        if (hides === secret) wallX = x0 + dx;
      }
      for (let tx = x0; tx <= wallX + 3; tx++) {
        for (let ty = foot - 5; ty < foot; ty++) s.setTile(tx, ty, T.EMPTY);
        s.setTile(tx, foot, T.GROUND);
        s.setTile(tx, foot + 1, T.GROUND);
      }
      for (let ty = foot - 3; ty < foot; ty++) s.setTile(wallX, ty, ch);
      if (cork) p.cork(400);
      for (let f = 0; f < 340; f++) {
        i.held = blank();
        i.held.right = true;
        i.held.run = true;
        i.pressed = blank();
        s.update(i);
      }
      return {
        found: wallX >= 0,
        gone: s.tileAt(wallX, foot - 1) === T.EMPTY,
        past: p.x > wallX * 16,
        player: p,
      };
    };

    expect('murtava tehostus on neljäs voimatyyppi ja sillä on nimi',
      P.POWER_TYPES.includes('pop') && P.POWER_NAMES.pop === 'PAUKKUPAPU',
      `${P.POWER_TYPES.join(',')} / ${P.POWER_NAMES.pop}`);

    {
      const withIt = chargeInto({ type: 'pop', level: 1 }, T.BRICK);
      expect('paukkupavulla tiili hajoaa sivusta juosten — pienimmälläkin koolla',
        withIt.gone && withIt.past, `hajosi ${withIt.gone}, pääsi läpi ${withIt.past}`);
    }
    {
      // The strongest player in the game without the power-up. Side-breaking is
      // the power-up's own doing, not a perk of being big — otherwise pea soup
      // is a second source and the fight stops being the only one.
      const without = chargeInto({ type: 'leaf', level: 5 }, T.BRICK);
      expect('ilman paukkupapua tiili pysyy vaikka voimataso olisi 5',
        !without.gone && !without.past, `hajosi ${without.gone}, pääsi läpi ${without.past}`);
    }
    {
      const corked = chargeInto({ type: 'pop', level: 3 }, T.BRICK, { cork: true });
      expect('ummetus tukkii myös murtamisen', !corked.gone && !corked.past,
        `hajosi ${corked.gone}`);
    }
    {
      const hiding = chargeInto({ type: 'pop', level: 3 }, T.BRICK, { secret: true });
      expect('salaisuutta kätkevä tiili kestää murtamisen, kuten kuorenkin',
        hiding.found && !hiding.gone, `löytyi ${hiding.found}, hajosi ${hiding.gone}`);
    }
    {
      // The whole table in one assertion: exactly one character gives way.
      const kept = [];
      for (const ch of [T.QCOIN, T.QPOWER, T.QSTAR, T.HARD, T.GROUND, T.CRUMBLE,
        T.SWITCH, T.USED, T.NOTE]) {
        if (chargeInto({ type: 'pop', level: 3 }, ch).gone) kept.push(ch);
      }
      expect('murtava tehostus rikkoo vain tiilen, ei mitään muuta ruutua',
        kept.length === 0, kept.length ? `hajosi myös: ${kept.join(' ')}` : 'vain B');
    }
    {
      // Losing it costs rewards and nothing else: the ability goes with the
      // type, and the type is the first thing a hit takes.
      reset({ type: 'pop', level: 1 });
      const s = new LevelScene(game, '1-1');
      const p = s.player;
      const before = p.breaker;
      p.hurt();
      expect('tehostuksen menettäminen vie murtamisen, ei kulkua',
        before === true && p.breaker === false && !p.dying,
        `ennen ${before}, jälkeen ${p.breaker}`);
    }

    /* ---------------------------- papuparooni --------------------------- */

    expect("ENEMY_CHARS has the mini-boss on 'P'",
      !!E.ENEMY_CHARS.P && E.ENEMY_CHARS.P(null, 0, 0) instanceof E.BeanBaron);

    {
      const sprites = await import('/src/gfx/sprites.js');
      expect('paroonilla, pommilla ja paukkupavulla on oma piirroksensa',
        typeof sprites.drawBeanBaron === 'function'
        && typeof sprites.drawBeanBomb === 'function');
    }

    {
      // DESIGN.md 6: a spawn character that is also a tile character is a level
      // that silently loses either the enemy or the tile.
      const clash = Object.keys(E.ENEMY_CHARS).filter((ch) => Object.values(T).includes(ch));
      expect('yksikään vihollismerkki ei törmää ruutumerkkiin', clash.length === 0,
        clash.join(' ') || `${Object.keys(E.ENEMY_CHARS).length} merkkiä`);
    }

    /* The arena and everything in it. Grouped inside one try so that a missing
     * level or a missing class reports as a failed check rather than as a
     * thrown page error — the difference matters when the suite is being used
     * red-first and half of this is not written yet. */
    try {
    {
      reset();
      const s = new LevelScene(game, '2-M');
      const barons = s.entities.filter((e) => e instanceof E.BeanBaron);
      expect('2-M on aavikon minipomokenttä: kaksi paroonia ja lippu, ei pomo-ovea',
        barons.length === 2 && !!s.goal && !s.def.boss,
        `${barons.length} paroonia, maali ${!!s.goal}`);
    }

    {
      reset();
      const s = new LevelScene(game, '2-M');
      game.setScene(s);
      const barons = s.entities.filter((e) => e instanceof E.BeanBaron);
      const drops = () => s.entities.filter((e) => e.kind === 'item' && e.itemKind === 'pop').length;
      barons[0].hp = 1;
      barons[0].stomp();
      const afterFirst = drops();
      barons[1].hp = 1;
      barons[1].stomp();
      const afterSecond = drops();
      expect('vasta viimeinen parooni pudottaa murtavan tehostuksen',
        afterFirst === 0 && afterSecond === 1, `${afterFirst} -> ${afterSecond}`);
    }

    {
      // The fight is winnable at the smallest size, like every boss in the game.
      reset();
      const s = new LevelScene(game, '2-M');
      game.setScene(s);
      const b = s.entities.find((e) => e instanceof E.BeanBaron);
      const hp = b.hp;
      const p = s.player;
      p.x = b.cx - p.w / 2;
      p.y = b.y - p.h + 4;
      p.vy = 3; p.invuln = 0; p.frozen = 0;
      s.collisions();
      expect('voimatason 0 tallaus vahingoittaa paroonia', b.hp === hp - 1 && !p.dying,
        `hp ${hp} -> ${b.hp}`);
    }

    {
      // And losable: the thing it throws is a hazard, and a hazard hits.
      reset({ type: 'shroom', level: 1 });
      const s = new LevelScene(game, '2-M');
      game.setScene(s);
      const b = s.entities.find((e) => e instanceof E.BeanBaron);
      const bomb = b.throwBomb();
      const p = s.player;
      p.x = bomb.cx - p.w / 2;
      p.y = bomb.cy - p.h / 2;
      p.invuln = 0; p.frozen = 0;
      s.collisions();
      expect('papupommi vahingoittaa: taistelun voi hävitä', p.powerLevel === 0,
        `voima 1 -> ${p.powerLevel}`);
    }

    {
      /* Left alone in its own arena for twenty seconds with the player in
       * range, a baron has to do the two things the fight is made of: throw,
       * and stay where it was put. The second one is not decoration — a baron
       * that walks off carries the game's only paukkupapu away with it, and
       * nothing would report that but a player who never found the reward. */
      reset({ type: 'shroom', level: 3 });
      const s = new LevelScene(game, '2-M');
      game.setScene(s);
      const barons = s.entities.filter((e) => e instanceof E.BeanBaron);
      const p = s.player;
      p.x = (barons[0].cx + barons[1].cx) / 2;
      p.y = 13 * 16 - p.h;
      s.centerCamera();
      const thrown = new Set();
      let strayed = 0;
      /* Sampled every frame, not once at the end. A baron hops, so `onGround`
       * at one arbitrary instant says only which phase of the hop the loop
       * stopped in — this assertion passed and failed on the same simulation
       * depending on where it landed. What the fight actually promises is that
       * it never *falls off*, and that is a property of every frame. */
      let sank = 0;
      const idle = mkInput();
      for (let f = 0; f < 1200; f++) {
        p.invuln = 20;                       // this is about them, not about him
        s.update(idle);
        for (const e of s.entities) if (e instanceof E.BeanBomb) thrown.add(e.id);
        for (const b of barons) {
          strayed = Math.max(strayed, Math.abs(b.x - b.homeX));
          sank = Math.max(sank, b.y + b.h);
        }
      }
      const onPlinth = sank <= 12 * 16 + 1;
      expect('paroonit heittelevät ja pysyvät jalustoillaan',
        thrown.size >= 4 && strayed <= 32 && onPlinth,
        `${thrown.size} pommia, poikkeama ${Math.round(strayed)} px, jalustalla ${onPlinth}`);
    }

    {
      reset();
      const s = new LevelScene(game, '2-M');
      game.setScene(s);
      const b = s.entities.find((e) => e instanceof E.BeanBaron);
      b.throwBomb();
      const snap = captureState(game);
      const kinds = snap ? snap.level.entities.map((d) => d.t) : [];
      expect('parooni ja sen pommi selviävät tilatallennuksesta — REGISTRY',
        kinds.includes('BeanBaron') && kinds.includes('BeanBomb'), kinds.join(' '));
    }
    } catch (err) {
      expect('papuparoonien areena rakentuu ja taistelu toimii', false, err.message);
    }

    {
      // The rule from the roadmap, made executable: the fight is the ONLY
      // source. Every question block, every secret brick and the moon all draw
      // from rollPowerup, so one assertion covers all three.
      reset({ type: 'shroom', level: 2 });
      const s = new LevelScene(game, '1-1');
      const seen = new Set();
      for (let i = 0; i < 2000; i++) seen.add(s.rollPowerup(s.player));
      expect('mikään lohko ei arvo murtavaa tehostusta', !seen.has('pop'),
        [...seen].join(' '));
    }
  }

  /* ---------------------------- koon vaihtuminen ------------------------ */
  /* Growing and shrinking used to be a sprite swapped while nobody was looking.
   * The freeze frames were already there; this is what they are for. The
   * hitbox must NOT flicker with the picture — only the picture. */
  {
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const i = mkInput();
    for (let f = 0; f < 6; f++) s.update(i);
    const p = s.player;

    p.collect('shroom');
    const grew = p.morphTimer > 0 && p.morphFrom === 1 && p.powerLevel === 2;
    const boxAtOnce = p.h === PLAYER_SIZES[2].h;
    let flickered = false;
    const seen = new Set();
    for (let f = 0; f < 20; f++) {
      seen.add(p.morphTimer > 0 && Math.floor(p.tick / 3) % 2 ? p.morphFrom : p.powerLevel);
      if (p.h !== PLAYER_SIZES[2].h) flickered = true;
      s.update(i);
    }
    const ran = p.morphTimer === 0;

    p.invuln = 0;
    p.frozen = 0;
    p.hurt();
    const shrank = p.morphTimer > 0 && p.morphFrom === 2 && p.powerLevel === 1;
    expect('growing and shrinking flicker between the two bodies',
      grew && shrank && boxAtOnce && !flickered && ran && seen.size === 2,
      `kasvu ${grew}, kutistus ${shrank}, laatikko vakaa ${!flickered}, `
      + `kokoja ${seen.size}`);
  }

  /* ------------------------------ ilmajarru ----------------------------- */
  /*
   * Reported from play: "there is a bit of inertia when you jump and land, you
   * still move sideways, and it is really hard to react so that you could
   * avoid the enemy you are heading towards."
   *
   * Measured (tools/measure-braking.mjs): almost none of that distance is
   * spent on the ground. At the run cap a jump carries 155 px through the air
   * and only 24 px after landing — so the reaction happens, or fails to
   * happen, in mid-air.
   *
   * The cause was one word. `skidding` required `onGround`, so turning round
   * in the air braked at the acceleration rate (0.0547) instead of the skid
   * rate (0.125). The SMB3 disassembly gates two things on `Player_InAir` —
   * plain friction with no direction held, and the bleed back down to the
   * speed cap — and gates the skid rate on neither. Both of those gates are
   * still here; this one never should have been.
   */
  {
    const flat = (power) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      for (let y = 0; y < s.h - 2; y++) s.grid[y] = s.grid[y].map(() => ' ');
      for (let y = s.h - 2; y < s.h; y++) s.grid[y] = s.grid[y].map(() => '#');
      s.entities = s.entities.filter((e) => e.kind === 'player');
      s.goal = null;
      s.time = 400;
      return s;
    };
    /** Runs up to the cap, jumps, then holds the other way for the whole arc. */
    const turnRoundInAir = (power) => {
      const s = flat(power);
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 40; f++) { s.update(i); i.pressed = blank(); }
      i.held.right = true; i.held.run = true;
      for (let f = 0; f < 90; f++) { s.update(i); i.pressed = blank(); }
      const v0 = p.vx;
      i.pressed.jump = true; i.held.jump = true;
      s.update(i); i.pressed = blank();
      i.held.right = false; i.held.left = true; i.held.jump = false;
      let frames = 0;
      while (!p.onGround && p.vx > 0 && frames < 200) {
        s.update(i); i.pressed = blank(); frames++;
      }
      return { v0, frames, stopped: p.vx <= 0 };
    };

    const air = turnRoundInAir({ type: 'shroom', level: 1 });
    // 2.5 / 0.125 = 20 frames at the skid rate; 46 at the acceleration rate.
    expect('turning round in mid-air brakes at the skid rate, not the walk rate',
      air.stopped && air.frames <= 24,
      `${air.v0.toFixed(2)} -> 0 in ${air.frames}f, pysähtyi ${air.stopped}`);

    /*
     * And the two gates that *are* faithful must stay. Letting go of the pad
     * in mid-air keeps every pixel per frame of speed — that is what makes a
     * jump commit — and it is the same rule for every body size.
     */
    const coastInAir = (power) => {
      const s = flat(power);
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 40; f++) { s.update(i); i.pressed = blank(); }
      i.held.right = true; i.held.run = true;
      for (let f = 0; f < 90; f++) { s.update(i); i.pressed = blank(); }
      const v0 = p.vx;
      i.pressed.jump = true; i.held.jump = true;
      s.update(i); i.pressed = blank();
      i.held.right = false; i.held.run = false; i.held.jump = false;
      for (let f = 0; f < 20; f++) { s.update(i); i.pressed = blank(); }
      return { v0, v1: p.vx, air: !p.onGround };
    };
    const coast = coastInAir({ type: 'shroom', level: 1 });
    expect('letting go in mid-air still costs nothing — no air friction',
      coast.air && Math.abs(coast.v1 - coast.v0) < 0.001,
      `${coast.v0.toFixed(2)} -> ${coast.v1.toFixed(2)}`);
  }

  /* ------------------------------ katto --------------------------------- */
  /* Reported from play: in 1-F you could jump up where the opening screen has
   * no ceiling, land on the roof, and run the level along the top — past the
   * boss, unable to come down and unable to win. The fix is that the world has
   * a lid, so this asserts the lid rather than the one level that lacked it. */
  {
    reset({ type: 'shroom', level: 2 });
    const s = new LevelScene(game, '1-F');
    game.setScene(s);
    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    expect('the top of the world is solid', s.solidAt(4, -1) && s.solidAt(4, -3));

    // Jump for the sky from the open start area and stay inside the level.
    const i = mkInput();
    let highest = s.player.y;
    for (let f = 0; f < 240; f++) {
      i.held = blank();
      i.held.right = f > 60;
      i.held.run = true;
      i.held.jump = f % 30 < 18;
      i.pressed = blank();
      i.pressed.jump = f % 30 === 0;
      s.update(i);
      highest = Math.min(highest, s.player.y);
    }
    expect('the player cannot get on top of the ceiling and run the roof',
      highest >= 0 && s.player.y >= 0, `ylin y ${Math.round(highest)}`);
  }

  /* --------------------------- debug-warp -------------------------------- */
  /* A testing tool, and the two things that make it safe to have one: it does
   * nothing without the developer overlay up (an invisible warp is a cheat code
   * somebody finds by accident), and a run that used it cannot reach the board
   * at all. There is an honest star for "rewound"; there is none for "skipped
   * four worlds". */
  {
    const scores = await import('/src/core/scores.js');
    reset();
    /* Tämä lohko koskee **maailmawarppia**, ja sama näppäin tarkoittaa
     * kentässä kentän ohitusta. Edellinen testi on voinut jättää ruudulle
     * kentän, joten kohde sanotaan tässä ääneen sen sijaan että se
     * perittäisiin. */
    game.pendingNode = null;
    game.debug = false;
    const world0 = game.state.world;
    game.debugWarp();
    const blocked = game.state.world === world0 && !game.state.debugWarped;

    game.debug = true;
    game.debugWarp();
    /* Warppi vie nyt oville eikä maailmaan `n + 1` (19.8.2026), koska maailmat
     * ovat kuution kärkiä: numeron kasvattaminen olisi ainoa paikka pelissä
     * joka kulkee seinän läpi. Merkintä tehdään heti, maailma vaihtuu vasta
     * kun ovi valitaan — joten "liikkui" tarkoittaa nyt "ruutu tarjoaa ovia". */
    const doorScene = game.scene && game.scene.constructor.name === 'DieScene';
    const moved = doorScene && game.state.debugWarped === true;
    if (doorScene) game.scene.pick(game.scene.doors[0].i);
    const landed = game.state.world !== world0;
    expect('the debug warp needs the overlay, marks the run and offers doors',
      blocked && moved && landed,
      `ilman debugia ${blocked}, debugilla ovet ${moved}, ovesta läpi ${landed}`);

    scores.clearScores();
    game.state.score = 999999;
    game.finishRun();
    expect('a warped run never reaches the high score table',
      scores.loadScores().length === 0
      && game.scene.constructor.name === 'HighScoreScene',
      `${scores.loadScores().length} riviä, ${game.scene.constructor.name}`);
    game.debug = false;
    game.state.debugWarped = false;
    scores.clearScores();
  }

  /* ---- kentän ohitus, sama näppäin eri paikassa ---- */
  /*
   * Omistaja kysyi tätä nimenomaan siksi että maailman warppi ei riitä
   * testaamiseen: se vie maailman **alkusolmuun**, ja siitä eteenpäin
   * `isLinkOpen` vaatii että jompikumpi pää on selvitetty. Kenttään 4-3
   * pääsemiseksi piti siis pelata 4-1 ja 4-2 läpi — mahdotonta juuri silloin
   * kun ohitettava kenttä on se joka on rikki.
   *
   * Kolme väitettä, ja kolmas on se joka pitää tämän rehellisenä:
   *   1. kentässä ohitus merkitsee **sen** kentän selvitetyksi eikä vaihda
   *      maailmaa
   *   2. kartalla sama näppäin tekee yhä sen mitä ennenkin
   *   3. ohitus kulkee `finishLevel`in läpi, joten se avaa seuraavan polun
   *      samalla koodilla jolla maali sen avaisi — oikotie olisi toinen tapa
   *      läpäistä kenttä, ja kaksi tapaa eroaa aina lopulta
   */
  {
    const worldmap = await import('/src/data/worlds.js');
    reset();
    game.debug = true;
    game.state.world = 3;                       // maailma 4
    const w4 = worldmap.WORLDS[3];
    const first = w4.nodes.find((n) => n.level);
    game.state.node = first.id;
    game.setScene(new LevelScene(game, first.level));
    game.pendingNode = first;                   // kartalta tultaessa tämä on asetettu
    /* `reset()` korvaa `finishLevel`in tyhjällä funktiolla, koska useimmat
     * testit eivät halua kentän päättyvän. Tämä testi haluaa nimenomaan sen:
     * koko väite on että ohitus kulkee oikeaa reittiä. Oma ominaisuus pois,
     * niin prototyypin oikea metodi näkyy taas. */
    delete game.finishLevel;
    const worldBefore = game.state.world;
    game.debugWarp();

    const skipped = game.state.cleared[first.id] === true;
    const stayed = game.state.world === worldBefore;
    const marked = game.state.debugWarped === true;
    expect('ohitus kentässä merkitsee sen kentän eikä vaihda maailmaa',
      skipped && stayed && marked,
      `${first.level} selvitetty ${skipped}, maailma ${worldBefore}->${game.state.world}, merkitty ${marked}`);

    /* Ja seuraava polku on auki, koska ohitus kulki oikeaa reittiä. */
    const link = w4.links.find((l) => l.a === first.id || l.b === first.id);
    const map = new (await import('/src/scenes/worldmap.js')).WorldMapScene(game);
    expect('ohitettu kenttä avaa seuraavan polun kuten maali avaisi',
      !!link && map.isLinkOpen(link),
      link ? `${link.a}->${link.b} auki ${map.isLinkOpen(link)}` : 'ei linkkiä');

    /*
     * Kartalla sama näppäin tarkoittaa yhä maailmaa — mutta **ovea** eikä
     * seuraavaa numeroa (19.8.2026). Väite on nyt se joka kuutiosta seuraa:
     * warpilla päädytään naapuriin, eli kohteen ja lähdön indeksit eroavat
     * tasan yhdellä bitillä. Se on tiukempi väite kuin vanha `+1`, koska se
     * kaatuu myös silloin jos ovilista joskus lakkaa olemasta kuutio.
     */
    reset();
    game.debug = true;
    const before = game.state.world;
    game.toWorldMap();
    game.debugWarp();
    const offered = game.scene && game.scene.constructor.name === 'DieScene';
    if (offered) game.scene.pick(game.scene.doors[0].i);
    const step = before ^ game.state.world;
    expect('kartalla ohitusnäppäin vie oville, ja ovi vie naapuriin',
      offered && step !== 0 && (step & (step - 1)) === 0,
      `${before} -> ${game.state.world}, ovia tarjottiin ${offered}`);

    game.debug = false;
    game.state.debugWarped = false;
  }

  /* ----------------------- tauko ei jää jumiin --------------------------- */
  /* A pause is something that happened to a level, not a mode the machine is
   * in. Warping out from under the pause screen used to leave `paused` true on
   * the world map — and nothing there can clear it, because the pause key only
   * answers inside a LevelScene. The map never updated, Enter did nothing, and
   * the only way out was a reload.
   *
   * The warp is only the shortest way to reproduce it. Any scene change made
   * while paused does the same, which is why the fix is in `setScene` and this
   * test checks the state of the game rather than the state of the warp. */
  {
    reset();
    game.debug = true;
    game.setScene(new LevelScene(game, '1-1'));
    /* Ilman solmua tämä on maailmawarppi, ja se on se jonka tämä testi
     * tarkoittaa: kenttä on tässä vain lyhin tapa saada tauko päälle. */
    game.pendingNode = null;
    game.paused = true;
    game.debugWarp();
    const cleared = game.paused === false;
    /* Warppi vie oville, ja ovet ovat yhtä lailla "jokin muu ruutu": tämä
     * väite koskee `paused`-lippua eikä sitä mihin päädyttiin. */
    const onMap = game.scene.constructor.name === 'DieScene';

    /* Asserted on the flag and not by running a frame: `game.step()` drives the
     * whole loop, including the attract-mode idle counter, and a test that
     * borrows it hands the next three tests a title screen that has already
     * been waiting. Found the hard way — it failed the demo tests, not this
     * one. `paused` on a scene with no pause key *is* the stuck state, so the
     * flag is the thing worth asserting. */
    expect('warping out from under the pause screen leaves the game running',
      cleared && onMap,
      `paused ${game.paused}, ${game.scene.constructor.name}`);

    /* And the same for the ordinary way out of a level, which shares the fix. */
    reset();
    game.setScene(new LevelScene(game, '1-1'));
    game.paused = true;
    game.toWorldMap();
    expect('any scene change clears the pause, not just the warp',
      game.paused === false, `paused ${game.paused}`);

    game.debug = false;
    game.state.debugWarped = false;
  }

  /* --------------------------- salaisuuslaskuri -------------------------- */
  {
    reset();
    const tall = new LevelScene(game, '1-2');
    const c = game.levelSecrets(tall);
    const plain = game.levelSecrets(new LevelScene(game, '1-1'));
    /* The scene is fresh, so its beanstalk has not been grown yet and there is
     * not one vine tile in the grid. It still has to count as a vine: this
     * overlay exists to say what a level is hiding while somebody tests it, and
     * a count that only appears once the tester has already found the thing is
     * a count that helps nobody. */
    expect('the debug overlay counts the secrets in the level, grown or not',
      c.vine === 1 && c.warp > 0 && c.bands === 1
      && plain.vine === 0 && plain.warp === 0 && plain.bands === 0,
      `1-2: varsi ${c.vine} (ruudukossa ${tall.beanstalks.size} istuttamatta) `
      + `putki ${c.warp} kaistat ${c.bands}`
      + ` / 1-1: varsi ${plain.vine} putki ${plain.warp}`);
    /* Counted across the whole game rather than one level: there are only 186
     * bricks in all of it, and the first version of this feature hid about five
     * surprises in the lot — a mechanic nobody would ever meet. */
    let bricks = 0;
    let secrets = 0;
    for (const id of levelIds()) {
      const sc = new LevelScene(game, id);
      for (let ty = 0; ty < sc.h; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          if (sc.rawTileAt(tx, ty) !== 'B') continue;
          bricks++;
          if (sc.brickSecret(tx, ty)) secrets++;
        }
      }
    }
    const share = secrets / Math.max(1, bricks);
    expect('secret bricks are common enough to meet and rare enough to matter',
      secrets >= 12 && share > 0.08 && share < 0.35,
      `${secrets}/${bricks} tiiltä = ${Math.round(share * 100)} %`);
  }

  /* ------------- kolikkojonot: vihje eikä kyltti (DESIGN.md §5) ----------- */
  /*
   * A hidden band is the one secret in this game that a player cannot stumble
   * into. A loaded brick is bumped by accident, a star block is an ordinary `?`
   * and gets hit out of habit, a switch is a tile of its own with a slab of
   * brick hanging over it — but a warp pipe asks you to *stand on it and press
   * down*, and nothing in ordinary play ever does that. So the ways into a
   * hidden band are the places a coin hint has to earn its keep, and these are
   * the properties that separate a hint from a sign. Each one can actually go
   * wrong, which is why each one is a line here rather than a sentence in a
   * comment somewhere:
   *
   *   1. **every entrance carries one.** A census, not a spot check: eight ways
   *      into a hidden band in the whole game, and a ninth added later has to
   *      come past this line rather than ship silently unhinted.
   *   2. **it pays on its own.** Every hint coin is collectible from the route
   *      band's own floor at power level 0, without finding anything. That is
   *      `fac_duct_down`'s test, quoted: "they are worth having on their own, so
   *      following them costs nothing if there turns out to be nothing".
   *   3. **it is not an arrow.** Three ways of failing that, all measured: a
   *      coin touching the entrance tile marks it; a run centred on the entrance
   *      is an X on the spot; and a shape that only ever appears at a secret is
   *      a signpost however innocent it looks. The third is the one that needs
   *      the whole game to answer, so it is counted over the whole game.
   *   4. **the shape says "a pipe", never "this pipe".** Two-tile floor pipes
   *      are pixel-identical apart from the shine in a warp's throat, so the
   *      coins over them have to be identical too. This is the line that fails
   *      when somebody gives the secret one a hint and forgets its twin.
   *
   * What is deliberately *not* asserted here: that a loaded brick, a star block
   * or a switch has a hint. None of them gets one, and that is the design —
   * a trail on a secret that already reads is noise, and noise is what makes
   * the real hints stop working.
   */
  {
    reset();
    const { getLevel } = await import('/src/data/levels.js');
    const jump = await (await fetch('/tools/jump-budget.json')).json();

    /* Eight columns either side, and rows 7-10 of the band. That is the bump
     * row and the two rows around it — the band a coin has to be in to be
     * grabbed from the floor at all — widened by enough that a three-coin run
     * beside an entrance counts and the next chunk's coins do not. */
    const WIN = 8;
    const BUMP_FROM = 7;
    const BUMP_TO = 10;
    /* Anything the feet can rest on, so a coin over a pipe is measured against
     * the pipe's own lid rather than the floor four rows under it. */
    const STANDABLE = new Set([...'#XB?!*uN[]{}%()S-']);
    const isCoin = (sc, tx, ty) => sc.rawTileAt(tx, ty) === 'o';

    /**
     * Every way into a hidden band, read from the loaded scene rather than from
     * the level data, so that the bean block is the one the engine actually
     * planted (`plantVines`) instead of a fourth copy of where it hangs.
     */
    const entrancesOf = (sc) => {
      const def = getLevel(sc.id);
      if (!def.bands) return [];
      const top = def.bands.main;
      const list = [];
      for (let ty = top; ty < top + def.bands.rows; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          if (!'()'.includes(sc.rawTileAt(tx, ty))) continue;
          if (tx > 0 && '()'.includes(sc.rawTileAt(tx - 1, ty))) continue;
          let x1 = tx;
          while (x1 + 1 < sc.w && '()'.includes(sc.rawTileAt(x1 + 1, ty))) x1++;
          list.push({ kind: 'putki', x0: tx, x1, y: ty, top });
        }
      }
      for (const key of sc.beanstalks.keys()) {
        const [bx, by] = key.split(',').map(Number);
        list.push({ kind: 'papulohko', x0: bx, x1: bx, y: by, top });
      }
      return list.map((e) => ({ ...e, where: `${sc.id} ${e.kind}@${e.x0}` }));
    };

    const hints = [];
    let runs = 0;
    let runsAtSecret = 0;
    const pipes = [];
    for (const id of levelIds()) {
      const sc = new LevelScene(game, id);
      const def = getLevel(id);
      const doors = entrancesOf(sc);
      for (const e of doors) {
        const coins = [];
        for (let ty = e.top + BUMP_FROM; ty <= e.top + BUMP_TO; ty++) {
          for (let tx = Math.max(0, e.x0 - WIN); tx <= Math.min(sc.w - 1, e.x1 + WIN); tx++) {
            if (isCoin(sc, tx, ty)) coins.push({ tx, ty });
          }
        }
        hints.push({ id, e, coins, sc });
      }

      /* Every coin run in the bump band of every band, so that "how often does
       * a coin row mean something" is a number and not an impression. A run is
       * allowed one empty column, because `o o o` is one row of coins and not
       * three rows of one. */
      const bandTops = def.bands ? [0, def.bands.main, def.bands.cave] : [0];
      for (const b of bandTops) {
        for (let ty = b + BUMP_FROM; ty <= b + BUMP_TO; ty++) {
          let tx = 0;
          while (tx < sc.w) {
            if (!isCoin(sc, tx, ty)) { tx++; continue; }
            let end = tx;
            for (;;) {
              if (isCoin(sc, end + 1, ty)) { end++; continue; }
              if (sc.rawTileAt(end + 1, ty) === ' ' && isCoin(sc, end + 2, ty)) { end += 2; continue; }
              break;
            }
            runs++;
            if (doors.some((e) => e.top === b && end >= e.x0 - WIN && tx <= e.x1 + WIN)) runsAtSecret++;
            tx = end + 1;
          }
        }
      }

      /* Two-tile floor pipes: a mouth, one tile of throat, and ground. That is
       * `pipe_short`, `warp_pipe` and `fac_duct_down` — the same silhouette
       * whether or not it goes anywhere. */
      for (let ty = 0; ty < sc.h; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          const ch = sc.rawTileAt(tx, ty);
          if (ch !== '[' && ch !== '(') continue;
          if (sc.rawTileAt(tx, ty + 1) !== '{' || sc.rawTileAt(tx, ty + 2) !== '#') continue;
          const offsets = [];
          for (let cy = ty - 4; cy < ty; cy++) {
            for (let cx = tx - WIN; cx <= tx + WIN; cx++) if (isCoin(sc, cx, cy)) offsets.push(cx - tx);
          }
          pipes.push({ id, tx, warp: ch === '(', offsets: offsets.join(',') });
        }
      }
    }

    /* 1. The census. */
    const bare = hints.filter((h) => h.coins.length < 3);
    expect('jokainen tie salaiselle kaistalle kantaa kolikkovihjeen',
      hints.length === 8 && bare.length === 0,
      `${hints.length} sisäänkäyntiä, kolikoita ${hints.map((h) => h.coins.length).join('/')}`
      + (bare.length ? ` — vihjeettä: ${bare.map((h) => h.e.where).join(' ')}` : ''));

    /* 2. It pays on its own: the drop from every hint coin to the first thing
     * under it that holds, against the measured standing jump at power 0. A
     * coin with nothing under it at all is worse than a high one — it hangs
     * over a pit, and a coin you have to dare a pit for is not a free hint. */
    const standing = (jump.cases.find((c) => c.label === 'standing, held') || {}).height || 0;
    let worst = 0;
    const dangling = [];
    for (const h of hints) {
      for (const c of h.coins) {
        let sy = -1;
        for (let ty = c.ty + 1; ty < h.e.top + 16; ty++) {
          if (STANDABLE.has(h.sc.rawTileAt(c.tx, ty))) { sy = ty; break; }
        }
        if (sy < 0) { dangling.push(`${h.e.where} ${c.tx},${c.ty}`); continue; }
        worst = Math.max(worst, sy - c.ty);
      }
    }
    expect('vihjekolikot saa pienimmällä koolla ilman itse salaisuutta',
      dangling.length === 0 && worst * 16 <= standing,
      `korkeintaan ${worst} ruutua = ${worst * 16} px, paikaltaan hyppy nostaa ${standing} px`
      + (dangling.length ? ` — tyhjän päällä: ${dangling.join(' ')}` : ''));

    /* 3a. No coin touches the entrance tile. A coin on the thing is a marker on
     * the thing, whatever the rest of the run is doing. */
    let nearest = 99;
    for (const h of hints) {
      for (const c of h.coins) {
        const dx = Math.max(h.e.x0 - c.tx, c.tx - h.e.x1, 0);
        nearest = Math.min(nearest, Math.max(dx, Math.abs(c.ty - h.e.y)));
      }
    }
    expect('yksikään vihjekolikko ei kosketa sisäänkäyntiä',
      nearest >= 2, `lähin kolikko ${nearest} ruudun päässä`);

    /* 3b. And the run is not centred on it. Coins either side of a thing, evenly
     * spaced, is the oldest map marking there is. */
    const offCentre = hints.map((h) => {
      const xs = h.coins.map((c) => c.tx);
      const mid = (Math.min(...xs) + Math.max(...xs)) / 2;
      return { where: h.e.where, off: Math.abs(mid - (h.e.x0 + h.e.x1) / 2) };
    });
    const centred = offCentre.filter((o) => o.off < 1);
    expect('vihjejono ei ole keskitetty sisäänkäynnin päälle',
      centred.length === 0,
      `poikkeama keskeltä ${offCentre.map((o) => o.off).join('/')} ruutua`
      + (centred.length ? ` — keskitetty: ${centred.map((o) => o.where).join(' ')}` : ''));

    /* 3c. The camouflage, counted over the whole game: a coin row that means
     * something has to be the exception, or following coin rows becomes an
     * oracle and the hint has turned into a sign. */
    const share = runsAtSecret / Math.max(1, runs);
    expect('kolikkorivi on tavallinen näky eikä salaisuuden merkki',
      runs >= 200 && share <= 0.1,
      `${runsAtSecret}/${runs} kolikkoriviä salaisuuden kohdalla = ${(share * 100).toFixed(1)} %`);

    /* 4. The twin. */
    const shapes = new Set(pipes.map((p) => p.offsets));
    const warps = pipes.filter((p) => p.warp).length;
    expect('kahden ruudun lattiaputket kantavat saman kolikkorivin, warppasi tai ei',
      pipes.length >= 6 && shapes.size === 1 && warps < pipes.length,
      `${pipes.length} putkea, ${warps} warppia, kolikkorivit [${[...shapes].join('] [')}]`);

    /*
     * 5. JA SAMA VÄITE MUODOSTA: lyhyt putki ei saa olla warpin synonyymi.
     *
     * Kohta 4 takaa että kaikki kahden ruudun lattiaputket *näyttävät*
     * samalta. Se ei takaa mitään siitä miten usein sellaisen alle menee
     * jotain — ja jos niitä on kuusi ja neljä on warppeja, "paina alas jokaisen
     * kolikoidun lyhyen putken päällä" osuu kahdesti kolmesta. Salaisuus jonka
     * arvaa kahdesti kolmesta ei ole salaisuus vaan rutiini, ja koko
     * kolikkovihjeen idea (kohta 3c) kaatuu sen mukana: vihje näyttäisi
     * vihjeeltä ja toimisi kylttinä.
     *
     * **Miksi kolmasosa.** Luku ei ole makuasia eikä sitä ole poimittu ilmasta,
     * vaan se on *sama kaista jonka peli jo asettaa toiselle tavalliselta
     * näyttävälle esineelle joka joskus onkin salaisuus*: piilotiili. Tuon
     * testin raja tässä samassa tiedostossa on `share < 0.35` — alle 35 % kaikista
     * tiilistä saa kätkeä jotain. Lyhyt lattiaputki on täsmälleen sama väite eri
     * esineestä, joten se saa saman katon, ja kolmasosa on lähin luku jonka
     * alle nykyiset neljä warppia mahtuvat: 4/12 = 33,3 %.
     *
     * Kolmasosa on myös se kohta jossa väite muuttuu laadullisesti. Puolikkaalla
     * "useimmat lyhyet putket ovat tavallisia" on totta yhden putken erolla ja
     * kääntyy takaisin heti kun joku lisää yhden warpin. Kolmasosalla pelaaja
     * joka painaa alas jokaisen lyhyen putken päällä on väärässä kaksi kertaa
     * useammin kuin oikeassa, ja uusi warp maksaa kolme uutta tavallista
     * putkea — mikä on juuri se hinta jonka sen kuuluu maksaa.
     *
     * Ei alarajaa. Tavallisia putkia ei voi olla liikaa: jokainen niistä on
     * ilmaisia kolikoita ja yksi vertailukohta lisää.
     */
    expect('lyhyt lattiaputki ei ole warpin synonyymi',
      warps * 3 <= pipes.length,
      `${warps}/${pipes.length} lattiaputkesta warppaa = ${(warps * 100 / pipes.length).toFixed(1)} %`
      + ` (katto 33,3 %, sama kuin piilotiilen 35 %)`);
  }

  /* ---------------- salaisuudet kartalla: kertoo että, ei missä ----------- */
  /*
   * Four things have to hold at once, and the last two are the design:
   *
   *   1. the count is right, and right WITHOUT loading the level — the map has
   *      to draw it for every node at once;
   *   2. finding one moves it, and the move survives a save;
   *   3. a save written before any of this existed still loads, and reads as
   *      nothing found, which is the truth;
   *   4. the map shows HOW MANY and never WHICH. That one is tested by pixels,
   *      because it is the only way to prove a negative: two saves that found
   *      different secrets but the same number of them must draw the same map.
   */
  {
    reset();
    const {
      secretKeys, secretTotal, secretTally, foundKeys, noteSecret, brickHides, SKY, CAVE,
    } = await import('/src/core/secrets.js');
    const { WorldMapScene } = await import('/src/scenes/worldmap.js');
    const { Save, DEFAULT_SAVE } = await import('/src/core/save.js');
    const { getLevel } = await import('/src/data/levels.js');

    /* 1a. A level with a known secret, and one with none. 1-2 is the tall level
     * of world 1: a room above, a cave below and one loaded brick. 1-1 is the
     * opening level and hides nothing at all.
     *
     * **Kolme eikä viisi 18.8.2026 alkaen.** Piilotiili on sijainnin hajautus
     * (`hashPlace(tx, ty)`), ja kun kenttädata kasvoi 15 rivistä 16:een jokainen
     * ruutu siirtyi rivin alaspäin — eli jokainen piilotiili koko pelissä
     * arvottiin uudestaan. Mitattuna: 98 piilotiiltä ennen, 79 jälkeen, ja
     * 1-2:n kolmesta jäi yksi. Luku on siis mitattu uudestaan eikä löysätty,
     * ja 1-1:n nolla on yhä nolla — se on se puolisko joka on väite. */
    const tall = secretKeys('1-2');
    expect('salaisuuslaskenta osaa kentän jossa on salaisuuksia ja kentän jossa ei ole',
      secretTotal('1-2') === 3 && tall.includes(SKY) && tall.includes(CAVE)
      && secretTotal('1-1') === 0,
      `1-2: ${tall.join(' ')} / 1-1: ${secretTotal('1-1')}`);

    /* 1b. Counted from level data alone, so it must agree with the engine's own
     * reading of the loaded grid. This is what keeps the copied brick rates
     * honest: they drift, this fails. */
    const drift = [];
    for (const id of levelIds()) {
      const sc = new LevelScene(game, id);
      let bricksHere = 0; let stars = 0; let switches = 0;
      for (let ty = 0; ty < sc.h; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          const ch = sc.rawTileAt(tx, ty);
          if (ch === 'B' && sc.brickSecret(tx, ty)) {
            bricksHere++;
            if (!brickHides(tx, ty)) drift.push(`${id} ${tx},${ty}`);
          }
          if (ch === '*') stars++;
          if (ch === 'S') switches++;
        }
      }
      const keys = secretKeys(id);
      const mine = { b: 0, s: 0, w: 0, band: 0 };
      for (const k of keys) {
        if (k === SKY || k === CAVE) mine.band++;
        else if (k[0] === 'B') mine.b++;
        else if (k[0] === '*') mine.s++;
        else if (k[0] === 'S') mine.w++;
      }
      if (mine.b !== bricksHere || mine.s !== stars || mine.w !== switches) {
        drift.push(`${id} ${mine.b}/${bricksHere} ${mine.s}/${stars} ${mine.w}/${switches}`);
      }
      const bands = getLevel(id).bands ? 1 : 0;
      if (!bands && mine.band) drift.push(`${id} kaistaton mutta ${mine.band} aluetta`);
    }
    expect('kartan laskenta ja moottorin luenta ovat samaa mieltä joka kentässä',
      drift.length === 0, drift.slice(0, 4).join(' · '));

    /* 2. Found means "the game gave you what it was hiding". A block pays out;
     * a hidden area is where your feet are. */
    reset();
    const scene = new LevelScene(game, '1-2');
    const brick = secretKeys('1-2').find((k) => k[0] === 'B') || 'B0,0';
    const [bx, by] = brick.slice(1).split(',').map(Number);
    scene.bumpTile(bx, by, scene.player);
    const afterBrick = secretTally(game.state, '1-2');
    scene.player.y = 5 * 16;
    scene.player.x = 150 * 16;
    scene.update(mkInput());
    const afterSky = secretTally(game.state, '1-2');
    expect('salaisuus löytyy silloin kun se antaa sen mitä se kätki',
      afterBrick.found === 1 && afterBrick.total === 3
      && afterSky.found === 2 && foundKeys(game.state, '1-2').includes(SKY),
      `tiili ${afterBrick.found}/${afterBrick.total} → alue ${afterSky.found}`);

    /* …and it has to still be there tomorrow. */
    const before = localStorage.getItem('sfb3.save.v2');
    Save.write(game.state);
    const reloaded = Save.load();
    expect('löydetty salaisuus kestää tallennuksen',
      secretTally(reloaded, '1-2').found === 2, JSON.stringify(reloaded.secrets || null));

    /* 3. The save format did not get a new version number, so this is the case
     * that has to work: a save written yesterday, with no secret field at all. */
    localStorage.setItem('sfb3.save.v2', JSON.stringify({
      lives: 3, coins: 7, score: 4200, power: { type: 'shroom', level: 2 },
      reserve: null, world: 0, node: 'w1-2', cleared: { 'w1-1': true }, worldsOpen: 1,
    }));
    let old = null; let oldErr = '';
    try { old = Save.load(); } catch (e) { oldErr = e.message; }
    const oldReads = old && secretTally(old, '1-2');
    expect('vanha tallennus ilman salaisuustietoa latautuu ja lukee nollaksi',
      !!old && old.lives === 3 && !!old.secrets && oldReads.found === 0
      && oldReads.total === 3 && DEFAULT_SAVE().secrets
      && noteSecret(old, '1-2', brick) === true,
      oldErr || `lives ${old && old.lives}  ${oldReads && oldReads.found}/${oldReads && oldReads.total}`);
    if (before === null) localStorage.removeItem('sfb3.save.v2');
    else localStorage.setItem('sfb3.save.v2', before);

    /* 4. Same map, drawn three ways. */
    const shot = (found) => {
      const g = Object.create(game);
      g.state = { ...DEFAULT_SAVE(), world: 0, node: 'w1-2', secrets: { '1-2': found } };
      const map = new WorldMapScene(g);
      const cv = document.createElement('canvas');
      cv.width = 320; cv.height = 240;
      const c2 = cv.getContext('2d');
      map.draw(c2);
      return c2.getImageData(0, 0, 320, 240).data.join(',');
    };
    const bricksOf = secretKeys('1-2').filter((k) => k[0] === 'B').concat('B0,0');
    const none = shot([]);
    const oneA = shot([bricksOf[0]]);
    const oneB = shot([SKY]);
    expect('kartta kertoo montako salaisuutta on löytynyt',
      none !== oneA, `${none.length} vs ${oneA.length} tavua`);
    expect('kartta ei kerro mikä salaisuus löytyi',
      oneA === oneB, 'sama määrä, eri salaisuus, sama kuva');
  }

  /* ------------------- generoitujen kenttien uusi sanasto ---------------- */
  /*
   * The generated world gets its own assertions, and they are here rather than
   * in the generator because the generator only knows what it wrote. These ask
   * the *engine* what is in the shipped grid.
   *
   * The one that matters most is the secret. Which brick hides something is a
   * pure function of position, so it costs nothing and applies to generated
   * levels for free — and "for free" is how the levels this replaced ended up
   * with 5-1 and 5-2 holding no secret at all. `gen-levels.mjs` now guarantees
   * one, using its own copy of the two rates in `src/scenes/level.js` because
   * that module cannot be loaded outside a browser. This test is what makes the
   * copy safe: it asks `brickSecret` itself, so if the rates ever drift apart
   * the gate fails instead of the world quietly going empty.
   */
  {
    reset();
    const { T } = await import('/src/gfx/tiles.js');
    const generated = ['5-1', '5-2', '5-3'];
    const world = { crumble: 0, switches: 0, stars: 0 };
    const perLevel = [];
    for (const id of generated) {
      const sc = new LevelScene(game, id);
      const seen = { crumble: 0, switches: 0, stars: 0, bricks: 0, secrets: 0 };
      for (let ty = 0; ty < sc.h; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          const ch = sc.rawTileAt(tx, ty);
          if (ch === T.CRUMBLE) seen.crumble++;
          if (ch === T.SWITCH) seen.switches++;
          if (ch === T.QSTAR) seen.stars++;
          if (ch === T.BRICK) {
            seen.bricks++;
            if (sc.brickSecret(tx, ty)) seen.secrets++;
          }
        }
      }
      world.crumble += seen.crumble;
      world.switches += seen.switches;
      world.stars += seen.stars;
      perLevel.push({ id, ...seen });
    }
    const say = perLevel.map((l) => `${l.id}: %${l.crumble} S${l.switches} *${l.stars} `
      + `${l.secrets}/${l.bricks} salaista`).join(' · ');

    expect('every generated level hides something in an ordinary brick',
      perLevel.every((l) => l.secrets > 0), say);
    /* Exactly one star per level: none means the level never got the surprise,
     * two means it stopped being one. */
    expect('every generated level has exactly one star block',
      perLevel.every((l) => l.stars === 1), say);
    /* Coverage is the world's promise, not the level's — the hand-made worlds
     * hand out mechanics one per level too. */
    expect('the generated world carries crumbling platforms and a switch block',
      world.crumble > 0 && world.switches > 0, say);
    /* A switch with nothing to change is furniture. */
    expect('every switch block has bricks in the same level to change',
      perLevel.every((l) => l.switches === 0 || l.bricks > 0), say);
  }

  /* ------------------------- teemakohtainen seisonta -------------------- */
  /* Standing about is where the character says what kind of place this is: he
   * shivers on the ice and mops his brow in the desert. Asserted by pixel count
   * against the same pose in a temperate world, because "it is in there
   * somewhere" is how the first version shipped a four-pixel bead nobody could
   * see. Same idle value on both sides — comparing different idle values only
   * measures the ordinary idle beats. */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const c = document.createElement('canvas');
    c.width = 40;
    c.height = 40;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    const shot = (o) => {
      g.clearRect(0, 0, 40, 40);
      sprites.drawPlayer(g, 8, 4, {
        type: null, level: 1, facing: 1, state: 'idle', frame: 0, wag: 0, ...o,
      });
      return g.getImageData(0, 0, 40, 40).data;
    };
    const diff = (a, b) => {
      let n = 0;
      for (let i = 0; i < a.length; i += 4) {
        if (a[i] !== b[i] || a[i + 1] !== b[i + 1] || a[i + 2] !== b[i + 2]
          || a[i + 3] !== b[i + 3]) n++;
      }
      return n;
    };
    const cold = diff(shot({ tick: 100, idle: 210, theme: 'grass' }),
      shot({ tick: 100, idle: 210, theme: 'ice' }));
    const hot = diff(shot({ tick: 100, idle: 300, theme: 'grass' }),
      shot({ tick: 100, idle: 300, theme: 'desert' }));
    const shivers = diff(shot({ tick: 100, idle: 210, theme: 'ice' }),
      shot({ tick: 102, idle: 210, theme: 'ice' }));
    // A temperate world must stay exactly as it was.
    const plainSame = diff(shot({ tick: 100, idle: 300, theme: 'grass' }),
      shot({ tick: 100, idle: 300 }));
    expect('the hero shivers on the ice and sweats in the desert',
      cold > 40 && hot > 20 && shivers > 40 && plainSame === 0,
      `jää ${cold}px, aavikko ${hot}px, värinä ${shivers}px, niitty ${plainSame}px`);
  }

  /* --------------------- animaatiokierrokset, viisi kokoa ---------------- */
  /*
   * Every pose the player can be in, at all five power levels and in all four
   * power types, measured against the box the game actually hits things with.
   * Two rules, and both of them were broken when this was written:
   *
   *  1. Nothing may be drawn outside the box except the exceptions named here.
   *     The walk cycle drew its feet 3px below the floor line at level 0 and
   *     1-2px below it at levels 1-5, and the idle breath lifted the cap out
   *     through the top of the head.
   *  2. The character is one piece. The breath pulled the shirt off the
   *     trousers at every level above 0, so for a third of every breath he came
   *     apart at the waist, and the walk's third frame left the back leg
   *     floating a pixel below the hip at every size.
   *
   * Neither was visible to any numeric test before this one and both were
   * obvious the moment the poses were laid out as a sheet — which is why this
   * measures the picture and not the numbers that made it.
   *
   * Artwork is told apart from its own outline by colour, not by alpha: the
   * outline is rgba(16,16,24,0.85), translucent everywhere except where all
   * four offsets stack, and there it lands on 16,16,23 — one blue short of
   * C.ink, and therefore not a colour the player is ever painted in.
   *
   * The exceptions are named rather than tolerated as slack, because slack
   * hides the next bug: a raccoon has ears above his head and a tail behind
   * him, a bead of sweat leaves the face on its way down, the shoulders are a
   * pixel wider than the box on each side (see the report — closing that one
   * means moving PLAYER_SIZES, which moves every collision in the game), and
   * the shiver displaces the whole body a pixel sideways because that is what
   * a shiver is. Allowances are given in template pixels and scaled up with
   * the sprite, since that is how the drawing itself grows.
   */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const { PLAYER_SIZES, PLAYER_DUCK_SIZES, drawPlayer } = sprites;
    /* Twelve rows taller and the sprite twelve lower than this used to be: the
     * sleeper's ZZZ climbs 21 px above his head, and a picture that runs off
     * the top of the sheet counts as one piece fewer rather than as a leak,
     * which is a check quietly measuring the canvas instead of the drawing. */
    const W = 96; const H = 88; const OX = 36; const OY = 27;
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    /* Every colour the player is ever painted in. It is a list and not a rule
     * because the outline has to be told from the artwork, and the day the
     * costume changed it was also the list that said what the costume was: the
     * greens and whites of the old shirt left it, the slate, the purples, the
     * gas green and the brass of POWER_LOOKS came in. A colour missing from
     * here does not fail loudly — the audit below simply stops seeing that part
     * of the body, and a sprite with an invisible middle counts as two pieces. */
    const ART = new Set([
      '16,16,24', '240,184,144', '192,120,80', '31,111,38',
      '140,76,24', '90,44,12', '200,140,64', '248,248,248', '92,156,40',
      '255,208,72', '156,106,40', '224,76,60', '200,200,208', '192,90,36',
      '140,60,28', '74,28,10', '42,74,106', '127,200,240',
      '232,248,255',
      // POWER_LOOKS, the gas hose and the valves.
      '168,224,74', '160,76,160', '106,44,106', '60,24,64',
      '106,116,136', '57,65,79', '76,86,102', '232,255,192', '216,168,96',
      // Kaasulehden messinki (puku, vyö, housut), ks. POWER_LOOKS.leaf.
      '184,134,44', '92,60,12', '140,100,20',
    ]);

    const poses = [
      { n: 'idle', s: { state: 'idle', tick: 0, idle: 0 } },
      { n: 'breath', s: { state: 'idle', tick: 40, idle: 60 } },
      { n: 'look up', s: { state: 'idle', tick: 5, idle: 230 } },
      { n: 'scratch', s: { state: 'idle', tick: 5, idle: 320 } },
      { n: 'tap', s: { state: 'idle', tick: 5, idle: 497 } },
      { n: 'shiver-', s: { state: 'idle', tick: 100, idle: 210, theme: 'ice' } },
      { n: 'shiver+', s: { state: 'idle', tick: 102, idle: 210, theme: 'ice' } },
      { n: 'sweat 0', s: { state: 'idle', tick: 5, idle: 231, theme: 'desert' } },
      { n: 'sweat 7', s: { state: 'idle', tick: 5, idle: 385, theme: 'desert' } },
      { n: 'wipe', s: { state: 'idle', tick: 5, idle: 620, theme: 'desert' } },
      { n: 'walk 0', s: { state: 'walk', frame: 0 } },
      { n: 'walk 1', s: { state: 'walk', frame: 1 } },
      { n: 'walk 2', s: { state: 'walk', frame: 2 } },
      { n: 'walk 3', s: { state: 'walk', frame: 3 } },
      { n: 'run 0', s: { state: 'walk', frame: 0, running: true } },
      { n: 'run 2', s: { state: 'walk', frame: 2, running: true } },
      { n: 'jump', s: { state: 'jump', frame: 0 } },
      { n: 'duck', s: { state: 'duck', ducking: true } },
      /*
       * MAAHANISKU, kolme näytettä. Ne ovat tässä listassa eivätkä omassa
       * kokeessaan siksi että tämän listan kaksi porttia ovat juuri ne jotka
       * uusi asento voi rikkoa: kyykky piirretään laatikon *pohjalle* eikä sen
       * ylälaitaan, joten se on kaikista asennoista lähimpänä sitä riviä jonka
       * alle mikään ei saa mennä (`below: 0` — lattiaviiva on lattiaviiva), ja
       * se on myös ainoa asento jossa pää ja vartalo on siirretty yhdessä eikä
       * erikseen, eli ainoa jossa hahmo voisi katketa kahtia.
       *
       * `ducking` on tarkoituksella `false` kaikissa kolmessa: syöksy ei kutistu
       * laatikkoaan, ja jos joku joskus panee sen kutistumaan, tämä lista mittaa
       * asennon väärää laatikkoa vasten ja kertoo siitä.
       */
      { n: 'pound charge', s: { state: 'jump', pound: 'charge', poundT: 12 } },
      { n: 'pound lag', s: { state: 'idle', pound: 'lag', poundT: 20 } },
      { n: 'pound rise', s: { state: 'idle', pound: 'lag', poundT: 3 } },
      /* Hand over hand up a vine, seen from behind. Nothing leaves the box
       * that the standing pose does not already send out: the raised arms sit
       * on the same columns the hanging ones do. */
      { n: 'climb 0', s: { state: 'climb', frame: 0 } },
      { n: 'climb 1', s: { state: 'climb', frame: 1 } },
      /*
       * The second-tier idle, one per theme. Each is sampled at the frame of
       * its own cycle that reaches furthest, so the numbers below are the
       * animation's maxima and not one convenient still: `px` is template
       * pixels and grows with the sprite, `screen` is finished pixels and does
       * not, and `comps` is the exact number of pieces the picture is allowed
       * to be in. Every one of them was measured off the drawing rather than
       * chosen, and none of them is round.
       *
       * The icicles and the flame are the room acting on the character, so
       * they are drawn by the body and grow with it. The ZZZ is a symbol and
       * is not part of the body, so it is drawn beside it at a fixed size —
       * see the note in sprites/player.js.
       */
      { n: 'sleep', s: { state: 'idle', tick: 5, idle: 1319 }, a: { screen: { above: 21, front: 12 }, comps: 4 } },
      /* Two samples of the icicle breath: the first one still on his lip, and
       * the frame where all three are clear of him and as far out as they go. */
      { n: 'frost 1', s: { state: 'idle', tick: 5, idle: 1244, theme: 'ice' }, a: { px: { front: 2 } } },
      { n: 'frost 3', s: { state: 'idle', tick: 5, idle: 1263, theme: 'ice' }, a: { px: { front: 11 }, comps: 4 } },
      { n: 'alight', s: { state: 'idle', tick: 5, idle: 1218, theme: 'desert' }, a: { px: { above: 2 } } },
      /* The panic beats the body a pixel sideways as well as the arms, so the
       * back arm reaches one further out than a hanging one — the same pixel
       * the shiver is already allowed on the ice, for the same reason. */
      { n: 'panic', s: { state: 'idle', tick: 5, idle: 1260, theme: 'desert' }, a: { px: { above: 4, back: 1 } } },
      { n: 'smoke', s: { state: 'idle', tick: 5, idle: 1355, theme: 'desert' }, a: { px: { above: 4 } } },
      /*
       * KUOLEMA, kolme näytettä — jäykkä, paisunut, tyhjä kuori. Ne ovat
       * tässä listassa samasta syystä kuin maahanisku: kuolema on ainoa muu
       * asento joka piirretään kokonaan omalla piirrolla, ja sen keskimmäinen
       * vaihe on ainoa koko pelissä joka **kasvaa laatikkonsa ulkopuolelle**.
       *
       * Väljyys on ilmoitettu eikä sallittu: pullistuma on `DEATH_BULGE` (3)
       * pikseliä kumpaankin sivuun isolla keholla, ja kädet työntyvät sen
       * mukana — eli neljä. Ylöspäin se ei mene ja **alaspäin ei lainkaan**,
       * koska pullistuma kasvaa vyötäröltä ylös ja jalat ovat se osa joka on
       * jäykkänä maata kohti. `below` pysyy siis nollassa kaikissa kolmessa,
       * ja juuri se on tässä se rivi jota kannattaa katsoa.
       */
      { n: 'dead stiff', s: { state: 'jump', dead: true, deadT: 6 } },
      { n: 'dead swell', s: { state: 'jump', dead: true, deadT: 40 }, a: { px: { front: 4, back: 4 } } },
      { n: 'dead husk', s: { state: 'jump', dead: true, deadT: 60 } },
    ];

    const leaks = [];
    const pieces = [];
    const hashes = {};
    /* Kuinka monta pikseliä laatikon ylälaidasta alaspäin piirros alkaa. Yksi
     * luku per asento, ja se on koko kyykyn mitta: kyykky *on* se että pää on
     * alempana. */
    const tops = {};
    for (const level of [0, 1, 2, 3, 4, 5]) {
      for (const type of [null, 'shroom', 'flower', 'leaf', 'pop']) {
        for (const p of poses) {
          for (const facing of [1, -1]) {
            const s = {
              type, level, facing, frame: 0, running: false, wag: 1.1,
              ducking: false, theme: 'grass', tick: 5, idle: 0, ...p.s,
            };
            const box = (s.ducking ? PLAYER_DUCK_SIZES : PLAYER_SIZES)[level];
            g.clearRect(0, 0, W, H);
            drawPlayer(g, OX, OY, s);
            const d = g.getImageData(0, 0, W, H).data;
            const art = new Uint8Array(W * H);
            let x0 = 1e9; let y0 = 1e9; let x1 = -1; let y1 = -1;
            let hash = 0;
            for (let y = 0; y < H; y++) {
              for (let x = 0; x < W; x++) {
                const i = (y * W + x) * 4;
                hash = (hash * 33 + d[i] * 7 + d[i + 1] * 3 + d[i + 3]) | 0;
                if (d[i + 3] !== 255) continue;
                if (!ART.has(`${d[i]},${d[i + 1]},${d[i + 2]}`)) continue;
                art[y * W + x] = 1;
                if (x < x0) x0 = x;
                if (y < y0) y0 = y;
                if (x > x1) x1 = x;
                if (y > y1) y1 = y;
              }
            }
            if (facing === 1) {
              hashes[`${level}|${type}|${p.n}`] = hash;
              tops[`${level}|${type}|${p.n}`] = y0 - OY;
            }
            const where = `L${level} ${type || 'none'} ${p.n} f${facing}`;
            if (x1 < 0) { leaks.push(`${where}: nothing drawn at all`); continue; }

            /* Named allowances, in template pixels. */
            const sx = level < 2 ? 1 : box.w / 14;
            const sy = level < 2 ? 1 : box.h / (s.ducking ? 16 : 26);
            const ice = s.theme === 'ice';
            const sweaty = s.theme === 'desert' || s.theme === 'factory';
            const up = (n, k) => (n <= 0 ? 0 : Math.ceil(n * k));
            const px = (p.a && p.a.px) || {};
            const scr = (p.a && p.a.screen) || {};
            const allow = {
              above: up((type === 'leaf' ? 2 : 0) + (px.above || 0), sy) + (scr.above || 0),
              below: 0,                                        // the floor line is the floor line
              front: up((sweaty ? 2 : 1) + (ice ? 1 : 0) + (px.front || 0), sx) + (scr.front || 0),
              back: up((type === 'leaf' ? 9 : 1) + (ice ? 1 : 0) + (px.back || 0), sx) + (scr.back || 0),
            };
            const over = {
              above: OY - y0,
              below: y1 - (OY + box.h - 1),
              [facing > 0 ? 'front' : 'back']: x1 - (OX + box.w - 1),
              [facing > 0 ? 'back' : 'front']: OX - x0,
            };
            for (const k of ['above', 'below', 'front', 'back']) {
              if (over[k] > allow[k]) leaks.push(`${where}: ${over[k]}px ${k} of the box, ${allow[k]} allowed`);
            }

            /* One character, not a pile of parts. */
            let comps = 0;
            const seen = new Uint8Array(W * H);
            const stack = [];
            for (let q0 = 0; q0 < W * H; q0++) {
              if (!art[q0] || seen[q0]) continue;
              comps++;
              stack.push(q0);
              seen[q0] = 1;
              while (stack.length) {
                const q = stack.pop();
                const qx = q % W;
                if (qx > 0 && art[q - 1] && !seen[q - 1]) { seen[q - 1] = 1; stack.push(q - 1); }
                if (qx < W - 1 && art[q + 1] && !seen[q + 1]) { seen[q + 1] = 1; stack.push(q + 1); }
                if (q >= W && art[q - W] && !seen[q - W]) { seen[q - W] = 1; stack.push(q - W); }
                if (q < W * (H - 1) && art[q + W] && !seen[q + W]) { seen[q + W] = 1; stack.push(q + W); }
              }
            }
            const wantComps = (p.a && p.a.comps) || 1;
            if (comps !== wantComps) pieces.push(`${where}: ${comps} pieces, ${wantComps} named`);
          }
        }
      }
    }
    expect('every pose at every power level stays inside its own box',
      leaks.length === 0, `${leaks.length} poses leak: ${leaks.slice(0, 4).join('; ')}`);
    expect('the player is one piece in every pose at every power level',
      pieces.length === 0, `${pieces.length} broken: ${pieces.slice(0, 4).join('; ')}`);

    /*
     * MAAHANISKUN KYYKKY ON KYYKKY, JA SE MITATAAN PÄÄN PAIKASTA.
     *
     * Asento tuli siksi että liikkeen hinta — ne 12 + n framea joina pelaaja ei
     * ohjaa mitään — oli koko ajan olemassa mutta näkymätön: ilmassa `state()`
     * sanoi `jump` ja maassa `idle`, eli lataus näytti leijumiselta ja
     * laskeutumisen jälkeinen jäykkyys siltä että hahmo seisoo tumput suorina.
     * "Piirsimme asennon" ei ole tarkistettavissa; **"pää on alempana"** on.
     *
     * Kolme lukua ja kaksi väitettä: kyykyssä pää on alempana kuin seistessä,
     * ja nousussa se on matkalla takaisin ylös muttei vielä perillä. Jokaisella
     * voimatasolla ja jokaisella tehostuksella, koska piirros skaalataan
     * tasoille 2–5 samasta 26 rivin pohjasta eikä yksikään niistä ole erikseen
     * piirretty — ja juuri siksi yksikään niistä ei myöskään ole erikseen
     * katsottu.
     */
    {
      const flat = [];
      for (const level of [0, 1, 2, 3, 4, 5]) {
        for (const t of [null, 'shroom', 'flower', 'leaf', 'pop']) {
          const key = (n) => tops[`${level}|${t}|${n}`];
          const stand = key('idle');
          const lag = key('pound lag');
          const rise = key('pound rise');
          if (!(lag > stand && rise < lag && rise >= stand)) {
            flat.push(`L${level} ${t || 'none'}: seisten ${stand}, kyykyssä ${lag}, noustessa ${rise}`);
          }
        }
      }
      expect('maahaniskun kyykky on kyykky: pää laskee ja nousee takaisin',
        flat.length === 0,
        flat.length ? flat.slice(0, 4).join('; ')
          : `L1 none seisten ${tops['1|null|idle']}, kyykyssä ${tops['1|null|pound lag']}`
            + `, noustessa ${tops['1|null|pound rise']}`
            + ` — L5 none ${tops['5|null|idle']}/${tops['5|null|pound lag']}`
            + `/${tops['5|null|pound rise']}`);
    }

    /* The paukkupapu landed as the fourth power type on the day this audit was
     * written, and a new type that inherits another one's drawing looks exactly
     * like a working feature until somebody collects it. */
    const same = [];
    for (const level of [0, 1, 2, 3, 4, 5]) {
      for (const p of poses) {
        for (const t of [null, 'shroom', 'flower', 'leaf']) {
          if (hashes[`${level}|pop|${p.n}`] === hashes[`${level}|${t}|${p.n}`]) {
            same.push(`L${level} ${p.n} == ${t || 'none'}`);
          }
        }
      }
    }
    expect('the paukkupapu has a body of its own at every level and pose',
      same.length === 0, same.slice(0, 4).join('; '));
  }

  /* ------------------------ hahmon oma ulkonäkö ------------------------- */
  /*
   * Two measurements that stand for a decision rather than for a bug: the hero
   * is this game's own character and not the genre's most-copied costume. Both
   * are shape and colour, not naming, because a sprite cannot be checked by
   * asking it what it is called.
   *
   *  1. **The head is a head, not a peaked cap.** A brim is the one thing on a
   *     platform hero that is wider than the skull it sits on, and the old
   *     drawing made it exactly as wide as the whole character: 12 px of brim
   *     across a 14 px body, 10 across a 12 px one, with the crown only 9 and 8.
   *     The rule is therefore about *width*, not about colour — a red cap
   *     repainted green is still a cap. The head, measured on the rows just
   *     below the top of the box, has to be at least four pixels narrower than
   *     the body: room for a skull and hair, no room for a brim.
   *
   *     The top row of the box is left out of the measurement on purpose. That
   *     is where the kaasulehti's fronds sit, and they are a named exception in
   *     the audit above for the same reason they are one here: they are not the
   *     head, they are what the power-up put on it.
   *
   *  2. **The five power looks are five looks.** `POWER_LOOKS` used to change
   *     the cap and nothing else between "no power" and the first mushroom, so
   *     two of the five tiers were the same drawing with a hat repainted —
   *     about a quarter of the body. A tier a player cannot name at a glance is
   *     not a tier, and at 12x16 a quarter of the body is a detail. Measured as
   *     the share of the character's own pixels that actually change between
   *     every pair of tiers, at the smallest size and the largest, since those
   *     are the two that could disagree.
   *
   * Both numbers are reported so that a future palette can be argued with in
   * numbers: they are the floor, not the target.
   */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const { PLAYER_SIZES, drawPlayer } = sprites;
    const W = 80; const H = 80; const OX = 26; const OY = 14;
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    const TYPES = [null, 'shroom', 'flower', 'leaf', 'pop'];
    /* Artwork is told apart from its own outline the same way the audit above
     * does it: the outline only ever reaches full alpha where all four offsets
     * stack, and there it lands on 16,16,23 — one blue short of C.ink. */
    const shot = (type, level) => {
      g.clearRect(0, 0, W, H);
      drawPlayer(g, OX, OY, {
        type, level, facing: 1, frame: 0, state: 'idle', running: false,
        ducking: false, theme: 'grass', tick: 0, idle: 0, wag: 0,
      });
      const d = g.getImageData(0, 0, W, H).data;
      const art = new Uint8Array(W * H);
      for (let i = 0; i < W * H; i++) {
        const q = i * 4;
        if (d[q + 3] !== 255) continue;
        if (d[q] === 16 && d[q + 1] === 16 && d[q + 2] === 23) continue;
        art[i] = 1;
      }
      return { art, d };
    };

    const heads = [];
    for (const level of [0, 1]) {
      const box = PLAYER_SIZES[level];
      let widest = 0;
      for (const type of TYPES) {
        const { art } = shot(type, level);
        for (let row = 1; row <= 5; row++) {
          let lo = -1; let hi = -1;
          /* Only the box and the one pixel of shoulder it has always been
           * allowed on each side. Anything further out is not the head: the
           * kaasulehti's hose swings back eleven pixels and crosses these rows
           * on its way up, and it would otherwise be measured as a hat. What
           * leaves the box is the audit above's question, not this one's. */
          for (let x = Math.max(0, OX - 1); x <= OX + box.w; x++) {
            if (!art[(OY + row) * W + x]) continue;
            if (lo < 0) lo = x;
            hi = x;
          }
          if (hi >= 0) widest = Math.max(widest, hi - lo + 1);
        }
      }
      heads.push({ level, widest, allow: box.w - 4 });
    }
    expect('the hero has a head and not a peaked cap',
      heads.every((h) => h.widest <= h.allow),
      heads.map((h) => `taso ${h.level}: pää ${h.widest}px, laatikko `
        + `${PLAYER_SIZES[h.level].w}px, sallittu ${h.allow}px`).join(', '));

    /* Every pair of tiers, both ends of the size range. The denominator is the
     * character's own pixels rather than the canvas, so the number means "how
     * much of him changed" and does not quietly improve when he grows. */
    const shares = [];
    for (const level of [0, 5]) {
      const shots = TYPES.map((t) => shot(t, level));
      let worst = 100;
      let pair = '';
      for (let a = 0; a < TYPES.length; a++) {
        for (let b = a + 1; b < TYPES.length; b++) {
          let own = 0;
          let changed = 0;
          for (let i = 0; i < W * H; i++) {
            if (!shots[a].art[i] && !shots[b].art[i]) continue;
            own++;
            const q = i * 4;
            for (let k = 0; k < 3; k++) {
              if (shots[a].d[q + k] !== shots[b].d[q + k]) { changed++; break; }
            }
          }
          const share = Math.round((changed / own) * 100);
          if (share < worst) {
            worst = share;
            pair = `${TYPES[a] || 'none'}/${TYPES[b] || 'none'}`;
          }
        }
      }
      shares.push({ level, worst, pair });
    }
    expect('the five power looks are five looks and not one with a hat repainted',
      shares.every((s) => s.worst >= 45),
      shares.map((s) => `taso ${s.level}: lähimmät ${s.pair} ${s.worst}%`).join(', ')
      + ', vaadittu 45%');
  }

  /* ------------------ vihollisten laatikot ja hengitys ------------------- */
  /*
   * The audit above, pointed at the things that walk at him. Same method —
   * measure the picture, not the numbers that made it — and it found the same
   * two kinds of fault.
   *
   *  1. `Walker` is declared 16x16 and drew x+1..+15, y+3..+16, so a three
   *     pixel band above its head hurt without ever being visible (DESIGN.md
   *     §7). Fixed by growing the art into the box, never by shrinking the box
   *     onto the art: the walker is the enemy every other one is a variation
   *     of, so its box is the size of a stomp everywhere in the game, and
   *     trimming it would quietly make every walker harder to land on.
   *  2. Nothing that walks had any vertical motion at all. Everything alive
   *     breathes now — one pixel — and two neighbours must not breathe in step.
   *
   * `over` is art outside the box: visible, harmless, a wing or a spine.
   * `under` is box with no art on it: invisible, harmful, and the worse of the
   * two. Both are named per enemy rather than tolerated as slack, because
   * slack is where the next one hides — every non-zero number below is a
   * finding somebody may still decide to fix.
   */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const W = 88; const H = 72; const OX = 28; const OY = 24;
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    /* Every colour an enemy body is painted in. Trailing gas and the stink
     * cloud's shadow are deliberately not on the list: they are translucent, so
     * they only reach full alpha where they land on the stacked outline, and a
     * puff of gas behind an enemy is not part of its body. */
    const ART = new Set([
      '248,248,248', '16,16,24',
      '200,200,216', '90,80,64',
      '232,224,200', '168,152,120', '216,168,96', '156,106,40',
      '255,208,72',
      /* Neljä lajia, jotka menivät kontrastikynnyksen alle ja maalattiin
       * uudestaan 10.8.2026. Vanhat sävyt lähtivät tästä listasta samalla,
       * koska "jokainen väri jolla vihollisen runko on maalattu" on väite ja
       * väri jota mikään ei enää maalaa tekee siitä epätoden — ja koska juuri
       * tämä lista on se joka päättää mikä on ruumista ja mikä ei.
       *
       * piikkiukko: kylläinen violetti harmaanvioletin tilalle */
      '240,40,200', '168,12,144', '120,4,108',
      // ruskea pilvi: kellertävä myrkkyruskea maanruskean tilalle
      '180,164,16', '108,96,4',
      // ummetuskorkki: kumitulpan runko, ja korkki yhä sen päälaella
      '48,96,200', '28,56,120', '16,28,72',
      // papuparooni: luumu ruskean tilalle, hattu mukana
      '156,16,96', '88,8,52', '60,8,36', '108,16,68', '240,184,144',
      // kurnuttaja: suo-turkoosi, joka ei ole kenenkään muun väri tässä pelissä
      '30,90,76', '52,140,110', '108,200,160', '18,60,52',
      // pöhö: suolenvärinen kaasupussi, joka korvasi ruskean kävelijän
      '224,120,120', '248,168,168', '168,60,76', '112,28,48',
      // pönttö: teräksinen painesäiliö ja se kalpea toukka joka asuu siinä
      '32,80,192', '92,144,232', '16,48,108', '168,200,240',
      '216,224,240', '140,156,192',
      // nielu: märkä, lähes musta kurkku ja sen punainen sisus
      '24,16,48', '52,44,104', '104,88,176', '32,24,64', '120,16,60', '200,40,108',
      /*
       * Neljä uutta lajia, 16.8.2026. Terästä ei ole tässä listassa kahdesti:
       * törähdystorvi ja sen ammus on maalattu **pöntön omilla sinisillä**,
       * koska ne ovat samaa tehdasta — se on piirroksen väite ja tämä lista on
       * paikka jossa se väite näkyy koodina.
       */
      // torvi ja törähdys: messinkiä läpi koko esineen, ja se kaasu joka niistä tulee
      '255,232,160', '255,200,74', '200,144,24', '140,90,16',
      '168,224,74', '92,156,40', '244,255,208',
      // paarma: happamanvihreä raidoitus
      '200,232,56', '92,108,16',
      // yökki: kuuma oranssi, jota kukaan muu tässä pelissä ei käytä
      '224,88,32', '122,36,8', '248,160,80', '168,28,28',
      // karvapallo: vaalennettu takku, ja se kirkas kohta joka näyttää kierteen
      '160,104,48', '216,168,96', '90,50,16', '248,224,168',
      // paukkupöhö: paineen punainen, ja valkoiseksi kirkastuva sytytys
      '200,24,32', '240,64,48', '140,12,24', '255,232,192',
      /* Kävelijän kaksi muuta ihosävyä (17.8.2026). Lista on tarkoituksella
       * käsin kirjoitettu rekisteri piirroksen omasta paletista — juuri siksi
       * se huomasi uudet sävyt heti ja ilmoitti kävelijän hajonneeksi kahteen
       * osaan: valkolistan ulkopuolinen väri ei ole tälle portille kuvaa
       * lainkaan. Ks. `WALKER_TONES`. */
      // syvä ruusu
      '200,96,120', '232,140,160', '152,48,72', '96,20,40',
      // ruoste
      '208,112,88', '240,160,128', '160,64,40', '104,32,20',
    ]);
    const shot = (paint) => {
      g.clearRect(0, 0, W, H);
      paint();
      const d = g.getImageData(0, 0, W, H).data;
      const art = new Uint8Array(W * H);
      let x0 = 1e9; let y0 = 1e9; let x1 = -1; let y1 = -1;
      let rows = 0; let n = 0;
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          const i = (y * W + x) * 4;
          if (d[i + 3] !== 255) continue;
          if (!ART.has(`${d[i]},${d[i + 1]},${d[i + 2]}`)) continue;
          art[y * W + x] = 1;
          if (x < x0) x0 = x;
          if (y < y0) y0 = y;
          if (x > x1) x1 = x;
          if (y > y1) y1 = y;
          rows += y;
          n++;
        }
      }
      /* One body, not a pile of parts — the same flood fill as the player's
       * audit, and here for the same reason: his breath used to lift the shirt
       * off the trousers, and a breath that pins the top of a sprite while it
       * moves the middle is exactly the shape of mistake that does it again. */
      let pieces = 0;
      const seen2 = new Uint8Array(W * H);
      const stack = [];
      for (let q0 = 0; q0 < W * H; q0++) {
        if (!art[q0] || seen2[q0]) continue;
        pieces++;
        stack.push(q0);
        seen2[q0] = 1;
        while (stack.length) {
          const q = stack.pop();
          const qx = q % W;
          if (qx > 0 && art[q - 1] && !seen2[q - 1]) { seen2[q - 1] = 1; stack.push(q - 1); }
          if (qx < W - 1 && art[q + 1] && !seen2[q + 1]) { seen2[q + 1] = 1; stack.push(q + 1); }
          if (q >= W && art[q - W] && !seen2[q - W]) { seen2[q - W] = 1; stack.push(q - W); }
          if (q < W * (H - 1) && art[q + W] && !seen2[q + W]) { seen2[q + W] = 1; stack.push(q + W); }
        }
      }
      // `lift` is the art's vertical centre of mass in hundredths of a pixel:
      // it moves whenever any part of the body moves up or down, and it does
      // not care where along the ground the sprite was drawn.
      return { x0, y0, x1, y1, pieces, lift: n ? Math.round((rows / n) * 100) : -1 };
    };

    const none = { over: {}, under: {} };
    /*
     * `stomp` is the rule the entity actually enforces (`Enemy.stompable`), and
     * it is on this table rather than read out of the classes on purpose: the
     * point of the crown audit below is to compare the *picture* against the
     * rule, so the rule has to arrive from somewhere the picture cannot reach.
     * `pit` marks the one enemy the player never arrives above.
     */
    const subjects = [
      { n: 'walker', box: [0, 0, 16, 16], breathes: true, clock: 8, stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawWalker(g, ox, OY, Math.floor(t / 8), f, false) },
      // A flattened walker is scenery for twenty-two frames and cannot hurt
      // anybody, so it is not held to the box it no longer fills.
      { n: 'flyer', box: [0, 0, 16, 16], stomp: true,
        over: { left: 4, right: 4 }, under: {},
        paint: (ox, t, f) => sprites.drawFlyer(g, ox, OY, t, f) },
      { n: 'shell walking', box: [1, 0, 14, 24], breathes: true, clock: 1, stomp: true,
        over: {}, under: { top: 1 },
        paint: (ox, t, f) => sprites.drawShell(g, ox, OY, t, f, 'walk') },
      { n: 'shell', box: [1, 0, 14, 14], stomp: true,
        over: { left: 1, right: 1 }, under: { top: 2 },
        paint: (ox, t, f) => sprites.drawShell(g, ox, OY, t, f, 'shell') },
      /* The kicked one. It was never in this audit, which is a gap and not a
       * decision: a shell that slides through a room is the one drawing in the
       * game the player is asked to read while it is moving fastest. */
      { n: 'shell sliding', box: [1, 0, 14, 14], stomp: true,
        over: { left: 1, right: 1 }, under: { top: 2 },
        paint: (ox, t, f) => sprites.drawShell(g, ox, OY, t, f, 'sliding') },
      { n: 'spikeguy', box: [0, 0, 16, 16], breathes: true, clock: 2, stomp: false,
        over: { top: 2 }, under: { left: 1, right: 1 },
        paint: (ox, t, f) => sprites.drawSpikeGuy(g, ox, OY, Math.floor(t / 2), f) },
      { n: 'plant', box: [0, 0, 16, 32], breathes: true, clock: 1, stomp: false,
        over: {}, under: { left: 1, right: 1 }, facings: [1],
        paint: (ox, t) => sprites.drawPlant(g, ox, OY, t) },
      { n: 'corkguy', box: [1, 0, 14, 16], breathes: true, clock: 1, stomp: true,
        over: {}, under: { top: 2, left: 1, right: 1 },
        paint: (ox, t, f) => sprites.drawCorkGuy(g, ox, OY, t, f) },
      { n: 'stink cloud', box: [0, 0, 20, 14], stomp: true,
        over: {}, under: { top: 1, bottom: 1, left: 1, right: 1 },
        paint: (ox, t, f) => sprites.drawStinkCloud(g, ox, OY, t, f, true) },
      { n: 'bean baron', box: [0, 0, 18, 26], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawBeanBaron(g, ox, OY, Math.floor(t / 7), f, 0, false) },
      /* Kurnuttaja. Silmät ovat laatikon katto ja jalat sen lattia, ja hengitys
       * liikkuu niiden välissä — sama rakenne kuin kävelijällä, ja samasta
       * syystä: se on ainoa tapa täyttää laatikko jokaisella framella. */
      { n: 'kurnuttaja', box: [0, 0, 16, 16], breathes: true, clock: 8,
        stomp: false, pit: true, ...none,
        paint: (ox, t, f) => sprites.drawKurnuttaja(g, ox, OY, t, f) },
      /*
       * NELJÄ UUTTA, JA NE OVAT TÄSSÄ LISTASSA SAMALLA RIVILLÄ KUIN MUUTKIN.
       *
       * Se on koko pointti: uusi vihollinen ei tule peliin sillä että se toimii
       * vaan sillä että se kestää samat mitat kuin ne jotka ovat jo siellä.
       * Kolme näistä on tallattavia ja niiden lakipinnan on siis oltava leveä;
       * karvapallo ei ole, ja sen on kannettava piikkejä. Kumpaakaan ei
       * väitetä tässä — ne mitataan alempana samasta piirroksesta.
       *
       * Latautuva torvi ja yökkäävä yökki piirretään myös ladatussa asennossaan
       * (`charge`/`heave` 1), koska varoitusasento on se frame jolla piirros voi
       * kasvaa ulos laatikostaan huomaamatta: se on se muoto jota kukaan ei
       * katso kuin sen puolen sekunnin ajan.
       */
      { n: 'torvi', box: [0, 0, 16, 16], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawTorvi(g, ox, OY, t, f, 0) },
      { n: 'torvi ladattu', box: [0, 0, 16, 16], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawTorvi(g, ox, OY, t, f, 1) },
      { n: 'törähdys', box: [0, 0, 16, 12], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawTorahdys(g, ox, OY, t, f) },
      { n: 'paarma', box: [0, 0, 16, 12], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawPaarma(g, ox, OY, t, f, 0) },
      { n: 'paarma tähtää', box: [0, 0, 16, 12], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawPaarma(g, ox, OY, t, f, 1) },
      { n: 'yökki', box: [0, 0, 16, 16], breathes: true, clock: 8, stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawYokki(g, ox, OY, Math.floor(t / 8), f, 0) },
      { n: 'yökki yökkää', box: [0, 0, 16, 16], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawYokki(g, ox, OY, Math.floor(t / 8), f, 1) },
      /* Tupsut nousevat rivin laatikon yli, ja se on sama sallittu ylitys kuin
       * piikkiukolla: piikki on taidetta joka ei satuta, ja juuri siksi se saa
       * olla laatikon ulkopuolella. */
      { n: 'karvapallo', box: [0, 0, 12, 12], stomp: false, ...none,
        paint: (ox, t, f) => sprites.drawKarvapallo(g, ox, OY, t, f) },
      { n: 'paukkupöhö', box: [0, 0, 16, 16], breathes: true, clock: 8, stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawPaukkupoho(g, ox, OY, Math.floor(t / 8), f, 0) },
      { n: 'paukkupöhö sytytetty', box: [0, 0, 16, 16], stomp: true, ...none,
        paint: (ox, t, f) => sprites.drawPaukkupoho(g, ox, OY, Math.floor(t / 8), f, 0.9) },
    ];

    // One line per distinct fault, not one per frame: 176 frames of the same
    // three pixel band is one bug, and a list of 700 of them hides the next.
    const seen = new Map();
    const disagree = [];
    const note = (what, t) => {
      if (!seen.has(what)) { seen.set(what, t); disagree.push(what); }
    };
    const worst = [];
    for (const s of subjects) {
      const [dx, dy, bw, bh] = s.box;
      const bx0 = OX + dx; const by0 = OY + dy;
      const bx1 = bx0 + bw - 1; const by1 = by0 + bh - 1;
      let gap = 0;
      for (const facing of (s.facings || [1, -1])) {
        for (let t = 0; t < 176; t += 2) {
          const m = shot(() => s.paint(OX, t, facing));
          if (m.x1 < 0) { note(`${s.n} f${facing}: nothing drawn`, t); continue; }
          if (m.pieces !== 1) note(`${s.n} f${facing}: came apart into ${m.pieces} pieces`, t);
          const over = { top: by0 - m.y0, bottom: m.y1 - by1, left: bx0 - m.x0, right: m.x1 - bx1 };
          const under = { top: m.y0 - by0, bottom: by1 - m.y1, left: m.x0 - bx0, right: bx1 - m.x1 };
          for (const k of ['top', 'bottom', 'left', 'right']) {
            if (under[k] > gap) gap = under[k];
            if (over[k] > (s.over[k] || 0)) {
              note(`${s.n} f${facing}: ${over[k]}px of art ${k} of the box, ${s.over[k] || 0} allowed`, t);
            }
            if (under[k] > (s.under[k] || 0)) {
              note(`${s.n} f${facing}: ${under[k]}px of box with no art at the ${k}, ${s.under[k] || 0} allowed`, t);
            }
          }
        }
      }
      worst.push(`${s.n} ${gap}`);
    }
    // The measurement, not just the verdict: the widest band of box that no
    // pixel of the enemy ever covers. Zero is what the walker was grown for.
    expect('every enemy\'s drawing agrees with the box it hurts you with',
      disagree.length === 0,
      disagree.length ? disagree.join('; ') : `laatikossa kattamatta: ${worst.join(', ')}`);

    /*
     * One shared breath, offset per enemy — the trick the world map already
     * uses on its tiles. Without the offset a row of walkers pulses as one
     * body and reads as a rendering fault rather than as life. Measured three
     * ways: it moves at all, a neighbour a tile away is out of step with it,
     * and one pixel of walking does not jump its phase.
     *
     * Not on the list, because they already have vertical motion of their own
     * and a second one would fight it: the stink cloud (bobs on a sine), the
     * flyer (bounces off the floor), the bean baron (hops), the angry sun and
     * the moon (both hover), and anything sealed in a bubble.
     */
    const flat = [];
    const lockstep = [];
    const measured = [];
    const PERIOD = sprites.BREATH_PERIOD;
    const flipOf = (ser) => {
      for (let i = 1; i < ser.length; i++) if (ser[i] !== ser[0]) return i;
      return -1;
    };
    for (const s of subjects.filter((q) => q.breathes)) {
      const series = (ox) => {
        const out = [];
        for (let t = 0; t < PERIOD + 16; t++) out.push(shot(() => s.paint(ox, t, 1)).lift);
        return out;
      };
      // A whole tile's worth of standing positions, so whatever the phase is
      // derived from, this walks across at least one of its boundaries.
      const steps = [0, 4, 8, 12, 16].map((d) => series(OX + d));
      const here = steps[0];
      let apart = 0;
      for (let i = 0; i < here.length; i++) if (here[i] !== steps[4][i]) apart++;
      // How far the breath's phase moved for four pixels of ground. It has to
      // move — that is what keeps neighbours apart — but it may only ever
      // drift, never snap, or an enemy would change its breathing the moment
      // it stepped over a tile boundary. The slack is one step of the sprite's
      // own animation clock, which for the walker is eight frames because that
      // is the only clock it is given.
      let jumped = 0;
      for (let i = 1; i < steps.length; i++) {
        const a = flipOf(steps[i - 1]); const b = flipOf(steps[i]);
        if (a < 0 || b < 0) continue;
        const d = Math.abs(a - b);
        jumped = Math.max(jumped, Math.min(d, PERIOD - d));
      }
      const slack = 4 + s.clock;
      if (new Set(here).size < 2) flat.push(`${s.n} never moves`);
      if (apart < 3) lockstep.push(`${s.n}: the next tile along differs on ${apart} frames`);
      if (jumped > slack) lockstep.push(`${s.n}: four pixels of travel snapped the breath ${jumped} frames, ${slack} allowed`);
      measured.push(`${s.n} ${apart}/${jumped}`);
    }
    expect('everything alive breathes, and neighbours are not in step',
      flat.length === 0 && lockstep.length === 0,
      [...flat, ...lockstep, `naapurin ero / 4px:n siirtymä: ${measured.join(', ')}`].join('; '));

    /* ------------- ylälaita kertoo saako päälle hypätä ------------------- */
    /*
     * Stomping is the one verb this game teaches in its first screen, and the
     * whole verb rests on a yes/no the player has to read *before* the jump, at
     * a distance, in a fraction of a second. There is exactly one place in a
     * sprite where that answer can live: the top edge, because that is the part
     * a falling player is aimed at.
     *
     * So the claim is not "the art looks different". It is that **the top edges
     * of the two populations do not overlap** — that no enemy you must walk
     * around offers a wider flat landing than the narrowest one you are meant to
     * jump on, with a band of at least four pixels between them where nothing
     * lives. That is a number, it is measured off the finished pixels, and it
     * cannot be satisfied by choosing a nicer colour: colour has to be learned
     * first, and a row of points does not (the same argument `drawSpines`
     * already makes for the piikkiukko, now enforced instead of asserted).
     *
     * **What the red said, and it is worth reading twice.** Measured on the old
     * art, the widest flat landing surface in the entire enemy roster belonged
     * to the *plant* — 14 px of unbroken flat crown out of a 16 px box, wider
     * than the walker's 10, tied with the shell that you are supposed to jump
     * on — and the plant is the one enemy in the game that has never been
     * stompable. The picture said "land here" in the largest type available and
     * the rule said "this costs you a power level". The other unstompable, the
     * piikkiukko, measured 1. So the populations were not merely close, they
     * were inverted, and the game taught a lie in 1-2 to every player who had
     * just been taught the truth in 1-1.
     *
     * `landing` is the widest run of columns whose topmost painted pixel is
     * within one pixel of the sprite's own highest, over the box's columns only
     * — a wing hanging off the side is not somewhere you can land. `points` is
     * how many separate such runs there are, which is what tells a row of teeth
     * apart from a plateau with a notch in it.
     */
    const crown = (paint, box) => {
      const [dx, , bw] = box;
      g.clearRect(0, 0, W, H);
      paint();
      const d = g.getImageData(0, 0, W, H).data;
      const top = new Int32Array(bw).fill(1e9);
      for (let y = 0; y < H; y++) {
        for (let i = 0; i < bw; i++) {
          const q = ((y * W) + OX + dx + i) * 4;
          if (d[q + 3] !== 255) continue;
          if (!ART.has(`${d[q]},${d[q + 1]},${d[q + 2]}`)) continue;
          if (y < top[i]) top[i] = y;
        }
      }
      let min = 1e9;
      for (const v of top) if (v < min) min = v;
      let landing = 0; let run = 0; let points = 0; let was = false;
      for (let i = 0; i < bw; i++) {
        const hi = top[i] <= min + 1;
        if (hi) { run++; if (!was) points++; if (run > landing) landing = run; } else { run = 0; }
        was = hi;
      }
      return { landing, points };
    };
    {
      const read = [];
      for (const s of subjects) {
        if (s.stomp === undefined) continue;
        let landing = 1e9; let points = 1e9;
        for (const facing of (s.facings || [1, -1])) {
          for (let t = 0; t < 176; t += 2) {
            const m = crown(() => s.paint(OX, t, facing), s.box);
            landing = Math.min(landing, m.landing);
            points = Math.min(points, m.points);
          }
        }
        read.push({ ...s, landing, points });
      }
      /* The kurnuttaja is the one exemption and it is named rather than
       * tolerated. It is not stompable either, but it spends its life at the
       * bottom of a pit: the player never arrives above it by choice, and the
       * warning it owes is the column of bubbles `drawCroak` puts in the air
       * over the hole — a signal in a place, not a shape on a crown. Its own
       * number is printed anyway, because an exemption nobody can see the size
       * of is just a hole in a test. Measured 6, which is inside the band this
       * assertion keeps empty, and somebody may yet decide to narrow its eye
       * turrets. */
      const land = read.filter((s) => !s.pit);
      const yes = land.filter((s) => s.stomp);
      const no = land.filter((s) => !s.stomp);
      const softest = yes.reduce((m, s) => (s.landing < m.landing ? s : m), yes[0]);
      const flattest = no.reduce((m, s) => (s.landing > m.landing ? s : m), no[0]);
      const blunt = no.filter((s) => s.points < 3);
      const pit = read.find((s) => s.pit);
      expect('vihollisen ylälaita kertoo saako sen päälle hypätä',
        softest.landing >= flattest.landing + 4 && blunt.length === 0,
        `tallattavista kapein ${softest.n} ${softest.landing} px, `
        + `tallaamattomista levein ${flattest.n} ${flattest.landing} px`
        + (blunt.length ? ` — piikittömät: ${blunt.map((s) => `${s.n} ${s.points}`).join(', ')}` : '')
        + `; kaikki: ${read.map((s) => `${s.n} ${s.landing}/${s.points}`).join(', ')}`
        + (pit ? ` (${pit.n} kuopan pohjalla, ei portissa)` : ''));
    }

    /* ------------ vihollinen erottuu siitä maasta jolla se seisoo -------- */
    /*
     * The tiles have had a per-theme contrast gate for a while and the enemies
     * have not, which is the wrong way round: a brick that melts into the
     * ground costs you a secret, an enemy that melts into the ground costs you
     * a power level. Eight themes and one sprite each means eight chances for
     * a species to disappear, and the one that disappears will be the one on
     * the world nobody replayed.
     *
     * Same measure as the tile gate, deliberately — mean channel difference out
     * of a full 255, crude but unbreakable, and worth more as *the same number*
     * than as a better one nobody can compare against anything. Two differences,
     * both forced by what is being measured:
     *
     *   - The outline is left out (`16,16,24`). Every sprite in the game wears
     *     the same one, so it can only ever hide the thing being asked about,
     *     which is whether the *body* has a colour of its own.
     *   - The threshold is not typed in. It is the desert's own ground/brick
     *     gap, computed here from the same tiles — the weakest pair the game
     *     already ships and knowingly tolerates. "At least as separate as the
     *     worst pair we already live with" is a claim that stays true when the
     *     palette moves, which a hard-coded 8.6 would not.
     *
     * **What the red said.** The walker — the first enemy in the game, in 1-1,
     * standing on grass — measured 6.0 % against grass and 5.7 % against the
     * night ground of world 2, both under the 8.6 % floor. The plant measured
     * 6.9 % against grass. Brown on brown, and it had been that way since the
     * first sprite was written.
     *
     * Gated on the three species this pass redrew, and **measured on all of
     * them**: the rest of the roster is printed with its worst theme so the
     * ones still under the line are a decision somebody makes with a number in
     * front of them rather than a thing this test quietly blesses.
     */
    {
      const { THEMES, T, drawTile } = await import('/src/gfx/tiles.js');
      const bodyMean = (paint) => {
        g.clearRect(0, 0, W, H);
        paint();
        const d = g.getImageData(0, 0, W, H).data;
        let r = 0; let gg = 0; let b = 0; let n = 0;
        for (let i = 0; i < W * H; i++) {
          const q = i * 4;
          if (d[q + 3] !== 255) continue;
          const key = `${d[q]},${d[q + 1]},${d[q + 2]}`;
          if (!ART.has(key) || key === '16,16,24') continue;
          r += d[q]; gg += d[q + 1]; b += d[q + 2]; n++;
        }
        return n ? [r / n, gg / n, b / n] : null;
      };
      const tileMean = (ch, theme) => {
        g.clearRect(0, 0, W, H);
        drawTile(g, ch, 0, 0, theme, 3, 5, 0, ' ', {});
        const d = g.getImageData(0, 0, 16, 16).data;
        let r = 0; let gg = 0; let b = 0; let n = 0;
        for (let q = 0; q < d.length; q += 4) {
          if (d[q + 3] < 8) continue;
          r += d[q]; gg += d[q + 1]; b += d[q + 2]; n++;
        }
        return n ? [r / n, gg / n, b / n] : null;
      };
      const sep = (a, b) => (!a || !b ? 0
        : ((Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2])) / 3 / 255) * 100);
      const floor = sep(tileMean(T.GROUND, 'desert'), tileMean(T.BRICK, 'desert'));
      const grounds = Object.keys(THEMES).map((th) => [th, tileMean(T.GROUND, th)]);
      /* The three species this pass redrew. The flyer is on the list because
       * it *is* the walker — `drawFlyer` paints `walkerBody` and adds wings —
       * so leaving it out would be pretending a body is two bodies. */
      const owned = new Set(['walker', 'flyer', 'shell walking', 'shell', 'shell sliding', 'plant']);
      const rows = [];
      for (const s of subjects) {
        const m = bodyMean(() => s.paint(OX, 0, 1));
        let worst = { th: '?', v: 1e9 };
        for (const [th, ground] of grounds) {
          const v = sep(m, ground);
          if (v < worst.v) worst = { th, v };
        }
        rows.push({ n: s.n, owned: owned.has(s.n), ...worst });
      }
      const mine = rows.filter((r) => r.owned);
      const rest = rows.filter((r) => !r.owned);
      const sunk = mine.filter((r) => r.v < floor);
      expect('uudelleenpiirretty vihollinen erottuu jokaisen teeman maasta',
        sunk.length === 0,
        `kynnys ${floor.toFixed(1)} % = aavikon maa vs tiili; `
        + `${mine.map((r) => `${r.n} ${r.v.toFixed(1)} (${r.th})`).join(', ')}`
        + ` — mittaamatta portissa: ${rest.map((r) => `${r.n} ${r.v.toFixed(1)} (${r.th})`).join(', ')}`);
    }
  }

  /* ------------------ tehostusten laatikko, siluetti ja tausta ----------- */
  /*
   * The same audit as the two above, pointed at the things the player picks
   * up. It is here because the pickups were the last set of sprites nobody had
   * measured, and measuring them is what turned DESIGN.md §1's claim about the
   * graphics from a sentence in a file header into something a machine checks.
   *
   * A pickup has one job and it is read in a tenth of a second: *which* power
   * this is. That splits into four measurements, and every one of them is a
   * number rather than an opinion:
   *
   *   1. **It fills the box it is picked up by.** `Item` is 16x16 (see
   *      entities/items.js) and that box is also the frame of the goal card,
   *      which is exactly 16 wide — so a sprite that paints outside the box
   *      paints outside the card's border, and a sprite that leaves a band of
   *      the box empty gets collected off thin air.
   *   2. **No two of them are the same picture.** Measured the way the eye
   *      asks the question: what fraction of the box actually *looks*
   *      different — counting a pixel one of them paints and the other does
   *      not, and a pixel both paint in colours less than a fifth apart as
   *      the same. Shape and palette in one number, because the player is not
   *      told which of the two is carrying the difference.
   *   3. **It survives all eight themes.** The tile audit already forbids two
   *      *tiles* from being the same colour; a pickup that matches the ground
   *      it is lying on is the same fault one layer up, and the pickup is the
   *      one the player is supposed to run towards.
   *   4. **It breathes on the shared clock.** Everything else alive in this
   *      game does (`breath`), and these are organs and fungi and a bowl of
   *      something still cooking — a still one reads as a pasted-on icon.
   *
   * Translucency is deliberately not body: the wisp of gas leaking out of a
   * pickup and the star's halo are light and vapour, not the thing you touch,
   * so they are allowed outside the box and do not count towards filling it.
   * That is the same line the enemy audit above draws for trailing gas.
   */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const { THEMES } = await import('/src/gfx/tiles.js');
    /* Kuusi eikä seitsemän: `oneup` poistettiin 10.8.2026, koska mikään pelissä
     * ei koskaan tuottanut sitä (ks. src/gfx/sprites/items.js). Portin
     * mittaamat esineet ovat ne jotka pelaaja voi saada. */
    const KINDS = ['shroom', 'flower', 'leaf', 'soup', 'pop', 'star'];
    const BOX = 16;
    const W = 48; const H = 48; const OX = 16; const OY = 16;
    const PERIOD = sprites.BREATH_PERIOD;
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;

    /** How far apart two colours are, on the same 0..100 scale the tile audit uses. */
    const gap = (a, b) => ((Math.abs(((a >> 16) & 255) - ((b >> 16) & 255))
      + Math.abs(((a >> 8) & 255) - ((b >> 8) & 255))
      + Math.abs((a & 255) - (b & 255))) / 3 / 255) * 100;

    /** One frame of one sprite, reduced to the colour of every pixel of its box. */
    const shot = (paint) => {
      g.clearRect(0, 0, W, H);
      paint();
      const d = g.getImageData(0, 0, W, H).data;
      const px = new Int32Array(BOX * BOX).fill(-1);
      const inside = new Uint8Array(BOX * BOX);
      const colors = new Map();
      let n = 0; let rows = 0; let far = 0;
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          const i = (y * W + x) * 4;
          if (d[i + 3] !== 255) continue;
          const dx = x - OX; const dy = y - OY;
          if (dx >= 0 && dx < BOX && dy >= 0 && dy < BOX) {
            const key = (d[i] << 16) | (d[i + 1] << 8) | d[i + 2];
            px[dy * BOX + dx] = key;
            inside[dy * BOX + dx] = 1;
            n++;
            rows += dy;
            colors.set(key, (colors.get(key) || 0) + 1);
          } else {
            far = Math.max(far, -dx, dx - (BOX - 1), -dy, dy - (BOX - 1));
          }
        }
      }
      let cols = 0; let lines = 0;
      for (let k = 0; k < BOX; k++) {
        let anyCol = 0; let anyRow = 0;
        for (let q = 0; q < BOX; q++) {
          if (inside[q * BOX + k]) anyCol = 1;
          if (inside[k * BOX + q]) anyRow = 1;
        }
        cols += anyCol;
        lines += anyRow;
      }
      // `lift` is the body's vertical centre of mass in hundredths of a pixel,
      // the same measure the enemy breath is read from.
      return { px, inside, colors, n, far, cols, lines,
        lift: n ? Math.round((rows / n) * 100) : -1 };
    };

    /**
     * The smallest fraction of the box, over the whole cycle, on which two
     * sprites do not look the same. A pixel counts as different when one of
     * them paints it and the other does not, or when both paint it more than a
     * fifth apart — the same fifth this file uses below to say a pickup is not
     * its background.
     */
    const apart = (a, b) => {
      let worst = 1e9;
      for (let i = 0; i < a.length && i < b.length; i++) {
        let diff = 0;
        for (let q = 0; q < BOX * BOX; q++) {
          const p = a[i].px[q]; const r = b[i].px[q];
          if (p < 0 && r < 0) continue;
          if (p < 0 || r < 0 || gap(p, r) >= 20) diff++;
        }
        worst = Math.min(worst, diff);
      }
      return (worst / (BOX * BOX)) * 100;
    };

    const seen = new Map();
    for (const kind of KINDS) {
      const frames = [];
      for (let t = 0; t < PERIOD; t++) frames.push(shot(() => sprites.drawItem(g, kind, OX, OY, t)));
      seen.set(kind, frames);
    }

    /* 1. the box */
    const loose = [];
    const filled = [];
    for (const kind of KINDS) {
      const frames = seen.get(kind);
      let minFill = 1e9; let minCols = 16; let minRows = 16; let bleed = 0;
      for (const f of frames) {
        minFill = Math.min(minFill, f.n);
        minCols = Math.min(minCols, f.cols);
        minRows = Math.min(minRows, f.lines);
        bleed = Math.max(bleed, f.far);
      }
      // 40 % of the box is the smallest a pickup can be and still be the thing
      // the box belongs to; below that the player is collecting the air around
      // it. All sixteen columns and rows must be touched at every frame.
      if (minFill < 102 || minCols < BOX || minRows < BOX || bleed > 0) {
        loose.push(`${kind}: ${Math.round((minFill / 256) * 100)} % täynnä, `
          + `${minCols}/${BOX} saraketta, ${minRows}/${BOX} riviä`
          + (bleed > 0 ? `, ${bleed} px laatikon ulkopuolella` : ''));
      }
      filled.push(`${kind} ${Math.round((minFill / 256) * 100)}%`);
    }
    expect('jokainen tehostus täyttää poimintalaatikkonsa eikä vuoda sen yli',
      loose.length === 0, loose.length ? loose.join('; ') : filled.join(', '));

    /*
     * 2. no two pickups are the same picture, and the threshold is not invented.
     *
     * **Where 40 % comes from.** The same measurement was run over the five
     * enemies that share this 16x16 box and that a player is already expected
     * to tell apart across a room. The tightest pair of *species* is the spiky
     * one and the kurnuttaja at 43.8 %; the loosest comparison in the game is
     * the walker and the flyer at **0.8 %**, and that one is not a fault but
     * the clearest possible statement of what this box can and cannot hold —
     * inside it the flyer simply *is* the walker, and the wings that tell them
     * apart are drawn outside the box entirely. So 40 % is a hair under what
     * the game already ships and defends, and the enemy figure is measured
     * again here rather than remembered, so that it is visible if it drifts.
     *
     * The old pickups had eight pairs under that line and the worst of them
     * was the flower and the leaf at 29.7 %. The pair this was written for was
     * the mushroom and the 1-up: one drawing, two hues, 35.9 % apart, and the
     * difference between one more hit and one more life. (The 1-up itself is
     * gone since 10.8.2026 — nothing in the game ever spawned it — but the
     * threshold it bought stays, because it is what keeps the next pair honest.)
     */
    const APART = 40;
    const pairs = [];
    for (let a = 0; a < KINDS.length; a++) {
      for (let b = a + 1; b < KINDS.length; b++) {
        pairs.push({ pair: `${KINDS[a]}/${KINDS[b]}`,
          d: apart(seen.get(KINDS[a]), seen.get(KINDS[b])) });
      }
    }
    pairs.sort((p, q) => p.d - q.d);
    const same = pairs.filter((p) => p.d < APART);
    // The calibration, re-measured. Guarded because the enemies live in
    // somebody else's file and a missing one must not fail the pickups.
    const species = [
      ['walker', sprites.drawWalker, (f, t) => f(g, OX, OY, Math.floor(t / 8), 1, false)],
      ['spikeguy', sprites.drawSpikeGuy, (f, t) => f(g, OX, OY, Math.floor(t / 2), 1)],
      ['corkguy', sprites.drawCorkGuy, (f, t) => f(g, OX, OY, t, 1)],
      ['kurnuttaja', sprites.drawKurnuttaja, (f, t) => f(g, OX, OY, t, 1)],
    ].filter(([, fn]) => typeof fn === 'function')
      .map(([name, fn, call]) => [name, (t) => call(fn, t)]);
    const beasts = new Map();
    for (const [name, paint] of species) {
      const frames = [];
      for (let t = 0; t < PERIOD; t += 4) frames.push(shot(() => paint(t)));
      beasts.set(name, frames);
    }
    let floor = { pair: '-', d: -1 };
    for (let a = 0; a < species.length; a++) {
      for (let b = a + 1; b < species.length; b++) {
        const d = apart(beasts.get(species[a][0]), beasts.get(species[b][0]));
        if (floor.d < 0 || d < floor.d) floor = { pair: `${species[a][0]}/${species[b][0]}`, d };
      }
    }
    expect('kaksi tehostusta eivät ole sama kuva',
      same.length === 0,
      (same.length ? `${same.map((p) => `${p.pair} ${p.d.toFixed(1)} %`).join('; ')} — ` : '')
        + `lähin pari ${pairs[0].pair} ${pairs[0].d.toFixed(1)} %, toiseksi lähin `
        + `${pairs[1].pair} ${pairs[1].d.toFixed(1)} % (raja ${APART} %, `
        + `vihollislajien tiukin pari ${floor.pair} ${floor.d.toFixed(1)} %)`);

    /* 3. the eight themes, plus the two frames a pickup is drawn in */
    const grounds = [];
    for (const [name, th] of Object.entries(THEMES)) {
      for (const [what, css] of [['taivas', th.sky[0]], ['horisontti', th.sky[1]],
        ['maa', th.ground], ['pinta', th.groundTop], ['tiili', th.brick],
        ['kova', th.hard], ['kukkula', th.hill]]) {
        grounds.push({ name: `${name} ${what}`, rgb: [parseInt(css.slice(1, 3), 16),
          parseInt(css.slice(3, 5), 16), parseInt(css.slice(5, 7), 16)] });
      }
    }
    // The two backgrounds that are not a theme at all and are the extremes:
    // the HUD's reserve box is nearly black and the goal card is nearly white.
    grounds.push({ name: 'HUD-lokero', rgb: [0x20, 0x20, 0x38] });
    grounds.push({ name: 'maalikortti', rgb: [0xf8, 0xf8, 0xf8] });
    const vanish = [];
    const worstBg = [];
    for (const kind of KINDS) {
      let worst = 1e9; let where = '';
      for (const bg of grounds) {
        let least = 1e9;
        for (const f of seen.get(kind)) {
          let stands = 0;
          for (const [key, count] of f.colors) {
            const dr = Math.abs(((key >> 16) & 255) - bg.rgb[0]);
            const dg = Math.abs(((key >> 8) & 255) - bg.rgb[1]);
            const db = Math.abs((key & 255) - bg.rgb[2]);
            if (((dr + dg + db) / 3 / 255) * 100 >= 20) stands += count;
          }
          least = Math.min(least, stands);
        }
        if (least < worst) { worst = least; where = bg.name; }
      }
      // 40 px is a 6x7 patch — the smallest blob of this artwork that is still
      // a shape and not a speck — and 20 % is twice the gap the tile audit
      // already calls indistinguishable (fortress ground vs brick, 8.6 %).
      if (worst < 40) vanish.push(`${kind}: vain ${worst} px erottuu taustasta ${where}`);
      worstBg.push(`${kind} ${worst}px (${where})`);
    }
    expect('yksikään tehostus ei katoa yhteenkään taustaan',
      vanish.length === 0, vanish.length ? vanish.join('; ') : worstBg.join(', '));

    /* 4. the shared breath */
    const still = [];
    const beats = [];
    for (const kind of KINDS) {
      const frames = seen.get(kind);
      let hi = 0; let hiN = 0; let lo = 0; let loN = 0;
      for (let t = 0; t < PERIOD; t++) {
        if (sprites.breath(t, OX, OY)) { hi += frames[t].lift; hiN++; } else { lo += frames[t].lift; loN++; }
      }
      // Positive means the body sits higher on the frames the shared clock is
      // inhaling on, in hundredths of a pixel of centre of mass.
      const rise = (loN && hiN) ? (lo / loN) - (hi / hiN) : 0;
      if (rise < 20) still.push(`${kind} nousee ${(rise / 100).toFixed(2)} px`);
      beats.push(`${kind} ${(rise / 100).toFixed(2)}`);
    }
    expect('jokainen tehostus hengittää muun pelin kellolla',
      still.length === 0,
      still.length ? still.join('; ') : `nousu hengityksen tahdissa: ${beats.join(', ')} px`);
  }

  /* ------------------------ kävelyn ohitusasento ------------------------ */
  /*
   * A walk is contact, pass, contact, pass. The three leg frames were always
   * right — 0 and 2 are the two contacts, 1 is the pass — but the driver ran
   * them with `% 3`, so once every stride the cycle wrapped 2 straight back to
   * 0 and the character put both feet down twice in a row.
   *
   * Measured on the pictures a player who is actually walking asks for, not on
   * the counter: the counter can be renumbered, the limp cannot be argued with.
   */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const c = document.createElement('canvas');
    c.width = 40;
    c.height = 40;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    const shot = (frame) => {
      g.clearRect(0, 0, 40, 40);
      sprites.drawPlayer(g, 8, 4, {
        type: 'shroom', level: 1, facing: 1, frame, state: 'walk',
        running: false, tick: 5, idle: 0, wag: 0,
      });
      const d = g.getImageData(0, 0, 40, 40).data;
      let h = 0;
      for (let i = 0; i < d.length; i += 4) h = (h * 31 + d[i] * 5 + d[i + 3]) | 0;
      return h;
    };

    reset({ type: 'shroom', level: 1 });
    const scene = new LevelScene(game, '1-1');
    const input = mkInput();
    input.held.right = true;
    const asked = [];
    for (let f = 0; f < 400; f++) {
      scene.update(input);
      const p = scene.player;
      if (p.state() === 'walk') asked.push(p.animFrame);
    }
    // The pictures, with repeats of the same picture collapsed.
    const pics = [];
    for (const f of asked) {
      const h = shot(f);
      if (pics.length === 0 || pics[pics.length - 1] !== h) pics.push(h);
    }
    const pass = shot(1);
    const contacts = new Set(pics.filter((h) => h !== pass));
    let doubled = 0;
    for (let i = 1; i < pics.length; i++) {
      if (pics[i] !== pass && pics[i - 1] !== pass) doubled++;
    }
    expect('the walk passes through the closed-legs frame between every contact',
      pics.length > 8 && contacts.size === 2 && doubled === 0,
      `${pics.length} kuvaa, ${contacts.size} kosketusasentoa, ${doubled} peräkkäin`);
  }

  /* ------------------------- kiipeilyn oma asento ----------------------- */
  /*
   * Half of this was already in the engine and thrown away: `animFrame` was
   * being driven as a two-frame hand-over-hand cycle while `state()` reported
   * `jump`, so the vine showed a frozen jump pose that never changed. Both
   * halves are checked here — the state the engine reports, and that the two
   * frames are actually two different pictures and neither of them is the jump.
   */
  {
    const { T } = await import('/src/gfx/tiles.js');
    const sprites = await import('/src/gfx/sprites.js');
    reset({ type: 'shroom', level: 1 });
    let scene = null;
    let vine = null;
    for (const id of levelIds()) {
      const sc = new LevelScene(game, id);
      /* No beanstalk is in the grid until its block has been hit, so a test
       * about climbing one has to plant it first. The entities are stepped on
       * their own rather than through `scene.update`, so nothing else in the
       * level — enemies, the clock, the player falling off something — moves
       * while this is only trying to make a vine exist. */
      for (const key of [...sc.beanstalks.keys()]) {
        const [bx, by] = key.split(',').map(Number);
        sc.bumpTile(bx, by, sc.player);
      }
      for (let f = 0; f < 400; f++) {
        const growing = sc.entities.filter((e) => e.kind === 'prop');
        if (!growing.length) break;
        for (const e of growing) e.update();
        sc.entities = sc.entities.filter((e) => !e.remove);
      }
      for (let ty = 1; ty < sc.h && !vine; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          if (sc.rawTileAt(tx, ty) === T.VINE && sc.rawTileAt(tx, ty + 1) === T.VINE) {
            vine = { tx, ty }; scene = sc; break;
          }
        }
      }
      if (vine) break;
    }
    let climbState = 'ei köyttä';
    let moved = false;
    if (vine) {
      const p = scene.player;
      p.x = vine.tx * 16 + (16 - p.w) / 2;
      p.y = vine.ty * 16;
      p.onGround = false;
      const input = mkInput();
      input.held.up = true;
      const seen = new Set();
      for (let f = 0; f < 40; f++) {
        scene.update(input);
        if (p.climbing) { climbState = p.state(); seen.add(p.animFrame); }
      }
      moved = seen.size === 2;
    }

    const c = document.createElement('canvas');
    c.width = 40;
    c.height = 40;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    const shot = (o) => {
      g.clearRect(0, 0, 40, 40);
      sprites.drawPlayer(g, 8, 4, {
        type: 'shroom', level: 1, facing: 1, frame: 0, state: 'idle',
        running: false, tick: 5, idle: 0, wag: 0, ...o,
      });
      const d = g.getImageData(0, 0, 40, 40).data;
      let h = 0;
      for (let i = 0; i < d.length; i += 4) h = (h * 31 + d[i] * 5 + d[i + 3]) | 0;
      return h;
    };
    const a = shot({ state: 'climb', frame: 0 });
    const b = shot({ state: 'climb', frame: 1 });
    const jump = shot({ state: 'jump', frame: 0 });
    expect('a player on a vine climbs instead of hanging in a jump pose',
      climbState === 'climb' && moved && a !== b && a !== jump && b !== jump,
      `tila "${climbState}", kaksi framea ${moved}, framet eroavat ${a !== b}, `
      + `ei hyppyasento ${a !== jump && b !== jump}`);
  }

  /* --------------------- toisen tason seisonta-animaatiot --------------- */
  /*
   * Twenty seconds of standing still — the same wait the title screen makes
   * before the cabinet starts playing by itself — and the character starts a
   * bigger performance: he falls asleep in an ordinary level, breathes icicles
   * on the ice and sets his hair on fire in the desert.
   *
   * Three things are checked, and the first two are the whole joke:
   *  1. Nothing at all changes before the twenty seconds are up. The first-tier
   *     idle keeps its own 360-frame cycle, so a shot at 1199 must be identical
   *     to the same phase 360 frames earlier.
   *  2. It ends in one frame when anything comes near, exactly as the attract
   *     demo hands the machine back.
   *  3. All three are different performances, not one with a repaint.
   */
  {
    const sprites = await import('/src/gfx/sprites.js');
    const c = document.createElement('canvas');
    c.width = 64;
    c.height = 64;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    const shot = (o) => {
      g.clearRect(0, 0, 64, 64);
      sprites.drawPlayer(g, 22, 26, {
        type: null, level: 1, facing: 1, state: 'idle', frame: 0, wag: 0,
        running: false, ducking: false, theme: 'grass', tick: 100, ...o,
      });
      return g.getImageData(0, 0, 64, 64).data;
    };
    const diff = (a, b) => {
      let n = 0;
      for (let i = 0; i < a.length; i += 4) {
        if (a[i] !== b[i] || a[i + 1] !== b[i + 1] || a[i + 2] !== b[i + 2]
          || a[i + 3] !== b[i + 3]) n++;
      }
      return n;
    };
    const quiet = diff(shot({ idle: 1199 }), shot({ idle: 839 }));
    const wakes = diff(shot({ idle: 1199 }), shot({ idle: 1300 }));
    const sleep = shot({ idle: 1300 });
    const frost = shot({ idle: 1263, theme: 'ice' });
    const fire = shot({ idle: 1260, theme: 'desert' });
    const own = Math.min(diff(sleep, frost), diff(sleep, fire), diff(frost, fire));
    // …and it must be an animation, not a still.
    const alive = diff(shot({ idle: 1300 }), shot({ idle: 1340 }));
    expect('the second-tier idle waits twenty seconds and then puts on a show',
      quiet === 0 && wakes > 30 && own > 20 && alive > 10,
      `ennen ${quiet}px, laukeaa ${wakes}px, teemojen ero ${own}px, elää ${alive}px`);

    /* Breaking in a single frame is the same promise the attract demo makes. */
    reset({ type: 'shroom', level: 1 });
    const scene = new LevelScene(game, '1-1');
    const p = scene.player;
    const idleInput = mkInput();
    for (let f = 0; f < 30; f++) scene.update(idleInput);
    // Nothing in the room to begin with, so the twenty seconds can run out.
    const foes = scene.entities.filter((e) => e.kind === 'enemy');
    for (const e of foes) e.x += 4000;
    p.idle = 1400;
    scene.update(idleInput);
    const undisturbed = p.idle;
    let broke = -1;
    if (foes.length) {
      const foe = foes[0];
      foe.x = p.x + 40;
      foe.y = p.y;
      foe.active = true;
      p.idle = 1400;
      scene.update(idleInput);
      broke = p.idle;
    }
    expect('the second-tier idle stops dead the frame something comes near',
      undisturbed > 1400 && broke === 0,
      `häiriöttä ${undisturbed}, vihollinen lähellä ${broke}`);
  }

  /* ---------------------------- voittoruutu ----------------------------- */
  /* Clearing a castle used to leave the player standing on the edge of the
   * arena while the map loaded. The card must appear, must be skippable, and
   * must never be able to swallow the world it was celebrating. */
  {
    const { VictoryScene } = await import('/src/scenes/cards.js');
    reset({ type: 'leaf', level: 3 });
    let completed = 0;
    const realComplete = game.completeWorld;
    game.completeWorld = () => { completed++; };
    game.pendingNode = { id: 'w1-f', level: '1-F', type: 'fortress' };
    game.finishLevel = Object.getPrototypeOf(game).finishLevel || game.finishLevel;
    game.setScene(new VictoryScene(game, 1, () => game.completeWorld()));
    const shown = game.scene instanceof VictoryScene;
    const i = mkInput();
    for (let f = 0; f < 20; f++) game.scene.update(i);
    const early = completed;
    i.pressed.jump = true;
    game.scene.update(i);
    const afterKey = completed;
    // …and it must also end on its own, for whoever puts the pad down.
    game.setScene(new VictoryScene(game, 1, () => game.completeWorld()));
    for (let f = 0; f < 600; f++) game.scene.update(mkInput());
    expect('the victory card shows, skips on a key and ends by itself',
      shown && early === 0 && afterKey === 1 && completed === 2,
      `alussa ${early}, näppäimellä ${afterKey}, lopuksi ${completed}`);
    game.completeWorld = realComplete;
  }

  /* --------------------------- tehostusportti --------------------------- */
  /*
   * SEGMENTTI JONKA LÄPI EI PÄÄSE ILMAN TEHOSTUSTA — ja se on tietoinen
   * poikkeus DESIGN.md kohtaan 5.
   *
   * Omistajan päätös 18.8.2026 sanatarkasti: *"voi olla segmenttejä, joissa
   * TARVITAAN powerup, mutta VARMISTA ETTÄ POWERUP on saatavilla sitä ennen!"*
   * Poikkeus on siis kaupan, ja tämä lohko on se hinta: **lupaus ei muutu
   * väljemmäksi vaan täsmällisemmäksi.** Vanha lupaus oli "kenttä on
   * läpäistävissä voimatasolla 0"; uusi on "kenttä on läpäistävissä
   * voimatasolla 0 **aloittaen**", eli tehostus on matkan varrella eikä
   * pelaajan mukana.
   *
   * Neljä mittausta, ja kaksi niistä on punaista ennen vihreää:
   *
   *   1. botti läpäisee kentän voimatasolla 0 — eli poimii lahjan matkalla;
   *   2. **ilman lahjaa se ei läpäise**, eli portti on oikeasti portti eikä
   *      koriste (ilman tätä koko poikkeus voisi olla turha);
   *   3. lahja on ennen porttia ja lähellä sitä;
   *   4. **poikkeus koskee vain ilmoitettuja sarakkeita**: sama ruudukko ilman
   *      ilmoitusta kaatuu sääntöön, eli ilmoitus on se joka tekee eron eikä
   *      kuilun leveys.
   */
  {
    const { runGround } = await import('/tools/level-bot.js');
    const { isSolid: solid2, T: TG } = await import('/src/gfx/tiles.js');
    const { validateLevel: rules2 } = await import('/src/data/rules.js');
    const budget2 = await (await fetch('/tools/jump-budget.json')).json();
    const { getLevel: getDef2, levelIds: ids2 } = await import('/src/data/levels.js');
    /* Portilliset kentät löytyvät **lahjasta ruudukossa** eikä datakentästä,
     * koska ilmoitus on lahja. Ks. `rules.js`, `giftBefore`. */
    const gated = ids2().map((id) => ({ id, def: getDef2(id) }))
      .filter((x) => x.def.rows.some((row) => row.includes(TG.GIFT)));

    const run = (id, strip) => {
      reset({ type: null, level: 0 });
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      if (strip) s.entities = s.entities.filter((e) => e.kind !== 'item');
      s.time = 9999;
      s.clockStopped = true;
      return runGround(s, solid2, 7000, () => finished);
    };

    const rows = [];
    for (const { id, def } of gated) {
      const withGift = run(id, false);
      const without = run(id, true);
      /* Lahja on ruudukossa merkkinä `i` ennen kuin kohtaus muuttaa sen
       * olioksi, joten se luetaan kentän riveistä eikä kohtauksesta. */
      let giftCol = -1;
      for (const row of def.rows) {
        const at = row.indexOf(TG.GIFT);
        if (at >= 0 && (giftCol < 0 || at < giftCol)) giftCol = at;
      }
      /* Sama ruudukko ilman lahjaa: se on se koe joka todistaa ettei kuilun
       * leveys yksin riitä poikkeukseksi. Lahja pyyhitään riveiltä, eikä
       * kentästä muuteta mitään muuta. */
      const nogift = def.rows.map((row) => row.split(TG.GIFT).join(' '));
      const naked = rules2(nogift, budget2, { vertical: !!def.vertical, segments: def.segments });
      const gapCol = Number((naked.find((pr) => /^gap of/.test(pr)) || '')
        .replace(/^gap of \d+ at column (\d+).*/, '$1'));
      rows.push({
        id,
        cleared: withGift.cleared,
        blocked: !without.cleared,
        giftCol,
        gapCol,
        near: giftCol >= 0 && gapCol > giftCol && gapCol - giftCol <= 24,
        declared: naked.some((pr) => /^gap of/.test(pr)),
      });
    }

    expect('tehostusportti: botti läpäisee voimatasolla 0 poimimalla lahjan',
      gated.length > 0 && rows.every((r) => r.cleared),
      rows.map((r) => `${r.id} ${r.cleared ? 'läpi' : 'jumissa'}`).join(', ') || 'ei portteja');
    expect('tehostusportti on oikeasti portti: ilman lahjaa ei pääse läpi',
      rows.every((r) => r.blocked),
      rows.map((r) => `${r.id} ilman lahjaa ${r.blocked ? 'pysähtyy' : 'pääsee silti'}`).join(', '));
    expect('lahja on ennen porttia ja sen lähellä',
      rows.every((r) => r.near),
      rows.map((r) => `${r.id} lahja sarakkeessa ${r.giftCol}, kuilu ${r.gapCol}`).join(', '));
    expect('kuilun leveys ei riitä poikkeukseksi, ilmoitus riittää',
      rows.every((r) => r.declared),
      rows.map((r) => `${r.id} ilman ilmoitusta ${r.declared ? 'kaatuu sääntöön' : 'menee läpi'}`).join(', '));
  }

  /* ------------------------------- verbi 6 ------------------------------ */
  /*
   * NIELTY VIHOLLINEN ON TYÖKALU — IDEAS kohta 6, tuomio "kyllä".
   *
   * *"Syö vihollinen, saat kyvyn — piikkiukko tekee piikikkääksi, lentäjä
   * antaa hypyn — eli jokaisesta lajista tulee työkalu."* Neljä väitettä, ja
   * jokainen mitataan tapahtumana: nieleminen tapahtuu, kyky **tekee jotain**,
   * kyky loppuu, eikä yksikään laji jää ilman lahjaa.
   */
  {
    const E6 = await import('/src/entities/enemies.js');
    const { T: T6 } = await import('/src/gfx/tiles.js');

    /** Kenttä, pelaaja maassa, ja yksi kuplassa oleva vihollinen vieressä. */
    const withBubble = (Ctor, power = { type: null, level: 0 }) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      const p = s.player;
      const e = new Ctor(s, p.x + 6, p.y);
      e.y = p.y;
      e.active = true;
      e.alwaysActive = true;
      e.spawnGrace = 0;
      s.add(e);
      e.trap();
      return { s, p, e };
    };
    const up = () => { const i = mkInput(); i.held.up = true; return i; };

    /* 1. NIELEMINEN: kupla katoaa ja suussa on kyky. */
    {
      const { s, p, e } = withBubble(E6.Flyer);
      s.update(up());
      expect('kuplassa oleva vihollinen niellään ylöspainalluksella',
        p.swallowed === 'siivet' && e.remove,
        `suussa ${p.swallowed || 'ei mitään'}, kupla ${e.remove ? 'poissa' : 'jäljellä'}`);
    }

    /* 2. KYKY TEKEE JOTAIN, ja jokainen neljästä mitataan omalla tavallaan. */
    {
      const wings = withBubble(E6.Flyer);
      wings.s.update(up());
      const airBefore = 0;
      const airAfter = wings.p.airJumpsMax;

      const spikes = withBubble(E6.SpikeGuy);
      spikes.s.update(up());
      const victim = new E6.Walker(spikes.s, spikes.p.x + 4, spikes.p.y);
      victim.y = spikes.p.y;
      victim.active = true;
      victim.alwaysActive = true;
      victim.spawnGrace = 0;
      spikes.s.add(victim);
      const powerBefore = spikes.p.powerLevel;
      for (let f = 0; f < 4; f++) spikes.s.update(mkInput());
      const killedByTouch = victim.dying || victim.remove;

      const cold = withBubble(E6.Kuura);
      cold.s.update(up());
      for (let f = 0; f < 20; f++) cold.s.update(mkInput());
      const froze = cold.s.frost.size;

      const magnet = withBubble(E6.Kolikkovaras);
      magnet.s.update(up());
      const px = Math.floor(magnet.p.cx / 16);
      const py = Math.floor(magnet.p.cy / 16);
      magnet.s.setTile(px + 3, py, T6.COIN);
      const purse = game.state.coins;
      for (let f = 0; f < 6; f++) magnet.s.update(mkInput());
      const pulled = game.state.coins > purse && magnet.s.tileAt(px + 3, py) !== T6.COIN;

      expect('nielty kyky tekee sen mitä laji teki',
        airAfter > airBefore && killedByTouch && spikes.p.powerLevel === powerBefore
        && froze > 0 && pulled,
        `siivet ${airBefore}->${airAfter} ilmahyppyä, piikit tappoivat ${killedByTouch} `
        + `(voimataso ${powerBefore}->${spikes.p.powerLevel}), kylmä jäädytti ${froze} ruutua, `
        + `magneetti veti ${pulled}`);
    }

    /*
     * 3. KYKY EI KULU AJASSA VAAN PAIKASTA (19.8.2026).
     *
     * Tämä tarkisti ennen että kyky loppuu kahdeksassa sekunnissa. Se raja on
     * poistettu tarkoituksella: kyky vie tehostuksen paikan ja työntää sen
     * varalokeroon, eli sillä on hinta eikä kelloa. Kolme väitettä:
     *
     *   - kyky **pysyy** vaikka kello kävisi kuinka pitkään
     *   - nieleminen **maksaa**: lehti on varalokerossa jälkeenpäin
     *   - keho **ei kutistu**: taso on sama ennen ja jälkeen, koska "mikä
     *     voima" ja "kuinka kaasuinen" ovat eri kysymyksiä
     */
    {
      const { s, p } = withBubble(E6.Flyer);
      p.power = { type: 'leaf', level: 3 };
      s.game.state.reserve = null;
      const levelBefore = p.power.level;
      s.update(up());
      const got = p.swallowed;
      const banked = s.game.state.reserve;
      for (let f = 0; f < 900; f++) s.update(mkInput());
      expect('nielty kyky ei kulu ajassa, se maksaa tehostuksen paikan',
        got === 'siivet' && banked === 'leaf' && p.swallowed === 'siivet'
        && p.power.level === levelBefore,
        `sai ${got || 'ei mitään'}, lokeroon ${banked || 'ei mitään'},`
        + ` 900 framen jälkeen ${p.swallowed || 'ei mitään'},`
        + ` taso ${levelBefore} -> ${p.power.level}`);
    }

    /* 4. EIKÄ YKSIKÄÄN KUPLATTAVA LAJI JÄÄ ILMAN LAHJAA. Poikkeuslistaa ei ole:
     *    laji jolla ei ole omaa kykyä antaa itsensä ammuksena (`sylky`). */
    {
      reset();
      const probe = new LevelScene(game, '1-1');
      game.setScene(probe);
      const gifts = [];
      for (const [ch, make] of Object.entries(E6.ENEMY_CHARS)) {
        const e = make(probe, 20, 11, 0);
        if (!e.bubbleable) continue;
        gifts.push(`${ch}:${probe.swallowGift(e)}`);
      }
      const named = gifts.filter((g) => g.split(':')[1]);
      expect('jokainen kuplattava laji antaa jonkin kyvyn',
        gifts.length >= 8 && named.length === gifts.length,
        gifts.join(' '));
    }
  }

  /* --------------------------- kaistan vilkaisu ------------------------- */
  /*
   * KAISTAN VILKAISU — IDEAS kohta D, tuomio "tee rajattuna", ja rajaus on
   * kirjattu ROADMAP.md:hen 10.8.2026 kolmena päätöksenä. Ne kolme päätöstä
   * ovat tässä kolmena mittauksena, ja neljäs mittaa sen ettei painallus voi
   * maksaa kahdesti.
   *
   * Ratkaiseva on portti 2: **kenttägraafi ei saa muuttua.** Se on koko syy
   * siihen että tämä versio hyväksyttiin ja se raskaampi (läpi astuminen) ei —
   * `rules.js` todistaa yhä yhden kaistan läpäistävyyden eikä kaistojen
   * välistä graafia. Portti lukee ruudukon ennen ja jälkeen eikä luota siihen
   * että piirtofunktio "ei kai kirjoita mitään".
   */
  {
    const { PEEK_FRAMES, PEEK_IN: PEEK_IN2 } = await import('/src/scenes/level.js');
    const { P_METER_MAX: PMAX } = await import('/src/entities/player.js');

    /** Ensimmäinen kolmikaistainen kenttä, pelaaja lähtöruudussaan. */
    const tallId = levelIds().find((id) => getLevelDef(id).bands);
    const tall = () => {
      reset({ type: null, level: 0 });
      const s = new LevelScene(game, tallId);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    const down = () => { const i = mkInput(); i.pressed.down = true; i.held.down = true; return i; };
    const gridOf = (s) => s.grid.map((r) => (typeof r === 'string' ? r : r.join(''))).join('\n');

    /* 1. HINTA: tyhjä mittari ei riitä, täysi mittari kuluu kokonaan. */
    {
      const empty = tall();
      empty.player.pMeter = 0;
      empty.update(down());
      const poor = `tyhjällä ${empty.peek} framea`;

      const s = tall();
      s.player.pMeter = PMAX;
      s.update(down());
      const paid = `täydellä ${s.peek} framea, mittari ${Math.round(s.player.pMeter)}`;

      /* Ja sama isolla keholla täyttä vauhtia, koska juuri siinä oli ansa: alas
       * aloittaa kyykyn, kyykky jarruttaa, ja mittari luettaisiin vasta sen
       * jälkeen. Ks. `Player.pFullEntry` — ilman sitä tämä rivi on nolla. */
      reset({ type: 'shroom', level: 1 });
      const big = new LevelScene(game, tallId);
      game.setScene(big);
      big.entities = big.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      big.player.pMeter = PMAX;
      big.player.vx = 2.5;
      const i = down();
      i.held.right = true;
      i.held.run = true;
      big.update(i);
      const duck = `isona kyykyssä ${big.peek} framea`;

      expect('vilkaisu maksaa koko vauhtimittarin eikä lähde tyhjällä',
        empty.peek === 0 && empty.player.pMeter === 0
        && s.peek > 0 && s.player.pMeter === 0 && big.peek > 0,
        `${poor}, ${paid}, ${duck}`);
    }

    /* 2. VAIN KATSOMINEN: ruudukko, kaista ja kamera ovat vilkaisun jälkeen
     *    tasan siinä missä ennenkin. */
    {
      const s = tall();
      const p = s.player;
      p.pMeter = PMAX;
      const before = { grid: gridOf(s), band: s.bandAt(p.y + p.h), cam: s.cam.y, y: p.y };
      s.update(down());
      for (let f = 0; f < 30; f++) s.update(mkInput());
      const after = { grid: gridOf(s), band: s.bandAt(p.y + p.h), cam: s.cam.y, y: p.y };
      expect('vilkaisu on katsomista eikä kulkemista',
        before.grid === after.grid && before.band === after.band
        && before.cam === after.cam && before.y === after.y && s.peek > 0,
        `ruudukko ${before.grid === after.grid ? 'sama' : 'MUUTTUI'}, kaista `
        + `${before.band}->${after.band}, kamera ${Math.round(before.cam)}->`
        + `${Math.round(after.cam)}, vilkaisua jäljellä ${s.peek}`);
    }

    /* 3. KUVA: alempi kaista näkyy, ja se katoaa itsestään.
     *
     * Mitataan pikseleistä eikä lipusta, ja vertailukohta on **kaksoiskohtaus
     * samalla framella**: kaksi samasta kentästä rakennettua kohtausta saavat
     * saman syötteen ja maksavat saman mittarin, mutta toiselta vilkaisu
     * nollataan heti. Kaikki muu — kello, ruoho, pelaajan asento, HUDin
     * mittari — on niissä silloin identtinen, joten ainoa mahdollinen ero on
     * haamu. Aiempi versio vertasi framea 0 frameen 98 ja epäonnistui siihen
     * että maailma hengittää: 2728 pikseliä eroa pelkästä kellosta.
     */
    {
      const cv = document.createElement('canvas');
      cv.width = 320; cv.height = 240;
      const g = cv.getContext('2d');
      const shot = (s) => {
        g.clearRect(0, 0, 320, 240);
        s.draw(g);
        return g.getImageData(0, 0, 320, 240).data;
      };
      const diff = (a, b) => {
        let n = 0;
        for (let i = 0; i < a.length; i += 4) {
          if (a[i] !== b[i] || a[i + 1] !== b[i + 1] || a[i + 2] !== b[i + 2]) n++;
        }
        return n;
      };
      /* Seisomapaikaksi se sarake jonka **alla oikeasti on jotain**. Kentän
       * 1-2 luolakaista on lähtöruudussa tyhjä — koko kaistan muste on 177
       * laattaa neljälläsadalla sarakkeella — joten lähdöstä vilkaistu haamu
       * on tyhjä haamu, ja portti mittasi 960 pikseliä joista 640 oli juova.
       * Se ei ole vika vaan idean ydin: vilkaisu kertoo *missä* kammio on. */
      const ink = [];
      {
        const probe = tall();
        for (let tx = 0; tx < probe.w; tx++) {
          let n = 0;
          for (let ty = probe.def.bands.cave; ty < probe.h; ty++) {
            if (probe.grid[ty][tx] !== ' ') n++;
          }
          ink.push(n);
        }
      }
      let bestCol = 0;
      let best = -1;
      for (let tx = 0; tx < ink.length - 20; tx++) {
        let sum = 0;
        for (let d = 0; d < 20; d++) sum += ink[tx + d];
        if (sum > best) { best = sum; bestCol = tx + 10; }
      }
      const standAt = (s) => {
        const bands = s.def.bands;
        const p = s.player;
        let ty = bands.main + bands.rows - 1;
        while (ty > bands.main && !isSolid(s.grid[ty][bestCol])) ty--;
        p.x = bestCol * 16;
        p.y = ty * 16 - p.h;
        p.vx = 0; p.vy = 0; p.onGround = true;
        p.pMeter = PMAX;
        s.centerCamera();
      };

      const a = tall();
      standAt(a);
      a.update(down());
      const b = tall();
      standAt(b);
      b.update(down());
      b.peek = 0;
      /* Mitataan täydeltä läpikuultavuudelta eikä ensimmäiseltä framelta, ja
       * se on portin terävin kohta: ensimmäisellä framella nousu on 1/8 ja ero
       * oli 640 pikseliä — tasan `320 * 2`, eli **pyyhkäisyjuova yksin**.
       * Sellainen portti olisi mennyt läpi vaikka yhtäkään haamulaattaa ei
       * olisi piirretty. Kynnys on siksi moninkertainen juovaan nähden. */
      for (let f = 0; f < PEEK_IN2; f++) { a.update(mkInput()); b.update(mkInput()); }
      const lit = diff(shot(a), shot(b));
      for (let f = 0; f < PEEK_FRAMES; f++) { a.update(mkInput()); b.update(mkInput()); }
      const over = diff(shot(a), shot(b));
      expect('alempi kaista näkyy haamuna ja katoaa itsestään',
        lit > 5000 && a.peek === 0 && over === 0,
        `haamu ${lit} pikseliä (juova yksin olisi 640), lopuksi ${over} pikseliä`);
    }

    /* 4. SAMA PAINALLUS EI MAKSA KAHDESTI: putken suulla alas on putki, ja
     *    alimmassa kaistassa alas ei ole mitään.
     *
     * Mittari luetaan kynnyksellä eikä yhtäsuuruudella: `Player.update` valuttaa
     * sitä joka framella (P_DRAIN), joten "koskematon" on 111,3 eikä 112. Se
     * ero on mittarin oma luonnollinen tyhjeneminen, ei vilkaisun hinta —
     * hinta on nolla, ja niiden välissä on sata yksikköä. */
    {
      const s = tall();
      const p = s.player;
      const key = [...s.warpExits.keys()].find((k) => {
        const [, ty] = k.split(',').map(Number);
        return s.bandAt(ty * 16) < 2;
      });
      let pipe = 'ei putkea kentässä';
      let pipeOk = !!key;
      if (key) {
        const [tx, ty] = key.split(',').map(Number);
        p.x = tx * 16; p.y = ty * 16 - p.h;
        p.vx = 0; p.vy = 0; p.onGround = true; p.warpLock = 0; p.transit = null;
        p.pMeter = PMAX;
        s.centerCamera();
        s.update(down());
        pipeOk = !!p.transit && s.peek === 0 && p.pMeter > PMAX * 0.9;
        pipe = `putkella matka ${p.transit ? 'alkoi' : 'EI ALKANUT'}, vilkaisu `
          + `${s.peek}, mittari ${Math.round(p.pMeter)}`;
      }

      /* Alin kaista: etsitään sieltä oikea lattia, eli kiinteä laatta jonka
       * päällä on tilaa seistä. Reittikaistan lattia ei kelpaa — koko väite on
       * että **alimmassa** kaistassa ei ole mitään alempaa katsottavaa. */
      const c = tall();
      const q = c.player;
      const rows = c.def.bands.rows;
      const lastBand = Math.floor((c.h - 1) / rows);
      let spot = null;
      for (let tx = 2; tx < c.w - 2 && !spot; tx++) {
        for (let ty = c.h - 1; ty >= lastBand * rows + 2; ty--) {
          if (isSolid(c.grid[ty][tx]) && !isSolid(c.grid[ty - 1][tx])
            && !isSolid(c.grid[ty - 2][tx])) { spot = [tx, ty]; break; }
        }
      }
      q.x = spot[0] * 16; q.y = spot[1] * 16 - q.h;
      q.vx = 0; q.vy = 0; q.onGround = true;
      q.pMeter = PMAX;
      c.centerCamera();
      c.update(down());
      const deep = `kaistassa ${c.bandAt(q.y + q.h)}/${lastBand}: vilkaisu ${c.peek}, `
        + `mittari ${Math.round(q.pMeter)}`;
      expect('vilkaisu ei veloita silloin kun alas tarkoittaa jotain muuta',
        pipeOk && c.bandAt(q.y + q.h) === lastBand && c.peek === 0
        && q.pMeter > PMAX * 0.9,
        `${pipe}; ${deep}`);
    }

    /* 5. OPETUS: nuoli näkyy tasan silloin kun vilkaisu on mahdollinen, ja
     *    ensimmäinen vilkaisu lopettaa sen lopullisesti.
     *
     * Mitataan **saman kohtauksen kahtena piirtona samalla framella**, ja
     * ainoa muuttuja on `taught.peek`, jonka piirto lukee elävästä pelitilasta.
     * Erotus on siis tasan ne pikselit jotka nuoli piirtää.
     *
     * Väriä ei lasketa, ja se on mittaus eikä mieltymys: mittarin täyttyessä
     * `drawSpeedPulse` vetää koko ikkunan yli verhon, joka värjää senkin mikä
     * on jo piirretty — nuoli on ruudulla mutta ei enää `#9fe8ff`. Sama
     * täysi mittari joka avaa vilkaisun myös sytyttää sen verhon, joten näitä
     * kahta ei voi nähdä erikseen missään framessa.
     */
    {
      const cv = document.createElement('canvas');
      cv.width = 320; cv.height = 240;
      const g = cv.getContext('2d');
      const shot = (s) => {
        g.clearRect(0, 0, 320, 240);
        s.draw(g);
        return g.getImageData(0, 0, 320, 240).data;
      };
      const diff = (a, b) => {
        let n = 0;
        for (let i = 0; i < a.length; i += 4) {
          if (a[i] !== b[i] || a[i + 1] !== b[i + 1] || a[i + 2] !== b[i + 2]) n++;
        }
        return n;
      };
      /* Nuolen pikselit: sama kuva opettamattomalle ja opetetulle pelaajalle. */
      const arrow = (s) => {
        const was = game.state.taught;
        game.state.taught = {};
        const on = shot(s);
        game.state.taught = { peek: true };
        const off = shot(s);
        game.state.taught = was;
        return diff(on, off);
      };
      /* Täyttä juoksua eikä paikallaan: mittari pysyy täynnä vain vauhdissa
       * (`atSpeed`), ja juuri se on se hetki jossa opetuksen kuuluu näkyä. */
      const sprint = () => { const i = mkInput(); i.held.right = true; i.held.run = true; return i; };
      const running = (id, meter, fresh = true) => {
        if (fresh) reset({ type: null, level: 0 });
        const s = new LevelScene(game, id);
        game.setScene(s);
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        const p = s.player;
        p.pMeter = meter;
        p.vx = 2.5;
        p.onGround = true;
        s.centerCamera();
        s.update(sprint());
        return s;
      };

      const shown = arrow(running(tallId, PMAX));
      const idle = arrow(running(tallId, 0));
      const flat = arrow(running(levelIds().find((id) => !getLevelDef(id).bands), PMAX));

      /* Ensimmäinen vilkaisu kirjaa opetuksen, ja se säilyy seuraavaan kenttään
       * samassa kierroksessa (`fresh = false` säilyttää pelitilan, koska juuri
       * se tila on se joka muistaa). */
      const first = running(tallId, PMAX);
      first.player.pMeter = PMAX;
      first.update(down());
      const learned = !!(game.state.taught && game.state.taught.peek);
      const next = running(tallId, PMAX, false);
      const kept = !!(game.state.taught && game.state.taught.peek) && next.peekReady();

      /* Ja se säilyy levylle asti. `Save.load` levittää oletuksen puuttuvan
       * kentän päälle, joten tämä mittaa nimenomaan `write`in listaa — sitä
       * käsin kirjoitettua kohtaa jossa `doors` kerran unohtui. */
      const saveMod = await import('/src/core/save.js');
      saveMod.Save.write({ ...game.state, taught: { peek: true } });
      const reloaded = !!(saveMod.Save.load().taught || {}).peek;

      expect('vilkaisun opetus näkyy vain kun se on totta, ja loppuu opittuna',
        shown > 5 && idle === 0 && flat === 0 && learned && kept && reloaded,
        `täydellä ${shown} pikseliä, tyhjällä ${idle}, tasakentässä ${flat}, `
        + `vilkaisu kirjattu ${learned}, muistissa seuraavassa kentässä ${kept}, `
        + `tallennuksesta ${reloaded}`);
    }
  }

  /* ------------------- kupla, kuittaus ja vihollisen iho ---------------- */
  /*
   * Kolme omistajan pyyntöä samasta pelituntumasta, ja jokainen mitataan
   * tapahtumana eikä koodirivinä.
   */
  {
    const E4 = await import('/src/entities/enemies.js');
    const gfx4 = await import('/src/gfx/sprites.js');

    /*
     * 1. MAAHANISKU KAATAA KUMOON. *"Ehkä ground stomp KAATAA VIHOLLISEN eli
     *    sprite menee ylösalaisin, jalat sätkivät ilmassa."* (17.8.2026, ja
     *    samalla kupla palasi kaasupallon yksinoikeudeksi.) Väite on että
     *    kävelijä on iskun jälkeen **elossa ja kumossa** — ei poissa eikä
     *    kuplassa.
     */
    reset({ type: 'shroom', level: 2 });
    const s5 = new LevelScene(game, '1-1');
    game.setScene(s5);
    s5.entities = s5.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
    const p5 = s5.player;
    const floor5 = 12;
    /* Yhden ja kahden laatan päähän, koska iskun ulottuvuus on mitattu 44 px
     * plus viisi per voimataso — neljä laattaa oli kuusikymmentäneljä
     * pikseliä eli **ulottuvuuden ulkopuolella**, ja portti mittasi silloin
     * tyhjää eikä vangitsemista. */
    const victims = [1, 2].map((d) => {
      const e = new E4.Walker(s5, (Math.floor(p5.cx / 16) + d) * 16, floor5 * 16);
      e.y = floor5 * 16 - e.h;
      e.active = true;
      e.alwaysActive = true;
      e.spawnGrace = 0;
      s5.add(e);
      return e;
    });
    /* Jalat lattiassa ja pudotus muistissa: `poundImpact` mittaa ulottuvuuden
     * **jalkojen tasolta** (`POUND_LIFT`), joten ilmassa leijuva koekappale
     * mittasi iskun kahdeksankymmentä pikseliä väärästä korkeudesta. */
    p5.x = victims[0].x - 20;
    p5.y = floor5 * 16 - p5.h;
    p5.onGround = true;
    p5.poundFromY = p5.y - 174;
    s5.poundImpact(p5, 1);
    const bubbled = victims.filter((e) => e.bubbled).length;
    const gone = victims.filter((e) => e.remove || e.dying).length;
    const flipped = victims.filter((e) => e.flipped).length;
    expect('maahanisku kaataa kumoon eikä tapa suoralta eikä vangitse kuplaan',
      flipped === victims.length && gone === 0 && bubbled === 0,
      `${victims.length} kävelijää: kumossa ${flipped}, kuplassa ${bubbled},`
      + ` poissa ${gone}`);

    /*
     * 2. VIHOLLISELLA ON IHO, JA SE ON VAIN PINTAA. Sama kolmikko kuin
     *    laatoilla — eroa on, eroa on vähän — **ja lisäksi yksi jota laatoilla
     *    ei ollut**: siluetin on oltava identtinen, koska siitä luetaan
     *    tallattavuus.
     */
    const shotE = () => {
      const c = document.createElement('canvas');
      c.width = 24; c.height = 24;
      return c.getContext('2d', { willReadFrequently: true });
    };
    const paintE = (skin) => {
      const g = shotE();
      g.clearRect(0, 0, 24, 24);
      gfx4.drawWalker(g, 4, 4, 0, 1, false, skin);
      return g.getImageData(0, 0, 24, 24).data;
    };
    const base = paintE(0.1);
    let diffPx = 0;
    let maskPx = 0;
    let changed = 0;
    for (const skin of [0.3, 0.45, 0.6, 0.75, 0.9]) {
      const other = paintE(skin);
      let d = 0;
      for (let i = 0; i < base.length; i += 4) {
        const aOn = base[i + 3] > 8;
        const bOn = other[i + 3] > 8;
        if (aOn !== bOn) maskPx++;
        if (aOn && bOn && (base[i] !== other[i] || base[i + 1] !== other[i + 1])) d++;
      }
      if (d > 0) changed++;
      diffPx = Math.max(diffPx, d);
    }
    const area = 16 * 16;
    /* Kaksisuuntainen raja (17.8.2026). Alaraja nousi kahdesta pikselistä
     * viiteen prosenttiin, koska omistajan huomio oli mitattavissa: vanha iho
     * muutti korkeintaan 6 % pinnasta, ja se on liian vähän erottuakseen
     * juostessa. Yläraja on 75 % eikä 12 % — sävy muuttaa koko rungon kerralla
     * ja se on tarkoitus — mutta se on yhä olemassa, koska "kokonaan toinen
     * kuva" on eri asia kuin "sama otus omalla ihollaan" — mutta yläraja on
     * 90 % eikä 75 %, koska sävynvaihto maalaa rungon kokonaan ja mitattu
     * suurin ero on 83 %. Se mikä oikeasti estää "eri otuksen" on kaksi muuta
     * porttia: siluetin on oltava identtinen (nolla pikseliä, koska siitä
     * luetaan tallattavuus) ja jokaisen sävyn on oltava piirroksen omassa
     * palettirekisterissä, jota `laatikko`-portti ylläpitää käsin. */
    expect('kävelijällä on yksilöllinen pinta, muttei yksilöllistä siluettia',
      changed >= 3 && diffPx > area * 0.05 && diffPx < area * 0.9 && maskPx === 0,
      `erilaisia ${changed}/5, suurin ero ${diffPx} pikseliä (${(100 * diffPx / area).toFixed(1)} %), `
      + `siluettiero ${maskPx} pikseliä`);
  }

  /* ------------------------ maailmaan vaikuttavat ----------------------- */
  /*
   * OLIO JOKA MUUTTAA KENTTÄÄ, ja kolme väitettä siitä.
   *
   * Omistaja 18.8.2026: *"olisi kiva että oliot voisivat reagoida pelaajaan /
   * maailmaan / vaikuttaa maailmaan."* `ENEMY_VERBS`-taulussa luki silloin
   * `maailma: 'ei'` jokaisella yhdeksällätoista lajilla. Nämä kaksi ovat
   * vastaus, ja koska ne kirjoittavat ruudukkoon, ne mitataan samalla
   * tiukkuudella kuin valuva hiekka ja areenan pilarit: **muutos tapahtuu,
   * muutos palautuu, eikä kenttä jää toisenlaiseksi.**
   */
  {
    const E3 = await import('/src/entities/enemies.js');
    const { T: TF } = await import('/src/gfx/tiles.js');

    /* 1. KUURA jäädyttää maan alleen — ja se sulaa. */
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '8-1');
    game.setScene(s);
    s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
    const before = s.grid.map((row) => row.join('')).join('|');
    const floorRow = s.grid.findIndex((row, i) => i > 10 && row[20] && isSolid(row[20]));
    const kuura = new E3.Kuura(s, 20 * 16, (floorRow - 1) * 16);
    kuura.active = true;
    kuura.alwaysActive = true;
    s.add(kuura);
    const idle = mkInput();
    for (let f = 0; f < 120; f++) s.update(idle);
    const frozen = s.frost.size;
    const iceNow = s.grid.flat().filter((c) => c === TF.ICE).length;
    kuura.remove = true;
    for (let f = 0; f < 400; f++) s.update(idle);
    const after = s.grid.map((row) => row.join('')).join('|');
    expect('kuuran jälki jäätyy, sulaa, eikä kenttä jää toisenlaiseksi',
      frozen > 0 && iceNow >= frozen && s.frost.size === 0 && after === before,
      `jäätyi ${frozen} ruutua, jäätä ruudukossa ${iceNow}, sulamisen jälkeen `
      + `${s.frost.size} kesken, ruudukko ${after === before ? 'ennallaan' : 'muuttunut'}`);

    /* 2. KOLIKKOVARAS syö kolikon ja antaa sen takaisin tallattuna. */
    reset({ type: 'shroom', level: 1 });
    const s2 = new LevelScene(game, '1-3');
    game.setScene(s2);
    s2.entities = s2.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
    let coinRow = -1;
    let coinCol = -1;
    for (let ty = 0; ty < s2.h && coinRow < 0; ty++) {
      for (let tx = 30; tx < s2.w - 20; tx++) {
        if (s2.grid[ty][tx] === TF.COIN) { coinRow = ty; coinCol = tx; break; }
      }
    }
    const coins0 = s2.grid.flat().filter((c) => c === TF.COIN).length;
    const thief = new E3.Kolikkovaras(s2, (coinCol - 2) * 16, (coinRow) * 16);
    thief.active = true;
    thief.alwaysActive = true;
    s2.add(thief);
    for (let f = 0; f < 200 && thief.loot === 0; f++) s2.update(idle);
    const coins1 = s2.grid.flat().filter((c) => c === TF.COIN).length;
    /* Uran kokonaisluku eikä säiliön pinta: kolikot ovat aika (18.8.2026) ja
     * säiliö valuu koko ajan, joten "saiko pelaaja saaliin" on kysymys jonka
     * vain kulumaton luku voi vastata. */
    const purse = game.state.coinsTotal || 0;
    /* The haul is read before the stomp, because death empties the belly:
     * `spill` zeroes `loot` precisely so that one hoard cannot pay twice. */
    const ate = thief.loot;
    thief.stomp();
    for (let f = 0; f < 60; f++) s2.update(idle);
    expect('kolikkovaras syö kolikon ja pudottaa saaliin tallattuna',
      ate > 0 && coins1 < coins0 && (game.state.coinsTotal || 0) >= purse + ate - Math.floor(ate / 4),
      `söi ${ate}, kolikoita ${coins0} -> ${coins1},`
      + ` ura ${purse} -> ${game.state.coinsTotal || 0}`);

    /*
     * 2 b. SE PAISUU SILLÄ MITÄ SE ON SYÖNYT — and the three claims here are
     * the three that can break each other.
     *
     * The body grows with the loot and stops at one tile, which is the cap
     * that keeps this species out of the terrain question its own class
     * comment promises to stay out of (`THIEF_CAP`): every corridor a 16x16
     * walker fits through, a full-grown thief fits through too, and its head
     * reaches a one-tile ceiling without ever being inside it. The feet stay
     * on the floor while it grows, because a body that grew from its corner
     * would grow into the ground. And the box is square at every step, because
     * the drawing below is measured against it.
     */
    const grower = new E3.Kolikkovaras(s2, 8 * 16 + 1, 8 * 16 + 2);
    const feet0 = grower.y + grower.h;
    const swell = [];
    let feetMoved = 0;
    let broken = 0;
    for (let n = 0; n <= 10; n++) {
      grower.loot = n;
      grower.fatten();
      swell.push(grower.w);
      if (grower.y + grower.h !== feet0) feetMoved++;
      if (grower.w > 16 || grower.h !== grower.w) broken++;
    }
    expect('kolikkovaras paisuu saaliistaan laatikkoaan myöten, laattaa isommaksi ei',
      swell[0] === 14 && swell[10] === 16 && broken === 0 && feetMoved === 0
      && swell.every((v, i) => i === 0 || v >= swell[i - 1]),
      `koot ${swell.join(',')}, jalat liikkuivat ${feetMoved} kertaa, laatikko rikki ${broken}`);

    /*
     * And the picture keeps the box it was given. Measured rather than
     * asserted, and measured as a *difference*: the art's bounding box against
     * the entity's box has to come out the same at 14 and at 16. A drawing
     * that grew at its own rate would show up here as a margin that moved,
     * which is the one failure that matters — the top edge is where the player
     * reads whether he may jump on this thing.
     *
     * The numbers themselves are the sprite's own habits and not this test's
     * business: the sack hangs a pixel past the box on the carrying side, and
     * `outlined` and `breath` each add one below.
     */
    const gfxT = await import('/src/gfx/sprites.js');
    const CW = 48;
    const cT = document.createElement('canvas');
    cT.width = CW;
    cT.height = CW;
    const gT = cT.getContext('2d', { willReadFrequently: true });
    const OT = 12;
    const margins = (loot, size, facing) => {
      const out = { left: -99, right: -99, top: -99, bottom: -99, h: 0 };
      for (let t = 0; t < 40; t++) {
        gT.clearRect(0, 0, CW, CW);
        gfxT.drawKolikkovaras(gT, OT, OT, t, facing, loot, size);
        const d = gT.getImageData(0, 0, CW, CW).data;
        let x0 = 1e9; let y0 = 1e9; let x1 = -1; let y1 = -1;
        for (let y = 0; y < CW; y++) {
          for (let x = 0; x < CW; x++) {
            if (d[((y * CW) + x) * 4 + 3] < 8) continue;
            if (x < x0) x0 = x;
            if (x > x1) x1 = x;
            if (y < y0) y0 = y;
            if (y > y1) y1 = y;
          }
        }
        out.left = Math.max(out.left, OT - x0);
        out.right = Math.max(out.right, x1 - (OT + size - 1));
        out.top = Math.max(out.top, OT - y0);
        out.bottom = Math.max(out.bottom, y1 - (OT + size - 1));
        out.h = Math.max(out.h, y1 - y0 + 1);
      }
      return out;
    };
    /* The size pairs are asked of the entity rather than written down here,
     * so the drawing is measured with the numbers it is actually drawn with;
     * an invented pair (a full sack in a thin box) would measure a thief that
     * cannot exist. One coin is the smallest haul on the list because the
     * empty-handed thief is the only one carrying no sack at all, and a sack
     * appearing is a different event from a body growing. */
    const pairs = [1, 2, 4, 10].map((n) => {
      grower.loot = n;
      grower.fatten();
      return [n, grower.w];
    });
    const edges = ['left', 'right', 'top', 'bottom'];
    const drift = [];
    const seenM = [];
    for (const facing of [1, -1]) {
      let ref = null;
      for (const [n, size] of pairs) {
        const m = margins(n, size, facing);
        if (m.h !== size) drift.push(`saalis ${n}: piirros ${m.h} px ${size} px:n laatikossa`);
        if (!ref) ref = m;
        else {
          for (const k of edges) {
            if (m[k] !== ref[k]) drift.push(`saalis ${n} suunta ${facing}: ${k} ${m[k]}, ohuena ${ref[k]}`);
          }
        }
        seenM.push(`${n}/${size}${facing < 0 ? '<' : '>'} ${edges.map((k) => m[k]).join(' ')}`);
      }
    }
    expect('paisuneen varkaan piirros pitää laatikkonsa',
      drift.length === 0,
      drift.length ? drift.join('; ') : `vasen/oikea/ylä/ala: ${seenM.join(', ')}`);

    /*
     * 2 c. KUOLLESSAAN SE PAMAHTAA AUKI ja pitää neljäsosan.
     *
     * The burst is `addCoin` with the `?` block's own stagger, so this reads
     * the flights the scene actually queued: one per coin, five frames apart,
     * each from its own point across the body. One coin from one point five
     * times over would be a pile, and the owner asked for a burst.
     *
     * The quarter is rounded down, and the second thief here is that decision
     * measured: three coins in, three coins out. What you lose is what you let
     * it get fat on, never a race you lost by half a second — which is the
     * sentence in the class comment that had to stay true.
     */
    const rich = new E3.Kolikkovaras(s2, 8 * 16 + 1, 8 * 16 + 2);
    s2.add(rich);
    rich.loot = 8;
    rich.fatten();
    s2.coinFlights.length = 0;
    const purseR = game.state.coinsTotal || 0;
    rich.stomp();
    const burst = s2.coinFlights.slice();
    const paid = (game.state.coinsTotal || 0) - purseR;
    const fan = new Set(burst.map((f) => f.x0)).size;
    expect('kuollut varas pamahtaa auki, pitää neljäsosan ja sirottelee loput',
      paid === 6 && rich.loot === 0 && rich.w === 14 && burst.length === 6 && fan === 6
      && burst.every((f, i) => f.wait === i * 5 && f.phase === 'pop'),
      `maksoi ${paid}/8, lentoja ${burst.length}, lähtöpaikkoja ${fan}, `
      + `odotukset ${burst.map((f) => f.wait).join(',')}`);

    const poor = new E3.Kolikkovaras(s2, 9 * 16 + 1, 8 * 16 + 2);
    s2.add(poor);
    poor.loot = 3;
    poor.fatten();
    const purseP = game.state.coinsTotal || 0;
    /* A shell and not a stomp: the same death through the other door, and it
     * pays the same. Before this batch it paid nothing at all. */
    poor.flipDie(1);
    const paidPoor = (game.state.coinsTotal || 0) - purseP;
    expect('kolmen kolikon varas antaa kuoresta takaisin kaikki kolme',
      paidPoor === 3 && poor.loot === 0,
      `maksoi ${paidPoor}/3`);

    /*
     * 3. JA JOKAINEN LAJI SELVIÄÄ PIKATALLENNUKSESTA.
     *
     * Tämä löytyi tätä erää tehdessä ja se oli **hiljainen vika**: `savestate.js`
     * herättää vain ne luokat jotka ovat sen rekisterissä, ja seitsemän lajia
     * oli tullut peliin listan kirjoittamisen jälkeen. Pikatallennus keskellä
     * maailmaa 6 tai 7 palautti kentän ilman niitä — mikään ei kaatunut, jokin
     * vain puuttui. Nyt lista kävellään merkeistä eikä muistista.
     */
    const { captureState, restoreState } = await import('/src/core/savestate.js');
    const lost = [];
    for (const [ch, make] of Object.entries(E3.ENEMY_CHARS)) {
      reset({ type: 'shroom', level: 1 });
      const s3 = new LevelScene(game, '1-1');
      game.setScene(s3);
      s3.entities = s3.entities.filter((e) => e.kind !== 'enemy');
      const made = make(s3, 20, 11, 0);
      made.active = true;
      s3.add(made);
      const name = made.constructor.name;
      captureState(game, 0);
      restoreState(game, 0);
      const back = game.scene.entities.some((e) => e.constructor.name === name);
      if (!back) lost.push(`${ch} ${name}`);
    }
    expect('jokainen vihollislaji selviää pikatallennuksesta',
      lost.length === 0,
      lost.length ? `katosi: ${lost.join(', ')}`
        : `${Object.keys(E3.ENEMY_CHARS).length} merkkiä, kaikki palasivat`);
  }

  /* --------------------------- laattojen ihot --------------------------- */
  /*
   * SAMA ELEMENTTI, ERI YKSILÖ — ja tasapaino mitataan eikä katsota.
   *
   * Omistajan pyyntö: *"etsi tasapaino, jossa pelaaja tunnistaa heti elementin
   * samaksi, mutta niissä on kuitenkin pieni vivahde-ero."* Tasapaino on kaksi
   * lukua samasta mittauksesta — **eroa on** ja **eroa on vähän** — ja
   * kolmantena se joka tekee siitä käsityötä eikä kohinaa: sama putki näyttää
   * samalta joka kerta.
   *
   * Rajat: 1 % on se raja jonka alle jäävä ero ei näy edes vierekkäin, ja 12 %
   * on se jonka yli mennessä kaksi putkea eivät enää lue samaksi esineeksi.
   * Mitattu putkien pintakuviosta: sauma, niitit, pultit ja kolhu ovat yhteensä
   * noin kymmenesosa laatan pikseleistä, joten koko vaihteluvara mahtuu
   * yksityiskohtiin ilman että pohjaväri liikkuu lainkaan.
   */
  {
    const tiles = await import('/src/gfx/tiles.js');
    const shot = () => {
      const c = document.createElement('canvas');
      c.width = 16; c.height = 16;
      return { c, g: c.getContext('2d', { willReadFrequently: true }) };
    };
    /* Mitataan **runkolaatta** eikä suuta, ja se on korjaus mittaukseen eikä
     * kuvaan: suun alla on vain muutama rivi kuilua, joten sauma, niitit ja
     * kolhu — eli koko se pinta jolla vaihtelu elää — jäävät sen ulkopuolelle.
     * Mitattuna suusta ero oli 0,0 % kahdeksasta putkesta seitsemällä, ja
     * silti putket eroavat toisistaan ruudulla. Väärä laatta, ei väärä väite. */
    const paint = (tx, tick, ch = tiles.T.PIPE_BL) => {
      const { c, g } = shot();
      g.clearRect(0, 0, 16, 16);
      tiles.drawTile(g, ch, 0, 0, 'grass', tx, 12, tick, tiles.T.PIPE_TL, {});
      return g.getImageData(0, 0, 16, 16).data;
    };
    const diff = (a, b) => {
      let n = 0;
      for (let i = 0; i < a.length; i += 4) {
        if (a[i] !== b[i] || a[i + 1] !== b[i + 1] || a[i + 2] !== b[i + 2]) n++;
      }
      return (n * 100) / (a.length / 4);
    };
    const base = paint(4, 0);
    const right = paint(5, 0, tiles.T.PIPE_BR);
    const others = [6, 8, 10, 12, 14, 16, 18, 20].map((tx) => diff(base, paint(tx, 0)))
      .concat([7, 9, 11, 13].map((tx) => diff(right, paint(tx, 0, tiles.T.PIPE_BR))));
    const changed = others.filter((d) => d > 0.5);
    const loudest = Math.max(...others);
    expect('kaksi putkea eroaa toisistaan, muttei niin että ne olisivat eri esineitä',
      changed.length >= 3 && loudest > 1 && loudest < 12,
      `erot ${others.map((d) => d.toFixed(1)).join(' ')} % — erilaisia ${changed.length}/${others.length}, `
      + `suurin ${loudest.toFixed(1)} %`);

    /* Sama putki, sama kuva: iho on paikan funktio eikä kellon eikä arvan. */
    expect('sama putki näyttää samalta joka kerta',
      diff(paint(4, 0), paint(4, 0)) === 0 && diff(paint(9, 30), paint(9, 30)) === 0,
      'kaksi piirtoa samasta putkesta samalla framella ovat identtiset');

    /*
     * Ja pikkuanimaatio on **pikku**: kiilto liikkuu saumaa pitkin, ja jos se
     * muuttaisi enemmän kuin kourallisen pikseleitä, se lukisi merkkinä
     * (DESIGN.md kohta 8) eikä pintana. Mitataan koko kierros kahdessadassa
     * framessa ja otetaan suurin muutos peräkkäisten framejen välillä.
     */
    let biggest = 0;
    let moved = 0;
    /* Koko kierros ja vähän yli: kiillon jakso on 420 framea eli seitsemän
     * sekuntia, ja jokaisella putkella on oma vaiheensa. Kahdensadan framen
     * ikkuna mittasi siis vaihetta eikä kiiltoa — mitattuna 0/200. */
    let prev = paint(4, 0);
    for (let t = 1; t <= 460; t += 1) {
      const now = paint(4, t);
      const d = diff(prev, now);
      if (d > 0) moved++;
      biggest = Math.max(biggest, d);
      prev = now;
    }
    expect('putken kiilto on pinta eikä merkki: se liikkuu, muttei huuda',
      moved > 0 && biggest < 3,
      `muuttuvia frameja ${moved}/460, suurin muutos ${biggest.toFixed(1)} % laatasta`);

    /*
     * JA SAMA VAATIMUS JOKAISELLE LAATALLE JOLLA ON IHO.
     *
     * Putki oli ensimmäinen; kivi, lauta ja maa saivat saman kohtelun, koska
     * ne ovat ne kolme joita kentässä on eniten. Väite on sama kolmikko —
     * **eroa on, eroa on vähän, ja se on sama joka kerta** — mutta mitattuna
     * jokaiselta erikseen, koska jokaisella on eri määrä pintaa jolla vaihdella.
     */
    const kinds = [
      { name: 'kivi', ch: tiles.T.HARD, above: ' ' },
      { name: 'lauta', ch: tiles.T.PLATFORM, above: ' ' },
      { name: 'maa', ch: tiles.T.GROUND, above: ' ' },
      { name: 'tiili', ch: tiles.T.BRICK, above: ' ' },
    ];
    const skinRows = [];
    for (const k of kinds) {
      const draw = (tx, tick) => {
        const { c, g } = shot();
        g.clearRect(0, 0, 16, 16);
        tiles.drawTile(g, k.ch, 0, 0, 'grass', tx, 9, tick, k.above, {});
        return g.getImageData(0, 0, 16, 16).data;
      };
      const b = draw(3, 0);
      const ds = [5, 7, 9, 11, 13, 15, 17, 19].map((tx) => diff(b, draw(tx, 0)));
      const changed = ds.filter((d) => d > 0.5).length;
      const worst = Math.max(...ds);
      const stable = diff(draw(3, 0), draw(3, 0)) === 0;
      skinRows.push({ name: k.name, changed, worst, stable });
    }
    /* Maan katto on 24 % eikä 12 %, ja se on mitattu ero eikä löysennys: maa on
     * ainoa näistä jonka **koko yläreuna on kasvillisuutta** — korret,
     * tuppaat ja niiden varjot ovat laatan pinta-alasta viidennes, ja ne ovat
     * juuri se osa joka saa vaihdella. Kivi, lauta ja tiili vaihtelevat
     * yksityiskohdissa, ja niiden katto on se sama 12 % kuin putkella. */
    const roof = (name) => (name === 'maa' ? 24 : 12);
    expect('jokainen yleinen laatta on yksilö, muttei eri palikka',
      skinRows.every((r) => r.changed >= 3 && r.worst > 1 && r.worst < roof(r.name) && r.stable),
      skinRows.map((r) => `${r.name} ${r.changed}/8 erilaista, suurin ${r.worst.toFixed(1)} %`
        + `${r.stable ? '' : ', EI VAKAA'}`).join(' · '));

    /*
     * Ja heinä heiluu — mutta vain heinä. Maalaatan **kiinteä osa** (rivit
     * 0…15 laatan sisällä) ei saa liikkua lainkaan, koska se on se pinta jolla
     * seistään; liike on sen yläpuolella olevissa korsissa, jotka piirtyvät
     * laatan ulkopuolelle. Mitataan molemmat erikseen samasta kuvasta.
     */
    const grass = (tick) => {
      const { c, g } = shot();
      c.height = 20;
      g.clearRect(0, 0, 16, 20);
      tiles.drawTile(g, tiles.T.GROUND, 0, 4, 'grass', 6, 9, tick, ' ', {});
      return g.getImageData(0, 0, 16, 20).data;
    };
    let bladesMoved = 0;
    let bodyMoved = 0;
    const g0 = grass(0);
    for (let t = 6; t <= 180; t += 6) {
      const gt = grass(t);
      for (let i = 0; i < g0.length; i += 4) {
        if (g0[i] === gt[i] && g0[i + 1] === gt[i + 1] && g0[i + 2] === gt[i + 2]) continue;
        const row = Math.floor((i / 4) / 16);
        if (row < 4) bladesMoved++;
        else bodyMoved++;
      }
    }
    expect('heinä heiluu laatan yläpuolella, eikä maa liiku lainkaan',
      bladesMoved > 0 && bodyMoved === 0,
      `korsia liikkui ${bladesMoved} pikseliä, maata ${bodyMoved}`);
  }

  /* ------------------------------ näppäimet ----------------------------- */
  /*
   * ENTER ON AINA VALINTA, ja se mitataan **ruuduilta eikä taulukosta**.
   *
   * Omistajan raportti 17.8.2026: *"näppäimet ovat menuissa välillä outoja,
   * mielestäni enter voisi aina olla select."* Ja niin se oli: `Enter` oli
   * `start`, ja `start` tarkoitti kolmea eri asiaa eri ruuduilla — valitse
   * (alkuruutu, kortit, pistetaulu), peru (vaikeustaso, päivän pieru, jako) ja
   * käytä varaesine (kartta). Yksi taulukkorivi ei todista että se on ohi;
   * kolme ruutua todistaa.
   *
   * Näppäin painetaan oikeana tapahtumana `window`iin asti, koska juuri se
   * ketju — `event.code` → `KEYMAP` → `Input.pressed` → kohtaus — on se jossa
   * vika oli.
   */
  {
    const { WorldMapScene } = await import('/src/scenes/worldmap.js');
    const { TitleScene } = await import('/src/scenes/title.js');
    /* Kymmenen framea ennen painallusta, ja se on ruutujen oma sääntö eikä
     * varovaisuutta: valikot vartioivat ensimmäiset kuusi framea (`tick < 6`)
     * jottei edellisen ruudun viimeinen painallus valitse tällä. Kaksi framea
     * mittasi siis vartiointia eikä näppäintä. */
    const settleUI = (n = 10) => { for (let f = 0; f < n; f++) game.step(); };
    /* Kartta tarvitsee enemmän: maailman nimilappu (`bannerTimer`) syö
     * ensimmäisen painalluksen tarkoituksella, jotta edellisen ruudun Enter ei
     * käynnistä kenttää. Mitattuna kymmenen framea mittasi siis lappua. */
    const MAP_SETTLE = 160;
    const tap = (code) => {
      dispatchEvent(new KeyboardEvent('keydown', { code }));
      game.step();
      dispatchEvent(new KeyboardEvent('keyup', { code }));
      game.step();
    };

    reset();
    game.toTitle();
    settleUI();
    const fromTitle = game.scene.constructor.name;
    tap('Enter');
    const afterTitle = game.scene.constructor.name;

    /* Kartalla kursori pannaan **kentän** solmuun: aloitussolmu ei ole kenttä,
     * eikä "Enter ei tehnyt mitään aloitusruudulla" ole väite mistään. */
    reset();
    game.state.world = 0;
    const firstLevel = WORLDS[0].nodes.find((n) => n.level);
    game.state.node = firstLevel.id;
    game.setScene(new WorldMapScene(game));
    settleUI(MAP_SETTLE);
    tap('Enter');
    const afterMap = game.scene.constructor.name;

    /* Ja se toinen puoli: Escape perääntyy eikä valitse. Alkuruudulta ei ole
     * mihin perääntyä, joten tämä mitataan vaikeustasoruudulta, joka on se
     * ruutu jolla Enter ennen perui. */
    reset();
    game.chooseDifficulty();
    settleUI();
    const inChooser = game.scene.constructor.name;
    tap('Enter');
    const chose = game.scene.constructor.name;
    reset();
    game.chooseDifficulty();
    settleUI();
    tap('Escape');
    const backed = game.scene.constructor.name;

    /*
     * JA KENTÄSSÄ ENTER ON TAUKO. Omistaja löysi tämän samana iltana kun
     * edellinen versio antoi Enterin hypylle: *"nyt enter on hyppy myös pelin
     * sisällä eli ei toimi pausena."* Kolme tapausta, kolme mittausta —
     * kentässä tauko, taukovalikossa valinta, muualla valinta.
     */
    reset();
    const lvl = new LevelScene(game, '1-1');
    game.setScene(lvl);
    settleUI();
    const beforePause = game.paused;
    tap('Enter');
    const paused = game.paused;
    /* Ja taukovalikossa sama näppäin valitsee: kursori on JATKAssa, joten
     * valinta purkaa tauon. Se on myös se tapaus joka rikkoutuisi hiljaa jos
     * käännös tehtäisiin väärässä järjestyksessä. */
    tap('Enter');
    const resumed = !game.paused;
    expect('Enter on tauko kentässä ja valinta taukovalikossa',
      beforePause === false && paused === true && resumed === true,
      `ennen ${beforePause}, painalluksen jälkeen ${paused}, toisen jälkeen ${!resumed}`);

    expect('Enter valitsee jokaisella ruudulla, ja Escape perääntyy',
      fromTitle === 'TitleScene' && afterTitle !== 'TitleScene'
      && afterMap !== 'WorldMapScene'
      && inChooser === 'DifficultyScene' && chose !== 'DifficultyScene'
      && backed === 'TitleScene',
      `alkuruutu ${fromTitle}->${afterTitle}, kartta ->${afterMap}, `
      + `vaikeustaso ${inChooser}->${chose}, Escape ->${backed}`);

    /* Kartan varaesine on `run`issa, ja se on mitattava erikseen: se on se
     * toiminto joka Enterin tieltä siirrettiin, ja siirretty toiminto jota
     * mikään ei enää kutsu on huonompi kuin ennallaan jätetty. */
    reset();
    game.state.world = 0;
    game.state.node = firstLevel.id;
    game.state.reserve = 'shroom';
    const map = new WorldMapScene(game);
    game.setScene(map);
    settleUI(MAP_SETTLE);
    tap('KeyX');
    expect('kartalla X käyttää varaesineen',
      game.state.reserve === null,
      `varasto ${game.state.reserve === null ? 'tyhjeni' : game.state.reserve}`);
    game.toTitle();
    void TitleScene;
  }

  /* ------------------------------- attract ----------------------------- */
  {
    const { DemoScene } = await import('/src/scenes/demo.js');
    const key = (code) => {
      dispatchEvent(new KeyboardEvent('keydown', { code }));
      dispatchEvent(new KeyboardEvent('keyup', { code }));
    };
    const storage = () => {
      const all = {};
      for (let i = 0; i < localStorage.length; i++) {
        all[localStorage.key(i)] = localStorage.getItem(localStorage.key(i));
      }
      return JSON.stringify(all);
    };
    const toDemo = () => {
      game.toTitle();
      for (let f = 0; f < 1300 && !(game.scene instanceof DemoScene); f++) game.step();
      return game.scene instanceof DemoScene;
    };

    reset();
    game.toTitle();
    let startedAt = -1;
    for (let f = 0; f < 2000 && startedAt < 0; f++) {
      game.step();
      if (game.scene instanceof DemoScene) startedAt = f + 1;
    }
    /* Kenttä on `esittely` eikä `1-1`, ja se on koko kolmannen löydettävyyden
     * osan ehto: demo tekee tempun kentässä jota ei ole pelissä, joten verbi
     * opetetaan paljastamatta paikkaa. Ks. `src/data/demo-level.js`. */
    expect('the title screen starts playing by itself when left alone',
      startedAt > 60 && startedAt <= 1300 && game.scene.level.id === 'esittely',
      `${startedAt} framea, ${game.scene.level && game.scene.level.id}`);

    const back = [];
    for (const code of ['KeyZ', 'KeyQ']) {
      if (!toDemo()) { back.push(`${code}:ei esittelyä`); continue; }
      key(code);
      game.step();
      back.push(`${code}:${game.scene.constructor.name}`);
    }
    expect('any key ends the demo within a frame',
      back.every((r) => r.endsWith('TitleScene')), back.join(' '));

    reset();
    const before = storage();
    const lives = game.state.lives;
    const score = game.state.score;
    const started = toDemo();
    /*
     * Kuolema tapetaan tässä eikä odoteta sitä, ja se on tarkennus eikä
     * löysennys.
     *
     * Tässä ajettiin demoa kunnes botti sattui kuolemaan, ja lupaus todistui
     * vain jos se sattui. Esittelykenttä on lyhyt ja botti pääsee sen läpi —
     * mitattu 920 framea maaliin — joten sattuma kääntyi toisin päin ja portti
     * olisi alkanut kaatua siitä että demo onnistuu. Lupaus on silti sama:
     * botin kuolema päättää demon eikä peliä. Nyt se kysytään suoraan.
     */
    let frames = 0;
    let died = false;
    if (started) {
      game.scene.level.player.die('testi');
      for (; frames < 600 && game.scene instanceof DemoScene; frames++) {
        game.step();
        game.render();
        if (game.scene instanceof DemoScene && game.scene.level.state === 'dead') died = true;
      }
    }
    expect('the demo survives the bot dying and returns to the title',
      started && died && game.scene.constructor.name === 'TitleScene',
      `${frames} framea, kuoli ${died}, ${game.scene.constructor.name}`);

    /* Ja sama lupaus toisesta päästä: demo joka pääsee maaliin palauttaa koneen
     * yhtä lailla. `stand.finishLevel` on demon oma, joten läpäisy ei saa
     * vuotaa pelaajan omaan sen enempää kuin kuolemakaan. */
    reset();
    const cleared = toDemo();
    let clearFrames = 0;
    for (; clearFrames < 6000 && game.scene instanceof DemoScene; clearFrames++) {
      game.step();
      game.render();
    }
    expect('the demo hands the machine back when the bot finishes the level',
      cleared && game.scene.constructor.name === 'TitleScene',
      `${clearFrames} framea, ${game.scene.constructor.name}`);
    expect('the demo writes nothing and spends nothing',
      storage() === before && game.state.lives === lives && game.state.score === score,
      `${lives}/${score} -> ${game.state.lives}/${game.state.score}`);

    if (toDemo()) game.scene.level.update = () => { throw new Error('botti hajosi'); };
    game.step();
    game.render();
    expect('an error inside the demo ends the demo, not the game',
      game.scene.constructor.name === 'TitleScene', game.scene.constructor.name);
    game.toTitle();

    /* ------------------------ demo näyttää tempun ------------------------ */
    /*
     * Salaisuuksien löydettävyyden kolmas osa, ja se mitataan **tapahtumana**:
     * "demo on olemassa" ei todista mitään, ja "demossa on lämpöputki" ei
     * myöskään — kysymys on meneekö botti siitä sisään ja tuleeko se takaisin.
     * Kaista luetaan jaloista samalla laskutoimituksella kuin `LevelScene`
     * itse tekee, eli 1 on pinta ja 2 on luola.
     */
    {
      reset();
      const { TILE: TZ } = await import('/src/gfx/tiles.js');
      const demo = new DemoScene(game);
      demo.enter();
      const bands = demo.level.def.bands;
      const bandOf = () => {
        const p = demo.level.player;
        return Math.floor(Math.floor((p.y + p.h - 1) / TZ) / bands.rows);
      };
      const path = [];
      let down = -1;
      let up = -1;
      for (let f = 0; f < 3600 && !demo.done; f++) {
        demo.update();
        const b = bandOf();
        if (path[path.length - 1] !== b) {
          path.push(b);
          if (down < 0 && b === 2) down = f;
          else if (down >= 0 && up < 0 && b === 1) up = f;
        }
      }
      demo.dispose();
      expect('esittely tekee tempun: putkesta alas ja samaa tietä takaisin',
        demo.tricks >= 2 && down > 0 && up > down && path.join('') === '121',
        `temppuja ${demo.tricks}, kaistat ${path.join('->')}, `
        + `alas framella ${down}, ylös framella ${up}`);
      /* Sama lupaus kuin muullakin demolla: temppu kirjoittaa kentän tilaan,
       * eikä kentän tila ole pelaajan. Kaistan löytyminen on tavallisesti
       * salaisuuskirjanpitoa (`noteSecret`), joten tämä on se rivi joka
       * varmistaa ettei esittely kerää salaisuuksia pelaajan puolesta. */
      const secrets = game.state.secrets && game.state.secrets.esittely;
      expect('esittelyn löytämät kaistat eivät päädy pelaajan kirjanpitoon',
        !secrets, secrets ? JSON.stringify(secrets) : 'ei merkintöjä');
    }

    /*
     * Esittelykenttä ei ole pelin sisällysluettelossa, joten se ei tule
     * mukaan siihen lohkoon joka ajaa säännöt ja botin joka kentälle. Se on
     * oikein — se ei ole osa opetusjärjestystä — mutta se on silti kenttä jonka
     * pelaaja näkee, ja näyteikkuna jonka läpi ei pääse on huonompi mainos kuin
     * ei näyteikkunaa lainkaan. Siis samat säännöt, sama botti, tässä.
     */
    {
      const { demoLevel } = await import('/src/data/demo-level.js');
      const { validateLevel } = await import('/src/data/rules.js');
      const { runGround } = await import('/tools/level-bot.js');
      const { isSolid } = await import('/src/gfx/tiles.js');
      const budget = await (await fetch('/tools/jump-budget.json')).json();
      const def = demoLevel();
      const problems = validateLevel(def.rows, budget);
      reset({ type: null, level: 0 });
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const s = new LevelScene(game, def.id, def);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      const got = runGround(s, isSolid, 7000, () => finished);
      expect('esittelykenttä läpäisee samat säännöt ja saman botin kuin pelin kentät',
        problems.length === 0 && got.cleared,
        `säännöt: ${problems.join(' / ') || 'ei huomautuksia'}, `
        + `botti: ${got.cleared ? 'läpi' : `jumissa ${got.reach} %`}`);
      game.toTitle();
    }
  }

  /* ----------------------------- suolimato ------------------------------ */
  /*
   * Kahdeksas variantti, ja sen väite on **missä** eikä **milloin**: se
   * kaivautuu lattiaan siksi aikaa kun kruunu on päässä, ja nousee jossain
   * muualla. Kolme mittausta, ja jokainen on tapahtuma:
   *
   *   1. kruunu päässä = maan alla, ja matka näkyy sarakkeina;
   *   2. maan alla se ei satuta eikä siihen voi osua;
   *   3. nousukohta on vähintään `BURROW_CLEAR` laattaa pelaajasta — sama
   *      turvaväli ja sama syy kuin areenan pilareilla.
   */
  {
    const E2 = await import('/src/entities/enemies.js');
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '8-5');
    game.setScene(s);
    const worm = s.entities.find((e) => e instanceof E2.Boss);
    const idle = mkInput();
    for (let f = 0; f < 90 && !(worm.onGround && f > 2); f++) s.update(idle);
    const startX = worm.cx;
    const surfaceY = worm.y;
    worm.spikePhase = 'spiky';
    worm.spikeTimer = 999;
    for (let f = 0; f < 90; f++) s.update(idle);
    const under = worm.under;
    const moved = Math.abs(worm.cx - startX);
    const sank = worm.y - surfaceY;
    const cannotTouch = worm.harmless;
    /* Nousu tilataan vaihtamalla vaihe, kuten pelissäkin: kruunu laskee ja
     * runko on pinnalla samalla framella. */
    s.player.x = worm.cx - 8;
    worm.spikePhase = 'open';
    worm.spikeTimer = 999;
    s.update(idle);
    const gap = Math.abs(worm.cx - s.player.cx) / 16;
    expect('suolimato kaivautuu kruunun ajaksi, ei satuta maan alla, eikä nouse jalkojen alta',
      under && moved > 16 && sank > 16 && cannotTouch && !worm.under && gap >= 3,
      `maan alla ${under}, siirtyi ${Math.round(moved)} px, vajosi ${Math.round(sank)} px, `
      + `vaaraton ${cannotTouch}, nousi ${gap.toFixed(1)} laatan päähän`);
  }

  /* --------------------------- areenapomo ------------------------------- */
  /*
   * ROADMAP kohta 4: pomo järjestää kentän uusiksi. Kolme hyväksymiskriteeriä,
   * kolme mittausta — ja **validointi on se joka piti ratkaista ensin**, koska
   * `rules.js` katsoo kentän lähtötilaa eikä yksikään portti tähän asti
   * katsonut ruudukkoa joka muuttuu kesken taistelun.
   *
   * Vastaus ei ole ajaa botti kaikilla 2^n järjestelyllä vaan tehdä
   * järjestelyistä sellaisia ettei niiden lukumäärällä ole väliä: pilari on
   * yksi sarake leveä ja kaksi laattaa korkea, eli askelma eikä este. Se on
   * rakenteellinen argumentti, ja siksi tässä mitataan **sekä ehdot että
   * pahin tapaus** — argumentti ilman mittausta on mielipide.
   */
  {
    const { runGround } = await import('/tools/level-bot.js');
    const { isSolid: solidTile, T: TT, TILE: TS } = await import('/src/gfx/tiles.js');
    const forts = levelIds().filter((id) => /-F$/.test(id));
    const shapes = [];
    const bad = [];
    const stuck = [];
    let restored = 0;
    for (const id of forts) {
      reset({ type: null, level: 0 });
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      const slots = s.pillars || [];
      shapes.push(`${id}:${slots.length}`);

      /* 1. EHDOT. Jokainen paikka on tasaisella lattialla, sen yllä on tilaa
       *    isoimmalle keholle, se on kaukana ovesta ja areenan alusta, eikä
       *    kaksi ole vierekkäin. */
      let door = -1;
      for (let tx = s.arenaCol || 0; tx < s.w && door < 0; tx++) {
        for (let ty = 0; ty < s.h; ty++) if (s.tileAt(tx, ty) === TT.DOOR) { door = tx; break; }
      }
      slots.forEach((slot, i) => {
        if (!solidTile(s.tileAt(slot.tx, slot.floor))) bad.push(`${id}: ${slot.tx} ei ole lattialla`);
        for (let d = 1; d <= 3; d++) {
          if (s.tileAt(slot.tx, slot.floor - d) !== TT.EMPTY) bad.push(`${id}: ${slot.tx} ahdas`);
        }
        if (door >= 0 && door - slot.tx < 6) bad.push(`${id}: ${slot.tx} liian lähellä ovea`);
        if (slot.tx - (s.arenaCol || 0) < 6) bad.push(`${id}: ${slot.tx} liian lähellä alkua`);
        if (i > 0 && slot.tx - slots[i - 1].tx < 6) bad.push(`${id}: ${slot.tx} liian lähellä edellistä`);
      });

      /* 2. PAHIN TAPAUS. Kaikki pystyssä, ovi auki, botti voimatasolla 0
       *    areenan alusta ovelle. */
      for (const slot of slots) {
        slot.state = 'warn';
        slot.timer = 0;
      }
      s.player.x = (s.arenaCol + 2) * TS;
      s.updatePillars();
      const raised = slots.filter((slot) => slot.state === 'up').length;
      if (raised !== slots.length) bad.push(`${id}: nousi ${raised}/${slots.length}`);
      s.bossDefeated = s.tick + 1;
      const got = runGround(s, solidTile, 7000, () => finished);
      if (!got.cleared) stuck.push(`${id} ${got.reach} %`);

      /* 3. PALAUTUVUUS. Sama huone kuin lähtiessä, laatta laatalta. */
      const before = new LevelScene(game, id).grid.map((row) => row.join('')).join('|');
      s.dropPillars();
      if (s.grid.map((row) => row.join('')).join('|') === before) restored++;
    }
    expect('jokaisessa linnakkeessa on areenapaikkoja ja jokainen niistä kelpaa',
      forts.length > 0 && shapes.every((r) => Number(r.split(':')[1]) > 0) && bad.length === 0,
      `${shapes.join(' ')}${bad.length ? ` — ${bad.slice(0, 3).join(', ')}` : ''}`);
    expect('kaikki pilarit pystyssä, ovelle pääsee yhä voimatasolla 0',
      stuck.length === 0,
      stuck.length ? stuck.join(', ') : `${forts.length} linnaketta läpi`);
    expect('pomon kaatuminen palauttaa areenan laatta laatalta',
      restored === forts.length, `${restored}/${forts.length} palautui`);
  }

  /* ------------------- ketjutappo, pomppu, tanko, maali ----------------- */
  /*
   * Neljä muutosta jotka tulivat suoraan pelistä, ja jokainen mitataan
   * tapahtumana: mitä pelaaja sai, ei mitä koodissa lukee.
   */
  {
    const enemies = await import('/src/entities/enemies.js');
    const { TILE } = await import('/src/gfx/tiles.js');

    /** Kenttä jossa on tasainen lattia ja pelaaja ilmassa sen yllä. */
    const arena = (power = { type: 'shroom', level: 2 }) => {
      reset(power);
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    /** Kävelijä annettuun ruutuun, heti hereillä. */
    const walkerAt = (s, tx, ty) => {
      const e = new enemies.Walker(s, tx * TILE, ty * TILE);
      e.x = tx * TILE;
      e.y = ty * TILE - e.h;
      e.vx = 0;
      e.active = true;
      e.alwaysActive = true;
      e.spawnGrace = 0;
      s.add(e);
      return e;
    };

    /*
     * 1. KETJU: sama vihollinen maksaa enemmän kun se on ketjussa toinen.
     *
     * Kaksi kävelijää vierekkäin, pelaaja pudotetaan ensimmäisen päälle ja
     * heti perään toisen. Väite on suhde eikä absoluuttinen luku: kerroin on
     * viholliskohtaiseen pistearvoon, joten testi ei tiedä `Walker.score`ä
     * eikä sen tarvitse.
     */
    {
      const s = arena();
      const floor = 14;
      const a = walkerAt(s, 6, floor);
      const b = walkerAt(s, 8, floor);
      const p = s.player;
      /* Keho **päällekkäin** vihollisen kanssa ja putoamassa: `collisions`
       * vaatii osuman, ja kaksi pikseliä sen yläpuolella ei ole osuma. Sama
       * virhe kirjattiin tähän kerran mitattuna (1. 0, 2. 0). */
      const land = (e) => {
        p.x = e.x;
        p.y = e.y - p.h + 3;
        p.vy = 3;
        p.onGround = false;
        s.collisions();
      };
      const score0 = game.state.score;
      land(a);
      const first = game.state.score - score0;
      const mid = game.state.score;
      land(b);
      const second = game.state.score - mid;
      /* Ja maahan laskeutuminen katkaisee ketjun. Keho pudotetaan oikeasti
       * lattialle ja annetaan moottorin todeta kosketus — `onGround = true`
       * käsin asetettuna on edellisen framen väite, ja pelaajan oma päivitys
       * kumoaa sen ennen kuin kukaan lukee sitä. */
      p.x = 6 * TILE;
      p.y = floor * TILE - p.h;
      p.vy = 0;
      for (let f = 0; f < 8; f++) s.update(mkInput());
      const landed = p.onGround;
      const c = walkerAt(s, 10, floor);
      const before = game.state.score;
      land(c);
      const third = game.state.score - before;
      /* Suhde on kakkosen potenssi (`CHAIN` = [1, 2, 4, …], ks.
       * `src/core/points.js`), eli toinen tappo maksaa kaksinkertaisesti.
       * Luku oli neljä 18.8.2026 asti, jolloin taulukko vaihtui neliöistä
       * kakkosen potensseihin — sama väite, uusi asteikko. */
      expect('ilmassa ketjutettu tallaus maksaa enemmän, ja maakosketus katkaisee ketjun',
        first > 0 && second === first * 2 && third === first,
        `1. ${first}, 2. ${second}, maahan käynnin jälkeen ${third}`
        + `, maassa ${landed}`);
    }

    /*
     * 2. KUORELLA ON OMA KETJUNSA. Rivissä seisova jono on oma palkintonsa, ja
     *    laskuri lähtee potkusta — ei pelaajan kaaresta.
     */
    {
      const s = arena();
      const floor = 14;
      const shell = new enemies.ShellGuy(s, 5 * TILE, floor * TILE);
      shell.x = 5 * TILE;
      shell.y = floor * TILE - shell.h;
      shell.active = true;
      shell.alwaysActive = true;
      s.add(shell);
      shell.toShell();
      const row = [7, 9, 11].map((tx) => walkerAt(s, tx, floor));
      const paid = [];
      shell.kick(1);
      for (const target of row) {
        const before = game.state.score;
        shell.x = target.x;
        shell.y = target.y;
        s.shellSweep(shell);
        paid.push(game.state.score - before);
      }
      /* Kertoimet ovat kakkosen potensseja (`CHAIN`), eli 1 · 2 · 4. */
      expect('potkaistun kuoren jono maksaa nousevasti, ja ketju alkaa potkusta',
        paid[0] > 0 && paid[1] === paid[0] * 2 && paid[2] === paid[0] * 4,
        paid.join(' -> '));
    }

    /*
     * 3. LÄPÄISTY KENTTÄ EI SATUTA. Omistajan raportti: kuori kimposi takaisin
     *    maalin jälkeen, kesken sitä kävelyä jota ei enää ohjata.
     */
    {
      const s = arena();
      const p = s.player;
      const powerBefore = p.power.level;
      s.completeLevel('shroom');
      const hurt = p.hurt('enemy');
      expect('maalin jälkeen mikään ei enää satuta',
        hurt === false && p.power.level === powerBefore && !p.dying,
        `osui ${hurt}, voimataso ${powerBefore} -> ${p.power.level}, tila ${s.state}`);
    }

    /*
     * 4. TANGON KORKEUS ON PALKINTO. Kaksi tarttumista samaan tankoon, alhaalta
     *    ja huipulta: pisteiden pitää erota ja huipun antaa tähti.
     */
    {
      const grab = (frac) => {
        const s = arena();
        const g = s.goal;
        if (!g) return null;
        s.time = 0;                          // aikabonus pois mittauksen tieltä
        const pole = { x: g.x + 4, y: g.y - 8, w: 10, h: 6 * TILE + 8 };
        const p = s.player;
        p.x = pole.x;
        p.y = pole.y + pole.h * (1 - frac) - p.h;
        const before = game.state.score;
        s.grabGoal(pole);
        return { points: game.state.score - before, card: s.wonCard };
      };
      const low = grab(0.02);
      const high = grab(0.99);
      expect('tangon korkeus maksaa, ja huipulta saa tähden',
        !low || (high.points > low.points && high.card === 'star'),
        low ? `alhaalta ${low.points} (${low.card}), huipulta ${high.points} (${high.card})`
          : 'kentässä ei ole tankoa');
    }

    /*
     * 5. JA POMPPU ON ISOMPI KUIN OMA HYPPY. Mitattu nousu, ei vakion arvo:
     *    vakio voi vaihtua ilman että kaari muuttuu, ja kaari on se mitä
     *    pelaaja tuntee.
     */
    {
      /* Nousu mitataan samalla tavalla kummallekin: sama kenttä, sama lattia,
       * nappi pohjassa koko kaaren ajan. Pelaajalla ei ole `jump()`-metodia —
       * hyppy syntyy syötteestä — joten vertailukaari ajetaan syötteellä ja
       * pomppu kutsumalla sitä mitä tallaus kutsuu. */
      const rise = (start) => {
        const s = arena();
        const p = s.player;
        for (let f = 0; f < 40; f++) s.update(mkInput());
        const y0 = p.y;
        const first = mkInput();
        first.held.jump = true;
        if (start) start(p);
        else first.pressed.jump = true;
        s.update(first);
        let top = Math.min(y0, p.y);
        for (let f = 0; f < 200; f++) {
          const k = mkInput();
          k.held.jump = true;
          s.update(k);
          top = Math.min(top, p.y);
          if (p.onGround && f > 4) break;
        }
        return Math.round(y0 - top);
      };
      const bounced = rise((p) => { p.bounce(true); p.jumpHeld = true; });
      const jumped = rise(null);
      expect('vihollisen päältä ponnistaa korkeammalle kuin omalla hypyllä',
        bounced > jumped * 1.15,
        `pomppu ${bounced} px, paikaltaan hyppy ${jumped} px`);
    }
  }

  /* ------------------------------- piikit ------------------------------- */
  /* Reported from play: "the player passed on top of the spikes but still took
   * damage". The spikes are drawn in the bottom ten pixels of their tile, but
   * the damage test used the whole sixteen — so six pixels of plain air above
   * the points were just as lethal as the points. */
  {
    const { T, TILE, SPIKE_TOP } = await import('/src/gfx/tiles.js');
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '2-1');
    game.setScene(s);

    // Build a spike bed of our own so the test does not depend on level data.
    const ty = 12;
    const tx = Math.floor(s.player.x / TILE) + 4;
    for (let i = 0; i < 4; i++) s.setTile(tx + i, ty, T.SPIKE);

    const tryAt = (feetY) => {
      const p = s.player;
      p.dying = false;
      p.invuln = 0;
      p.frozen = 0;
      p.power = { type: 'shroom', level: 3 };
      p.applySize();
      p.x = (tx + 1) * TILE;
      p.y = feetY - p.h;
      const before = p.powerLevel;
      s.playerTiles();
      return p.powerLevel < before || p.dying;
    };

    const spikeTop = ty * TILE + SPIKE_TOP;
    const clear = tryAt(spikeTop - 1);      // feet one pixel above the points
    const grazed = tryAt(spikeTop + 3);     // feet in among the points
    expect('spikes hurt where the points are and not in the air above them',
      !clear && grazed, `yläpuolella ${clear ? 'sattui' : 'ei sattunut'}, `
      + `piikeissä ${grazed ? 'sattui' : 'ei sattunut'}`);
  }

  /* ---- tähti ja vaarat: isku vastaan paikka ---- */
  /*
   * Omistaja kuoli 4-1:ssä närästysliekkiin tähti päällä ja kysyi eikö tähden
   * pitäisi suojata. Pitäisi, ja koodi oli kahta mieltä itsensä kanssa:
   * **lattian piikki luki tähteä, `kind === 'hazard'` ei lukenut lainkaan.**
   * Tähti siis suojasi piikiltä lattiassa muttei liekiltä joka nousee samasta
   * lattiasta, ja kaksi kommenttia tässä samassa tiedostossa väitti eri asiaa.
   *
   * Raja on **isku vastaan paikka**: kuoppa, laava ja kello ovat paikkoja
   * joihin pelaaja menee eivätkä ne ole suojattuja; piikki, närästysliekki ja
   * papupommi osuvat pelaajaan, ja ne ovat. Molemmat vaaraoliot mitataan, ei
   * vain se jonka omistaja löysi.
   */
  {
    const { Heartburn, BeanBomb } = await import('/src/entities/enemies.js');
    const hazards = [
      /* Suihku pannaan palamaan käsin: `idle`-vaiheessa sen laatikon korkeus on
       * 0, eikä nollan korkuinen laatikko ole osuma. Testi mittaa törmäystä
       * eikä ajastinta. */
      ['närästysliekki', (lv, p) => {
        const h = new Heartburn(lv, p.x, p.y + p.h + 16);
        h.phase = 'fire';
        h.height = h.maxHeight;
        h.timer = 60;
        return h;
      }],
      ['papupommi', (lv, p) => new BeanBomb(lv, p.x, p.y, 0)],
    ];
    const rows = [];
    for (const [name, make] of hazards) {
      for (const withStar of [false, true]) {
        reset({ type: 'shroom', level: 2 });
        const sc = new LevelScene(game, '1-1');
        game.setScene(sc);
        const inp = mkInput();
        for (let f = 0; f < 6; f++) sc.update(inp);
        sc.entities = sc.entities.filter((e) => e.kind !== 'enemy');
        const pl = sc.player;
        if (withStar) pl.collect('star');
        const before = pl.power.level;
        const hz = make(sc, pl);
        hz.alwaysActive = true;
        /* Vaara ajetaan pelaajan päälle suoraan: se mitä mitataan on
         * törmäyksen seuraus, ei se osuuko ajastin. */
        hz.x = pl.x; hz.y = pl.y;
        if (hz.box) { hz.box.x = pl.x; hz.box.y = pl.y; hz.box.w = pl.w; hz.box.h = pl.h; }
        sc.entities.push(hz);
        for (let f = 0; f < 4; f++) sc.update(inp);
        rows.push({ name, withStar, before, after: pl.power.level, alive: !pl.dead });
      }
    }
    const hurtBare = rows.filter((r) => !r.withStar).every((r) => r.after < r.before || !r.alive);
    const safeStar = rows.filter((r) => r.withStar).every((r) => r.after === r.before && r.alive);
    expect('tähti suojaa vaaralta joka osuu, kuten se suojaa piikiltä',
      hurtBare && safeStar,
      rows.map((r) => `${r.name} ${r.withStar ? 'tähdellä' : 'ilman'} ${r.before}->${r.after}`
        + `${r.alive ? '' : ' kuoli'}`).join(', '));
  }

  /* ------------------------------ supertähti ---------------------------- */
  /* It kills what it touches, and it protects you from enemies and from nothing
   * else. The three "still kills" cases are the whole point of the feature —
   * the lead designer specified them — so each lethal path is asked separately,
   * because each one lives in different code. */
  {
    const { Walker } = await import('/src/entities/enemies.js');
    const { T } = await import('/src/gfx/tiles.js');

    reset({ type: 'shroom', level: 2 });
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    const i = mkInput();
    for (let f = 0; f < 6; f++) s.update(i);
    s.entities = s.entities.filter((e) => e.kind !== 'enemy');
    const p = s.player;
    p.collect('star');

    const scoreBefore = game.state.score;
    const powerBefore = p.powerLevel;
    const w = new Walker(s, p.x + p.w - 4, p.y + p.h - 16);
    w.active = true; w.alwaysActive = true; w.vx = 0;
    s.entities.push(w);
    s.collisions();
    expect('the star kills the enemy it touches and leaves the player alone',
      (w.dying || w.remove) && !p.dying && p.powerLevel === powerBefore
      && game.state.score > scoreBefore,
      `power ${powerBefore}->${p.powerLevel}, score ${scoreBefore}->${game.state.score}`);

    const survived = [];
    for (const [what, kill] of [
      ['kuoppa', (sc) => { sc.player.y = sc.heightPx + 40; sc.playerTiles(); }],
      ['laava', (sc) => {
        sc.setTile(Math.floor(sc.player.cx / 16), Math.floor(sc.player.cy / 16), T.LAVA);
        sc.playerTiles();
      }],
      /* "Aika" on nyt tyhjä säiliö (18.8.2026: kolikot ovat aika). Sama
       * väite, uusi lähde: tähti ei suojaa siltä että polttoaine loppuu. */
      ['aika', (sc) => {
        game.state.coins = 0;
        sc.timeSub = 999;
        sc.updateTimer();
      }],
    ]) {
      reset({ type: 'shroom', level: 2 });
      const sc = new LevelScene(game, '1-1');
      game.setScene(sc);
      for (let f = 0; f < 6; f++) sc.update(mkInput());
      sc.player.collect('star');
      kill(sc);
      if (!sc.player.dying) survived.push(what);
    }
    /* Spikes are one of the things in the level that hit you, so the star does
     * cover them — the lead designer asked for exactly that. The level itself
     * still is not covered, which is the line the previous check draws. */
    {
      const { T } = await import('/src/gfx/tiles.js');
      reset({ type: 'shroom', level: 3 });
      const sc = new LevelScene(game, '1-1');
      game.setScene(sc);
      for (let f = 0; f < 6; f++) sc.update(mkInput());
      const p2 = sc.player;
      const tx = Math.floor(p2.cx / 16);
      const ty = Math.floor((p2.y + p2.h) / 16) - 1;
      sc.setTile(tx, ty, T.SPIKE);
      p2.y = ty * 16 + 10 - p2.h;
      const withoutStar = p2.powerLevel;
      sc.playerTiles();
      const hurt = p2.powerLevel < withoutStar;

      reset({ type: 'shroom', level: 3 });
      const sc2 = new LevelScene(game, '1-1');
      game.setScene(sc2);
      for (let f = 0; f < 6; f++) sc2.update(mkInput());
      const p3 = sc2.player;
      p3.collect('star');
      const tx2 = Math.floor(p3.cx / 16);
      const ty2 = Math.floor((p3.y + p3.h) / 16) - 1;
      sc2.setTile(tx2, ty2, T.SPIKE);
      p3.y = ty2 * 16 + 10 - p3.h;
      const before2 = p3.powerLevel;
      sc2.playerTiles();
      expect('the star carries you over ground spikes',
        hurt && p3.powerLevel === before2 && !p3.dying,
        `ilman tähteä ${hurt ? 'sattui' : 'ei sattunut'}, tähdellä `
        + `${p3.powerLevel === before2 ? 'ei sattunut' : 'sattui'}`);
    }

    expect('the star does not save you from the level itself',
      survived.length === 0,
      survived.length ? `selvisi: ${survived.join(', ')}` : 'kuoppa/laava/aika tappavat yhä');
  }

  {
    const { T } = await import('/src/gfx/tiles.js');
    reset({ type: 'shroom', level: 2 });
    const s = new LevelScene(game, '1-1');
    game.pendingNode = WORLDS[0].nodes.find((n) => n.id === 'w1-1');
    game.setScene(s);
    const i = mkInput();
    for (let f = 0; f < 6; f++) s.update(i);
    s.player.collect('star');
    const full = s.player.star;

    const snap = JSON.parse(JSON.stringify(captureState(game)));
    s.player.star = 0;
    restoreState(game, snap);
    const r = game.scene;
    expect('a save state keeps the star running', r.player.star === full,
      `${full} vs ${r.player.star}`);

    let ran = 0;
    while (r.player.star > 0 && ran < 3000) { r.update(i); ran++; }
    expect('the star runs out', r.player.star === 0 && ran < 3000, `${ran} framea`);

    const blocks = [];
    for (const id of levelIds()) {
      const sc = new LevelScene(game, id);
      for (let ty = 0; ty < sc.h; ty++) {
        for (let tx = 0; tx < sc.w; tx++) {
          if (sc.rawTileAt(tx, ty) === T.QSTAR) blocks.push({ id, tx, ty });
        }
      }
    }
    expect('a star block exists in a hand-made level', blocks.length > 0,
      blocks.map((b) => `${b.id} ${b.tx},${b.ty}`).join(' '));
    if (blocks.length) {
      reset();
      const sc = new LevelScene(game, blocks[0].id);
      game.setScene(sc);
      sc.bumpTile(blocks[0].tx, blocks[0].ty, sc.player);
      const item = sc.entities.find((e) => e.kind === 'item');
      expect('a star block yields a star and not a rolled power-up',
        !!item && item.itemKind === 'star', item ? item.itemKind : 'ei mitään');
    }
  }

  /* ----------------------------- kytkinruudut --------------------------- */
  {
    const { T, TILE } = await import('/src/gfx/tiles.js');
    const E = await import('/src/entities/enemies.js');
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '3-2');
    game.setScene(s);
    const i = mkInput();

    let button = null;
    let brick = null;
    for (let ty = 0; ty < s.h && !button; ty++) {
      for (let tx = 0; tx < s.w; tx++) if (s.grid[ty][tx] === T.SWITCH) { button = { tx, ty }; break; }
    }
    for (let ty = 0; ty < s.h && !brick; ty++) {
      for (let tx = 0; tx < s.w; tx++) if (s.grid[ty][tx] === T.BRICK) { brick = { tx, ty }; break; }
    }
    expect('3-2 has a switch block and bricks for it to change', !!button && !!brick,
      `${button ? `${button.tx},${button.ty}` : 'ei kytkintä'} / ${brick ? 'tiiliä' : 'ei tiiliä'}`);

    if (button && brick) {
      const solidBefore = s.solidAt(brick.tx, brick.ty);
      s.startSwitch();
      const asCoin = s.tileAt(brick.tx, brick.ty) === T.COIN;
      const passable = !s.solidAt(brick.tx, brick.ty);
      // The stored grid must not have changed — that is the whole design.
      const gridUntouched = s.grid[brick.ty][brick.tx] === T.BRICK;
      expect('a running switch turns bricks into coins without rewriting the grid',
        solidBefore && asCoin && passable && gridUntouched,
        `kiinteä ${solidBefore}, kolikko ${asCoin}, ruudukko ${s.grid[brick.ty][brick.tx]}`);

      // Park the player somewhere harmless and let it run out.
      s.player.x = s.spawn.x;
      s.player.y = s.spawn.y - s.player.h;
      s.player.vy = 0;
      for (let f = 0; f < 40 && s.switchTimer > 0; f++) s.update(i);
      s.switchTimer = 3;
      for (let f = 0; f < 12; f++) s.update(i);
      expect('a switch runs out and the bricks come back',
        s.switchTimer === 0 && s.solidAt(brick.tx, brick.ty), `ajastin ${s.switchTimer}`);

      /*
       * A SLIDING SHELL THROWS THE SWITCH TOO (18.8.2026).
       *
       * The switch was reachable exactly where a jump was, which made a *time*
       * puzzle into a *height* puzzle. A shell is already something the player
       * aims down a corridor, so this adds a second way in without adding a
       * thing to learn — and the two ways must be the same switch, which is
       * what the second half of this check is for: the tile is consumed to
       * `T.USED` exactly as a head bump consumes it.
       *
       * The shell is placed to the LEFT of the button and pushed right, and
       * the tile read is the one ahead of the body — a shell at speed is inside
       * the next column before a frame boundary notices it.
       */
      s.switchTimer = 0;
      s.grid[button.ty][button.tx] = T.SWITCH;
      const shell = new E.ShellGuy(s, button.tx * TILE, button.ty * TILE);
      /* Adjacent, not near: `shellThrowsSwitch` reads the tile the body is
       * about to enter, so the gap has to be under one pixel or the read lands
       * on the column before the button. */
      shell.x = button.tx * TILE - shell.w;
      shell.y = button.ty * TILE;
      shell.vx = 4;
      s.shellSweep(shell);
      expect('liukuva kuori heittää kytkimen, ja se on sama kytkin',
        s.switchTimer > 0 && s.grid[button.ty][button.tx] === T.USED,
        `ajastin ${s.switchTimer}, ruutu ${s.grid[button.ty][button.tx]}`);

      /* The one way this design could hurt someone is being inside a brick when
       * it comes back. It turns out that cannot happen, and not for the reason
       * the guard in `updateSwitch` assumes: a brick reading as a coin is
       * *collected* the moment the player touches it, which empties that cell
       * of the stored grid for good. There is nothing left to return. The guard
       * stays as defence for any future mapping that is not collectable, but
       * this is the property that actually protects the player, so this is the
       * one worth asserting. */
      s.startSwitch();
      s.player.x = brick.tx * 16 + (16 - s.player.w) / 2;
      s.player.y = brick.ty * 16;
      s.player.vy = 0;
      s.update(i);
      const collected = s.grid[brick.ty][brick.tx] === T.EMPTY;
      s.switchTimer = 2;
      for (let f = 0; f < 20; f++) {
        s.player.x = brick.tx * 16 + (16 - s.player.w) / 2;
        s.player.y = brick.ty * 16;
        s.player.vy = 0;
        s.update(i);
      }
      expect('a switched brick is collected, so nothing can come back on top of you',
        collected && s.switchTimer === 0 && !s.solidAt(brick.tx, brick.ty)
        && !s.player.dying,
        `kerätty ${collected}, ajastin ${s.switchTimer}, `
        + `kiinteä ${s.solidAt(brick.tx, brick.ty)}`);

      // Bumping the block is what starts it, and it only works once.
      const s2 = new LevelScene(game, '3-2');
      game.setScene(s2);
      s2.bumpTile(button.tx, button.ty, s2.player);
      const started = s2.switchTimer > 0;
      const spent = s2.grid[button.ty][button.tx] === T.USED;
      expect('hitting the block starts the switch and spends the block',
        started && spent, `ajastin ${s2.switchTimer}, ruutu ${s2.grid[button.ty][button.tx]}`);

      // And a save state has to carry it, or a reload silently changes the level.
      game.pendingNode = WORLDS[2].nodes.find((n) => n.level === '3-2') || game.pendingNode;
      const snap = JSON.parse(JSON.stringify(captureState(game)));
      s2.switchTimer = 0;
      restoreState(game, snap);
      expect('a save state remembers a running switch',
        game.scene.switchTimer > 0, `${game.scene.switchTimer}`);
    }
  }

  /* -------------------------- murenevat lavat -------------------------- */
  {
    const { T } = await import('/src/gfx/tiles.js');
    reset({ type: 'shroom', level: 1 });
    const s = new LevelScene(game, '4-1');
    game.setScene(s);
    const i = mkInput();

    // Find a crumbling tile and stand the player on it.
    let spot = null;
    for (let ty = 0; ty < s.h && !spot; ty++) {
      for (let tx = 0; tx < s.w; tx++) if (s.grid[ty][tx] === T.CRUMBLE) { spot = { tx, ty }; break; }
    }
    expect('4-1 has a crumbling catwalk in it', !!spot, spot ? `${spot.tx},${spot.ty}` : 'ei löytynyt');

    if (spot) {
      s.player.x = spot.tx * 16 + 2;
      s.player.y = spot.ty * 16 - s.player.h;
      s.player.vy = 0;
      for (let f = 0; f < 3; f++) s.update(i);
      const heldAtFirst = s.tileAt(spot.tx, spot.ty) === T.CRUMBLE;
      const started = s.crumbleProgress(spot.tx, spot.ty) > 0;

      // It has to hold long enough to walk across…
      for (let f = 0; f < 40; f++) s.update(i);
      const stillThere = s.tileAt(spot.tx, spot.ty) === T.CRUMBLE;

      /* …and then go, whether or not anyone is still standing there. Step off
       * first: the pit under this catwalk is bottomless, and a dead scene stops
       * updating after the death animation, so staying would only prove that. */
      s.player.x = s.spawn.x;
      s.player.y = s.spawn.y - s.player.h;
      s.player.vy = 0;
      for (let f = 0; f < 40; f++) s.update(i);
      const gone = s.tileAt(spot.tx, spot.ty) === T.EMPTY;
      expect('a crumbling platform holds, warns, then drops out',
        heldAtFirst && started && stillThere && gone,
        `heti ${heldAtFirst}, ajastin ${started}, 40 framea ${stillThere}, 80 framea poissa ${gone}`);

      /* It must come back. Dying halfway across a row of these would otherwise
       * leave the level impassable for the rest of the attempt, with nothing on
       * screen to explain why. */
      for (let f = 0; f < 260; f++) s.update(i);
      expect('a crumbling platform grows back',
        s.tileAt(spot.tx, spot.ty) === T.CRUMBLE, s.tileAt(spot.tx, spot.ty));

      // And the save state has to carry the timers, like it does for bumps.
      const s2 = new LevelScene(game, '4-1');
      game.pendingNode = WORLDS[3].nodes.find((n) => n.level === '4-1') || game.pendingNode;
      game.setScene(s2);
      s2.player.x = spot.tx * 16 + 2;
      s2.player.y = spot.ty * 16 - s2.player.h;
      for (let f = 0; f < 8; f++) s2.update(i);
      const snap = JSON.parse(JSON.stringify(captureState(game)));
      const before = s2.crumbles.size;
      restoreState(game, snap);
      expect('a save state remembers which platforms are already crumbling',
        before > 0 && game.scene.crumbles.size === before,
        `${before} -> ${game.scene.crumbles.size}`);
    }
  }

  /* --------------------------- kosketusohjaus -------------------------- */
  {
    const { Input } = await import('/src/core/input.js');
    const { LAYOUTS } = await import('/src/core/touch.js');
    const touch = game.touch;
    touch.reveal();

    const rect = (act) => document.querySelector(`#touch [data-act="${act}"]`)
      .getBoundingClientRect();
    const send = (type, id, x, y) => {
      document.getElementById('touch').dispatchEvent(new PointerEvent(type, {
        pointerId: id, clientX: x, clientY: y, pointerType: 'touch', bubbles: true, cancelable: true,
      }));
    };
    const at = (act) => {
      const r = rect(act);
      return [r.left + r.width / 2, r.top + r.height / 2];
    };
    const held = () => {
      Input.poll();
      return Object.entries(Input.held).filter(([, v]) => v).map(([k]) => k).sort().join(',');
    };
    const letGo = () => {
      touch._releaseAll();
      Input.poll();
      Input.poll();
    };

    touch.setLayout('napit');
    letGo();
    send('pointerdown', 1, ...at('left'));
    const pressed = held();
    send('pointerup', 1, ...at('left'));
    const released = held();
    expect('a touch key presses and releases',
      pressed === 'left' && released === '', `alas "${pressed}", ylös "${released}"`);

    /* Rolling a thumb from one key to the next has to work. The browser sends
     * no leave event for that, which is why the hit-testing is done by hand. */
    letGo();
    send('pointerdown', 2, ...at('left'));
    held();                                  // a frame passes, as it would in life
    send('pointermove', 2, ...at('right'));
    const rolled = held();
    send('pointerup', 2, ...at('right'));
    expect('sliding a thumb between keys switches the direction',
      rolled === 'right', `"${rolled}"`);

    // Steering, running and jumping at once is three fingers, and dropping any
    // one of them would read as the game sticking.
    letGo();
    send('pointerdown', 3, ...at('right'));
    send('pointerdown', 4, ...at('jump'));
    send('pointerdown', 5, ...at('run'));
    const three = held();
    send('pointerup', 4, ...at('jump'));
    const afterOne = held();
    for (const id of [3, 5]) send('pointerup', id, 0, 0);
    expect('three fingers work at once, and lifting one keeps the others',
      three === 'jump,right,run' && afterOne === 'right,run',
      `"${three}" -> "${afterOne}"`);

    // A tap shorter than a frame still counts: on a touchscreen that is not an
    // edge case, that is simply what tapping is.
    letGo();
    send('pointerdown', 6, ...at('jump'));
    send('pointerup', 6, ...at('jump'));
    expect('a tap shorter than one frame still registers', held().includes('jump'));

    /* The thumb layout: no buttons, the halves of the screen are the control. */
    touch.setLayout('peukalot');
    letGo();
    const lx = innerWidth * 0.25;
    const ly = innerHeight * 0.7;
    send('pointerdown', 7, lx, ly);
    const neutral = held();
    send('pointermove', 7, lx + 50, ly);
    const right = held();
    send('pointermove', 7, lx - 50, ly);
    const left = held();
    send('pointermove', 7, lx, ly - 60);
    const up = held();
    send('pointerup', 7, lx, ly);
    expect('the floating stick steers from wherever the thumb landed',
      neutral === '' && right === 'right' && left === 'left' && up === 'up',
      `neutraali "${neutral}" oikea "${right}" vasen "${left}" ylös "${up}"`);

    letGo();
    send('pointerdown', 8, innerWidth * 0.8, innerHeight * 0.8);
    const jump = held();
    send('pointerup', 8, innerWidth * 0.8, innerHeight * 0.8);
    send('pointerdown', 9, innerWidth * 0.8, innerHeight * 0.1);
    const run = held();
    send('pointerup', 9, innerWidth * 0.8, innerHeight * 0.1);
    expect('the right half jumps low down and farts up top',
      jump === 'jump' && run === 'run', `alhaalla "${jump}", ylhäällä "${run}"`);

    /* The rolling layout: the fart pad is a field low and right where the flat
     * of the thumb rests, and the jump button sits *inside* it, up and left
     * where the tip reaches. One finger is one point to every touchscreen ever
     * built, so the only way one thumb can hold two buttons is for the two
     * rectangles to overlap. That containment is the whole mechanism, so it is
     * asserted directly rather than through the pixels it happens to have. */
    touch.setLayout('rulla');
    letGo();
    expect('the old layouts are still on offer',
      LAYOUTS.includes('napit') && LAYOUTS.includes('peukalot'), LAYOUTS.join(','));
    expect('the rolling layout keeps the d-pad', rect('left').width > 0, `${rect('left').width}`);

    const runPad = rect('run');
    const jumpPad = rect('jump');
    expect('the jump button lies wholly inside the fart pad, above and left of the thumb rest',
      jumpPad.left >= runPad.left && jumpPad.right <= runPad.right
      && jumpPad.top >= runPad.top && jumpPad.bottom <= runPad.bottom
      && jumpPad.left > runPad.left && jumpPad.bottom < runPad.bottom,
      `pieru ${Math.round(runPad.left)},${Math.round(runPad.top)} ${Math.round(runPad.width)}x${Math.round(runPad.height)}`
      + ` hyppy ${Math.round(jumpPad.left)},${Math.round(jumpPad.top)} ${Math.round(jumpPad.width)}x${Math.round(jumpPad.height)}`);

    /* This is the bug the owner reported, written as a gesture: rest the thumb
     * on the fart pad, roll the tip up onto jump, roll back. Run must never let
     * go — a jump that drops the run bit is a short jump, and short jumps miss
     * gaps that were measured for long ones. */
    letGo();
    const rest = [runPad.right - 18, runPad.bottom - 18];
    send('pointerdown', 20, ...rest);
    const resting = held();
    send('pointermove', 20, ...at('jump'));
    const rolledUp = held();
    send('pointermove', 20, ...rest);
    const rolledBack = held();
    send('pointerup', 20, ...rest);
    const lifted = held();
    expect('one thumb holds the fart button down and still reaches jump',
      resting === 'run' && rolledUp === 'jump,run' && rolledBack === 'run' && lifted === '',
      `lepo "${resting}" ylös "${rolledUp}" alas "${rolledBack}" irti "${lifted}"`);

    // Steering with the other hand has to keep working through all of it.
    letGo();
    send('pointerdown', 21, ...at('right'));
    send('pointerdown', 22, ...at('jump'));
    const runJumpRight = held();
    for (const id of [21, 22]) send('pointerup', id, 0, 0);
    expect('the rolling layout still runs, jumps and steers at once',
      runJumpRight === 'jump,right,run', `"${runJumpRight}"`);

    expect('the rolling layout is remembered too', touch.loadLayout() === 'rulla', touch.loadLayout());

    // Switching layout mid-press must not leave an action stuck down.
    letGo();
    touch.setLayout('napit');
    send('pointerdown', 10, ...at('left'));
    touch.setLayout('peukalot');
    const afterSwitch = held();
    expect('switching layout mid-press does not leave a key stuck',
      afterSwitch === '', `"${afterSwitch}"`);

    touch.setLayout('napit');
    letGo();
    expect('the touch layout is remembered', touch.loadLayout() === 'napit', touch.loadLayout());
  }

  /* --------------------- selaimen zoom mobiiliselaimessa --------------------- */
  /*
   * Two halves of one bug. Double-tapping beside the canvas zooms the page in,
   * and the full-screen control overlay then swallows the pinch that would
   * take it back out. `user-scalable=no` does not help: iOS Safari has ignored
   * it since iOS 10, and on Android it makes the trap worse by disabling the
   * way back out.
   */
  {
    const touch = game.touch;
    const root = document.getElementById('touch');
    const meta = document.querySelector('meta[name="viewport"]').content;

    touch.setZoomed?.(false);
    expect('nothing in the viewport meta can lock a player out of zooming back out',
      !/user-scalable\s*=\s*(no|0)/i.test(meta) && !/maximum-scale/i.test(meta), meta);

    expect('the double tap is killed by touch-action on the root element',
      getComputedStyle(document.documentElement).touchAction === 'manipulation',
      getComputedStyle(document.documentElement).touchAction);

    const playing = getComputedStyle(root).touchAction;
    touch.setZoomed?.(true);
    const zoomedRoot = getComputedStyle(document.documentElement).touchAction;
    const zoomedOverlay = getComputedStyle(root).touchAction;
    touch.setZoomed?.(false);
    expect('the overlay eats browser gestures while playing and gives them back while zoomed',
      playing === 'none' && zoomedOverlay === 'auto' && zoomedRoot === 'auto',
      `pelatessa "${playing}", zoomattuna juuri "${zoomedRoot}" / peite "${zoomedOverlay}"`);

    /* The belt to that pair of braces: swallow the second tap ourselves. It has
     * to stay off the controls — the toolbar is ordinary DOM and needs the
     * synthetic click that preventDefault would eat. */
    const tap = (target, x, y) => {
      const t = new window.Touch({ identifier: 1, target, clientX: x, clientY: y });
      const ev = new TouchEvent('touchend', {
        bubbles: true, cancelable: true, touches: [], targetTouches: [], changedTouches: [t],
      });
      target.dispatchEvent(ev);
      return ev.defaultPrevented;
    };
    const first = tap(document.body, 40, 40);
    const second = tap(document.body, 42, 41);
    const tool = root.querySelector('.tool');
    const onTool = tap(tool, 4, 4) || tap(tool, 4, 4);
    expect('a double tap beside the game is swallowed, and the controls are not',
      first === false && second === true && onTool === false,
      `1. "${first}" 2. "${second}" työkalu "${onTool}"`);
  }

  /* ------------------------------ kuvaefektit -------------------------- */
  {
    const { PostFX, PRESETS } = await import('/src/gfx/postfx.js');

    // A fresh instance per case: the live PostFX is already attached to the
    // real canvas and must not be re-initialised out from under the game.
    const makeFX = () => Object.create(PostFX);
    const testCanvas = () => {
      const c = document.createElement('canvas');
      c.width = 320;
      c.height = 240;
      const g = c.getContext('2d');
      g.fillStyle = '#204080';
      g.fillRect(0, 0, 320, 240);
      g.fillStyle = '#ffe0a0';                 // something bright for the bloom
      g.fillRect(140, 90, 40, 40);
      return c;
    };
    const pixels = (c) => c.getContext('2d').getImageData(0, 0, 320, 240).data;
    // Any channel counts. A bloom around something already at 255 red shows up
    // only in the other two, and counting red alone missed almost all of it.
    const differs = (a, b) => {
      let n = 0;
      for (let i = 0; i < a.length; i += 4) {
        if (a[i] !== b[i] || a[i + 1] !== b[i + 1] || a[i + 2] !== b[i + 2]) n++;
      }
      return n;
    };

    /* THE point of this file: a machine without WebGL still gets a game.
     * getContext('webgl2') returns null on a blocklisted driver, in a VM and
     * whenever hardware acceleration is off — in an up-to-date browser. */
    const realGet = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function (type, opts) {
      if (String(type).startsWith('webgl')) return null;
      return realGet.call(this, type, opts);
    };
    let fallbackOk = false;
    let drewGlow = 0;
    let drewCrt = 0;
    try {
      const fx = makeFX();
      const c = testCanvas();
      const shown = fx.init(c);
      fallbackOk = fx.mode === '2d' && shown === c && !fx.displayCanvas
        && fx.present() === false;
      for (const [preset, out] of [['hehku', 'glow'], ['crt', 'crt']]) {
        const t = testCanvas();
        fx.source = t;
        fx.setPreset(preset);
        const before = pixels(t).slice();
        fx.apply(t.getContext('2d'));
        const n = differs(before, pixels(t));
        if (out === 'glow') drewGlow = n; else drewCrt = n;
      }
    } finally {
      HTMLCanvasElement.prototype.getContext = realGet;
    }
    expect('without WebGL the game still draws, effects and all',
      fallbackOk && drewGlow > 200, `mode-ok ${fallbackOk}, hehku muutti ${drewGlow} px`);
    // Scanlines and the vignette live in the shader when there is one, and in
    // Canvas 2D when there is not. Without WebGL, CRT must still beat plain glow.
    expect('the CRT preset really does more than the glow one without WebGL',
      drewCrt > drewGlow * 4, `hehku ${drewGlow} px, crt ${drewCrt} px`);

    // A context that throws outright must land in the same place as a null one.
    HTMLCanvasElement.prototype.getContext = function (type, opts) {
      if (String(type).startsWith('webgl')) throw new Error('ajuri estetty');
      return realGet.call(this, type, opts);
    };
    let threwOk = false;
    try {
      const fx = makeFX();
      threwOk = fx.init(testCanvas()) !== null && fx.mode === '2d';
    } catch {
      threwOk = false;
    } finally {
      HTMLCanvasElement.prototype.getContext = realGet;
    }
    expect('a driver that throws falls back instead of taking the game down', threwOk);

    /* Every preset has to survive being drawn, and 'pois' has to mean off —
     * an effects switch that does not switch anything off is worse than none. */
    const perPreset = [];
    for (const preset of PRESETS) {
      const fx = makeFX();
      const c = testCanvas();
      fx.init(c);
      fx.setPreset(preset);
      const before = pixels(c).slice();
      try {
        fx.apply(c.getContext('2d'));
        fx.present();
        perPreset.push({ preset, changed: differs(before, pixels(c)), error: null });
      } catch (err) {
        perPreset.push({ preset, changed: -1, error: err.message });
      }
    }
    const off = perPreset.find((p) => p.preset === 'pois');
    const on = perPreset.filter((p) => p.preset !== 'pois');
    expect('every effect preset renders, and "pois" really is off',
      perPreset.every((p) => !p.error) && off.changed === 0
      && on.every((p) => p.changed > 200),
      perPreset.map((p) => `${p.preset}:${p.error || p.changed}`).join(' '));

    /* Effects must leave the context exactly as they found it. A filter or a
     * composite mode left set wrecks the next frame's tiles, and that reads as
     * a graphics glitch rather than as a leak. */
    {
      const fx = makeFX();
      const c = testCanvas();
      fx.init(c);
      fx.setPreset('crt');
      const g = c.getContext('2d');
      g.imageSmoothingEnabled = false;
      g.globalAlpha = 1;
      g.globalCompositeOperation = 'source-over';
      fx.apply(g);
      expect('effects put the drawing context back the way they found it',
        g.imageSmoothingEnabled === false && g.globalAlpha === 1
        && g.globalCompositeOperation === 'source-over'
        && (!('filter' in g) || g.filter === 'none'),
        `smoothing ${g.imageSmoothingEnabled}, alpha ${g.globalAlpha}, `
        + `op ${g.globalCompositeOperation}, filter ${g.filter}`);
    }

    // The preset is a taste decision, so it has to survive a reload.
    {
      const fx = makeFX();
      fx.init(testCanvas());
      fx.setPreset('crt');
      const other = makeFX();
      other.init(testCanvas());
      expect('the chosen preset is remembered', other.preset === 'crt', other.preset);
      const cycled = [fx.cyclePreset(), fx.cyclePreset(), fx.cyclePreset()];
      expect('the effects key cycles through every preset and back',
        cycled.join(',') === 'pois,hehku,crt', cycled.join(','));
    }

    /* The bloom reads back 4800 pixels every frame. That is affordable, but it
     * is exactly the kind of thing that quietly stops being affordable, so the
     * budget is asserted rather than assumed. */
    {
      const fx = makeFX();
      const c = testCanvas();
      fx.init(c);
      fx.setPreset('crt');
      const g = c.getContext('2d');
      fx.apply(g);                        // warm up
      const t0 = performance.now();
      for (let i = 0; i < 60; i++) fx.apply(g);
      const per = (performance.now() - t0) / 60;
      expect('the effect pass fits in the frame budget',
        per < 2.5, `${per.toFixed(2)} ms / frame`);
    }

    /* Per-level atmosphere comes from the level's theme, and nothing else must
     * be able to set it — a shimmer on the world map would just be a bug. */
    {
      const { THEME_AMBIENCE } = await import('/src/gfx/postfx.js');
      const { getLevel, levelIds } = await import('/src/data/levels.js');
      const seen = new Set(levelIds().map((id) => THEME_AMBIENCE[getLevel(id).theme] || null));
      expect('the desert shimmers and the ice world frosts over',
        THEME_AMBIENCE.desert === 'heat' && THEME_AMBIENCE.ice === 'frost'
        && seen.has('heat') && seen.has('frost') && seen.has(null),
        [...seen].join(','));

      reset();
      const desert = new LevelScene(game, '2-1');
      game.setScene(desert);
      const inDesert = game.fx.ambience;
      game.toWorldMap();
      const onMap = game.fx.ambience;
      expect('atmosphere follows the scene and clears when you leave',
        inDesert === 'heat' && onMap === null, `${inDesert} -> ${onMap}`);
    }

    /*
     * ILMAKEHÄ EI KOSKE KERTOJAAN, ja tämä on sama väite kuin ennen mutta
     * toisella takuulla.
     *
     * Kuumuus väreili aikanaan kelloa ja huurre kasvoi pisteluvun päälle, mikä
     * on juuri sitä tunnelmaa joka tekee pelistä vaikealukuisen eikä
     * kauniimman. Takuu oli 32 px korkea HUD-nauha jonka ilmakehä jätti
     * rauhaan (`HUD_H`). Nauhaa ei ole enää olemassa, joten takuu on nyt
     * **piirtojärjestys**: `main.js` piirtää kohtauksen, ajaa `PostFX.apply`n
     * ja piirtää vasta sitten `drawOverlay`in.
     *
     * Se luetaan lähdetekstistä eikä pikseleistä, koska väite koskee
     * järjestystä eikä väriä: kaksi riviä väärässä järjestyksessä ei näy
     * yhdessäkään yksittäisessä kuvassa vaan vasta siinä kentässä jossa
     * sattuu olemaan kuumuutta.
     */
    {
      const src = await (await fetch('/src/main.js')).text();
      const applyAt = src.indexOf('PostFX.apply(ctx)');
      const overlayAt = src.indexOf('drawOverlay(ctx)');
      const presentAt = src.indexOf('PostFX.present()');
      expect('ilmestyvät lukemat piirretään kuvaefektien jälkeen',
        applyAt > 0 && overlayAt > applyAt && presentAt > overlayAt,
        `apply ${applyAt}, drawOverlay ${overlayAt}, present ${presentAt}`);
    }

    // And whatever the live game ended up with, it has to be a working mode.
    expect('the running game has a valid effect mode',
      ['webgl', '2d'].includes(game.fx.mode) && PRESETS.includes(game.fx.preset),
      `${game.fx.mode} / ${game.fx.preset}`);
    game.fx.setPreset('hehku');
  }

  /* ------------------------ kuvasuhde ja valokeila --------------------- */
  {
    const { VIEW_W, VIEW_H } = await import('/src/scenes/level.js');
    const { PostFX } = await import('/src/gfx/postfx.js');
    const { T, TILE } = await import('/src/gfx/tiles.js');

    // A fresh instance per case, as in the kuvaefektit block above: the live
    // PostFX is attached to the real canvas and must not be re-initialised.
    const makeFX = () => Object.create(PostFX);
    const shot = () => {
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d', { willReadFrequently: true });
      g.imageSmoothingEnabled = false;
      g.fillStyle = '#000';
      g.fillRect(0, 0, c.width, c.height);
      return { c, g };
    };
    const data = (c) => c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    const at = (x, y) => 4 * (y * VIEW_W + x);
    const luma = (d, i) => (d[i] * 54 + d[i + 1] * 183 + d[i + 2] * 19) >> 8;
    const rowBlack = (d, y) => {
      for (let x = 0; x < VIEW_W; x++) {
        const i = at(x, y);
        if (d[i] || d[i + 1] || d[i + 2]) return false;
      }
      return true;
    };
    const strip = (d, y0, y1) => [...d.slice(at(0, y0), at(0, y1))].join(',');

    /* Cinemascope is a crop, not a mask: if the camera's vertical range does not
     * narrow with the bars, the level is showing the same picture with a slice
     * painted out — which takes away the part you were reading and adds nothing. */
    reset();
    const wide = new LevelScene(game, '2-1');
    expect('2-1 and 2-3 are letterboxed and world 1 is not',
      wide.bar === 24 && wide.viewH === VIEW_H - 48
      && new LevelScene(game, '2-3').bar === 24
      && new LevelScene(game, '1-1').bar === 0
      && new LevelScene(game, '1-1').viewH === VIEW_H,
      `2-1 bar ${wide.bar}, viewH ${wide.viewH}`);

    {
      const input = mkInput();
      let hi = -Infinity;
      let escaped = 0;
      for (let f = 0; f < 900; f++) {
        input.held.right = true;
        input.held.run = true;
        input.pressed.jump = f % 47 === 0;
        input.held.jump = f % 47 < 12;
        input.held.down = f % 137 < 20;          // crouching must not break it either
        wide.update(input);
        hi = Math.max(hi, wide.cam.y);
        if (wide.cam.y < -0.001 || wide.cam.y + wide.viewH > wide.heightPx + 0.001) escaped++;
      }
      expect('the letterbox camera stays inside the narrowed band, and the crop is real',
        escaped === 0 && hi > wide.heightPx - VIEW_H,
        `${escaped} frames outside, max cam.y ${hi.toFixed(1)} `
        + `vs full-height limit ${wide.heightPx - VIEW_H}`);
    }

    /* The bars belong to the playfield. A widescreen score readout is just a
     * score readout with a slice missing. */
    {
      reset();
      const s = new LevelScene(game, '2-1');
      const a = shot();
      s.draw(a.g);
      const d = data(a.c);
      let bars = true;
      for (let y = 0; y < s.bar; y++) if (!rowBlack(d, y)) bars = false;
      for (let y = VIEW_H - s.bar; y < VIEW_H; y++) if (!rowBlack(d, y)) bars = false;
      const reaches = !rowBlack(d, s.bar) && !rowBlack(d, VIEW_H - s.bar - 1);

      const s2 = new LevelScene(game, '2-1');
      s2.bar = 0;
      s2.viewH = VIEW_H;
      const b = shot();
      s2.draw(b.g);
      /* Nauhaa ei enää ole, joten väite on se mikä siitä jäi jäljelle: palkit
       * ovat ikkunan ylä- ja alareunassa ja kuva ulottuu kumpaankin reunaan
       * asti. `b` piirretään yhä vertailun vuoksi — sama kenttä ilman palkkeja
       * — jotta rikkinäinen palkkilogiikka erottuu tyhjästä kuvasta. */
      const plainDrawn = !rowBlack(data(b.c), Math.floor(VIEW_H / 2));
      expect('kirjekuoripalkit ovat ikkunassa ja kuva ylettyy kumpaankin reunaan',
        bars && reaches && plainDrawn,
        `bars ${bars}, picture at both band edges ${reaches}, ilman palkkeja ${plainDrawn}`);
    }

    /* A narrower window must still hold the highest jump in the game — 100 px,
     * measured. Standing on the desert floor the head sits 102 px below the top
     * of the band, so the apex fits before the camera even follows it up. */
    {
      reset();
      game.state.power = { type: 'shroom', level: 3 };
      let worst = Infinity;
      let ground = 0;
      for (const id of ['2-1', '2-3']) {
        const s = new LevelScene(game, id);
        const input = mkInput();
        for (let f = 0; f < 900; f++) {
          input.held.right = true;
          input.held.run = true;
          input.pressed.jump = f % 53 === 0;
          input.held.jump = f % 53 < 34;
          s.update(input);
          if (s.player.dying) continue;
          const head = s.player.y - s.cam.y;
          worst = Math.min(worst, head);
          if (s.player.onGround) ground = Math.max(ground, head);
        }
      }
      expect('the highest jump still fits inside the letterbox band',
        worst >= -0.5 && ground >= 90,
        `head rests ${ground.toFixed(1)} px below the band top, jumps to ${worst.toFixed(1)}`);
    }

    /*
     * Red before green (DESIGN.md §7) for the owner's report: "the ground
     * disappears from view pretty often when jumping".
     *
     * The measurement is the complaint, stated as a number: over a run of
     * ordinary running jumps, on how many airborne frames is the tile the
     * player took off from — the one they are about to land back on — still
     * inside the window? Before the camera anchor it was **58.4 %** in 2-1 at
     * power level 0 and 58.8 % at level 3, with the tile as much as 42 px past
     * the bottom edge. In 1-1, where the window is 208 rows and the camera has
     * only 32 px of travel, it was already 100 %, which is why this only ever
     * showed up in the letterboxed desert.
     *
     * It is asserted at 100 % and not at "better than before": the rule is that
     * the view does not follow a jump upward at all, so there is no arc that
     * can take the ground with it, and any frame that fails is the rule being
     * broken rather than a threshold being missed.
     */
    {
      const rows = [];
      for (const [id, power] of [['2-1', { type: null, level: 0 }],
        ['2-1', { type: 'shroom', level: 3 }], ['1-1', { type: 'shroom', level: 3 }]]) {
        reset(power);
        const s = new LevelScene(game, id);
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        const input = mkInput();
        let air = 0;
        let seen = 0;
        let rise = 0;
        let takeoff = null;
        let counted = false;
        for (let f = 0; f < 1200; f++) {
          input.held = blank();
          input.pressed = blank();
          input.held.right = true;
          input.held.run = true;
          const phase = f % 60;
          if (phase === 40 && s.player.onGround) { input.pressed.jump = true; input.held.jump = true; }
          else if (phase > 40 && phase < 74) input.held.jump = true;
          const wasGround = s.player.onGround;
          const camBefore = s.cam.y;
          /* Whether the view had finished its last move before this take-off.
           * See the assertion below for why an unfinished one has to be left
           * out of the *rise* number and stays in the *ground* number. */
          const settled = Math.abs(s.cam.y - s.cameraY()) < 0.5;
          s.update(input);
          const p = s.player;
          if (p.dying) break;
          if (wasGround && !p.onGround) { takeoff = p.y + p.h; counted = settled; }
          if (!p.onGround && takeoff !== null) {
            air++;
            if (takeoff < s.cam.y + s.viewH) seen++;
            // How far the view climbed on a single airborne frame.
            if (counted) rise = Math.max(rise, camBefore - s.cam.y);
          }
          if (p.onGround) takeoff = null;
        }
        rows.push({ id, level: power.level, air, seen, rise });
      }
      expect('the ground you jumped off stays on screen for the whole jump',
        rows.every((r) => r.air > 200 && r.seen === r.air),
        rows.map((r) => `${r.id} taso ${r.level}: ${r.seen}/${r.air} framea`).join(', '));
      /* And the mechanism, not just its effect: the view may rise a little near
       * the apex to keep the head in frame (CAM_TOP_MARGIN), and it must never
       * ride the arc. A jump lifts the body ~5 px on its fastest frame.
       *
       * The 2-1 power-3 row reads 0.27 rather than 0.00 since `CAM_TOP_LEAD`,
       * and that is the anticipation zone rather than a regression: that jump
       * tops out 16.4 px from the top of the letterbox band, 0.4 px short of
       * forcing the old hard clamp, so it was always going to move the view —
       * it now moves it 0.93 px over the whole 85 px arc instead of stepping.
       * The power-0 row has 20.4 px of headroom and stays at 0.00.
       *
       * **Only jumps that start from a settled view count**, which is the same
       * filter its sibling below has had since `CAM_TOP_LEAD` and for the same
       * reason: landing moves the anchor and the view then glides up to it at
       * `CAM_V_EASE`, so a jump taken while that glide is still running carries
       * the glide into the air with it and the number stops being about the
       * arc. It only started mattering here when the letterboxed levels stopped
       * cutting their big landings — a cut was over inside one frame and could
       * never overlap the next take-off, so this filter was free before and is
       * load-bearing now. Unfiltered the bot reads 2.65 px in 2-1, and every
       * pixel of it is the previous landing finishing.
       *
       * The *ground* number deliberately keeps every frame: the take-off tile
       * must stay on screen through jumps taken mid-glide as well, and that is
       * a promise about the picture rather than about which mechanism moved it. */
      expect('the view does not ride a jump upward',
        rows.every((r) => r.rise < 2),
        rows.map((r) => `${r.id} ${r.rise.toFixed(2)} px/frame`).join(', '));
    }

    /*
     * Red before green (DESIGN.md §7) for the owner's second camera report:
     * "now it's better that it doesn't move when we jump, but then when the
     * character is actually high enough for the camera to move, it moves
     * suddenly. It just snaps higher instead of animating."
     *
     * The hold and the downward follow were both right and both stay; what was
     * wrong was the moment the hold ends. `CAM_TOP_MARGIN` was a hard clamp
     * applied after the ease, so the frame the head crossed it the view was
     * pinned to `p.y - 16` and tracked it exactly — nought to the body's own
     * rise speed between two frames.
     *
     * **A snap is a big number on one frame; an animation is a small number on
     * many.** So the measurement is the largest single-frame upward move of the
     * view over a run of jumps. Before `CAM_TOP_LEAD`: **2.92 px**, on a frame
     * where the body lifted 2.93 — the view matching the body's speed from a
     * standstill. After: **1.95 px**, and reached over several frames.
     *
     * Two things about the fixture, both of which decide what is being
     * measured:
     *
     *   - **only jumps that start from a settled view count.** Landing on a
     *     ledge moves the anchor, and the view then glides up to it at
     *     `CAM_V_EASE` — 8.7 px on its first frame, by design, because that is
     *     the *downward* follow working. Jumping again mid-glide and blaming
     *     the number on the top margin measures the wrong thing entirely; it
     *     was 6.70 px before the filter and had nothing to do with the report.
     *   - **fart jumps**, because nothing else reaches the zone. A running
     *     jump rises 85 px and tops out with the head still 16 px clear of the
     *     frame even in a letterboxed level, so it never asks the camera for
     *     anything — which is why the two power-0 and running-jump rows below
     *     are 0.00 px and must stay 0.00 px.
     */
    {
      const rows = [];
      for (const [id, power] of [['2-3', { type: 'leaf', level: 5 }],
        ['2-1', { type: 'leaf', level: 5 }], ['2-1', { type: 'leaf', level: 3 }],
        ['1-1', { type: 'leaf', level: 5 }], ['2-1', { type: null, level: 0 }],
        ['2-1', { type: 'shroom', level: 3 }]]) {
        reset(power);
        const s = new LevelScene(game, id);
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        const input = mkInput();
        let rise = 0;
        let air = 0;
        let seen = 0;
        let head = Infinity;
        let takeoff = null;
        let counted = false;
        for (let f = 0; f < 1800; f++) {
          input.held = blank();
          input.pressed = blank();
          input.held.right = true;
          input.held.run = true;
          const phase = f % 60;
          if (phase === 40 && s.player.onGround) { input.pressed.jump = true; input.held.jump = true; }
          else if (phase > 40 && phase < 74) input.held.jump = true;
          // The second press, in mid-air: the fart jump.
          if (phase === 48) { input.pressed.jump = true; input.held.jump = true; }
          const wasGround = s.player.onGround;
          const camBefore = s.cam.y;
          const settled = Math.abs(s.cam.y - s.cameraY()) < 0.5;
          s.update(input);
          const p = s.player;
          if (p.dying) break;
          if (wasGround && !p.onGround) { takeoff = p.y + p.h; counted = settled; }
          if (!p.onGround && takeoff !== null && counted) {
            air++;
            if (takeoff < s.cam.y + s.viewH) seen++;
            rise = Math.max(rise, camBefore - s.cam.y);
            head = Math.min(head, p.y - s.cam.y);
          }
          if (p.onGround) takeoff = null;
        }
        rows.push({ id, level: power.level, air, seen, rise, head });
      }
      /* 2.5 and not 2.92: the ceiling is under the number the snap produced and
       * over the number the ease produces, so it is the snap that cannot come
       * back rather than the whole mechanism being frozen. */
      expect('a view that has to rise animates instead of snapping',
        rows.every((r) => r.air > 200 && r.rise < 2.5),
        rows.map((r) => `${r.id} taso ${r.level}: ${r.rise.toFixed(2)} px/frame`).join(', '));
      /* And the warning must buy the smoothness out of itself, not out of the
       * two things that were already right: the head still may not touch the
       * top of the frame — nor even reach the margin, which is how you can tell
       * the clamp is no longer the thing doing the work — and the ground under
       * a jump still may not leave the bottom of it. */
      expect('anticipating the rise costs neither the headroom nor the ground',
        rows.every((r) => r.head > 16 && r.seen === r.air),
        rows.map((r) => `${r.id}: pää ${r.head.toFixed(2)} px, maa ${r.seen}/${r.air}`).join(', '));
    }

    /* `applySize()` pins the bottom of the body and changes its height, so
     * ducking used to shove `p.y` down 13 px in one frame and the camera went
     * with it — a jolt with no cue, because the backdrop has no vertical
     * parallax to move with it. The vertical camera hangs off the feet now. */
    {
      reset();
      game.state.power = { type: 'shroom', level: 3 };
      const results = [];
      for (const id of ['1-1', '1-2', '1-3', '2-2']) {
        const s = new LevelScene(game, id);
        let spot = null;
        for (let tx = 4; tx < s.w && !spot; tx++) {
          for (let ty = 3; ty < s.h; ty++) {
            if (s.rawTileAt(tx, ty) === T.PIPE_TL) { spot = { tx, ty }; break; }
          }
        }
        if (!spot) continue;
        s.player.x = spot.tx * TILE + 4;
        s.player.y = spot.ty * TILE - s.player.h;
        s.player.vy = 0;
        s.player.onGround = true;
        s.centerCamera();
        const input = mkInput();
        for (let f = 0; f < 60; f++) s.update(input);
        const camBefore = s.cam.y;
        const yBefore = s.player.y;
        input.held.down = true;
        s.update(input);
        results.push({
          id, jump: Math.abs(s.cam.y - camBefore), body: Math.abs(s.player.y - yBefore),
          ducked: s.player.ducking,
        });
      }
      const worst = results.reduce((a, b) => (b.jump > a.jump ? b : a));
      expect('crouching on a pipe does not jolt the camera',
        results.length >= 3 && results.every((r) => r.ducked && r.body > 8 && r.jump < 0.5),
        `body moves ${worst.body} px, camera moves ${worst.jump.toFixed(2)} px (${worst.id})`);

      // …and anchoring to the feet must not re-frame ordinary play.
      const s = new LevelScene(game, '1-3');
      s.player.power = { type: 'shroom', level: 1 };
      s.player.applySize();
      const old = Math.max(0, Math.min(s.player.y - s.viewH * 0.55, s.heightPx - s.viewH));
      expect('a standing mushroom-sized player is framed exactly as before',
        Math.abs(s.cameraY() - old) < 0.001, `${s.cameraY().toFixed(2)} vs ${old.toFixed(2)}`);
    }

    /* Vertical easing is fine; a camera that watches a fall from behind is not.
     * What matters is how much ground is still visible under the feet. */
    {
      reset();
      const rows = [];
      for (const id of ['1-1', '1-3', '2-1', '1-2']) {
        const s = new LevelScene(game, id);
        const input = mkInput();
        s.player.y -= 120;
        s.player.onGround = false;
        let lag = 0;
        let below = Infinity;
        for (let f = 0; f < 240; f++) {
          s.update(input);
          lag = Math.max(lag, Math.abs(s.cam.y - s.cameraY()));
          below = Math.min(below, s.cam.y + s.viewH - (s.player.y + s.player.h));
          if (s.player.onGround && f > 40) break;
        }
        rows.push({ id, lag, below });
      }
      expect('a fall keeps the landing point on screen',
        rows.every((r) => r.below > 24 && r.lag <= 28),
        rows.map((r) => `${r.id} ${r.below.toFixed(0)}px alla / ${r.lag.toFixed(0)}px jäljessä`).join(' '));
    }

    /*
     * Red before green (DESIGN.md §7) for the owner's third camera report:
     * "vertical camera movement when falling down from a platform that is
     * above the ground is still janky". The rise was fixed by anticipating
     * (CAM_TOP_LEAD); this is the same axis falling, and it was still wrong.
     *
     * **The complaint stated as a number: how long does the camera keep moving
     * after the player has stopped?** Feet stop dead on contact. An exponential
     * ease chasing a target that moves at v settles a constant (1-e)/e = 3v
     * behind it, so at TERMINAL the view was 12 px in debt at the moment of
     * touchdown and paid it off afterwards, gliding on while the body it was
     * following stood still. That is inertia, and the comment on `updateCamera`
     * says in as many words that inertia is what makes a platformer seasick —
     * the horizontal axis goes to real lengths to avoid it and the vertical
     * axis had it.
     *
     * Measured before, walking or jumping off a real ledge in a real level:
     * 6.97 px over 10 frames (4-1), 4.30 px over 9 (2-3), 4.12 px over 9 (2-1).
     * The ordinary 15-row levels hid it — 0.71 px over 2 frames in 1-1 — not
     * because the camera was well behaved but because those levels only have
     * 32 px of vertical travel and the level's own limit paid the debt off
     * mid-fall. It is the letterboxed and banded levels, where the camera has
     * room, that show what the mechanism actually does.
     *
     * The fixture is a real ledge and not a teleport: the deepest edge in the
     * level with four to eight tiles of air and a floor under it, walked off
     * and jumped off. Both, because they are different: walking off starts the
     * camera and the body from rest together, while jumping off means the body
     * is already at TERMINAL by the time it passes the line it left.
     *
     * `CAM_SNAP` was measured too and it is **not** part of this: over every
     * fall here the biggest gap between the view and where it wants to be is
     * 14.5 px against a threshold of 48, so no real fall has ever reached the
     * cut. (Landing *on* a raised platform does — see the note in level.js.)
     */
    {
      /** The deepest walk-off edge in the level with a floor under it. */
      const ledge = (s, minDrop, maxDrop) => {
        let best = null;
        for (let tx = 4; tx < s.w - 8; tx++) {
          for (let ty = 2; ty < s.h - 3; ty++) {
            if (!s.solidAt(tx, ty)) continue;
            if (s.solidAt(tx, ty - 1) || s.solidAt(tx, ty - 2) || s.solidAt(tx, ty - 3)) continue;
            if (s.solidAt(tx + 1, ty) || s.solidAt(tx + 1, ty - 1)) continue;
            let d = 1;
            while (ty + d < s.h && !s.solidAt(tx + 1, ty + d) && !s.solidAt(tx + 2, ty + d)) d++;
            if (ty + d >= s.h || d < minDrop || d > maxDrop) continue;
            if (!best || d > best.drop) best = { tx, ty, drop: d };
          }
        }
        return best;
      };

      const fall = (id, mode) => {
        reset();
        const s = new LevelScene(game, id);
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        const spot = ledge(s, 4, 8);
        if (!spot) return null;
        const p = s.player;
        p.x = spot.tx * TILE + 2;
        p.y = spot.ty * TILE - p.h;
        p.vx = 0;
        p.vy = 0;
        p.onGround = true;
        s.centerCamera();
        const input = mkInput();
        for (let f = 0; f < 40; f++) s.update(input);   // let the view settle
        let left = -1;
        let landed = -1;
        let after = 0;
        let tail = 0;
        let rise = 0;
        let below = Infinity;
        let pounded = false;
        for (let f = 0; f < 240; f++) {
          input.held = blank();
          input.pressed = blank();
          input.held.right = true;
          if (mode === 'jump' && f === 0) input.pressed.jump = true;
          if (mode === 'jump' && f < 14) input.held.jump = true;
          if (mode === 'pound' && left >= 0 && !p.onGround && !pounded && f > left + 2) {
            input.held.down = true;
            input.pressed.jump = true;
            input.held.jump = true;
            pounded = true;
          } else if (mode === 'pound' && pounded && !p.onGround) input.held.down = true;
          const wasGround = p.onGround;
          const camBefore = s.cam.y;
          s.update(input);
          const d = s.cam.y - camBefore;
          if (left < 0 && wasGround && !p.onGround) left = f;
          if (left >= 0) {
            rise = Math.max(rise, -d);
            below = Math.min(below, s.cam.y + s.viewH - (p.y + p.h));
          }
          if (left >= 0 && landed < 0 && p.onGround) landed = f;
          if (landed >= 0 && f > landed) {
            if (Math.abs(d) > 0.1) after = f - landed;
            tail += Math.abs(d);
          }
          if (landed >= 0 && f > landed + 45) break;
        }
        return {
          id, mode, drop: spot.drop, after, tail, rise, below, landed,
          pounded: mode !== 'pound' || pounded,
        };
      };

      const ids = ['1-1', '2-1', '2-3', '4-1', '5-1', '1-2'];
      const rows = [];
      for (const mode of ['walk', 'jump']) for (const id of ids) {
        const r = fall(id, mode);
        if (r) rows.push(r);
      }
      const say = (r) => `${r.id} ${r.mode} ${r.tail.toFixed(2)} px / ${r.after} framea`;

      /* 3.5 px is the ceiling for the same reason 2.5 is the ceiling on the
       * rising side: it is under the 6.97 px the debt produced and over the
       * 2.94 px the anticipation leaves, so it is the inertia that cannot come
       * back rather than the whole mechanism being frozen. */
      expect('a view that has fallen stops when the player stops',
        rows.length >= 10 && rows.every((r) => r.tail < 3.5 && r.after <= 8),
        rows.map(say).join(', '));

      /* And the anticipation must be bought out of itself, not out of the two
       * things that were already right: the view still may not creep upward
       * during a fall, and what you are falling towards still may not leave
       * the bottom of the window. */
      expect('anticipating the fall costs neither the ground below nor the hold',
        rows.every((r) => r.rise < 0.01 && r.below > 24),
        rows.map((r) => `${r.id} ${r.mode} ylös ${r.rise.toFixed(2)} px, `
          + `alla ${r.below.toFixed(0)} px`).join(', '));

      /*
       * The ground pound gets its own line and its own number, and the number
       * is bigger on purpose. The dive is 7.5 px/frame — 1.9x TERMINAL — and
       * it starts from a dead hang, so its own lag is 22.5 px rather than 12.
       * The lead may only grow as fast as gravity could grow it, which is what
       * stops the dive's standing start from jerking the view (that costs the
       * dive most of its lead), so this improves rather than disappears:
       * 11.51 px over 12 frames before, 8.47 over 11 after, worst case 2-3.
       */
      const pounds = [];
      for (const id of ids) {
        const r = fall(id, 'pound');
        if (r) pounds.push(r);
      }
      expect('a ground pound is not followed down by the view it landed under',
        pounds.length >= 5 && pounds.every((r) => r.pounded && r.tail < 9.5),
        pounds.map(say).join(', '));
    }

    /*
     * Red before green (DESIGN.md §7) for the fourth camera report, which is
     * the one the previous fix measured and deliberately did not fix blind:
     * **jumping onto a raised platform cuts.**
     *
     * The two fixes above are the falling axis and the top-of-frame axis. This
     * is the third and it is the one nobody complained about, because it does
     * not look like a camera bug — it looks like the level jumping. Landing is
     * `onGround` on the frame the feet touch, so the anchor moves the whole
     * height of the platform in one frame and `CAM_V_EASE` glides the view up
     * to it. That is by design and it is what every ordinary level does: the
     * biggest landing in a 208-row level moves the view 32 px and its first
     * frame is 8 px. In the two letterboxed levels the same landing is bigger
     * than the old `CAM_SNAP` threshold and was cut instead of glided.
     *
     * **A cut is the whole distance on one frame; a glide is a decaying series
     * over many.** So the measurement is the same one the rising fix used: the
     * largest single-frame upward move of the view over a real jump onto a real
     * platform, driven with the pad rather than teleported, because a teleport
     * would prove a step the player cannot actually take.
     *
     * The fixture picks, per level, the platform whose landing moves the view
     * furthest — in 2-1 and 2-3 alike that is a four-tile top at row 9 over the
     * desert floor at row 13, which frames at 30 against the floor's 80, so the
     * step is 50 px of the level's 80 px of travel.
     */
    {
      /**
       * The landing in this level that moves the view furthest, jumped for real.
       *
       * Candidates are ranked by how far the framing would move — `cameraY()`
       * asked twice, once with the feet on the lower floor and once with them
       * on the platform — rather than by how tall the platform is, because the
       * level's own clamp is what decides whether a tall step is a big move or
       * no move at all. Then the best few are jumped at with the pad, and the
       * first one the player genuinely lands on is the answer.
       */
      const climb = (id, power) => {
        reset(power);
        const probe = new LevelScene(game, id);
        const frameAt = (feet) => {
          probe.player.y = feet - probe.player.h;
          probe.player.onGround = true;
          probe.camAnchor = feet;
          return probe.cameraY();
        };
        const tops = [];
        for (let tx = 3; tx < probe.w - 3; tx++) {
          for (let ty = 3; ty < probe.h - 2; ty++) {
            if (!probe.solidAt(tx, ty) || probe.solidAt(tx, ty - 1)) continue;
            if (!probe.solidAt(tx + 1, ty)) continue;
            let fy = ty + 1;
            while (fy < probe.h && !probe.solidAt(tx - 2, fy)) fy++;
            /* Two to four tiles of step. Below two there is nothing to measure;
             * above four the jump does not reach the top and the run would be
             * measuring a landing that never happened — the measured budget is
             * 100 px of rise, and clearing a rim needs more than just reaching
             * its height. */
            if (fy >= probe.h || fy - ty < 2 || fy - ty > 4) continue;
            tops.push({ tx, ty, fy, move: frameAt(fy * TILE) - frameAt(ty * TILE) });
          }
        }
        tops.sort((a, b) => b.move - a.move);
        /* Several run-ups, because how much room a jump needs depends on the
         * platform and not on this fixture's opinion: four tiles clears the
         * four-tile step in 2-1 and lands short of the same step in 2-3. */
        for (const spot of tops.slice(0, 10)) for (const runUp of [4, 6, 8, 3]) {
          reset(power);
          const s = new LevelScene(game, id);
          s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
          s.time = 9999;
          s.clockStopped = true;
          const p = s.player;
          p.x = (spot.tx - runUp) * TILE;
          p.y = spot.fy * TILE - p.h;
          p.vx = 0;
          p.vy = 0;
          p.onGround = true;
          s.centerCamera();
          const input = mkInput();
          for (let f = 0; f < 40; f++) s.update(input);   // let the view settle
          let jumped = false;
          let step = 0;
          let settle = 0;
          let landed = -1;
          let onTop = false;
          for (let f = 0; f < 140; f++) {
            input.held = blank();
            input.pressed = blank();
            /* The pad is dropped the moment the feet touch. The complaint is
             * about the settling and not about what happens next, and a player
             * who keeps running off the far side would fold a second landing
             * into the number. */
            if (landed < 0) {
              input.held.right = true;
              input.held.run = true;
              if (p.onGround && !jumped) {
                input.pressed.jump = true;
                input.held.jump = true;
                jumped = true;
              } else if (jumped && p.vy < 0) input.held.jump = true;
            }
            const wasAir = !p.onGround;
            const camBefore = s.cam.y;
            s.update(input);
            const d = camBefore - s.cam.y;
            if (landed < 0 && jumped && wasAir && p.onGround) {
              landed = f;
              onTop = p.y + p.h <= spot.ty * TILE + 1;
              if (!onTop) break;                              // landed short
              /* Stopped dead on touchdown. The complaint is vertical, and a
               * body that slides on and off the far rim would fold a second
               * landing and a fall into a number that is meant to be about
               * one rise. */
              p.vx = 0;
            }
            if (landed >= 0) {
              step = Math.max(step, d);
              // How long the view took to arrive: a cut arrives on the frame it
              // happens, an animation does not.
              if (!settle && Math.abs(s.cam.y - s.cameraY()) <= 1) settle = f - landed + 1;
            }
            if (p.dying) break;
            if (landed >= 0 && (settle || f > landed + 40)) break;
          }
          if (onTop) return { id, level: power.level, top: spot.ty, step, settle };
        }
        return null;
      };

      const rows = [];
      for (const [id, power] of [['2-1', { type: null, level: 0 }],
        ['2-1', { type: 'leaf', level: 3 }], ['2-3', { type: null, level: 0 }],
        ['2-3', { type: 'leaf', level: 3 }], ['1-1', { type: null, level: 0 }],
        ['4-1', { type: null, level: 0 }]]) {
        const r = climb(id, power);
        if (r) rows.push(r);
      }
      /* 13 px is the ceiling for the same reason 2.5 and 3.5 are the ceilings
       * on the other two axes: it is far under the 50 px the cut produced and
       * just over the 12.5 px the ease produces on its first frame, so it is
       * the cut that cannot come back rather than the mechanism being frozen.
       * 12.5 is `CAM_V_EASE` × 50 and nothing else, which is exactly what an
       * ordinary level's 32 px landing already does at 8 px.
       *
       * **Liikkumaton näkymä ei ole tässä vika, vaan tulos** (17.8.2026):
       * ikkuna on nauhan poistuttua 240 px ja tavallinen kenttä on 15 riviä
       * eli täsmälleen yhtä korkea, joten siellä ei ole mitään mihin kamera
       * voisi nousta. Väite koskee siis niitä näkymiä joilla on varaa liikkua
       * — kirjekuoripalkitetut ja pystykentät — ja liikkumattomat luetellaan
       * silti riville, jottei kadonnut liike voi piiloutua tyhjään joukkoon. */
      const movers = rows.filter((r) => r.step > 0.01);
      expect('a view that has to rise on landing animates instead of cutting',
        rows.length >= 5 && movers.length >= 2
        && movers.every((r) => r.step < 13 && r.settle > 4),
        rows.map((r) => `${r.id} taso ${r.level}: ${r.step.toFixed(2)} px/frame, `
          + `asettui ${r.settle || '>40'} framessa`).join(', '));
    }

    /* ------------------------------- kiipeäminen ------------------------- */
    /*
     * PYSTYKENTTÄ: KAMERA, BOTTI JA SE ETTÄ KUMPIKAAN EI KOSKE MUUHUN PELIIN.
     *
     * Red before green (DESIGN.md §7) for the owner's fifth camera report, and
     * it is not a bug this time but a shape the game does not have yet: *"the
     * player character stops there, and then the camera tilts down… and then
     * play continues with the player character at the top of the screen. That
     * way, if you're going down, you see what's beneath you."*
     *
     * The fixture is a CLIMB and not a level: 20 columns — one screen exactly,
     * see `VERTICAL_COLS` — by 45 rows, thirteen plank rungs three tiles apart,
     * a power block in the bottom quarter, bedrock across the bottom because a
     * fall here is a setback and not a death, and the flag at the top. It is
     * built here rather than in `src/data/levels/` for the same reason
     * `scoreRows` exists: another agent owns the level files, the game ships no
     * vertical level yet, and a capability proved only by the content it is
     * about to bless is not proved. `LevelScene` takes the definition directly.
     *
     * What the red said, on the code as it stood this morning:
     *
     *   - the paging test, with the same fixture built as an ordinary level:
     *     `0 sivunvaihtoa, 388 liikeframea 779:stä, pahin 12.00 px` — the
     *     ordinary ease doing exactly what it is meant to do on the wrong
     *     shape of level, moving on every other frame and never holding still.
     *   - the bot: `96 % oikealle, 11 % ylös, ei maalia` — the run-right-and-
     *     jump bot finds the right-hand wall and stays there.
     *   - the rules: reading the same fixture horizontally reports six problems
     *     and not one of them is true — `no power-up in the first quarter`,
     *     four `platform at … leads to nothing`, `nothing leads into the sky
     *     band`.
     *   - the meter: `1920.5` against a world-1 level's 100, from summing a
     *     gap-shaped cost over every rung of a ladder.
     */
    {
      const { RULE_CONSTANTS, climbGraph } = await import('/src/data/rules.js');
      const { makeClimber } = await import('/tools/climb-bot.js');
      const { TILE: TILE_PX } = await import('/src/gfx/tiles.js');
      const budget = await (await fetch('/tools/jump-budget.json')).json();
      const W = RULE_CONSTANTS.VERTICAL_COLS;
      const H = 45;

      /** The fixture climb. One fault at a time, the same way the tall one does. */
      const climbRows = (over = {}) => {
        const rows = Array.from({ length: H }, () => ' '.repeat(W));
        const put = (y, s) => { rows[y] = s.padEnd(W, ' ').slice(0, W); };
        put(3, '              F     ');
        [4, 7, 10, 13, 16, 19, 22, 25, 28, 31, 34, 37, 40].forEach((y, i) => {
          /* Lankut eivät saa mennä päällekkäin, ja se on nyt sääntö eikä maku
           * (`checkClimbTraverse`): jaettu sarake tarkoittaa saraketta jolla on
           * jalansija joka askelmalla, eli kiipeilyn voi ratkaista hyppimällä
           * paikallaan. Tämä koekenttä oli 7-T:n vian näköinen siihen asti kun
           * sääntö kirjoitettiin ja kaatoi molemmat samalla lauseella. */
          put(y, i % 2 === 0 ? '          --------- ' : ' ---------          ');
        });
        put(39, '     !              ');
        put(42, '  1                 ');
        put(43, '####################');
        put(44, '####################');
        for (const [y, s] of Object.entries(over)) put(Number(y), s);
        return rows;
      };
      const climbDef = (over) => ({
        id: 'vFix', theme: 'cloud', bg: 'clouds', music: 'cloud', time: 9999,
        boss: false, bossVariant: 0, bands: null, vertical: true, rows: climbRows(over),
      });

      /**
       * One climb, driven by the shared climber, with the camera watched.
       *
       * @param {number} pageFrames 0 = a cut, >0 = a pan with the player frozen
       */
      const runClimb = (power, pageFrames, over) => {
        reset(power);
        const s = new LevelScene(game, 'vFix', climbDef(over));
        s.camPageFrames = pageFrames;
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        let finished = null;
        game.finishLevel = (r) => { finished = r; };
        const bot = makeClimber(s, climbRows(over), budget);
        const input = mkInput();
        const startFeet = s.player.y + s.player.h;
        let top = startFeet;
        let moves = 0;            // frames on which the page line moved at all
        let pages = 0;            // and how many of those completed a page
        let biggest = 0;
        let frozen = 0;           // frames the player could not act
        let midArc = 0;           // pages taken while a jump was still rising
        let net = 0;              // frames the headroom net was the binding term
        let headOut = 0;          // px the head ever went above the frame
        let feetOut = 0;          // px the feet ever went below it
        let firstSeen = -1;       // frames from a page to the new ground showing
        let frames = 0;
        for (let f = 0; f < 4000 && !finished; f++) {
          frames = f;
          const p = s.player;
          const before = s.camPageY;
          const wasFrozen = s.camPage > 0;
          /* Only the played part of the level is measured. Touching the flag
           * hands the body to the clear animation, which walks it off the top
           * platform and back down the shaft — five pages of camera that
           * nobody is playing, and counting them would put the freeze's bill
           * on the wrong side of the ledger. */
          const playing = s.state === 'play';
          const want = bot.step();
          input.held = blank();
          input.pressed = blank();
          input.held.left = want.left;
          input.held.right = want.right;
          input.held.jump = want.jump;
          input.held.run = want.run;
          input.pressed.jump = want.press;
          s.update(input);
          if (!playing) continue;
          if (wasFrozen) frozen++;
          if (Math.abs(s.camPageY - before) > 0.001) {
            moves++;
            biggest = Math.max(biggest, Math.abs(s.camPageY - before));
            if (s.camPage <= 0) {
              pages++;
              if (firstSeen < 0) firstSeen = Math.max(0, pageFrames);
              if (!p.onGround && p.vy < 0) midArc++;
            }
          }
          if (Math.abs(s.cam.y - s.camPageY) > 0.001) net++;
          headOut = Math.max(headOut, s.cam.y - p.y);
          feetOut = Math.max(feetOut, (p.y + p.h) - (s.cam.y + s.viewH));
          top = Math.min(top, p.y + p.h);
        }
        return {
          cleared: !!(finished && finished.cleared),
          climbed: Math.round(((startFeet - top) / (startFeet - 4 * TILE_PX)) * 100),
          pages, moves, biggest, frozen, midArc, net, headOut, feetOut,
          firstSeen, frames, camX: s.cam.x,
        };
      };

      const cut = runClimb({ type: null, level: 0 }, 0);
      const held = runClimb({ type: null, level: 0 }, 12);
      const tall = runClimb({ type: 'leaf', level: 5 }, 0);

      /*
       * **The view holds still and then pages.** A cut is the whole distance on
       * one frame and an ease is a decaying series over many, so the question
       * is asked as a count rather than as a size: how many frames did the page
       * line move on, and how many pages were there? An eased camera moves on
       * almost every frame; this one may only move on the frames it pages, and
       * each of those moves is most of a screen.
       */
      expect('a climbing view holds still and then pages',
        cut.pages >= 4 && cut.moves === cut.pages && cut.biggest >= 64,
        `${cut.pages} sivunvaihtoa, ${cut.moves} liikeframea ${cut.frames}:sta, `
        + `suurin askel ${cut.biggest.toFixed(2)} px`);

      /* Locked sideways: one screen wide means `cam.x` is 0 for the whole
       * level, not merely small. */
      expect('a climb is locked sideways',
        cut.camX === 0 && climbRows()[0].length === 20,
        `cam.x ${cut.camX}, leveys ${climbRows()[0].length} saraketta`);

      /* And the body stays in the picture — at the smallest size, which is the
       * promise, and at the largest, which is where it is hardest. Without the
       * headroom net inside `applyPageView` the head went 45.31 px above the
       * frame on the last jump before every page; the net is what buys the
       * zero, and the price of the net is the frames it is the binding term,
       * which is reported rather than hidden. */
      expect('a paging view keeps the climber in the frame',
        cut.headOut <= 0 && cut.feetOut <= 0 && tall.headOut <= 0 && tall.feetOut <= 0,
        `taso 0: pää ${cut.headOut.toFixed(2)} px yli, jalat ${cut.feetOut.toFixed(2)} px ali, `
        + `katto käytössä ${cut.net}/${cut.frames} framea — `
        + `taso 5: ${tall.headOut.toFixed(2)} / ${tall.feetOut.toFixed(2)}, `
        + `katto ${tall.net}/${tall.frames}`);

      /*
       * FREEZE VERSUS NO FREEZE, MEASURED RATHER THAN ARGUED.
       *
       * The owner's instinct was to freeze the player while the camera moves.
       * Both are built; this is the table. The decisive column is the last one:
       * because the page hangs off `camAnchor`, which does not move while a
       * jump is rising, a page **cannot** happen in mid-air — so the freeze has
       * nothing left to protect the player from, and the whole of what it does
       * is take the frames away.
       */
      expect('freezing the climber during a page buys nothing it does not already have',
        cut.midArc === 0 && held.midArc === 0 && cut.frozen === 0
        && held.frozen === held.pages * 12 && cut.cleared && held.cleared
        && held.frames > cut.frames,
        `leikkaus: ${cut.frozen} framea ohjausta pois, maa näkyvissä `
        + `${cut.firstSeen} framen päästä, ${cut.midArc}/${cut.pages} kesken nousua, `
        + `kiipeäminen ${cut.frames} framea — 12 framen panorointi: ${held.frozen} framea `
        + `pois, ${held.firstSeen} framen päästä, ${held.midArc}/${held.pages} kesken `
        + `nousua, kiipeäminen ${held.frames} framea`);

      /*
       * THE BOT, AND THE PROMISE IT CARRIES.
       *
       * DESIGN.md §5 promises the route works at the smallest size with no
       * power-up, and that promise has to survive the change of axis rather
       * than be quietly dropped with it. So this is the same proof
       * `playable.mjs` gives every horizontal level — power level 0, no
       * enemies, `finishLevel` actually fired — with the only difference being
       * which way the bot is trying to go.
       */
      expect('a climb is passable at power 0, and the bot climbs it',
        cut.cleared && cut.climbed >= 99,
        `${cut.climbed} % kiivetty, maali ${cut.cleared ? 'saavutettu' : 'saavuttamatta'}, `
        + `${cut.pages} sivunvaihtoa`);

      /* The climber may not be cleverer than the validator: a bot that clears
       * what the rules refuse would make the rules a formality. Same graph,
       * asked twice. */
      {
        const g = climbGraph(climbRows(), budget);
        const carry = [0, 1, 2, 3, 4].map((r) => g.carry(r));
        expect('the bot and the validator read the same jump',
          carry.join(',') === '6,4,3,2,1' && g.platforms.length === 15,
          `kantama nousun mukaan ${carry.join(',')} ruutua, ${g.platforms.length} tasannetta`);
      }

      /*
       * AND IT RUNS IN EXACTLY THE TWO LEVELS THAT ASKED FOR IT.
       *
       * The owner's constraint, in his own words: the paging camera is a
       * vertical-level feature and the horizontal levels keep exactly the
       * vertical follow they have. That is guaranteed structurally — every
       * paging branch is behind `this.vertical`, which is `def.vertical` — and
       * guaranteed is not measured, so it is measured: every level in the game
       * is driven for 600 frames and asked whether it ever paged.
       *
       * **Tämä väite oli `no shipped level ever pages` siihen asti kun peli sai
       * kaksi pystykenttää (10.8.2026), ja se on nyt kavennettu eikä
       * poistettu.** Vanha muoto oli oikea niin kauan kuin pystykenttiä oli
       * nolla: silloin "yksikään ei sivuta" ja "vain pystykenttä sivuttaa"
       * olivat sama lause. Nyt ne eroavat, ja se mitä omistaja pyysi
       * suojeltavaksi — vaakakentän kamera — on jälkimmäinen. Vaakakentät
       * mitataan täsmälleen kuten ennen; pystykentät poistetaan tästä
       * silmukasta nimeltä ja lasketaan, ja niiden oma sivutus mitataan
       * kiipeilijällä lohkossa "pystykentät kentissä" — tämä botti juoksee
       * oikealle, mikä on pystykentässä seinään käveleminen eikä mittaus.
       */
      {
        const bad = [];
        const climbs = [];
        for (const id of levelIds()) {
          reset();
          const s = new LevelScene(game, id);
          s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
          s.time = 9999;
          s.clockStopped = true;
          if (s.vertical) { climbs.push(id); continue; }
          const input = mkInput();
          for (let f = 0; f < 600; f++) {
            input.held = blank();
            input.pressed = blank();
            input.held.right = true;
            input.held.run = true;
            if (f % 45 === 20) { input.pressed.jump = true; input.held.jump = true; }
            else if (f % 45 > 20 && f % 45 < 36) input.held.jump = true;
            s.update(input);
            if (s.player.dying) break;
          }
          if (s.camPages || s.camPage) bad.push(`${id}:${s.camPages}`);
        }
        expect('vain pystykenttä sivuttaa — yksikään vaakakenttä ei',
          bad.length === 0 && climbs.length === 2,
          bad.length ? bad.join(' ')
            : `${levelIds().length - climbs.length} vaakakenttää, 0 sivunvaihtoa — `
              + `pystykentät ${climbs.join(' ') || '—'}`);
      }
    }

    /* ---- pystykentät kentissä ---- */
    /*
     * KAKSI PYSTYKENTTÄÄ, JA NE OVAT TARKOITUKSELLA ERI KENTTIÄ.
     *
     * Yllä oleva lohko todistaa **kyvyn** koekentällä, ja se on oikein: kyky
     * jota kokeillaan vain sillä sisällöllä jonka se siunaa ei ole kokeiltu.
     * Tämä lohko todistaa **toimitetun sisällön**, ja se on eri väite. Koekenttä
     * on kolmentoista lankun tikkaat joissa jokainen askelma on sama; nämä kaksi
     * ovat kenttiä joita pelataan, ja kysymykset ovat siksi toiset.
     *
     * Kentät ovat `7-T` TERMIIKKI (kaasukehä, ylös) ja `6-K` KAIVAUTUMINEN
     * (luulaakso, alas). Ne eivät ole toistensa peilikuvia, ja se on koko syy
     * siihen että ne ovat kaksi kenttää eikä yksi kahteen suuntaan
     * (IDEAS.md I):
     *
     *   - **Ylöspäin virhe maksaa sivun.** Pudotus vie takaisin alemmalle
     *     lavalle ja kiivetään uudestaan, joten kiipeilyssä ei tarvita — eikä
     *     saa olla — tappavaa maastoa. Mitattuna: 7-T:ssä on **nolla** tappavaa
     *     ruutua, ja jokainen sen tasanne on sellainen että alla on jotain
     *     alle yhden ruudun päässä. Sen vaikeus on askelman korkeus ja se
     *     kuinka kapealle pitää osua.
     *   - **Alaspäin virhe kantaa eteenpäin, väärään paikkaan**, joten
     *     rangaistus on rakennettava maastoon. Mitattuna: 6-K:ssa on piikkejä
     *     usealla rivillä, ja ne ovat siellä minne väärä pudotus vie.
     *
     * Kolme väitettä on tässä sellaisia joita `validateLevel` ei tee, ja
     * jokainen on tämän muodon oma:
     *
     *   1. **Ei ansoja.** `checkClimb` tulvittaa lähdöstä maaliin ja on
     *      tyytyväinen kun maali löytyy. Kaivautumiskentässä se ei riitä:
     *      pudotus vie *eteenpäin*, joten pelaaja päätyy paikkoihin joihin ei
     *      tähdännyt, ja tasku josta ei pääse pois läpäisisi validaattorin ja
     *      jumittaisi pelaajan. Tässä kysytään vahva yhteys: **jokaisesta
     *      tasanteesta johon lähdöstä pääsee, maaliin pääsee edelleen.** Se on
     *      juuri se ero jonka IDEAS.md nimeää — umpiperä saa maksaa kiipeämisen
     *      takaisin, ei kenttää.
     *   2. **Umpiperäsääntö on käytössä eikä vain voimassa.** DESIGN.md kohdan
     *      5 pystymuoto sanoo että tasanne josta ei jatketa on oltava käymisen
     *      arvoinen. Sääntö jota yksikään toimitettu kenttä ei laukaise on
     *      sääntö jota ei ole koeteltu, joten tässä lasketaan että toimitetussa
     *      sisällössä on ainakin yksi maksettu umpiperä.
     *   3. **Botti pelaa molemmat läpi voimatasolla 0** — sama moottori, sama
     *      fysiikka, `finishLevel` oikeasti laukeaa — ja kamera sivuttaa
     *      molemmissa. Kiipeilijä on sama `tools/climb-bot.js` jonka koekenttä
     *      yllä todistaa, joten tämä ei ole toinen botti vaan sama botti
     *      toisella sisällöllä.
     */
    {
      const { getLevel } = await import('/src/data/levels.js');
      const { validateLevel, climbGraph } = await import('/src/data/rules.js');
      const { makeClimber } = await import('/tools/climb-bot.js');
      const climbBudget = await (await fetch('/tools/jump-budget.json')).json();

      const climbIds = levelIds().filter((id) => getLevel(id).vertical);
      const shape = (id) => {
        const rows = getLevel(id).rows;
        return { id, w: rows[0].length, h: rows.length, rows };
      };

      expect('peli toimittaa tasan kaksi pystykenttää, yhden ylös ja yhden alas',
        climbIds.join(' ') === '6-K 7-T',
        climbIds.length
          ? climbIds.map((id) => { const s = shape(id); return `${id} ${s.w}×${s.h}`; }).join(', ')
          : 'ei yhtään pystykenttää');

      /* Leveys ei ole enimmäismäärä vaan leveys, ja tämä on se kohta jossa se
       * koskee oikeaa kenttää eikä koekenttää: 21 saraketta kytkisi
       * vaakavierityksen takaisin päälle juuri siinä muodossa jossa sitä ei saa
       * olla. Korkeus on toinen puolisko — yhden ruudun korkuinen "pystykenttä"
       * ei sivuttaisi kertaakaan. */
      {
        const wrong = climbIds.filter((id) => shape(id).w !== 20 || shape(id).h <= 15);
        expect('molemmat pystykentät ovat tasan ruudun levyisiä ja montaa ruutua korkeita',
          climbIds.length === 2 && wrong.length === 0,
          climbIds.map((id) => { const s = shape(id); return `${id} ${s.w} saraketta × ${s.h} riviä`; })
            .join(', ') || 'ei mitattavaa');
      }

      /* Suunta luetaan ruudukosta eikä nimestä: lähtö ja maali, ja kumpi on
       * ylempänä. Kaksi kenttää, kaksi merkkiä. */
      {
        const dirOf = (id) => {
          const { rows } = shape(id);
          const find = (ch) => {
            for (let y = 0; y < rows.length; y++) if (rows[y].includes(ch)) return y;
            return -1;
          };
          return { start: find('1'), goal: find('F') };
        };
        const dirs = climbIds.map((id) => ({ id, ...dirOf(id) }));
        const up = dirs.filter((d) => d.goal < d.start);
        const down = dirs.filter((d) => d.goal > d.start);
        expect('toinen pystykenttä nousee ja toinen laskee',
          up.length === 1 && down.length === 1 && up[0].id === '7-T' && down[0].id === '6-K',
          dirs.map((d) => `${d.id} rivi ${d.start} → ${d.goal}`).join(', ') || 'ei mitattavaa');
      }

      /* Pystysäännöt luetaan toimitetuista kentistä. Sama kutsu kuin
       * `design rules across every level` tekee, tässä nimeltä, jotta
       * huomautus näkyy sellaisenaan eikä lukumääränä. */
      {
        const probs = climbIds.flatMap((id) => validateLevel(shape(id).rows, climbBudget, { vertical: true })
          .map((p) => `${id}: ${p}`));
        expect('molemmat pystykentät läpäisevät pystysäännöt',
          climbIds.length === 2 && probs.length === 0,
          probs.length ? probs.slice(0, 3).join(' / ')
            : `${climbIds.length} kenttää, 0 huomautusta`);
      }

      /*
       * EI ANSOJA — vahva yhteys, ei pelkkä läpäisy.
       *
       * Sama verkko kuin validaattorilla ja botilla, kysyttynä toisin päin:
       * jokaisesta tasanteesta johon lähdöstä pääsee, tulvitetaan uudestaan ja
       * kysytään löytyykö maali. Alaspäin mentäessä tämä on se väite joka
       * pitää kentän pelattavana — pudotus vie eteenpäin, ei takaisin.
       */
      {
        const trapped = [];
        const counts = [];
        for (const id of climbIds) {
          const { rows } = shape(id);
          const g = climbGraph(rows, climbBudget);
          const at = (x, y) => rows[y][x];
          const find = (ch) => {
            for (let y = 0; y < rows.length; y++) {
              for (let x = 0; x < rows[0].length; x++) if (at(x, y) === ch) return { x, y };
            }
            return null;
          };
          const landsOn = (x, y) => {
            let best = null;
            for (const p of g.platforms) {
              if (p.y < y || x < p.x0 || x > p.x1) continue;
              if (!best || p.y < best.y) best = p;
            }
            return best;
          };
          const flood = (seed) => {
            const seen = new Set([seed]);
            const stack = [seed];
            while (stack.length) for (const n of g.edges[stack.pop()]) if (!seen.has(n)) { seen.add(n); stack.push(n); }
            return seen;
          };
          const st = find('1');
          const go = find('F');
          const from = st && landsOn(st.x, st.y);
          const to = go && landsOn(go.x, go.y);
          if (!from || !to) { trapped.push(`${id}: lähtö tai maali ei seiso millään`); continue; }
          const reach = flood(from.i);
          for (const i of reach) {
            if (!flood(i).has(to.i)) trapped.push(`${id}: ${g.platforms[i].x0},${g.platforms[i].y}`);
          }
          counts.push(`${id} ${reach.size}/${g.platforms.length} tasannetta`);
        }
        expect('jokaisesta tasanteesta johon pääsee, pääsee vielä maaliin',
          climbIds.length === 2 && trapped.length === 0,
          trapped.length ? trapped.slice(0, 4).join(' / ') : counts.join(', ') || 'ei mitattavaa');
      }

      /*
       * UMPIPERÄSÄÄNTÖ ON KÄYTÖSSÄ, EI VAIN VOIMASSA.
       *
       * Lasketaan samalla määritelmällä kuin `checkClimb`: tasanne joka on
       * saavutettavissa, ei ole maalin oma, eikä siitä lähde yhtään ylöspäin
       * vievää kaarta. Sellainen tasanne on kentässä vain jos se on maksettu —
       * validaattori olisi hylännyt maksamattoman — joten tämä luku on
       * "montako kertaa sääntö oikeasti mitattiin toimitetussa sisällössä".
       */
      {
        const paid = [];
        for (const id of climbIds) {
          const { rows } = shape(id);
          const g = climbGraph(rows, climbBudget);
          let n = 0;
          for (const p of g.platforms) {
            if (g.edges[p.i].some((j) => g.platforms[j].y < p.y)) continue;
            n++;
          }
          paid.push({ id, n });
        }
        expect('toimitettu pystykenttä koettelee umpiperäsäännön',
          paid.length === 2 && paid.some((p) => p.n > 0),
          paid.map((p) => `${p.id} ${p.n} umpiperää`).join(', ') || 'ei mitattavaa');
      }

      /*
       * MIKÄ RANKAISEE MISTÄKIN, LUKUINA.
       *
       * Kiipeilyssä pudotus on takaisku, joten maasto ei saa tappaa: nolla
       * tappavaa ruutua. Kaivautumisessa pudotus vie eteenpäin, joten
       * rangaistuksen on oltava maastossa: piikkirivejä enemmän kuin nolla.
       * Tämä on sama ero kuin IDEAS.md I:ssä, mitattuna eikä muistettuna.
       */
      {
        const lethalRows = (id) => (climbIds.includes(id)
          ? shape(id).rows.filter((r) => /[\^W]/.test(r)).length : -1);
        const upKill = lethalRows('7-T');
        const downKill = lethalRows('6-K');
        expect('kiipeäminen ei tapa maastolla, kaivautuminen tappaa',
          upKill === 0 && downKill >= 4,
          `7-T ${upKill} tappavaa riviä, 6-K ${downKill}`);
      }

      /*
       * JA PILVIMAAILMAN OMA VÄITE, KÄÄNNETTYNÄ TOISELLE AKSELILLE.
       *
       * Kohta 3 luulaakson ja pilvimaailman lohkossa mittaa että kaasukehässä
       * on lattia eikä se ole bonushuone venytettynä: `sky_garden` on 0 %
       * maata ja 100 % lautaa, ja maailman kentät ovat 80 %+ / alle 25 %.
       * `7-T`:llä ei ole riviä 13, joten se jää sieltä pois — ja pois jäävä
       * väite on hiljaa lakkaava väite, mikä on pahempi kuin korvattu.
       *
       * Pystyvastine on sama kysymys ilman lattiariviä: **kuinka suuri osa
       * siitä mille voi seistä on pakattua pilveä eikä lautaa.** Bonushuoneessa
       * vastaus on nolla; tässä sen pitää olla huomattava osa. Kenttä on
       * rakennettu niin että alempi puolisko on pankkia ja ylempi ohutta, eli
       * luku on rakenteen mitta eikä sattuma.
       */
      {
        const { CHUNKS } = await import('/src/data/chunks.js');
        const bankShare = (rows) => {
          let bank = 0;
          let plank = 0;
          for (const row of rows) {
            for (const ch of row) {
              if (ch === '#' || ch === 'X') bank++;
              else if (ch === '-') plank++;
            }
          }
          return bank + plank ? (bank / (bank + plank)) * 100 : 0;
        };
        const climbShare = climbIds.includes('7-T') ? bankShare(shape('7-T').rows) : -1;
        const garden = bankShare(CHUNKS.sky_garden.rows);
        expect('pystykentässäkin kaasukehällä on lattia, bonushuoneella ei',
          climbShare >= 40 && garden === 0,
          `7-T ${climbShare.toFixed(0)} % pakattua pilveä jalansijasta, `
          + `sky_garden ${garden.toFixed(0)} %`);
      }

      /*
       * JA BOTTI PELAA MOLEMMAT LÄPI VOIMATASOLLA 0.
       *
       * Sama kiipeilijä kuin koekentällä, sama moottori, samat viholliset pois
       * (maasto on kysymys; vihollisen alle jääminen on eri testi ja se on jo
       * olemassa). Sivunvaihdot lasketaan samalla ajolla: kenttä joka ei
       * sivuta kertaakaan on pystykenttä vain nimeltä.
       */
      {
        const runs = [];
        for (const id of climbIds) {
          const { rows } = shape(id);
          reset({ type: null, level: 0 });
          let finished = null;
          game.finishLevel = (r) => { finished = r; };
          const s = new LevelScene(game, id);
          game.setScene(s);
          s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
          s.time = 9999;
          s.clockStopped = true;
          const bot = makeClimber(s, rows, climbBudget);
          const input = mkInput();
          const startFeet = s.player.y + s.player.h;
          const goalFeet = (bot.goalPlat ? bot.goalPlat.y : 0) * 16;
          const span = Math.abs(goalFeet - startFeet) || 1;
          let best = startFeet;
          let frames = 0;
          for (let f = 0; f < 9000 && !finished; f++) {
            frames = f;
            const want = bot.step();
            input.held = blank();
            input.pressed = blank();
            input.held.left = want.left;
            input.held.right = want.right;
            input.held.jump = want.jump;
            input.held.run = want.run;
            input.pressed.jump = want.press;
            s.update(input);
            const feet = s.player.y + s.player.h;
            if (Math.abs(feet - goalFeet) < Math.abs(best - goalFeet)) best = feet;
            if (s.state === 'dead') break;
          }
          runs.push({
            id,
            cleared: !!(finished && finished.cleared),
            went: Math.round((Math.abs(best - startFeet) / span) * 100),
            pages: s.camPages,
            frames,
            died: s.state === 'dead',
          });
        }
        expect('kiipeilijä pelaa molemmat pystykentät läpi voimatasolla 0, ja kamera sivuttaa',
          runs.length === 2 && runs.every((r) => r.cleared && r.pages >= 3),
          runs.map((r) => `${r.id}: ${r.went} % kuljettu, ${r.pages} sivunvaihtoa, `
            + `${r.frames} framea, maali ${r.cleared ? 'saavutettu' : r.died ? 'kuoli' : 'saavuttamatta'}`)
            .join(' — ') || 'ei mitattavaa');
      }
    }

    /* ---------------------------- osioitu kenttä ------------------------ */
    /*
     * OSIOITU KENTTÄ: KENTTÄ JOKA VAIHTAA AKSELIA KESKEN MATKAN.
     *
     * Omistaja pyysi kenttää *"jossa on sekä vaaka- että pystysuuntaista
     * liikettä, vuorotellen"*, ja `7-P` on se kenttä. Kameran puoli siitä
     * (`LevelScene.updateSegment`) toimitettiin aiemmin; tässä mitataan se mikä
     * on kenttää eikä kameraa.
     *
     * Neljä väitettä, ja jokainen on olemassa siksi että sen vastakohta olisi
     * mennyt läpi huomaamatta:
     *
     *   1. **Säännöt luetaan palasta eikä kentästä, ja ne osaavat hylätä.**
     *      Ensimmäinen versio osiotarkastuksesta palautti *ei ongelmia*
     *      ruudukolle josta oli poistettu yksi nousun puola. Se meni läpi
     *      koska pystypalasta puuttuvat aloitusmerkki ja lippu, jolloin
     *      kulkukelpoisuustarkastus palasi heti — sääntö joka ei voi laueta.
     *      Tässä ajetaan viisi rikottua koekappaletta, ja jokaisen on
     *      valitettava.
     *   2. **Osiointi kattaa koko leveyden.** Sarakkeet joita mikään osio ei
     *      omista jäisivät lukematta kokonaan, mikä on hiljainen aukko eikä
     *      virhe.
     *   3. **Kaista ja suunta johdetaan, ei kirjoiteta.** `segmentSlices` on
     *      ainoa paikka jossa ne lasketaan, ja sekä säännöstö että
     *      `tools/difficulty.mjs` lukevat ne sieltä. Tässä varmistetaan että
     *      johdetut luvut vastaavat sitä mitä kentässä oikeasti on.
     *   4. **Botti pelaa sen läpi voimatasolla 0 ja kamera kääntyy.** Sama
     *      kiipeilijä kuin pystykentillä, koska `isClimb` tuntee osioidun
     *      kentän. Käänteet lasketaan ajosta: kenttä joka ei vaihda akselia
     *      kertaakaan on osioitu vain nimeltä.
     */
    {
      const { getLevel } = await import('/src/data/levels.js');
      const { validateLevel, segmentSlices } = await import('/src/data/rules.js');
      const { makeClimber, isClimb } = await import('/tools/climb-bot.js');
      const segBudget = await (await fetch('/tools/jump-budget.json')).json();

      const segIds = levelIds().filter((id) => {
        const def = getLevel(id);
        return Array.isArray(def.segments) && def.segments.length;
      });

      expect('peli toimittaa osioidun kentän, ja kiipeilijä tunnistaa sen omakseen',
        segIds.length >= 1 && segIds.every((id) => isClimb(getLevel(id)) && !getLevel(id).vertical),
        segIds.length
          ? segIds.map((id) => `${id} ${getLevel(id).segments.length} osiota`).join(', ')
          : 'ei osioituja kenttiä');

      /* Osiointi kattaa koko leveyden, ja palat vuorottelevat akselia — muuten
       * "vuorotteleva kenttä" olisi nimi eikä muoto. */
      {
        const bad = [];
        for (const id of segIds) {
          const def = getLevel(id);
          const { slices, error } = segmentSlices(def.rows, def.segments);
          if (error) { bad.push(`${id}: ${error}`); continue; }
          const covered = slices.reduce((a, sl) => a + (sl.to - sl.from), 0);
          if (covered !== def.rows[0].length) bad.push(`${id}: osiot kattavat ${covered}/${def.rows[0].length}`);
          for (let i = 1; i < slices.length; i++) {
            if (slices[i].vertical === slices[i - 1].vertical) {
              bad.push(`${id}: osiot ${i} ja ${i + 1} ovat samalla akselilla`);
            }
          }
        }
        expect('osiot kattavat koko kentän ja vuorottelevat akselia',
          segIds.length > 0 && bad.length === 0,
          bad.length ? bad.slice(0, 3).join(' / ')
            : segIds.map((id) => {
              const def = getLevel(id);
              return `${id}: ${segmentSlices(def.rows, def.segments).slices
                .map((sl) => `${sl.from}-${sl.to}${sl.vertical ? '↑' : '→'}`).join(' ')}`;
            }).join(', '));
      }

      /* Kaista ja suunta ovat johdettuja lukuja, ja tässä ne verrataan siihen
       * mitä ruudukossa on: vaakaosion lattiarivillä on oltava kiinteää, ja
       * pystyosion tulo- ja lähtörivin on oltava naapureiden lattiat. */
      {
        const bad = [];
        for (const id of segIds) {
          const def = getLevel(id);
          const { slices } = segmentSlices(def.rows, def.segments);
          for (const sl of slices) {
            if (!sl.vertical) {
              const floor = def.rows[sl.floorRow].slice(sl.from, sl.to);
              if (!/[#X]/.test(floor)) bad.push(`${id} osio ${sl.i + 1}: johdetulla lattiarivillä ${sl.floorRow} ei ole maata`);
              if (sl.rows.length !== 16) bad.push(`${id} osio ${sl.i + 1}: kaista on ${sl.rows.length} riviä`);
            } else {
              const neighbours = slices.filter((o) => !o.vertical).map((o) => o.floorRow);
              if (!neighbours.includes(sl.entryRow)) bad.push(`${id} osio ${sl.i + 1}: tulorivi ${sl.entryRow} ei ole minkään vaakaosion lattia`);
              if (sl.travel < 10) bad.push(`${id} osio ${sl.i + 1}: nousua vain ${sl.travel} riviä`);
            }
          }
        }
        expect('kaista, suunta ja matka johdetaan ruudukosta ja osuvat siihen mitä siinä on',
          segIds.length > 0 && bad.length === 0,
          bad.length ? bad.slice(0, 3).join(' / ')
            : segIds.map((id) => {
              const def = getLevel(id);
              return `${id}: ${segmentSlices(def.rows, def.segments).slices
                .map((sl) => (sl.vertical ? `${sl.entryRow}→${sl.exitRow}` : `kaista ${sl.floorRow - 14}-${sl.floorRow}`))
                .join(', ')}`;
            }).join(' — '));
      }

      /*
       * PUNAINEN ENNEN VIHREÄÄ (DESIGN.md 7).
       *
       * Koekappale on toimitettu kenttä itse, rikottuna viidellä eri tavalla.
       * Kenttädatasta rikkominen on tässä oikea tapa eikä oikaisu: se todistaa
       * että sääntö laukeaa *sillä* geometrialla jota peli oikeasti sisältää,
       * eikä vain jollain käsin kirjoitetulla ruudukolla joka sattuu
       * laukaisemaan sen.
       */
      {
        const id = segIds[0];
        const def = id ? getLevel(id) : null;
        const bend = (mut) => def.rows.map((row, y) => mut(row, y) ?? row);
        const cases = [];
        if (def) {
          const { slices } = segmentSlices(def.rows, def.segments);
          const climbSeg = slices.find((sl) => sl.vertical);
          /* Yksi puola pois nousun keskeltä. */
          const rungRow = (() => {
            for (let y = climbSeg.exitRow + 3; y < climbSeg.entryRow - 3; y++) {
              if (def.rows[y].slice(climbSeg.from, climbSeg.to).includes('-')) return y;
            }
            return -1;
          })();
          cases.push({
            why: 'puuttuva puola',
            rows: bend((row, y) => (y === rungRow
              ? row.slice(0, climbSeg.from) + ' '.repeat(climbSeg.to - climbSeg.from) + row.slice(climbSeg.to)
              : null)),
          });
          /* Reikä nousun lattiassa. */
          cases.push({
            why: 'reikä nousun lattiassa',
            rows: bend((row, y) => (y >= def.rows.length - 2
              ? row.slice(0, climbSeg.from + 4) + '   ' + row.slice(climbSeg.from + 7)
              : null)),
          });
          /* Tikapuusarake: jalansija joka askelmalla samassa sarakkeessa. */
          cases.push({
            why: 'tikapuusarake',
            rows: bend((row, y) => ((y > climbSeg.exitRow && y < climbSeg.entryRow && (climbSeg.entryRow - y) % 3 === 0)
              ? row.slice(0, climbSeg.from + 2) + '--' + row.slice(climbSeg.from + 4)
              : null)),
          });
          /* Osiointi joka ei kata loppua. */
          cases.push({
            why: 'vajaa osiointi',
            rows: def.rows,
            segments: def.segments.slice(0, -1),
          });
          /* Tehostus pois ensimmäisestä osiosta. */
          cases.push({ why: 'ei tehostusta alussa', rows: bend((row) => row.replace('!', ' ')) });
        }
        const missed = cases.filter((c) => validateLevel(c.rows, segBudget,
          { segments: c.segments || def.segments }).length === 0).map((c) => c.why);
        const soundProblems = def ? validateLevel(def.rows, segBudget, { segments: def.segments }) : ['ei kenttää'];
        expect('osiosäännöt hyväksyvät toimitetun kentän ja hylkäävät jokaisen rikotun',
          !!def && soundProblems.length === 0 && cases.length === 5 && missed.length === 0,
          missed.length ? `läpi meni: ${missed.join(', ')}`
            : soundProblems.length ? `ehjä kenttä valitti: ${soundProblems.slice(0, 2).join(' / ')}`
              : `${cases.length} rikottua koekappaletta, kaikki hylättiin`);
      }

      /*
       * JA BOTTI PELAA SEN LÄPI VOIMATASOLLA 0.
       *
       * Sama kiipeilijä, sama moottori, viholliset pois (maasto on kysymys).
       * Käänteet lasketaan ajon aikana `scene.vertical`in vaihdoksina, koska
       * juuri se on se asia jota tämä kenttä on: kolme käännettä neljälle
       * osiolle, ja jokainen niistä on sivunvaihdon lyönti.
       */
      {
        const runs = [];
        for (const id of segIds) {
          const rows = getLevel(id).rows;
          reset({ type: null, level: 0 });
          let finished = null;
          game.finishLevel = (r) => { finished = r; };
          const s = new LevelScene(game, id);
          game.setScene(s);
          s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
          s.time = 9999;
          s.clockStopped = true;
          const bot = makeClimber(s, rows, segBudget);
          const input = mkInput();
          let axis = s.vertical;
          let turns = 0;
          let frames = 0;
          for (let f = 0; f < 9000 && !finished; f++) {
            frames = f;
            const want = bot.step();
            input.held = blank();
            input.pressed = blank();
            input.held.left = want.left;
            input.held.right = want.right;
            input.held.jump = want.jump;
            input.held.run = want.run;
            input.pressed.jump = want.press;
            s.update(input);
            if (s.vertical !== axis) { axis = s.vertical; turns++; }
            if (s.state === 'dead') break;
          }
          runs.push({
            id,
            cleared: !!(finished && finished.cleared),
            turns,
            frames,
            died: s.state === 'dead',
            at: `${Math.floor(s.player.cx / 16)},${Math.floor((s.player.y + s.player.h) / 16)}`,
          });
        }
        expect('kiipeilijä pelaa osioidun kentän läpi voimatasolla 0, ja akseli vaihtuu matkalla',
          runs.length > 0 && runs.every((r) => r.cleared && r.turns >= 3),
          runs.map((r) => `${r.id}: ${r.turns} käännettä, ${r.frames} framea, maali `
            + `${r.cleared ? 'saavutettu' : r.died ? `kuoli kohdassa ${r.at}` : `saavuttamatta, jäi kohtaan ${r.at}`}`)
            .join(' — ') || 'ei mitattavaa');
      }
    }

    /* ---------------------------- vihainen aurinko ---------------------- */
    /*
     * The sun is the one enemy that positions itself against the camera, which
     * makes it the one the letterbox can break: `viewH` is 160 in 2-1 and 208
     * in 2-2, so a sun that aims at the uncropped height aims at 48 px the
     * player never sees. Both levels are measured, because the same enemy in
     * the two framings is the only A/B this game has for the crop.
     *
     * What this caught: `skyY = Math.min(skyY, cam.y + 18)` is a ratchet. It
     * could only ever raise the sun, so the first descent left it above the
     * frame for the rest of the level — 0 of 390 hunting frames on screen in
     * 2-1, and clipped through the top edge on every bob in 2-2.
     */
    /* The wait between dives is the one random number in the sun, and a gate
     * that measures a retreat cannot afford to sample a different dive on every
     * run. Seeded for this block and put back at the end of it. */
    const realRandom = Math.random;
    let sunSeed = 20260809;
    Math.random = () => {
      sunSeed = (sunSeed * 1103515245 + 12345) & 0x7fffffff;
      return sunSeed / 0x7fffffff;
    };

    const sunRun = (id, place, frames = 420, walk = false) => {
      // Power 3, because the bot is standing under a thing that dives at it and
      // a level-0 death would end the sample after the first hit — this block
      // is measuring where the sun is, not how long the bot lives.
      reset({ type: 'leaf', level: 3 });
      const s = new LevelScene(game, id);
      const sun = s.entities.find((e) => e.constructor.name === 'AngrySun');
      const input = mkInput();
      const out = {
        id, sun, scene: s, hunting: 0, seen: 0, hover: 0, whole: 0, dives: 0,
        wind: 0, windAtDive: -1, quitAt: -1, gone: -1, quitY: 0, endY: 0, ran: 0,
        low: -Infinity, after: 0,
      };
      if (!sun) return out;
      place(s, sun);
      s.centerCamera();
      let prevY = sun.y;
      let prevPhase = sun.phase;
      for (let f = 0; f < frames; f++) {
        // A cleared level keeps updating its entities, and that is the point:
        // the retreat is meant to be watched while the flag animation plays.
        if (s.state === 'dead') break;
        /* Jumping on the spot is the harder case and the deliberate one: a jump
         * swings the vertical camera through its whole range and back, which is
         * exactly the pan the old `Math.min` could only follow in one
         * direction. Walking is for the runs that have to reach the flag. */
        input.held.right = walk;
        input.held.run = walk;
        input.pressed.jump = f % 41 === 0;
        input.held.jump = f % 41 < 14;
        s.update(input);
        if (f < 30) { prevY = sun.y; continue; }   // the drop and the camera settle
        const top = sun.y - s.cam.y;
        if (sun.quit) {
          if (out.quitAt < 0) { out.quitAt = f; out.quitY = sun.y; }
          if (out.gone < 0 && top + sun.h < 0) out.gone = f;
        } else {
          out.hunting++;
          if (top + sun.h > 0 && top < s.viewH) out.seen++;
          if (sun.phase === 'hover') {
            out.hover++;
            if (top >= 0 && top + sun.h <= s.viewH) out.whole++;
          }
        }
        if (sun.phase === 'dive' && prevPhase === 'hover') {
          out.dives++;
          if (out.quitAt >= 0) out.after++;
          out.windAtDive = out.wind;
          out.wind = 0;
        } else if (sun.windUp > 0) {
          out.wind++;
        }
        out.low = Math.max(out.low, sun.y + sun.h);
        out.endY = sun.y;
        out.ran = f;
        prevPhase = sun.phase;
        prevY = sun.y;
      }
      return out;
    };
    /* Walk it in under the sun: the level puts it five chunks in, and the spawn
     * row is the one band the ground route runs along. */
    const underSun = (s, sun) => {
      s.player.x = sun.x;
      s.player.y = s.spawn.y;
      s.player.vy = 0;
    };

    {
      const runs = ['2-1', '2-2'].map((id) => sunRun(id, underSun));
      expect('vihainen aurinko pysyy näkyvässä kaistassa myös laajakuvassa',
        runs.every((r) => r.hunting > 200 && r.seen === r.hunting && r.whole === r.hover),
        runs.map((r) => `${r.id} viewH ${r.scene.viewH}: ruudulla ${r.seen}/${r.hunting}, `
          + `kokonaan ${r.whole}/${r.hover}`).join(' | '));

      /* The dive is telegraphed. Both halves in the same beat (DESIGN.md §8),
       * and the warning is taken out of the wait rather than added to it: the
       * launch frame does not move, so the fight is no harder than it was. */
      expect('sukellusta edeltää puolen sekunnin ennakkovaroitus, eikä se siirrä lähtöä',
        runs.every((r) => r.dives >= 1 && r.windAtDive === 34)
        && runs.every((r) => r.low < r.scene.cam.y + r.scene.viewH + 40),
        runs.map((r) => `${r.id} ${r.dives} sukellusta, varoitus ${r.windAtDive} framea`).join(' | '));
    }

    /*
     * Most persistent enemies give up before the flag, and the sun is the game's
     * only one that follows you the whole way. It has to be *seen* leaving —
     * that is the reward for surviving it — so the retreat is a climb out of
     * frame and not a switch, and it is measured as one.
     */
    {
      const flag = sunRun('2-1', (s, sun) => {
        // Far enough out that it is genuinely hunting when the flag arrives.
        s.player.x = s.goal.x - 900;
        s.player.y = s.spawn.y;
        s.player.vy = 0;
        sun.x = s.player.x - 84;
      }, 700, true);
      const climb = flag.quitY - flag.endY;
      /* Nine tenths and not all of them: this run walks the level, and a dive
       * is a fixed arc that does **not** chase the camera. Descend a staircase
       * mid-dive and the tail of the arc is briefly above the frame — the
       * alternative is a dive that follows you down, which is a harder fight,
       * and the wind-up is a promise about where the thing is coming from. */
      expect('aurinko luovuttaa lipun näkyessä ja nousee näkyvästi pois',
        flag.hunting > 100 && flag.seen > flag.hunting * 0.9
        && flag.quitAt > 0 && flag.sun.quit === 'flag' && flag.after === 0
        // Out of the top of the frame, and by climbing there: a cut would be a
        // bug wearing the same end state, so the travel is measured too.
        && flag.gone > 0 && flag.gone - flag.quitAt < 120
        && flag.ran - flag.quitAt > 60 && climb > 40,
        `jahtasi ${flag.hunting} framea (${flag.seen} ruudulla), luovutti framella `
        + `${flag.quitAt}, poissa framella ${flag.gone}, nousi ${climb.toFixed(0)} px, `
        + `sukelluksia luovutuksen jälkeen ${flag.after}`);
    }

    /*
     * And it is the *sky's*. A tall level is sky / route / cave; following the
     * camera down a warp pipe would park an unkillable, unavoidable thing
     * inside a sealed room. No desert level has a pipe today — the tall ones
     * are worlds 1-4's secrets — so this is unreachable in the shipped game and
     * built anyway: containment that depends on nobody adding a pipe is a trap
     * for whoever adds one. 2-2 is tall, so it can be asked directly.
     */
    {
      reset();
      const s = new LevelScene(game, '2-2');
      const sun = s.entities.find((e) => e.constructor.name === 'AngrySun');
      const input = mkInput();
      const span = s.def.bands.rows * TILE;
      const cave = 2 * span;
      // Into the sealed tomb room under column 224, where the warp pipe lands,
      // with the sun overhead and awake — it wakes with the camera, and the
      // level puts it eleven chunks earlier.
      s.player.x = 230 * TILE;
      s.player.y = cave + 11 * TILE;
      s.player.vy = 0;
      sun.x = s.player.x - 84;
      sun.active = true;
      s.centerCamera();
      let deepest = -Infinity;
      for (let f = 0; f < 240; f++) s.update(input), deepest = Math.max(deepest, sun.y + sun.h);
      const left = sun.quit === 'band' && sun.y + sun.h <= span && deepest < cave;
      // …and it comes back when the player does.
      s.player.x = sun.x;
      s.player.y = s.spawn.y;
      s.player.vy = 0;
      s.centerCamera();
      let back = -1;
      for (let f = 0; f < 240; f++) {
        s.update(input);
        const top = sun.y - s.cam.y;
        if (back < 0 && !sun.quit && top >= 0 && top + sun.h <= s.viewH) back = f;
      }
      expect('aurinko ei seuraa maan alle vaan odottaa oman kaistansa yllä',
        left && back >= 0 && back < 120,
        `luovutus ${sun.quit || 'ei'}, alin ${Math.round(deepest)} vs luola ${cave}, `
        + `paluu framella ${back}`);
    }
    Math.random = realRandom;

    /* The lamp. It is an ambience like the heat and the frost, so it has to work
     * on a machine with no WebGL — and it must never be the reason a hazard is
     * invisible, which is the one thing this game does not do. */
    {
      reset();
      const night = new LevelScene(game, '2-N');
      game.setScene(night);
      const on = game.fx.ambience;
      game.toWorldMap();
      expect('2-N is lit by a lamp, and leaving the level puts it out',
        on === 'spotlight' && game.fx.ambience === null, `${on} -> ${game.fx.ambience}`);
    }

    const realGet = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function (type, opts) {
      if (String(type).startsWith('webgl')) return null;
      return realGet.call(this, type, opts);
    };
    try {
      reset();
      const s = new LevelScene(game, '2-N');
      const a = shot();
      s.draw(a.g);
      const fx = makeFX();
      fx.init(a.c);
      fx.source = a.c;
      fx.setPreset('hehku');
      fx.setAmbience('night', s.def);
      const focus = { ...PostFX.focus };       // the scene pushed it while drawing
      fx.setFocus(focus.x, focus.y);
      const before = data(a.c).slice();
      fx.apply(a.g);
      const after = data(a.c);

      const near = at(Math.round(focus.x), Math.round(focus.y) - 40);
      const far = at(focus.x > VIEW_W / 2 ? 4 : VIEW_W - 5, 40);
      const keptNear = luma(after, near) / Math.max(1, luma(before, near));
      const keptFar = luma(after, far) / Math.max(1, luma(before, far));
      expect('without WebGL the lamp still lights the player and darkens the distance',
        fx.mode === '2d' && keptNear > 0.95 && keptFar < 0.45,
        `mode ${fx.mode}, lähellä ${keptNear.toFixed(2)}, kaukana ${keptFar.toFixed(2)}`);

      /* Darkness may hide the route and the rewards. It may not hide a spike:
       * a hazard you can only learn by dying is the one thing this game is not
       * supposed to have. Measured at the darkest a hazard can legitimately get
       * — the far side of the view, with the CRT vignette dimming it again. */
      const spikes = [];
      for (let ty = 0; ty < s.h; ty++) {
        for (let tx = 0; tx < s.w; tx++) {
          if (s.rawTileAt(tx, ty) === T.SPIKE) spikes.push({ tx, ty });
        }
      }
      let worst = null;
      for (const sp of spikes) {
        const s2 = new LevelScene(game, '2-N');
        s2.player.y = sp.ty * TILE;
        s2.centerCamera();
        const sx = 300;
        s2.cam.x = sp.tx * TILE - sx;
        if (s2.cam.x < 0 || s2.cam.x > s2.widthPx - VIEW_W) continue;
        const sy = sp.ty * TILE - Math.round(s2.cam.y);
        if (sy < 0 || sy + TILE > VIEW_H) continue;
        const b = shot();
        s2.draw(b.g);
        // The dead zone and the look-ahead keep the player between screen x 126
        // and 194, so 194 px is as far as a hazard can get from the light.
        fx.source = b.c;
        fx.setPreset('crt');
        fx.setAmbience('night', s2.def);
        fx.setFocus(sx + TILE / 2 - 194, sy + 8);
        fx.apply(b.g);
        const d2 = data(b.c);
        let tip = 0;
        let air = 0;
        let n = 0;
        for (let y = sy + 6; y < sy + TILE; y++) {
          for (let x = sx; x < sx + TILE; x++) tip = Math.max(tip, luma(d2, at(x, y)));
        }
        for (let y = sy - 10; y < sy + 5; y++) {
          for (let x = sx; x < sx + TILE; x++) { air += luma(d2, at(x, y)); n++; }
        }
        const gap = tip - air / Math.max(1, n);
        if (!worst || gap < worst.gap) worst = { gap, tx: sp.tx, ty: sp.ty };
      }
      expect('a lethal tile outside the beam is still readable',
        worst && worst.gap >= 20,
        worst ? `piikit erottuvat ${worst.gap.toFixed(1)} luminanssia taustasta`
          : 'no spike tile could be placed');
      fx.setPreset('hehku');
    } finally {
      HTMLCanvasElement.prototype.getContext = realGet;
    }

    /* A GLSL error is silent — `_initGL` returns false and the game falls back
     * to Canvas 2D forever. So the shader is compiled and run on purpose. */
    {
      const probe = document.createElement('canvas').getContext('webgl2')
        || document.createElement('canvas').getContext('webgl');
      const gfx = makeFX();
      const a = shot();
      gfx.init(a.c);
      gfx.setAmbience('night', { spotlight: true });
      gfx.setFocus(100, 100);
      let presented = false;
      try { presented = gfx.present(); } catch { presented = false; }
      expect('the spotlight shader compiles and runs where there is a GPU',
        !probe || (gfx.mode === 'webgl' && presented
          && gfx._uniforms.dark && gfx._uniforms.focus),
        probe ? `mode ${gfx.mode}, present ${presented}` : 'ei WebGL:ää — ohitettu');
      if (gfx.displayCanvas) gfx.displayCanvas.remove();
    }

    game.fx.setAmbience(null);
  }

  /* -------------------------------- audio ------------------------------ */
  const { Sfx, Music, Ambience: Bed, audioTap } = await import('/src/core/audio.js');

  /*
   * ÄÄNIMITTAUKSEN KAKSI APURIA, ja miksi ne ovat olemassa.
   *
   * Neljä puhetestiä kaatui satunnaisesti noin joka toisessa ajossa, ja vikaa
   * etsittiin **kolme kertaa testin omista luvuista**: ensin kiinteä 900 ms:n
   * odotus vaihdettiin hiljaisuuden odottamiseen, sitten yksi ikkuna kahdeksi
   * peräkkäiseksi. Kumpikin korjasi oikean asian ja kumpikaan ei auttanut,
   * koska vika ei ollut siinä mitä mitattiin vaan siinä **mittasiko kone
   * ollenkaan**.
   *
   * Mitattu, ja tämä on se rivi joka päätti asian:
   *
   *     hiljeni 465 ms, äänikello 0.00 s / seinäkello 0.47 s, ikkunat 0.00 0.00
   *
   * Eli seinäkello eteni puoli sekuntia ja **äänikello ei lainkaan**.
   * `ctx.state` sanoi koko ajan `running`. Kun renderöijä seisoo:
   *
   *   1. `getFloatTimeDomainData` palauttaa saman vanhan puskurin uudestaan ja
   *      uudestaan — siitä ne toistuvat *täsmälleen* yhtä suuret lukemat
   *      (`s 24.82 š 24.82 f 24.82`), joita elävä ääni ei voi tuottaa;
   *   2. kaikki mitä sillä välillä soitetaan ajastetaan samaan jäätyneeseen
   *      hetkeen, ja kun renderöijä herää, ne soivat **yhtä aikaa** — siitä ne
   *      mahdottomat pohjakohinat 15,3 · 25,1 · 46,0, jotka eivät ole yhden
   *      äänen häntä vaan sata ääntä samassa näytteessä;
   *   3. juuri soitettu ääni lukee 0,000, koska sitä ei ole vielä renderöity.
   *
   * Sama yksi syy tuottaa siis molemmat oireet — sekä "väylä ei rauhoitu" että
   * "puhetta ei kuulu" — ja siksi kolme neljästä kaatuvasta testistä oli koko
   * ajan oire eikä oma vikansa.
   *
   * **Peli ei vuoda ääntä.** Tämä on headless-Chromiumin renderöijä, ei
   * `audio.js`: oikealla koneella on oikea äänilaite joka pyytää näytteitä 48
   * kertaa sekunnissa riippumatta siitä mitä sivu tekee. Se on tärkeä ero,
   * koska toinen johtopäätös olisi ollut paljon isompi.
   *
   * Vastaus on kaksiosainen, eikä kumpikaan osa löysää yhtään kynnystä:
   *
   *   - `keepRendering()` panee väylälle **äänettömän** oskillaattorin
   *     mittausten ajaksi. Elävä lähde on se mikä pitää renderöijän töissä, ja
   *     nollavahvistus tarkoittaa ettei se lisää mittaukseen mitään.
   *   - `metered()` vertaa äänikelloa seinäkelloon. Jos kone ei renderöinyt,
   *     rivi sanoo **"ei mitattu"** samalla tavalla kuin se sanoo sen
   *     jäähtyneelle äänikontekstille — se ei väitä mitään lukua joka ei ole
   *     mittaus. Ja jotta portti ei voi kadota huomaamatta, alempana on
   *     tarkistus joka kaatuu jos *yksikään* äänimittaus ei toteutunut.
   */
  let audioSkipped = 0;
  let audioMeasured = 0;
  /**
   * Mittausikkuna **äänikellossa**, ei seinäkellossa.
   *
   * Tämä on se toinen puolisko, ja mitattuna se on tärkeämpi kuin oskillaattori:
   * vihreässäkin ajossa renderöijä jäi jälkeen — *äänikello 2,65 s / seinäkello
   * 6,14 s*, eli 43 % nopeudella — ja 420 ms:n seinäkelloikkuna oli silloin
   * 180 ms ääntä. Puhuttu rivi on 400 ms pitkä, joten portti mittasi puolikkaan
   * sanan ja vertasi sitä kokonaisen sanan kynnykseen.
   *
   * Ikkuna odottaa nyt sen verran **soitettua** ääntä kuin siltä pyydettiin.
   * Katto on seinäkellossa ja väljä (kuusinkertainen): jos renderöijä on
   * kokonaan seisonut, ikkuna ei koskaan täyty, ja silloin `stalled()` kertoo
   * sen eikä lukua julisteta mittaukseksi.
   */
  const meterFor = (tap, an) => {
    const buf = new Float32Array(an.fftSize);
    /** Kuinka pitkän pätkän ääntä analysaattori muistaa kerralla. */
    const windowSec = an.fftSize / tap.ctx.sampleRate;
    let stalled = false;
    const peakFor = async (ms) => {
      let peak = 0;
      const c0 = tap.ctx.currentTime;
      const w0 = performance.now();
      const cap = ms * 6 + 500;
      let last = c0;
      const sample = () => {
        an.getFloatTimeDomainData(buf);
        for (let i = 0; i < buf.length; i++) peak = Math.max(peak, Math.abs(buf[i]));
        const now = tap.ctx.currentTime;
        if (now - last > windowSec) stalled = true;
        last = now;
      };
      while ((tap.ctx.currentTime - c0) * 1000 < ms) {
        sample();
        if (performance.now() - w0 > cap) { stalled = true; break; }
        await new Promise((r) => setTimeout(r, 4));
      }
      /*
       * Vielä yksi näyte silmukan **jälkeen**, ja se on korjaus eikä
       * varmuuden vuoksi.
       *
       * Renderöijä ei ainoastaan seiso — se **ottaa kiinni ryöppyinä**:
       * mitattu `äänikello 12.18 s / seinäkello 3.99 s`, eli neljässä
       * sekunnissa renderöitiin kaksitoista sekuntia ääntä. Jos ryöppy osuu
       * viimeisen näytteen ja poistumisehdon väliin, koko mitattava ääni
       * renderöityy sen jälkeen kun sitä viimeksi katsottiin — mitattu
       * `s 0.00 š 0.00 f 0.00` kolmelta peräkkäiseltä äänteeltä kun loput
       * samasta silmukasta olivat normaaleja.
       *
       * Analysaattori muistaa vain viimeiset `windowSec` sekuntia, joten
       * ryöpyn yli hypätty ääni ei ole hiljaisuutta vaan **ohi mennyttä**.
       * Siksi jokainen näyte tarkistaa myös sen, mahtuiko edellisen ja tämän
       * väliin enemmän ääntä kuin ikkunaan mahtuu; jos mahtui, tämä ei ole
       * mittaus.
       */
      sample();
      return peak;
    };
    /**
     * Odota väylän rauhoittumista, ja odota se **äänikellossa**.
     *
     * Tämä oli se viimeinen reikä: hiljaisuutta odotettiin seinäkellolla, ja
     * kun renderöijä seisoi, silmukka luovutti kuudessa sekunnissa ehtimättä
     * kuunnella kuin *kaksi kymmenesosaa sekuntia ääntä* — mitattu
     * `äänikello 0.20 s / seinäkello 6.88 s`, ja kasautuneen ryöpyn jäänne
     * 7,90 luettiin pohjakohinaksi. Nyt budjetti on soitettua ääntä, ja
     * seinäkellossa on vain väljä varmistus jottei ajo voi jäädä roikkumaan;
     * jos siihen mennään, luku ei ole mittaus vaan `stalled`.
     */
    const settle = async (seconds = 4, quiet = 0.02) => {
      let calm = 0;
      let level = 1;
      const c0 = tap.ctx.currentTime;
      const w0 = performance.now();
      while (calm < 2 && tap.ctx.currentTime - c0 < seconds) {
        level = await peakFor(200);
        calm = level > quiet ? 0 : calm + 1;
        if (performance.now() - w0 > seconds * 6000 + 2000) { stalled = true; break; }
      }
      return level;
    };
    /* Nollaus ennen sitä ikkunaa jonka luku väitetään, ja se on tarkoituksella
     * mahdollista: mitattu, että renderöijä laahaa nimenomaan lohkon alussa —
     * *ikkunat 302.78 302.78 12.30 3.60 1.55 0.11 0.00* — eli juuri silloin kun
     * odotetaan väylän rauhoittumista. Jos yksikin hidas odotusikkuna
     * mitätöisi koko lohkon, portti ohittaisi mittauksen joka onnistui. */
    return { peakFor, settle, stalled: () => stalled, clear: () => { stalled = false; } };
  };
  /**
   * PELI PARKKIIN ÄÄNIMITTAUKSEN AJAKSI, ja se on näiden porttien korjaus.
   *
   * Mitattu, ja molemmat luvut ovat tässä koska ne ovat koko todiste.
   *
   *   1. **Väylällä oli 24,25 ennen kuin lohko soitti mitään**, ja pedin tila
   *      oli `wind`. Tuulipeti on jatkuvaa kohinaa, ja juuri sen muotoinen oli
   *      kaatunut ajo: *ikkunat … 5.62 5.62 5.62*, kolme peräkkäistä
   *      täsmälleen yhtä suurta lukemaa. Vaimeneva häntä ei tee sitä. Peti
   *      herää joka kerta kun elossa oleva näyttämö kutsuu `hold()`ia, eli
   *      mittaus riippui siitä mikä näyttämö sattui olemaan pystyssä.
   *   2. Pelkkä `game.toTitle()` ei riitä, ja sekin on mitattu: parkkeerattuna
   *      väylä oli puhdas (*ennen 0.00*) — ja sitten **houkutusdemo lähti
   *      kesken odotuksen** (*pitäjät TitleScene/… DemoScene/m:level/…*,
   *      ikkunat 282.65 viisi kertaa peräkkäin, 19,4 sekuntia). Nimikkösivulle
   *      palaaminen *ostaa* kaksikymmentä sekuntia; se ei takaa mitään, ja
   *      hitaalla renderöijällä lohko kestää kauemmin.
   *
   * Siksi demo ei ole ajastettu vaan **irrotettu**: `startDemo` on mittauksen
   * ajan tyhjä, ja se pannaan takaisin lopuksi. Kynnyksiin ja odotusaikoihin ei
   * kosketa — kumpaakin on jo kerran yritetty, ks. alempana.
   *
   * @param {boolean} restoreScene palautetaanko parkkia edeltänyt näyttämö.
   */
  const park = (restoreScene = false) => {
    const wasScene = game.scene;
    const ownDemo = Object.prototype.hasOwnProperty.call(game, 'startDemo');
    const wasDemo = game.startDemo;
    game.startDemo = () => {};
    game.toTitle();
    Music.stop();
    Bed.stop();
    return () => {
      if (ownDemo) game.startDemo = wasDemo;
      else delete game.startDemo;
      if (restoreScene && wasScene) game.scene = wasScene;
    };
  };
  const keepRendering = (tap) => {
    if (!tap) return () => {};
    const osc = tap.ctx.createOscillator();
    const silent = tap.ctx.createGain();
    silent.gain.value = 0;
    osc.connect(silent).connect(tap.bus);
    osc.start();
    return () => {
      try { osc.stop(); } catch { /* jo pysäytetty */ }
      osc.disconnect();
      silent.disconnect();
    };
  };
  /**
   * Toteutuiko mittaus: konteksti käy **ja** äänikello eteni sen aikana.
   *
   * Puolet seinäkellosta on raja eikä maku: renderöijä joka on hereillä pysyy
   * mitatusti sadasosan päässä seinäkellosta (12 ikkunaa, suurin ero 6 ms), ja
   * seissyt renderöijä jää nollaan. Väliä ei ole, joten raja saa olla väljä.
   */
  const metered = (tap, stalled) => {
    /* Kone jolla ei ole ääntä lainkaan ei ole ohitus vaan eri kone, eikä sitä
     * lasketa kumpaankaan lukuun: alempi tarkistus kysyy "mitattiinko mitään
     * niistä joista olisi voinut mitata", eikä sen pidä kaatua siitä että
     * ajoympäristössä ei ole äänilaitetta. */
    if (!tap || tap.ctx.state !== 'running') return false;
    if (stalled) audioSkipped++;
    else audioMeasured++;
    return !stalled;
  };

  /* The vocals are synthesised through two narrow bandpass filters, so their
   * `gain` argument is applied to whatever survives the filters — it never
   * meant what it said. Measured, a nominal 0.44 came out at a third the
   * loudness of a coin, which is why they were reported as inaudible three
   * times. This asserts the measurement, because the constant cannot. */
  {
    const tap = audioTap();
    let voice = 0;
    let floorNoise = 0;
    let note = '';
    let stalled = false;
    const stopWake = keepRendering(tap);
    let unpark = null;
    if (tap && tap.ctx.state === 'running') {
      /*
       * PELI PARKKIIN MITTAUKSEN AJAKSI, ja tämä on se korjaus jota kolme
       * edellistä yritystä etsi testin omista luvuista.
       *
       * Mitattu, ja se on tässä koska se on koko todiste. Diagnostiikkarivi
       * juuri ennen kuin tämä lohko soitti mitään:
       *
       *     ennen 24.25 @ WorldMapScene/m:-/a:wind
       *
       * Kaksi asiaa kerralla. **Väylällä oli jo 24,25** — eli lohkon oma
       * neljän äänen "punainen" ei ollut se mitä odotus kuunteli, vaan koko
       * suiten jäänne. Ja **`Ambience.current` oli `wind`**: tuulipeti on
       * jatkuvaa kohinaa eikä hännällinen ääni, ja se on tasan se muoto jonka
       * kaatunut ajo näytti — *ikkunat … 5.62 5.62 5.62*, kolme peräkkäistä
       * täsmälleen yhtä suurta lukemaa. Vaimeneva häntä ei tee sitä; tasainen
       * lähde tekee. Peti nousee henkiin joka kerta kun jokin näyttämö kutsuu
       * `hold()`ia, eli se mitä tämä portti mittasi riippui siitä mikä
       * näyttämö sattui olemaan elossa edellisen lohkon jäljiltä.
       *
       * Siksi peli parkkeerataan: nimikkönäyttämö (joka samalla virittää uudelleen
       * sen kahdenkymmenen sekunnin houkutusajastimen, ks. konsonanttilohko),
       * musiikki kiinni ja peti kiinni. Kynnystä ei löysätty eikä odotusta
       * pidennetty — kumpikin oli jo kerran yritetty, ks. alla. Näyttämö
       * palautetaan mittauksen jälkeen.
       */
      unpark = park(true);
      /* Punainen ennen vihreää, ja satunnaiselle vialle se tarkoittaa että
       * vika pitää **tuottaa tahallaan**. Kaatuneissa ajoissa tausta oli 0,379
       * … 3,029 — se ei ole yhden äänen häntä vaan muutama päällekkäinen ääni,
       * eli suite itse jätti väylän soimaan. Neljä ääntä yhtä aikaa tekee
       * saman joka ajolla ja pysyy siinä suuruusluokassa jonka oikeat
       * kaatumiset näyttivät; kymmenen ääntä olisi tuottanut leikkaavan
       * 19,450:n eli vian jota suite ei koskaan tuota itse. */
      const an = tap.ctx.createAnalyser();
      /* 743 ms yhtäjaksoista aaltoa eikä 46 ms, ja syy on renderöijän ryöppy:
       * lyhyt ikkuna ei muista kuin murusen siitä mitä yhden ryöpyn aikana
       * soitettiin, ja ohi mennyt ääni luetaan nollaksi. Sama luku kuin
       * konsonanttilohkolla. */
      an.fftSize = 32768;
      tap.bus.connect(an);
      const meter = meterFor(tap, an);
      const peakFor = meter.peakFor;
      /*
       * Väylän taso **ennen** kuin tämä lohko soittaa mitään, ja se jää riville
       * pysyvästi. Juuri tämä luku paljasti vian: parkkeeraamattomana se oli
       * 24,25, eli lohkon oma neljän äänen punainen oli murto-osa siitä mitä
       * odotus todella kuunteli. Jos se joskus taas kasvaa, rivi kertoo sen
       * heti eikä vasta silloin kun odotus loppuu kesken. */
      const before = await peakFor(200);
      const beforeWho = `${game.scene ? game.scene.constructor.name : '-'}`
        + `/m:${Music.current || '-'}/a:${Bed.current || '-'}${Bed.live ? '+' : ''}`;
      for (const s of ['sprout', 'bigfart', 'burst', 'flight']) Sfx.play(s);
      meter.clear();
      /* Odota hiljaisuutta, älä kelloa.
       *
       * Tässä oli kiinteä 900 ms odotus ja perustelu "suite on soittanut ääniä
       * minuutin ajan, annetaan väylän rauhoittua". Perustelu oli oikea, luku
       * ei: 900 ms on arvaus siitä miten pitkä häntä edellisellä äänellä
       * sattuu olemaan, ja arvaus meni pieleen noin joka toinen ajo. Mitattuna
       * tausta oli milloin 0,000 ja milloin 3,029 — eli testi ei mitannut
       * pohjakohinaa vaan sitä ehtiikö edellinen ääni loppua. Portti joka
       * kaatuu satunnaisesti ei ole portti vaan kolikonheitto, ja se on
       * pahempi kuin puuttuva testi: se opettaa ohittamaan punaisen.
       *
       * Nyt väylää kuunnellaan kunnes se on oikeasti hiljaa, ja **samalla
       * ikkunalla jolla lopputulos mitataan**. Ensimmäinen yritys tarkkaili
       * hiljaisuutta 60 ms:n ikkunalla ja mittasi sitten 200 ms:llä, mikä
       * kaatui omaan mittaansa: ääni jossa on tauko näyttää 60 ms:n ikkunassa
       * hiljaiselta ja jatkuu heti perään. Mitattu tulos oli "hiljeni 182 ms,
       * tausta 19,450" — eli portti julisti hiljaisuuden keskellä ryminää.
       * Yksi ikkuna, se jonka väite koskee, ei voi valehdella noin.
       *
       * **Kaksi peräkkäistä hiljaista ikkunaa, ei yhtä**, ja siihen on
       * konkreettinen syy: `sprout` on ajastettu ääni jonka sisällä on tauko
       * (kopsahdus, hiljaisuus, sitten nouseva kahina). Yhden ikkunan sääntö
       * osui siihen taukoon — tausta 0,000 ja heti perään ääni 4,250, eli
       * mittaus luuli mittaavansa yhtä puhuttua riviä ja mittasi kahinaa sen
       * päällä. Neljäsataa millisekuntia yhtäjaksoista hiljaisuutta on
       * pidempi kuin yksikään pelin äänen sisäinen tauko.
       *
       * Jos väylä ei rauhoitu kuudessa sekunnissa **soitettua ääntä**, sekin on
       * tulos eikä oletus: silmukka päättyy, `tausta` jää suureksi ja rivi
       * kaatuu kertoen syyn. Budjetti on äänikellossa, ks. `meterFor`. */
      const QUIET = 0.02;
      const t0 = performance.now();
      const ct0 = tap.ctx.currentTime;
      let calm = 0;
      /* Kun väylä ei rauhoitu, se ei ole mittausvirhe vaan *joku soittaa*. Siksi
       * tähän kerätään ikkunoiden sarja ja se näyttämö joka oli elossa silloin
       * kun luovutettiin: kolme edellistä korjausyritystä etsi vikaa testin
       * omista luvuista, ja jokainen niistä olisi loppunut minuutissa jos rivi
       * olisi kertonut kuka ääntä piti. */
      const windows = [];
      /* Kuka ääntä pitää, ikkuna ikkunalta: näyttämö, raita ja peti. Peti on
       * niistä se joka kaatoi tämän portin — jatkuva kohina ei vaimene, joten
       * `Ambience.current` kuuluu riville siinä missä ikkunoiden sarjakin. */
      const holders = [];
      while (calm < 2 && tap.ctx.currentTime - ct0 < 6) {
        floorNoise = await peakFor(200);
        windows.push(floorNoise.toFixed(2));
        holders.push(`${game.scene ? game.scene.constructor.name : '-'}`
          + `/m:${Music.current || '-'}/a:${Bed.current || '-'}${Bed.live ? '+' : ''}`);
        calm = floorNoise > QUIET ? 0 : calm + 1;
        if (performance.now() - t0 > 40000) break;      // renderöijä seisoo, ks. alla
      }
      /* Rauhoittumaton väylä on tulos vain jos kone ehti kuunnella sen: jos
       * äänikello ei edennyt, luku on kasautuneen ryöpyn jäänne eikä
       * pohjakohina. Mitattu kaatuneesta ajosta: `äänikello 0.20 s /
       * seinäkello 6.88 s`, tausta 7,90. */
      const heard = calm >= 2 || tap.ctx.currentTime - ct0 >= 5.5;
      const waited = Math.round(performance.now() - t0);
      const ctWaited = tap.ctx.currentTime - ct0;
      /* Näyttämö ja ikkunoiden sarja mukaan riville: jos väylä ei rauhoitu,
       * kysymys on kuka ääntä pitää, ja kolme edellistä korjausyritystä olisi
       * loppunut minuutissa jos rivi olisi kertonut sen. */
      const live = game.scene ? game.scene.constructor.name : 'ei mitään';
      meter.clear();
      Sfx.play('yeah');
      voice = await peakFor(420);
      an.disconnect();
      unpark();                            // parkki purettu, ks. `park`
      stalled = meter.stalled() || !heard;
      note = ` (hiljeni ${waited} ms, näyttämö ${live}`
        + `, äänikello ${ctWaited.toFixed(2)} s / seinäkello ${(waited / 1000).toFixed(2)} s`
        + `, ikkunat ${windows.slice(-8).join(' ')}`
        + `, ennen ${before.toFixed(2)} @ ${beforeWho}`
        + `, pitäjät ${[...new Set(holders)].join(' ')})`;
    }
    stopWake();
    const measured = metered(tap, stalled);
    expect('a spoken line is loud enough to hear',
      !measured || (floorNoise < 0.1 && voice > 0.25),
      measured ? `ääni ${voice.toFixed(3)}, tausta ${floorNoise.toFixed(3)}${note}`
        : `ei mitattu${note}`);
  }

  /*
   * Consonants.
   *
   * The vocals used to be five vowels and nothing else, so every line was one
   * glide with a shape on it. Three things have to be true of the consonants and
   * not one of them can be read off the source:
   *
   *   - a plosive's silence has to be *in the waveform*. Without it the ear
   *     hears a tap, and a burst scheduled 35 ms after a vowel that is still
   *     ringing is exactly that.
   *   - a fricative is broadband noise and a vowel is two narrow bandpass peaks.
   *     They do not arrive at the same level for the same nominal gain, so the
   *     numbers are measured against the same references as everything else on
   *     this bus (coin 0.32, death 0.57).
   *   - the vowel-only words the game already speaks ('iea', 'ou', 'eo', 'uo')
   *     have to come out of the segmented path exactly as they did out of the
   *     single-glide one.
   */
  {
    const audio = await import('/src/core/audio.js');
    const { vox, voxPlan, Ambience } = audio;
    const tap = audioTap();
    const measured = tap && tap.ctx.state === 'running';
    const check = (name, fn) => {
      try {
        const [ok, detail] = fn();
        expect(name, ok, detail);
      } catch (err) {
        expect(name, false, `heitti: ${err.message}`);
      }
    };
    const near = (a, b, tol) => Math.abs(a - b) <= tol;
    const kinds = (plan) => plan.map((s) => s.kind).join(' ');

    check('a vowel-only word is still one unbroken glide', () => {
      const p = voxPlan('iea', 0.32);
      const t = p[0] && p[0].targets;
      return [
        p.length === 1 && p[0].kind === 'run' && p[0].at === 0
          && near(p[0].dur, 0.32, 1e-9) && t.length === 3
          && near(t[0].at, 0, 1e-9) && near(t[1].at, 0.136, 1e-6)
          && near(t[2].at, 0.272, 1e-6),
        `${kinds(p)}, kohdat ${t ? t.map((x) => x.at.toFixed(3)).join('/') : '-'}`,
      ];
    });

    check('a plosive is silence before it is a burst', () => {
      const bad = [];
      for (const c of ['p', 't', 'k']) {
        const p = voxPlan(`a${c}a`, 0.4);
        const [, gap, burst] = p;
        if (kinds(p) !== 'run silence burst run') { bad.push(`${c}: ${kinds(p)}`); continue; }
        if (gap.dur < 0.03) bad.push(`${c}: hiljaisuus vain ${(gap.dur * 1000).toFixed(0)} ms`);
        if (!near(burst.at, gap.at + gap.dur, 1e-9)) bad.push(`${c}: purske ei seuraa hiljaisuutta`);
      }
      const g = voxPlan('ata', 0.4)[1];
      return [bad.length === 0, bad.join(', ') || `esim. t: ${(g.dur * 1000).toFixed(0)} ms kiinni`];
    });

    /* Unknown letters used to become an 'a'. With five-letter vowel words that
     * was harmless; with real words a stray letter turning into an extra "ah"
     * adds a syllable nobody wrote. They are dropped now — and a word left with
     * nothing at all still falls back to an 'a', because a sound effect that
     * silently does nothing is the failure that never gets reported. */
    check('an unknown letter is dropped instead of becoming an "a"', () => {
      const same = JSON.stringify(voxPlan('jee', 0.3)) === JSON.stringify(voxPlan('ee', 0.3));
      const empty = voxPlan('jvlr', 0.3);
      const fallback = empty.length === 1 && empty[0].targets.length === 1
        && empty[0].targets[0].f[0] === 730;
      return [same && fallback, `jee=ee ${same}, tuntematon sana -> ${kinds(empty)}`];
    });

    if (measured) {
      /*
       * The attract demo plays the game to nobody after twenty seconds on the
       * title screen, and it fires jumps and stomps into the very bus these
       * checks read. Going back to the title re-arms that timer, which buys the
       * twenty seconds this block needs — the readings below were varying by a
       * factor of two before, and it was the demo landing a coin in the window.
       */
      const unpark = park();                 // näyttämö, raita, peti ja demo
      const stopWake = keepRendering(tap);
      const an = tap.ctx.createAnalyser();
      an.fftSize = 32768;                    // 743 ms of contiguous waveform at 44.1k
      tap.bus.connect(an);
      const wave = new Float32Array(an.fftSize);
      const rate = tap.ctx.sampleRate;
      const meter = meterFor(tap, an);
      const peakFor = meter.peakFor;
      /* Tauko ei ole kello vaan ehto: odota kunnes väylä on oikeasti hiljaa,
       * ja jos se ei rauhoitu, tämä ei ollut mittaus. Seinäkellon 300 ms oli
       * arvaus edellisen sanan hännästä, ja ryöppyävällä renderöijällä myös
       * kasautunut jäänne ehti sen sisään — mitattu `s 7.582`. */
      let noisy = false;
      const quiet = async () => {
        const floor = await meter.settle(2);
        if (floor > 0.02) noisy = true;
      };
      const say = async (word, gain = 0.44, dur = 0.34, ms = 420) => {
        await quiet();
        vox({ word, dur, gain });
        return peakFor(ms);
      };

      /* Jokainen näistä kolmesta on mittaus, ja mittaus on tulos vasta jos kone
       * renderöi sen ajan. Ks. `metered` ylempänä: kolme näistä neljästä
       * puhetestistä oli oire eikä oma vikansa, ja tämä on se rivi jolla ero
       * tehdään. */
      /* Kolme tarkistusta, yksi mittaus: `levels` kerätään ensimmäisessä ja
       * luetaan kahdessa seuraavassa. Siksi ohitus periytyy — jos numeroita ei
       * mitattu, niistä johdettu väite ei ole sen mitatumpi. Mitattu ilman
       * tätä: `s 0.000` kaatoi frikatiivirivin samassa ajossa jossa sen oma
       * lähde sanoi jo "ei mitattu". */
      let inconclusive = false;
      const checkA = async (name, fn) => {
        try {
          meter.clear();
          noisy = false;
          const [ok, detail] = await fn();
          const why = meter.stalled() ? 'äänikello seisoi'
            : noisy ? `väylä ei rauhoittunut, pitäjä ${game.scene ? game.scene.constructor.name : '-'}`
              + `/m:${Music.current || '-'}/a:${Bed.current || '-'}${Bed.live ? '+' : ''}`
              : 'edellinen mittaus jäi kesken';
          const real = metered(tap, meter.stalled() || noisy) && !inconclusive;
          if (!real) inconclusive = true;
          expect(name, !real || ok, real ? detail : `ei mitattu (${why}): ${detail}`);
        } catch (err) {
          expect(name, false, `heitti: ${err.message}`);
        }
      };

      /* Every consonant on its own. A fricative or a burst that never made it
       * out of the graph would still leave the word around it sounding fine. */
      const levels = {};
      await checkA('every consonant makes a sound of its own', async () => {
        for (const c of ['s', 'š', 'f', 'h', 'p', 't', 'k', 'm', 'n', 'a']) {
          levels[c] = await say(c);
        }
        const mute = Object.entries(levels).filter(([, v]) => v < 0.05).map(([c]) => c);
        return [mute.length === 0,
          Object.entries(levels).map(([c, v]) => `${c} ${v.toFixed(2)}`).join(' ')];
      });

      /* A fricative is noise where a vowel is two resonances: it will not land
       * at the same level for the same nominal gain, and both numbers only mean
       * something next to the coin and the death sound on this same bus. */
      await checkA('a fricative is audible against the same reference as a vowel', async () => [
        levels.s > 0.16 && levels.s < levels.a,
        `s ${levels.s.toFixed(3)}, vokaali ${levels.a.toFixed(3)}, `
        + `h ${levels.h.toFixed(3)}, t-purske ${levels.t.toFixed(3)} (kolikko 0.32)`,
      ]);

      /* And the silence, in the recorded waveform rather than in the schedule.
       * `ata` is a vowel, a closure and a burst: if the closure is not really
       * there the envelope never comes down between the two vowels. */
      await checkA('a plosive keeps its silence in the waveform', async () => {
        await quiet();
        await peakFor(200);
        vox({ word: 'ata', dur: 0.42, gain: 0.44 });
        /* 560 ms **soitettua** ääntä ennen kuin puskuri luetaan: sana on 420 ms
         * pitkä, ja seinäkellossa odotettuna se olisi puolikas sana silloin kun
         * renderöijä laahaa. Juuri se teki tästä testistä oireen: se luki
         * aaltomuodon josta puolet ei ollut vielä olemassa. */
        await peakFor(560);
        an.getFloatTimeDomainData(wave);
        const block = 64;                    // 1.45 ms per step
        const env = [];
        for (let i = 0; i + block <= wave.length; i += block) {
          let m = 0;
          for (let j = i; j < i + block; j++) m = Math.max(m, Math.abs(wave[j]));
          env.push(m);
        }
        const top = Math.max(...env);
        const start = env.findIndex((v) => v > top * 0.25);
        /*
         * The longest quiet stretch inside the word that is answered by
         * something loud. "Answered" is looked for over the 12 ms after the
         * silence rather than in the first block out of it, because a burst
         * starts from nothing and its own attack would end the count early.
         *
         * Twelve and not forty: with a wider window this check passed a build
         * whose closures had been deleted, because a vowel fading in over 30 ms
         * leaves a quiet stretch of its own. The window is now shorter than any
         * onset that is not a transient.
         */
        const reply = Math.round((0.012 * rate) / block);
        let gap = 0;
        let run = 0;
        let after = 0;
        for (let i = Math.max(0, start); i < env.length; i++) {
          if (env[i] < top * 0.06) { run++; continue; }
          if (run > gap) {
            let hi = 0;
            for (let j = i; j < Math.min(env.length, i + reply); j++) hi = Math.max(hi, env[j]);
            if (hi > top * 0.2) { gap = run; after = hi; }
          }
          run = 0;
        }
        const ms = (gap * block * 1000) / rate;
        return [top > 0.2 && ms >= 20 && after > top * 0.2,
          `kiinni ${ms.toFixed(0)} ms, huippu ${top.toFixed(2)}, `
          + `purskeen jälkeen ${after.toFixed(2)}`];
      });
      an.disconnect();
      unpark();
      stopWake();
    }
  }

  /*
   * JOKAISELLA POMOLLA ON OMA ÄÄNI, ja se mitataan ääneksi eikä tauluksi.
   *
   * Päätös 9.8.2026 oli **oma ääni, jaetut toimintaäänet**, ja se odotti
   * konsonantteja: pelkillä vokaaleilla puhuva ääni ei voi sanoa eri asioita,
   * se voi vain huutaa eri korkeuksilla. Kolme väitettä:
   *
   *   1. jokainen seitsemästä todella puhuu — ääni väylällä, ei taulun rivi;
   *   2. ne eivät ole sama ääni — mitattu perustaajuus eroaa, ja järjestys on
   *      se minkä hahmot lupaavat (jättiläinen matalin, rynnäkkö korkein);
   *   3. kutsupaikkoja on kolme (tulo, osuma, kaatuminen) eikä enempää — sama
   *      lähdekoodista luettu lista kuin poimittavilla, ja samasta syystä.
   */
  {
    const { bossSay, audioTap: tapOf } = await import('/src/core/audio.js');
    const tap = tapOf();
    const running = tap && tap.ctx.state === 'running';
    const heard = [];
    let stalled = false;
    const stopWake = keepRendering(tap);
    if (running) {
      const unpark = park();
      const an = tap.ctx.createAnalyser();
      an.fftSize = 16384;
      an.smoothingTimeConstant = 0;
      tap.bus.connect(an);
      const meter = meterFor(tap, an);
      const bins = new Float32Array(an.frequencyBinCount);
      const hz = tap.ctx.sampleRate / an.fftSize;
      for (let v = 0; v < 8; v++) {
        await meter.settle(3);
        meter.clear();
        bossSay(v, 'arrive');
        /* Huippu **ja** vahvin taajuus samasta ikkunasta: ensimmäinen kertoo
         * että hän puhui, toinen kenen äänellä. Kaksi eri mittausta samasta
         * hetkestä on halvempi ja rehellisempi kuin kaksi eri hetkeä. */
        let peak = 0;
        /* Desibelejä eikä amplitudia: `getFloatFrequencyData` palauttaa
         * negatiivisia lukuja, ja nollasta alkava vertailu ei löytänyt
         * yhtäkään — mitattu `@ 0 Hz` kaikilla seitsemällä. */
        let best = -Infinity;
        let bestBin = 0;
        const t0 = tap.ctx.currentTime;
        while (tap.ctx.currentTime - t0 < 0.5) {
          peak = Math.max(peak, await meter.peakFor(60));
          an.getFloatFrequencyData(bins);
          /* Alle 900 Hz: perusääni ja ensimmäinen formantti asuvat siellä, ja
           * konsonantin kohina ylempänä veisi voiton joka kerta. */
          for (let i = 1; i < Math.min(bins.length, Math.floor(900 / hz)); i++) {
            if (bins[i] > best) { best = bins[i]; bestBin = i; }
          }
        }
        heard.push({ v, peak: Number(peak.toFixed(3)), hz: Math.round(bestBin * hz) });
      }
      stalled = meter.stalled();
      an.disconnect();
      unpark();
    }
    stopWake();
    const measured = running && metered(tap, stalled);
    /* Kuuluu, ei huuda: sama vaatimus ja samat vertailuluvut kuin muillakin
     * tämän tiedoston äänimittauksilla (kolikko 0,32, kuolema 0,57,
     * tehostus 0,60). Pomon huuto kuullaan kerran kentässä, joten se saa olla
     * niiden luokassa muttei niiden yli. */
    const mute = heard.filter((r) => r.peak < 0.12 || r.peak > 0.62).map((r) => r.v);
    const giant = heard.find((r) => r.v === 3);
    const rush = heard.find((r) => r.v === 2);
    expect('jokainen kahdeksasta pomosta puhuu, ja jättiläinen on matalampi kuin rynnäkkö',
      !measured || (mute.length === 0 && giant.hz < rush.hz),
      measured ? heard.map((r) => `${r.v}: ${r.peak} @ ${r.hz} Hz`).join(', ') : 'ei mitattu');
  }

  {
    /*
     * 2. TAPON KUITTAUS NOUSEE KETJUN MUKANA. Mitataan taajuudesta eikä
     *    koodista: sama ääni ketjun ensimmäisenä ja neljäntenä, ja jälkimmäisen
     *    vahvin taajuus on korkeampi. Ilman tätä "tyydyttävä" on mielipide.
     */
    const tapv = audioTap();
    if (tapv && tapv.ctx.state === 'running') {
      const { killSound } = await import('/src/core/audio.js');
      const stopWake2 = keepRendering(tapv);
      const an2 = tapv.ctx.createAnalyser();
      an2.fftSize = 16384;
      an2.smoothingTimeConstant = 0;
      tapv.bus.connect(an2);
      const meter2 = meterFor(tapv, an2);
      const bins2 = new Float32Array(an2.frequencyBinCount);
      const hz2 = tapv.ctx.sampleRate / an2.fftSize;
      const peakHz = async (step) => {
        await meter2.settle(2);
        meter2.clear();
        killSound(step);
        let best = -Infinity;
        let bin = 0;
        const t0 = tapv.ctx.currentTime;
        while (tapv.ctx.currentTime - t0 < 0.35) {
          await meter2.peakFor(50);
          an2.getFloatFrequencyData(bins2);
          /* 400…3000 Hz: kuittaus asuu siellä, ja rungon matala kolmio (60…200)
           * jää alle — muuten mitattaisiin iskua eikä palkintoa. */
          for (let i = Math.floor(400 / hz2); i < Math.floor(3000 / hz2); i++) {
            if (bins2[i] > best) { best = bins2[i]; bin = i; }
          }
        }
        return Math.round(bin * hz2);
      };
      const first = await peakHz(0);
      const fourth = await peakHz(4);
      an2.disconnect();
      stopWake2();
      const real = metered(tapv, meter2.stalled());
      expect('tapon kuittaus nousee ketjun mukana',
        !real || fourth > first,
        real ? `ensimmäinen ${first} Hz, neljäs ${fourth} Hz` : 'ei mitattu');
    }
  }

  {
    /* Ja kolme kutsupaikkaa, luettuna lähdekoodista. Sama tapa kuin
     * poimittavilla: taulukko joka on olemassa muttei koskaan soi on
     * ominaisuus jota teeskennellään. */
    const src = await (await fetch('/src/entities/enemies.js')).text();
    const kinds = ['arrive', 'hurt', 'die'].filter((k) => src.includes(`'${k}'`));
    const calls = (src.match(/bossSay\(/g) || []).length;
    expect('pomoäänellä on kutsupaikka jokaiselle kolmelle tilanteelle',
      kinds.length === 3 && calls === 3, `${kinds.join(' ')} — ${calls} kutsua`);
  }

  /*
   * UUDET MERKIT VÄYLÄLLÄ, mitattuna eikä muistettuna.
   *
   * Uusi ääni on regressio kahdella tavalla joita kumpaakaan ei näe koodista:
   * se voi jäädä pohjakohinaan (merkki jota ei kuule ei ole merkki) tai se voi
   * nousta niin kovaksi että se peittää ne merkit jotka olivat täällä ensin.
   * Kolikko mitataan samassa ajossa vertailukohdaksi, koska tämän tiedoston
   * muut äänimittaukset on kalibroitu siihen (kolikko 0,32) ja muistiin
   * kirjattu vertailuluku vanhenee ensimmäisessä miksausmuutoksessa.
   *
   * Väylä odotetaan hiljaiseksi ennen jokaista mittausta samalla ikkunalla
   * jolla mitataan — sama sääntö ja sama syy kuin puhutun rivin kohdalla
   * ylempänä: kiinteä odotus on arvaus edellisen äänen hännän pituudesta, ja
   * arvaava portti on kolikonheitto.
   */
  {
    // Esittelydemo käynnistyy kahdenkymmenen sekunnin jouten olosta ja soittaa
    // hyppyjä tälle samalle väylälle. Kello nollataan tästä.
    game.toTitle();
    const { Ambience } = await import('/src/core/audio.js');
    const tap = audioTap();
    const running = tap && tap.ctx.state === 'running';
    const peaks = {};
    let floorAfter = 0;
    let stalled = false;
    const stopWake = keepRendering(tap);
    if (running) {
      Music.stop();
      Ambience.stop();
      const an = tap.ctx.createAnalyser();
      /*
       * 372 ms yhtäjaksoista aaltoa, eikä 46 ms, ja se on mittausvirhe joka
       * tuotettiin tahallaan ennen kuin se korjattiin. `reserve` on kaksi
       * kopsahdusta 95 millisekunnissa, ja 2048 näytteen ikkunalla se mittasi
       * **0,000** — eli portti olisi julistanut äänettömäksi äänen jonka
       * samat kaiuttimet soittavat. Sama ikkuna mittasi 0,228 heti kun se
       * levennettiin. Lyhyt ääni ei mahdu ikkunoiden väliin kun ikkuna on
       * pidempi kuin ääni; sama syy kuin konsonanttilohkon 32768:lla.
       */
      an.fftSize = 16384;
      tap.bus.connect(an);
      const meter = meterFor(tap, an);
      const peakFor = meter.peakFor;
      /* Neljä sekuntia **soitettua ääntä**, ei seinäkelloa: ks. `meterFor`. */
      const settle = () => meter.settle(4);
      for (const name of ['pfull', 'pspent', 'pipeout', 'reserve', 'pipe', 'coin', 'powerup']) {
        /*
         * Jouten olon kello nollataan **jokaisen** äänen edeltä, eikä kerran
         * lohkon alussa.
         *
         * Kerran riitti niin kauan kuin lohko ehti mitata seitsemän ääntä
         * kahdessakymmenessä sekunnissa. Se ei ole taattua: `settle` odottaa
         * väylän hiljenemistä jopa neljä sekuntia kerrallaan, joten pahin
         * tapaus on ~32 s ja esittelydemo käynnistyy 20 s:n kohdalla samalle
         * väylälle. Mitattu kerran: `pipe` 0,332 kun sen neljä edellistä ajoa
         * olivat 0,169 — eli tasan kaksinkertainen, koska demon oma ääni osui
         * samaan ikkunaan. Portti kaatui äänestä joka ei liity siihen mitä se
         * mittaa, ja se on juuri se laji vikaa jota tämä tiedosto muualla
         * korjaa nimeltä mainiten.
         */
        if (game.scene && game.scene.idle !== undefined) game.scene.idle = 0;
        else if (game.scene && game.scene.constructor.name === 'DemoScene') {
          // Demo ehti jo alkaa: takaisin alkuruutuun, ja väylä hiljaiseksi
          // samoilla kahdella kutsulla joilla tämä lohko aloitti. Muu kohtaus
          // ei voi käynnistää demoa, joten sitä ei myöskään herätellä tässä.
          game.toTitle();
          Music.stop();
          Ambience.stop();
        }
        await settle();
        /* Odotusikkunat eivät ratkaise, mitattava ikkuna ratkaisee: nollaus
         * tähän ja luku heti sen jälkeen. Ks. `meterFor`. */
        meter.clear();
        Sfx.play(name);
        peaks[name] = await peakFor(600);
        stalled = stalled || meter.stalled();
      }
      floorAfter = await settle();
      an.disconnect();
    }
    stopWake();
    const measured = running && metered(tap, stalled);
    const n = (name) => (peaks[name] === undefined ? 0 : peaks[name]);
    const shown = Object.entries(peaks).map(([k, v]) => `${k} ${v.toFixed(3)}`).join(', ');
    expect('uudet merkit kuuluvat, eivät huuda, eivätkä jätä väylää soimaan',
      !measured || (
        // Kuuluu kolikon luokassa, ei yli pelin kovimman palkinnon.
        n('pfull') > 0.2 && n('pfull') <= n('powerup')
        // Soi joka kerta kun juoksunappi irtoaa, joten se on tarkoituksella
        // selvästi täyttymistä hiljaisempi. Merkki joka soi usein ja kovaa on
        // melua, ja melu peittää ne merkit jotka olivat täällä ensin.
        && n('pspent') > 0.08 && n('pspent') < n('pfull') * 0.7
        // Putken kaksi päätä ovat pari, joten ne mitataan pariksi.
        && n('pipeout') > n('pipe') * 0.6 && n('pipeout') < n('pipe') * 1.6
        && n('reserve') > 0.12 && n('reserve') < n('powerup')
        // Eikä yksikään niistä jätä väylää soimaan.
        && floorAfter < 0.02),
      measured ? `${shown}, tausta jäljessä ${floorAfter.toFixed(3)}` : 'ei mitattu');
  }

  /* ---- kuninkaan muodonvaihto ---- */
  /*
   * RUUTU PUKEE SAAPUVAN MAAILMAN VÄRIN.
   *
   * PIERUKUNINGAS (8-F, variantti 6) on pelin ainoa pomo joka vastaa
   * tallaukseen **vaihtumalla joksikin toiseksi**: jokainen osuma antaa
   * hänelle seuraavan linnakkeen liikevalikoiman (`KING_FORMS`). Jokainen muu
   * pomo nostaa jotakin omaa numeroaan, ja se ero on koko finaalin idea — se
   * lunastuu vain jos pelaaja **tunnistaa kesken tappelun kuka juuri saapui**,
   * eli tasan sen taidon jonka maailman 8 seitsemän uusintaa opettivat.
   *
   * Merkki ei siis saa sanoa *että* jotain vaihtui vaan **kuka** vaihtui, ja
   * siksi valkoinen välähdys olisi heittänyt koko ominaisuuden pois. Ruutu
   * pukee sen maailman värin josta saapuva muoto tulee, ja väri luetaan
   * paletista (`themeTint` + `WORLDS[i].theme`) eikä kirjoiteta toiseen
   * kertaan — toinen kopio ajautuisi erilleen ensimmäisestä heti kun jotakin
   * palettia siirretään.
   *
   * Viisi mittausta, ja ne mittaavat viittä eri tapaa mennä pieleen:
   *
   *   1  merkki    vaihdos näkyy koko ruudulla ja kuuluu omalla äänellään —
   *                eikä peitä sitä tappelua jonka päällä se soi
   *   2  väri      jokainen saapuminen kantaa oman maailmansa paletin, ja
   *                jokainen pari mitataan pelin omaa 8,6 %:n kynnystä vasten
   *   3  tallennus muoto ja sen väri kestävät pikatallennuksen
   *   4  efektit   sama merkki kaikilla kolmella kuvatehosteasetuksella,
   *                myös `pois` — jossa `PostFX.apply` palaa aikaisin
   *   5  ääni      huippu mitattuna, ei arvattuna: kuuluu, ei huuda, ei jää
   *                soimaan
   *
   * **Punainen ennen vihreää.** Ennen tätä muutosta kohta 1 mittasi
   * "0/66560 px pelialueesta muuttui, saapumisen ääni fart" — eli kuvaa ei
   * ollut lainkaan ja ääni oli lainattu jättiläisen kasvulta. Se on mittaus
   * hiljaisuudesta eikä mielipide siitä että tähän pitäisi ehkä lisätä jotain.
   */
  {
    const { PostFX: FX, PRESETS: FX_PRESETS } = await import('/src/gfx/postfx.js');
    const kingMod = await import('/src/entities/enemies.js');
    const tiles8 = await import('/src/gfx/tiles.js');
    const tintOf = tiles8.themeTint;

    /* Äänet jotka tarkoittavat jo jotain muuta. Sama lista ja sama syy kuin
     * lohkossa "tilanvaihdos joka ei kuulunut eikä näkynyt": lainattu ääni
     * tarkoittaa lainaamisen jälkeen kahta asiaa, ja pelaaja oppii lukemaan
     * toisen niistä väärin. `fart` on tässä nimenomaan siksi että se oli se
     * ääni jolla kuningas vaihtoi muotoa — ja se on jättiläisen kasvun ääni. */
    const OTHERS = ['jump', 'bigjump', 'fart', 'bigfart', 'squeak', 'flight', 'coin',
      'stomp', 'bump', 'brick', 'burst', 'sprout', 'dive', 'slam', 'kurnutus',
      'loikka', 'kick', 'spikes', 'pop', 'upota', 'kahlaa', 'cork', 'soup', 'powerup',
      'yeah', 'oof', 'letsgo', 'powerdown', 'oneup', 'die', 'clear', 'cursor', 'select',
      'luuranko', 'boss', 'timewarn', 'door', 'payout', 'kytkin', 'doorin',
      'pfull', 'pspent', 'pipeout', 'reserve', 'pipe'];

    const kc = document.createElement('canvas');
    kc.width = 320;
    kc.height = 240;
    const kg = kc.getContext('2d', { willReadFrequently: true });
    const PLAY_W = 320;
    const PLAY_H = 208;
    const PLAY_PX = PLAY_W * PLAY_H;
    /* Kuva niin kuin se menee ruudulle: kohtaus ja sen päälle jälkikäsittely,
     * koska verho asuu `PostFX.apply`issa eikä `LevelScene.draw`issa. */
    const shot = () => {
      kg.clearRect(0, 0, 320, 240);
      game.scene.draw(kg);
      FX.apply(kg);
      return kg.getImageData(0, 0, PLAY_W, PLAY_H).data;
    };
    /* Verho pois ilman että maailmaan kosketaan: kaksi muuten identtistä
     * ruutua, joten erotus on verho ja vain verho. */
    const stopFlash = () => { FX.flashLeft = 0; };
    const listenK = () => {
      const real = Sfx.play;
      const heard = [];
      Sfx.play = function tap(name) { heard.push(name); };
      return { heard, off() { Sfx.play = real; } };
    };
    const kingFight = () => {
      reset();
      const s = new LevelScene(game, '8-F');
      game.setScene(s);
      stopFlash();
      return { s, boss: s.entities.find((e) => e instanceof kingMod.Boss) };
    };
    /* Yksi osuma, ja siitä kaksi kuvaa: verhon kanssa ja ilman. Maailmaa ei
     * päivitetä välissä, joten erotus ei voi olla kävelevä pomo. */
    const hit = (boss) => {
      const tap = listenK();
      let heard = [];
      try {
        boss.invuln = 0;
        boss.stomp();
        heard = tap.heard.slice();
      } finally { tap.off(); }
      const lit = shot();
      stopFlash();
      const dark = shot();
      return { heard, lit, dark };
    };
    const changed = (a, b) => {
      let n = 0;
      for (let p = 0; p < a.length; p += 4) {
        if (a[p] !== b[p] || a[p + 1] !== b[p + 1] || a[p + 2] !== b[p + 2]) n++;
      }
      return n;
    };
    /** Suorakulmion keskimääräinen ja pahin värimuutos, kanavittain. */
    const boxDelta = (a, b, x0, y0, w, h) => {
      const d = [0, 0, 0];
      let n = 0;
      let worst = 0;
      for (let y = Math.max(0, y0); y < Math.min(PLAY_H, y0 + h); y++) {
        for (let x = Math.max(0, x0); x < Math.min(PLAY_W, x0 + w); x++) {
          const p = (y * PLAY_W + x) * 4;
          for (let c = 0; c < 3; c++) {
            d[c] += a[p + c] - b[p + c];
            worst = Math.max(worst, Math.abs(a[p + c] - b[p + c]));
          }
          n++;
        }
      }
      return { mean: n ? d.map((v) => v / n) : [0, 0, 0], worst, n };
    };
    /** Nurkka, jossa verho on täydessä voimassaan eikä kukaan seiso. */
    const corner = (r) => boxDelta(r.lit, r.dark, 0, 0, 12, 12).mean;
    /* Sama mitta kuin vihollisen ja maan kontrastilla: keskimääräinen
     * kanavaero täydestä 255:stä. Karkea, mutta **sama luku** kuin se jota
     * peli jo käyttää erottuvuuden mittana, ja se on tässä arvokkaampaa kuin
     * parempi luku jota ei voi verrata mihinkään. */
    const sepK = (a, b) => ((Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1])
      + Math.abs(a[2] - b[2])) / 3 / 255) * 100;
    /* Kynnys ei ole typotettu tähän: se on aavikon oma maa/tiili-ero, pelin
     * heikoin pari joka on jo tuotannossa ja tiedetään siedettäväksi. */
    const floorSep = (() => {
      const mean = (ch, theme) => {
        kg.clearRect(0, 0, 16, 16);
        tiles8.drawTile(kg, ch, 0, 0, theme, 3, 5, 0, ' ', {});
        const d = kg.getImageData(0, 0, 16, 16).data;
        const acc = [0, 0, 0];
        let n = 0;
        for (let q = 0; q < d.length; q += 4) {
          if (d[q + 3] < 8) continue;
          acc[0] += d[q]; acc[1] += d[q + 1]; acc[2] += d[q + 2]; n++;
        }
        return n ? acc.map((v) => v / n) : [0, 0, 0];
      };
      return sepK(mean(tiles8.T.GROUND, 'desert'), mean(tiles8.T.BRICK, 'desert'));
    })();

    let arriveSfx = null;

    /*
     * 1. MERKKI. Kaksi puolta yhdessä (DESIGN.md kohta 8) ja kolmas ehto joka
     *    on reiluutta eikä kauneutta: verho ei saa peittää sitä tappelua jonka
     *    päällä se soi. Pelaaja on tällä framella kesken hyppyä pomon päällä,
     *    ja läpinäkymätön täysvälähdys juuri siinä on epäreilu eikä koriste.
     *    Ruudun keskus jää siksi koskemattomaksi ja väri asuu reunoilla, josta
     *    sen näkee katsomatta pois siitä mitä tekee.
     */
    {
      const { s, boss } = kingFight();
      const p = s.player;
      /* Se hetki jota väite koskee: pelaaja on juuri tallannut ja on ilmassa
       * pomon pään yläpuolella. Kentän alussa mitattuna kumpikaan ei ole edes
       * ruudulla, ja "verho ei peitä tappelua" mitattaisiin tyhjästä
       * käytävästä. */
      p.x = boss.cx - p.w / 2;
      p.y = boss.y - p.h - 12;
      p.vx = 0;
      p.vy = -2;
      p.onGround = false;
      s.centerCamera();
      const cam = { x: Math.round(s.cam.x), y: Math.round(s.cam.y) };
      const r = hit(boss);
      const cover = changed(r.lit, r.dark);
      const onBoss = boxDelta(r.lit, r.dark, Math.round(boss.x) - cam.x,
        Math.round(boss.y) - cam.y + s.bar, Math.round(boss.w), Math.round(boss.h));
      const onPlayer = boxDelta(r.lit, r.dark, Math.round(p.x) - cam.x,
        Math.round(p.y) - cam.y + s.bar, Math.round(p.w), Math.round(p.h));
      const arrive = r.heard.filter((x) => x !== 'stomp');
      arriveSfx = arrive.length === 1 ? arrive[0] : null;
      /* Kesto mitataan pikseleistä eikä vakiosta luetaan: verho elää niin
       * kauan kuin se muuttaa ruutua. Osuman jälkeen pomoon ei voi osua 70
       * frameen (`invuln`), joten se on se ikkuna jonka sisään sen on
       * mahduttava — merkki joka on yhä ruudulla kun tappelu jatkuu on
       * suodatin eikä merkki. */
      let frames = 0;
      {
        const { boss: b2 } = kingFight();
        b2.invuln = 0;
        b2.stomp();
        for (let f = 0; f < 240; f++) {
          const a = shot();
          const keep = FX.flashLeft || 0;
          FX.flashLeft = 0;
          const b = shot();
          FX.flashLeft = keep;
          if (changed(a, b) > 0) frames++; else break;
        }
      }
      expect('kuninkaan muodonvaihto näkyy koko ruudulla ja kuuluu omalla äänellään',
        !!arriveSfx && Sfx.has(arriveSfx) && !OTHERS.includes(arriveSfx)
        && cover > PLAY_PX * 0.5 && onBoss.worst <= 26 && onPlayer.worst <= 26
        && frames >= 8 && frames <= 40,
        `ääni "${r.heard.join('+') || '-'}" (saapuminen "${arrive.join('+') || '-'}"), `
        + `${cover}/${PLAY_PX} px pelialueesta = ${((cover / PLAY_PX) * 100).toFixed(1)} %, `
        + `kesto ${frames} framea = ${Math.round((frames / 60) * 1000)} ms `
        + `(osumattomuus 70 framea), pomon päällä enintään ${onBoss.worst}/255, `
        + `pelaajan päällä ${onPlayer.worst}/255`);
    }

    /*
     * 2. VÄRI, ja tämä on se väite joka on ensimmäistä arvokkaampi.
     *
     *    Merkki joka nimeää kaksi eri saapujaa samalla värillä on pahempi kuin
     *    merkitsemättömyys, koska sen oppii uskomaan. Siksi jokainen pari
     *    mitataan, ja kynnyksenä on pelin oma: aavikon maa vastaan aavikon
     *    tiili, se heikoin pari jonka peli jo tietoisesti sietää.
     *
     *    **Ja tässä on löydös jota ei etsitty.** Maailma 5 (JÄLKIPYYKKI)
     *    kantaa maailman 1 palettia — kirjattu päätös `worlds.js`:ssä ("sama
     *    ruoho, eri maasto") — joten niiden pari mittaa **0,0 %**. Se ei
     *    kuitenkaan osu tähän merkkiin, ja syy on kuninkaan omassa
     *    kierrossaan: hän **kävelee sisään** maailman 1 muodossa eikä saavu
     *    siinä, ja seitsemäs osuma kaataa hänet vaihtamatta muotoa. Verhoja on
     *    siis kuusi ja ne ovat maailmat 2…7, joissa jokainen paletti esiintyy
     *    kerran. Portti vaatii sen erikseen: yksikään maalattu pari ei jää
     *    kynnyksen alle. Jos joku joskus antaa kuninkaalle kahdeksannen
     *    linnakkeen tai laukaisee verhon myös tappelun alussa, tämä kaatuu.
     */
    {
      const forms = kingMod.KING_FORMS ? kingMod.KING_FORMS.length : 7;
      const worlds = [];
      for (let i = 0; i < forms; i++) worlds.push(WORLDS[i]);
      const tints = worlds.map((w) => (tintOf ? tintOf(w.theme) : null));

      const { boss } = kingFight();
      const seen = [];
      for (let i = 0; i < forms; i++) {
        const from = boss.formIndex;
        const r = hit(boss);
        seen.push({ from, to: boss.formIndex, d: corner(r) });
      }
      const arrivals = seen.filter((x) => x.to !== x.from);
      const painted = arrivals.filter((x) => Math.max(...x.d.map(Math.abs)) > 4);
      const worldsPainted = painted.map((x) => x.to);

      /* Kaikki 21 paria luetaan raporttiin, myös se nolla: mitattu luku joka
       * ei ole missään näkyvissä on sama asia kuin muistettu luku. */
      const pairs = [];
      let worstPainted = 1e9;
      let worstPaintedPair = '-';
      for (let i = 0; i < forms; i++) {
        for (let j = i + 1; j < forms; j++) {
          const v = tints[i] && tints[j] ? sepK(tints[i], tints[j]) : 0;
          const both = worldsPainted.includes(i) && worldsPainted.includes(j);
          pairs.push(`w${i + 1}/w${j + 1} ${v.toFixed(1)}${both ? '' : '°'}`);
          if (both && v < worstPainted) {
            worstPainted = v;
            worstPaintedPair = `w${i + 1}/w${j + 1}`;
          }
        }
      }
      /* Ja sama erottuvuus mitattuna ruudulta eikä paletista: verho on
       * lisäävä, joten kahden verhon ero ruudulla on sama ero vaimennettuna. */
      let worstPx = 1e9;
      for (let i = 0; i < painted.length; i++) {
        for (let j = i + 1; j < painted.length; j++) {
          worstPx = Math.min(worstPx, sepK(painted[i].d, painted[j].d));
        }
      }
      expect('jokainen saapuminen kantaa oman maailmansa värin, ja ne erottuvat toisistaan',
        !!tintOf && arrivals.length === forms - 1 && painted.length === arrivals.length
        && new Set(worldsPainted).size === painted.length
        && worstPainted >= floorSep && worstPx > 0,
        `kynnys ${floorSep.toFixed(1)} % (aavikon maa vs tiili); `
        + `verhoja ${painted.length}/${arrivals.length} saapumista `
        + `(maailmat ${worldsPainted.map((i) => i + 1).join(' ')}); `
        + `heikoin maalattu pari ${worstPaintedPair} `
        + `${worstPainted === 1e9 ? '-' : `${worstPainted.toFixed(1)} %`}, `
        + `ruudulta mitattuna ${worstPx === 1e9 ? '-' : `${worstPx.toFixed(1)} %`}; `
        + `värit ${tints.map((c, i) => `w${i + 1} ${c ? c.join('/') : '-'}`).join(' ')}; `
        + `kaikki parit ${pairs.join(' ')} (° = pari jota ei koskaan maalata)`);
    }

    /*
     * 3. PIKATALLENNUS. Kuninkaan kohta kierrossa on `formIndex`, ja jos se ei
     *    kestä tallennusta, ladattu tappelu jatkuu väärältä muodolta ja verho
     *    nimeää väärän maailman. `savestate.js` sarjallistaa entiteetin omat
     *    kentät, joten tämä kaatuu jos joku joskus siirtää muodon johonkin
     *    mikä ei ole oma kenttä — ja verhon oma tila on tarkoituksella
     *    `PostFX`:ssä eikä tallennuksessa, samoin kuin vauhtimittarin sykäys.
     */
    {
      const { boss } = kingFight();
      for (let i = 0; i < 3; i++) { boss.invuln = 0; boss.stomp(); }
      stopFlash();
      const before = { form: boss.form, index: boss.formIndex, hp: boss.hp };
      const snap = JSON.parse(JSON.stringify(captureState(game)));
      restoreState(game, snap);
      const back = game.scene.entities.find((e) => e instanceof kingMod.Boss);
      const after = back
        ? { form: back.form, index: back.formIndex, hp: back.hp } : null;
      const r = back ? hit(back) : null;
      const got = r ? corner(r) : [0, 0, 0];
      /* Verho on lisäävä, joten muutos osoittaa värin suuntaan. Lähin
       * seitsemästä maailmasta on se jonka ruutu puki — ja vertailu tehdään
       * väriin eikä numeroon, koska kaksi maailmaa jakaa paletin. */
      const norm = (v) => {
        const m = Math.max(1e-6, Math.hypot(v[0], v[1], v[2]));
        return v.map((x) => x / m);
      };
      let nearest = -1;
      if (tintOf && r) {
        const g0 = norm(got);
        let best = -1;
        for (let i = 0; i < 7; i++) {
          const c = norm(tintOf(WORLDS[i].theme));
          const dot = c[0] * g0[0] + c[1] * g0[1] + c[2] * g0[2];
          if (dot > best) { best = dot; nearest = i; }
        }
      }
      const want = after && tintOf ? tintOf(WORLDS[after.index + 1].theme) : null;
      const drew = nearest >= 0 && tintOf ? tintOf(WORLDS[nearest].theme) : null;
      expect('pikatallennus palauttaa kuninkaan samaan muotoon, ja verho samaan väriin',
        !!after && JSON.stringify(before) === JSON.stringify(after)
        && !!want && !!drew && want.join(',') === drew.join(','),
        `ennen ${JSON.stringify(before)}, jälkeen ${JSON.stringify(after)}, `
        + `seuraava verho rgb(${got.map((v) => Math.round(v)).join(',')}) → `
        + `${drew ? `rgb(${drew.join(',')})` : '-'} (maailma ${nearest + 1}), `
        + `odotettu ${want ? `rgb(${want.join(',')})` : '-'} `
        + `(maailma ${after ? after.index + 2 : '-'})`);
    }

    /*
     * 4. KUVATEHOSTEET, ja **kaikki kuusi yhdistelmää eikä kolmea**.
     *
     *    `7` kiertää kolme asetusta, ja niistä yksi on `pois`, jossa
     *    `PostFX.apply` palaa aikaisin: verho joka olisi kirjoitettu sen paluun
     *    alapuolelle olisi näkymätön tasan sille pelaajalle joka on pyytänyt
     *    nähdä pelin sellaisenaan.
     *
     *    Mutta asetus on vain toinen puoli. Ilman WebGL:ää skanviivat ja
     *    vinjetti piirretään **2D:nä samaan kankaaseen verhon jälkeen**, eli
     *    juuri siinä polussa nurkka voi tummua takaisin — ja se on se polku
     *    jota tämä ajo ei muuten koskaan aja, koska ajuri on tässä koneessa
     *    kunnossa. Siksi sama mittaus tehdään myös irrallisella 2D-instanssilla
     *    (`Object.create`, sama tapa kuin jälkikäsittelyn omassa lohkossa).
     *
     *    Peitto yksinään ei kelpaa väitteeksi kummassakaan: sama pikselimäärä
     *    voi muuttua paljon vähemmän. Siksi mitataan myös kuinka monta askelta
     *    255:stä nurkka nousee.
     */
    {
      const was = FX.preset;
      /* 2D-polku omana instanssinaan: sama koodi, sama kangas, ei ajuria.
       * `_bloomCtx` ja muut välimuistit peritään, mikä on tarkoitus — ne ovat
       * työkaluja eivätkä tilaa. */
      const soft = Object.create(FX);
      soft.mode = '2d';
      soft.source = kc;
      soft.ambience = null;
      soft.ambienceAmount = 0;
      soft.tick = 0;
      soft.flashLeft = 0;
      soft.flashRgb = null;
      soft.flashSpan = 1;
      /** Sama kuva toisella jälkikäsittelijällä, verhon kanssa ja ilman. */
      const shotWith = (fx) => {
        kg.clearRect(0, 0, 320, 240);
        game.scene.draw(kg);
        fx.apply(kg);
        return kg.getImageData(0, 0, PLAY_W, PLAY_H).data;
      };
      const rows = [];
      let worstShare = 1;
      let worstLift = 255;
      for (const name of FX_PRESETS) {
        FX.setPreset(name);
        soft.preset = name;
        const { boss } = kingFight();
        const r = hit(boss);
        const share = changed(r.lit, r.dark) / PLAY_PX;
        const lift = Math.max(...corner(r));
        rows.push(`${name}/${FX.mode} ${(share * 100).toFixed(1)} % +${lift.toFixed(0)}`);
        worstShare = Math.min(worstShare, share);
        worstLift = Math.min(worstLift, lift);

        // Ja sama ilman ajuria. Verho laukaistaan käsin, koska pomo puhuu
        // moduulin omalle instanssille.
        const { boss: b2 } = kingFight();
        b2.invuln = 0;
        b2.stomp();
        soft.flashRgb = FX.flashRgb;
        soft.flashSpan = FX.flashSpan;
        soft.flashLeft = FX.flashLeft;
        const lit2 = shotWith(soft);
        soft.flashLeft = 0;
        const dark2 = shotWith(soft);
        const share2 = changed(lit2, dark2) / PLAY_PX;
        const lift2 = Math.max(...boxDelta(lit2, dark2, 0, 0, 12, 12).mean);
        rows.push(`${name}/2d ${(share2 * 100).toFixed(1)} % +${lift2.toFixed(0)}`);
        worstShare = Math.min(worstShare, share2);
        worstLift = Math.min(worstLift, lift2);
      }
      FX.setPreset(was);
      expect('verho näkyy kaikilla kolmella kuvatehosteasetuksella, myös ilman ajuria',
        worstShare > 0.5 && worstLift > 20,
        `${rows.join(', ')} (osuus pelialueesta ja nurkan nousu 255:stä)`);
    }

    /*
     * 5. ÄÄNI, mitattuna eikä arvattuna. Uusi ääni voi jäädä pohjakohinaan
     *    (merkki jota ei kuule ei ole merkki) tai nousta niin kovaksi että se
     *    peittää ne merkit jotka olivat täällä ensin. Vertailukohdat mitataan
     *    samassa ajossa, koska muistiin kirjattu luku vanhenee ensimmäisessä
     *    miksausmuutoksessa — ja `stomp` on niistä tärkein: osuma ja saapuminen
     *    ovat kaksi tapahtumaa samalla framella, ja saapumisen on oltava se
     *    jonka korva poimii.
     */
    {
      game.toTitle();
      const { Ambience: Amb } = await import('/src/core/audio.js');
      const tap = audioTap();
      const running = tap && tap.ctx.state === 'running';
      const peaks = {};
      let floorAfter = 0;
      let stalled = false;
      const stopWake = keepRendering(tap);
      if (running) {
        Music.stop();
        Amb.stop();
        const an = tap.ctx.createAnalyser();
        // Sama 16384 kuin muillakin lyhyillä äänillä: ikkunan on oltava
        // pidempi kuin mitattava ääni, tai portti julistaa äänettömäksi äänen
        // jonka kaiuttimet soittavat.
        an.fftSize = 16384;
        tap.bus.connect(an);
        const meter = meterFor(tap, an);
        const peakFor = meter.peakFor;
        const settle = () => meter.settle(4);     // äänikellossa, ks. `meterFor`
        for (const name of [arriveSfx, 'stomp', 'coin', 'powerup']) {
          if (!name || !Sfx.has(name)) continue;
          await settle();
          meter.clear();                     // ks. `meterFor`: vain mitattava ikkuna ratkaisee
          Sfx.play(name);
          peaks[name] = await peakFor(600);
          stalled = stalled || meter.stalled();
        }
        floorAfter = await settle();
        an.disconnect();
      }
      stopWake();
      const measured = running && metered(tap, stalled);
      const n = (name) => (name && peaks[name] !== undefined ? peaks[name] : 0);
      const shown = Object.entries(peaks).map(([k, v]) => `${k} ${v.toFixed(3)}`).join(', ');
      expect('saapumisen ääni kuuluu, ei huuda, eikä jätä väylää soimaan',
        !measured || (
          n(arriveSfx) > n('coin') && n(arriveSfx) <= n('powerup')
          && n(arriveSfx) > n('stomp') && floorAfter < 0.02),
        measured ? `${shown}, tausta jäljessä ${floorAfter.toFixed(3)}` : 'ei mitattu');
    }
  }
  /* ---- kuninkaan muodonvaihto loppuu ---- */

  /*
   * Ja se rivi joka pitää huolen ettei äänimittaus voi kadota huomaamatta.
   *
   * "Ei mitattu" on rehellinen vastaus yhdelle mittaukselle jonka aikana kone
   * ei renderöinyt — mutta jos se olisi vastaus *jokaiseen*, koko ääniportti
   * olisi sammunut ilman että kukaan huomaa, ja se on tasan se tapa jolla
   * portteja hiljaisesti menetetään. Sama vaatimus kuin missä tahansa
   * poikkeuslistassa tässä tiedostossa: sen pituus on itsessään mitattava luku.
   */
  expect('äänimittaukset todella mitattiin eikä vain ohitettu',
    audioSkipped === 0 || audioMeasured > 0,
    `mitattu ${audioMeasured}, ohitettu ${audioSkipped} (äänikello ei edennyt)`);

  /* A backgrounded tab throttles setTimeout, so the sequencer can wake up
   * seconds behind the audio clock. Playing that backlog would build thousands
   * of oscillators in one turn of the event loop and freeze the keyboard. */
  {
    Sfx.resume();
    Music.play('level');
    const before = Music._step;
    Music._nextTime -= 30;                 // pretend the tab was hidden
    const t0 = performance.now();
    let threw = null;
    try { Music._tick(); } catch (err) { threw = err.message; }
    const elapsed = performance.now() - t0;
    const aligned = Music._step - before > 0 && Music._step % Music._loopLen < 8;
    expect('the sequencer drops a backlog instead of playing it',
      !threw && elapsed < 150 && aligned,
      `${Math.round(elapsed)}ms${threw ? `, threw ${threw}` : ''}`);
    Music.stop();
  }
  {
    const { getLevel, levelIds } = await import('/src/data/levels.js');
    const missing = [...new Set(levelIds().map((id) => getLevel(id).music).filter(Boolean))]
      .filter((name) => !Music.has(name));
    expect('every level names a real music track', missing.length === 0, missing.join(', '));
  }

  /*
   * DANSE MACABRE, ELI SE ETTÄ VALSSI ON DATASSA EIKÄ KOMMENTISSA.
   *
   * Luumaailman raita on Saint-Saëns'n *Danse macabre* (1874, vapautunut
   * 1.1.1992), ja DESIGN.md kohta 1 b sanoo millä ehdoilla: sävelet käsin
   * `TRACKS`-tauluun, ei äänitettä eikä nuottilaitosta, ja lähde nimetään.
   * Nimeäminen tarkistetaan ajon lopussa tiedostoista; tässä tarkistetaan se
   * mikä on tarkistettavissa itse datasta.
   *
   * Kaksi väitettä, ja molemmat ovat sellaisia jotka voi rikkoa vahingossa
   * yhdellä nuotilla eikä kumpikaan näkyisi missään muualla:
   *
   *   - **Teos on kolmijakoinen.** Sekvensseri laskee kuudestoistaosia ja sen
   *     tahti on 16 askelta eli neljäjakoinen. Valssi tehdään tässä niin että
   *     jokainen ääni ja jokainen rumpukuvio on kuuden askeleen monikerta —
   *     kuusi kuudestoistaosaa on yksi 3/4-tahti. Yksikin ääni väärän
   *     mittaisena, ja raita alkaa vaeltaa omaa tahtiaan muita vasten. Se
   *     kuulostaisi rikkinäiseltä eikä väärältä, mikä on juuri se vika jota
   *     kukaan ei osaa etsiä.
   *   - **Keskiyö lyö kaksitoista.** Teos alkaa kahdellatoista lyönnillä, ja
   *     ne ovat tässä ensimmäisenä fraasina. Se on koko sovituksen tunnistettavin
   *     yksittäinen asia, joten se on myös se jonka pitää olla luettavissa
   *     datasta eikä vain kuultavissa.
   */
  {
    Sfx.resume();
    Music.play('bone');
    const track = Music._track;
    const lens = [
      ...(Music._voices || []).map((v) => `${v.name} ${v.len}`),
      ...(Music._phrases || []).map((p, i) => `fraasi${i} ${p.len}`),
      ...Object.entries((track && track.drums) || {}).map(([k, p]) => `${k} ${p.length}`),
    ];
    const numbers = lens.map((s) => Number(s.split(' ')[1]));
    const inThree = numbers.length > 0 && numbers.every((n) => n % 6 === 0);

    const first = track && track.lead && track.lead.phrases ? track.lead.phrases[0] : [];
    let run = 0;
    let best = 0;
    let prev = null;
    for (const [semi] of first) {
      run = semi !== null && semi === prev ? run + 1 : 1;
      prev = semi;
      best = Math.max(best, run);
    }
    expect('luumaailman raita on kolmijakoinen jokaista ääntä myöten',
      inThree, lens.join(', ') || 'ei raitaa');
    expect('keskiyö lyö kaksitoista ennen kuin tanssi alkaa',
      best === 12, `pisin toisto ${best} lyöntiä, fraasissa ${first.length} nuottia`);
    Music.stop();
  }

  /*
   * KAASUKEHÄ, ELI SE ETTÄ LYYDINEN ON DATASSA EIKÄ TUNNELMASSA.
   *
   * Maailman 7 raita on **tätä peliä varten sävelletty** — ei `source`-kenttää,
   * eikä sitä kysytä miltään, koska DESIGN.md kohdan 1 b sääntö koskee
   * lainattua eikä kaikkea. Vapautuneesta sävelmistöstä ei löytynyt teosta joka
   * olisi ollut *tämä paikka* samalla tavalla kuin Danse macabre oli
   * luulaakso, ja aihevalinta on ainoa peruste jolla lainaaminen on tässä
   * pelissä tehty.
   *
   * Sävellyksen yksi ajatus on kirjoitettavissa numeroina, joten se
   * tarkistetaan: raita on **D-lyydisessä**. Lyydinen on duuriasteikko jonka
   * neljäs sävel on korotettu, ja juuri se yksi sävel on syy valita se tänne:
   * korotettu kvartti poistaa vetovoiman subdominanttiin, eli harmonia ei
   * koskaan kallistu alaspäin. Se on kirjaimellisesti sen soundi ettei mikään
   * laskeudu — mikä on tämän maailman koko aihe.
   *
   * Kaksi lukua, ja molemmat rikkoutuvat yhdestä nuotista:
   *   - **alennettua kvarttia (G) ei ole kertaakaan.** Yksi G ja moodi on
   *     jälleen tavallinen duuri, eikä kukaan osaisi etsiä sitä yhtä säveltä.
   *   - **korotettu kvartti (G#) soi useasti.** Lyydinen jossa ei koskaan soi
   *     sen oma sävel on lyydinen vain paperilla.
   */
  {
    Sfx.resume();
    Music.play('cloud');
    const track = Music._track;
    /* D on -7 puolisävelaskelta A:sta, joten sävelluokka lasketaan siitä. */
    const pcOf = (semi) => (((semi + 7) % 12) + 12) % 12;
    const LYDIAN = [0, 2, 4, 6, 7, 9, 11];
    const counts = new Array(12).fill(0);
    const collect = (notes) => {
      for (const [semi] of notes || []) {
        if (semi === null || semi === undefined) continue;
        for (const s of Array.isArray(semi) ? semi : [semi]) counts[pcOf(s)]++;
      }
    };
    for (const name of ['lead', 'harm', 'bass']) {
      const voice = (track || {})[name];
      if (!voice) continue;
      collect(voice.notes);
      for (const phrase of voice.phrases || []) collect(phrase);
    }
    const outside = counts
      .map((n, pc) => ({ pc, n }))
      .filter((x) => x.n && !LYDIAN.includes(x.pc));
    expect('pilviraita on D-lyydinen: korotettu kvartti soi, alennettua ei ole',
      outside.length === 0 && counts[6] >= 8 && counts[5] === 0,
      `G# ${counts[6]} kertaa, G ${counts[5]} kertaa, asteikon ulkopuolella `
      + `${outside.map((x) => `pc${x.pc}×${x.n}`).join(' ') || 'ei mitään'}`
      + ` — säveliä yhteensä ${counts.reduce((a, b) => a + b, 0)}`);
    Music.stop();
  }

  /*
   * YÖ AUTIOVUORELLA, ELI SE ETTÄ AAMU ON DATASSA EIKÄ SELITYKSESSÄ.
   *
   * Viimeisen linnakkeen raita on Modest Mussorgskin *Yö Autiovuorella* (1867)
   * Nikolai Rimski-Korsakovin sovituksena (1886), ja DESIGN.md kohta 1 b
   * sanoo millä ehdoilla: sävelet käsin `TRACKS`-tauluun, ei äänitettä eikä
   * nuottilaitosta, ja lähde nimetään. Nimeäminen tarkistetaan ajon lopussa
   * molemmista dokumenteista — ja **molemmat tekijät**, koska sovitus on oma
   * teoksensa omine suoja-aikoineen. Täällä tarkistetaan se mikä on
   * tarkistettavissa itse sävelistä.
   *
   * Teoksen koko dramaturgia on yksi käänne: **yö on mollissa, aamu on
   * duurissa.** Kellon lyötyä pahat väistyvät ja loppu on sama sävellaji
   * suurena. Se on kirjoitettavissa numeroina, ja se on juuri sen lajin väite
   * joka rikkoutuu yhdestä nuotista huomaamatta:
   *
   *   - **yön fraasit eivät sisällä duuriterssiä kertaakaan.** Yksi F# yössä ja
   *     käänteestä tulee koriste, koska duuri oli jo käynyt.
   *   - **aamun fraasi ei sisällä molliterssiä kertaakaan**, ja sisältää
   *     duuriterssin. Muuten aamu on vain hiljaisempi yö.
   *
   * Ja kello: aamufraasi alkaa toistuvilla lyönneillä samaa säveltä, kuten
   * luulaakson keskiyö. Ero on tarkoituksellinen ja se on suunta — luulaakson
   * kaksitoista lyöntiä *aloittavat* tanssin, tämän raidan lyönnit *lopettavat*
   * yön.
   */
  {
    Sfx.resume();
    Music.play('autiovuori');
    const track = Music._track;
    /* D on -7 puolisävelaskelta A:sta, sama laskutapa kuin pilviraidalla. */
    const pcOf = (semi) => (((semi + 7) % 12) + 12) % 12;
    const MINOR_THIRD = 3;
    const MAJOR_THIRD = 4;
    const phrases = ((track || {}).lead || {}).phrases || [];
    const countIn = (phrase, pc) => {
      let n = 0;
      for (const [semi] of phrase || []) {
        if (semi === null || semi === undefined) continue;
        for (const s of Array.isArray(semi) ? semi : [semi]) if (pcOf(s) === pc) n++;
      }
      return n;
    };
    const night = phrases.slice(0, -1);
    const dawn = phrases[phrases.length - 1] || [];
    const nightMajor = night.reduce((s, p) => s + countIn(p, MAJOR_THIRD), 0);
    const nightMinor = night.reduce((s, p) => s + countIn(p, MINOR_THIRD), 0);
    const dawnMajor = countIn(dawn, MAJOR_THIRD);
    const dawnMinor = countIn(dawn, MINOR_THIRD);
    /* Kello: pisin sarja samaa säveltä aamufraasin alussa. */
    let toll = 0;
    for (const [semi] of dawn) {
      if (semi !== null && semi === (dawn[0] || [])[0]) toll++;
      else break;
    }
    expect('autiovuoren yö on mollissa ja sen aamu duurissa',
      phrases.length >= 3 && nightMinor > 0 && nightMajor === 0
      && dawnMajor > 0 && dawnMinor === 0,
      `yössä molliterssi ${nightMinor}, duuriterssi ${nightMajor} `
      + `(${night.length} fraasia); aamussa duuriterssi ${dawnMajor}, `
      + `molliterssi ${dawnMinor}`);
    expect('aamun fraasi alkaa kellonlyönneillä',
      toll >= 4, `${toll} lyöntiä, aamufraasissa ${dawn.length} nuottia`);

    /*
     * Ja se puolisko ilman jota käänne ei kuuluisi: **säestyksessä ei ole
     * terssiä.**
     *
     * Sekvensseri vaihtaa fraasia joka kierroksella mutta soittaa saman
     * `harm`in läpi koko raidan. Mollisointu aamun alla rikkoisi käänteen
     * täsmälleen sillä nuotilla jolla se tehdään, eikä sitä kuulisi
     * rikkinäisenä vaan latteana. Paljas kvintti kantaa molemmat, ja se on
     * tarkistettavissa: ei yhtään F:ää eikä F#:ää.
     */
    const harmThirds = ((track || {}).harm || {}).notes || [];
    let thirds = 0;
    for (const [semi] of harmThirds) {
      if (semi === null || semi === undefined) continue;
      for (const s of Array.isArray(semi) ? semi : [semi]) {
        if (pcOf(s) === MINOR_THIRD || pcOf(s) === MAJOR_THIRD) thirds++;
      }
    }
    expect('autiovuoren säestyksessä ei ole terssiä, joten sama sointu kantaa yön ja aamun',
      harmThirds.length > 0 && thirds === 0,
      `${harmThirds.length} sointua, terssejä ${thirds}`);
    Music.stop();
  }


  /* ===================== THE MUSIC PASS, 20.8.2026 ====================== *
   *
   * Ten gates, and every one of them reads notes rather than labels. That is
   * the whole difficulty with music in a test suite: a track called "a waltz"
   * is a waltz because somebody typed the word, and a gate that checks the word
   * checks nothing. So each of these picks the one thing about a piece that
   * would stop being true if the piece were written the ordinary way, and
   * counts it.
   * ===================================================================== */

  /*
   * 1. DOUBLE TIME IS DENSITY, NOT TEMPO.
   *
   * Owner, 20.8.2026: *"the speedup in the first tune sounds bad. i think it'd
   * better be a doubletime kinda thing where only one instrument switches to a
   * faster subdivision but the others keep the same tempo."*
   *
   * The old hurry multiplied the step by 1.4 and the `double time` section
   * multiplied it by 2, so everything moved together and nothing was heard
   * against anything. What replaced it has to be measured as **three numbers at
   * once**, because any two of them are satisfiable by the old behaviour too:
   *
   *   - the named voice's onsets **double**. A faster tempo does that as well.
   *   - every other voice's onsets are **unchanged**. This is the one the old
   *     gear could not do, and it is why the counts are per voice.
   *   - the step length is **the same number**. Without it, a tempo change that
   *     happened to keep the note count would pass.
   *
   * `jaatie` is the track under test because every note in its lead is an
   * eighth or longer, so the doubling is exact rather than approximate — the
   * `DOUBLE_MIN_LEN` floor never fires and the count is arithmetic. The counts
   * come out of the sequencer itself (`audioDiag().onsets`), so what is
   * measured is the code that plays and not a model of it.
   */
  {
    const { audioDiag: diag } = await import('/src/core/audio.js');
    Sfx.resume();
    const runPass = (name, hurried) => {
      Music.stop();
      Music.current = null;
      Music.play(name);
      /* `play` primes the lookahead, so one or two steps are already scheduled
       * and counted before `setHurry` can be called — and those would be calm
       * steps inside the hurried tally, which is exactly the kind of off-by-two
       * that makes an exact claim into an approximate one. Stop the clock and
       * zero the counters, then drive the steps by hand. */
      if (Music._timer) { clearTimeout(Music._timer); Music._timer = null; }
      Music.setHurry(hurried);
      Music._onsets.clear();
      const dur = Music._stepDur;
      const t0 = (audioTap() ? audioTap().ctx.currentTime : 0) + 0.25;
      for (let s = 0; s < 32; s++) Music._emit(s, t0 + s * dur, false, dur);
      return { onsets: diag().onsets, doubling: diag().doubling, dur };
    };
    const calm = runPass('jaatie', false);
    const rush = runPass('jaatie', true);
    Music.stop();
    Music.current = null;
    const named = rush.doubling;
    const others = Object.keys(calm.onsets).filter((k) => k !== named);
    const doubled = calm.onsets[named] > 0
      && rush.onsets[named] === calm.onsets[named] * 2;
    const steady = others.length > 0
      && others.every((k) => rush.onsets[k] === calm.onsets[k]);
    const sameClock = Math.abs(rush.dur - calm.dur) < 1e-12;
    const show = (o) => Object.entries(o).map(([k, n]) => `${k} ${n}`).join(' ');
    expect('kaksinkertainen jako tihentää yhtä ääntä eikä liikuta pulssia',
      named !== 'none' && doubled && steady && sameClock,
      `tihennetty ${named}; rauhassa ${show(calm.onsets)}; kiireessä `
      + `${show(rush.onsets)}; askel ${(calm.dur * 1000).toFixed(3)} -> `
      + `${(rush.dur * 1000).toFixed(3)} ms`);
  }

  /*
   * 2. AND THE ARRANGEMENT'S OWN DOUBLE-TIME SECTION IS THE SAME MECHANISM.
   *
   * There were two speed-ups and only one of them was the clock's. The
   * `double time` variation used to carry `speed: 2`, which is the same fault
   * in the other half of the engine — and a fix that left it there would have
   * meant the owner still heard a tempo jump, just every tenth pass instead of
   * when the coins ran low. Section 7 of `SECTIONS` is that variation; landing
   * on it must change what `_doubling` answers and must not change `_stepDur`.
   */
  {
    const { audioDiag } = await import('/src/core/audio.js');
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('level');
    const plain = { step: Music._stepDur, label: Music.variation(), on: audioDiag().doubling };
    /* Cycle 12 is the first pass of section 7 (six sections of two passes
     * before it). Set the counter and re-apply rather than waiting for it. */
    Music._cycle = 12;
    Music._applyVariation();
    const geared = { step: Music._stepDur, label: Music.variation(), on: audioDiag().doubling };
    Music.stop();
    Music.current = null;
    expect('tuplatempo-osio tihentää yhden äänen eikä kiristä tempoa',
      /double time/.test(geared.label) && geared.on === 'lead'
      && plain.on === 'none' && Math.abs(geared.step - plain.step) < 1e-12,
      `${plain.label} (${plain.on}, ${(plain.step * 1000).toFixed(3)} ms) -> `
      + `${geared.label} (${geared.on}, ${(geared.step * 1000).toFixed(3)} ms)`);
  }

  /*
   * 3. EVERY TRACK NAMES A LINE IT CAN ACTUALLY SUBDIVIDE.
   *
   * `double` is a voice name, and the two ways to get it wrong are both silent:
   * name a voice the track does not have, and nothing happens; name one whose
   * notes are all single steps, and nothing happens either, because
   * `DOUBLE_MIN_LEN` skips them one at a time. Both look exactly like a track
   * that opted out — and opting out is legal (`jouset` does), which is what
   * makes the difference invisible without this.
   */
  {
    Sfx.resume();
    const bad = [];
    const rows = [];
    for (const name of Music.names()) {
      Music.stop();
      Music.current = null;
      Music.play(name);
      const track = Music._track;
      const named = track.double;
      if (named === undefined) { bad.push(`${name}: ei kenttää double`); continue; }
      if (named === null) { rows.push(`${name} —`); continue; }
      const voice = (Music._voices || []).find((v) => v.name === named);
      if (!voice) { bad.push(`${name}: double '${named}' ei ole ääni`); continue; }
      const long = voice.notes.filter((n) => n[0] !== null && n[1] >= 2).length;
      if (!long) bad.push(`${name}: ${named} ei sisällä yhtään jaettavaa nuottia`);
      rows.push(`${name} ${named}/${long}`);
    }
    Music.stop();
    Music.current = null;
    expect('jokainen raita nimeää äänen jonka se voi jakaa, tai kieltäytyy nimeltä',
      bad.length === 0, bad.join('; ') || rows.join(', '));
  }

  /*
   * 4. UUSI RAITA EI SAA OLLA ÄÄNEKKÄÄMPI KUIN VANHAT.
   *
   * Kuoleman ääni on tämän tiedoston mitattu katto (0,57; kolikko 0,32,
   * tehostus 0,60), eikä musiikki ole lähelläkään sitä — se kulkee `musicBus`in
   * kautta ja jokainen ääni on murto-osa. Se mikä *voi* mennä pieleen on
   * sisäinen: uusi raita kirjoitettuna kovemmaksi kuin yksikään vanha nousee
   * ääniefektien päälle ja pakottaa säätämään koko miksauksen.
   *
   * Siksi katto on **mitattu vanhoista raidoista**: `title` on suurin summa
   * (0,380 = 0,15 + 0,07 + 0,16) ja `level`in basso suurin yksittäinen ääni
   * (0,20). Kumpikaan luku ei ole makuasia vaan se mitä pelissä on jo ollut
   * kuukauden, ja kumpikin rikkoutuu yhdestä huolimattomasta nollasta.
   *
   * Summa eikä huippu, koska äänet soivat yhtä aikaa: kolme ääntä 0,15:llä on
   * kovempi kuin yksi 0,20:llä, ja juuri se on se tapa jolla raita hiipii yli
   * ilman että yksikään rivi näyttää väärältä.
   */
  {
    const SUM_MAX = 0.381;      // title, mitattu taulusta
    const ONE_MAX = 0.201;      // level/bass, mitattu taulusta
    Sfx.resume();
    const loud = [];
    const rows = [];
    for (const name of Music.names()) {
      Music.stop();
      Music.current = null;
      Music.play(name);
      const voices = Music._voices || [];
      const sum = voices.reduce((s, v) => s + (v.gain || 0), 0);
      const top = Math.max(0, ...voices.map((v) => v.gain || 0));
      rows.push(`${name} ${sum.toFixed(3)}`);
      if (sum > SUM_MAX) loud.push(`${name}: summa ${sum.toFixed(3)} > ${SUM_MAX}`);
      if (top > ONE_MAX) loud.push(`${name}: yksi ääni ${top.toFixed(3)} > ${ONE_MAX}`);
    }
    Music.stop();
    Music.current = null;
    expect('yksikään raita ei ole kirjoitettu kovemmaksi kuin kovin vanha raita',
      loud.length === 0, loud.join('; ') || rows.join(', '));
  }

  /*
   * 5. VALSSI — kolmijakoisuus ja **siirretty basso**.
   *
   * Kaksi väitettä ja molemmat ovat sellaisia jotka yksi nuotti rikkoo.
   *
   * Kolmijakoisuus on sama vaatimus kuin luulaaksolla ja samasta syystä:
   * sekvensserin tahti on kuusitoista askelta, joten valssi pysyy valssina vain
   * jos jokainen ääni ja jokainen rumpukuvio on kuuden monikerta.
   *
   * Siirretty basso on se joka erottaa tämän wieniläisvalssista, ja se on
   * kirjaimellisesti luettavissa: **yhtäkään bassonuottia ei ole tahdin
   * ykkösellä.** Yksikin pohja iskulle yksi ja um-pa-pa on takaisin — ei
   * rikkinäisenä vaan tavallisena, mikä on juuri se vika jota kukaan ei osaa
   * etsiä. Kolmantena: korotettu johtosävel (A#) soi tasan yhdessä soinnussa,
   * eli kadenssi on tapahtuma eikä väritys.
   */
  {
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('valssi');
    const track = Music._track;
    const lens = [
      ...(Music._voices || []).map((v) => `${v.name} ${v.len}`),
      ...(Music._phrases || []).map((p, i) => `fraasi${i} ${p.len}`),
      ...Object.entries(track.drums || {}).map(([k, p]) => `${k} ${p.length}`),
    ];
    const inThree = lens.length > 0
      && lens.every((s) => Number(s.split(' ')[1]) % 6 === 0);
    const bassVoice = (Music._voices || []).find((v) => v.name === 'bass');
    const onBeatOne = [...(bassVoice ? bassVoice.map.keys() : [])].filter((s) => s % 6 === 0);
    let leading = 0;
    for (const [semi] of (track.harm || {}).notes || []) {
      for (const s of Array.isArray(semi) ? semi : [semi]) {
        if (s !== null && ((s % 12) + 12) % 12 === 1) leading++;
      }
    }
    expect('valssi on kolmijakoinen ja sen basso on siirretty pois ykköseltä',
      inThree && bassVoice && onBeatOne.length === 0 && bassVoice.map.size === 16,
      `${lens.join(', ')}; bassonuotteja ${bassVoice ? bassVoice.map.size : 0}, `
      + `niistä ykkösellä ${onBeatOne.length}`);
    expect('valssin ainoa korotettu johtosävel on kadenssissa',
      leading === 1,
      `A#-säveliä säestyksessä ${leading} kpl`);
  }

  /*
   * 6. POLKKA — nopeus on rummuissa, kiinnostus on muualla.
   *
   * Kielletty asia on um-pa: pohja ykkösellä, sointu kakkosella, ikuisesti. Se
   * on juuri se kuvio joka tekee polkasta karaokea, ja sen poissaolo on
   * mitattavissa kahdesta paikasta.
   *
   *   - **Sointu ei ole koskaan iskulla.** Jokainen `harm`in isku osuu
   *     kuudestoistaosalle joka ei ole neljän monikerta, eli takapotkulle.
   *   - **Basso on linja eikä pumppu.** Yhdessäkään tahdissa ei soi samaa
   *     säveltä kahdesti. Um-pa-basso rikkoo tämän ensimmäisellä tahdilla.
   *
   * Ja moodi: matala septimi (G) soi ja johtosäveltä (G#) ei ole kertaakaan.
   * Yksi G# ja tämä on tavallinen A-duuri, mikä kuulostaisi vain
   * tavallisemmalta — sama vika kuin pilviraidan lyydisellä kvartilla.
   */
  {
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('polkka');
    const harm = (Music._voices || []).find((v) => v.name === 'harm');
    const bass = (Music._voices || []).find((v) => v.name === 'bass');
    const stabs = [...(harm ? harm.map.keys() : [])];
    const onBeat = stabs.filter((s) => s % 4 === 0);
    let repeats = 0;
    if (bass) {
      for (let bar = 0; bar < bass.len; bar += 8) {
        const seen = new Set();
        for (let s = bar; s < bar + 8; s++) {
          const note = bass.map.get(s);
          if (!note) continue;
          if (seen.has(note[0])) repeats++;
          seen.add(note[0]);
        }
      }
    }
    const pc = new Array(12).fill(0);
    for (const name of ['lead', 'harm', 'bass']) {
      const voice = (Music._track || {})[name];
      if (!voice) continue;
      for (const list of [voice.notes, ...(voice.phrases || [])]) {
        for (const [semi] of list) {
          if (semi === null || semi === undefined) continue;
          for (const s of Array.isArray(semi) ? semi : [semi]) pc[((s % 12) + 12) % 12]++;
        }
      }
    }
    Music.stop();
    Music.current = null;
    expect('polkan säestys ei ole um-pa: sointu on takapotkulla ja basso on linja',
      stabs.length === 8 && onBeat.length === 0 && repeats === 0,
      `${stabs.length} sointua, iskulla ${onBeat.length}, `
      + `bassossa toistoja tahdin sisällä ${repeats}`);
    expect('polkka on miksolyydinen: matala septimi soi, johtosäveltä ei ole',
      pc[10] >= 4 && pc[11] === 0,
      `G ${pc[10]} kertaa, G# ${pc[11]} kertaa`);
  }

  /*
   * 7. SEISKA — 7/8 on rakenne eikä maku.
   *
   * Kaksi asiaa, ja niistä jälkimmäinen on se joka tekee epäsymmetrisestä
   * tahtilajista musiikkia eikä laskuharjoitusta.
   *
   *   - **Kaikki on seitsemää ja sataakahtatoista.** Seitsemän ja kuusitoista
   *     sopivat yhteen vasta 112 askeleen kohdalla, joten yksikin ääni väärän
   *     mittaisena panee raidan vaeltamaan omaa sovitustaan vasten. Se
   *     kuulostaisi rikkinäiseltä, ei väärältä.
   *   - **Melodia on ryhmitelty 2+2+3.** Jokainen seitsemän askeleen tahti
   *     lyijyssä on tasan kolme nuottia, ja niiden pituudet ovat 2, 2 ja 3
   *     siinä järjestyksessä. Ilman tätä metri olisi vain rumpukuvio, ja rummut
   *     pudotetaan kahdessa osiossa kymmenestä.
   */
  {
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('seiska');
    const track = Music._track;
    const lens = [
      ...(Music._voices || []).map((v) => `${v.name} ${v.len}`),
      ...Object.entries(track.drums || {}).map(([k, p]) => `${k} ${p.length}`),
    ];
    const sevens = lens.every((s) => Number(s.split(' ')[1]) % 7 === 0);
    const loopOk = Music._loopLen === 112;
    const lead = track.lead.notes;
    const wrong = [];
    for (let i = 0; i < lead.length; i += 3) {
      const group = [lead[i], lead[i + 1], lead[i + 2]].map((n) => (n ? n[1] : '?'));
      if (group.join(',') !== '2,2,3') wrong.push(`tahti ${i / 3}: ${group.join('+')}`);
    }
    Music.stop();
    Music.current = null;
    expect('seiska on 7/8 ja pysyy siinä: kaikki pituudet ovat seitsemän monikertoja',
      sevens && loopOk, `${lens.join(', ')}; kierros ${Music._loopLen}`);
    expect('seiskan melodia on ryhmitelty 2+2+3 joka tahdissa',
      wrong.length === 0 && lead.length === 48,
      wrong.slice(0, 4).join('; ') || `${lead.length} nuottia, 16 tahtia, kaikki 2+2+3`);
  }

  /*
   * 8. KELLO — kolme jaksoa, ja ne kohtaavat kerran.
   *
   * "Jotain Saharan eteläpuolelta" tehdään yleensä asteikolla ja rummulla, ja
   * kumpikin on väärä puoli. Se mikä siirtyy on **arkkitehtuuri**: monta eri
   * mittaista jaksoa yhtä aikaa, jokainen yksinkertainen, ja yhdistelmä joka
   * kestää paljon kauemmin kuin yksikään osansa.
   *
   * Se on aritmetiikkaa ja siksi mitattavissa: kolmen äänen pituuksien pienin
   * yhteinen jaettava **on** kierros. Muuta yhtä jaksoa askeleella ja joko
   * teos hajoaa tai siitä tulee neljä kertaa pidempi, ja kumpikin näkyy tässä.
   *
   * Toinen väite koskee kelloa itseään: sen iskujen välit eivät ole
   * yhtäsuuria. Tasavälinen kello on metronomi, ja metronomi on täsmälleen se
   * asia jota vastaan koko rakenne on kirjoitettu.
   */
  {
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('kello');
    const byName = Object.fromEntries((Music._voices || []).map((v) => [v.name, v]));
    /*
     * The period of a written figure, measured rather than declared: the
     * smallest shift under which the voice's own note table is unchanged. It
     * has to be this and not `voice.len`, because every voice here is a whole
     * pass long (48) — what interlocks is the figure inside them, and a voice
     * whose figure had been edited would still add up to 48.
     */
    const periodOf = (voice) => {
      for (let p = 1; p <= voice.len; p++) {
        if (voice.len % p) continue;
        let same = true;
        for (const [at, note] of voice.map) {
          const other = voice.map.get((at + p) % voice.len);
          if (!other || JSON.stringify(other) !== JSON.stringify(note)) { same = false; break; }
        }
        if (same && voice.map.size % (voice.len / p) === 0) return p;
      }
      return voice.len;
    };
    const gcd = (a, b) => (b ? gcd(b, a % b) : a);
    const lcm = (a, b) => (a * b) / gcd(a, b);
    const bell = byName.comp;
    const hits = bell ? [...bell.map.keys()].filter((s) => s < 12).sort((a, b) => a - b) : [];
    const gaps = hits.map((s, i) => (i ? s - hits[i - 1] : s + 12 - hits[hits.length - 1]));
    const even = gaps.length > 0 && gaps.every((g) => g === gaps[0]);
    const periods = {
      comp: bell ? periodOf(bell) : 0,
      bass: byName.bass ? periodOf(byName.bass) : 0,
      hat: (Music._track.drums || {}).hat ? Music._track.drums.hat.length : 0,
    };
    const three = Object.values(periods);
    const meet = three.every((n) => n > 0) ? three.reduce((a, b) => lcm(a, b), 1) : 0;
    /* No two the same, and none a divisor of another: either would mean two of
     * the three come round together every time, which is one cycle wearing two
     * hats rather than two cycles. */
    const nested = three.some((a, i) => three.some((b, j) => i !== j && a % b === 0));
    Music.stop();
    Music.current = null;
    expect('kellon kolme jaksoa ovat eri mittaisia eivätkä kohtaa kierroksen sisällä',
      periods.comp === 12 && periods.bass === 8 && periods.hat === 5
      && !nested && meet === 120 && meet > Music._loopLen,
      `jaksot ${Object.entries(periods).map(([k, n]) => `${k} ${n}`).join(', ')}; `
      + `kohtaavat ${meet} askeleen välein, kierros ${Music._loopLen}`);
    expect('kellokuvio on epätasainen, eli kello eikä metronomi',
      hits.length === 5 && !even,
      `iskut ${hits.join(' ')}, välit ${gaps.join(' ')}`);
  }

  /*
   * 9. MAKAM — asteikko joka ei ole sama ylös ja alas, ja se sävel jota ei ole.
   *
   * Kielletty asia on ylinouseva sekunti, eli se 1800-luvun eurooppalainen
   * lyhennysmerkki jolla "itämainen" yleensä tehdään. Sen tilalla on kaksi
   * asiaa jotka ovat maqamissa oikeasti rakennetta:
   *
   *   - **Sama sävelaskel eri suuntiin eri korkeudella.** Bayati nousee
   *     H:n kautta ja laskee B:n kautta, eli kuudes aste riippuu siitä minne
   *     ollaan menossa. Datassa se on tämä: jokaista H:ta seuraa korkeampi
   *     sävel ja jokaista B:tä matalampi. Kirjoita asteikko asteikkona ja tämä
   *     kaatuu — mikä on koko ero.
   *   - **Toinen aste ei ole puolisävelaskel eikä kokosävelaskel.** Se on
   *     niiden välissä, ja se on pelin ensimmäinen mikrointervalli. Portti
   *     vaatii että `cents`-merkki on olemassa, että se on 50 ja että sitä
   *     kantaa **vain** toinen aste — merkki muualla olisi epävire eikä maqam.
   */
  {
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('makam');
    const lead = Music._track.lead;
    const notes = lead.notes;
    const FLAT_SIX = 1;        // B flat, a semitone above A
    const NAT_SIX = 2;         // B natural
    const bad = [];
    let ups = 0;
    let downs = 0;
    for (let i = 0; i < notes.length; i++) {
      const [semi] = notes[i];
      const next = notes[i + 1];
      if (semi === NAT_SIX) {
        ups++;
        if (!next || next[0] <= semi) bad.push(`H @${i} ei jatka ylöspäin`);
      }
      if (semi === FLAT_SIX) {
        downs++;
        if (!next || next[0] >= semi) bad.push(`B @${i} ei jatka alaspäin`);
      }
    }
    const marked = notes.filter((n) => n[2] === 'n');
    const second = marked.every((n) => n[0] === -6);
    const cents = ((lead.marks || {}).n || {}).cents;
    Music.stop();
    Music.current = null;
    expect('makam nousee ja laskee eri säveliä pitkin',
      ups > 0 && downs > 0 && bad.length === 0,
      bad.join('; ') || `nousevia H ${ups}, laskevia B ${downs}`);
    expect('makamin toinen aste on neutraali sekunti, eikä mikään muu sävel ole',
      cents === 50 && marked.length >= 3 && second,
      `${marked.length} merkittyä nuottia, viritys ${cents} senttiä, `
      + `kaikki toisella asteella ${second}`);
  }

  /*
   * 10. JOUSET — kaanon, tintinnabuli ja se että kaari lähtee nuotista.
   *
   * Omistaja pyysi tätä nimeltä ("dramatic strings with bends, like gorecki"),
   * ja kolme kohtaa siitä pussista on sellaisia jotka joko ovat datassa tai
   * eivät ole olemassa.
   *
   *   - **Kaanon.** `harm` on sama linja tahtia myöhemmin ja kvinttiä alempaa.
   *     Portti lukee molempien käännetyt nuottitaulut ja vaatii että jokainen
   *     harmonian nuotti on lyijyn nuotti kuusitoista askelta aiemmin, seitsemän
   *     puolisävelaskelta alempana. Kaanon jonka toinen ääni ei ole sama linja
   *     on sointukierto jolla on tarina.
   *   - **Tintinnabuli.** `comp` soittaa **vain** toonikakolmisoinnun säveliä.
   *     Yksi neljäs sävel ja Pärtin temppu on pelkkä säestys.
   *   - **Kaari lähtee nuotista.** Uusi `bend`-kenttä on koko syy tämän raidan
   *     olemassaoloon, ja siitä on kaksi kokoa: puolisävelaskel ja
   *     **neljännessävelaskel**, jolla ei ole mihin laskeutua. Portti vaatii
   *     että molemmat ovat käytössä oikeasti eivätkä vain taulussa.
   *
   * Ja se mitä raidassa **ei** ole: yhtään terssiä bassossa. Avoin kvintti
   * kantaa sekä valituksen että aamun, mikä on sama ratkaisu kuin
   * `autiovuori`ssa ja samasta syystä — sama säestys soi kahden vastakkaisen
   * ruudun alla (peli ohi / lopputekstit).
   */
  {
    Sfx.resume();
    Music.stop();
    Music.current = null;
    Music.play('jouset');
    const track = Music._track;
    const byName = Object.fromEntries((Music._voices || []).map((v) => [v.name, v]));
    const lead = byName.lead;
    const harm = byName.harm;
    const off = [];
    if (lead && harm) {
      for (const [at, note] of harm.map) {
        const src = lead.map.get(at - 16);
        if (!src) { off.push(`@${at}: lyijyllä ei ole nuottia @${at - 16}`); continue; }
        if (note[0] !== src[0] - 7) off.push(`@${at}: ${note[0]} vs ${src[0]} - 7`);
      }
    }
    const TRIAD = [0, 3, 7];
    const strays = ((track.comp || {}).notes || [])
      .filter(([s]) => s !== null && !TRIAD.includes(((s % 12) + 12) % 12));
    let thirds = 0;
    for (const [semi] of (track.bass || {}).notes || []) {
      for (const s of Array.isArray(semi) ? semi : [semi]) {
        const p = ((s % 12) + 12) % 12;
        if (p === 3 || p === 4) thirds++;
      }
    }
    const marks = (track.lead || {}).marks || {};
    const bends = new Set();
    for (const list of [track.lead.notes, ...(track.lead.phrases || [])]) {
      for (const [, , mark] of list) {
        if (mark && marks[mark] && marks[mark].bend) bends.add(marks[mark].bend);
      }
    }
    Music.stop();
    Music.current = null;
    expect('jousten toinen ääni on sama linja tahtia myöhemmin ja kvinttiä alempaa',
      harm && harm.map.size >= 6 && off.length === 0,
      off.slice(0, 3).join('; ') || `${harm ? harm.map.size : 0} nuottia kaanonissa`);
    expect('jousten tintinnabuli soittaa vain toonikakolmisoinnun säveliä',
      strays.length === 0 && ((track.comp || {}).notes || []).length >= 6,
      strays.map(([s]) => s).join(' ') || `${((track.comp || {}).notes || []).length} nuottia, `
      + `kaikki A C E; bassossa terssejä ${thirds}`);
    expect('jousten kaaret lähtevät nuotista, ja toinen niistä on neljännessävelaskel',
      bends.has(-1) && bends.has(-0.5) && thirds === 0,
      `käytetyt kaaret ${[...bends].sort().join(' ')} puolisävelaskelta, `
      + `bassossa terssejä ${thirds}`);
  }

  /* ------------------------------ rendering ---------------------------- */
  {
    const { drawBackdrop } = await import('/src/gfx/backdrop.js');
    const { drawTile, THEMES, T } = await import('/src/gfx/tiles.js');
    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 208;
    const g = canvas.getContext('2d');

    // A backdrop that throws, or comes out as a flat wash, is a regression.
    const shot = (bg, theme, camX, tick) => {
      g.clearRect(0, 0, 320, 208);
      drawBackdrop(g, bg, theme, camX, 320, 208, tick);
      return g.getImageData(0, 0, 320, 208).data;
    };
    const badBg = [];
    for (const theme of Object.keys(THEMES)) {
      for (const bg of ['hills', 'dunes', 'peaks', 'bones', 'clouds', 'factory', 'none']) {
        try {
          const near = shot(bg, theme, 0, 24);
          const far = shot(bg, theme, 640, 24);
          const seen = new Set();
          let moved = 0;
          for (let i = 0; i < near.length; i += 4 * 89) {
            seen.add((near[i] << 16) | (near[i + 1] << 8) | near[i + 2]);
            if (near[i] !== far[i] || near[i + 1] !== far[i + 1]) moved++;
          }
          if (seen.size < 5) badBg.push(`${theme}/${bg} flat`);
          if (moved < 8) badBg.push(`${theme}/${bg} does not parallax`);
        } catch (err) {
          badBg.push(`${theme}/${bg}: ${err.message}`);
        }
      }
    }
    expect('every backdrop renders with detail and parallax', badBg.length === 0, badBg.join(' '));

    const badTile = [];
    const chars = Object.values(T).filter((ch) => ch !== ' ');
    for (const theme of Object.keys(THEMES)) {
      for (const ch of chars) {
        try {
          for (const t of [0, 44]) {
            drawTile(g, ch, 0, 16, theme, 3, 5, t, ' ', { doorOpen: true });
            drawTile(g, ch, 0, 16, theme, 4, 5, t, '#', { doorOpen: false });
          }
        } catch (err) {
          badTile.push(`${theme}/${ch}: ${err.message}`);
        }
      }
    }
    expect('every tile type draws in every theme', badTile.length === 0, badTile.join(' '));

    /*
     * Ja teeman ruutujen pitää erottua TOISISTAAN, ei vain piirtyä.
     *
     * Tämä on se puolisko jonka jäljelle jäi kun teemakohtaiset ruutumuodot
     * peruttiin (ROADMAP, ✘ 9.8.2026): jos siluetti on kaikissa maailmoissa
     * sama, koko ero on materiaalissa ja värissä — ja silloin väri on
     * mekaniikkaa eikä koristetta. Tiili hajoaa ja maa ei, joten pelaajan on
     * nähtävä kumpi on kumpi yhdellä silmäyksellä.
     *
     * Mitta on kanavakohtainen keskiero täydestä 255:stä, mikä on karkea mutta
     * rikkomaton: se ei osaa sanoa mitään muodosta, ja juuri siksi se mittaa
     * sitä yhtä asiaa joka teemasta toiseen muuttuu.
     *
     * **Mitattu ennen kuin luuteemaa oli olemassa**, ja luku kannattaa lukea:
     * ruoho 9,3 %, aavikko 8,6 %, yö **0,4 %**, jää 22,3 %, tehdas 17,9 %,
     * linnake 7,9 %. Yön tiili ja yön maa olivat siis käytännössä sama väri —
     * `#7a5a30` vastaan `#6a5030` — eli 2-N:ssä rikottava lohko sulautui
     * maahan. Se oli pitkään löydös eikä korjattava, koska yön paletin
     * muuttaminen muuttaa valmiin kentän ulkonäön; omistaja päätti sen
     * erikseen, ja korjaus on **tiilessä eikä maassa** (ks. oma kohtansa alla).
     *
     * Siksi väite on se jonka tämä työ omistaa ja joka on rikottavissa:
     * **luumaailman pari on koko pelin selvin.** Ei "riittävän hyvä" vaan
     * mitattuna paras, koska sen maa on luuta ja sen tiili hautamultaa — kaksi
     * eri ainetta eikä saman aineen kaksi sävyä. Kynnyksenä on nykyinen paras
     * (jää), joten tämä ei voi mennä läpi vahingossa.
     */
    {
      const meanOf = (ch, theme) => {
        g.clearRect(0, 0, 320, 208);
        drawTile(g, ch, 0, 16, theme, 3, 5, 0, ' ', {});
        const d = g.getImageData(0, 16, 16, 16).data;
        let r = 0; let gg = 0; let b = 0; let n = 0;
        for (let q = 0; q < d.length; q += 4) {
          if (d[q + 3] < 8) continue;
          r += d[q]; gg += d[q + 1]; b += d[q + 2]; n++;
        }
        return n ? [r / n, gg / n, b / n] : null;
      };
      const gapOf = (theme) => {
        const a = meanOf(T.GROUND, theme);
        const b = meanOf(T.BRICK, theme);
        if (!a || !b) return 0;
        return ((Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2])) / 3 / 255)
          * 100;
      };
      const gaps = Object.keys(THEMES).map((theme) => ({ theme, gap: gapOf(theme) }));
      const others = gaps.filter((x) => x.theme !== 'bone');
      const worst = others.reduce((m, x) => (x.gap < m.gap ? x : m), others[0]);
      const best = others.reduce((m, x) => (x.gap > m.gap ? x : m), others[0]);
      const bone = gaps.find((x) => x.theme === 'bone');
      expect('luumaailman tiili ja maa erottuvat selvemmin kuin minkään muun teeman',
        !!bone && bone.gap > best.gap,
        `${gaps.map((x) => `${x.theme} ${x.gap.toFixed(1)} %`).join(', ')}`
        + ` — muista paras ${best.theme}, huonoin ${worst.theme}`);

      /*
       * Ja juoksuhiekan pitää erottua siitä maasta johon se on kaivettu.
       *
       * Kynnys ei ole makuasia vaan sama mitta yhtä askelta tiukempana: aavikon
       * oma maa/tiili-pari on 8,6 %, ja se on pelin heikoimpia — tiedossa oleva
       * ongelma, ei tavoite. Uhka jota ei tunnista ensi silmäyksellä on juuri se
       * laji jota tässä pelissä ei saa olla (sama sääntö kuin piikkien
       * varoitusraidalla), joten hiekan ja maan eron on oltava suurempi kuin
       * tuon parin. Toinen puolisko on ettei se saa lukea laavana: kaksi
       * samanlaista signaalia opettaa väärän lukutavan.
       */
      const sandGap = gapOf('desert');
      const quick = meanOf(T.QUICKSAND, 'desert');
      const ground = meanOf(T.GROUND, 'desert');
      const lava = meanOf(T.LAVA, 'desert');
      const sep = (a, b) => (!a || !b ? 0
        : ((Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2])) / 3 / 255) * 100);
      const vsGround = sep(quick, ground);
      const vsLava = sep(quick, lava);
      expect('juoksuhiekka erottuu aavikon maasta selvemmin kuin maa erottuu tiilestä',
        !!quick && vsGround > sandGap && vsLava > sandGap,
        `hiekka vs maa ${vsGround.toFixed(1)} %, hiekka vs laava ${vsLava.toFixed(1)} %, `
        + `aavikon maa vs tiili ${sandGap.toFixed(1)} %`);

      /*
       * JÄÄ, JA MIKSI SEN KYNNYS ON JOKA TEEMASSA EIKÄ YHDESSÄ.
       *
       * Juoksuhiekka on aavikon asia ja se mitataan aavikkoa vasten. Jää ei ole
       * minkään maailman asia: se on laatta jonka saa ladota mihin tahansa, ja
       * juuri se on koko syy siihen että se on laatta eikä teema. Siksi ehto on
       * kaikki kahdeksan teemaa kertaa neljä naapuria, ja **huonoin luku on se
       * joka ratkaisee**.
       *
       * Kynnys 17 % on sama luku ja sama perustelu kuin yön tiilellä: kaksi
       * kertaa pelin heikoin selviytynyt pari. Se ei ole makuasia vaan
       * kalibrointi jonka tämä tiedosto on jo kerran tehnyt.
       *
       * **Ja tämä testi löysi oikean vian.** Ensimmäinen jää oli vaaleansinistä
       * ja mitattiin jäämaailman omaa maata vastaan **2,7 %** — huonompi kuin yön
       * tiili ennen korjaustaan, ja tasan siinä maailmassa johon ensiesittely oli
       * juuri sijoitettu. Silmällä katsottuna se näytti hyvältä. Toinen löytö oli
       * pahempi ja tuli vasta kun halkeama otettiin mukaan: **jää vs. halkeama
       * 14,8 %**, eli turvallinen laatta ja tappava laatta jakoivat saman
       * vaalean yläreunan. Nykyinen turkoosi on kummankin mittauksen tulos.
       */
      const iceThemes = Object.keys(THEMES).map((theme) => {
        const ice = meanOf(T.ICE, theme);
        return {
          theme,
          ground: sep(ice, meanOf(T.GROUND, theme)),
          hard: sep(ice, meanOf(T.HARD, theme)),
          lava: sep(ice, meanOf(T.LAVA, theme)),
          spike: sep(ice, meanOf(T.SPIKE, theme)),
        };
      });
      const iceWorst = iceThemes.reduce((worst, t) => {
        const low = Math.min(t.ground, t.hard, t.lava, t.spike);
        return !worst || low < worst.low ? { theme: t.theme, low, t } : worst;
      }, null);
      expect('jää erottuu joka teemassa maasta, kovasta palikasta ja tappavista',
        !!iceWorst && iceWorst.low >= 17,
        iceWorst
          ? `huonoin ${iceWorst.theme} ${iceWorst.low.toFixed(1)} %, kynnys 17 % — `
            + `maa ${iceWorst.t.ground.toFixed(1)}, kova ${iceWorst.t.hard.toFixed(1)}, `
            + `laava/halkeama ${iceWorst.t.lava.toFixed(1)}, piikki ${iceWorst.t.spike.toFixed(1)}`
          : 'jäälaattaa ei saatu piirrettyä');

      /*
       * Ja pilviteema on juuri se teema joka tämän testin kuuluisi kaataa.
       *
       * Valkoista valkoisella on koko maailman lähtökohta, ja se on samalla se
       * tapa jolla teema epäonnistuisi hiljaa: rikottava lohko sulaisi maahan
       * kuten yössä (0,4 %), eikä kukaan huomaisi ennen kuin joku juoksisi
       * kentän läpi ja ihmettelisi minne palikat katosivat. Siksi tässä
       * maailmassa maa ja tiili ovat **kaksi eri pilveä**: pohjapilvi on
       * auringon puolelta valaistua, tiili on ukkospilveä. Kynnys 25 % on
       * korkeampi kuin yhdelläkään ennen luumaailmaa toimitetulla teemalla,
       * eli se ei mene läpi vahingossa — ja luumaailman oma väite yllä pitää
       * huolen ylärajasta, koska se vaatii olevansa koko pelin selvin pari.
       */
      const cloud = gaps.find((x) => x.theme === 'cloud');
      expect('pilvimaailman tiili erottuu maasta vaikka molemmat ovat pilveä',
        !!cloud && cloud.gap >= 25,
        cloud ? `pilvi ${cloud.gap.toFixed(1)} %, kynnys 25 % — jää ${
          (gaps.find((x) => x.theme === 'ice') || {}).gap.toFixed(1)} %, yö ${
          (gaps.find((x) => x.theme === 'night') || {}).gap.toFixed(1)} %`
          : 'ei pilviteemaa lainkaan');

      /*
       * JA YÖ. Pelin heikoin pari, 0,4 %, ja koko päivän tiedossa ollut ongelma:
       * `#7a5a30` tiiltä `#6a5030` maata vasten on kaksi nimeä samalle ruskealle,
       * eli 2-N:n rikottava lohko on käytännössä näkymätön. Se on ehtinyt ohjata
       * kahta suunnittelupäätöstä — juoksuhiekka jätettiin pois 2-N:stä ja
       * pilviteema rakennettiin 25 %:n kynnykseen juuri ettei tämä toistuisi.
       *
       * **Omistaja päätti että tiili vaalenee ja maa jää.** Se on tärkeä puoli:
       * 2-N:n lattia näyttää tämän jälkeen täsmälleen siltä miltä ennenkin.
       *
       * Kynnys on 17 %, ja se on **kaksi kertaa pelin heikoin selviytynyt pari**
       * (aavikko 8,6 %). Se ei ole jään 22,3 % eikä sitä yritetäkään: jään koko
       * paletti asuu luminanssivälillä 145–224, eli sillä on 80 tasoa
       * liikkumavaraa, kun taas yön paletti on tarkoituksella puristettu pimeään
       * päähän — ja juuri se puristus **on** se mikä tekee yöstä yön. Kynnys ei
       * myöskään ole "hiukan yli nykyisen": se on lähellä sitä maksimia jonka
       * paletti antaa alla olevan pimeysehdon vallitessa, ja mitattu paras
       * puumainen sävy sen alla oli 19,2 %.
       */
      const night = gaps.find((x) => x.theme === 'night');
      expect('yön tiili erottuu yön omasta maasta',
        !!night && night.gap >= 17,
        night ? `yö ${night.gap.toFixed(1)} %, kynnys 17 % = 2 × aavikko `
          + `(${(gaps.find((x) => x.theme === 'desert') || {}).gap.toFixed(1)} %) `
          + `— ennen korjausta 0,4 %` : 'ei yöteemaa lainkaan');

      /*
       * Ja tässä on se puolisko joka estää helpon vastauksen.
       *
       * Vaalentamisella on raja, ja ilman rajaa tämän testin voisi läpäistä
       * maalaamalla yön tiilen niin kirkkaaksi että se hehkuu sisältäpäin — yksi
       * bugi vaihdettuna toiseen. Raja on mitattu eikä keksitty: **kova palikka
       * on jokaisen kahdeksan teeman kirkkain kiinteä ruutu**, maata ja tiiltä
       * myöten (mitattuna luminanssina ruoho 192,3 / 99,5 / 105,6; aavikko
       * 186,7 / 166,2 / 141,0; yö 133,1 / 86,6; jää 224,3; tehdas 162,5;
       * luu 211,0; pilvi 232,6; linnake 171,0).
       *
       * Se on kaksi asiaa yhdessä. Fysiikan puolella kova palikka on se pinta
       * jonka taivas valaisee kirkkaimmin, joten mikä tahansa sitä kirkkaampi
       * ruutu tekee valonsa itse — juuri se on "hehkuu sisältäpäin" mitattuna.
       * Luettavuuden puolella se on opittu merkki: **kirkkain on se jota ei voi
       * rikkoa.** Yksi teema joka kääntää sen nurin opettaa väärän lukutavan
       * kaikkien muiden jäljiltä.
       *
       * Väite koskee kaikkia teemoja eikä vain yötä, koska sääntö on koko pelin
       * eikä yhden korjauksen — ja koska juuri niin se pysyy voimassa myös
       * seuraavan paletin kohdalla.
       */
      const lumOf = (ch, theme) => {
        const m = meanOf(ch, theme);
        return m ? 0.299 * m[0] + 0.587 * m[1] + 0.114 * m[2] : 0;
      };
      const lit = Object.keys(THEMES).map((theme) => ({
        theme,
        hard: lumOf(T.HARD, theme),
        ground: lumOf(T.GROUND, theme),
        brick: lumOf(T.BRICK, theme),
      }));
      const glowing = lit.filter((x) => x.hard <= x.brick || x.hard <= x.ground);
      const nightLit = lit.find((x) => x.theme === 'night');
      expect('kova palikka on jokaisen teeman kirkkain kiinteä ruutu',
        glowing.length === 0,
        `${lit.map((x) => `${x.theme} ${x.hard.toFixed(0)}/${x.ground.toFixed(0)}/`
          + `${x.brick.toFixed(0)}`).join(', ')} (kova/maa/tiili)`
        + (nightLit ? ` — yön tiilelle jää ${(nightLit.hard - nightLit.brick).toFixed(1)} `
          + 'luminanssia pelivaraa' : ''));
    }

    /* A pipe that goes up has to look like it goes up, or the rule `tryWarp`
     * enforces is invisible and the warp reads as broken. The tile knows from
     * the neighbour it is already handed: pipe overhead means this mouth is the
     * bottom end of something hanging, so it is drawn mirrored. Asserted as the
     * mirror rather than as "different", because "different" would also pass if
     * the two were merely two shades of the same wrong picture. */
    {
      const px = (d, x, y) => (d[(y * 320 + x) * 4] << 16) | (d[(y * 320 + x) * 4 + 1] << 8)
        | d[(y * 320 + x) * 4 + 2];
      const tile = (above) => {
        g.clearRect(0, 0, 320, 208);
        drawTile(g, '(', 0, 0, 'factory', 3, 5, 0, above, {});
        drawTile(g, ')', 16, 0, 'factory', 4, 5, 0, above, {});
        return g.getImageData(0, 0, 320, 208).data;
      };
      const floor = tile(' ');
      const ceiling = tile('{');
      let mirrored = 0;
      let same = 0;
      for (let x = 0; x < 32; x++) {
        for (let y = 0; y < 16; y++) {
          if (px(floor, x, y) === px(ceiling, x, 15 - y)) mirrored++;
          if (px(floor, x, y) === px(ceiling, x, y)) same++;
        }
      }
      expect('a pipe hanging from the ceiling is drawn the other way up',
        mirrored === 512 && same < 512,
        `peilattuja ${mirrored}/512, samoja ${same}/512`);
    }

    /* Sprites now tint and glow, and glowing means switching the composite mode
     * mid-draw. One that is not switched back corrupts every tile drawn after
     * it, which looks like a graphics bug rather than a leak — so this is
     * asserted the same way the post-processing pass is. */
    {
      const sprites = await import('/src/gfx/sprites.js');
      g.globalCompositeOperation = 'source-over';
      g.globalAlpha = 1;
      const leaks = [];
      const check = (what) => {
        if (g.globalCompositeOperation !== 'source-over') leaks.push(`${what}: ${g.globalCompositeOperation}`);
        if (g.globalAlpha !== 1) leaks.push(`${what}: alpha ${g.globalAlpha}`);
        g.globalCompositeOperation = 'source-over';
        g.globalAlpha = 1;
      };
      for (const kind of ['shroom', 'flower', 'leaf', 'soup', 'star', 'pop']) {
        sprites.drawItem(g, kind, 20, 20, 30);
        check(`item ${kind}`);
      }
      // Both halves of the bean: falling, and once it is a stalk.
      for (const bare of [true, false]) {
        sprites.drawSprout(g, 20, 20, 30, bare);
        check(`sprout ${bare ? 'bare' : 'grown'}`);
      }
      const { TINTS } = sprites;
      for (const level of [0, 1, 3, 5]) {
        for (const tint of [null, TINTS && TINTS.frozen, TINTS && TINTS.flash]) {
          sprites.drawPlayer(g, 20, 20, {
            type: 'leaf', level, facing: 1, state: 'walk', frame: 1, tick: 12, tint,
          });
          check(`player ${level}${tint ? ' tinted' : ''}`);
        }
      }
      // The star draws the whole player a second time, additively — the most
      // likely place for a composite mode to escape.
      for (const t of (sprites.STAR_TINTS || [])) {
        sprites.drawPlayer(g, 20, 20, {
          type: 'leaf', level: 5, facing: 1, state: 'walk', frame: 1, tick: 12,
          tint: t, glow: sprites.GLOWS && sprites.GLOWS.star,
        });
        check('player starred');
      }
      for (const out of [0, 0.3, 1]) {
        sprites.drawSpines(g, 20, 40, 30, out, 12);
        check(`spines ${out}`);
      }
      sprites.drawSpikeGuy(g, 20, 40, 7, -1);
      check('spikeguy');
      // The sun's wake and its wind-up halo are both additive, which is the
      // one thing in this file that switches the composite mode mid-sprite.
      {
        const trail = [];
        for (let i = 0; i < 14; i++) trail.push({ x: 20 + i * 3, y: 40 + i, life: 26 - i });
        for (const wind of [0, 0.4, 0.9, 1]) {
          sprites.drawAngrySun(g, 20, 40, 12, wind > 0.9, false, { trail, windUp: wind });
          check(`angrysun ${wind}`);
        }
        sprites.drawAngrySun(g, 20, 40, 12, false, true);
        check('angrysun bare');
      }
      if (sprites.drawBeanBaron) {
        for (const wind of [0, 0.5, 1]) {
          sprites.drawBeanBaron(g, 20, 40, 12, -1, wind, false);
          check(`beanbaron ${wind}`);
        }
        sprites.drawBeanBomb(g, 20, 40, 12);
        check('beanbomb');
      }
      // Neljä uutta, ladattuina ja lataamattomina: `charge`-haarat ovat niitä
      // joissa piirto vaihtaa väriä kesken sprite, eli juuri niitä joissa
      // composite-tila voi jäädä auki.
      for (const c of [0, 1]) {
        sprites.drawTorvi(g, 20, 40, 12, 1, c);
        check(`torvi ${c}`);
        sprites.drawPaarma(g, 20, 40, 12, -1, c);
        check(`paarma ${c}`);
        sprites.drawYokki(g, 20, 40, 12, 1, c);
        check(`yökki ${c}`);
        sprites.drawPaukkupoho(g, 20, 40, 12, -1, c);
        check(`paukkupöhö ${c}`);
      }
      sprites.drawTorahdys(g, 20, 40, 12, 1);
      check('törähdys');
      sprites.drawKarvapallo(g, 20, 40, 12, 1);
      check('karvapallo');
      sprites.drawPisara(g, 20, 40, 12);
      check('happopisara');
      /* Kaikki seitsemän, ei viisi. Lista oli `[0,1,2,3,4]` siihen asti kun
       * pomot piirrettiin uusiksi, eli sääherra ja kuningas — ne kaksi jotka
       * tulivat viimeisenä ja joita kukaan ei ollut katsonut — olivat ainoat
       * joiden piirtoa tämä ei koskaan ajanut. */
      for (const v of [0, 1, 2, 3, 4, 5, 6]) {
        sprites.drawBoss(g, 20, 40, 12, 1, false, v, 1, 1);
        check(`boss ${v} spiny`);
      }
      // Kurnuttajan varoituskupla on läpikuultava, eli se koskee globalAlphaan.
      if (sprites.drawKurnuttaja) {
        sprites.drawKurnuttaja(g, 20, 40, 12, -1);
        check('kurnuttaja');
        for (const t of [0.01, 0.5, 1]) {
          sprites.drawCroak(g, 20, 56, t, 12);
          check(`kurnutus ${t}`);
        }
      }
      expect('drawing a sprite leaves the canvas state as it found it',
        leaks.length === 0, leaks.join(', '));

      /*
       * JOKAINEN POMO ON OMAN MUOTOINEN, JA SE MITATAAN VÄRIT POIS OTETTUINA.
       *
       * Pomot olivat vuoteen asti yksi piirros ja seitsemän väriä: sama neliöpää,
       * sama silmäpari, sama suu, samat valkoiset kädet, ja erona hattu ja sävy.
       * Sen huomasi vasta kun ne pani vierekkäin — eli juuri sellainen vika jota
       * silmä ei löydä koodia lukemalla, ja jota mikään portti ei kysynyt.
       *
       * Väite on siksi **siluetista eikä väristä**: jokainen pomo piirretään
       * läpinäkyvälle pohjalle, alfa pelkistetään maskiksi, ja jokainen pari
       * verrataan leikkaus/yhdiste-suhteella. Väri ei osallistu mittaukseen
       * lainkaan, koska väri on se puolustus jonka takana vanha muoto piileskeli
       * — ja koska pelaaja lukee hahmon muodosta ennen kuin ehtii lukea sävyn.
       *
       * Kynnys 0,82. Mitattu pahin pari on nyrkkeilijä vs. pöhö **0,771**, eli
       * varaa on 0,05; vanha jaettu vartalo olisi ollut lähellä ykköstä, joten
       * tämä ei ole raja joka menee läpi vahingossa. Jos joku joskus piirtää
       * kaksi pomoa samasta rungosta, tämä kaatuu ennen kuin se on kentässä.
       */
      {
        /* Kehys mitoitetaan `BOSS_SIZES`ista eikä kirjoiteta käsin, ja se on
         * korjaus eikä siistiminen: tässä luki `W = 40, H = 40` siltä ajalta
         * jolloin jokainen pomo oli 30x32. Kun koot erosivat, 68 leveä sääherra
         * **rajautui 36 pikseliin** ja 52 korkea kuningas katkesi — eli portti
         * vertaili typistettyjä siluetteja ja piti niitä kokonaisina. Se meni
         * läpi, mikä on juuri se tapa jolla tällainen vika jää huomaamatta. */
        const PAD = 4;
        const W = Math.max(...sprites.BOSS_SIZES.map((b) => b.w)) + PAD * 2;
        const H = Math.max(...sprites.BOSS_SIZES.map((b) => b.h)) + PAD * 2;
        const maskOf = (v) => {
          const c = document.createElement('canvas');
          c.width = W;
          c.height = H;
          const gg = c.getContext('2d');
          sprites.drawBoss(gg, PAD, PAD, 12, 1, false, v, 1, 0);
          const d = gg.getImageData(0, 0, W, H).data;
          const m = new Uint8Array(W * H);
          for (let i = 0; i < W * H; i++) m[i] = d[i * 4 + 3] > 8 ? 1 : 0;
          return m;
        };
        const masks = [0, 1, 2, 3, 4, 5, 6].map(maskOf);
        let worst = { a: -1, b: -1, iou: 0 };
        for (let a = 0; a < masks.length; a++) {
          for (let b = a + 1; b < masks.length; b++) {
            let inter = 0;
            let uni = 0;
            for (let i = 0; i < W * H; i++) {
              const x = masks[a][i];
              const y = masks[b][i];
              if (x && y) inter++;
              if (x || y) uni++;
            }
            const iou = uni ? inter / uni : 1;
            if (iou > worst.iou) worst = { a, b, iou };
          }
        }
        const empty = masks.findIndex((m) => m.reduce((s, v) => s + v, 0) < 100);
        expect('jokainen pomo on oman muotoinen, väri pois otettuna',
          empty < 0 && worst.iou < 0.82,
          empty >= 0
            ? `pomo ${empty} on käytännössä tyhjä — piirto ei tuottanut siluettia`
            : `pahin pari ${worst.a} vs ${worst.b}: ${worst.iou.toFixed(3)}, kynnys 0,82`);

        /*
         * JA SE MITÄ ERILAISUUS EI TODISTA: ETTÄ MUOTO ON HAHMON MUOTO.
         *
         * Yllä oleva portti vertaa pomoja toisiinsa, ja seitsemän erilaista
         * huonekalua läpäisee sen vaivatta. Väriltä riisuttuna ne olivatkin
         * mäki, veturi, muna, läiskä ja porttikäytävä — ja jokainen niistä oli
         * eri muotoinen kuin muut. Ero ei ole luettavuus.
         *
         * Yhteinen vika oli viidessä seitsemästä sama: **päätä ei ollut
         * siluetissa.** Se oli piirretty vartalon ääriviivan sisään ja merkitty
         * värillä, ja väri on ensimmäinen asia joka katoaa siltä etäisyydeltä
         * jolta tätä peliä pelataan.
         *
         * Portti lukee kunkin pomon oman `BOSS_PLANS`-ilmoituksen ja mittaa
         * juuri sen väitteen. Ilmoitus on datana `boss.js`:ssä, koska portin
         * oma kopio siitä vanhenee — kaksi muuta vakiota tässä samassa
         * tiedostossa vanheni jo tällä viikolla.
         */
        const shape = (mask) => {
          const rows = [];
          for (let y = 0; y < H; y++) {
            let n = 0;
            for (let x = 0; x < W; x++) n += mask[y * W + x];
            rows.push(n);
          }
          const first = rows.findIndex((n) => n > 0);
          const last = rows.length - 1 - [...rows].reverse().findIndex((n) => n > 0);
          const widths = rows.slice(first, last + 1);
          const maxW = Math.max(...widths);
          const area = widths.reduce((a, b) => a + b, 0);
          let cy = 0;
          widths.forEach((n, y) => { cy += n * y; });
          cy = area ? cy / area : 0;

          // notch: the deepest pinch in the top 60 % — a neck, in other words.
          let notch = 1;
          for (let y = 1; y < Math.floor(widths.length * 0.6); y++) {
            if (!widths[y]) continue;
            const above = Math.max(...widths.slice(0, y));
            const below = Math.max(...widths.slice(y + 1));
            notch = Math.max(notch, Math.min(above, below) / widths[y]);
          }
          // monotone: how consistently the outline goes one way.
          const steps = widths.slice(1)
            .map((n, k) => Math.sign(n - widths[k])).filter(Boolean);
          const down = steps.filter((v) => v < 0).length;
          const monotone = steps.length
            ? Math.max(down, steps.length - down) / steps.length : 1;
          // crest: the biggest drop in the top contour, for heads carried in
          // front rather than on top. Row widths cannot see those at all.
          const tops = [];
          for (let x = 0; x < W; x++) {
            let y = 0;
            while (y < H && !mask[y * W + x]) y++;
            if (y < H) tops.push(y);
          }
          let crest = 0;
          for (let k = 1; k < tops.length; k++) {
            crest = Math.max(crest, tops[k] - tops[k - 1]);
          }
          return {
            fill: area / (maxW * widths.length),
            top: 1 - cy / Math.max(1, widths.length - 1),
            taper: maxW / Math.min(...widths.filter((n) => n > 0)),
            notch,
            monotone,
            crest: crest / widths.length,
            rounds: new Set(widths).size,
            baseFrac: widths[widths.length - 1] / maxW,
          };
        };
        const HIGH = (m) => [m.top >= 0.40, `massa liian alhaalla, ${m.top.toFixed(2)} < 0,40`];
        const NECK = (m) => [m.notch >= 1.5, `kaulaa ei näy, kurouma ${m.notch.toFixed(2)} < 1,5`];
        const PLANS = {
          figure: (m) => [NECK(m), HIGH(m)],
          wedge: (m) => [[m.monotone >= 0.78,
            `ääriviiva kääntyy liikaa, ${m.monotone.toFixed(2)} < 0,78`], HIGH(m)],
          quadruped: (m) => [[m.crest >= 0.18,
            `yläreuna on tasainen, harja ${m.crest.toFixed(2)} < 0,18`], HIGH(m)],
          blob: (m) => [[m.rounds >= 6,
            `ääriviivassa ${m.rounds} eri leveyttä, alle kuuden se on laatikko`], HIGH(m)],
          anvil: (m) => [
            [m.top <= 0.46, `ei sittenkään alapainoinen, ${m.top.toFixed(2)} > 0,46`],
            [m.baseFrac >= 0.8, `jalusta ${m.baseFrac.toFixed(2)} leveimmästä, liian kapea`],
            NECK(m),
          ],
        };
        const planBad = [];
        const planShown = [];
        masks.forEach((mask, v) => {
          const plan = sprites.BOSS_PLANS[v];
          const m = shape(mask);
          planShown.push(`${v}=${plan} kurouma ${m.notch.toFixed(1)} täyttö ${m.fill.toFixed(2)}`);
          if (!PLANS[plan]) { planBad.push(`pomo ${v}: tuntematon runkotyyppi "${plan}"`); return; }
          if (m.fill > 0.80) planBad.push(`pomo ${v}: täyttö ${m.fill.toFixed(2)} > 0,80, se on laatikko`);
          if (m.taper < 2.0) planBad.push(`pomo ${v}: kavennus ${m.taper.toFixed(2)} < 2,0, se on palkki`);
          PLANS[plan](m).forEach(([ok, why]) => { if (!ok) planBad.push(`pomo ${v} (${plan}): ${why}`); });
        });
        expect('jokainen pomo on sen muotoinen minkä se itse ilmoittaa olevansa',
          planBad.length === 0, planBad.length ? planBad.join(' | ') : planShown.join(', '));
      }
    }
  }

  /*
   * TURVAVERKKO KOLMELLA OHJAUSTAVALLA, EI YHDELLÄ.
   *
   * Pikatallennus on `1`/`F5`/numpad, ja `input.js` pitää apunäppäimet
   * tarkoituksella poissa ohjaimelta. Kosketuksessa niitä ei ole lainkaan.
   * Turvaverkko oli siis olemassa vain näppäimistöllä, ja se on eri vika kuin
   * "kentät ovat pitkiä" — mitattuna kenttä on 31 s eikä kaipaa välipistettä,
   * mutta puhelimella pelaavalla ei ollut mitään.
   *
   * Testi vaatii että taukovalikossa on tallennus ja lataus, että ne ovat
   * valittavissa **hypyllä** (ainoa nappi joka on kaikilla kolmella), ja että
   * aika-ajossa niitä ei ole — kello käy tauon yli, joten ladattu tila tekisi
   * ajasta väitteen jota kukaan ei ole juossut.
   */
  {
    const ids = (ta) => {
      const was = game.timeAttack;
      game.timeAttack = ta;
      const out = game.pauseItems().map((it) => it.id);
      game.timeAttack = was;
      return out;
    };
    const menu = {
      normal: ids(false),
      attack: ids(true),
      hasUpdate: typeof game.updatePauseMenu === 'function',
    };
    const wantN = ['resume', 'save', 'load', 'slot'];
    expect('taukovalikossa on turvaverkko myös ilman näppäimistöä',
      menu.hasUpdate && wantN.every((k) => menu.normal.includes(k))
      && !menu.attack.includes('save') && !menu.attack.includes('load'),
      `tavallinen [${menu.normal}], aika-ajo [${menu.attack}]`);
  }

  /*
   * JOKAINEN TALLENNETTAVA KENTTÄ SELVIÄÄ KIERROKSESTA write -> load.
   *
   * `Save.write` luettelee kentät käsin, ja `doors` lisättiin `DEFAULT_SAVE`en
   * muttei sinne. Ovi toimi siis istunnon sisällä ja katosi jokaisesta
   * latauksesta — ominaisuus joka on olemassa vain kunnes välilehti suljetaan,
   * eikä mikään sanonut mitään.
   *
   * Tämä on **kuudes kerta tässä erässä** samalle vialle: kaksi paikkaa jotka
   * kuvaavat samaa muotoa, ja vain toinen päivittyy. Portti vertaa nyt
   * avainjoukkoja, joten seuraava lisäys kaatuu tähän eikä pelaajan
   * tallennukseen.
   */
  {
    /*
     * Luetaan **raaka localStorage** eikä `Save.load()`.
     *
     * Ensimmäinen versio vertasi `load()`in tulosta, ja se ei voinut kaatua
     * koskaan: `load` levittää `DEFAULT_SAVE()`n ensin, joten `write`istä
     * pudonnut avain täyttyy oletuksella eikä lue koskaan `undefined`ina.
     * Portti oli kirjoitettu kiinni ottamaan tasan se vika jonka se päästi
     * läpi — ja se on huonompi kuin ei porttia, koska se näyttää katetulta.
     */
    const { Save, KEY: SAVE_KEY } = await import('/src/core/save.js');
    const want = DEFAULT_SAVE();
    Save.write({ ...want, doors: { '3-F': true }, secrets: { '1-1': ['a'] } });
    const raw = JSON.parse(localStorage.getItem(SAVE_KEY) || '{}');
    const roundTrip = Object.keys(want).filter((k) => raw[k] === undefined);
    expect('jokainen tallennuksen kenttä selviää kierroksesta write -> load',
      roundTrip.length === 0,
      roundTrip.length ? `katosi: ${roundTrip.join(', ')}` : 'kaikki kentät');
  }

  /* ---- kamera ja äänten merkitykset ---- */
  /*
   * KAKSI AVOINTA KYSYMYSTÄ, JA NIIDEN VÄLILLÄ YKSI YHTEINEN VIKA.
   *
   * 1. **Kamera hyllyllä.** 2-1:n tiilihylly sarakkeessa 228 (palikka 14, rivi
   *    9) on toimitetussa kentässä ja pelaaja pääsee sille. Voimatasolla 3 sieltä
   *    lähtevä pieruhyppy nosti näkymää **2,73 px yhdellä framella** (katto 2,5)
   *    ja jätti päälle **16,10 px** pelivaraa (lattia 16) — eli toinen luku oli
   *    kymmenesosapikselin päässä siitä että sekin kaatuisi. Kaksi
   *    porttiväitettä kattaa juuri tämän — *"a view that has to rise animates
   *    instead of snapping"* ja *"anticipating the rise costs neither the
   *    headroom nor the ground"* — eivätkä ne ole koskaan nähneet sitä.
   *
   * 2. **Ja se on niistä pienempi vika.** Molemmat väitteet ajavat bottia 2-1:n
   *    alusta, ja botti kuolee ennen saraketta 228. Kattavuus on siis
   *    palikkajärjestyksen sivutuote: sekoita `chunks`-lista ja väite alkaa tai
   *    lakkaa mittaamasta hyllyä ilman että kukaan muuttaa väitettä. Sama muoto
   *    kuin kahdessa muussa tänään löytyneessä viassa — `if (m.mode === 'walk')`
   *    joka ei koskaan lauennut ja alkuperäisyystarkistus joka luki nolla
   *    korpustiedostoa ja tulosti puhtaat paperit.
   *
   * Siksi tämä lohko ei aja bottia lainkaan. Se **etsii** kentästä sen hyllyn
   * jolla kuvaa on vähiten pään yllä — seisontakorkeus plus kameran jäljellä
   * oleva matka — ja **asettaa** pelaajan sinne, ja hyppy on käsikirjoitettu.
   * Kolme asiaa seuraa siitä ja ne ovat koko korjaus kattavuuteen:
   *
   *   - jos kenttädata muuttuu, haku löytää uuden ahtaimman paikan eikä vanha
   *     sarakenumero jää valehtelemaan;
   *   - jos ahtainta paikkaa ei löydy, väite kaatuu sen sijaan että se ohittaisi
   *     itsensä hiljaa (`spots.length` on osa väitettä);
   *   - jokainen rivi kantaa mukanaan todisteen siitä että se **oli** ilmassa ja
   *     että näkymä oikeasti liikkui (`air`, `moved`). Rivi joka ei mitannut
   *     mitään ei ole vihreä rivi.
   *
   * Ja kaksi eri väitettä eikä yksi, koska kameralla on raja jota se ei voi
   * ylittää: kun kenttä loppuu näkymän yläpuolelta, `clampCamY` pysäyttää
   * kuvan ja pään pelivara on se joka antaa periksi. Se ei ole kameran vika
   * vaan kentän korkeus, joten se mitataan omana rivinään — mutta pehmeys ei
   * anna periksi siinäkään tapauksessa. Jos yksikään rivi ei osu kentän
   * kattoon, se väite on tyhjä — ja se on tässä turvallista siksi että
   * jokainen rivi on silloin toisen väitteen alla, joka on niistä kahdesta
   * vahvempi. Tyhjä väite ei siis piilota riviä, se vain vaihtaa vartijaa.
   */
  {
    const { TILE } = await import('/src/gfx/tiles.js');

    /**
     * Jokainen ruudun katto jolla keho voi seisoa, ahtain ensin.
     *
     * Järjestys on **pään yläpuolelle jäävä kuva yhteensä**: seisova pelivara
     * plus se matka joka kameralla on vielä jäljellä. Pelkkä hyllyn korkeus
     * olisi väärä mitta, koska kentän oma yläraja ratkaisee onko korkea hylly
     * ahdas paikka vai ei — sama perustelu kuin laskeutumisväitteen `climb`illä
     * rivin `cameraY()` ympärillä.
     */
    const shelves = (id, power) => {
      reset(power);
      const probe = new LevelScene(game, id);
      const p = probe.player;
      const found = [];
      for (let tx = 3; tx < probe.w - 3; tx++) {
        for (let ty = 2; ty < probe.h - 1; ty++) {
          if (!probe.solidAt(tx, ty) || probe.solidAt(tx, ty - 1)) continue;
          if (!probe.solidAt(tx - 1, ty) || !probe.solidAt(tx + 1, ty)) continue;
          // Kaksi tyhjää riviä yllä: isoin keho seisoo, eikä hyppy ala kattoon.
          if (probe.solidAt(tx, ty - 2) || probe.solidAt(tx, ty - 3)) continue;
          const feet = ty * TILE;
          p.y = feet - p.h;
          p.vy = 0;
          p.onGround = true;
          probe.camAnchor = feet;
          const cam = probe.cameraY();
          const lo = probe.clampCamY(-1e9);
          found.push({ tx, ty, reach: (feet - p.h) - lo, rest: cam, travel: cam - lo });
        }
      }
      found.sort((a, b) => a.reach - b.reach || a.tx - b.tx);
      return found;
    };

    /** Yksi käsikirjoitettu juokseva pieruhyppy nimetyltä ruudun katolta. */
    const jumpFrom = (id, power, spot) => {
      reset(power);
      const s = new LevelScene(game, id);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      const p = s.player;
      p.x = spot.tx * TILE + (TILE - p.w) / 2;
      p.y = spot.ty * TILE - p.h;
      p.vx = 0;
      p.vy = 0;
      p.onGround = true;
      s.centerCamera();
      const input = mkInput();
      // Näkymä asettuu ensin: hyppy joka lähtee kesken liu'un mittaisi liukua.
      for (let f = 0; f < 30; f++) { input.held = blank(); input.pressed = blank(); s.update(input); }
      const settled = Math.abs(s.cam.y - s.cameraY()) < 0.5;
      const takeoff = p.y + p.h;
      let rise = 0;
      let head = Infinity;
      let air = 0;
      let seen = 0;
      let spent = 0;
      let moved = 0;
      const restCam = s.cam.y;
      for (let f = 0; f < 90; f++) {
        input.held = blank();
        input.pressed = blank();
        input.held.right = true;
        input.held.run = true;
        if (f === 0) { input.pressed.jump = true; input.held.jump = true; }
        else if (f < 20) input.held.jump = true;
        if (f === 8) { input.pressed.jump = true; input.held.jump = true; }   // pieruhyppy
        const camBefore = s.cam.y;
        s.update(input);
        if (p.dying) break;
        if (!p.onGround) {
          air++;
          if (takeoff < s.cam.y + s.viewH) seen++;
          rise = Math.max(rise, camBefore - s.cam.y);
          head = Math.min(head, p.y - s.cam.y);
          // Kuinka paljon näkymä lopulta liikkui. Rivi jolla tämä on nolla ei
          // ole ajanut mekanismia lainkaan eikä siis todista siitä mitään.
          moved = Math.max(moved, restCam - s.cam.y);
          if (s.cam.y <= s.clampCamY(-1e9) + 0.01) spent++;
        }
        if (p.onGround && f > 20) break;
      }
      return { air, seen, spent, settled, rise, head, moved };
    };

    const rows = [];
    for (const [id, power] of [['2-1', { type: 'shroom', level: 3 }],
      ['2-1', { type: null, level: 0 }], ['2-1', { type: 'leaf', level: 5 }],
      ['2-3', { type: 'shroom', level: 3 }], ['2-3', { type: 'leaf', level: 5 }],
      ['1-1', { type: 'shroom', level: 3 }]]) {
      const spots = shelves(id, power);
      const spot = spots[0];
      if (!spot) { rows.push({ id, level: power.level, spots: 0 }); continue; }
      rows.push({
        id, level: power.level, spots: spots.length, tx: spot.tx, ty: spot.ty,
        ...jumpFrom(id, power, spot),
      });
    }
    const say = (r) => `${r.id} taso ${r.level} (${r.tx},${r.ty}): `
      + `${r.rise.toFixed(2)} px/frame, pää ${r.head.toFixed(2)} px, `
      + `maa ${r.seen}/${r.air}`;
    // Rivit joilla kentän oma katto ei vielä pysäyttänyt kuvaa, ja loput.
    const free = rows.filter((r) => r.air && !r.spent);
    const capped = rows.filter((r) => r.air && r.spent);

    /* Sama katto ja sama perustelu kuin lattialta mitatussa sisaressa: 2,5 on
     * alle sen mitä nykäys tuottaa ja yli sen mitä liuku tuottaa, joten se on
     * nykäys joka ei voi palata eikä mekanismi joka jäädytetään. Tämä rivi ajaa
     * sen paikan yli jolla nykäys oikeasti tapahtui. */
    expect('hyllyltä lähtevä hyppy animoi näkymän, ei nykäise sitä',
      rows.length === 6 && rows.every((r) => r.spots > 20 && r.air > 20 && r.settled)
      && rows.every((r) => r.rise < 2.5),
      rows.map((r) => `${say(r)}${r.spent ? ` (pohjassa ${r.spent})` : ''}`).join(', '));

    /* Ja pelivara pysyy, niin kauan kuin kameralla on matkaa jäljellä. Rivi
     * jolla näkymä ei liikkunut lainkaan ei todista tästä mitään — se sanoisi
     * vain että hyppy ei yltänyt pelivaraan asti — joten vähintään yhden rivin
     * on oikeasti ajanut mekanismin. Se ehto on koko kattavuuskorjaus yhdellä
     * rivillä: väite joka lakkaa mittaamasta kaatuu sen sijaan että vihertäisi. */
    /* Kolme riviä eikä neljä (17.8.2026): ikkuna kasvoi 208:sta 240:een kun
     * HUD-nauha poistui, ja yksi tapaus siirtyi `free`stä `capped`iin — sen
     * yläpuolelta loppui kuva. Se ei ole mittauksen kaventuminen vaan sama
     * kenttä toisessa ikkunassa, ja `capped` mittaa sen omalla väitteellään
     * heti alla. */
    expect('hyllyltä lähtevä hyppy ei maksa pelivaraa niin kauan kuin kuvaa riittää',
      free.length >= 3 && free.some((r) => r.moved > 8)
      && free.every((r) => r.head > 16 && r.seen === r.air),
      free.map((r) => `${say(r)}, näkymä liikkui ${r.moved.toFixed(2)} px`).join(', '));

    /* Ja kun kenttä loppuu yläpuolelta, kamera on käyttänyt kaiken minkä sillä
     * oli. Se on eri väite eikä poikkeus: pelivara antaa periksi vain silloin
     * kun kuva on lopussa, eikä koskaan siksi että kamera olisi myöhässä. */
    expect('kun kenttä loppuu näkymän yläpuolelta, kuva on lopussa eikä kamera myöhässä',
      capped.every((r) => r.rise < 2.5 && r.spent > 0 && r.seen === r.air),
      capped.length
        ? capped.map((r) => `${say(r)}, pohjassa ${r.spent}/${r.air} framea`).join(', ')
        : 'yksikään rivi ei osunut kentän kattoon');

    /*
     * SEISOVAN PELAAJAN KUVA EI SAA LIIKAHTAA, JA SE ON ARITMETIIKKAA EIKÄ
     * LIPPU. Kallistus on ilmaan ulottuva vain siksi että seisovan kehon pää ei
     * yllä `CAM_AIR_MARGIN`iin missään ikkunassa millään koolla. Sitä ei ole
     * kytketty pois maassa lipulla, joten jos ikkuna kapenee tai keho kasvaa, se
     * alkaa purra seisovaan kuvaan — ja juuri sen tämä rivi estää. (Seisova keho
     * on lisäksi paikallaan, joten `push` on nolla; tämä on niistä kahdesta
     * vartijasta se joka ei riipu siitä että toinen muistetaan.)
     */
    {
      const worst = [];
      for (const id of ['1-1', '2-1', '2-3', '1-2']) {
        for (const level of [0, 1, 2, 3, 4, 5]) {
          reset({ type: level ? 'leaf' : null, level });
          const probe = new LevelScene(game, id);
          const p = probe.player;
          let slack = Infinity;
          for (let ty = 3; ty < probe.h - 1; ty++) {
            const feet = ty * TILE;
            p.y = feet - p.h;
            p.vy = 0;
            p.onGround = true;
            probe.camAnchor = feet;
            const rest = feet - probe.viewH * 0.55 - 26;
            slack = Math.min(slack, (feet - p.h) - rest - 48);   // CAM_AIR_MARGIN
          }
          worst.push({ id, level, h: p.h, slack });
        }
      }
      const tight = worst.reduce((a, b) => (b.slack < a.slack ? b : a));
      expect('leveä raja ei yllä seisovan kehon päähän missään koossa eikä ikkunassa',
        worst.every((w) => w.slack > 0),
        `ahtain ${tight.id} taso ${tight.level} (korkeus ${tight.h}): `
        + `${tight.slack.toFixed(1)} px pelivaraa`);
    }

    /*
     * ÄÄNET JOTKA TARKOITTIVAT KAHTA ASIAA.
     *
     * Aamun auditointi jätti neljä löysää päätä raportoiduiksi eikä
     * korjatuiksi. Ne ovat kaikki samaa lajia kuin putki, joka sai oman
     * `pipeout`insa: **yksi merkki kahdelle tilanvaihdokselle**. Tässä ne
     * mitataan, ja mittaus on se osa jota kommentti ei voi korvata — "door
     * tarkoittaa kahta asiaa" on väite, "door soi framella 10 ja uudestaan
     * framella 47 samassa kentässä" on luku.
     *
     * Kolme näistä on kuvattu auki `LevelScene.onBossDefeated`issa ja
     * `audio.js`:ssä. Neljäs — kuollut `SFX.land` — on poistettu, ja sen
     * tilalle tuli portti joka estää seuraavan: **jokaisella äänellä on
     * kutsupaikka.** Se on täsmälleen sama vikaluokka kuin tämän lohkon
     * kamerapuolisko, kirjoitettuna toisin päin: siinä testi lakkasi
     * mittaamasta, tässä koodi lakkasi soimasta, eikä kumpikaan sanonut mitään.
     */
    {
      const { Sfx: A } = await import('/src/core/audio.js');
      const { TILE: TZ, info: tinfo } = await import('/src/gfx/tiles.js');

      /** Kuuntelija joka ei soita läpi: mitataan mitä peli pyytää, ei väylää. */
      const clock = { f: 0 };
      const listen = () => {
        const real = A.play;
        const heard = [];
        A.play = (name) => { heard.push({ name, f: clock.f }); };
        return { heard, off() { A.play = real; } };
      };

      /* 1. LINNAKKEEN OVI. Pomo kaadetaan framella 10 ja pelaaja siirretään
       * oven eteen — käsin, koska botti ei pääse linnakkeen ovelle asti ja
       * mittaus joka riippuu siitä ei mittaa ovea vaan bottia. */
      const fortress = [];
      for (const id of ['1-F', '2-F', '8-F']) {
        reset({ type: 'shroom', level: 3 });
        const s = new LevelScene(game, id);
        s.time = 9999;
        s.clockStopped = true;
        s.entities = s.entities.filter((e) => e.kind !== 'hazard');
        const boss = s.entities.find((e) => e.constructor.name === 'Boss');
        let door = null;
        for (let tx = 0; tx < s.w && !door; tx++) {
          for (let ty = 0; ty < s.h; ty++) {
            if (tinfo(s.tileAt(tx, ty)).door) { door = { tx, ty }; break; }
          }
        }
        const tap = listen();
        const input = mkInput();
        const p = s.player;
        try {
          for (let f = 0; f < 400; f++) {
            clock.f = f;
            input.held = blank();
            input.pressed = blank();
            if (f === 10 && boss) { boss.hp = 1; boss.stomp(1); }
            if (f === 12 && door) {
              p.x = (door.tx - 3) * TZ;
              p.y = door.ty * TZ + TZ - p.h;
              p.vx = 0;
              p.vy = 0;
              p.onGround = true;
              s.centerCamera();
            }
            if (f > 12) input.held.right = true;
            s.update(input);
            if (s.state === 'clear' && f > 20) break;
          }
        } finally { tap.off(); }
        const at = (name) => tap.heard.filter((h) => h.name === name).map((h) => h.f);
        fortress.push({
          id, done: s.state === 'clear', open: at('door'), walk: at('doorin'), clear: at('clear'),
        });
      }
      const fsay = (r) => `${r.id} ovi auki ${r.open.join('+') || '-'}, `
        + `sisään ${r.walk.join('+') || '-'}, kenttä läpi ${r.clear.join('+') || '-'}`;
      expect('oven aukeaminen ja siitä sisään käveleminen ovat eri äänet',
        fortress.length === 3 && fortress.every((r) => r.done
          && r.open.length === 1 && r.walk.length === 1 && r.open[0] < r.walk[0]),
        fortress.map(fsay).join(' | '));
      /* Ja sama jingle kahdesti sekunnin sisällä oli se toinen puolisko. `clear`
       * kuuluu kentän loppumiselle ja sitä on tasan yksi, vaikka linnakkeessa
       * on kaksi hetkeä joita voisi juhlia. */
      expect('linnakkeen läpäisyjingle soi kerran eikä kahdesti',
        fortress.every((r) => r.clear.length === 1 && r.clear[0] > r.walk[0]),
        fortress.map((r) => `${r.id}: clear ${r.clear.join('+') || '-'} `
          + `(ovi ${r.open.join('+') || '-'})`).join(', '));

      /* 2. LOHKO JOKA ANTAA, JA KEHO JOKA KASVAA. Sama mansikka, kaksi
       * tapahtumaa: se työntyy ulos lohkosta ja sekunti myöhemmin se syödään.
       * Mitataan molemmat samasta ajosta, koska väite on niiden **erosta**. */
      let payout = null;
      let grew = null;
      let switched = null;
      {
        reset({ type: null, level: 0 });
        const s = new LevelScene(game, '1-1');
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        let block = null;
        for (let tx = 3; tx < s.w && !block; tx++) {
          for (let ty = 2; ty < s.h - 1; ty++) {
            if (tinfo(s.tileAt(tx, ty)).question) { block = { tx, ty }; break; }
          }
        }
        const tap = listen();
        try {
          if (block) s.bumpTile(block.tx, block.ty, s.player);
          payout = tap.heard.map((h) => h.name);
          tap.heard.length = 0;
          s.player.collect('shroom');
          grew = tap.heard.map((h) => h.name);
          tap.heard.length = 0;
          s.startSwitch();
          switched = tap.heard.map((h) => h.name);
        } finally { tap.off(); }
      }
      expect('lohkon maksu, kehon kasvu ja kytkin ovat kolme eri merkkiä',
        payout.length === 1 && grew.length === 1 && switched.length === 1
        && new Set([payout[0], grew[0], switched[0]]).size === 3
        && grew[0] === 'powerup' && A.has(payout[0]) && A.has(switched[0]),
        `lohko "${payout.join('+') || '-'}", kasvu "${grew.join('+') || '-'}", `
        + `kytkin "${switched.join('+') || '-'}"`);

      /* 3. EIKÄ `powerup` OLE ENÄÄ KENTÄN SISÄLLÄ MUUTA KUIN KASVAMINEN.
       * Luettu lähteestä eikä ajosta: kutsupaikka jota mikään testi ei satu
       * ajamaan on juuri se joka jää. Valikot ja kartta saavat pitää sen —
       * ne ovat kertojan puolella (kohta 8) — mutta kenttä ei. */
      const srcOf = async (path) => (await fetch(path)).text();
      const levelSrc = await srcOf('/src/scenes/level.js');
      const inLevel = (levelSrc.match(/Sfx\.play\('powerup'\)/g) || []).length;
      expect('kentän moottori ei enää lainaa kasvamisen ääntä',
        inLevel === 0, `Sfx.play('powerup') src/scenes/level.js:ssä ${inLevel} kertaa`);

      /*
       * 4. EIKÄ YKSIKÄÄN ÄÄNI OLE MÄÄRITELTY SOIMATTA.
       *
       * `SFX.land` oli määritelty ja soittamaton, ja se löytyi lukemalla eikä
       * ajamalla — mikä on toinen tapa sanoa että mikään ei ollut estämässä
       * seuraavaa. Tämä lukee lähteet ja vaatii jokaiselta nimeltä kutsupaikan.
       *
       * Poikkeuslista on **yksi nimi ja se on kirjattu**: `oof` on repliikki
       * jolle peli ei ole vielä keksinyt paikkaa, ja se on aiemmin kirjattu
       * juuri niin. Poikkeus jonka nimi on tässä on päätös; poikkeus jota ei
       * ole tässä on unohdus, ja ero näiden välillä on koko portin idea.
       */
      const SILENT_ON_PURPOSE = ['oof'];
      /* Tiedostolista **kävellään moduuligraafista** eikä kirjoiteta käsin, ja
       * se on sama päätös kuin kamerapuoliskon hyllynhaku: käsin kirjoitettu
       * lista vanhenee ensimmäisessä uudessa tiedostossa, ja vanhentunut lista
       * julistaisi elävän äänen kuolleeksi tai päinvastoin. Lähtö on se sama
       * `main.js` jonka selain lataa, joten kattavuus on määritelmän mukaan sama
       * kuin pelin oma. */
      const seenFiles = new Map();
      const walk = async (path) => {
        if (seenFiles.has(path)) return;
        seenFiles.set(path, '');
        let text = '';
        try { text = await srcOf(path); } catch { return; }
        seenFiles.set(path, text);
        const specs = [...text.matchAll(/(?:from|import)\s*\(?\s*'(\.[^']+)'/g)].map((m) => m[1]);
        for (const spec of specs) {
          await walk(new URL(spec, `${location.origin}${path}`).pathname);
        }
      };
      await walk('/src/main.js');
      const sources = [...seenFiles.values()].join('\n');
      const played = new Set();
      for (const m of sources.matchAll(/Sfx\.play\(\s*'([a-z]+)'/g)) played.add(m[1]);
      // Kolme paikkaa valitsee nimen ehdollisesti, ja ne ovat literaaleja siinä
      // missä muutkin — vain sulkujen sisällä.
      for (const m of sources.matchAll(/Sfx\.play\([^)]*\?\s*'([a-z]+)'\s*:\s*'([a-z]+)'/g)) {
        played.add(m[1]);
        played.add(m[2]);
      }
      const dead = A.names().filter((n) => !played.has(n) && !SILENT_ON_PURPOSE.includes(n));
      const stale = SILENT_ON_PURPOSE.filter((n) => played.has(n) || !A.has(n));
      expect('jokaisella määritellyllä äänellä on kutsupaikka, tai nimetty syy olla ilman',
        seenFiles.size > 25 && dead.length === 0 && stale.length === 0,
        `${seenFiles.size} tiedostoa, ${A.names().length} ääntä, ${played.size} soitettua, `
        + `kuolleita ${dead.join(', ') || '0'}, `
        + `vanhentunut poikkeus ${stale.join(', ') || '0'}`);

      /*
       * 5. JA UUDET MERKIT KUULUVAT. Sama mittaustapa ja sama 16384 näytteen
       * ikkuna kuin aamun erässä — ikkuna on pidempi kuin mikään mitä se
       * mittaa, koska 2048 näytteellä 95 ms:n ääni mittautui nollaksi ja portti
       * olisi julistanut kuulumattomaksi äänen jonka kaiuttimet soittavat.
       */
      const tap2 = audioTap();
      const running = tap2 && tap2.ctx.state === 'running';
      const peaks = {};
      let after = 0;
      let stalled = false;
      /* Sama kahtia jaettu korjaus kuin aamun erässä (`meterFor` ja
       * `keepRendering` ylempänä), omana kappaleenaan koska tämä lohko ajetaan
       * eri `page.evaluate`ssa eikä siis näe niitä. Perustelu on kirjoitettu
       * kerran sinne: ikkuna mitataan **äänikellossa**, ja väylällä pidetään
       * äänetön lähde jotta renderöijä pysyy töissä. */
      let wake = () => {};
      if (running) {
        const osc = tap2.ctx.createOscillator();
        const silent = tap2.ctx.createGain();
        silent.gain.value = 0;
        osc.connect(silent).connect(tap2.bus);
        osc.start();
        wake = () => {
          try { osc.stop(); } catch { /* jo pysäytetty */ }
          osc.disconnect();
          silent.disconnect();
        };
      }
      if (running) {
        const { Ambience: Amb } = await import('/src/core/audio.js');
        Music.stop();
        Amb.stop();
        const an = tap2.ctx.createAnalyser();
        an.fftSize = 16384;
        tap2.bus.connect(an);
        const buf = new Float32Array(an.fftSize);
        const windowSec = an.fftSize / tap2.ctx.sampleRate;
        const peakFor = async (ms) => {
          let peak = 0;
          const c0 = tap2.ctx.currentTime;
          const w0 = performance.now();
          const cap = ms * 6 + 500;
          let last = c0;
          const sample = () => {
            an.getFloatTimeDomainData(buf);
            for (let i = 0; i < buf.length; i++) peak = Math.max(peak, Math.abs(buf[i]));
            const now = tap2.ctx.currentTime;
            if (now - last > windowSec) stalled = true;
            last = now;
          };
          while ((tap2.ctx.currentTime - c0) * 1000 < ms) {
            sample();
            if (performance.now() - w0 > cap) { stalled = true; break; }
            await new Promise((r) => setTimeout(r, 4));
          }
          sample();                          // ks. `meterFor`: ryöppy ikkunan ohi
          return peak;
        };
        /* Neljä sekuntia soitettua ääntä, sama kuin aamun erässä. Seinäkellossa
         * on vain väljä varmistus jottei ajo jää roikkumaan seisovaan
         * renderöijään; siihen meneminen tarkoittaa ettei tämä ollut mittaus. */
        const settle = async () => {
          let calm = 0;
          let level = 1;
          const c0 = tap2.ctx.currentTime;
          const w0 = performance.now();
          while (calm < 2 && tap2.ctx.currentTime - c0 < 4) {
            level = await peakFor(200);
            calm = level > 0.02 ? 0 : calm + 1;
            if (performance.now() - w0 > 26000) { stalled = true; break; }
          }
          return level;
        };
        for (const name of ['payout', 'kytkin', 'doorin', 'door', 'pipe', 'coin', 'powerup']) {
          /* Jouten olon kello nollataan jokaisen äänen edeltä — sama korjaus ja
           * sama mitattu syy kuin aamun erässä: `settle` voi odottaa neljä
           * sekuntia kerrallaan, joten seitsemän ääntä ei mahdu taatusti siihen
           * kahteenkymmeneen sekuntiin jonka jälkeen esittelydemo alkaa soittaa
           * samalle väylälle. Mitattu kerran tässä lohkossa: `pipe` 0,332 kun
           * sen neljä edellistä ajoa olivat 0,169. */
          if (game.scene && game.scene.idle !== undefined) game.scene.idle = 0;
          else if (game.scene && game.scene.constructor.name === 'DemoScene') {
            game.toTitle(); Music.stop(); Amb.stop();
          }
          await settle();
          stalled = false;                   // vain mitattava ikkuna ratkaisee
          A.play(name);
          peaks[name] = await peakFor(600);
          if (stalled) break;
        }
        after = await settle();
        an.disconnect();
      }
      wake();
      const measured = running && !stalled;
      const pk = (name) => (peaks[name] === undefined ? 0 : peaks[name]);
      const shownPeaks = Object.entries(peaks).map(([k, v]) => `${k} ${v.toFixed(3)}`).join(', ');
      expect('uudet merkit kuuluvat, eivät huuda, eivätkä jätä väylää soimaan',
        !measured || (
          // Kuuluu, mutta on pienempi kuin se palkinto jota se ei ole: lohko
          // antaa, poimiminen palkitsee, ja tässä järjestyksessä.
          pk('payout') > 0.15 && pk('payout') < pk('coin')
          // Huoneen muutos on iso, muttei pelin kovin ääni.
          && pk('kytkin') > 0.15 && pk('kytkin') < pk('powerup')
          // Näkyvistä häviämisen kaksi tapaa mitataan pariksi, samalla tavalla
          // kuin putken kaksi päätä aamulla.
          && pk('doorin') > pk('pipe') * 0.6 && pk('doorin') < pk('pipe') * 1.6
          && after < 0.02),
        measured ? `${shownPeaks}, tausta jäljessä ${after.toFixed(3)}` : 'ei mitattu');
    }
  }

  const { TRACK_SOURCES } = await import('/src/core/audio.js');
  return {
    levels, checks, failures, worlds: WORLDS.length, ruleReport,
    audio: { sfx: Sfx.names(), music: Music.names() },
    trackSources: TRACK_SOURCES || {},
  };
}, OVERWORLDS);

/* ---------------------- kosketusohjaus puhelimen mitoissa ----------------- */
/*
 * A second context with an iPhone's viewport, pixel ratio and touch support.
 *
 * What this proves: that the layout survives 390 CSS pixels of width, that the
 * phone-only media queries — which never run in the desktop page above — put
 * the buttons where they are meant to be, and that the hit-testing still reads
 * a thumb roll at that size.
 *
 * What it does NOT prove: anything about Safari. This is Chromium wearing an
 * iPhone's measurements. Double-tap zoom, pinch and `touch-action` handling are
 * WebKit's own, and only a real phone can confirm them.
 */
{
  const phone = await browser.newContext({ ...devices['iPhone 13'] });
  const page2 = await phone.newPage();
  page2.on('pageerror', (e) => errors.push(`[iphone pageerror] ${e.message}`));
  page2.on('console', (m) => {
    const text = m.text();
    if (m.type() === 'error' && !text.includes('favicon')) errors.push(`[iphone console] ${text}`);
  });
  await page2.goto(`http://127.0.0.1:${PORT}`, { waitUntil: 'networkidle' });
  await page2.waitForTimeout(400);

  const mobile = await page2.evaluate(async () => {
    const checks = [];
    const failures = [];
    const expect = (name, ok, detail = '') => {
      checks.push({ name: `${name} (iPhone-mitat)`, ok, detail });
      if (!ok) failures.push(`${name} [iPhone-mitat]${detail ? ` (${detail})` : ''}`);
    };
    const { Input } = await import('/src/core/input.js');
    const touch = window.sfb3.touch;
    touch.reveal();

    // A phone that has never been given a preference gets the layout that was
    // built for one thumb. Anyone who has chosen keeps their choice — that is
    // what localStorage is for, and this context has nothing stored.
    expect('a phone with no stored preference starts in the rolling layout',
      touch.layout === 'rulla', touch.layout);

    touch.setLayout('rulla');
    const rect = (act) => document.querySelector(`#touch [data-act="${act}"]`).getBoundingClientRect();
    const send = (type, id, x, y) => {
      document.getElementById('touch').dispatchEvent(new PointerEvent(type, {
        pointerId: id, clientX: x, clientY: y, pointerType: 'touch', bubbles: true, cancelable: true,
      }));
    };
    const held = () => {
      Input.poll();
      return Object.entries(Input.held).filter(([, v]) => v).map(([k]) => k).sort().join(',');
    };

    expect('the root element still forbids double-tap zoom on a phone',
      getComputedStyle(document.documentElement).touchAction === 'manipulation',
      getComputedStyle(document.documentElement).touchAction);

    const runPad = rect('run');
    const jumpPad = rect('jump');
    const dpad = ['left', 'right', 'up', 'down'].map(rect);
    const small = [runPad, jumpPad, ...dpad].filter((r) => r.width < 44 || r.height < 44);
    expect('no control is under the 44 px a fingertip needs', small.length === 0,
      small.map((r) => `${Math.round(r.width)}x${Math.round(r.height)}`).join(' '));

    expect('the jump button stays inside the fart pad at phone width',
      jumpPad.left >= runPad.left && jumpPad.right <= runPad.right
      && jumpPad.top >= runPad.top && jumpPad.bottom <= runPad.bottom,
      `pieru ${Math.round(runPad.left)}..${Math.round(runPad.right)} / hyppy ${Math.round(jumpPad.left)}..${Math.round(jumpPad.right)}`);

    const clash = dpad.filter((r) => r.right > runPad.left && r.bottom > runPad.top && r.top < runPad.bottom);
    expect('the fart pad does not land on the d-pad at 390 px of width',
      clash.length === 0, `d-pad ends at ${Math.round(Math.max(...dpad.map((r) => r.right)))}, pieru alkaa ${Math.round(runPad.left)}`);

    const offscreen = [runPad, jumpPad, ...dpad]
      .filter((r) => r.left < 0 || r.top < 0 || r.right > innerWidth || r.bottom > innerHeight);
    expect('every control is on the screen', offscreen.length === 0,
      `${Math.round(innerWidth)}x${Math.round(innerHeight)}, ulkona ${offscreen.length}`);

    touch._releaseAll();
    Input.poll();
    Input.poll();
    const rest = [runPad.right - 16, runPad.bottom - 16];
    send('pointerdown', 30, ...rest);
    const resting = held();
    send('pointermove', 30, jumpPad.left + jumpPad.width / 2, jumpPad.top + jumpPad.height / 2);
    const rolled = held();
    send('pointermove', 30, ...rest);
    const back = held();
    send('pointerup', 30, ...rest);
    expect('the thumb roll works at phone size too',
      resting === 'run' && rolled === 'jump,run' && back === 'run',
      `lepo "${resting}" ylös "${rolled}" alas "${back}"`);

    /*
     * HYPPY EI SAA OLLA KOMENTO, ja tämä on omistajan iPhone-raportti
     * 17.8.2026 porttina: *"default layoutilla ei voinut käynnistää kenttää,
     * molemmat napit käynnistivät jako-toiminnon."*
     *
     * Syy oli oletusmallin idea — hyppyympyrä on juoksukentän sisällä, joten
     * yksi sormi antaa molemmat — ja se on oikein pelissä. Valikoissa `run` on
     * komento (alkuruudulla jako, kartalla varaesine) ja komennot luetaan
     * reunasta, joten jokainen hyppy oli myös komento.
     *
     * Väite on siis kaksiosainen ja molemmat puolet ovat välttämättömiä:
     * ympyrään osuva sormi **pitää** juoksun (juoksuhyppy säilyy) muttei anna
     * sille **reunaa** (valikko ei näe painallusta). Ja juoksukenttään yksin
     * osuva sormi antaa reunan normaalisti, koska ampuminen ja varaesine ovat
     * oikeita painalluksia.
     */
    const edges = () => {
      Input.poll();
      return Object.entries(Input.pressed).filter(([, v]) => v).map(([k]) => k).sort().join(',');
    };
    touch._releaseAll();
    Input.poll();
    Input.poll();
    send('pointerdown', 31, jumpPad.left + jumpPad.width / 2, jumpPad.top + jumpPad.height / 2);
    const jumpEdges = edges();
    const jumpHeld = Object.entries(Input.held).filter(([, v]) => v).map(([k]) => k).sort().join(',');
    send('pointerup', 31, jumpPad.left + jumpPad.width / 2, jumpPad.top + jumpPad.height / 2);
    Input.poll();
    Input.poll();
    send('pointerdown', 32, runPad.right - 16, runPad.bottom - 16);
    const runEdges = edges();
    send('pointerup', 32, runPad.right - 16, runPad.bottom - 16);
    Input.poll();
    expect('hyppyympyrä pitää juoksun muttei paina sitä — ja pelkkä juoksukenttä painaa',
      jumpEdges === 'jump' && jumpHeld === 'jump,run' && runEdges === 'run',
      `ympyrä: reunat "${jumpEdges}" pidot "${jumpHeld}", kenttä yksin: reunat "${runEdges}"`);

    /*
     * NAPAUTUS KÄVELEE, PITO JUOKSEE. Omistaja: *"kosketusnäytön
     * ohjainlayoutilla on vaikea juosta samalla kun hyppää."* Kolmas asia
     * kahdelle peukalolle on aina jonkun toisen päällä, joten juoksu tulee
     * ajasta. Väitteessä on kolme osaa: lyhyt kosketus ei juokse, pitkä
     * juoksee, eikä automaatti **paina** juoksua (se on myös ampumisnappi, ja
     * reunallinen automaatti ampuisi joka kerta kun pelaaja lähtee liikkeelle).
     */
    touch._releaseAll();
    Input.poll();
    Input.poll();
    const right = rect('right');
    send('pointerdown', 33, right.left + right.width / 2, right.top + right.height / 2);
    let short = '';
    let shot = '';
    for (let f = 0; f < 12; f++) { Input.poll(); if (Input.pressed.run) shot = 'ampui'; }
    short = Input.held.run ? 'juoksee' : 'kävelee';
    for (let f = 0; f < 20; f++) { Input.poll(); if (Input.pressed.run) shot = 'ampui'; }
    const long = Input.held.run ? 'juoksee' : 'kävelee';
    send('pointerup', 33, right.left + right.width / 2, right.top + right.height / 2);
    Input.poll();
    Input.poll();
    const after = Input.held.run ? 'juoksee' : 'kävelee';
    expect('kosketuksessa napautus kävelee ja pito juoksee, eikä automaatti ammu',
      short === 'kävelee' && long === 'juoksee' && after === 'kävelee' && shot === '',
      `12 framea: ${short}, 32 framea: ${long}, irrotuksen jälkeen: ${after},`
      + ` ampumisreunoja: ${shot || 'ei yhtään'}`);

    return { checks, failures };
  });
  report.checks.push(...mobile.checks);
  report.failures.push(...mobile.failures);
  await phone.close();
}

/* ------------------------ kehys kaarevan kuvan ympärillä ------------------ */
/*
 * Omistajan havainto Chromella: "kuvaputkiruudun ympärillä on laatikko".
 *
 * Syy on kahden asian törmäys, ja molemmat mitataan tässä ennen kuin kumpaakaan
 * uskotaan. `styles.css` piirtää esityskankaalle suorakulmaisen renkaan
 * (`box-shadow: 0 0 0 2px`), kun taas `postfx.js`:n tynnyrivääristymä vetää
 * kuvan **sisäänpäin** (`uv += uv * offset`, ja rajan yli menevä näyte on
 * kehystä). Suora rengas jää siis seisomaan kaarevan kuvan ympärille, ja rako
 * niiden välissä on suurimmillaan nurkissa — juuri siellä missä se ruutukaappauksessa näkyy.
 *
 * Mittaus on kaksiosainen, koska rengas ei ole kankaalla vaan sivulla: kaarevuus
 * luetaan esityskankaan pikseleistä (lähde valkoiseksi, yksi `present`, ja
 * katsotaan mistä kuva alkaa), ja rengas oikeasta ruutukaappauksesta, jonka
 * selain on jo yhdistänyt varjoineen päivineen. Kaappaus puretaan takaisin
 * sivulla `createImageBitmap`illa — se on sama kaksikko joka repossa jo on
 * (`tools/make-card.mjs` kuvaa elementin, testistö lukee pikseleitä).
 *
 * Vaatimus on nimenomaan ehdollinen eikä "poista kehys". Kuvamoodeja on kolme
 * (`7`: pois → hehku → kuvaputki) ja vain kuvaputki kaartaa, eikä WebGL:tä
 * vailla olevalla koneella kaareva kuva ole edes mahdollinen. Suora kuva saa
 * siis pitää kehyksensä, ja se on toinen tämän kohdan väitteistä: pelkkä rivin
 * poistaminen tiedostosta kaataa sen.
 */
{
  const expect = (name, ok, detail = '') => {
    report.checks.push({ name, ok, detail });
    if (!ok) report.failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const glThere = await page.evaluate(async () => {
    const { PostFX } = await import('/src/gfx/postfx.js');
    return PostFX.mode === 'webgl';
  });

  if (!glThere) {
    // Kelvollista WebGL:ää vailla ei ole kaarevaa kuvaa eikä siis tätä bugia.
    // Ohitus sanotaan ääneen: hiljaa ohitettu testi on vihreä joka ei mittaa.
    report.checks.push({
      name: 'kaareva kuva ei kanna suoraa kehystä',
      ok: true,
      detail: 'ei WebGL-kontekstia, ei kaarevuutta — ohitettu',
    });
  } else {
    /* 1. Kaarevuus: kuinka kauas kuva vetäytyy elementin reunasta.
     *
     * Lähde maalataan valkoiseksi, jotta ero kuvan ja kehysvärin
     * (`vec4(0.02, 0.02, 0.03, 1.0)`) välillä on suurin mahdollinen eikä mittaus
     * riipu siitä mikä kohtaus sattuu olemaan ruudulla. Nurkasta lähdetään
     * lävistäjää pitkin sisään ja reunan keskeltä suoraan sisään: ero näiden
     * kahden välillä **on** koko bugi, koska suora kehys sopii vain siihen
     * jälkimmäiseen. */
    const curve = await page.evaluate(async () => {
      const { PostFX } = await import('/src/gfx/postfx.js');
      const game = window.sfb3;
      const src = game.canvas;
      const g = src.getContext('2d');
      g.fillStyle = '#ffffff';
      g.fillRect(0, 0, src.width, src.height);
      PostFX.setPreset('crt');
      PostFX.present();
      const disp = PostFX.displayCanvas;
      // Piirtopuskuria luetaan saman tehtävän sisällä kuin se piirrettiin:
      // ilman `preserveDrawingBuffer`ia se on tyhjä heti kun selain on ehtinyt
      // yhdistää ruudun.
      const probe = document.createElement('canvas');
      probe.width = disp.width;
      probe.height = disp.height;
      const p = probe.getContext('2d');
      p.drawImage(disp, 0, 0);
      const d = p.getImageData(0, 0, probe.width, probe.height).data;
      const sum = (x, y) => {
        const i = (y * probe.width + x) * 4;
        return d[i] + d[i + 1] + d[i + 2];
      };
      // Kehysväri on summana 18; 40 on sen yläpuolella ja kaukana valkoisesta.
      let diag = 0;
      while (diag < probe.height / 2 && sum(diag, diag) < 40) diag++;
      let mid = 0;
      const my = probe.height >> 1;
      while (mid < probe.width / 2 && sum(mid, my) < 40) mid++;
      game.render();                     // takaisin siihen mitä ruudulla oli
      return { w: probe.width, h: probe.height, diag, mid };
    });
    expect('kuvaputken kuva vetäytyy nurkista mutta ei reunojen keskeltä',
      curve.diag >= 8 && curve.mid === 0,
      `nurkassa ${curve.diag} px sisään, reunan keskellä ${curve.mid} px `
      + `(${curve.w}x${curve.h})`);

    /* 2. Rengas: kirkkain pikseli siinä kahden pikselin nauhassa joka jää heti
     * elementin ulkopuolelle. Siellä asuu `box-shadow`in levitys, ja siellä
     * asuu myös pudotusvarjo — joka vain tummentaa, joten sivun oma tausta on
     * oikea vertailukohta molempiin suuntiin. */
    const band = async (preset) => {
      await page.evaluate(async (name) => {
        const { PostFX } = await import('/src/gfx/postfx.js');
        PostFX.setPreset(name);
        window.sfb3.render();
      }, preset);
      await page.waitForTimeout(80);
      const box = await page.evaluate(() => {
        const el = document.getElementById('screen') || document.getElementById('game');
        const r = el.getBoundingClientRect();
        return { x: r.x, y: r.y, w: r.width, h: r.height };
      });
      const pad = 6;
      const png = await page.screenshot({
        clip: {
          x: Math.round(box.x - pad),
          y: Math.round(box.y - pad),
          width: Math.round(box.w + pad * 2),
          height: Math.round(box.h + pad * 2),
        },
      });
      return page.evaluate(async ({ b64, edge }) => {
        const blob = await (await fetch(`data:image/png;base64,${b64}`)).blob();
        const bmp = await createImageBitmap(blob);
        const c = document.createElement('canvas');
        c.width = bmp.width;
        c.height = bmp.height;
        const g = c.getContext('2d');
        g.drawImage(bmp, 0, 0);
        const d = g.getImageData(0, 0, c.width, c.height).data;
        const lum = (x, y) => {
          const i = (y * c.width + x) * 4;
          return 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
        };
        let max = 0;
        for (let x = edge; x < c.width - edge; x++) {
          max = Math.max(max, lum(x, edge - 1), lum(x, edge - 2),
            lum(x, c.height - edge), lum(x, c.height - edge + 1));
        }
        for (let y = edge; y < c.height - edge; y++) {
          max = Math.max(max, lum(edge - 1, y), lum(edge - 2, y),
            lum(c.width - edge, y), lum(c.width - edge + 1, y));
        }
        const bg = getComputedStyle(document.body).backgroundColor.match(/\d+/g).map(Number);
        return { max, bg: 0.299 * bg[0] + 0.587 * bg[1] + 0.114 * bg[2] };
      }, { b64: png.toString('base64'), edge: pad });
    };

    const wasPreset = await page.evaluate(async () => {
      const { PostFX } = await import('/src/gfx/postfx.js');
      return PostFX.preset;
    });
    const crt = await band('crt');
    const flat = await band('pois');
    const glow = await band('hehku');
    await page.evaluate(async (name) => {
      const { PostFX } = await import('/src/gfx/postfx.js');
      PostFX.setPreset(name);
      window.sfb3.render();
    }, wasPreset);

    expect('kaareva kuva ei kanna suoraa kehystä',
      crt.max <= crt.bg,
      `kirkkain kehyspikseli ${crt.max.toFixed(1)}, sivun tausta ${crt.bg.toFixed(1)} `
      + `— kuva vetäytyy nurkassa ${curve.diag} px`);

    /* Ja toinen puolisko: suora kuva on suora, ja suoran kuvan ympärille kehys
     * kuuluu. Ilman tätä väitettä bugin voisi "korjata" poistamalla rivin, ja
     * silloin ilman WebGL:ää pelaava — sama kone jolle koko varajärjestelmä on
     * olemassa — saisi reunattoman kankaan mustalla sivulla. */
    expect('suora kuva pitää kehyksensä molemmissa muissa moodeissa',
      flat.max > flat.bg && glow.max > glow.bg,
      `pois ${flat.max.toFixed(1)}, hehku ${glow.max.toFixed(1)}, `
      + `tausta ${flat.bg.toFixed(1)}`);
  }
}

/* --------------------- haastelinkki oikeana sivunlatauksena --------------- */
/*
 * Kolme asiaa haastelinkissä ei ole testattavissa funktiokutsuna, koska ne ovat
 * sivunlatauksen tapahtumia: parametrien luku käynnistyksessä, niiden poisto
 * osoiteriviltä ja se että vastaanotto **ei kirjoita mitään**. Ne vaativat
 * oman selainkontekstin ja oikean `goto`:n kyselymerkkijonolla.
 *
 * Kontekstit ovat erillisiä tarkoituksella: roskatestit käynnistävät pelin ja
 * kirjoittavat tallennuksen, ja se sotkisi kirjoitusmittauksen.
 */
{
  const base = `http://127.0.0.1:${PORT}/`;
  const expect = (name, ok, detail = '') => {
    report.checks.push({ name, ok, detail });
    if (!ok) report.failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  /* --- A: roska parametreissa ei saa estää peliä käynnistymästä --- */
  {
    const junkCtx = await browser.newContext();
    const jp = await junkCtx.newPage();
    const junkErrors = [];
    jp.on('pageerror', (e) => junkErrors.push(`[haaste pageerror] ${e.message}`));
    jp.on('console', (m) => {
      const text = m.text();
      if (m.type() === 'error' && !text.includes('favicon')) junkErrors.push(`[haaste console] ${text}`);
    });

    /* Jokainen rivi: kyselymerkkijono, odotettu haaste (null = ei haastetta)
     * ja se mitä tapaus koettelee. Peruste kaikille: haaste on väite ajosta
     * jonka tämä peli olisi voinut tuottaa. Jos väite ei ole sellainen, ei ole
     * haastetta — ja alkuruutu on täsmälleen se mikä se on ilman linkkiäkin. */
    const cases = [
      ['', null, 'ei parametreja'],
      ['?', null, 'tyhjä kysely'],
      ['?s=abc&n=OLLI', null, 'kirjaimia pisteinä'],
      ['?s=-5', null, 'negatiivinen tulos'],
      ['?s=1e999', null, 'eksponentti eli ääretön'],
      [`?s=1000&n=${'A'.repeat(500)}`, { score: 1000, name: 'AAAAAA', level: '' }, '500 merkin nimi'],
      ['?s=1000&n=%F0%9F%92%A9%E4%B8%AD%E6%96%87', { score: 1000, name: 'KAVERI', level: '' }, 'unicode-nimi'],
      ['?s=1000&n=OLLI&l=9-9', { score: 1000, name: 'OLLI', level: '' }, 'olematon kenttä'],
      ['?s=45200&n=OLLI&l=2-3', { score: 45200, name: 'OLLI', level: '2-3' }, 'kunnollinen haaste'],
    ];

    const results = [];
    for (const [query] of cases) {
      await jp.goto(base + query, { waitUntil: 'networkidle' });
      await jp.waitForTimeout(120);
      results.push(await jp.evaluate(async () => {
        const game = window.sfb3;
        if (!game) return { booted: false };
        // Alkuruutu piirtyy: haaste tai ei, ruudulla on peliä eikä mustaa.
        game.render();
        const px = game.ctx.getImageData(0, 0, 320, 240).data;
        const seen = new Set();
        for (let p = 0; p < px.length; p += 4 * 37) {
          seen.add((px[p] << 16) | (px[p + 1] << 8) | px[p + 2]);
        }
        // …ja peli lähtee käyntiin. Se on se mitä roskalinkki ei saa estää.
        const before = game.scene.constructor.name;
        game.newGame();
        const started = game.scene.constructor.name;
        return {
          booted: true,
          challenge: game.challenge ? { ...game.challenge } : null,
          colors: seen.size,
          title: before,
          started,
          search: location.search,
        };
      }));
    }

    const bad = [];
    cases.forEach(([query, want, why], i) => {
      const got = results[i];
      if (!got.booted) { bad.push(`${why}: ei bootannut`); return; }
      if (got.title !== 'TitleScene') bad.push(`${why}: alkuruutu oli ${got.title}`);
      if (got.colors < 5) bad.push(`${why}: ruutu tyhjä (${got.colors} väriä)`);
      if (!isOverworld(got.started)) bad.push(`${why}: peli ei lähtenyt (${got.started})`);
      const c = got.challenge;
      if (!want && c) bad.push(`${why}: haaste syntyi tyhjästä (${JSON.stringify(c)})`);
      if (want && !c) bad.push(`${why}: haaste jäi lukematta`);
      if (want && c && (c.score !== want.score || c.name !== want.name || c.level !== want.level)) {
        bad.push(`${why}: ${JSON.stringify(c)} != ${JSON.stringify(want)}`);
      }
      if (got.search.includes('s=') || got.search.includes('n=') || got.search.includes('l=')) {
        bad.push(`${why}: parametrit jäivät osoiteriville (${got.search})`);
      }
    });
    expect('roskalinkki ei estä peliä käynnistymästä eikä keksi haastetta',
      bad.length === 0 && junkErrors.length === 0,
      [...bad, ...junkErrors].join('; ') || `${cases.length} tapausta`);

    /* Osoiterivin siivous on kaksi lupausta yhdessä: päivitys ei herätä
     * vanhentunutta haastetta, eikä `?touch=1` saa kadota siivouksen mukana —
     * se on kehitystyökalu joka elää samassa kyselyssä. */
    await jp.goto(`${base}?s=45200&n=OLLI&l=2-3&touch=1`, { waitUntil: 'networkidle' });
    await jp.waitForTimeout(120);
    const stripped = await jp.evaluate(() => ({
      search: location.search,
      challenge: window.sfb3.challenge ? { ...window.sfb3.challenge } : null,
      entries: performance.getEntriesByType('navigation').length,
    }));
    await jp.reload({ waitUntil: 'networkidle' });
    await jp.waitForTimeout(120);
    const reloaded = await jp.evaluate(() => ({
      search: location.search,
      challenge: window.sfb3.challenge ? { ...window.sfb3.challenge } : null,
    }));
    expect('haasteparametrit katoavat osoiteriviltä eivätkä herää päivityksessä',
      stripped.search === '?touch=1' && stripped.challenge
      && stripped.challenge.score === 45200
      && reloaded.search === '?touch=1' && reloaded.challenge === null,
      `${stripped.search} -> ${reloaded.search}, haaste ${reloaded.challenge}`);

    await junkCtx.close();
  }

  /* --- B: haasteen vastaanotto ei kirjoita yhtään tavua --- */
  /*
   * DESIGN.md kohta 6 luettelee kaikki kuusi localStorage-avainta. Ne kylvetään
   * tunnetuilla arvoilla, sivu ladataan haastelinkillä ja avaimet luetaan
   * uudelleen: haaste elää istunnon muistissa eikä koske tallennukseen,
   * pistetauluun eikä pelidataan. Sama vaatimus kuin esittelytilalla, ja siksi
   * se todistetaan samalla tavalla — mittaamalla, ei lupaamalla.
   */
  {
    const cleanCtx = await browser.newContext();
    const cp = await cleanCtx.newPage();
    const quietErrors = [];
    cp.on('pageerror', (e) => quietErrors.push(`[haaste pageerror] ${e.message}`));
    cp.on('console', (m) => {
      const text = m.text();
      if (m.type() === 'error' && !text.includes('favicon')) quietErrors.push(`[haaste console] ${text}`);
    });

    await cp.goto(base, { waitUntil: 'networkidle' });
    const before = await cp.evaluate(() => {
      const seed = {
        'sfb3.save.v2': JSON.stringify({
          lives: 3, coins: 7, score: 111, power: { type: 'shroom', level: 2 },
          reserve: null, world: 1, node: 'w2-1', cleared: { 'w1-1': true },
          worldsOpen: 2, usedSaveState: false, continues: 1,
        }),
        'sfb3.savestate.1': JSON.stringify({ label: '2-1', at: 1 }),
        'sfb3.savestate.2': JSON.stringify({ label: '3-2', at: 2 }),
        'sfb3.savestate.3': JSON.stringify({ label: '4-3', at: 3 }),
        'sfb3.scores.v1': JSON.stringify([
          { name: 'MINÄ', score: 777, world: 1, level: '1-1', at: 1, version: 'x' },
        ]),
        'sfb3.telemetry.v1': JSON.stringify([{ t: 'death', id: '1-1', x: 5, y: 5 }]),
        'sfb3.fx.v1': 'crt',
        'sfb3.touch.v1': 'rulla',
      };
      localStorage.clear();
      for (const [k, v] of Object.entries(seed)) localStorage.setItem(k, v);
      // Avainjärjestys ei ole taattu, joten se lajitellaan ennen vertailua —
      // muuten testi voisi punastua pelkästä järjestyksestä.
      const all = [];
      for (let i = 0; i < localStorage.length; i++) all.push(localStorage.key(i));
      all.sort();
      return JSON.stringify(all.map((k) => [k, localStorage.getItem(k)]));
    });

    await cp.goto(`${base}?s=45200&n=OLLI&l=2-3`, { waitUntil: 'networkidle' });
    await cp.waitForTimeout(400);
    const after = await cp.evaluate(() => {
      const game = window.sfb3;
      // Ruutuja pyöritetään hetki: haaste ei saa vuotaa tallennukseen
      // myöskään sen jälkeen kun alkuruutu on ehtinyt piirtyä ja liikkua.
      for (let f = 0; f < 120; f++) { game.step(); game.render(); }
      game.toHighScores();
      for (let f = 0; f < 30; f++) { game.step(); game.render(); }
      game.toTitle();
      const all = [];
      for (let i = 0; i < localStorage.length; i++) all.push(localStorage.key(i));
      all.sort();
      return {
        storage: JSON.stringify(all.map((k) => [k, localStorage.getItem(k)])),
        challenge: game.challenge ? { ...game.challenge } : null,
        keys: all.join(' '),
      };
    });

    expect('haasteen vastaanotto ei kirjoita yhtään tavua selaimen muistiin',
      before === after.storage && !!after.challenge && after.challenge.score === 45200
      && quietErrors.length === 0,
      before === after.storage
        ? (after.challenge ? `${after.keys}` : 'haaste jäi lukematta')
        : 'tallennus muuttui');

    await cleanCtx.close();
  }
}

/* ----------------------------- peliohjain -------------------------------- */
/*
 * Playwrightissa ei ole ohjainemulaatiota, mutta peli lukee ohjaimen
 * `navigator.getGamepads()`:sta joka pollilla eikä missään muualla. Siksi
 * valeohjain sivulla on rehellinen testi eikä kiertotie: se syöttää
 * täsmälleen sen rajapinnan jota oikea ohjain käyttää, ja oikea `Input.poll()`
 * lukee sen.
 *
 * Mukana on myös ääniluvan aukko, koska se on ohjaimen ominaisuus eikä äänen:
 * selain avaa AudioContextin vain käyttäjän eleestä, ja **ohjaimen napinpainallus
 * ei ole ele**. Sitä ei voi korjata yrittämällä uudestaan, joten testataan se
 * mitä oikeasti tehdään — kerrotaan asiasta ruudulla.
 */
{
  const gamepad = await page.evaluate(async () => {
    const checks = [];
    const failures = [];
    const expect = (name, ok, detail = '') => {
      checks.push({ name, ok, detail });
      if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
    };
    const { Input } = await import('/src/core/input.js');
    const { Music, isMuted, toggleMute } = await import('/src/core/audio.js');
    const game = window.sfb3;

    const realGetGamepads = navigator.getGamepads.bind(navigator);
    let pads = [];
    navigator.getGamepads = () => pads;

    /** Standardin muotoinen ohjain: 16 nappia, kaksi akselia. */
    const mkPad = (down = [], axes = [0, 0], mapping = 'standard') => ({
      index: 0, id: 'testipad', connected: true, mapping, timestamp: 0,
      buttons: Array.from({ length: 16 }, (_, i) => ({
        pressed: down.includes(i), touched: down.includes(i), value: down.includes(i) ? 1 : 0,
      })),
      axes,
    });

    const clear = () => {
      pads = [];
      dispatchEvent(new Event('blur'));   // nollaa näppäimet ja latchin
      Input.poll();
      Input.poll();
    };
    const held = () => {
      Input.poll();
      return Object.entries(Input.held).filter(([, v]) => v).map(([k]) => k).sort().join(',');
    };
    const key = (type, code) => dispatchEvent(new KeyboardEvent(type, { code, bubbles: true }));

    /* --- napit tulevat perille oikeina toimintoina --- */
    clear();
    pads = [mkPad([0])];
    const jump = held();
    pads = [mkPad([2])];
    const run = held();
    pads = [mkPad([9])];
    const start = held();
    pads = [mkPad([14])];
    const dpadLeft = held();
    expect('ohjaimen napit tulevat peliin oikeina toimintoina',
      jump === 'jump' && run === 'run' && start === 'start' && dpadLeft === 'left',
      `0="${jump}" 2="${run}" 9="${start}" 14="${dpadLeft}"`);

    /* --- tatti: kuollut alue pitää ja sen yli ohjaa --- */
    clear();
    pads = [mkPad([], [-1, 0])];
    const stickLeft = held();
    pads = [mkPad([], [-0.2, 0])];
    const stickIdle = held();
    pads = [mkPad([], [0, 0.9])];
    const stickDown = held();
    pads = [mkPad([], [0, -0.39])];
    const stickAlmost = held();
    expect('tatti ohjaa kuolleen alueen ulkopuolella eikä sisäpuolella',
      stickLeft === 'left' && stickIdle === '' && stickDown === 'down' && stickAlmost === '',
      `-1="${stickLeft}" -0.2="${stickIdle}" +0.9="${stickDown}" -0.39="${stickAlmost}"`);

    /* --- molemmat elossa yhtä aikaa: kumpikaan ei kumoa toista --- */
    clear();
    key('keydown', 'ArrowRight');
    const keyOnly = held();
    pads = [mkPad([0])];
    const both = held();
    key('keyup', 'ArrowRight');
    const padOnly = held();
    clear();
    expect('näppäimistö ja ohjain ovat elossa yhtä aikaa',
      keyOnly === 'right' && both === 'jump,right' && padOnly === 'jump',
      `näppäin "${keyOnly}" molemmat "${both}" ohjain "${padOnly}"`);

    /* --- irronnut tai vajaa ohjain ei saa kaataa pollia --- */
    clear();
    let crash = '';
    const survives = (label, value) => {
      pads = value;
      try { Input.poll(); } catch (e) { crash += `${label}: ${e.message}; `; }
    };
    survives('null-paikka', [null]);
    survives('tyhjä lista', []);
    survives('undefined-paikka', [undefined]);
    survives('connected=false', [{ ...mkPad([0]), connected: false }]);
    survives('ei nappeja eikä akseleita', [{ index: 0, id: 'rikki', connected: true, mapping: 'standard' }]);
    survives('lyhyt akselilista', [{ ...mkPad([]), axes: [] }]);
    survives('yhden akselin ohjain', [{ ...mkPad([]), axes: [0.9] }]);
    survives('NaN akselilla', [{ ...mkPad([]), axes: [NaN, NaN] }]);
    navigator.getGamepads = () => null;
    try { Input.poll(); } catch (e) { crash += `getGamepads null: ${e.message}; `; }
    navigator.getGamepads = () => pads;
    pads = [];
    Input.poll();
    const leftovers = Object.entries(Input.held).filter(([, v]) => v).map(([k]) => k).join(',');
    expect('irronnut tai vajaa ohjain ei kaada eikä jätä nappeja pohjaan',
      crash === '' && leftovers === '', crash || `jäi pohjaan: ${leftovers}`);

    /* --- ei-standardi kuvaus: napit luetaan, akseleita ei --- */
    clear();
    pads = [mkPad([0], [-1, 0], '')];
    const odd = held();
    clear();
    pads = [mkPad([], [0, -1], 'vendor-specific')];
    const oddAxis = held();
    clear();
    expect('ei-standardi ohjain ei ohjaa akseleillaan mutta napit toimivat',
      odd === 'jump' && oddAxis === '',
      `napit+akseli "${odd}" pelkkä akseli "${oddAxis}"`);

    /* --- ohjaimen nappi ei ole ele, näppäin on --- */
    clear();
    const realGesture = Input.onGesture;
    let gestures = 0;
    Input.onGesture = () => { gestures++; if (realGesture) realGesture(); };
    pads = [mkPad([0])];
    Input.poll();
    Input.poll();
    const afterPad = gestures;
    key('keydown', 'KeyZ');
    key('keyup', 'KeyZ');
    const afterKey = gestures;
    dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }));
    const afterPointer = gestures;
    Input.onGesture = realGesture;
    clear();
    /* Lukumäärä ei ole yksi vaan kaksi, koska tämä testitiedosto kutsuu itse
     * `Input.install()`in uudestaan ylempänä ja kuuntelijoita on siksi kaksi
     * kerrosta. Väite ei ole "tasan kerran" vaan se mikä oikeasti ratkaisee:
     * **ohjaimesta ei nolla kertaa, näppäimestä ja osoittimesta joka kerta.** */
    expect('ääniluvan yritys lähtee eleestä, ei ohjaimen napista',
      afterPad === 0 && afterKey > 0 && afterPointer > afterKey,
      `ohjain ${afterPad} näppäin ${afterKey} osoitin ${afterPointer}`);

    /* --- ääniloukku: mitä ruudulla lukee, milloin ja kenelle --- */
    const wasMuted = isMuted();
    if (wasMuted) toggleMute();
    const realScene = game.scene;
    const realTrack = Music.current;
    const realAudioState = game.audioState;
    Music.current = null;               // ei aloiteta samaa raitaa satoja kertoja
    game.scene = { update() {}, draw() {} };
    // Tunnelmaefektit pois: kuumuuden väreily muuttaa pikseleitä joka framella
    // ja tekisi alla olevasta pikselivertailusta arpapeliä.
    game.fx.setAmbience(null, null);
    const resetHint = () => {
      game.audioHintOff = false;
      game.audioHintWasUp = false;
      game.flashTimer = 0;
      game.flashIsHint = false;
      game.flash = '';
    };
    const steps = (n) => { for (let i = 0; i < n; i++) game.step(); };

    // (a) ääni käynnissä: ohjaimella pelataan pitkään eikä mitään sanota
    game.audioState = () => 'running';
    resetHint();
    clear();
    pads = [mkPad([0])];
    steps(300);
    const whenFine = game.audioHintVisible === true;

    // (b) ääni kiinni ja ohjaimelta tulee syötettä: sanotaan heti, ei kellon jälkeen
    game.audioState = () => 'suspended';
    resetHint();
    game.step();
    const atOnce = game.audioHintVisible === true;
    const text = game.flash;
    steps(300);
    const stillUp = game.audioHintVisible === true;   // uusitaan, ei umpeudu alta

    // (c) ääni lähtee: vihje katoaa samalla framella
    game.audioState = () => 'running';
    game.step();
    const gone = game.audioHintVisible === true;

    // (d) selaimessa ei ole Web Audiota ollenkaan: ei nalkuteta turhaan
    game.audioState = () => 'none';
    resetHint();
    steps(300);
    const noWebAudio = game.audioHintVisible === true;

    expect('ääniloukun vihje näkyy heti kun ääni on kiinni ja ohjain puhuu',
      !whenFine && atOnce && text === 'OHJAIN EI AVAA ÄÄNTÄ - PAINA NÄPPÄINTÄ'
      && stillUp && !gone && !noWebAudio,
      `käynnissä ${whenFine} heti ${atOnce} pysyy ${stillUp} äänen jälkeen ${gone}`
      + ` ei-audiota ${noWebAudio} teksti "${text}"`);

    /* (e) Väärä hälytys on se mitä tässä ratkaisussa nimenomaan ei saa olla:
     * näppäimistöpelaaja avaa äänen ensimmäisellä painalluksellaan, ja jos
     * ehto katsoisi pelkkää "syötettä" hän näkisi vilauksen siitä muutaman
     * framen ajan sillä välin kun `resume()` etenee. Ohjain saa olla kytkettynä
     * — se ei ole rikos, se on pöydällä. */
    game.audioState = () => 'suspended';
    resetHint();
    clear();
    pads = [mkPad()];                 // kytketty, mutta kukaan ei koske siihen
    key('keydown', 'ArrowRight');
    steps(300);
    const keyboardNagged = game.audioHintVisible === true;
    key('keyup', 'ArrowRight');
    clear();
    expect('näppäimistöpelaaja ei näe ääniloukun vihjettä vaikka ohjain on kiinni',
      !keyboardNagged, `näkyi ${keyboardNagged}`);

    // (f) oikea ilmoitus voittaa: se on vastaus siihen mitä pelaaja juuri teki
    game.audioState = () => 'suspended';
    resetHint();
    pads = [mkPad([0])];
    steps(3);
    const hintFirst = game.audioHintVisible === true;
    game.toast('TILA 1 LADATTU');
    steps(3);
    const realWins = game.flash === 'TILA 1 LADATTU' && game.audioHintVisible === false;
    steps(120);                        // ilmoitus umpeutuu
    const hintReturns = game.audioHintVisible === true;
    expect('oikea ilmoitus voittaa vihjeen, ja vihje palaa itse',
      hintFirst && realWins && hintReturns,
      `vihje ${hintFirst} ilmoitus "${game.flash}" voitti ${realWins} palasi ${hintReturns}`);

    // (g) vihje on oikeasti ruudulla eikä vain lipussa
    const strip = () => Array.from(game.ctx.getImageData(0, 0, 320, 14).data).join(',');
    game.audioState = () => 'running';
    resetHint();
    game.render();
    const without = strip();
    game.render();
    const withoutAgain = strip();
    game.audioState = () => 'suspended';
    resetHint();
    steps(2);
    game.render();
    const withHint = strip();
    game.audioState = () => 'running';
    game.step();
    game.render();
    const afterUnlock = strip();
    expect('vihje piirtyy ilmoitusriville ja katoaa kun ääni lähtee',
      without === withoutAgain && withHint !== without && afterUnlock === without,
      `vakaa ${without === withoutAgain}, erosi ${withHint !== without},`
      + ` palasi ${afterUnlock === without}`);

    /* (h) Kuittaus ohjaimen napilla. Se on ainoa kuittaus jolla on merkitystä:
     * näppäimellä kuittaava avaa samalla äänen, joten vihje olisi mennyt
     * muutenkin. Ohjaimella kuittaava on valinnut hiljaisuuden — eikä ääni
     * lähde siitä painalluksesta, joten valinnan pitää pysyä. */
    game.audioState = () => 'suspended';
    resetHint();
    clear();
    pads = [mkPad([14])];              // ristiohjain vasemmalle: ehto täyttyy
    steps(4);
    const upBeforePress = game.audioHintVisible === true;
    pads = [mkPad([14, 0])];           // ja nyt hyppynappi eli uusi painallus
    game.step();
    const afterPress = game.audioHintVisible === true;
    const dismissed = game.audioHintOff === true;
    steps(300);
    const stayedGone = game.audioHintVisible === true;
    const stillStuck = game.audioState() !== 'running';
    expect('ohjaimen napilla kuittaaminen sulkee vihjeen koko istunnoksi',
      upBeforePress && !afterPress && dismissed && !stayedGone && stillStuck,
      `ennen ${upBeforePress} jälkeen ${afterPress} kuitattu ${dismissed}`
      + ` pysyi poissa ${!stayedGone}`);

    // (i) kuittaus elää vain muistissa, ei selaimen muistissa
    const stored = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (/audio|hint|vihje|gamepad|ohjain/i.test(k)) stored.push(k);
    }
    expect('vihjeen kuittaus ei jätä uutta avainta selaimen muistiin',
      stored.length === 0, stored.join(' '));

    if (realAudioState) game.audioState = realAudioState; else delete game.audioState;
    resetHint();
    game.scene = realScene;
    Music.current = realTrack;
    if (wasMuted !== isMuted()) toggleMute();
    clear();
    navigator.getGamepads = realGetGamepads;

    return { checks, failures };
  });
  report.checks.push(...gamepad.checks);
  report.failures.push(...gamepad.failures);
}

/* -------------------------------- aika-ajo ------------------------------- */
/*
 * AIKA-AJO on tila johon mennään erikseen, joten sen väitteitä on kaksi lajia:
 * mitä tilassa tapahtuu, ja mitä tavallisessa kierroksessa **ei** tapahdu.
 * Jälkimmäinen on se puoli joka rikkoutuu hiljaa — kukaan ei huomaa että
 * tavallinen kenttä alkoi laskea jotain — joten se mitataan framejonona eikä
 * luettuna koodista.
 */
{
  const race = await page.evaluate(async () => {
    const checks = [];
    const failures = [];
    const expect = (name, ok, detail = '') => {
      checks.push({ name, ok, detail });
      if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
    };
    const game = window.sfb3;
    const { LevelScene, VIEW_W, VIEW_H } = await import('/src/scenes/level.js');
    const { MAX_RUN } = await import('/src/entities/player.js');
    const { getLevel, levelIds } = await import('/src/data/levels.js');
    const { Save } = await import('/src/core/save.js');
    const { captureState, restoreState } = await import('/src/core/savestate.js');
    const { TILE } = await import('/src/gfx/tiles.js');
    const font = await import('/src/gfx/font.js');

    /* Moduuli haetaan varovasti. Kun sitä ei vielä ole, jokainen alla oleva
     * väite saa kertoa oman puuttumisensa mittana — punainen lohko on
     * hyödyllinen vasta kun se kertoo mitä puuttuu eikä pelkkää poikkeusta. */
    let TA = null;
    let taError = '';
    try {
      TA = await import('/src/core/timeattack.js');
    } catch (e) {
      taError = String((e && e.message) || e);
    }

    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false, reset: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const reset = (extra = {}) => {
      game.timeAttack = false;
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {}, ...extra,
      };
      game.finishLevel = () => {};
    };
    const marks = (...v) => v;

    /* Arvonta kiinni: kaksi kierrosta samasta kentästä ovat vertailukelpoisia
     * vasta kun ne saavat saman satunnaislukujonon. */
    const realRandom = Math.random;
    let seed = 0;
    const seeded = () => {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      return seed / 2147483648;
    };

    const runTrace = (id, timeAttack, frames = 600, best = null) => {
      seed = 20260810;
      Math.random = seeded;
      reset();
      if (best) game.state.bestTimes[id] = best;
      game.timeAttack = timeAttack;
      const scene = new LevelScene(game, id);
      const input = mkInput();
      const rows = [];
      let transit = 0;
      for (let f = 0; f < frames; f++) {
        input.held.right = true;
        input.held.run = (f % 130) < 90;
        input.held.jump = (f % 41) < 11;
        input.pressed.jump = (f % 41) === 0;
        if (scene.player.transit) transit++;
        scene.update(input);
        const p = scene.player;
        rows.push([
          Math.round(p.x * 100), Math.round(p.y * 100),
          Math.round(p.vx * 1000), Math.round(p.vy * 1000),
          scene.time, scene.timeSub, scene.tick, scene.state,
          game.state.score, game.state.coins,
          Math.round(scene.cam.x * 100), Math.round(scene.cam.y * 100),
        ].join(','));
      }
      Math.random = realRandom;
      game.timeAttack = false;
      return { scene, rows, transit };
    };

    /* 1. Tavallinen kierros on muuttumaton. Ei rakenteesta vaan framejonona:
     * sama kenttä, sama syöte, sama arvontasiemen, tila päällä ja pois. */
    {
      const plain = runTrace('1-1', false);
      const timed = runTrace('1-1', true, 600,
        { frames: 700, marks: marks(40, 90, 150, 210, 280, 340, 420, 500) });
      let diff = 0;
      let first = '';
      for (let i = 0; i < plain.rows.length; i++) {
        if (plain.rows[i] === timed.rows[i]) continue;
        diff++;
        if (!first) first = ` ensimmäinen frame ${i}: ${plain.rows[i]} vs ${timed.rows[i]}`;
      }
      expect('aika-ajo ei liikuta tavallista kierrosta yhdelläkään framella',
        diff === 0 && plain.scene.race === null && timed.scene.race !== null,
        `${plain.rows.length} framea, eroja ${diff};${first} tavallisessa ajokello`
        + ` ${plain.scene.race === null ? 'puuttuu' : 'ON — sitä ei saa olla'},`
        + ` aika-ajossa ${timed.scene.race ? 'on' : 'PUUTTUU'}`);
    }

    /* 2. Ilmestyviä lukemia on jo neljä nurkassa. Aika-ajon jako on viides, ja
     * se mitataan pikseleinä: paljonko uutta mustetta, paljonko peitettyä, ja
     * kuinka lähelle vanhaa se tulee. Mittaus on nyt koko ikkuna eikä nauha —
     * `drawOverlay` piirtää läpinäkyvälle pohjalle, joten "vanhaa mustetta" on
     * täsmälleen se mitä muut lukemat piirsivät. */
    {
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d');
      const shot = (timeAttack, tweak) => {
        reset({ lives: 9999, coins: 99, score: 9999999 });
        game.timeAttack = timeAttack;
        const scene = new LevelScene(game, '1-1');
        scene.tick = 12;
        scene.time = 300;
        scene.player.star = 400;          // oikean laidan lokero varattuna
        scene.player.pMeter = 90;
        scene.player.powerLevel = 3;
        scene.player.type = 'leaf';
        if (tweak) tweak(scene);
        g.clearRect(0, 0, VIEW_W, VIEW_H);
        scene.drawOverlay(g);
        game.timeAttack = false;
        return g.getImageData(0, 0, VIEW_W, VIEW_H).data;
      };
      const plain = shot(false, null);
      const variants = [
        (s) => { if (s.race) { s.race.best = null; s.race.delta = null; } },
        (s) => { if (s.race) { s.race.delta = -92; s.race.flash = 0; } },
        (s) => { if (s.race) { s.race.delta = 137; s.race.flash = 0; } },
        (s) => { if (s.race) { s.race.delta = 137; s.race.flash = 5; } },
        (s) => { if (s.race) { s.race.delta = 60 * 615; s.race.flash = 0; } },
        (s) => { if (s.race) { s.race.delta = -60 * 615; s.race.flash = 0; } },
      ];
      let covered = 0;
      let added = 0;
      const box = { x0: 1e9, x1: -1e9, y0: 1e9, y1: -1e9 };
      const newCols = new Set();
      for (const tweak of variants) {
        const shotB = shot(true, tweak);
        for (let i = 0; i < plain.length; i += 4) {
          const wasInk = plain[i + 3] > 0;
          const same = plain[i] === shotB[i] && plain[i + 1] === shotB[i + 1]
            && plain[i + 2] === shotB[i + 2] && plain[i + 3] === shotB[i + 3];
          if (same) continue;
          if (wasInk) { covered++; continue; }
          added++;
          const px = (i / 4) % VIEW_W;
          const py = Math.floor((i / 4) / VIEW_W);
          newCols.add(px);
          if (px < box.x0) box.x0 = px;
          if (px > box.x1) box.x1 = px;
          if (py < box.y0) box.y0 = py;
          if (py > box.y1) box.y1 = py;
        }
      }
      /* Etäisyys mitataan **siltä riviltä jolla lukema on**, ei koko nauhasta:
       * kolikkorivi kulkee lukeman alta eri rivillä, ja sarakkeittain luettuna
       * se näyttäisi törmäykseltä vaikka mikään ei ole päällekkäin. */
      const oldCols = new Set();
      for (let i = 0; i < plain.length; i += 4) {
        const py = Math.floor((i / 4) / VIEW_W);
        if (py < box.y0 || py > box.y1) continue;
        if (plain[i + 3] > 0) oldCols.add((i / 4) % VIEW_W);
      }
      let gap = 1e9;
      for (const nx of newCols) for (const ox of oldCols) gap = Math.min(gap, Math.abs(nx - ox));
      expect('aika-ajon jako ei peitä yhtään olemassa olevaa lukemaa',
        added > 0 && covered === 0 && gap >= 2,
        added ? `uutta mustetta ${added} px, peitettyä ${covered} px, laatikko x`
          + ` ${box.x0}-${box.x1} y ${box.y0}-${box.y1} (HUD-nauhan sisällä),`
          + ` lähin vanha muste ${gap === 1e9 ? '-' : `${gap} px`}`
          : 'lukemaa ei piirretä lainkaan: 0 px uutta mustetta');
    }

    /* 2 b. Sama mitta maalikuvalle. Rako lipputekstin ja korttikuvan välissä
     * näyttää tyhjältä mutta on ensimmäiset kahdeksan framea seitsemän pikseliä
     * matalampi, koska `drawBanner` iskee silloin isommalla kirjasimella. */
    {
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d');
      const shot = (result, age) => {
        reset({ lives: 4, coins: 37, score: 128400 });
        game.timeAttack = !!result;
        const scene = new LevelScene(game, '1-1');
        scene.tick = 12;
        scene.time = 271;
        scene.state = 'clear';
        scene.stateTimer = age;
        scene.wonCard = 'shroom';
        if (result) scene.raceResult = result;
        g.clearRect(0, 0, VIEW_W, VIEW_H);
        scene.drawBanners(g);
        game.timeAttack = false;
        return g.getImageData(0, 0, VIEW_W, VIEW_H).data;
      };
      const results = [
        { frames: 4823, best: null, record: true },
        { frames: 4823, best: 5100, record: true },
        { frames: 5400, best: 5100, record: false },
        { frames: 359999, best: 358000, record: false },
      ];
      let covered = 0;
      let added = 0;
      let rows = [1e9, -1e9];
      for (const age of [2, 40]) {
        const plain = shot(null, age);
        for (const r of results) {
          const timed = shot(r, age);
          /* Vain lippu ja kortti: `drawBanners` piirtää nimenomaan ne, ja
           * ilmestyvien lukemien oma mitta on väitteessä 2. */
          for (let i = 0; i < VIEW_H * VIEW_W * 4; i += 4) {
            const wasInk = plain[i + 3] > 0;
            const same = plain[i] === timed[i] && plain[i + 1] === timed[i + 1]
              && plain[i + 2] === timed[i + 2] && plain[i + 3] === timed[i + 3];
            if (same) continue;
            if (wasInk) { covered++; continue; }
            added++;
            const py = Math.floor((i / 4) / VIEW_W);
            if (py < rows[0]) rows[0] = py;
            if (py > rows[1]) rows[1] = py;
          }
        }
      }
      expect('aika-ajon maalirivi ei peitä maalitekstiä eikä korttikuvaa',
        added > 0 && covered === 0,
        added ? `neljä lopputulosta kahdella iskuvaiheella: uutta mustetta ${added} px,`
          + ` peitettyä ${covered} px, rivit ${rows[0]}-${rows[1]}`
          : 'maaliriviä ei piirretä lainkaan');
    }

    /* 3. Sama kello, eri jako. Jos jako olisi AIKA-kellon toisinto, sama AIKA
     * antaisi saman jaon riippumatta siitä mitä pelaaja on aiemmin tehnyt. */
    {
      const a = runTrace('1-1', true, 500,
        { frames: 900, marks: marks(30, 70, 120, 180, 240, 300, 380, 460) });
      const b = runTrace('1-1', true, 500,
        { frames: 900, marks: marks(90, 190, 320, 480, 640, 800, 900, 980) });
      const ra = a.scene.race;
      const rb = b.scene.race;
      const fmt = (d) => (TA && d !== null && d !== undefined ? TA.formatDelta(d) : String(d));
      expect('sama AIKA-lukema mutta eri jako: jako ei ole kellon toisinto',
        !!ra && !!rb && a.scene.time === b.scene.time
          && ra.delta !== null && rb.delta !== null && ra.delta !== rb.delta,
        ra && rb ? `AIKA ${a.scene.time} molemmissa, jako ${fmt(ra.delta)} vs ${fmt(rb.delta)}`
          : `ajokelloa ei ole (${taError})`);
    }

    /* 4. Ja toisin päin: kulunut aika **piirretään**, koska AIKA-kelloa ei enää
     * ole (18.8.2026: kolikot ovat aika). Ennen tämä väite oli päinvastainen ja
     * sen perustelu oli laskukaava — kulunut aika oli AIKA-lukeman toisinto
     * framelleen — mutta toisinnon toinen puoli katosi, ja kilpa jonka kelloa
     * ei näe on kilpa jota ei voi ajaa. Väite on nyt kaksiosainen: kello on
     * ruudulla aika-ajossa **eikä** ole tavallisella kierroksella. */
    {
      const shot = (timed) => {
        seed = 7;
        Math.random = seeded;
        reset();
        game.timeAttack = timed;
        const scene = new LevelScene(game, '1-1');
        const input = mkInput();
        for (let f = 0; f < 240; f++) {
          input.held.right = true;
          input.held.jump = (f % 41) < 11;
          input.pressed.jump = (f % 41) === 0;
          scene.update(input);
        }
        const c = document.createElement('canvas');
        c.width = VIEW_W;
        c.height = VIEW_H;
        const g = c.getContext('2d');
        g.clearRect(0, 0, VIEW_W, VIEW_H);
        scene.drawOverlay(g);
        Math.random = realRandom;
        game.timeAttack = false;
        /* Ylin rivi keskeltä: kello on siellä ja vain siellä. */
        const d = g.getImageData(120, 4, 80, 12).data;
        let ink = 0;
        for (let i = 3; i < d.length; i += 4) if (d[i] > 0) ink++;
        return { ink, frames: scene.race ? scene.race.frames : null };
      };
      const timed = shot(true);
      const plain = shot(false);
      expect('aika-ajossa kulunut aika on ruudulla, tavallisella kierroksella ei',
        timed.ink > 20 && plain.ink === 0 && timed.frames > 0,
        `aika-ajossa ${timed.ink} px mustetta (ajokello ${timed.frames} framea),`
        + ` tavallisessa ${plain.ink} px`);
    }

    /* 5. Tilan lataus. Tähtilogiikkaa ei kahdenneta: tila vain kieltäytyy, ja
     * merkintä jää siihen missä se on aina ollut. */
    {
      reset();
      game.pendingNode = { id: 'w1-1', level: '1-1' };
      game.scene = new LevelScene(game, '1-1');
      game.scene.time = 275;
      game.slot = 1;
      game.quickSave();
      game.scene.time = 100;
      game.quickLoad();
      const plainLoaded = game.scene.time;
      const plainStar = !!game.state.usedSaveState;

      reset();
      game.timeAttack = true;
      game.pendingNode = { id: 'w1-1', level: '1-1' };
      game.scene = new LevelScene(game, '1-1');
      game.scene.time = 100;
      const before = game.scene;
      game.quickLoad();
      const sameScene = game.scene === before;
      const timedTime = game.scene.time;
      const timedStar = !!game.state.usedSaveState;
      game.timeAttack = false;
      expect('aika-ajossa tilaa ei ladata, eikä tähtimerkintä synny',
        plainLoaded === 275 && plainStar && sameScene && timedTime === 100 && !timedStar,
        `tavallinen: AIKA ${plainLoaded} (odotus 275), tähti ${plainStar};`
        + ` aika-ajo: kohtaus ${sameScene ? 'sama' : 'VAIHTUI'}, AIKA ${timedTime}`
        + ` (odotus 100), tähti ${timedStar}`);
    }

    /* 6. Tauko. Ajokello käy, kenttäkello ei — jälkimmäinen tappaa, ja valikossa
     * kuolemiselle ei ole vastausta. */
    {
      reset();
      game.timeAttack = true;
      game.pendingNode = { id: 'w1-1', level: '1-1' };
      const scene = new LevelScene(game, '1-1');
      game.scene = scene;
      game.paused = true;
      const t0 = scene.time;
      const sub0 = scene.timeSub;
      const tick0 = scene.tick;
      const f0 = scene.race ? scene.race.frames : -1;
      for (let i = 0; i < 120; i++) game.step();
      const f1 = scene.race ? scene.race.frames : -1;
      game.paused = false;
      game.timeAttack = false;

      reset();
      const plainScene = new LevelScene(game, '1-1');
      game.scene = plainScene;
      game.paused = true;
      const plainTick = plainScene.tick;
      for (let i = 0; i < 120; i++) game.step();
      const plainAfter = plainScene.tick;
      game.paused = false;
      expect('tauko ei pysäytä ajokelloa, mutta kenttäkello seisoo valikossa',
        f1 - f0 === 120 && scene.time === t0 && scene.timeSub === sub0 && scene.tick === tick0
          && plainAfter === plainTick,
        `120 framea taukoa: ajokello ${f0}->${f1}, AIKA ${t0}->${scene.time},`
        + ` timeSub ${sub0}->${scene.timeSub}, tick ${tick0}->${scene.tick};`
        + ` tavallinen kierros tick ${plainTick}->${plainAfter}`);
    }

    /* 7. Tallennusmuoto molempiin suuntiin. */
    {
      const KEY = 'sfb3.save.v2';
      const keep = localStorage.getItem(KEY);
      const old = {
        lives: 3, coins: 17, score: 12345, power: { type: 'leaf', level: 3 },
        reserve: 'shroom', world: 2, node: 'w3-2', cleared: { 'w1-1': true }, worldsOpen: 3,
        usedSaveState: true, continues: 2, secrets: { '1-1': ['a'] },
      };
      localStorage.setItem(KEY, JSON.stringify(old));
      const loaded = Save.load();
      const oldKept = Object.keys(old)
        .filter((k) => JSON.stringify(loaded[k]) !== JSON.stringify(old[k]));
      let emptyTimes = false;
      try {
        emptyTimes = !!TA && Object.keys(TA.bestTimes(loaded)).length === 0;
      } catch { emptyTimes = false; }

      Save.write({ ...loaded, bestTimes: { '1-1': { frames: 812, marks: marks(1, 2, 3, 4, 5, 6, 7, 8) } } });
      const raw = JSON.parse(localStorage.getItem(KEY));
      const wrote = !!(raw.bestTimes && raw.bestTimes['1-1'] && raw.bestTimes['1-1'].frames === 812);
      /* Vanha lataaja on tasan tämä: vanhat oletukset, ja tallennus niiden
       * päälle. Uusi kenttä on sille tuntematon avain jota se ei lue. */
      const viaOld = {
        lives: 4, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: null, cleared: {}, worldsOpen: 1, usedSaveState: false,
        continues: 0, secrets: {}, ...raw,
      };
      const oldBroken = Object.keys(old)
        .filter((k) => JSON.stringify(viaOld[k]) !== JSON.stringify(old[k]));
      if (keep === null) localStorage.removeItem(KEY); else localStorage.setItem(KEY, keep);
      expect('parhaat ajat kulkevat vanhan tallennuksen läpi molempiin suuntiin',
        oldKept.length === 0 && emptyTimes && wrote && oldBroken.length === 0,
        `vanha -> uusi: ${Object.keys(old).length} kenttää ennallaan`
        + `${oldKept.length ? ` paitsi ${oldKept.join(',')}` : ''}, ajat ${emptyTimes ? '{}' : 'EI {}'};`
        + ` uusi -> vanha: ajat levyllä ${wrote}, vanhat kentät ehjiä`
        + ` ${Object.keys(old).length - oldBroken.length}/${Object.keys(old).length}`);
    }

    /* 7 b. Sama kysymys pikatallennukselle: vanha tilannekuva ei tunne kenttää
     * ollenkaan, ja `restoreState` asettaa `game.state`n suoraan. */
    {
      reset();
      game.pendingNode = { id: 'w1-1', level: '1-1' };
      game.scene = new LevelScene(game, '1-1');
      const snap = captureState(game);
      delete snap.gameState.bestTimes;
      let restored = false;
      let safe = false;
      let err = '';
      try {
        restored = restoreState(game, snap);
        safe = !!TA && Object.keys(TA.bestTimes(game.state)).length === 0;
      } catch (e) {
        err = String((e && e.message) || e);
      }
      expect('vanha pikatallennus ei jätä parhaita aikoja määrittelemättömäksi',
        restored && safe,
        `palautus ${restored}, ajat luettavissa ${safe}${err ? ` (${err})` : ''}`);
    }

    /* 8. Värit. Kaksi samannäköistä signaalia opettaa väärän luennan, joten
     * mitataan etäisyys jokaiseen HUDin väriin eikä katsota silmällä. */
    {
      const HUD_COLORS = ['#ffffff', '#ffd048', '#8fe04a', '#ff6060', '#f0b000', '#3a3a52',
        '#e04c3c', '#f8f8f8', '#c88c40', '#8fd0ff', '#ff8040', '#c85820', '#fff070', '#78c0ff',
        '#2a2a3e'];
      const LIT = ['#ffffff', '#ffd048', '#8fe04a', '#ff6060', '#f0b000', '#e04c3c',
        '#f8f8f8', '#c88c40', '#8fd0ff', '#ff8040', '#c85820', '#fff070', '#78c0ff'];
      const rgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
      const dist = (a, b) => {
        const x = rgb(a);
        const y = rgb(b);
        return Math.abs(x[0] - y[0]) + Math.abs(x[1] - y[1]) + Math.abs(x[2] - y[2]);
      };
      const lum = (h) => {
        const x = rgb(h);
        return 0.299 * x[0] + 0.587 * x[1] + 0.114 * x[2];
      };
      const cols = TA && TA.SPLIT_COLORS ? TA.SPLIT_COLORS : null;
      let worst = { d: 1e9, k: '-', v: '-', h: '-' };
      if (cols) {
        for (const k of ['ahead', 'behind']) {
          for (const h of HUD_COLORS) {
            const d = dist(cols[k], h);
            if (d < worst.d) worst = { d, k, v: cols[k], h };
          }
        }
      }
      const dimmest = Math.min(...LIT.map(lum));
      const noneLum = cols ? lum(cols.none) : 1e9;
      expect('aika-ajon värit eivät ole minkään muun HUD-lukeman värejä',
        !!cols && worst.d >= 120 && noneLum < dimmest,
        cols ? `lähin pari ${worst.k} ${worst.v} vs ${worst.h} = ${worst.d};`
          + ` "ei tietoa" ${cols.none} kirkkaus ${noneLum.toFixed(0)},`
          + ` himmein palava lukema ${dimmest.toFixed(0)}`
          : `värejä ei ole (${taError})`);
    }

    /* 9. Fontti. Puuttuva merkki ei heitä, se jättää reiän ja siirtää kohdistinta. */
    {
      const canvas = document.createElement('canvas');
      canvas.width = 16;
      canvas.height = 12;
      const g = canvas.getContext('2d');
      const missing = new Set();
      const strings = TA && TA.MODE_STRINGS ? TA.MODE_STRINGS : [];
      for (const s of strings) {
        for (const ch of String(s).toUpperCase()) {
          if (ch === ' ') continue;
          g.clearRect(0, 0, 16, 12);
          font.drawText(g, ch, 2, 2, { color: '#ffffff' });
          const d = g.getImageData(0, 0, 16, 12).data;
          let ink = 0;
          for (let i = 3; i < d.length; i += 4) if (d[i] > 0) ink++;
          if (!ink) missing.add(ch);
        }
      }
      expect('jokainen aika-ajon teksti on kirjoitettavissa tällä fontilla',
        strings.length > 0 && missing.size === 0,
        strings.length ? `${strings.length} merkkijonoa`
          + `${missing.size ? `, puuttuu: ${[...missing].join('')}` : ', ei reikiä'}`
          : `merkkijonoja ei ole (${taError})`);
    }

    /* 10. Ennätys korvautuu vain nopeammalla. */
    {
      const st = { bestTimes: {} };
      const seq = [];
      let err = '';
      try {
        if (TA) {
          TA.setBest(st, '1-1', { frames: 900, marks: marks(1, 2, 3, 4, 5, 6, 7, 8) });
          seq.push(TA.bestFor(st, '1-1').frames);
          TA.setBest(st, '1-1', { frames: 950, marks: marks(1, 2, 3, 4, 5, 6, 7, 8) });
          seq.push(TA.bestFor(st, '1-1').frames);
          TA.setBest(st, '1-1', { frames: 800, marks: marks(1, 2, 3, 4, 5, 6, 7, 8) });
          seq.push(TA.bestFor(st, '1-1').frames);
        }
      } catch (e) {
        err = String((e && e.message) || e);
      }
      expect('ennätys korvautuu vain nopeammalla ajalla',
        seq.join(',') === '900,900,800',
        seq.length ? `900 -> 950 -> 800 antaa ${seq.join(' ')}` : `ei mitattavissa (${taError}${err})`);
    }

    /* 11. Kentän kello ei kelpaa tavoiteajaksi, ja se on mittaus eikä mielipide:
     * budjetti suhteessa siihen mitä täysi juoksu kentän mitalla veisi. */
    {
      const rows = [];
      for (const id of levelIds()) {
        const def = getLevel(id);
        const floor = (def.rows[0].length * TILE) / MAX_RUN;
        rows.push({ id, ratio: (def.time * 24) / floor });
      }
      rows.sort((a, b) => a.ratio - b.ratio);
      const min = rows[0];
      const med = rows[Math.floor(rows.length / 2)];
      expect('kentän kello on määräaika eikä tavoiteaika',
        rows.length > 0 && min.ratio >= 3,
        `budjetti / täyden vauhdin alaraja: pienin ${min.ratio.toFixed(1)}x (${min.id}),`
        + ` mediaani ${med.ratio.toFixed(1)}x, ${rows.length} kenttää`);
    }

    /* 12. Nollaus kysyy ensin. */
    {
      reset({ bestTimes: { '1-1': { frames: 800, marks: marks(1, 2, 3, 4, 5, 6, 7, 8) } } });
      game.timeAttack = true;
      const step = () => (game.resetBestTimes ? game.resetBestTimes() : 'ei ole');
      const count = () => {
        try {
          return TA ? Object.keys(TA.bestTimes(game.state)).length : -1;
        } catch { return -1; }
      };
      const first = step();
      const afterFirst = count();
      const second = step();
      const afterSecond = count();
      game.timeAttack = false;
      expect('ajat nollataan vasta toisesta painalluksesta',
        first === 'arm' && afterFirst === 1 && second === 'cleared' && afterSecond === 0,
        `1. painallus "${first}" jättää ${afterFirst} aikaa,`
        + ` 2. painallus "${second}" jättää ${afterSecond}`);
    }

    /* 13. Jako liikkuu välipisteillä eikä joka framella — muuten se on kohina,
     * ei lukema. */
    {
      seed = 11;
      Math.random = seeded;
      reset({ bestTimes: { '1-1': { frames: 1500, marks: marks(120, 260, 400, 540, 680, 820, 960, 1100) } } });
      game.timeAttack = true;
      const scene = new LevelScene(game, '1-1');
      const input = mkInput();
      let changes = 0;
      let prev = scene.race ? scene.race.delta : null;
      for (let f = 0; f < 1200 && scene.state === 'play' && scene.race; f++) {
        input.held.right = true;
        input.held.run = true;
        input.held.jump = (f % 41) < 11;
        input.pressed.jump = (f % 41) === 0;
        scene.update(input);
        if (!scene.race) break;
        if (scene.race.delta !== prev) changes++;
        prev = scene.race.delta;
      }
      const crossed = scene.race ? scene.race.next : -1;
      const splits = TA && TA.RACE_SPLITS ? TA.RACE_SPLITS : -1;
      Math.random = realRandom;
      game.timeAttack = false;
      expect('jako päivittyy välipisteillä eikä joka framella',
        splits > 0 && crossed > 0 && changes === crossed && crossed <= splits,
        `1200 framea: ${crossed}/${splits} välipistettä ohitettu, jako vaihtui ${changes} kertaa`);
    }

    /* 14. Maali kirjoittaa ajan, ja tavallinen kierros ei kirjoita mitään.
     * Tämä on se polku joka kulkee `completeLevel`in ja `persist`in läpi, eli
     * ainoa jossa aika päätyy levylle asti. */
    {
      const KEY = 'sfb3.save.v2';
      const keep = localStorage.getItem(KEY);
      const finish = (frames, timeAttack) => {
        seed = 99;
        Math.random = seeded;
        game.timeAttack = timeAttack;
        const scene = new LevelScene(game, '1-1');
        const input = mkInput();
        for (let f = 0; f < frames; f++) {
          input.held.right = true;
          scene.update(input);
        }
        scene.completeLevel('shroom');
        Math.random = realRandom;
        game.timeAttack = false;
        return scene;
      };
      reset();
      const first = finish(200, true);
      const afterFirst = TA ? TA.bestFor(game.state, '1-1') : null;
      const onDisk = JSON.parse(localStorage.getItem(KEY) || '{}');
      const slower = finish(300, true);
      const afterSlower = TA ? TA.bestFor(game.state, '1-1') : null;
      const faster = finish(150, true);
      const afterFaster = TA ? TA.bestFor(game.state, '1-1') : null;
      reset();
      const plain = finish(120, false);
      const afterPlain = TA ? TA.bestFor(game.state, '1-1') : null;
      if (keep === null) localStorage.removeItem(KEY); else localStorage.setItem(KEY, keep);
      expect('maali kirjaa ajan aika-ajossa eikä kirjaa mitään tavallisessa kierroksessa',
        !!afterFirst && afterFirst.frames === 200 && first.raceResult.best === null
          && !!onDisk.bestTimes && onDisk.bestTimes['1-1'] && onDisk.bestTimes['1-1'].frames === 200
          && !!afterSlower && afterSlower.frames === 200 && slower.raceResult.record === false
          && !!afterFaster && afterFaster.frames === 150 && faster.raceResult.record === true
          && afterPlain === null && plain.raceResult === null,
        `200 framea -> ennätys ${afterFirst ? afterFirst.frames : 'ei'} (levyllä`
        + ` ${onDisk.bestTimes && onDisk.bestTimes['1-1'] ? onDisk.bestTimes['1-1'].frames : 'ei'}),`
        + ` 300 -> ${afterSlower ? afterSlower.frames : 'ei'} (uusi ennätys`
        + ` ${slower.raceResult && slower.raceResult.record}),`
        + ` 150 -> ${afterFaster ? afterFaster.frames : 'ei'} (uusi ennätys`
        + ` ${faster.raceResult && faster.raceResult.record});`
        + ` tavallinen kierros kirjasi ${afterPlain ? afterPlain.frames : 'ei mitään'}`);
    }

    reset();
    game.timeAttack = false;
    game.paused = false;
    game.toTitle();
    return { checks, failures };
  });
  report.checks.push(...race.checks);
  report.failures.push(...race.failures);
}

/* ------------------------- HUD-nauhan sarakkeet -------------------------- */
/*
 * KUKAAN EI SAA VUOTAA SARAKKEESTAAN.
 *
 * HUDin uusi jako (`HUD_X` `level.js`:ssä, `drawPanel` kartalla) on sarakkeita
 * joilla on mitatut rajat, ja mitattu raja vanhenee juuri niin hiljaa kuin
 * kaikki muutkin: yksi merkki lisää lukemaan, ja teksti kävelee naapurin
 * päälle ilman että mikään punastuu. Kirjoittaessa tämä tapahtui oikeasti —
 * kartan `KOLIKOT 99` ylsi 118:aan ja nimikilpi alkoi 112:sta.
 *
 * Väite luetaan pikseleistä eikä koodista: nauha piirretään **pahimmalla
 * mahdollisella tilalla** (9999 elämää, 99 kolikkoa, seitsennumeroiset
 * pisteet, pisin nielty kyky, pisin lähtölaskenta, pisin kentän nimi), ja
 * jokaisen musteellisen sarakkeen on osuttava johonkin sille riville
 * ilmoitettuun väliin. Väli on tässä tiedostossa käsin kirjoitettuna, koska
 * sen tehtävä on olla se *toinen* lähde: jos joku siirtää lukeman, tämä
 * punastuu ja pakottaa siirtämään myös perustelun.
 */
{
  const hud = await page.evaluate(async () => {
    const checks = [];
    const failures = [];
    const expect = (name, ok, detail = '') => {
      checks.push({ name, ok, detail });
      if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
    };
    const game = window.sfb3;
    const { LevelScene, VIEW_W, VIEW_H } = await import('/src/scenes/level.js');
    const { WorldMapScene } = await import('/src/scenes/worldmap.js');

    const BG = [0x10, 0x10, 0x18];
    /** Ne sarakkeet joilla on mustetta annetulla rivikaistalla. */
    const inkCols = (data, w, y0, y1) => {
      const cols = new Set();
      for (let y = y0; y <= y1; y++) {
        for (let x = 0; x < w; x++) {
          const i = (y * w + x) * 4;
          if (data[i + 3] === 0) continue;
          if (data[i] === BG[0] && data[i + 1] === BG[1] && data[i + 2] === BG[2]) continue;
          cols.add(x);
        }
      }
      return cols;
    };
    /** Sarakkeet jotka eivät mahdu yhteenkään sallittuun väliin. */
    const strays = (cols, ranges) => [...cols]
      .filter((x) => !ranges.some(([a, b]) => x >= a && x <= b))
      .sort((a, b) => a - b);
    const runs = (list) => {
      const out = [];
      for (const x of list) {
        const last = out[out.length - 1];
        if (last && x === last[1] + 1) last[1] = x;
        else out.push([x, x]);
      }
      return out.map(([a, b]) => (a === b ? `${a}` : `${a}-${b}`)).join(' ');
    };

    /* --- 1. kentän nurkat --- */
    {
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d');
      game.timeAttack = false;
      game.state = {
        lives: 9999, coins: 99, score: 9999999, power: { type: 'leaf', level: 3 },
        reserve: 'flower', world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1,
        cards: [], secrets: {}, usedSaveState: false, continues: 0, bestTimes: {},
      };
      const scene = new LevelScene(game, '1-1');
      scene.tick = 12;
      scene.time = 90;                    // kello kriisissä eli näkyvissä
      scene.player.pMeter = 999;
      /*
       * `powerLevel`, `type` ja `swallowed` ovat kaikki getterejä, ja tämä
       * lohko sijoitti niihin — `page.evaluate` ajaa löysässä tilassa, joten
       * sijoitukset olivat äänettömiä tyhjäkäyntejä ja koe mittasi mitä
       * konstruktori sattui antamaan. Yksi kirjoitus oikeaan kenttään tekee
       * kaikki kolme, koska nielty kyky **on** voimapaikka (19.8.2026).
       */
      scene.player.power = { type: 'magneetti', level: 5 };
      scene.player.corked = 9 * 60;
      g.clearRect(0, 0, VIEW_W, VIEW_H);
      scene.drawOverlay(g);
      const d = g.getImageData(0, 0, VIEW_W, VIEW_H).data;

      /* Sallitut välit riveittäin, ks. `OVERLAY`. Varjo vie yhden pikselin
       * oikealle ja alas, joten jokainen väli on yhtä leveämpi kuin teksti. */
      const top1 = strays(inkCols(d, VIEW_W, 6, 13), [[18, 60], [260, 315]]);
      const top2 = strays(inkCols(d, VIEW_W, 17, 24), [[18, 66], [255, 315]]);
      expect('kentän ilmestyvät lukemat pysyvät ylänurkissaan pahimmallakin tilalla',
        top1.length === 0 && top2.length === 0,
        `ylin rivi ${top1.length ? runs(top1) : 'siisti'}, toinen rivi`
        + ` ${top2.length ? runs(top2) : 'siisti'}`);

      /* Alanurkka: nielty kyky ja varalokero. Ja **koko keskikaista on
       * tyhjä** — se on koko muutoksen väite yhtenä mittana: pelialueen
       * keskellä ei ole kertojan mustetta lainkaan. */
      const bottom = strays(inkCols(d, VIEW_W, VIEW_H - 26, VIEW_H - 1), [[235, 315]]);
      const middle = strays(inkCols(d, VIEW_W, 30, VIEW_H - 30), []);
      expect('alanurkka on varattu ja ruudun keskeltä ei löydy yhtään lukemaa',
        bottom.length === 0 && middle.length === 0,
        `alanurkka ${bottom.length ? runs(bottom) : 'siisti'}, keskikaista`
        + ` ${middle.length ? runs(middle) : 'tyhjä'}`);
    }

    /* --- 2. kartan paneeli ja yläpalkki --- */
    {
      const c = document.createElement('canvas');
      c.width = 320;
      c.height = 240;
      const g = c.getContext('2d');
      game.state = {
        lives: 9999, coins: 99, score: 9999999, power: { type: 'leaf', level: 3 },
        reserve: 'flower', world: 7, node: null, cleared: {}, worldsOpen: 8,
        cards: [], secrets: {}, usedSaveState: false, continues: 0, bestTimes: {},
      };
      game.timeAttack = true;                 // pisin tilateksti yläpalkkiin
      const map = new WorldMapScene(game);
      map.tick = 12;
      g.clearRect(0, 0, 320, 240);
      map.draw(g);
      const d = g.getImageData(0, 0, 320, 240).data;
      game.timeAttack = false;

      /* Yläpalkki on 14 px korkea ja teksti alkaa kolmosesta. */
      const title = strays(inkCols(d, 320, 3, 9), [[6, 173], [267, 314]]);
      expect('kartan yläpalkissa on tilaa maailman nimen ja tilatekstin välissä',
        title.length === 0, title.length ? runs(title) : 'siisti');

      /* Paneelin kaksi ylintä riviä. Nimikilpi on täytetty suorakaide, joten
       * se on mustetta koko leveydeltään (124…279). */
      const panelY = 158;
      const prow1 = strays(inkCols(d, 320, panelY + 10, panelY + 16),
        [[8, 48], [124, 279], [286, 309]]);
      const prow2 = strays(inkCols(d, 320, panelY + 20, panelY + 26),
        [[8, 55], [60, 118], [124, 279], [286, 309]]);
      expect('kartan paneelin lukemat pysyvät sarakkeissaan',
        prow1.length === 0 && prow2.length === 0,
        `ylärivi ${prow1.length ? runs(prow1) : 'siisti'}, alarivi`
        + ` ${prow2.length ? runs(prow2) : 'siisti'}`);
    }

    /* --- 3. nauha nukkuu, keho puhuu --- */
    /*
     * Kaksi puolta samasta päätöksestä (ks. `HUD_WAKE` ja `PLUME_START`):
     * kertojan kerros vetäytyy kun sillä ei ole asiaa, ja se lukema jota
     * luetaan kesken juoksun siirtyy maailmaan. Jos nauha himmenee muttei
     * mikään korvaa sitä, muutos on pelkkää poistoa.
     */
    {
      const { P_METER_MAX } = await import('/src/entities/player.js');
      const blank2 = () => ({
        left: false, right: false, up: false, down: false, jump: false, run: false,
        start: false, mute: false, quicksave: false, quickload: false, slot: false, reset: false,
      });
      const idle = () => ({
        held: blank2(), pressed: blank2(), released: blank2(), consume() {},
      });
      game.state = {
        lives: 3, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {},
      };
      const s = new LevelScene(game, '1-1');
      const fresh = s.hudInk();
      for (let f = 0; f < 200; f++) s.update(idle());
      const slept = s.hudInk();
      game.state.coins++;
      s.update(idle());
      const woke = s.hudInk();
      /* Kello alle sadan on kriisi eikä tapahtuma: nauha ei saa nukahtaa
       * silloin vaikka mikään lukema ei muutu. */
      /* Kriisi on nyt vähissä oleva polttoaine eikä kello (18.8.2026). */
      game.state.coins = 8;
      for (let f = 0; f < 200; f++) s.update(idle());
      const urgent = s.hudInk();
      expect('HUD-nauha himmenee itsekseen ja herää lukeman muutoksesta',
        fresh === 1 && slept < 0.75 && woke === 1 && urgent === 1,
        `alussa ${fresh}, 200 framen jälkeen ${slept.toFixed(2)}, kolikosta ${woke},`
        + ` vähissä polttoaineessa ${urgent.toFixed(2)}`);

      /* Suihku: mitä täydempi mittari, sitä tiheämpi pilvi — ja kolme tilaa
       * joissa sitä ei tule lainkaan. */
      const p = s.player;
      const plumes = (setup, frames = 60) => {
        p.onGround = true;
        p.corked = 0;
        p.dying = false;
        setup();
        const before = s.entities.length;
        for (let f = 0; f < frames; f++) { p.tick++; p.ventPlume(); }
        return s.entities.length - before;
      };
      const walking = plumes(() => { p.pMeter = P_METER_MAX * 0.2; });
      const halfway = plumes(() => { p.pMeter = P_METER_MAX * 0.7; });
      const full = plumes(() => { p.pMeter = P_METER_MAX; });
      const airborne = plumes(() => { p.pMeter = P_METER_MAX; p.onGround = false; });
      const corked = plumes(() => { p.pMeter = P_METER_MAX; p.corked = 120; });
      expect('paine näkyy kehossa: suihku tihenee mittarin mukana eikä tule tyhjästä',
        walking === 0 && halfway > 0 && full > halfway && airborne === 0 && corked === 0,
        `kävely ${walking}, puolikas ${halfway}, täysi ${full}, ilmassa ${airborne},`
        + ` ummetus ${corked} (60 framea kutakin)`);
    }

    /* --- 4. kolikkoputkilo: pinta on luku, ja kolikot menevät sinne --- */
    /*
     * Putkilon koko väite on suhde: **sisätila on sata kolikkoa korkea**, eli
     * pinnan korkeus kertoo sekä määrän että etäisyyden elämään. Jos se suhde
     * lipsuu, mittari valehtelee näyttäen silti oikealta — juuri se vika jota
     * silmä ei löydä. Siksi se mitataan pikseleinä eikä luettuna koodista.
     */
    {
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d');
      const goldRows = (coins) => {
        game.state = {
          lives: 3, coins, score: 0, power: { type: null, level: 0 }, reserve: null,
          world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
          usedSaveState: false, continues: 0, bestTimes: {},
        };
        const s = new LevelScene(game, '1-1');
        /* Konstruktori nostaa säiliön lattiaan (`FUEL_FLOOR`), koska kolikot
         * ovat aika eikä kenttään lähetetä ketään tyhjänä. Tämä väite koskee
         * pinnan piirtoa, joten pinta asetetaan vasta sen jälkeen. */
        game.state.coins = coins;
        s.tubeFill = coins;
        s.updateCoinFlights();
        g.clearRect(0, 0, VIEW_W, VIEW_H);
        s.drawCoinTube(g);
        const d = g.getImageData(0, 0, VIEW_W, VIEW_H).data;
        const rows = new Set();
        for (let y = 0; y < VIEW_H; y++) {
          for (let x = 0; x < 16; x++) {
            const i = (y * VIEW_W + x) * 4;
            if (d[i] > 200 && d[i + 1] > 130 && d[i + 2] < 140 && d[i + 3] > 200) rows.add(y);
          }
        }
        return { rows: rows.size, fill: s.tubeFill };
      };
      const zero = goldRows(0);
      const ten = goldRows(10);
      const fifty = goldRows(50);
      const ninetynine = goldRows(99);
      /* Kaksi pikseliä per kolikko, ja sata kolikkoa on koko sisätila. */
      const ok = zero.rows === 0 && ten.rows === 20 && fifty.rows === 100
        && ninetynine.rows === 198;
      expect('putkilon pinta on tasan kaksi pikseliä per kolikko, sata täyttää sen',
        ok,
        `0 -> ${zero.rows} px, 10 -> ${ten.rows} px, 50 -> ${fifty.rows} px,`
        + ` 99 -> ${ninetynine.rows} px (sisätila 200 px)`);

      /* Kolikko ei katoa ilmaan: se lentää putkiloon ja pinta nousee vasta kun
       * se on perillä. Sata kolikkoa tyhjentää putkilon, ja se on 1UP nähtynä. */
      game.state = {
        lives: 3, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {},
      };
      const { COIN_CAP, RED_COST, RED_KEEP } = await import('/src/scenes/level.js');
      const { T } = await import('/src/gfx/tiles.js');
      const s = new LevelScene(game, '1-1');
      game.state.coins = 0;
      s.tubeFill = 0;
      s.addCoin(s.player.x + 40, s.player.y);
      const inAir = s.coinFlights.length;
      const fillAtPickup = s.tubeFill;
      for (let f = 0; f < 90 && s.coinFlights.length; f++) s.updateCoinFlights();
      const landed = s.tubeFill;
      const livesBefore = game.state.lives;
      game.state.coins = COIN_CAP - 1;
      s.tubeFill = COIN_CAP - 1;
      s.addCoin(s.player.x + 40, s.player.y);
      for (let f = 0; f < 90 && s.coinFlights.length; f++) s.updateCoinFlights();
      /* Sadas kolikko **ei** nollaa pintaa kertaheitolla vaan aloittaa
       * valumisen (`COIN_FLUSH`): täysi putkilo on se yksi hetki jonka koko
       * mittari on rakennettu lupaamaan, ja se saa kestää. Väite on siis
       * kaksiosainen — heti täysi, ja huuhtelun jälkeen tyhjä. */
      const afterMint = s.tubeFill;
      const coinsAfter = game.state.coins;
      const draining = s.tubeFlush;
      for (let f = 0; f < 90 && s.tubeFlush > 0; f++) s.updateCoinFlights();
      s.updateCoinFlights();
      const settled = s.tubeFill;
      /*
       * TÄYSI SÄILIÖ LYÖ PUNAISEN KOLIKON (18.8.2026).
       *
       * Owner: *"X yellow coins turns into one red coin, and each death takes
       * away one red coin."* `RED_COST` keltaista lähtee, `RED_KEEP` jää, ja
       * elämä nousee yhdellä — kolme väitettä yhdestä tapahtumasta, ja jokainen
       * niistä on ollut väärin jossain välissä:
       *
       *   - **Elämä.** Ennen tätä täysi säiliö ei antanut mitään; elämä tuli
       *     uran 500 kolikosta, ja huuhteluanimaatio heitti kipinän "sinne
       *     mistä 1UP tuli" ilman että 1UP:tä tapahtui.
       *   - **Hinta.** `coins` on aika, joten 64 kolikkoa on 80 sekuntia. Jos
       *     tämä ei vähentäisi säiliötä, elämä olisi ilmainen ja mittari
       *     valehtelisi toiseen suuntaan.
       *   - **Jäännös.** 32 jää, eli lasi ei koskaan tyhjene maksusta. Nolla
       *     tarkoittaisi että palkinto voi tappaa.
       */
      expect('täysi putkilo vaihtuu punaiseksi kolikoksi ja jättää reilun kolmanneksen',
        inAir === 1 && fillAtPickup === 0 && landed === 1
        && afterMint === RED_KEEP && coinsAfter === COIN_CAP - RED_COST
        && draining > 1 && settled === RED_KEEP
        && game.state.lives === livesBefore + 1,
        `poiminnassa ilmassa ${inAir} pinta ${fillAtPickup}, perillä ${landed};`
        + ` täyttyessä pinta ${afterMint} (odotus ${RED_KEEP}), coins ${coinsAfter}`
        + ` (odotus ${COIN_CAP - RED_COST}), huuhtelu ${draining} framea,`
        + ` lopulta ${settled}, elämät ${livesBefore} -> ${game.state.lives}`);

      /*
       * SYTYTETTY LYHTY TÄYTTÄÄ SÄILIÖN `FUEL_FLOOR`iin (18.8.2026).
       *
       * Konstruktori takaa ettei kukaan aloita kenttää sen alle, koska kenttä
       * jota ei voi läpäistä ei ole kenttä. Lyhty **siirtää sen mistä kenttä
       * alkaa** — `spawn` on sen sarake ja kuolema palauttaa siihen — joten
       * saman takuun on siirryttävä mukana. Muuten tarkistuspiste olisi lupaus
       * joka ohenee mitä syvemmällä se on: pelaaja palaisi paikkaan sillä
       * polttoaineella joka sattui olemaan jäljellä kun hän kuoli.
       *
       * Kaksi puolta, ja jälkimmäinen on se joka voisi rikkoutua hiljaa:
       * **täyttää muttei koskaan leikkaa**. Rikkaana saapuva pitää kaikkensa,
       * koska lattia joka voisi viedä kolikoita tekisi lyhdyn sytyttämisestä
       * asian jota kannattaa harkita.
       */
      const { FUEL_FLOOR } = await import('/src/scenes/level.js');
      const lampScene = new LevelScene(game, '1-1');
      const lamp = (() => {
        for (let ty = 0; ty < lampScene.h; ty++) {
          for (let tx = 0; tx < lampScene.w; tx++) {
            const ch = lampScene.grid[ty][tx];
            if (ch === T.LAMP || ch === T.LAMP_LIT) return { tx, ty };
          }
        }
        return null;
      })();
      let poorAfter = null;
      let richAfter = null;
      if (lamp) {
        game.state.coins = 4;
        lampScene.lightLamp(lamp.tx, lamp.ty);
        poorAfter = game.state.coins;
        const rich = new LevelScene(game, '1-1');
        game.state.coins = COIN_CAP - 1;
        rich.lightLamp(lamp.tx, lamp.ty);
        richAfter = game.state.coins;
      }
      expect('sytytetty lyhty täyttää säiliön kenttään saapumisen lattiaan, muttei leikkaa',
        !!lamp && poorAfter === FUEL_FLOOR && richAfter === COIN_CAP - 1,
        lamp ? `köyhänä 4 -> ${poorAfter} (odotus ${FUEL_FLOOR}),`
          + ` rikkaana ${COIN_CAP - 1} -> ${richAfter}` : '1-1:stä ei löytynyt lyhtyä');
    }

    /* --- 5. aurinko on kello, ei maisemaa --- */
    /*
     * Väite on kaksiosainen ja toinen puoli on se tärkeä: aurinko liikkuu
     * **ajan** mukana ja **ei** kameran. Jos se liikkuisi molempien, se ei
     * kertoisi kumpaakaan — ja juuri sitä se ennen teki (parallaksi 0,03).
     *
     * Kameraväite mitataan **vaakasuunnassa**, koska parallaksi on vaakasuora
     * ilmiö: vanha kerroin 0,03 olisi siirtänyt aurinkoa 900 px kameralla 27
     * px sivuun. Pystysuunta jätetään mittaamatta, ja syy on mitattu eikä
     * arvattu: pilvikerros ajelehtii kameran mukana ja voi peittää kiekon
     * ylä- tai alareunasta muutaman pikselin, mikä siirtää painopistettä
     * pystyssä ilman että aurinko itse liikkuu.
     */
    {
      const { drawBackdrop } = await import('/src/gfx/backdrop.js');
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d');
      const sunAt = (clock, camX) => {
        g.clearRect(0, 0, VIEW_W, VIEW_H);
        drawBackdrop(g, 'hills', 'grass', camX, VIEW_W, VIEW_H, 0, 0, clock);
        const d = g.getImageData(0, 0, VIEW_W, VIEW_H).data;
        let sx = 0; let sy = 0; let n = 0;
        for (let y = 0; y < VIEW_H; y++) {
          for (let x = 0; x < VIEW_W; x++) {
            const i = (y * VIEW_W + x) * 4;
            if (d[i] > 250 && d[i + 1] > 245 && d[i + 2] > 195 && d[i + 2] < 245) {
              sx += x; sy += y; n++;
            }
          }
        }
        return n ? { x: Math.round(sx / n), y: Math.round(sy / n), n } : null;
      };
      const dawn = sunAt(1, 0);
      const noon = sunAt(0.5, 0);
      const dusk = sunAt(0.02, 0);
      const moved = sunAt(0.5, 900);
      const rises = dawn && noon && dusk && moved
        && dawn.x < noon.x && noon.x < dusk.x
        && noon.y < dawn.y && noon.y < dusk.y
        && moved.x === noon.x;
      expect('aurinko kulkee kellon mukana eikä kameran mukana',
        rises,
        `alku ${dawn ? `${dawn.x},${dawn.y}` : 'ei löytynyt'},`
        + ` puoliväli ${noon ? `${noon.x},${noon.y}` : 'ei löytynyt'},`
        + ` loppu ${dusk ? `${dusk.x},${dusk.y}` : 'ei löytynyt'};`
        + ` sama aika toisella kameralla ${moved ? `${moved.x},${moved.y}` : 'ei löytynyt'}`);
    }

    /* --- 6. kentän nimi: tienvarressa siellä missä on tie, taivaalla muualla ---
     *
     * THE NAME MOVED (19.8.2026). It used to be smoke writing in the sky in
     * every level. It is now a roadside board that scrolls past — placed off
     * the right edge by `updateProps` and carried in by the backdrop's own
     * parallax — except where the camera climbs instead of running, because a
     * sign beside a road that is not there can never arrive.
     *
     * So the assertion is a **split**, not a replacement, and that is the part
     * worth gating: exactly one of the two says the name in any given level.
     * If both ever fired, that is DESIGN.md item 8 broken in the most literal
     * way the game can break it — the same words in two places at once.
     */
    {
      const c = document.createElement('canvas');
      c.width = VIEW_W;
      c.height = VIEW_H;
      const g = c.getContext('2d');
      const inkAt = (scene, tick) => {
        scene.tick = tick;
        g.clearRect(0, 0, VIEW_W, VIEW_H);
        scene.drawSkyName(g);
        const d = g.getImageData(0, 0, VIEW_W, VIEW_H).data;
        let n = 0;
        for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++;
        return n;
      };
      game.state = {
        lives: 3, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {},
      };
      /* Pystykenttä: nimi on yhä taivaalla, ja se käy pois ja palaa. */
      const sky = new LevelScene(game, '7-T');
      const intro = inkAt(sky, 100);
      const after = inkAt(sky, 600);
      const back = inkAt(sky, 240 + 1080 + 120);
      /* Vaakakenttä: taivas on tyhjä, ja kyltti on tiessä. */
      const road = new LevelScene(game, '1-1');
      const roadSky = inkAt(road, 100);
      const room = new LevelScene(game, '1-F');
      const inside = inkAt(room, 100);

      /* Kyltti mitataan piirtämällä, samoin kuin savukirjoitus: kysytään
       * kerroksen omalta piirtäjältä montako pikseliä se jättää. */
      road.tick = 0;
      road.updateProps();
      const carded = road.props.has('card');
      g.clearRect(0, 0, VIEW_W, VIEW_H);
      road.props.draw(g, road.cam.x, VIEW_W, VIEW_H);
      let boardPx = 0;
      {
        const d = g.getImageData(0, 0, VIEW_W, VIEW_H).data;
        for (let i = 3; i < d.length; i += 4) if (d[i] > 0) boardPx++;
      }

      let gaps = null;

      expect('kentän nimi kirjoitetaan taivaalle vain siellä missä ei ole tietä',
        intro > 100 && after === 0 && back > 100 && roadSky === 0 && inside === 0,
        `pystykentässä alussa ${intro} px, 600 framen kohdalla ${after} px,`
        + ` kierroksen jälkeen ${back} px; vaakakentän taivaalla ${roadSky} px,`
        + ` linnakkeessa ${inside} px`);

      /*
       * TWO SIGNS NEVER STAND IN THE SAME HOLE (20.8.2026).
       *
       * Owner, from play: *"make sure speed sign and world level sign don't
       * overlap."* Every prop was born at the same spot in layer space, so two
       * placed near the same moment were not unlucky — they were guaranteed.
       * The gap is asserted against the widest thing this layer draws rather
       * than against a number somebody liked.
       */
      {
        const { PropLayer } = await import('/src/gfx/props.js');
        const { textWidth: tw } = await import('/src/gfx/font.js');
        const q = new PropLayer();
        const first = q.place('card', 0, VIEW_W, { text: 'MAAILMA 1-1' });
        const second = q.place('speed', 0, VIEW_W, { limit: 50 });
        const third = q.place('speed', 30, VIEW_W, { limit: 80 });
        const boardW = tw('MAAILMA 1-1') + 12;
        gaps = { a: second.x - first.x, b: third.x - second.x, boardW };
      }

      expect('vaakakentässä nimi on tienvarressa, ja se syntyy ruudun ulkopuolella',
        carded && boardPx === 0 && road.props.list[0].x - road.cam.x * 0.6 >= VIEW_W,
        `kyltti asetettu ${carded}, ruudulla ${boardPx} px,`
        + ` reunan takana ${carded ? Math.round(road.props.list[0].x - road.cam.x * 0.6) : -1}`
        + ` (ruudun leveys ${VIEW_W})`);

      expect('kaksi kylttiä ei koskaan seiso samassa kuopassa',
        gaps && gaps.a >= gaps.boardW && gaps.b >= gaps.boardW,
        `peräkkäin ${gaps ? gaps.a : -1} ja ${gaps ? gaps.b : -1} px,`
        + ` levein kyltti ${gaps ? gaps.boardW : -1} px`);
    }

    /* --- 7. karannut kuori ja pallojen katto --- */
    /*
     * Kaksi omistajan raporttia samasta viasta eri suunnista: liike joka
     * jatkuu siellä missä kukaan ei ole. Kuori tyhjensi kentän ennen pelaajaa,
     * ja kukka piti ruudulla pysyvää pallomattoa. Kumpikin mitataan
     * tapahtumana.
     */
    {
      const E = await import('/src/entities/enemies.js');
      const { FartBall } = await import('/src/entities/items.js');
      game.state = {
        lives: 3, coins: 0, score: 0, power: { type: 'flower', level: 5 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {},
      };
      const s = new LevelScene(game, '1-1');
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      const shell = new E.ShellGuy(s, 6 * 16, 13 * 16);
      shell.y = 13 * 16 - shell.h;
      shell.active = true;
      shell.alwaysActive = true;
      s.add(shell);
      shell.toShell();
      shell.kick(1);
      const w = s.viewW;
      /* a) Ruudun sisällä, matkaa vasta vähän: elossa. */
      const near = shell.runaway;
      /* b) Matkaa yli ruudun mutta yhä ikkunassa (pelaaja juoksee perässä):
       *    elossa, koska sen näkee. */
      shell.x = shell.slideFrom + w + 40;
      s.cam.x = shell.x - 100;
      const followed = shell.runaway;
      /* c) Matkaa yli ruudun ja ikkunan ulkopuolella: karannut. */
      s.cam.x = shell.slideFrom - 100;
      const escaped = shell.runaway;
      shell.update();
      const cleared = shell.remove;
      expect('potkaistu kuori loppuu siihen missä katsekin, muttei ennen sitä',
        near === false && followed === false && escaped === true && cleared === true,
        `lähellä ${near}, perässä juostuna ${followed}, karanneena ${escaped},`
        + ` poistui ${cleared}`);

      /* Pallojen katto: kolmas laukaus ei kasvata määrää vaan syö vanhimman. */
      const s2 = new LevelScene(game, '1-1');
      s2.entities = s2.entities.filter((e) => e.kind !== 'enemy');
      const p2 = s2.player;
      p2.type = 'flower';
      p2.power = { type: 'flower', level: 5 };
      const live = () => s2.entities.filter((e) => e instanceof FartBall && !e.remove).length;
      const counts = [];
      let first = null;
      for (let shot = 0; shot < 4; shot++) {
        p2.shoot();
        if (!first) first = s2.entities.find((e) => e instanceof FartBall);
        counts.push(live());
      }
      expect('ilmassa on korkeintaan kaksi palloa, ja uusin syö vanhimman',
        counts.every((n) => n <= p2.maxLiveShots) && counts[counts.length - 1] > 0
        && !!first && first.remove,
        `katto ${p2.maxLiveShots}, laukausten jälkeen ${counts.join(' -> ')},`
        + ` ensimmäinen poistettu ${first ? first.remove : 'ei syntynyt'}`);
    }

    /* --- 8. kumossa oleva nousee itse ylös, ja sen voi niellä --- */
    {
      const E = await import('/src/entities/enemies.js');
      game.state = {
        lives: 3, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {},
      };
      const s = new LevelScene(game, '1-1');
      s.entities = s.entities.filter((e) => e.kind !== 'enemy');
      const e = new E.Walker(s, 6 * 16, 13 * 16);
      e.y = 13 * 16 - e.h;
      e.active = true;
      e.alwaysActive = true;
      e.spawnGrace = 0;
      s.add(e);
      const ok = e.knockOver(1);
      const down = e.flipped && e.harmless;
      let warned = false;
      for (let f = 0; f < E.FLIP_FRAMES + 5; f++) {
        e.update();
        if (e.righting) warned = true;
      }
      expect('kumoon kaadettu on vaaraton, varoittaa nousustaan ja nousee itse',
        ok && down && warned && !e.flipped && !e.harmless && !e.dying && !e.remove,
        `kaatui ${ok}, vaaraton kumossa ${down}, varoitti ${warned},`
        + ` nousi ${!e.flipped}, hengissä ${!e.dying && !e.remove}`);

      /* Ja ketju isku → kumoon → nieleminen on ehjä ilman kuplaa: se oli
       * VERBI 6:n koko rakenne, ja maahanisku lakkasi tänään vangitsemasta. */
      const e2 = new E.Walker(s, 6 * 16, 13 * 16);
      e2.y = 13 * 16 - e2.h;
      e2.active = true;
      e2.alwaysActive = true;
      e2.spawnGrace = 0;
      s.add(e2);
      e2.knockOver(1);
      const p2 = s.player;
      const ate = s.swallowEnemy(p2, e2);
      expect('kumossa olevan voi niellä: ketju isku → kumoon → kyky on ehjä',
        ate === true && !!p2.swallowed && p2.power.type === p2.swallowed && e2.remove,
        `nieltiin ${ate}, kyky ${p2.swallowed || 'ei mitään'},`
        + ` voimapaikassa ${p2.power.type || 'ei mitään'}`);
    }

    /* --- 8 a. hätä ja ladattu laukaus --- */
    /*
     * Kaksi uutta verbiä, ja molempien väite on **mitä ne eivät tee**: hätä ei
     * satuta ja ladattu laukaus ei ole uusi nappi.
     */
    {
      const E = await import('/src/entities/enemies.js');
      const { FartBall } = await import('/src/entities/items.js');
      const blank3 = () => ({
        left: false, right: false, up: false, down: false, jump: false, run: false,
        start: false, mute: false, quicksave: false, quickload: false, slot: false, reset: false,
      });
      const mkIn = () => ({
        held: blank3(), pressed: blank3(), released: blank3(), consume() {},
      });
      game.state = {
        lives: 3, coins: 0, score: 0, power: { type: 'flower', level: 3 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        usedSaveState: false, continues: 0, bestTimes: {}, bet: 0,
      };
      const s = new LevelScene(game, '1-1');
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      const p = s.player;

      /* 1. Hössötin: kosketus vie ohjauksen muttei elämää eikä voimatasoa. */
      const h = new E.Hossotin(s, p.x + 10, p.y);
      h.active = true;
      h.alwaysActive = true;
      h.spawnGrace = 0;
      s.add(h);
      const before = { lives: game.state.lives, level: p.powerLevel, x: p.x };
      s.collisions(mkIn());
      const panicked = p.panic;
      /* Vasemmalle painaminen ei auta: jalat vievät eteenpäin. */
      let moved = 0;
      for (let f = 0; f < 40; f++) {
        const i = mkIn();
        i.held.left = true;
        s.update(i);
        moved = p.x - before.x;
      }
      expect('hössötin vie ohjauksen muttei elämää — eikä vasemmalle pääse',
        panicked > 0 && game.state.lives === before.lives && p.powerLevel === before.level
        && moved > 8,
        `hätä ${panicked} framea, elämät ${before.lives}->${game.state.lives},`
        + ` taso ${before.level}->${p.powerLevel}, liike vasemmalle painaen ${moved.toFixed(1)} px`);

      /* 2. Ladattu laukaus: tauko tekee ison pallon, ja peräkkäiset eivät. */
      p.panic = 0;
      s.entities = s.entities.filter((e) => !(e instanceof FartBall));
      p.lastShot = -999;
      p.tick += 200;
      p.shoot();
      const first = s.entities.filter((e) => e instanceof FartBall);
      const bigFirst = first.length === 1 && first[0].charged && first[0].w === 16;
      s.entities = s.entities.filter((e) => !(e instanceof FartBall));
      p.tick += 10;
      p.shoot();
      const second = s.entities.filter((e) => e instanceof FartBall);
      const smallSecond = second.length >= 1 && second.every((b) => !b.charged);
      expect('tauko lataa laukauksen, ja peräkkäiset laukaukset ovat tavallisia',
        bigFirst && smallSecond,
        `tauon jälkeen ${first.length} palloa (ladattu ${first[0] && first[0].charged}),`
        + ` heti perään ${second.length} (ladattu ${second.some((b) => b.charged)})`);
    }

    /* --- 8 b. neljä taloa, kolme uhkapeliä --- */
    /*
     * Talojen väite on **panos**, ja panos on ainoa asia jonka väärin
     * laskeminen huomataan vasta pelaajan kolikoissa. Neljä mittausta:
     * kolikko ei voi kadota eikä syntyä väärin, kuppipeli antaa elämän vain
     * oikeasta kupista, veto säilyy kentän yli, ja arpa on arpa.
     */
    {
      const { WorldMapScene } = await import('/src/scenes/worldmap.js');
      const { WORLDS } = await import('/src/data/worlds.js');
      const fresh = (coins = 42) => {
        game.state = {
          lives: 3, coins, score: 0, power: { type: null, level: 0 }, reserve: null,
          world: 0, node: 'w1-1', cleared: {}, worldsOpen: 8, cards: [], secrets: {},
          usedSaveState: false, continues: 0, bestTimes: {}, bet: 0,
        };
        const m = new WorldMapScene(game);
        m.tick = 10;
        return m;
      };
      const tap = () => ({ pressed: { jump: true }, consume() {} });
      const idle = () => ({ pressed: {}, consume() {} });

      /* 1. Jokaisella talolla on laji, ja laji on tunnettu. */
      const houses = WORLDS.flatMap((w) => w.nodes.filter((n) => n.type === 'house'));
      const games = new Set(houses.map((h) => h.game));
      const unknown = houses.filter((h) => !['items', 'coinflip', 'cups', 'bet'].includes(h.game));
      expect('jokaisella talolla on tunnettu laji, ja lajeja on useampi kuin yksi',
        houses.length === 8 && unknown.length === 0 && games.size >= 3,
        `${houses.length} taloa, lajit ${[...games].sort().join(' ')}`);

      /*
       * The gambling games moved out of the map and into `house.js` on
       * 19.8.2026, because the globe needs the same rooms and a second copy
       * of a game is a second set of odds. These checks therefore drive the
       * room rather than the map — which is also the only way they can still
       * mean anything, since the map no longer decides what a bet pays.
       */
      const { House } = await import('/src/scenes/house.js');
      const openHouse = (kind, coins) => {
        const m = fresh(coins);
        const node = houses.find((h) => h.game === kind) || m.node;
        return new House(game, { ...node, game: kind }, () => {});
      };

      /* 2. Kolikonheitto: voitto tuplaa panoksen, häviö vie sen, eikä
       *    kummassakaan tapauksessa synny tai katoa muuta. */
      let won = null;
      let lost = null;
      for (let i = 0; i < 40 && (won === null || lost === null); i++) {
        const m = openHouse('coinflip', 42);
        m.houseCursor = 1;                       // panos 15
        m.update(tap());
        const after = game.state.coins;
        for (let f = 0; f < 60 && !m.done; f++) m.update(idle());
        const end = game.state.coins;
        if (m.houseResult && won === null) won = { after, end };
        if (!m.houseResult && lost === null) lost = { after, end };
      }
      expect('kolikonheitto tuplaa voiton ja vie häviön, eikä muuta',
        !!won && !!lost && won.after === 27 && won.end === 57
        && lost.after === 27 && lost.end === 27,
        `voitto ${won ? `${won.after} -> ${won.end}` : 'ei osunut'},`
        + ` häviö ${lost ? `${lost.after} -> ${lost.end}` : 'ei osunut'} (panos 15, alku 42)`);

      /* 3. Kuppipeli: elämä vain oikeasta kupista, ja sekoitus liikuttaa
       *    palkintoa — muuten se olisi kolme kuppia joista aina keskimmäinen. */
      let right = null;
      let wrong = null;
      /* Sekoitus mitataan omalla kierroksellaan eikä palkintokierroksen
       * kyljessä: yksi sekoitus voi päätyä lähtöruutuun (parillinen määrä
       * osuvia vaihtoja), joten yhden näytteen mittaus olisi kolikonheitto
       * siitä läpäiseekö portti. Kymmenen kierrosta, ja vaaditaan että
       * palkinto liikkui useimmissa. */
      let moved = 0;
      for (let i = 0; i < 10; i++) {
        const mm = openHouse('cups');
        mm.update(idle());
        const start = mm.cupPrize;
        for (let f = 0; f < 200 && mm.housePhase === 'shuffle'; f++) mm.update(idle());
        if (mm.cupPrize !== start) moved++;
      }
      for (let i = 0; i < 30 && (right === null || wrong === null); i++) {
        const m = openHouse('cups');
        m.update(idle());
        for (let f = 0; f < 200 && m.housePhase === 'shuffle'; f++) m.update(idle());
        const lives = game.state.lives;
        m.houseCursor = m.cupPrize;              // oikea kuppi
        m.update(tap());
        for (let f = 0; f < 80 && !m.done; f++) m.update(idle());
        if (right === null) right = game.state.lives - lives;

        const m2 = openHouse('cups');
        m2.update(idle());
        for (let f = 0; f < 200 && m2.housePhase === 'shuffle'; f++) m2.update(idle());
        const lives2 = game.state.lives;
        m2.houseCursor = (m2.cupPrize + 1) % 3;  // väärä kuppi
        m2.update(tap());
        for (let f = 0; f < 80 && !m2.done; f++) m2.update(idle());
        if (wrong === null) wrong = game.state.lives - lives2;
      }
      expect('kuppipeli antaa elämän vain oikeasta kupista, ja sekoitus liikuttaa palkintoa',
        right === 1 && wrong === 0 && moved >= 3,
        `oikea kuppi ${right} elämää, väärä ${wrong}, sekoitus liikutti palkintoa`
        + ` ${moved}/10 kierroksella`);

      /* 4. Veto elää `state`issa kentän yli: talo ottaa panoksen, `finishLevel`
       *    maksaa tuplat läpäisystä eikä mitään kuolemasta. */
      const m = openHouse('bet', 42);
      m.houseCursor = 2;                          // panos 30
      m.update(tap());
      const afterBet = { coins: game.state.coins, bet: game.state.bet };
      /* Prototyypin oma `finishLevel`, ei olion päälle asetettu: aiemmat
       * väitteet korvaavat sen tynkällä (`game.finishLevel = () => {}`), ja
       * tyngälle maksettu veto on veto jota kukaan ei maksanut. */
      const real = Object.getPrototypeOf(game).finishLevel;
      const keepNode = game.pendingNode;
      /* Oikea solmu, koska oikea `finishLevel` merkitsee sen selvitetyksi ja
       * siirtää pelaajan seuraavaan: tynkäsolmu kaatuisi `node.id`:hen. */
      game.pendingNode = WORLDS[0].nodes.find((n) => n.level && n.type === 'level');
      real.call(game, { cleared: true, card: null });
      const afterWin = { coins: game.state.coins, bet: game.state.bet };
      game.pendingNode = keepNode;
      expect('veto otetaan talossa ja maksetaan kentän lopussa',
        afterBet.coins === 12 && afterBet.bet === 30
        && afterWin.coins === 72 && afterWin.bet === 0,
        `talossa ${afterBet.coins} kolikkoa ja veto ${afterBet.bet};`
        + ` läpäisyn jälkeen ${afterWin.coins} ja veto ${afterWin.bet}`);
    }

    /* --- 9 c. pyörivät jalat --- */
    /*
     * Kolme väitettä, ja ne ovat samat kolme jotka mikä tahansa uusi
     * animaatio joutuu läpäisemään: **se on eri kuva** kuin se jonka tilalle
     * se tuli, **se liikkuu**, ja **se ei muuta siluettia** — pelaajan
     * ääriviivasta luetaan osumalaatikko.
     */
    {
      const sprites = await import('/src/gfx/sprites.js');
      const shot = (spin, tick) => {
        const c = document.createElement('canvas');
        c.width = 32; c.height = 40;
        const g = c.getContext('2d', { willReadFrequently: true });
        g.clearRect(0, 0, 32, 40);
        sprites.drawPlayer(g, 8, 8, {
          type: 'shroom', level: 1, facing: 1, state: 'walk', ducking: false,
          running: true, idle: 0, theme: 'grass', wag: 0, frame: 0, tick, spinLegs: spin,
        });
        return g.getImageData(0, 0, 32, 40).data;
      };
      const walking = shot(false, 0);
      const wheelA = shot(true, 0);
      const wheelB = shot(true, 4);
      const diff = (a2, b2) => {
        let n = 0;
        for (let i = 0; i < a2.length; i += 4) {
          if (a2[i] !== b2[i] || a2[i + 1] !== b2[i + 1] || a2[i + 2] !== b2[i + 2]
            || a2[i + 3] !== b2[i + 3]) n++;
        }
        return n;
      };
      const mask = (a2, b2) => {
        let n = 0;
        for (let i = 3; i < a2.length; i += 4) if ((a2[i] > 8) !== (b2[i] > 8)) n++;
        return n;
      };
      expect('kovassa vauhdissa jalat ovat pyörä, ja pyörä pyörii',
        diff(walking, wheelA) > 12 && diff(wheelA, wheelB) > 3 && mask(walking, wheelA) < 12,
        `kävely vs pyörä ${diff(walking, wheelA)} px, pyörän kaksi framea`
        + ` ${diff(wheelA, wheelB)} px, siluettiero ${mask(walking, wheelA)} px`);
    }

    /* --- 9 b. SID-sanasto: pulssi, arpeggio, suodin --- */
    /*
     * Kolme väitettä siitä mitä `tone`en tuli, ja jokainen on luettavissa
     * luvuista eikä korvasta.
     *
     *   1. **Pulssi ei ole kanttiaalto.** 50 %:n pulssilla joka toinen
     *      osaääni on nolla; 25 %:n pulssilla ne ovat mukana. Se on koko ero,
     *      ja se on myös se syy miksi leveysmodulaatio kuuluu.
     *   2. **Uusi raita käyttää sanastoa.** Raita joka olisi kirjoitettu
     *      vanhoilla aalloilla olisi sama raita uudella nimellä.
     *   3. **Vanhat raidat eivät muuttuneet.** Jokainen uusi parametri on
     *      oletuksena nolla, eli `title` soi täsmälleen kuten ennenkin.
     */
    {
      const audio = await import('/src/core/audio.js');
      const square = audio.pulseHarmonics(0.5);
      const narrow = audio.pulseHarmonics(0.25);
      const evensSquare = [2, 4, 6, 8].map((n) => Math.abs(square[n]));
      const evensNarrow = [2, 4, 6, 8].map((n) => Math.abs(narrow[n]));
      /* 50 %:llä **jokainen** parillinen osaääni on nolla. 25 %:llä nollia
       * ovat vain neljän monikerrat (2. ja 6. tulevat takaisin), ja juuri se
       * on se ero jonka korva kuulee kapeana pulssina. Väite on siis "kaikki
       * nollaa" vastaan "ei kaikki nollaa" eikä "kaikki mukana" — mitattu,
       * ensimmäinen versio tästä rivistä oli väärässä. */
      const hollow = evensSquare.every((v) => v < 1e-9);
      const back = evensNarrow.filter((v) => v > 0.02).length;
      expect('pulssiaalto on säädettävä eikä pelkkä kanttiaalto',
        hollow && back >= 2 && Math.abs(square[1]) > 0.5,
        `50 %: parilliset ${evensSquare.map((v) => v.toFixed(3)).join(' ')},`
        + ` 25 %: parilliset ${evensNarrow.map((v) => v.toFixed(3)).join(' ')}`
        + ` (${back} takaisin), perustaajuus ${Math.abs(square[1]).toFixed(2)}`);
    }

    /* --- 9 d. SID-sanaston loppu: varastettu kanava, rengas, sync, taulukot --- */
    /*
     * NELJÄ TEKNIIKKAA, NELJÄ MITTAUSTA, EIKÄ YHTÄÄN OLEMASSAOLOVÄITETTÄ.
     *
     * ROADMAPin "mitä SID-sanastosta jäi tekemättä" oli neljä kohtaa, ja
     * jokainen niistä on sellainen jonka voi *melkein* tehdä: rumpu basson
     * päällä on melkein varastettu kanava, korkeampi nuotti on melkein hard
     * sync, ja äänen vibrato on melkein nuotin vibrato. Portti joka tarkistaa
     * että parametri on asetettu hyväksyisi kaikki kolme melkeinversiota, ja
     * siksi jokainen näistä on **luku signaalista** eikä luku taulusta.
     *
     * Se on mahdollista vasta nyt: `renderTone` rakentaa saman graafin jonka
     * peli soittaa, mutta offline-kontekstiin, joten ääni on taulukko eikä
     * korvahavainto. Mittaus on siis toistettava eikä räpsyvä, eikä se tarvitse
     * äänikorttia — ja se mittaa oikeaa koodia eikä mallia siitä.
     */
    {
      const audio = await import('/src/core/audio.js');
      const { Music, Sfx, audioDiag, audioTap } = audio;
      const RATE = 44100;
      /* Goertzel-tyylinen yhden taajuuden magnitudi. Koko FFT olisi tässä
       * ylimitoitettu: jokainen väite koskee nimettyjä taajuuksia, ja
       * ruudukkoon pyöristetty binni osuisi niiden viereen. */
      const mag = (buf, a, n, f) => {
        const w = (2 * Math.PI * f) / RATE;
        let re = 0;
        let im = 0;
        for (let i = 0; i < n; i++) {
          const x = buf[a + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / n));
          re += x * Math.cos(w * i);
          im += x * Math.sin(w * i);
        }
        return Math.hypot(re, im) / n;
      };
      /** Nollan ylitykset alhaalta ylös, osanäytteen tarkkuudella. */
      const rises = (b, a, n) => {
        const out = [];
        for (let i = a + 1; i < a + n; i++) {
          if (b[i - 1] < 0 && b[i] >= 0) out.push(i - 1 + (-b[i - 1]) / (b[i] - b[i - 1]));
        }
        return out;
      };
      /** Hetkellinen taajuus jaksosta jaksoon: portamento ja vibrato lukuina. */
      const insideOut = (b, a, n) => {
        const c = rises(b, a, n);
        if (c.length < 3) return { first: 0, lo: 0, hi: 0 };
        let lo = 1e9;
        let hi = 0;
        for (let i = 1; i < c.length; i++) {
          const f = RATE / (c[i] - c[i - 1]);
          lo = Math.min(lo, f);
          hi = Math.max(hi, f);
        }
        return { first: RATE / (c[1] - c[0]), lo, hi };
      };

      /*
       * 1. RENGASMODULAATIO, ja se että se on **tulo eikä sekoitus**.
       *
       * Rengasmodulaatio ei lisää ääneen mitään: se korvaa kantoaallon kahdella
       * sivunauhalla, `f(r−1)` ja `f(r+1)`, ja kantoaalto itse **katoaa**. Juuri
       * siitä epäharmoninen kellon ääni syntyy, ja juuri siksi "kuulostaa
       * kirkkaammalta" ei ole sama asia. Kolme lukua samasta renderöinnistä:
       * kantoaallon vaimeneminen, molemmat sivunauhat paikallaan, eikä
       * kumpikaan lähellä kokonaislukumonikertaa.
       */
      {
        const A = Math.round(0.05 * RATE);
        const N = 8192;
        const F = 880;
        const R = 2.41;
        const wet = await audio.renderTone(
          { type: 'triangle', from: F, dur: 0.25, gain: 0.5, attack: 0.003, hold: 0.5, ring: R },
          0.35);
        const dry = await audio.renderTone(
          { type: 'triangle', from: F, dur: 0.25, gain: 0.5, attack: 0.003, hold: 0.5 }, 0.35);
        const carrier = mag(wet, A, N, F);
        const dryCarrier = mag(dry, A, N, F);
        const lo = mag(wet, A, N, F * (R - 1));
        const hi = mag(wet, A, N, F * (R + 1));
        const off = (x) => Math.abs(x - Math.round(x));
        const killed = dryCarrier / Math.max(1e-9, carrier);
        expect('rengasmodulaatio vaimentaa kantoaallon ja tuo kaksi epäharmonista sivunauhaa',
          killed > 100 && lo > dryCarrier * 0.2 && hi > dryCarrier * 0.2
          && off(R - 1) > 0.2 && off(R + 1) > 0.2,
          `kantoaalto ${carrier.toExponential(2)} vs kuiva ${dryCarrier.toFixed(4)}`
          + ` (${Math.round(killed)}× vaimeampi), sivunauhat ${lo.toFixed(4)} ja ${hi.toFixed(4)}`
          + ` kohdissa ${(R - 1).toFixed(2)}× ja ${(R + 1).toFixed(2)}× perustaajuutta`);
      }

      /*
       * 2. KOVA SYNKRONOINTI, ja se että se on **eri asia kuin korkeampi nuotti**.
       *
       * Jaksotettu uudelleenkäynnistys tuottaa aallon jonka jakso on isännän ja
       * jonka muoto on orjan. Se erottuu kahdesta naapuriratkaisustaan eri
       * luvulla kummastakin, ja molemmat naapurit ovat sellaisia jotka menisivät
       * läpi jos portti tarkistaisi vain että jotain tapahtui:
       *
       *   - **Ei ole vain kirkkaampi ääni.** Spektrin huippu siirtyy isännän
       *     ensimmäisestä osaäänestä neljänteen kun suhde kasvaa 1:stä 4:ään.
       *   - **Ei ole vain korkeampi nuotti.** Sama neljäs osaääni saadaan
       *     soittamalla nelinkertainen taajuus — mutta silloin perustaajuutta ei
       *     ole *ollenkaan*. Synkronoidussa se on tallella, ja se on se sävel
       *     jonka korva kuulee.
       *
       * Ja kolmas luku joka pitää tämän ratkaisun rehellisenä: energia sijaitsee
       * isännän monikerroilla eikä niiden välissä. Ilman sitä sama huippu voisi
       * olla mitä tahansa säröä.
       */
      {
        const A = Math.round(0.05 * RATE);
        const N = 8192;
        const M = 220;
        const shape = (buf) => {
          const on = [];
          const off = [];
          for (let k = 1; k <= 8; k++) {
            on.push(mag(buf, A, N, M * k));
            off.push(mag(buf, A, N, M * (k + 0.5)));
          }
          const sum = (xs) => xs.reduce((p, q) => p + q, 0);
          let peakK = 1;
          on.forEach((m2, i) => { if (m2 > on[peakK - 1]) peakK = i + 1; });
          return { on, peakK, comb: sum(on) / Math.max(1e-9, sum(off)) };
        };
        const base = { type: 'sawtooth', from: M, dur: 0.35, gain: 0.5, attack: 0.005, hold: 0.95 };
        const flat = shape(await audio.renderTone({ ...base, sync: 1 }, 0.45));
        const screamed = shape(await audio.renderTone({ ...base, sync: 4 }, 0.45));
        const higher = shape(await audio.renderTone({ ...base, from: M * 4 }, 0.45));
        expect('kova synkronointi siirtää sointiväriä muttei sävelkorkeutta',
          flat.peakK === 1 && screamed.peakK === 4
          && screamed.on[0] > higher.on[0] * 20 && screamed.comb > 10,
          `huippu osaäänessä ${flat.peakK} (suhde 1) -> ${screamed.peakK} (suhde 4);`
          + ` perustaajuus synkronoituna ${screamed.on[0].toFixed(4)},`
          + ` nelinkertaisella nuotilla ${higher.on[0].toFixed(4)};`
          + ` energiaa isännän monikerroilla ${screamed.comb.toFixed(0)}× välien verran`);
      }

      /*
       * 3. NUOTTIKOHTAINEN VIBRATO JA PORTAMENTO.
       *
       * Kaksi lukua, ja molemmat mittaavat *aikaa nuotin sisällä* — se on koko
       * ero äänen ominaisuuteen. Portamento saapuu perille kesken nuottia ja
       * pysyy siellä; viivästetty vibrato on alussa suora ja lopussa syvä.
       * Jälkimmäinen mitataan samaa nuottia vasten jolla ei ole viivettä, koska
       * "loppu väreilee" olisi tosi myös ilman koko ominaisuutta.
       */
      {
        const glided = await audio.renderTone(
          { type: 'triangle', from: 220, to: 330, dur: 0.4, gain: 0.5, attack: 0.005, hold: 0.95, glide: 0.5 },
          0.5);
        const at = (sec) => insideOut(glided, Math.round(sec * RATE), 1500).first;
        const start = at(0.01);
        const half = at(0.21);
        const end = at(0.35);
        expect('portamento saapuu perille kesken nuottia eikä sen lopussa',
          start < 245 && Math.abs(half - 330) < 6 && Math.abs(end - 330) < 6,
          `${start.toFixed(0)} Hz alussa, ${half.toFixed(0)} Hz puolivälissä,`
          + ` ${end.toFixed(0)} Hz lopussa (kohde 330)`);

        const wide = (buf, sec) => {
          const w = insideOut(buf, Math.round(sec * RATE), 8000);
          return w.hi - w.lo;
        };
        const shape = { type: 'triangle', from: 440, dur: 0.9, gain: 0.5, attack: 0.005, hold: 0.98, vibrato: 14, vibratoRate: 5 };
        const delayed = await audio.renderTone({ ...shape, vibDelay: 0.35 }, 1.0);
        const plain = await audio.renderTone(shape, 1.0);
        const early = wide(delayed, 0.02);
        const late = wide(delayed, 0.5);
        const always = wide(plain, 0.02);
        expect('viivästetty vibrato on alussa suora ja lopussa yhtä syvä kuin viiveetön',
          early < always * 0.5 && late > always * 0.85,
          `viiveellä alussa ${early.toFixed(1)} Hz ja lopussa ${late.toFixed(1)} Hz,`
          + ` ilman viivettä alusta asti ${always.toFixed(1)} Hz`);
      }

      /*
       * 4. VARASTETTU KANAVA, ja se että reikä on olemassa.
       *
       * Kaksi laskuria `audioDiag`ista, ja ne on tahallaan kaksi: osumat ilman
       * vaikenemista tarkoittaisi että rumpu tuli basson *päälle*, eli lisätty
       * rumpuraita uudella nimellä. Kolmas luku on `_spanOf`, joka on ainoa osa
       * varkaudesta jota emittoiduista nuoteista ei näe — `level`-basson
       * nuotit ovat kaikki yhden askeleen mittaisia, joten katkaisu ei laukea
       * kertaakaan, ja mittaamaton haara on rikki heti kun joku kirjoittaa
       * pidemmän nuotin. Ja neljäs: raita jolla ei ole `steal`ia ei varasta.
       */
      {
        Sfx.resume();
        const tap = audioTap();
        const run = (name) => {
          Music.play(name);
          const dur = Music._stepDur;
          const t0 = tap.ctx.currentTime + 0.25;
          for (let s = 0; s < 32; s++) Music._emit(s, t0 + s * dur, false, dur);
          const out = { hits: audioDiag().stolen, silenced: audioDiag().silenced, dur };
          return out;
        };
        const level = run('level');
        const span = { cut: Music._spanOf('bass', 4, 8), free: Music._spanOf('lead', 4, 8) };
        Music.stop();
        const quiet = run('title');
        Music.stop();
        const hole = 6 / 50;
        expect('varastettu kanava soittaa rummun ja jättää bassoon reiän',
          level.hits === 4 && level.silenced === 4 && span.cut === 2 && span.free === 8
          && quiet.hits === 0,
          `level: ${level.hits} osumaa ja ${level.silenced} vaiennettua nuottia`
          + ` 32 askeleella (varaus ${Math.round(hole * 1000)} ms,`
          + ` askel ${Math.round(level.dur * 1000)} ms); pitkä bassonuotti katkeaa`
          + ` ${span.cut} askeleeseen, lyijy soi ${span.free}; title ${quiet.hits} osumaa`);
      }

      /*
       * 5. JA SE HINTA JOKA PITÄÄ MITATA TAI SE KARKAA.
       *
       * Jaksotettu uudelleenkäynnistys maksaa yhden oskillaattorin isäntäjaksoa
       * kohti, eli hinta kasvaa sävelkorkeuden ja keston mukana. Se on
       * hyväksyttävä ratkaisu vain niin kauan kuin merkittyjä nuotteja on vähän
       * ja ne ovat matalalla — ja kumpikin ehto on sellainen jonka yksi
       * huolimaton nuottimerkki rikkoisi ilman että mikään muu portti näkisi
       * sitä. Katto on `SYNC_MAX_SEGMENTS` (128); tämä vaatii reilusti alle,
       * koska katon saavuttaminen tarkoittaisi että nuotin loppu soi
       * synkronoimatta.
       */
      {
        const OAC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
        Sfx.resume();
        let worst = 0;
        let marked = 0;
        let where = '';
        for (const name of Music.names()) {
          Music.play(name);
          const step = Music._stepDur;
          for (const voice of Music._voices || []) {
            if (!voice.marks) continue;
            for (const [at, note] of voice.map) {
              const m = voice.marks[note[2]];
              if (!m || !m.sync) continue;
              marked++;
              const ac = new OAC(1, 512, RATE);
              /* Pahin tapaus eikä kirjoitettu tapaus: lyijy nousee oktaavin
               * `lead octave up` -osiossa ja sävellaji kiipeää kvintin
               * (`KEY_PLAN`), ja hinta kaksinkertaistuu oktaavia kohti. */
              const worstOctave = (voice.octave || 0)
                + (voice.name === 'lead' ? 12 : 0) + 7;
              const n = audio.syncVoice(ac, {
                type: voice.wave,
                master: 440 * Math.pow(2, (note[0] + worstOctave) / 12),
                ratio: m.sync,
                ratioTo: m.syncTo,
                dur: note[1] * step * (voice.staccato || 0.98),
                t0: 0,
                dest: ac.destination,
              }).length;
              if (n > worst) { worst = n; where = `${name}/${voice.name}@${at}`; }
            }
          }
          Music.stop();
        }
        expect('kova synkronointi on nuotin ominaisuus eikä raidan, ja sen hinta on mitattu',
          marked > 0 && marked <= 8 && worst < 96,
          `${marked} merkittyä nuottia koko pelissä, kallein ${worst} oskillaattoria`
          + ` (${where}), katto 128`);
      }
    }

    /* --- 9. rinteet: maasto jonka pinta on vinossa --- */
    /*
     * RINNE ON MUUNNIN EIKÄ LIUKUMÄKI (IDEAS.md kohta 1, omistajan tuomio
     * 10.8.2026 "kyllä, vahvin"). Väitteitä on neljä, ja ne ovat tässä
     * järjestyksessä siksi että kolme ensimmäistä ovat ehtoja neljännelle:
     * rinne on ensin **maata jota pitkin kuljetaan** ja vasta sitten se joka
     * vaihtaa vauhdin korkeudeksi.
     *
     * Koekenttä rakennetaan käsin eikä kentistä: mitattava asia on fysiikka,
     * ja kenttädata voi muuttua ilman että fysiikka muuttuu.
     */
    {
      const { P_METER_MAX } = await import('/src/entities/player.js');
      const blank2 = () => ({
        left: false, right: false, up: false, down: false, jump: false, run: false,
        start: false, mute: false, quicksave: false, quickload: false, slot: false, reset: false,
      });
      const press = (dir, run) => {
        const i = { held: blank2(), pressed: blank2(), released: blank2(), consume() {} };
        if (dir > 0) i.held.right = true;
        if (dir < 0) i.held.left = true;
        i.held.run = !!run;
        return i;
      };
      const arena = (build) => {
        game.state = {
          lives: 3, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
          world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
          usedSaveState: false, continues: 0, bestTimes: {},
        };
        const s = new LevelScene(game, '1-1');
        s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        s.time = 9999;
        s.clockStopped = true;
        for (let tx = 0; tx < 40; tx++) {
          for (let ty = 0; ty < 15; ty++) s.setTile(tx, ty, ' ');
          s.setTile(tx, 13, '#');
          s.setTile(tx, 14, '#');
        }
        build(s);
        return s;
      };
      /** Nouseva rinne `from`-sarakkeesta `len` laattaa oikealle. */
      const rampUp = (s, from, len, floor = 12) => {
        for (let i = 0; i < len; i++) {
          s.setTile(from + i, floor - i, '/');
          for (let ty = floor - i + 1; ty <= floor; ty++) s.setTile(from + i, ty, '#');
        }
      };

      /* 1. Ylös kävellen: keho nousee, eikä `onGround` vilku kertaakaan. */
      {
        const s = arena((sc) => rampUp(sc, 8, 5));
        const p = s.player;
        p.x = 3 * 16; p.y = 13 * 16 - p.h; p.vx = 0; p.vy = 0;
        let air = 0;
        let startY = null;
        let topY = null;
        for (let f = 0; f < 260; f++) {
          s.update(press(1, false));
          if (p.onSlope) {
            if (startY === null) startY = p.y;
            topY = p.y;
            if (!p.onGround) air++;
          }
        }
        const rose = startY !== null ? startY - topY : 0;
        expect('kävelijä nousee rinnettä ylös eikä irtoa maasta kertaakaan',
          startY !== null && rose > 32 && air === 0,
          `nousi ${rose.toFixed(0)} px, ilmassa ${air} framea rinteessä`);
      }

      /* 2. Alas kävellen: sama, ja tässä se on tarttuminen (`SLOPE_SNAP`).
       *    Ilman sitä alamäki on sarja pieniä putoamisia. */
      {
        const s = arena((sc) => {
          for (let i = 0; i < 5; i++) {
            sc.setTile(8 + i, 8 + i, '\\');
            for (let ty = 9 + i; ty <= 12; ty++) sc.setTile(8 + i, ty, '#');
          }
          for (let tx = 0; tx < 8; tx++) for (let ty = 8; ty <= 12; ty++) sc.setTile(tx, ty, '#');
        });
        const p = s.player;
        p.x = 5 * 16; p.y = 8 * 16 - p.h; p.vx = 0; p.vy = 0;
        let air = 0;
        let seen = 0;
        for (let f = 0; f < 200; f++) {
          s.update(press(1, false));
          if (p.onSlope) { seen++; if (!p.onGround) air++; }
        }
        expect('alamäkeen kävelevä pysyy maassa eikä putoile porras kerrallaan',
          seen > 20 && air === 0,
          `rinteessä ${seen} framea, ilmassa ${air}`);
      }

      /* 3. Vauhti: alamäki lainaa ylimmän nopeuden, ylämäki ei pysäytä. */
      {
        const down = arena((sc) => {
          for (let i = 0; i < 8; i++) {
            sc.setTile(6 + i, 5 + i, '\\');
            for (let ty = 6 + i; ty <= 12; ty++) sc.setTile(6 + i, ty, '#');
          }
          for (let tx = 0; tx < 6; tx++) for (let ty = 5; ty <= 12; ty++) sc.setTile(tx, ty, '#');
        });
        const dp = down.player;
        dp.x = 2 * 16; dp.y = 5 * 16 - dp.h; dp.vx = 0; dp.vy = 0;
        let flat = 0;
        let fastest = 0;
        for (let f = 0; f < 220; f++) {
          down.update(press(1, true));
          if (dp.x < 6 * 16) flat = Math.abs(dp.vx);
          fastest = Math.max(fastest, Math.abs(dp.vx));
        }
        const up = arena((sc) => rampUp(sc, 8, 5));
        const upP = up.player;
        upP.x = 3 * 16; upP.y = 13 * 16 - upP.h; upP.vx = 0; upP.vy = 0;
        let climbed = 0;
        for (let f = 0; f < 300; f++) {
          up.update(press(1, false));
          climbed = Math.max(climbed, (13 * 16 - upP.h) - upP.y);
        }
        expect('alamäki lainaa ylimmän nopeuden, ylämäki hidastaa muttei pysäytä',
          fastest > flat + 0.5 && fastest <= 3.5 + 0.001 && climbed > 60,
          `tasamaa ${flat.toFixed(2)} -> alamäki ${fastest.toFixed(2)} (katto 3.50),`
          + ` kävelijä nousi ${climbed.toFixed(0)} px`);
      }

      /* 3 b. RINNE ON KULJETTAVA JOKA KOOSSA.
       *
       * Omistajan raportti 17.8.2026: *"kun juoksen rinnettä ylös (1-1),
       * hahmo PYSÄHTYY tähän ylänurkkaan."* Niin pysähtyikin, ja vika oli
       * askelma-avussa: rinteen pinta luetaan kehon **keskikohdasta**, mutta
       * törmäyksen tekee sen **etureuna** — joka on `w/2` edempänä ja 45
       * asteen rinteessä siis `w/2` pikseliä ylempänä. Kiinteä kuuden
       * pikselin askelma riitti pienimmälle keholle (12 px) ja vain sille.
       *
       * Miksi mikään ei huomannut: `playable.mjs` ajaa botin **voimatasolla
       * 0**, eli sillä ainoalla koolla joka mahtui. Siksi tämä väite ajaa
       * jokaisen neljän kokoluokan läpi oikean kentän oikean mäen — mitattu
       * vika oli sarakkeessa 103, eli rampin viimeisen laatan ja tasanteen
       * saumassa.
       */
      {
        const sizes = [[null, 0], ['shroom', 1], ['shroom', 3], ['leaf', 5]];
        const stuck = [];
        for (const [type, level] of sizes) {
          game.state = {
            lives: 3, coins: 0, score: 0, power: { type, level }, reserve: null,
            world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [], secrets: {},
            usedSaveState: false, continues: 0, bestTimes: {},
          };
          const s = new LevelScene(game, '1-1');
          s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
          s.time = 9999;
          s.clockStopped = true;
          const p = s.player;
          const col = s.grid[13].indexOf('/');
          p.x = (col - 6) * 16;
          p.y = 13 * 16 - p.h;
          let last = p.x;
          let still = 0;
          let stalledAt = null;
          for (let f = 0; f < 400; f++) {
            s.update(press(1, true));
            if (p.x - last < 0.2) {
              still++;
              if (still > 30 && stalledAt === null) stalledAt = Math.round(p.x / 16);
            } else still = 0;
            last = p.x;
            if (p.x / 16 > col + 20) break;
          }
          if (stalledAt !== null) stuck.push(`taso ${level} (${p.w} px) sarakkeessa ${stalledAt}`);
        }
        expect('rinteen yli pääsee jokaisessa koossa, ei vain pienimmässä',
          stuck.length === 0,
          stuck.length ? stuck.join(', ') : '4/4 kokoa nousi 1-1:n kumpareen yli');
      }

      /* 4. Muunnin: huipulta lähtevä vaihtaa vauhdin korkeudeksi, ja
       *    palkinto on portaittainen — kävelijä ei lennä, juoksija hyppää,
       *    täysi mittari pääsee reitille. */
      {
        const launch = (mode) => {
          const s = arena((sc) => {
            rampUp(sc, 8, 5);
            for (let tx = 13; tx < 40; tx++) { sc.setTile(tx, 13, ' '); sc.setTile(tx, 14, ' '); }
            for (let ty = 13; ty <= 14; ty++) for (let tx = 20; tx < 40; tx++) sc.setTile(tx, ty, '#');
          });
          const p = s.player;
          p.x = 2 * 16; p.y = 13 * 16 - p.h; p.vx = 0; p.vy = 0;
          let peak = 1e9;
          let lift = null;
          for (let f = 0; f < 300; f++) {
            if (mode === 'meter') p.pMeter = P_METER_MAX;
            const i = press(1, mode !== 'walk');
            if (lift !== null) i.held.jump = true;
            s.update(i);
            if (lift === null && p.vy < -0.2 && !p.onGround && !p.dying) lift = p.y;
            if (lift !== null && !p.dying) peak = Math.min(peak, p.y);
            if (p.dying || p.y > 16 * 16) break;
          }
          return lift === null ? 0 : lift - peak;
        };
        const walk = launch('walk');
        const run = launch('run');
        const meter = launch('meter');
        expect('rinteen huippu vaihtaa vauhdin korkeudeksi, ja kävelijä ei lennä',
          walk === 0 && run > 0 && meter > run + 8,
          `kävely ${walk.toFixed(0)} px, juoksu ${run.toFixed(0)} px,`
          + ` täysi mittari ${meter.toFixed(0)} px`);
      }
    }

    game.toTitle();
    return { checks, failures };
  });
  report.checks.push(...hud.checks);
  report.failures.push(...hud.failures);
}

/* --------------------- päivän pieru, selaimen puolella -------------------- */
/*
 * Se puolisko joka on oikeasti sivulla: kentän rakentaminen, sen ainoa yritys ja
 * se rivi joka lähtee kaverille.
 *
 * Node rakentaa saman kentän tässä vieressä ja rivit verrataan merkkijonoina.
 * Se on tämän osion kallein väite ja myös sen tärkein: koko tila lepää sen
 * varassa että selain ja työkalu ovat samaa mieltä siitä mitä päivän kenttä on
 * — todistus (`src/data/daily-origin.js`) on tehty Nodessa ja pelataan
 * selaimessa.
 */
{
  const daily = await import(join(ROOT, 'src/core/daily.js'));
  const today = daily.dayNumber();
  /* Kolme päivää eikä yksi: tänään on se jota pelataan, ja kaksi muuta ovat
   * siellä missä `attempt` on jotain muuta kuin nolla — sama koodi eri
   * haaralla. */
  const sample = [today, today + 37, today + 365].filter((d) => daily.dailyCertificate(d));
  const mine = sample.map((day) => {
    const cert = daily.dailyCertificate(day);
    return { day, attempt: cert.attempt, rows: daily.dailyBuild(day, cert.attempt).def.rows.join('\n') };
  });

  const pp = await page.evaluate(async ({ jobs, todayDay }) => {
    const checks = [];
    const failures = [];
    const expect = (name, ok, detail = '') => {
      checks.push({ name, ok, detail });
      if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
    };
    const d = await import('/src/core/daily.js');
    const { LevelScene } = await import('/src/scenes/level.js');
    const { isSolid } = await import('/src/gfx/tiles.js');
    const { runGround } = await import('/tools/level-bot.js');
    const { validateLevel } = await import('/src/data/rules.js');
    const { themeProblems } = await import('/src/data/generator.js');
    const { JUMP_BUDGET } = await import('/src/data/pacing.js');
    const font = await import('/src/gfx/font.js');
    const game = window.sfb3;

    const keepDaily = localStorage.getItem('sfb3.daily.v1');
    const wipe = () => localStorage.removeItem('sfb3.daily.v1');

    /* --- 1. sivu rakentaa saman kentän kuin työkalu --- */
    {
      const bad = jobs.filter((j) => d.dailyBuild(j.day, j.attempt).def.rows.join('\n') !== j.rows);
      expect('selain rakentaa saman päivän kentän kuin Node',
        bad.length === 0,
        bad.length ? `eroaa: ${bad.map((b) => b.day).join(' ')}`
          : `${jobs.length} päivää, ${jobs.map((j) => j.attempt).join('/')} yritystä`);
    }

    /* --- 2. tämän päivän kenttä läpäisee säännöt tässä selaimessa --- */
    const level = d.dailyLevel(todayDay);
    {
      const problems = level.ok
        ? validateLevel(level.def.rows, JUMP_BUDGET)
          .concat(themeProblems(level.def.theme, level.def.rows))
        : [`kenttää ei ole: ${level.reason}`];
      expect('tämän päivän kenttä läpäisee säännöt selaimessa',
        problems.length === 0,
        problems.length ? problems.slice(0, 2).join('; ')
          : `${level.def.rows[0].length} saraketta, teema ${level.def.theme}, `
            + `merkintä "${level.def.origin}"`);
    }

    /* --- 3. ja botti pääsee sen läpi voimatasolla 0 --- */
    if (level.ok) {
      game.state = {
        lives: 9, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      let finished = null;
      game.finishLevel = (r) => { finished = r; };
      const scene = new LevelScene(game, level.def.id, level.def);
      game.scene = scene;
      scene.entities = scene.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      scene.time = 9999;
      scene.clockStopped = true;
      const r = runGround(scene, isSolid, 7000, () => finished);
      expect('päivän kenttä on läpäistävissä voimatasolla 0',
        r.cleared, r.cleared ? `${scene.w} saraketta läpi` : `eteni ${r.reach} %`);
      game.finishLevel = () => {};
    }

    /* --- 4. yksi yritys, ja lataus on luovutus --- */
    {
      wipe();
      const first = d.dailyBegin(todayDay);
      const second = d.dailyBegin(todayDay);
      expect('päivän yritys kuluu kerran ja vain kerran',
        first === true && second === false, `ensimmäinen ${first}, toinen ${second}`);

      /* Sivun lataus kesken kentän: merkintä jää 'kesken', ja se luetaan
       * tulokseksi sellaisenaan eikä uudeksi yritykseksi. */
      d.dailyProgress(todayDay, { reach: 41, score: 3400, coins: 5 });
      const midway = d.dailyStatus(todayDay);
      const forfeited = d.dailyForfeit(todayDay);
      const after = d.dailyBegin(todayDay);
      expect('lataus kesken kentän on luovutus siihen asti mihin pääsi, ei uusi yritys',
        midway === 'kesken' && forfeited.reach === 41 && forfeited.keskeytyi === true
          && after === false,
        `kesken: ${midway}, luovutettu ${forfeited.reach} %, uusi yritys: ${after}`);

      /* Eilinen merkintä ei ole tämän päivän. */
      wipe();
      d.dailyBegin(todayDay - 1);
      expect('eilinen tulos ei vie tämän päivän yritystä',
        d.dailyStatus(todayDay) === 'vapaa' && d.dailyBegin(todayDay) === true,
        `tänään: ${d.dailyStatus(todayDay)}`);
      wipe();
    }

    /* --- 4 b. eikä se koske pelaajan omaan tallennukseen --- */
    if (level.ok) {
      const keepSave = localStorage.getItem('sfb3.save.v2');
      const keepScene = game.scene;
      const keepState = game.state;
      const keepFinish = game.finishLevel;
      wipe();
      /* Kierros jossa on jotain menetettävää: kolme elämää, pisteitä ja
       * maailma 3. Päivän yritys ajetaan sen päälle ja katsotaan mitä siitä
       * jäi — sama vaatimus kuin esittelytilalla, ja sama syy. */
      const before = {
        lives: 3, coins: 17, score: 4200, power: { type: 'shroom', level: 2 }, reserve: 'flower',
        world: 2, node: 'w3-2', cleared: { 'w3-1': true }, worldsOpen: 3, cards: ['shroom'],
        secrets: {}, continues: 1, usedSaveState: false,
      };
      game.state = before;
      localStorage.setItem('sfb3.save.v2', JSON.stringify(before));
      const stored = localStorage.getItem('sfb3.save.v2');
      /* Aika-ajo päällä, koska juuri se on se tila jonka ei saa tarttua
       * mukaan: yksi yritys ja paras aika ovat vastakkaisia ajatuksia, ja
       * `setBest` kirjaisi ajan tunnuksella joka on huomenna eri kenttä. */
      game.timeAttack = true;
      game.startDaily(d.dailyLevel(todayDay));
      const duringLives = game.state.lives;
      const duringRace = game.timeAttack;
      game.finishDaily({ died: true });
      const raceBack = game.timeAttack;
      game.timeAttack = false;
      const same = localStorage.getItem('sfb3.save.v2') === stored;
      const back = game.state === before && game.state.score === 4200
        && game.state.cards.length === 1 && game.state.world === 2;
      expect('päivän yritys ei kirjoita pelaajan tallennukseen eikä vie hänen kierrostaan',
        same && back && duringLives === 1,
        `tallennus ${same ? 'ennallaan' : 'MUUTTUI'}, kierros ${back ? 'palautui' : 'HUKKUI'},`
        + ` yrityksen elämät ${duringLives}`);
      expect('päivän yritys ei ole aika-ajo, eikä se sammuta aika-ajoa jälkeensä',
        duringRace === false && raceBack === true,
        `yrityksen aikana ${duringRace}, jälkeen ${raceBack}`);
      wipe();
      if (keepSave === null) localStorage.removeItem('sfb3.save.v2');
      else localStorage.setItem('sfb3.save.v2', keepSave);
      game.state = keepState;
      game.scene = keepScene;
      game.finishLevel = keepFinish;
      game.dailyRun = null;
    }

    /* --- 5. jakorivi ei paljasta kentästä mitään --- */
    {
      /* Mitattu eikä mielipide: sama tulos kahtena eri päivänä on kahden eri
       * kentän tulos, ja jos rivi kantaisi kentästä yhdenkään merkin, nämä
       * kaksi riviä eroaisivat muualtakin kuin päiväyksestä. */
      const a = d.dailyShareLine({ day: todayDay, reach: 63, score: 12345, cleared: false });
      const b = d.dailyShareLine({ day: todayDay + 37, reach: 63, score: 12345, cleared: false });
      const strip = (s, day) => s.replace(d.dayLabel(day), '');
      expect('jakorivi kertoo tuloksen eikä kenttää',
        strip(a, todayDay) === strip(b, todayDay + 37),
        `${a} | ${b}`);
      expect('jakorivissä ei ole kentän teemaa eikä tunnusta',
        !/GRASS|DESERT|NIGHT|ICE|FACTORY|BONE|CLOUD|MAAILMA/.test(a.toUpperCase()), a);
    }

    /* --- 6. jokainen tilan piirtämä merkki on fontissa --- */
    {
      const canvas = document.createElement('canvas');
      canvas.width = 16;
      canvas.height = 12;
      const g = canvas.getContext('2d');
      const missing = new Set();
      for (const s of d.dailyStrings()) {
        for (const ch of String(s).toUpperCase()) {
          if (ch === ' ') continue;
          g.clearRect(0, 0, 16, 12);
          font.drawText(g, ch, 2, 2, { color: '#ffffff' });
          const px = g.getImageData(0, 0, 16, 12).data;
          let ink = 0;
          for (let i = 3; i < px.length; i += 4) if (px[i] > 0) ink++;
          if (!ink) missing.add(ch);
        }
      }
      expect('päivän pierun jokainen merkkijono on kirjoitettavissa pelin fontilla',
        missing.size === 0, missing.size ? `puuttuu: ${[...missing].join('')}`
          : `${d.dailyStrings().length} merkkijonoa`);
    }

    /* --- 7. valikko mahtuu ruudulle silloinkin kun se on pisimmillään --- */
    {
      /*
       * Mitataan **ruudun ulkopuolelle** eikä ruudun sisälle, ja se on koko
       * mittauksen juju: alkuruutu maalaa taustan liukuvärillä joka peittää
       * rivit 0–239, joten "alin väritetty rivi" on 239 riippumatta siitä mitä
       * valikolle tapahtuu. 280 pikseliä korkealla piirtoalustalla rivit 240 ja
       * alle ovat läpinäkyviä ellei jokin piirry niille — eli ne ovat tasan se
       * mitä pelaaja ei näkisi.
       *
       * JA VALIKKO LUETAAN `enter()`:ISTÄ EIKÄ KIRJOITETA TÄHÄN. Tämä väite
       * kirjoitettiin kun rivejä oli neljä, ja rivi viisi saapui viikossa
       * toisesta haarasta (aika-ajo). Käsin kirjoitettu lista olisi mitannut
       * neljää riviä sinä päivänä jona ruudulla on viisi — eli se olisi
       * lakannut mittaamasta juuri sitä mitä se on olemassa mittaamaan.
       * Tallennuksen olemassaolo on ainoa asia joka listan pituuden ratkaisee,
       * joten se väännetään molempiin asentoihin ja kysytään ruudulta.
       */
      const { TitleScene } = await import('/src/scenes/title.js');
      const canvas = document.createElement('canvas');
      canvas.width = 320;
      canvas.height = 280;
      const g = canvas.getContext('2d');
      const keepSave = localStorage.getItem('sfb3.save.v2');
      const lowest = (hasSave) => {
        if (hasSave) localStorage.setItem('sfb3.save.v2', '{"lives":4}');
        else localStorage.removeItem('sfb3.save.v2');
        const stand = Object.create(game);
        const title = new TitleScene(stand);
        title.enter();
        title.tick = 40;
        title.puffs = [];
        g.clearRect(0, 0, 320, 280);
        title.draw(g);
        const px = g.getImageData(0, 0, 320, 280).data;
        let last = -1;
        for (let y = 0; y < 280; y++) {
          for (let x = 0; x < 320; x++) if (px[(y * 320 + x) * 4 + 3] > 0) { last = y; break; }
        }
        return { last, rows: title.options.length };
      };
      const withSave = lowest(true);
      const without = lowest(false);
      if (keepSave === null) localStorage.removeItem('sfb3.save.v2');
      else localStorage.setItem('sfb3.save.v2', keepSave);
      expect('alkuruudun valikko ja sen opaste mahtuvat ruudulle myös pisimmillään',
        withSave.last <= 239 && without.last <= 239,
        `${withSave.rows} riviä ${withSave.last}, ${without.rows} riviä ${without.last}`
        + ' (ruudun viimeinen rivi 239)');
    }

    if (keepDaily === null) wipe(); else localStorage.setItem('sfb3.daily.v1', keepDaily);
    return { checks, failures };
  }, { jobs: mine, todayDay: today });

  report.checks.push(...pp.checks);
  report.failures.push(...pp.failures);
}


/* ---- velat: 4-3, kuolleet palikat, kontrasti, oneup ---- */
/*
 * Neljä velkaa, yksi lohko, ja jokainen niistä on tässä samasta syystä: ne
 * kaikki olivat asioita jotka **joku muisti** eivätkä asioita joita mikään
 * mittasi. 4-3:n läpäisemättömyys asui muutoslokin "tiedossa olevissa
 * rajoituksissa", kuolleet palikat "jäi tekemättä" -listalla, neljän
 * vihollisen kontrasti portin *mittaamatta*-rivillä ja varapallo pelkkänä
 * hiljaisuutena. Muistiinpano kestää täsmälleen niin kauan kuin sen kirjoittaja.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  /* --- 1. jokainen kenttä on läpäistävissä voimatasolla 0 --- */
  /*
   * DESIGN.md kohta 5 lupaa että maareitti aukeaa pienimmällä koolla ilman
   * yhtään tehostusta. `tools/playable.mjs` on kysynyt sitä pitkään ja
   * vastannut siihen raporttina, ei porttina — se ei kaadu, koska sen botti
   * on heuristiikka ja "huono botti kaataa hyvän kentän" on väärin päin.
   *
   * Mutta raportti jonka kukaan ei ole velvollinen lukemaan on muistiinpano, ja
   * juuri niin kävi: 4-3 seisoi tuolla raportilla **rikkinäisenä niin kauan
   * että siitä tuli rivi muutoslokin rajoituslistalla**. Ja koska kukaan ei
   * lukenut listaa loppuun, 2-1 oli sen rinnalla saman lupauksen rikkojana
   * ilman että sitä oli koskaan mainittu missään.
   *
   * Ero raporttiin on se että tämä ei kysy botilta mielipidettä kentästä vaan
   * kentältä mielipidettä botista: **kaikki kuusikymmentä tai punainen.**
   * Poikkeuslistaa ei ole, koska sellaista ei tarvita — ja jos sellainen
   * joskus tarvitaan, se kirjoitetaan tähän nimeltä ja perusteluineen eikä
   * muutoslokiin.
   */
  {
    const rows = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const { isSolid } = await import('/src/gfx/tiles.js');
      const { levelIds, getLevel: getLevelDef } = await import('/src/data/levels.js');
      const { runGround } = await import('/tools/level-bot.js');
      const { isClimb } = await import('/tools/climb-bot.js');
      const game = window.sfb3;
      const out = [];
      const keepFinish = game.finishLevel;
      for (const id of levelIds()) {
        game.state = {
          lives: 9, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
          world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
        };
        let finished = null;
        game.finishLevel = (r) => { finished = r; };
        const scene = new LevelScene(game, id);
        game.scene = scene;
        /* Viholliset ja vaarat pois: tämä väite koskee maastoa. Ne kuolemat on
         * mitattu muualla ja ne ovat tunnettua kohinaa. */
        scene.entities = scene.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        if (scene.def.boss) scene.bossDefeated = true;
        scene.time = 9999;
        scene.clockStopped = true;
        /* Pystykentät kiipeävät eivätkä juokse; niillä on oma todisteensa
         * `climb-bot.js`:ssä ja `playable.mjs`:ssä. Peliin ei kuulu vielä
         * yhtään, joten tämä haara on varaus eikä poikkeus. */
        if (isClimb(scene.def)) { out.push({ id, cleared: true, reach: 100, vertical: true }); continue; }
        const r = runGround(scene, isSolid, 7000, () => finished);
        out.push({ id, cleared: r.cleared, reach: r.reach, at: r.death ? r.death.tx : r.stuckAt });
      }
      game.finishLevel = keepFinish;
      return out;
    });
    const stuck = rows.filter((r) => !r.cleared);
    expect('jokainen kenttä on läpäistävissä voimatasolla 0',
      stuck.length === 0,
      stuck.length
        ? `${stuck.length}/${rows.length} jäi: ${stuck.map((r) => `${r.id} ${r.reach} % (sarake ${r.at})`).join(', ')}`
        : `${rows.length} kenttää, matalin eteneminen ${Math.min(...rows.map((r) => r.reach))} %`);
  }

  /* --- 2. palikkataulussa ei ole palikkaa jota mikään kenttä ei aseta --- */
  /*
   * Sama peruste jolla `bone_twin` poistettiin, nyt mittana: palikka jota
   * kukaan ei saa asettaa on huonompi kuin ei palikkaa, koska se lupaa
   * sanaston jota ei ole. Kysymys on puhtaasti datasta — kaikki soittolistat
   * ja kaikki kaistat vastaan koko `CHUNKS` — eikä sitä siksi tarvitse
   * muistaa.
   *
   * **Poikkeuslista on nolla, ja se on tämän väitteen tärkein luku.** Tässä
   * luki 10.8.2026 asti neljä nimeä — `chunks/fortresses.js`:n `pyre_ledge`,
   * `crypt_ossuary`, `crypt_stair` ja `spire_squall` — koska se tiedosto oli
   * toisen työn alla eikä väite saanut koskea siihen. Ne on poistettu, ja
   * niiden mukana lähti se lista josta olisi voinut kasvaa tapa: nimetty
   * poikkeus on halpa lisätä ja kallis huomata, ja portti jossa ei ole
   * yhtään on ainoa portti jota ei tarvitse lukea ennen kuin siihen luottaa.
   */
  {
    const { CHUNKS } = await import(join(ROOT, 'src/data/chunks.js'));
    const worlds = await Promise.all([1, 2, 3, 4, 5, 6, 7, 8]
      .map((n) => import(join(ROOT, `src/data/levels/world${n}.js`))));
    const defs = Object.assign({}, ...worlds.map((m) => Object.values(m)[0]));
    const used = new Set();
    for (const def of Object.values(defs)) {
      for (const n of def.chunks || []) used.add(n);
      for (const band of ['sky', 'cave']) for (const [, n] of def[band] || []) used.add(n);
    }
    const dead = Object.keys(CHUNKS).filter((n) => !used.has(n));
    expect('yksikään palikka ei ole sellainen jota mikään kenttä ei aseta',
      dead.length === 0,
      `${Object.keys(CHUNKS).length} palikkaa, ${used.size} käytössä, `
      + `${dead.length} orpoa${dead.length ? `: ${dead.join(', ')}` : ''} (poikkeuksia 0)`);
  }

  /* --- 3. neljä vihollista, jotka olivat kontrastikynnyksen alla --- */
  /*
   * Portilla on ollut tämä mitta pitkään, mutta se **portitti kolme lajia ja
   * mittasi loput**: kolme uudelleenpiirrettyä kaadetaan, muut tulostetaan
   * rivillä "mittaamatta portissa". Se rivi sanoi 10.8.2026 aamulla
   * piikkiukko 3,3 %, papuparooni 3,3 %, ummetuskorkki 7,2 %, ruskea pilvi
   * 7,4 % — kynnys 8,6 % — eli neljä asiaa jotka voivat tappaa pelaajan
   * seisoivat maassa jota vasten niitä ei erota.
   *
   * Ne on maalattu uudestaan, ja tämä on se väite joka pitää maalin paikallaan.
   * Sama kaava kuin vieressä ja tarkoituksella: keskimääräinen kanavaero
   * 255:stä, ääriviiva pois laskuista, ja kynnys luettuna aavikon omasta
   * maa/tiili-parista eikä kirjoitettuna käsin — "vähintään yhtä erillään kuin
   * se huonoin pari jonka kanssa peli jo elää" pysyy totena kun paletti
   * liikkuu.
   */
  {
    const rows = await page.evaluate(async () => {
      const sprites = await import('/src/gfx/sprites.js');
      const { THEMES, T, drawTile } = await import('/src/gfx/tiles.js');
      const W = 96; const H = 64; const OX = 32; const OY = 16;
      const cv = document.createElement('canvas');
      cv.width = W; cv.height = H;
      const g = cv.getContext('2d', { willReadFrequently: true });
      /* Vain nämä neljä, ja jokainen värinsä kanssa: läpikuultavat vanat ja
       * varjot eivät ole ruumista (sama raja kuin viereisellä portilla). */
      const ART = new Set([
        '248,248,248',
        // piikkiukko: runko + luupiikit, jotka ovat jaettua sanastoa
        '240,40,200', '168,12,144', '120,4,108',
        '232,224,200', '168,152,120', '90,80,64',
        // ruskea pilvi
        '180,164,16', '108,96,4',
        // ummetuskorkki: kumitulppa ja se korkki jonka se ampuu
        '48,96,200', '28,56,120', '16,28,72', '216,168,96', '156,106,40',
        // papuparooni
        '156,16,96', '88,8,52', '60,8,36', '108,16,68', '240,184,144', '255,208,72',
      ]);
      const subjects = [
        { n: 'piikkiukko', paint: () => sprites.drawSpikeGuy(g, OX, OY, 0, 1) },
        { n: 'ruskea pilvi', paint: () => sprites.drawStinkCloud(g, OX, OY, 0, 1, true) },
        { n: 'ummetuskorkki', paint: () => sprites.drawCorkGuy(g, OX, OY, 0, 1) },
        { n: 'papuparooni', paint: () => sprites.drawBeanBaron(g, OX, OY, 0, 1, 0, false) },
      ];
      /* Kuinka monta pikseliä viimeinen mittaus luki. Tämä on ulkona siksi että
       * `ART`-lista voi mennä hiljaa vanhaksi: väri jota lista ei tunne ei
       * kaada mitään, se vain katoaa otoksesta. Luku tulostuu jokaisesta
       * lajista, joten kutistunut otos näkyy ennen kuin se ehtii valehdella. */
      let seen = 0;
      const mean = (paint, art) => {
        g.clearRect(0, 0, W, H);
        paint();
        const d = g.getImageData(0, 0, W, H).data;
        let r = 0; let gg = 0; let b = 0; let n = 0;
        for (let i = 0; i < W * H; i++) {
          const q = i * 4;
          if (d[q + 3] !== 255) continue;
          const key = `${d[q]},${d[q + 1]},${d[q + 2]}`;
          if (art && !art.has(key)) continue;
          r += d[q]; gg += d[q + 1]; b += d[q + 2]; n++;
        }
        seen = n;
        return n ? [r / n, gg / n, b / n] : null;
      };
      const tile = (ch, theme) => mean(() => drawTile(g, ch, 0, 0, theme, 3, 5, 0, ' ', {}), null);
      const sep = (a, b) => (!a || !b ? 0
        : ((Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2])) / 3 / 255) * 100);
      const floor = sep(tile(T.GROUND, 'desert'), tile(T.BRICK, 'desert'));
      const grounds = Object.keys(THEMES).map((th) => [th, tile(T.GROUND, th)]);
      return {
        floor,
        rows: subjects.map((s) => {
          const m = mean(s.paint, ART);
          const px = seen;
          let worst = { th: '?', v: 1e9 };
          for (const [th, ground] of grounds) {
            const v = sep(m, ground);
            if (v < worst.v) worst = { th, v };
          }
          return { n: s.n, px, ...worst };
        }),
      };
    });
    const sunk = rows.rows.filter((r) => r.v < rows.floor);
    expect('neljä huonoiten näkyvää vihollista erottuvat nyt jokaisen teeman maasta',
      sunk.length === 0,
      `kynnys ${rows.floor.toFixed(1)} % = aavikon maa vs tiili; `
      + rows.rows.map((r) => `${r.n} ${r.v.toFixed(1)} % (${r.th}, ${r.px} px)`).join(', '));
  }

  /* --- 4. piirretty poimittava on sellainen jonka peli osaa antaa --- */
  /*
   * Varapallo oli piirretty, poimittava, äänekäs ja mitattu neljällä akselilla,
   * eikä yksikään ruutu, lohko, vihollinen tai generaattori tuottanut sitä
   * koskaan. Se on omanlaisensa kuollut koodi: ei haara jota ei ajeta vaan
   * **ominaisuus jota teeskennellään**, ja se on huonompi kuin puuttuva
   * ominaisuus, koska se lukee valmiilta jokaiselle joka avaa tiedoston.
   *
   * Väite on tarkoituksella yleinen eikä varapallon nimi: jokainen kuva jonka
   * `drawItem` maalaa on kuva esineestä jonka joku voi saada. Tuottaja on
   * lähdekoodissa `new Item(...)`, `rollPowerup`in `return` tai maalitangon
   * `completeLevel(...)` — kolme paikkaa, ja kolme on koko lista. `Sfx.play`ta
   * ei lasketa, ja juuri se ero on tässä se joka merkitsee: `Sfx.play('oneup')`
   * elää yhä sadan kolikon ja korttipotin äänenä, eikä ääni ole esine.
   */
  {
    const CANDIDATES = ['shroom', 'flower', 'leaf', 'soup', 'pop', 'star', 'oneup'];
    const drawable = await page.evaluate(async (kinds) => {
      const sprites = await import('/src/gfx/sprites.js');
      const cv = document.createElement('canvas');
      cv.width = 48; cv.height = 48;
      const g = cv.getContext('2d', { willReadFrequently: true });
      const out = [];
      for (const k of kinds) {
        g.clearRect(0, 0, 48, 48);
        sprites.drawItem(g, k, 16, 16, 0);
        const d = g.getImageData(0, 0, 48, 48).data;
        let n = 0;
        for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++;
        if (n > 0) out.push(k);
      }
      return out;
    }, CANDIDATES);
    const SOURCES = ['src/scenes/level.js', 'src/entities/enemies.js'];
    const text = (await Promise.all(SOURCES.map((f) => readFile(join(ROOT, f), 'utf8')))).join('\n');
    const spawnLines = text.split('\n').filter((l) => l.includes('new Item(')
      || /\breturn '/.test(l) || l.includes('completeLevel('));
    const spawned = new Set(CANDIDATES.filter((k) => spawnLines.some((l) => l.includes(`'${k}'`))));
    const ghosts = drawable.filter((k) => !spawned.has(k));
    expect('jokainen piirretty poimittava on sellainen jonka peli osaa antaa',
      ghosts.length === 0,
      `piirrettyjä ${drawable.length} (${drawable.join(' ')}), `
      + `tuotettuja ${spawned.size} (${[...spawned].join(' ')})`
      + (ghosts.length ? ` — kuvia ilman lähdettä: ${ghosts.join(', ')}` : ''));
  }

  /*
   * YKSI OSOITE, JA KAIKKI MUUT VIITTAAVAT SIIHEN.
   *
   * `og:url` on ajonaikainen totuus: `share.js` lukee juuri sen metatagin eikä
   * `location.href`:iä, jotta jaettu linkki on aina se osoite jolla on
   * esikatselukuva. Ongelma ei ole se tagi vaan sen **kopiot** — README:n
   * pelilinkki, `challenge.js`:n esimerkki, CLAUDE.md:n julkaisuohje — jotka
   * eivät ole koodia eivätkä siksi kaadu mihinkään kun osoite vaihtuu.
   *
   * Ja se vaihtui: `sfb3.vercel.app` → `kaasuvoima.vercel.app` ja
   * `github.io/sfb3` → `github.io/kaasuvoima`. Kaikki kolme kopiota olisivat
   * jääneet osoittamaan kuolleeseen domainiin, eikä yksikään portti olisi
   * sanonut mitään. Sama vika kuin jakorivin nimessä ja talloportin
   * apuluvuissa: vakio joka kuvaa jotain luettavaa on luettava eikä
   * kirjoitettava uudelleen — ja kun se on pakko kirjoittaa (Markdown ei osaa
   * lukea metatagia), portti vertaa kopiot alkuperäiseen.
   *
   * CHANGELOG on tarkoituksella ulkopuolella: se kertoo missä peli **oli**
   * 8.8.2026, ja historian korjaaminen nykyhetkeen tekisi lokista valheen.
   */
  {
    const html = await readFile(join(ROOT, 'index.html'), 'utf8');
    const og = /<meta\s+property="og:url"\s+content="([^"]+)"/.exec(html);
    const canonical = og ? new URL(og[1]).host : null;
    const COPIES = ['README.md', 'CLAUDE.md', 'src/core/challenge.js', 'index.html'];
    const bad = [];
    for (const f of COPIES) {
      const text = await readFile(join(ROOT, f), 'utf8');
      for (const m of text.matchAll(/([a-z0-9-]+\.vercel\.app)/g)) {
        if (m[1] !== canonical) bad.push(`${f}: ${m[1]} != ${canonical}`);
      }
      for (const m of text.matchAll(/github\.io\/([a-z0-9-]+)/gi)) {
        if (m[1] !== REPO_SLUG) bad.push(`${f}: github.io/${m[1]} != github.io/${REPO_SLUG}`);
      }
    }
    expect('jokainen osoitteen kopio osoittaa samaan paikkaan kuin og:url',
      !!canonical && bad.length === 0,
      bad.length ? bad.join(' | ') : `og:url ${canonical}, pages /${REPO_SLUG}, ${COPIES.length} tiedostoa`);
  }

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- velat: loppu ---- */

/* ---- rippeet: kartan äänet, reseptin proosa ---- */
/*
 * Kaksi rippeenä jäänyttä epäsiisteyttä, ja kumpikin on tässä siksi että
 * kummallakin on **luku**: peli ei ollut rikki, mutta se sanoi jotain jota se
 * ei olisi voinut todistaa.
 *
 * 1. **Kartta soitti `powerup`in kun mikään ei kasvanut.** Sama vika kuin
 *    kentän puolella aamulla, samassa tapahtumassa (varalokero täyttyy) — ja
 *    aamun korjaus ei ulottunut karttakohtaukseen, koska se väite ajettiin
 *    `LevelScene`ä vasten. Merkki joka valehtelee opitaan uskomaan, ja se on
 *    yhtä totta kartalla kuin kentässä.
 * 2. **Generaattorin resepti nimesi kenttiä joita peli ei toimita.** Reseptin
 *    luvut ovat mitattuja, ja mittaus jonka lähde on poissa on muistiinpano.
 *    Se ei riko mitään tänään — `src/data/generated.js` on ennallaan — mutta
 *    seuraava generointiajo mittaisi jostakin mitä ei ole.
 *
 * Molemmat väitteet on kirjoitettu niin ettei kumpaankaan jää nimettyä
 * poikkeusta. Se on tämän erän oma opetus: samassa työssä poistettiin neljä
 * orpoa palikkaa, ja niiden mukana meni viereisen väitteen poikkeuslista
 * nollaan. Lista jota saa kasvattaa kasvaa.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  /* --- 1. varalokero täyttyy kartalla: sama tapahtuma, sama merkki --- */
  /*
   * Kolme mittausta yhdessä, koska yksi niistä yksin ei sano mitä tarkoitetaan:
   *
   *   - kartalla lokeroon menevä esine soittaa jotain **muuta** kuin `powerup`
   *   - se on **sama** ääni jonka kenttä soittaa samasta tapahtumasta (yksi
   *     tapahtuma, yksi merkki — ei kahta murretta samalle asialle)
   *   - ja `powerup` soi kartalla yhä siellä missä jotain oikeasti kasvaa,
   *     eli lokeroa käytettäessä. Ilman tätä kolmatta riviä väite menisi läpi
   *     myös vaientamalla koko kartan.
   */
  {
    const heard = await page.evaluate(async () => {
      const { WorldMapScene } = await import('/src/scenes/worldmap.js');
      const { LevelScene } = await import('/src/scenes/level.js');
      const { Sfx } = await import('/src/core/audio.js');
      const game = window.sfb3;

      const real = Sfx.play;
      const tapped = [];
      Sfx.play = function tap(name) { tapped.push(name); };
      const take = () => { const out = tapped.slice(); tapped.length = 0; return out; };

      const blank = () => ({
        left: false, right: false, up: false, down: false, jump: false, run: false,
        start: false, mute: false, quicksave: false, quickload: false, slot: false,
      });
      const state = (extra) => {
        game.state = {
          lives: 5, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
          world: 0, node: 'w1-h', cleared: {}, worldsOpen: 8, cards: [], ...extra,
        };
        game.finishLevel = () => {};
      };

      try {
        /* a) talossa poimittu esine menee varastoon: kartta ei kasvata mitään. */
        state({});
        /* The room, not the map: `house.js` owns what happens in one since
         * 19.8.2026, and the sound this check is about is made in there. */
        const { House: ItemHouse } = await import('/src/scenes/house.js');
        const map = new ItemHouse(game, { id: 'w1-h', game: 'items' }, () => {});
        map.houseCursor = 0;
        take();
        map.update({
          held: blank(), pressed: { ...blank(), jump: true }, released: blank(), consume() {},
        });
        const toStore = take();
        const storedItem = game.state.reserve;

        /* b) sama tapahtuma kentässä: täysi voimataso, poimittu tehostus. */
        state({ power: { type: 'shroom', level: 5 } });
        const scene = new LevelScene(game, '1-1');
        scene.entities = scene.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        scene.time = 9999;
        scene.clockStopped = true;
        game.setScene(scene);
        take();
        scene.player.collect('shroom');
        const inLevel = take();

        /* c) ja kartalla käytetty varasto, jossa jotain oikeasti kasvaa. */
        state({ reserve: 'shroom', power: { type: null, level: 0 } });
        const map2 = new WorldMapScene(game);
        take();
        map2.useReserve();
        const spent = take();
        const grewTo = game.state.power.level;

        return { toStore, inLevel, spent, storedItem, grewTo };
      } finally { Sfx.play = real; }
    });

    const [store] = heard.toStore;
    const [level] = heard.inLevel;
    const [spend] = heard.spent;
    expect('varalokeron täyttyminen kuulostaa kartalla samalta kuin kentässä, eikä kasvamiselta',
      heard.toStore.length === 1 && heard.inLevel.length === 1 && heard.spent.length === 1
      && !!store && store === level && store !== 'powerup'
      && spend === 'powerup' && heard.grewTo > 0 && !!heard.storedItem,
      `varastoon kartalla "${heard.toStore.join('+') || '-'}" (${heard.storedItem || '-'}), `
      + `kentässä "${heard.inLevel.join('+') || '-'}", `
      + `varastoa käyttäen "${heard.spent.join('+') || '-'}" (taso 0 → ${heard.grewTo})`);
  }

  /* --- 2. `powerup` on kartallakin vain siellä missä jokin kasvaa --- */
  /*
   * Ylempi väite ajaa kolme tapahtumaa; tämä lukee koko tiedoston. Ero on se
   * joka `level.js`:n kohdalla jo opittiin: kohtauksessa on kutsupaikkoja
   * joihin testi ei aja, ja niistä juuri ne unohtuvat. Samalla tuloste kantaa
   * kartan koko äänisanaston, jotta DESIGN.md kohdan 8 tarkistus on luettavissa
   * portin ajosta eikä muistilapusta.
   */
  {
    const src = await readFile(join(ROOT, 'src/scenes/worldmap.js'), 'utf8');
    const calls = [...src.matchAll(/Sfx\.play\('([a-z]+)'\)/g)];
    const tally = {};
    for (const [, name] of calls) tally[name] = (tally[name] || 0) + 1;
    const useAt = src.indexOf('useReserve()');
    const powerups = calls.filter((m) => m[1] === 'powerup');
    const outside = powerups.filter((m) => m.index < useAt);
    expect('kartan `powerup` soi vain siinä yhdessä paikassa jossa voimataso nousee',
      powerups.length === 1 && outside.length === 0,
      `${calls.length} kutsua: `
      + Object.entries(tally).sort().map(([n, c]) => `${n} ${c}`).join(', '));
  }

  /* --- 3. resepti ei nimeä kenttää jota peli ei toimita --- */
  /*
   * `tools/gen-levels.mjs`:n reseptit perustelevat `density`-, `maxGap`- ja
   * `aim`-lukunsa käsintehdyillä kentillä, nimeltä ja väliltä (`6-1…6-3`).
   * Käsintehty kenttä voi vaihtua — 6-3 ja 7-2 vaihtuivat pystykentiksi
   * 10.8.2026 — ja silloin perustelu osoittaa tyhjään ilman että mikään
   * punastuu: generaattoria ei ajeta joka päivä, ja `generated.js` on
   * committoitu.
   *
   * Väite lukee tiedoston tekstinä ja laajentaa välit: `X-a…X-b` numeerisin
   * päin tarkoittaa jokaista kenttää päiden välissä, koska juuri sitä se
   * lukijalle lupaa. Jokainen näin löytyvä tunnus on oltava `levelIds()`:ssä —
   * **eikä poikkeuslistaa ole**, vaan poistuneet ankkurit luetellaan
   * tiedostossa itsessään rivinä `POISTUNUT vanha -> uusi`, ja väite kääntyy
   * niille toisin päin: vanhan **ei saa** olla pelissä ja uuden **on**. Niin
   * merkintä vanhenee itsestään punaiseksi jos poistettu kenttä palaa, eikä
   * siitä voi tulla lista johon lisätään.
   */
  {
    const src = await readFile(join(ROOT, 'tools/gen-levels.mjs'), 'utf8');
    const { levelIds } = await import(join(ROOT, 'src/data/levels.js'));
    const ships = new Set(levelIds());
    const text = src.replace(/`/g, '');

    const retired = new Map();
    for (const m of text.matchAll(/POISTUNUT ([1-8]-[0-9A-Z]) -> ([1-8]-[0-9A-Z])\b/g)) {
      retired.set(m[1], m[2]);
    }

    const cited = new Set();
    /* Väli on väite jokaisesta päiden välissä olevasta kentästä. Kirjainpää
     * (`4-1…4-F`) ei ole numeerinen väli vaan lista, joten siitä luetaan päät. */
    for (const m of text.matchAll(/\b([1-8])-([0-9A-Z])…\1-([0-9A-Z])\b/g)) {
      const [, w, a, b] = m;
      if (/[0-9]/.test(a) && /[0-9]/.test(b)) {
        for (let i = Number(a); i <= Number(b); i++) cited.add(`${w}-${i}`);
      } else { cited.add(`${w}-${a}`); cited.add(`${w}-${b}`); }
    }
    for (const m of text.matchAll(/\b[1-8]-[0-9A-Z]\b/g)) cited.add(m[0]);

    const ghosts = [...cited].filter((id) => !ships.has(id) && !retired.has(id)).sort();
    const risen = [...retired.keys()].filter((id) => ships.has(id)).sort();
    const missing = [...retired.values()].filter((id) => !ships.has(id)).sort();
    expect('generaattorin resepti nimeää vain kenttiä jotka peli toimittaa',
      ghosts.length === 0 && risen.length === 0 && missing.length === 0,
      `${cited.size} nimettyä kenttää, ${retired.size} poistunutta ankkuria`
      + `${retired.size ? ` (${[...retired].map(([a, b]) => `${a}→${b}`).join(', ')})` : ''}`
      + `${ghosts.length ? ` — pelistä puuttuu: ${ghosts.join(', ')}` : ''}`
      + `${risen.length ? ` — poistunut on palannut: ${risen.join(', ')}` : ''}`
      + `${missing.length ? ` — korvaaja puuttuu: ${missing.join(', ')}` : ''}`);
  }

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- rippeet: loppu ---- */
/* ---- emergenssi: neljä lakia ---- */
/*
 * NELJÄ LAKIA, JA SE RAJA JOKA TEKEE NIISTÄ TURVALLISIA.
 *
 * ROADMAP 10.8.2026: **maasto → olio ja olio ↔ olio, ei olio → maastoa.** Raja
 * on koko turvamarginaali eikä makuasia. Spelunky saa antaa kaiken vaikuttaa
 * kaikkeen koska sen kenttä on kertakäyttöinen; tässä pelissä kentän on aina
 * oltava läpäistävissä (DESIGN.md kohta 5), ja **jokainen nykyinen portti
 * olettaa että kenttä on staattinen** — `playable.mjs` ajaa botin lähtötilan
 * läpi, `validateLevel` lukee ruudukkoa, `difficulty.mjs` mittaa layoutin.
 *
 * Siksi jokainen laki tässä lohkossa on joko yksisuuntainen (maasto vaikuttaa
 * olioon) tai olioiden välinen, ja se yksi kohta jossa maasto liikkuu —
 * mureneva lauta ja putoava möykky — **palautuu itsestään**. Palautuva muutos
 * on tilapäinen tapahtuma staattisessa kentässä; palautumaton olisi olio joka
 * muokkaa kenttää, ja silloin reitti voisi kadota.
 *
 * Mitattu, ei muistettu: jokainen väite kantaa lukunsa mukanaan.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const E = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { Walker, ShellGuy, Flyer, BeanBomb } = await import('/src/entities/enemies.js');
    const { T } = await import('/src/gfx/tiles.js');
    const { captureState, restoreState } = await import('/src/core/savestate.js');
    const { WORLDS } = await import('/src/data/worlds.js');
    const game = window.sfb3;

    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const reset = () => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
    };
    /* Oma kenttä joka väitteelle, viholliset ja vaarat pois: mitattava olio on
     * se joka tähän pannaan eikä se joka sattuu olemaan lähellä. */
    const scene = (id) => {
      reset();
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    const put = (s, e) => { e.active = true; e.alwaysActive = true; s.entities.push(e); return e; };
    const r1 = (v) => Math.round(v * 10) / 10;
    const out = {};

    /* --- 1. jää on liukas kaikille -------------------------------------- */
    /*
     * Mitataan **käännös**, ei lähtö, ja se on itsessään löydös: pito on sen
     * maan ominaisuus jonka päällä keho seisoo, joten se näkyy vasta kun jokin
     * pakottaa vauhdin muuttumaan. Seinä on juuri se jokin — `moveX` nollaa
     * vauhdin osumassa — ja se on maastoa, eli koko mittaus pysyy laissa
     * "maasto → olio".
     *
     * Sama kävelijä, sama seinä kolmen laatan päässä, kaksi teemaa. Ruoholla
     * kävelijä saa vauhtinsa takaisin yhdellä framella (60 framea × 0,55 =
     * täsmälleen 33 px, eli mikään ei muuttunut siellä missä lakia ei ole);
     * jäällä se tarvitsee 55 framea eikä ehdi.
     */
    {
      const walk = (id) => {
        const s = scene(id);
        const i = mkInput();
        const p = s.player;
        const w = put(s, new Walker(s, p.x + 48, p.y + p.h - 16));
        w.facing = 1;
        w.vx = 0;
        const row = Math.floor((w.y + w.h - 1) / 16);
        s.setTile(Math.floor(w.x / 16) + 3, row, T.HARD);
        let turn = -1;
        let xAtTurn = 0;
        let moved = 0;
        for (let f = 0; f < 300; f++) {
          s.update(i);
          if (turn < 0 && w.facing < 0) { turn = f; xAtTurn = w.x; }
          if (turn >= 0 && f === turn + 60) moved = xAtTurn - w.x;
        }
        return { theme: s.theme, turn, moved: r1(moved), speed: w.speed };
      };
      out.ice = { grass: walk('1-1'), ice: walk('3-1'), frames: 60 };
    }

    /* --- 2. mureneva lauta pettää vihollisen alta, ja kasvaa takaisin ---- */
    {
      const s = scene('4-1');
      const i = mkInput();
      let spot = null;
      for (let ty = 0; ty < s.h && !spot; ty++) {
        for (let tx = 0; tx < s.w; tx++) if (s.grid[ty][tx] === T.CRUMBLE) { spot = { tx, ty }; break; }
      }
      if (!spot) out.plank = { found: false };
      else {
        const w = put(s, new Walker(s, spot.tx * 16, spot.ty * 16 - 16));
        w.speed = 0;           // seisoo paikallaan: mitataan lauta, ei kävelyä
        w.vx = 0;
        let started = 0;
        for (let f = 0; f < 60; f++) {
          s.update(i);
          if (!started && s.crumbleProgress(spot.tx, spot.ty) > 0) started = f + 1;
        }
        const gone = s.tileAt(spot.tx, spot.ty) === T.EMPTY;
        for (let f = 0; f < 320; f++) s.update(i);
        const back = s.tileAt(spot.tx, spot.ty) === T.CRUMBLE;
        out.plank = { found: true, at: `${spot.tx},${spot.ty}`, started, gone, back };
      }
    }

    /* --- 3. tuuli kantaa kuoria ja vihollisia --------------------------- */
    /* Sama kenttä ja sama olio kahdessa eri kohdassa tuulen sykliä: puuska on
     * päällä kun `tick % 600 > 380`. Kaksi eri kenttää olisi mitannut maastoa. */
    {
      const gustAt = (startTick) => {
        const s = scene('2-N');
        const i = mkInput();
        const p = s.player;
        const fl = put(s, new Flyer(s, p.x + 40, p.y + p.h - 16));
        fl.facing = 1;
        s.tick = startTick;
        const x0 = fl.x;
        for (let f = 0; f < 60; f++) s.update(i);
        return r1(fl.x - x0);
      };
      out.wind = { gust: gustAt(400), calm: gustAt(0), frames: 60 };
    }

    /* --- 4. potkaistu kuori tappaa sen mihin osuu ----------------------- */
    /* Kävelijä on lähtötaso (se on kuollut aina), papupommi on se jota liukuva
     * kuori ei ole koskaan koskenut: `shellSweep` luki vain `kind === 'enemy'`,
     * ja papupommi on `hazard`. */
    {
      const s = scene('1-1');
      const i = mkInput();
      const p = s.player;
      const sh = put(s, new ShellGuy(s, p.x + 40, p.y + p.h - 24));
      sh.kick(1);
      const bomb = put(s, new BeanBomb(s, sh.x + 4, sh.y + 2, 0));
      const wk = put(s, new Walker(s, sh.x + 4, sh.y + 10));
      s.update(i);
      out.shell = { bomb: !!bomb.remove, walker: !!(wk.dying || wk.remove) };
    }

    /* --- 5. putoava laatta: möykky ------------------------------------- */
    /*
     * Koekenttä käsin: möykky, sen alla tiili, tiilen alla ilmaa ja maa.
     * Tiili rikotaan (`smashBrick` = se mitä pelaajan päänpuski tekee), ja
     * möykyn pitää tulla alas, tappaa se mikä on alla, ja **palata paikalleen**.
     */
    const fixture = (id, supportChar) => {
      const s = scene(id);
      const p = s.player;
      /* Sarake kaukana pelaajasta, jonka lattia on ehjä ja jonka yllä on tilaa. */
      let tx = -1;
      for (let x = Math.floor(p.x / 16) + 10; x < s.w - 4; x++) {
        if (s.grid[14][x] === T.GROUND && s.grid[13][x] === ' '
          && s.grid[12][x] === ' ' && s.grid[11][x] === ' ' && s.grid[10][x] === ' ') { tx = x; break; }
      }
      if (tx < 0) return null;
      s.setTile(tx, 10, T.LUMP);
      s.setTile(tx, 11, supportChar);
      return { s, tx };
    };
    {
      const f = fixture('1-1', T.BRICK);
      if (!f) out.lump = { built: false };
      else {
        const { s, tx } = f;
        const i = mkInput();
        const victim = put(s, new Walker(s, tx * 16, 13 * 16));
        victim.speed = 0;
        victim.vx = 0;
        s.smashBrick(tx, 11);
        let leftOrigin = 0;
        let landedAt = 0;
        for (let n = 0; n < 90; n++) {
          s.update(i);
          if (!leftOrigin && s.tileAt(tx, 10) !== T.LUMP) leftOrigin = n + 1;
          if (!landedAt && s.tileAt(tx, 12) === T.LUMP) landedAt = n + 1;
        }
        const killed = !!(victim.dying || victim.remove);
        let back = false;
        for (let n = 0; n < 400 && !back; n++) {
          s.update(i);
          back = s.tileAt(tx, 10) === T.LUMP && s.tileAt(tx, 12) !== T.LUMP;
        }
        out.lump = { built: true, tx, leftOrigin, landedAt, killed, back };
      }
    }

    /* --- 6. reiluus: ketju jonka pelaaja aloitti omistaa seurauksensa --- */
    {
      const f = fixture('1-1', T.BRICK);
      if (!f) out.fair = { built: false };
      else {
        const { s, tx } = f;
        const i = mkInput();
        const p = s.player;
        p.x = tx * 16;
        p.y = 14 * 16 - p.h;
        p.vy = 0;
        const before = p.powerLevel;
        s.smashBrick(tx, 11);
        for (let n = 0; n < 90; n++) s.update(i);
        out.fair = { built: true, before, after: p.powerLevel, alive: !p.dying };
      }
    }

    /* --- 7. pikatallennus keskellä putoamista --------------------------- */
    {
      const f = fixture('1-1', T.BRICK);
      if (!f) out.save = { built: false };
      else {
        const { s, tx } = f;
        const i = mkInput();
        s.smashBrick(tx, 11);
        for (let n = 0; n < 12; n++) s.update(i);
        game.pendingNode = WORLDS[0].nodes.find((n) => n.level === '1-1') || game.pendingNode;
        const mid = s.falls ? s.falls.size : 0;
        const snap = JSON.parse(JSON.stringify(captureState(game)));
        const rows1 = [];
        for (let n = 0; n < 60; n++) s.update(i);
        for (let y = 9; y <= 13; y++) rows1.push(s.tileAt(tx, y));
        restoreState(game, snap);
        const s2 = game.scene;
        const after = s2.falls ? s2.falls.size : 0;
        for (let n = 0; n < 60; n++) s2.update(i);
        const rows2 = [];
        for (let y = 9; y <= 13; y++) rows2.push(s2.tileAt(tx, y));
        out.save = {
          built: true, mid, after,
          same: rows1.join('') === rows2.join(''),
          before: rows1.join(''), then: rows2.join(''),
        };
      }
    }
    return out;
  });

  /* --- laki 1 --- */
  {
    const { grass, ice, frames } = E.ice;
    const ideal = grass.speed * frames;
    expect('jää on liukas kaikille: seinästä kimmonnut kävelijä ei saa vauhtiaan takaisin jäällä',
      grass.turn >= 0 && ice.turn >= 0
      && grass.moved >= ideal - 0.5 && ice.moved < grass.moved * 0.8,
      `${frames} framea käännöksen jälkeen: ruoho ${grass.moved} px `
      + `(täysi vauhti ${ideal.toFixed(1)}), jää ${ice.moved} px `
      + `— ${(100 * ice.moved / grass.moved).toFixed(0)} % ruohosta`);
  }

  /* --- laki 2 --- */
  expect('mureneva lauta pettää vihollisen alta ja kasvaa takaisin',
    E.plank.found && E.plank.started > 0 && E.plank.gone && E.plank.back,
    E.plank.found
      ? `lauta ${E.plank.at}: ajastin framella ${E.plank.started}, poissa ${E.plank.gone}, `
        + `palasi ${E.plank.back}`
      : '4-1:stä ei löytynyt murenevaa lautaa');

  /* --- laki 3 --- */
  expect('tuuli kantaa myös vihollista, ei vain pelaajaa',
    E.wind.gust < E.wind.calm - 4,
    `${E.wind.frames} framea 2-N:ssä: puuskassa ${E.wind.gust} px, tyynellä ${E.wind.calm} px `
    + `— ero ${(E.wind.calm - E.wind.gust).toFixed(1)} px`);

  /* --- laki 4 --- */
  expect('potkaistu kuori tappaa sen mihin osuu, myös papupommin',
    E.shell.walker && E.shell.bomb,
    `kävelijä ${E.shell.walker ? 'kuoli' : 'jäi henkiin'}, `
    + `papupommi ${E.shell.bomb ? 'räjähti' : 'jäi koskematta'}`);

  /* --- putoava laatta --- */
  expect('möykky putoaa kun sen tuki poistetaan, tappaa alta ja palaa paikalleen',
    E.lump.built && E.lump.leftOrigin > 0 && E.lump.landedAt > 0 && E.lump.killed && E.lump.back,
    E.lump.built
      ? `sarake ${E.lump.tx}: lähti framella ${E.lump.leftOrigin}, pysähtyi ${E.lump.landedAt}, `
        + `tappoi ${E.lump.killed}, palasi ${E.lump.back}`
      : 'koekenttää ei saatu rakennettua');

  /* --- reiluus --- */
  expect('pelaajan aloittama ketju satuttaa pelaajaa',
    E.fair.built && E.fair.after < E.fair.before,
    E.fair.built ? `voimataso ${E.fair.before} -> ${E.fair.after}` : 'koekenttää ei saatu rakennettua');

  /* --- determinismi --- */
  expect('pikatallennus palauttaa putoavan möykyn samaan kohtaan',
    E.save.built && E.save.mid > 0 && E.save.after === E.save.mid && E.save.same,
    E.save.built
      ? `putoavia ${E.save.mid} -> ${E.save.after}, sarake ${E.save.before} vs ${E.save.then}`
      : 'koekenttää ei saatu rakennettua');

  /* --- portti: möykky ei saa nojata murenevaan lautaan --- */
  /*
   * Tämä on reiluussäännön se puolisko joka ei ole havainto vaan portti.
   * Vihollinen voi poistaa tasan yhden ruudun: murenevan laudan (laki 2). Jos
   * möykky saisi nojata sellaiseen, vihollinen voisi pudottaa sen pelaajan
   * päähän — ketju jota pelaaja ei aloittanut. Muut tuen poistajat (päänpuski,
   * potkaistu kuori, kytkin) ovat kaikki pelaajan tekoja, joten kielto tekee
   * säännöstä rakenteellisen eikä muistettavan: **ruudun ulkopuolista
   * kirjanpitoa ei tarvita.**
   */
  {
    const { validateLevel } = await import('../src/data/rules.js');
    const budget = JSON.parse(await readFile(join(ROOT, 'tools/jump-budget.json'), 'utf8'));
    /* Möykky on kaksi riviä lattian yläpuolella eikä yksi, ja se on
     * mittaustulos: `checkHeadroom` vaatii kolme vapaata riviä sen ruudukon
     * yllä jonka päällä kuljetaan, joten tiili rivillä 11 olisi jo *toinen*
     * huomautus samasta koekentästä. Yksi vika kerrallaan, kuten
     * hiekkakoekentässä. */
    const fixture = (over = {}) => {
      const rows = Array.from({ length: 16 }, () => ' '.repeat(32));
      const set = (y, s) => { rows[y] = s.padEnd(32, ' ').slice(0, 32); };
      set(9, '              C ');
      set(10, '      !       B ');
      set(13, '  1                         F   ');
      set(14, '################################');
      set(15, '################################');
      for (const [y, s] of Object.entries(over)) set(Number(y), s);
      return rows;
    };
    const lumpProblems = (list) => list.filter((p) => /falling tile/i.test(p));

    const clean = validateLevel(fixture(), budget);
    expect('kelvollinen möykky ei ole validaattorille ongelma',
      clean.length === 0,
      clean.length ? clean.join('; ') : 'möykky tiilen päällä, ilmaa yllä — ei huomautuksia');

    const hanging = validateLevel(fixture({ 10: '      !         ' }), budget);
    expect('ilmassa roikkuva möykky raportoidaan',
      lumpProblems(hanging).length > 0,
      lumpProblems(hanging)[0] || `ei huomautusta (${hanging.join('; ') || 'ei mitään'})`);

    const onPlank = validateLevel(fixture({ 10: '      !       % ' }), budget);
    expect('möykky murenevan laudan päällä raportoidaan',
      lumpProblems(onPlank).length > 0,
      lumpProblems(onPlank)[0] || `ei huomautusta (${onPlank.join('; ') || 'ei mitään'})`);

    const walkedOn = validateLevel(fixture({ 8: '              o ' }), budget);
    expect('möykyn päälle ei rakenneta reittiä',
      lumpProblems(walkedOn).length > 0,
      lumpProblems(walkedOn)[0] || `ei huomautusta (${walkedOn.join('; ') || 'ei mitään'})`);
  }

  /* --- vaikeusmittari sanoo rajansa ääneen --- */
  /*
   * ROADMAP 10.8.2026 kohta 3: luku pysyy vertailukelpoisena kaikkien kenttien
   * ja kaiken ajan yli, ja siksi se mittaa yhä **lähtötilan**. Sanottu rajoitus
   * on parempi kuin luku joka hiljaa tarkoittaa uutta asiaa — ja sanottu
   * rajoitus jota mikään ei tarkista on muistiinpano, joten se luetaan ajosta.
   */
  {
    const { execFile } = await import('node:child_process');
    const { promisify } = await import('node:util');
    const run = promisify(execFile);
    let stdout = '';
    try {
      ({ stdout } = await run(process.execPath, [join(ROOT, 'tools/difficulty.mjs')],
        { cwd: ROOT, maxBuffer: 8 * 1024 * 1024 }));
    } catch (err) {
      stdout = `AJO KAATUI: ${err && err.message}`;
    }
    const line = stdout.split('\n').find((l) => /emergen/i.test(l)) || '';
    expect('vaikeusmittari sanoo ääneen että se mittaa lähtötilan',
      line.trim().length > 0,
      line.trim() || 'ei riviä joka mainitsisi emergenssin');
  }

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- emergenssi: loppu ---- */
/* ---- sää: kolme uutta ---- */
/*
 * KOLME UUTTA SÄÄTÄ, ja ne mitataan samalla ankaruudella kuin neljä lakia
 * yllä — samasta syystä. Sää on **maasto → olio**: se on huoneen ominaisuus
 * joka koskee kaikkea huoneessa olevaa, eikä yksikään näistä kolmesta muokkaa
 * kenttää. Se on myös se raja jonka rikkoutuminen olisi hiljainen: myrsky joka
 * unohtaisi vihollisen tai järistys joka heittäisi ilmassa olevaa näyttäisivät
 * aivan oikeilta ruudulla.
 *
 * Neljä väitettä, ja jokainen kantaa lukunsa:
 *
 *   1  järistys   nytkäyttää maassa olevaa, ei ilmassa olevaa — ja se koskee
 *                 vihollista siinä missä pelaajaa, paitsi kalusteita
 *   2  suppilo    vetää keskustaansa ja nostaa ytimessä, ja kantaa kuorta
 *   3  myrsky     varoittaa ennen kuin sataa, ja **katto sammuttaa kekäleen**
 *   4  kello      sama kello on sama sää: pikalataus ei arvo säätä uusiksi
 *
 * Väite 3 on se joka on ollut punaisena: ensimmäinen kekälesade oli
 * kohtauksen piirtämä eikä olio, ja se satoi katon läpi. Portti *"jokainen
 * kenttä on läpäistävissä voimatasolla 0"* kaatui 4-3:een sarakkeeseen 107,
 * koska se riisuu kentästä vaarat eikä maastoa — ja sade oli kirjoitettu
 * maastoksi. Nyt kekäle on `Entity`, `kind: 'hazard'`, ja katto sammuttaa sen.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const W = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { Walker, Ember, Boss } = await import('/src/entities/enemies.js');
    const { T } = await import('/src/gfx/tiles.js');
    const { levelIds, getLevel } = await import('/src/data/levels.js');
    const game = window.sfb3;
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const scene = (id) => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    const r2 = (v) => Math.round(v * 100) / 100;
    const out = {};

    /* Missä sää on käytössä. Yksi kenttä kutakin on suunnittelupäätös
     * (ROADMAP: uhka joka on joka kentässä on maastoa), ja "yksi" on siksi
     * mitattava luku eikä muistiinpano. */
    const flagged = (flag) => levelIds().filter((id) => getLevel(id)[flag]);
    out.where = {
      quake: flagged('quake'), twister: flagged('twister'), firestorm: flagged('firestorm'),
    };

    /* --- 1. järistys nytkäyttää sitä mikä on maassa ---------------------- */
    {
      const s = scene(out.where.quake[0] || '6-1');
      const i = mkInput();
      const p = s.player;
      /* Kävelijä pelaajan viereen tasaiselle maalle, ja pomo verrokiksi:
       * `quakeborne` on oletuksena kyllä ja kalusteilla ei. */
      const w = new Walker(s, p.x + 40, p.y);
      w.active = true;
      w.alwaysActive = true;
      w.speed = 0;
      w.vx = 0;
      s.entities.push(w);
      /* Aja järistyksen huipulle asti ja katso mitä sillä framella tapahtui. */
      const peak = 75;
      let kickP = 0;
      let kickW = 0;
      let air = 0;
      s.tick = 0;
      for (let f = 0; f < peak + 4; f++) {
        const wasP = p.vy;
        const wasW = w.vy;
        s.update(i);
        if (p.vy - wasP < kickP) kickP = p.vy - wasP;
        if (w.vy - wasW < kickW) kickW = w.vy - wasW;
      }
      /* Sama järistys ilmassa: hyppy juuri ennen huippua, eikä nytkäystä tule. */
      const s2 = scene(out.where.quake[0] || '6-1');
      const i2 = mkInput();
      s2.tick = 0;
      for (let f = 0; f < peak + 4; f++) {
        i2.held = blank();
        i2.pressed = blank();
        s2.player.onGround = false;
        s2.player.y -= 40;
        const was = s2.player.vy;
        s2.update(i2);
        if (f === peak && s2.player.vy - was < -1) air = s2.player.vy - was;
      }
      out.quake = {
        player: r2(kickP), walker: r2(kickW), air: r2(air), shake: r2(s.shakeAmp),
        furniture: !(Boss.prototype.quakeborne),
      };
    }

    /* --- 2. suppilo vetää ja nostaa -------------------------------------- */
    {
      const s = scene(out.where.twister[0] || '7-3');
      const i = mkInput();
      const p = s.player;
      const eye = s.twisterAt(p.cx);
      /* Kehälle: puolimatkaan ulottuvuudesta, jotta veto on olemassa muttei
       * ydintä. Mitataan `vx`:n muutos yhdellä framella. */
      p.x = eye + 60;
      p.vx = 0;
      p.vy = 0;
      s.update(i);
      const rim = r2(p.vx);
      /* Ytimeen: nosto näkyy `vy`:n muutoksena painovoimaa vastaan. */
      const s2 = scene(out.where.twister[0] || '7-3');
      const p2 = s2.player;
      p2.x = s2.twisterAt(p2.cx);
      p2.vy = 0;
      const beforeVy = p2.vy;
      s2.update(mkInput());
      const core = r2(p2.vy - beforeVy);
      /* Ja laki 3: se kantaa kuorta siinä missä pelaajaa. */
      const s3 = scene(out.where.twister[0] || '7-3');
      const w = new Walker(s3, s3.twisterAt(s3.player.cx) + 60, s3.player.y);
      w.active = true;
      w.alwaysActive = true;
      s3.entities.push(w);
      const drift0 = w.drift;
      s3.update(mkInput());
      out.twister = {
        rim, core, carries: r2(w.drift - drift0), windborne: w.windborne,
        /* Ulompana kuin ulottuvuus: ei mitään. */
        far: (() => {
          const s4 = scene(out.where.twister[0] || '7-3');
          const q = s4.player;
          q.x = s4.twisterAt(q.cx) + 200;
          q.vx = 0;
          s4.update(mkInput());
          return r2(q.vx);
        })(),
      };
    }

    /* --- 3. myrsky varoittaa, ja katto sammuttaa ------------------------- */
    {
      const s = scene(out.where.firestorm[0] || '4-3');
      /* Vaiheet kellosta: rauha → varoitus → sade, tässä järjestyksessä. */
      const seen = [];
      for (let t = 0; t < 720; t++) {
        s.tick = t;
        const ph = s.emberPhase();
        seen.push(ph.rain >= 0 ? 'sade' : (ph.warn > 0 ? 'varoitus' : 'rauha'));
      }
      const order = seen.filter((v, k) => v !== seen[k - 1]);
      out.storm = {
        order,
        warn: seen.filter((v) => v === 'varoitus').length,
        rain: seen.filter((v) => v === 'sade').length,
      };

      /* Katto sammuttaa, punainen vieressä: sama kekäle kahdessa sarakkeessa,
       * toisessa kiveä yllä ja toisessa avoin taivas. */
      const drop = (roofed) => {
        const t = scene(out.where.firestorm[0] || '4-3');
        const i = mkInput();
        const tx = 6;
        /* Lattia alle ja katto tai ei kattoa yllä, jotta mitattava asia on
         * katto eikä se mihin kohtaan kenttää osuttiin. */
        for (let dx = -6; dx <= 2; dx++) {
          for (let ty = 0; ty < 13; ty++) t.setTile(tx + dx, ty, T.EMPTY);
          t.setTile(tx + dx, 13, T.GROUND);
          /* Katto on kaistale eikä yksi laatta, koska kekäle **ajautuu**
           * sivuun pudotessaan: yhden laatan katto olisi mitannut sitä
           * osuuko se, eikä sitä sammuttaako katto. */
          if (roofed) t.setTile(tx + dx, 6, T.GROUND);
        }
        const e = new Ember(t, tx * 16 + 4, 16);
        e.alwaysActive = true;
        t.entities.push(e);
        let ended = -1;
        for (let f = 0; f < 240 && ended < 0; f++) {
          t.update(i);
          if (e.remove) ended = Math.round(e.y / 16);
        }
        return ended;
      };
      out.storm.roofed = drop(true);
      out.storm.open = drop(false);
    }

    /* --- 4. sama kello on sama sää --------------------------------------- */
    {
      const read = (id, flag, at) => {
        const s = scene(id);
        const i = mkInput();
        for (let f = 0; f < at; f++) s.update(i);
        return flag === 'quake' ? r2(s.quake) : r2(s.twisterAt(0));
      };
      const qa = read(out.where.quake[0] || '6-1', 'quake', 40);
      const qb = read(out.where.quake[0] || '6-1', 'quake', 40);
      const ta = read(out.where.twister[0] || '7-3', 'twister', 40);
      const tb = read(out.where.twister[0] || '7-3', 'twister', 40);
      out.clock = { qa, qb, ta, tb };
    }
    return out;
  });

  const one = (list) => list.length === 1;
  expect('jokaisella uudella säällä on tasan yksi kenttä',
    one(W.where.quake) && one(W.where.twister) && one(W.where.firestorm),
    `järistys ${W.where.quake.join(',') || '-'}, suppilo ${W.where.twister.join(',') || '-'},`
    + ` myrsky ${W.where.firestorm.join(',') || '-'}`);

  expect('järistys nytkäyttää maassa olevaa — pelaajaa ja vihollista — muttei ilmassa olevaa',
    W.quake.player < -2 && W.quake.walker < -2 && W.quake.air === 0
    && W.quake.shake > 0 && W.quake.furniture,
    `pelaaja ${W.quake.player}, kävelijä ${W.quake.walker}, ilmassa ${W.quake.air},`
    + ` tärinä ${W.quake.shake}, kaluste järistyksen ulkopuolella: ${W.quake.furniture}`);

  expect('suppilo vetää kehältä keskustaan, nostaa ytimessä eikä ulotu kauas',
    W.twister.rim < 0 && W.twister.core < 0 && W.twister.far === 0
    && W.twister.carries < 0 && W.twister.windborne,
    `kehä ${W.twister.rim} px/frame, ydin ${W.twister.core} px/frame,`
    + ` kaukana ${W.twister.far}, kuoren kanto ${W.twister.carries}`);

  /* ------------------------- ajelehtiva pelaaja ------------------------- */
  /*
   * SÄÄ RANKAISEE PAIKALLAAN OLOSTA (19.8.2026).
   *
   * Neljä väitettä, ja kolmas on se jonka takia tämä lohko on olemassa.
   *
   *   1. Paikallaan olo kerää mittaria, liike nollaa sen. Kumpi tahansa
   *      akseli, koska mitta on etäisyys ankkurista eikä suunta.
   *   2. Areenassa ei ajelehdita: siellä ei ole rataa jota edetä.
   *   3. **Liikkuvalle pelaajalle kerroin on tasan 1.** Tämä on se lupaus
   *      jonka rikkominen kaatoi 4-3:n kehitysvaiheessa: kekälesade on kuvio
   *      eikä määrä, ja jokainen mitattu luku on todistettu sitä kuviota
   *      vastaan jonka kerroin 1 tuottaa. Jos tämä luku liikahtaa, jokainen
   *      läpäistävyystodistus koskee eri kenttää kuin se joka julkaistaan.
   *   4. Vastatuuli lakkaa siitä framesta jolla pelaaja painaa suuntaa —
   *      muuten se vaikeuttaisi juuri sitä hyppyä johon on jääty kiinni.
   */
  {
    const D = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const game = window.sfb3;
      const fresh = (id) => {
        game.state = { lives: 3, coins: 60, score: 0, power: { type: null, level: 0 },
          reserve: null, world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
          secrets: {}, checks: {}, doors: {}, usedSaveState: false, continues: 0, bestTimes: {} };
        const sc = new LevelScene(game, id);
        game.setScene(sc);
        sc.time = 9999;
        sc.clockStopped = true;
        return sc;
      };
      const idle = () => ({ held: {}, pressed: {}, consume() {} });
      const right = () => ({ held: { right: true }, pressed: {}, consume() {} });

      const s = fresh('1-1');
      const moving = s.weatherScale;
      for (let f = 0; f < 400; f++) s.update(idle());
      const stood = { drift: s.drift, scale: s.weatherScale };
      /* Sama seisominen, mutta suunta pohjassa: mittari kerää yhä, tuuli ei
       * puhalla. `vx` luetaan ennen ja jälkeen yhden framen, pelaaja ilmassa
       * jotta puolitus ei sotke lukemaa. */
      s.player.onGround = false;
      s.player.vx = 0;
      s.updateDriftWind(right());
      const tryingPush = s.player.vx;
      s.player.vx = 0;
      s.updateDriftWind(idle());
      const idlePush = s.player.vx;

      const m = fresh('1-1');
      for (let f = 0; f < 400; f++) m.update(right());
      const ran = { drift: m.drift, scale: m.weatherScale, moved: m.player.cx > m.spawn.x + 32 };

      const arena = fresh('1-F');
      for (let f = 0; f < 400; f++) arena.update(idle());
      const boss = { drift: arena.drift, isBoss: !!arena.def.boss };
      return { moving, stood, ran, boss, tryingPush, idlePush };
    });

    expect('paikallaan seisominen kerää ajelehtimista, juokseminen ei',
      D.stood.drift === 1 && D.ran.drift === 0 && D.ran.moved,
      `seisten ${D.stood.drift}, juosten ${D.ran.drift} (eteni ${D.ran.moved})`);

    expect('liikkuvan pelaajan sää on tasan mitattu sää, kerroin 1',
      D.moving === 1 && D.ran.scale === 1 && D.stood.scale > 1,
      `alussa ${D.moving}, juosten ${D.ran.scale}, seisten ${D.stood.scale}`);

    expect('pomoareenassa ei ajelehdita, koska siellä ei ole rataa',
      D.boss.isBoss && D.boss.drift === 0, `areena ${D.boss.isBoss}, ajelehdus ${D.boss.drift}`);

    expect('vastatuuli väistyy heti kun pelaaja painaa suuntaa',
      D.tryingPush === 0 && D.idlePush < 0,
      `suunta pohjassa ${D.tryingPush}, joutilaana ${D.idlePush}`);
  }

  expect('tulimyrsky varoittaa ennen kuin se sataa, ja varoitus on lyhyempi kuin sade',
    W.storm.order.join('→') === 'rauha→varoitus→sade'
    && W.storm.warn > 0 && W.storm.rain > W.storm.warn,
    `${W.storm.order.join('→')}, varoitus ${W.storm.warn} framea, sade ${W.storm.rain}`);

  expect('katto sammuttaa kekäleen, avoin taivas ei',
    W.storm.roofed > 0 && W.storm.open > 0 && W.storm.roofed < W.storm.open,
    `katon alla sammui rivillä ${W.storm.roofed}, avoimessa rivillä ${W.storm.open}`);

  expect('sama kello on sama sää: sitä ei arvota kahdesti',
    W.clock.qa === W.clock.qb && W.clock.ta === W.clock.tb,
    `järistys ${W.clock.qa}/${W.clock.qb}, suppilo ${W.clock.ta}/${W.clock.tb}`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- sää: loppu ---- */
/* ---- vauhtimittari ---- */
/*
 * MITTARI TÄYTTYY NAPPI POHJASSA, JA P-NOPEUS ON KATTO.
 *
 * Tässä mitattiin 18.-19.8.2026 rytmipumppausta: nappia tahdissa napsauttamalla
 * mittari täyttyi 100 framen sijaan 78:ssa. Mekaniikka on poistettu 19.8.2026
 * ja poiston perustelu on mittaus, ei maku — ks. CHANGELOG. Lyhyesti:
 * täydellinen suoritus tuotti kahdeksassa sekunnissa 1533 px vastaan 1511 px,
 * eli **1,5 % lisää matkaa**, ja kaksi framea myöhässä puolitti vauhdin.
 * Mittarin ainoa tehtävä on viedä P-nopeuteen, P-nopeus on katto, joten
 * täyttymisnopeudella voi ostaa vain sen 1,6 sekuntia joka kuluu katon alla.
 *
 * Kaksi väitettä jäi, ja ne ovat ne kaksi joiden varassa muu lepää:
 *
 *   1  pohjassa pitäminen täyttää mittarin
 *   2  katto on `MAX_P`, eikä mikään vie sen yli
 *
 * Väite 1 on se lupaus johon DESIGN.md kohta 5 nojaa: `playable.mjs`:n
 * voimatason 0 botti pitää nappia pohjassa, joten jos kenttä joskus vaatisi
 * muuta, se portti kaatuisi.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const P = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { P_METER_MAX, MAX_P, MAX_RUN } = await import('/src/entities/player.js');
    const game = window.sfb3;
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const scene = () => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    /*
     * `style` is how the run button is played. `offset` is where in the beat
     * the press lands, so 0 is on it and 6 is as wrong as it gets.
     */
    const play = (style, offset = 0, cap = 900) => {
      const s = scene();
      const p = s.player;
      const i = {
        held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
      };
      let frames = cap;
      let vents = 0;
      let topSpeed = 0;
      for (let f = 0; f < cap; f++) {
        i.held = blank();
        i.pressed = blank();
        i.held.right = true;
        i.held.run = true;
        const before = p.pMeter;
        s.update(i);
        topSpeed = Math.max(topSpeed, Math.abs(p.vx));
        if (p.pMeter < before - 5) vents++;
        if (p.pMeter >= P_METER_MAX) { frames = f + 1; break; }
      }
      return { frames, vents, meter: Math.round(p.pMeter), top: Math.round(topSpeed * 100) / 100 };
    };
    const out = { max: { P: MAX_P, run: MAX_RUN } };
    out.hold = play('hold');

    /* And the ceiling, measured after the gauge is full: run on for a while
     * and see how fast the body actually goes. */
    const s = scene();
    const p = s.player;
    const i = {
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    };
    let fastest = 0;
    for (let f = 0; f < 400; f++) {
      i.held = blank();
      i.pressed = blank();
      i.held.right = true;
      i.held.run = true;
      s.update(i);
      fastest = Math.max(fastest, Math.abs(p.vx));
    }
    out.ceiling = Math.round(fastest * 1000) / 1000;
    return out;
  });

  /* ------------------------- vauhdin merkit ----------------------------- */
  /*
   * MITÄ TÄYSI VAUHTI TEKEE RUUDULLE (19.8.2026).
   *
   * Omistaja: *"when we reach full speed, the entire screen should warble.
   * Maybe the screen shifts a bit so you see more of what's ahead, to
   * compensate for the speed."*
   *
   * Kolme väitettä, ja kolmas on se jota ei saa rikkoa vahingossa: huojunta on
   * **aalto eikä väri**. Kokoruudun väri on tässä pelissä osuman kieli
   * (17.8.2026, ks. *"merkin on jätettävä ruudun toinen laita rauhaan"*), ja
   * juuri siksi vauhti puhuu geometrialla — sitä ei voi sekoittaa osumaan.
   */
  {
    const V = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const { MAX_RUN, MAX_P } = await import('/src/entities/player.js');
      const game = window.sfb3;
      const mk = () => {
        game.state = { lives: 3, coins: 60, score: 0, power: { type: null, level: 0 },
          reserve: null, world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
          secrets: {}, checks: {}, doors: {}, usedSaveState: false, continues: 0, bestTimes: {} };
        const sc = new LevelScene(game, '1-1');
        game.setScene(sc);
        sc.time = 9999;
        sc.clockStopped = true;
        return sc;
      };
      /* Katse edelle kahdella nopeudella, sama kenttä, kamera ajettuna
       * tasapainoon kummallakin. */
      const leanAt = (vx) => {
        const sc = mk();
        for (let f = 0; f < 200; f++) {
          sc.player.vx = vx;
          sc.player.x += vx;
          sc.updateCamera();
        }
        return Math.abs(Math.round(sc.camLook));
      };
      const runLean = leanAt(MAX_RUN);
      const pLean = leanAt(MAX_P);

      /* Huojunta: sama frame, mittari täynnä ja tyhjä. */
      const sc = mk();
      sc.player.pMeter = 0;
      const calm = sc.warbleOffset();
      const { P_METER_MAX } = await import('/src/entities/player.js');
      sc.player.pMeter = P_METER_MAX;
      let amp = 0;
      let moved = 0;
      for (let t = 0; t < 240; t++) {
        sc.tick = t;
        const w = sc.warbleOffset();
        amp = Math.max(amp, Math.abs(w.x), Math.abs(w.y));
        if (w.x !== 0 || w.y !== 0) moved++;
      }
      return { runLean, pLean, calm, amp, moved, full: sc.player.pFull };
    });

    expect('katse edelle kasvaa P-nopeuteen asti eikä pysähdy juoksukattoon',
      V.pLean > V.runLean * 1.2 && V.runLean > 0,
      `juoksuvauhdilla ${V.runLean} px, P-vauhdilla ${V.pLean} px`);

    expect('täysi mittari huojuttaa ruutua, tyhjä ei, ja huojunta on yhden pikselin',
      V.calm.x === 0 && V.calm.y === 0 && V.full && V.amp === 1 && V.moved > 60,
      `tyhjänä ${V.calm.x},${V.calm.y}; täynnä amplitudi ${V.amp} px,`
      + ` liikkeessä ${V.moved}/240 framea`);
  }

  /* --------------------- ketjuhyppy ja kuilun partaalta ------------------- */
  /*
   * TWO THINGS THE OWNER ASKED FOR, 20.8.2026, and four assertions between
   * them — two of which are the ones that stop either becoming pumping again.
   *
   *   "consecutive well-timed jumps should up the speed a bit, and maybe you
   *    should get a coin for a near-death stunt (be falling into a chasm and
   *    then use the second or third jump to get out of there?)"
   */
  {
    const K = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const { P_METER_MAX, MAX_P } = await import('/src/entities/player.js');
      const { TILE } = await import('/src/data/worlds.js');
      const game = window.sfb3;
      const fresh = (powerLevel = 0) => {
        game.state = { lives: 3, coins: 20, score: 0,
          power: { type: powerLevel ? 'shroom' : null, level: powerLevel },
          reserve: null, world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
          secrets: {}, checks: {}, doors: {}, usedSaveState: false, continues: 0,
          bestTimes: {} };
        return new LevelScene(game, '1-1');
      };
      const key = (held, pressed = {}) => ({ held, pressed, released: {}, consume() {} });

      /* 1 & 2. The refund, measured in isolation: a full meter on the ground
       *        below running speed drains; leaving inside the window hands
       *        back exactly what it cost, and riding it out hands back
       *        nothing at all. */
      const landing = (wait) => {
        const sc = fresh();
        const p = sc.player;
        for (let f = 0; f < 30; f++) sc.update(key({}));
        p.pMeter = P_METER_MAX;
        p.sinceLanding = 0;
        p.chain = 0;
        p.landingDrain = 0;
        const start = p.pMeter;
        for (let f = 0; f < wait; f++) sc.update(key({}));
        const before = p.pMeter;
        sc.update(key({ jump: true }, { jump: true }));
        return { drained: +(start - before).toFixed(2), refund: +(p.pMeter - before).toFixed(2) };
      };
      const quick = landing(4);
      const slow = landing(20);

      /* 3. The cap does not move. `MAX_P` is what the jump budget was measured
       *    at, and the slope catapult has the same assertion for the same
       *    reason. */
      const sc = fresh();
      const p = sc.player;
      p.pMeter = P_METER_MAX;
      let top = 0;
      for (let f = 0; f < 600; f++) {
        const held = { right: true, run: true };
        const pressed = p.onGround ? { jump: true } : {};
        if (p.onGround) held.jump = true;
        sc.update(key(held, pressed));
        top = Math.max(top, Math.abs(p.vx));
      }

      /* 4. The brink. Counted at `addCoin` rather than off `state.coins`,
       *    which also drains as fuel — a delta over a wait measures the clock
       *    as much as the reward. */
      const scan = fresh(2);
      let pit = -1;
      for (let tx = 4; tx < scan.w - 4; tx++) if (scan.pitUnder(tx, 0)) { pit = tx; break; }
      const drop = (save, deep = true) => {
        const s2 = fresh(2);
        const q = s2.player;
        for (let f = 0; f < 20; f++) s2.update(key({}));
        let awarded = 0;
        const real = s2.addCoin.bind(s2);
        s2.addCoin = (...a) => { awarded++; return real(...a); };
        q.x = pit * TILE + 2; q.y = 40; q.vy = 1; q.vx = 0; q.onGround = false;
        s2.brinkGroundY = deep ? 40 : 40 - TILE;
        let used = false;
        for (let f = 0; f < 240 && s2.state === 'play'; f++) {
          const pressed = {};
          if (save && s2.brink && !used && q.y > 40 + TILE * 3) { pressed.jump = true; used = true; }
          s2.update(key(used ? { left: true } : {}, pressed));
          if (q.onGround) break;
        }
        for (let f = 0; f < 60 && s2.state === 'play'; f++) s2.update(key({}));
        return { awarded, alive: s2.state === 'play' };
      };
      const rescued = drop(true);
      const doomed = drop(false);
      const hopped = (() => {
        const s2 = fresh(2);
        const q = s2.player;
        for (let f = 0; f < 20; f++) s2.update(key({}));
        let awarded = 0;
        const real = s2.addCoin.bind(s2);
        s2.addCoin = (...a) => { awarded++; return real(...a); };
        q.x = pit * TILE + 2; q.y = 40; q.vy = 1; q.onGround = false;
        s2.brinkGroundY = 40 - TILE;
        for (let f = 0; f < 12; f++) s2.update(key({}, f === 2 ? { jump: true } : {}));
        q.y = 40; q.onGround = true;
        for (let f = 0; f < 60 && s2.state === 'play'; f++) s2.update(key({}));
        return awarded;
      })();
      return { quick, slow, top: +top.toFixed(4), MAX_P, pit, rescued, doomed, hopped };
    });

    expect('ajoissa jatkettu hyppy maksaa laskeutumisen takaisin',
      K.quick.drained > 0 && Math.abs(K.quick.refund - K.quick.drained) < 0.01,
      `valui ${K.quick.drained}, palautui ${K.quick.refund}`);

    expect('ikkunan jälkeen ei palauteta mitään — ohittaminen maksaa saman kuin ennen',
      K.slow.drained > K.quick.drained && K.slow.refund <= 0,
      `valui ${K.slow.drained}, palautui ${K.slow.refund}`);

    /*
     * The one that keeps this from being pumping again. `MAX_P` is the number
     * `gapTiles` 6 and `wallTiles` 4 were measured at, and every level's
     * clearability is proved against it — so a speed skill may hold the cap
     * and may never raise it. Six hundred frames of perfect chaining.
     */
    expect('ketju ei nosta kattoa — MAX_P on hyppybudjetin mitta',
      Math.abs(K.top - K.MAX_P) < 0.001,
      `huippunopeus ${K.top}, MAX_P ${K.MAX_P}`);

    expect('kuilusta pelastautuminen maksaa kolikon, putoaminen ja hyppely eivät',
      K.pit > 0 && K.rescued.awarded === 1 && K.rescued.alive
      && K.doomed.awarded === 0 && !K.doomed.alive && K.hopped === 0,
      `kuilu sarakkeessa ${K.pit}: pelastui ${K.rescued.awarded} kolikkoa (elossa`
      + ` ${K.rescued.alive}), putosi ${K.doomed.awarded} (elossa ${K.doomed.alive}),`
      + ` matala loikka ${K.hopped}`);
  }

  /* ------------------------------ maailmannoppa -------------------------- */
  /*
   * NOPPA AUKEAA JA SULKEUTUU (19.8.2026).
   *
   * Ovivalinta oli valikko, ja valikko ei ole maailmankartta. Tämä on se
   * kappale: oktaedri jonka tahkot ovat maailmat, hidas pyörintä, taitos auki
   * litteäksi nauhaksi ja takaisin kiinni valitun tahkon ympärille.
   *
   * Neljä väitettä, ja ne koskevat **mekaniikkaa eikä kauneutta** — kuvaa ei
   * voi mitata, mutta sen voi mitata ettei ruutu jää jumiin, että jokainen
   * tahko päätyy nauhaan ruudun sisälle, ja että valinta vie naapuriin.
   */
  {
    const N = await page.evaluate(async () => {
      const { DieScene } = await import('/src/scenes/die.js');
      const game = window.sfb3;
      game.state = { lives: 3, coins: 60, score: 0, power: { type: null, level: 0 },
        reserve: null, world: 0, node: null, cleared: {}, worldsOpen: 1, cards: [],
        secrets: {}, checks: {}, doors: {}, visited: {}, usedSaveState: false,
        continues: 0, bestTimes: {} };
      let picked = -1;
      const sc = new DieScene(game, 0, (i) => { picked = i; });
      const idle = { held: {}, pressed: {}, released: {}, consume() {} };
      const press = (k) => ({ held: {}, pressed: { [k]: true }, released: {}, consume() {} });

      /* 1. Se aukeaa itsestään, eikä jää kesken. Matkalla lasketaan myös
       *    kuinka monta framea kappale seisoo paikallaan isometrisessä
       *    kulmassa ennen kuin taitos alkaa: ks. `ISO_BEAT`. */
      let openedAt = -1;
      let stillAt = 0;
      let restRot = null;
      for (let f = 0; f < 400 && openedAt < 0; f++) {
        sc.update(idle);
        if (sc.phase === 'settling' && sc.turn >= 1) {
          stillAt++;
          restRot = sc.rot.slice();
        }
        if (sc.phase === 'choosing') openedAt = f;
      }

      /* 2. Litteänä jokainen tahko on ruudulla. Kolmion kärjet lasketaan
       *    samasta metodista jota piirto käyttää, joten tämä mittaa sitä mitä
       *    näkyy eikä sitä mitä aiottiin. */
      let inside = true;
      const box = [999, 999, -999, -999];
      for (let i = 0; i < 8; i++) {
        for (const [x, y] of sc.facePoints(i).pts) {
          if (x < 0 || x > 320 || y < 0 || y > 240) inside = false;
          box[0] = Math.min(box[0], x); box[1] = Math.min(box[1], y);
          box[2] = Math.max(box[2], x); box[3] = Math.max(box[3], y);
        }
      }

      /* 3. Valinta liikkuu ja 4. hyväksyntä sulkee nopan ja vie naapuriin. */
      const first = sc.target;
      sc.update(press('right'));
      const moved = sc.target !== first;
      sc.tick = 100;
      sc.update(press('jump'));
      const shutting = sc.phase === 'shutting';
      for (let f = 0; f < 400 && picked < 0; f++) sc.update(idle);
      const step = picked >= 0 ? (0 ^ picked) : -1;
      /* 5. Levossa näkyy kolme tahkoa eikä yksi. Sama laskenta kuin
       *    piirrossa: tahko on edessä kun `front` on tosi. */
      let facesAtRest = 0;
      if (restRot) {
        sc.rot = restRot;
        sc.fold = 0;
        for (let i = 0; i < 8; i++) if (sc.facePoints(i).front) facesAtRest++;
      }
      return { openedAt, inside, box: box.map((n) => Math.round(n)), moved, shutting,
        picked, neighbour: step > 0 && (step & (step - 1)) === 0, stillAt, facesAtRest };
    });

    expect('noppa aukeaa itsestään eikä jää kesken',
      N.openedAt > 0 && N.openedAt < 200, `aukesi framella ${N.openedAt}`);

    expect('litteänä jokainen tahko mahtuu ruudulle',
      N.inside, `laatikko ${N.box.join(',')} vastaan 0,0,320,240`);

    expect('nuoli vaihtaa tahkoa ja hyväksyntä sulkee nopan',
      N.moved && N.shutting, `vaihtui ${N.moved}, sulkeutuu ${N.shutting}`);

    expect('nopasta astutaan naapuriin, ei mihin tahansa maailmaan',
      N.picked >= 0 && N.neighbour, `valittiin ${N.picked}, naapuri ${N.neighbour}`);

    /*
     * ISOMETRINEN LEPO (19.8.2026). Kaksi väitettä joita kumpaakin rikottiin
     * kerran rakentamisen aikana, ja kummankin oire oli sama: kappale lakkasi
     * lukemasta kappaleena.
     *
     * Ensimmäinen on ajoitus. Kiinteä kamera on koko isometrisen kuvan ehto,
     * ja jos asettuminen luovuttaa vuoron taitokselle samalla framella jolla
     * se saapuu, kiinteää kameraa ei ole ollut olemassa yhtenäkään framena.
     *
     * Toinen on geometria. Oktaedria suoraan tahkoa päin katsottaessa näkyy
     * **yksi** tahko: kolme naapuria ovat 109 asteen päässä ja osoittavat
     * kaikki poispäin. Lepoasento ei siis voi olla pelkkä `facing()`, ja tämä
     * on se tarkistus joka huomaa jos kallistus joskus nollataan.
     */
    expect('noppa seisoo isometrisessä kulmassa ennen kuin se aukeaa',
      N.stillAt >= 12, `paikallaan ${N.stillAt} framea`);

    expect('levossa näkyy useampi tahko kuin yksi, eli kappale lukee kappaleena',
      N.facesAtRest >= 3, `${N.facesAtRest} tahkoa edessä`);
  }

  /* ---------------------------- kuutiokartta ---------------------------- */
  /*
   * MAAILMAT KUUTION KÄRJISSÄ (19.8.2026).
   *
   * Kahdeksan maailmaa kahdeksansivuisen nopan tahkoilla; kaksi tahkoa on
   * naapureita kun niillä on yhteinen särmä, ja se verkko on kuutio, koska
   * oktaedrin duaali on kuutio. Linnakkeen jälkeen ei siis mennä maailmaan
   * `n + 1` vaan valitaan yksi kolmesta ovesta.
   *
   * Neljä väitettä. Kolmas on se joka tekee valinnasta valinnan eikä arvontaa,
   * ja neljäs on se joka pitää kierroksen loppuvan.
   */
  {
    const C = await page.evaluate(async () => {
      const { WORLDS, worldDoors, worldTier, startNode } = await import('/src/data/worlds.js');
      const { DIFFICULTY } = await import('/src/data/difficulty.js');
      const { EndingScene } = await import('/src/scenes/cards.js');
      const { DieScene } = await import('/src/scenes/die.js');
      const med = (i) => {
        const lv = (WORLDS[i].nodes || []).filter((n) => n.level && DIFFICULTY[n.level] !== undefined)
          .map((n) => DIFFICULTY[n.level]).sort((a, b) => a - b);
        return lv.length ? lv[Math.floor(lv.length / 2)] : 0;
      };
      const pop = (n) => (n & 1) + ((n >> 1) & 1) + ((n >> 2) & 1);

      /* 1 + 2: three doors each, each one bit away, and the whole thing joined up. */
      let shape = true;
      for (let i = 0; i < 8; i++) {
        const d = worldDoors(i);
        if (d.length !== 3) shape = false;
        for (const j of d) {
          if (pop(i ^ j) !== 1) shape = false;
          if (!worldDoors(j).includes(i)) shape = false;   // doors swing both ways
        }
      }
      const seen = new Set([0]);
      const q = [0];
      while (q.length) for (const j of worldDoors(q.shift())) if (!seen.has(j)) { seen.add(j); q.push(j); }

      /* 3: every door that leads AWAY from the start leads somewhere harder. */
      const down = [];
      for (let i = 0; i < 8; i++) {
        for (const j of worldDoors(i)) {
          if (pop(j) > pop(i) && med(j) < med(i)) down.push(`${i + 1}->${j + 1}`);
        }
      }

      /* 4: the fortress of a tier-3 world ends the run; anything else offers doors. */
      const game = window.sfb3;
      const mkState = (world) => ({ lives: 3, coins: 60, score: 0, power: { type: null, level: 0 },
        reserve: null, world, node: null, cleared: {}, worldsOpen: 1, cards: [], secrets: {},
        checks: {}, doors: {}, visited: {}, usedSaveState: false, continues: 0, bestTimes: {} });
      game.state = mkState(0);
      game.completeWorld();
      const mid = game.scene;
      const offered = mid instanceof DieScene ? mid.doors.length : -1;
      const picked = mid instanceof DieScene ? mid.doors[0].i : -1;
      if (mid instanceof DieScene) mid.pick(picked);
      const landedWorld = game.state.world;
      const landedNode = game.state.node;
      const wantNode = startNode(WORLDS[picked]).id;
      const visitedStart = !!game.state.visited[0];

      game.state = mkState(7);
      game.completeWorld();
      const ended = game.scene instanceof EndingScene;
      return { shape, joined: seen.size, down, offered, picked, landedWorld,
        nodeOk: landedNode === wantNode, visitedStart, ended, tierLast: worldTier(7) };
    });

    expect('jokaisesta maailmasta on kolme ovea, ja jokainen ovi aukeaa molempiin suuntiin',
      C.shape && C.joined === 8,
      `muoto ${C.shape}, saavutettavia maailmoja ${C.joined}/8`);

    expect('eteenpäin vievä ovi vie aina vaikeampaan maailmaan',
      C.down.length === 0, C.down.length ? `alaspäin: ${C.down.join(' ')}` : 'ei yhtään');

    expect('linnake tarjoaa kolme ovea, ja valittu vie sen maailman alkuun',
      C.offered === 3 && C.landedWorld === C.picked && C.nodeOk && C.visitedStart,
      `ovia ${C.offered}, valittiin ${C.picked + 1}, päädyttiin ${C.landedWorld + 1},`
      + ` alkuruutu ${C.nodeOk}, lähtömaailma merkitty käydyksi ${C.visitedStart}`);

    expect('kolmannen portaan linnake lopettaa kierroksen eikä tarjoa ovia',
      C.ended && C.tierLast === 3, `loppuruutu ${C.ended}, viimeisen porras ${C.tierLast}`);
  }

  /* --------------------------- rinnekatapultti -------------------------- */
  /*
   * AJOITETTU LÄHTÖ RINTEEN HUIPULTA (19.8.2026).
   *
   * Omistaja: *"well-timed jumps should be rewarded, maybe with a somersault
   * and extra distance? The most obvious place is right on the edge of a `/`,
   * which kinda functions like a catapult."*
   *
   * Neljä väitettä, ja kaksi viimeistä ovat ne joita ilman tämä olisi
   * pumppaus uudestaan:
   *
   *   1  ajoissa painettu nousee korkeammalle ja kantaa pidemmälle
   *   2  ikkuna sulkeutuu: myöhässä painettu on **tasan** sama kuin ei mitään
   *   3  vaakanopeus ei nouse — `MAX_P` on hyppybudjetin mitta ja pysyy
   *   4  ohittaminen ei maksa mitään: lähtö tapahtuu joka tapauksessa
   */
  {
    const S = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const { MAX_P } = await import('/src/entities/player.js');
      const game = window.sfb3;
      const runSlope = (pressAt) => {
        game.state = { lives: 3, coins: 90, score: 0, power: { type: null, level: 0 },
          reserve: null, world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
          secrets: {}, checks: {}, doors: {}, usedSaveState: false, continues: 0, bestTimes: {} };
        const sc = new LevelScene(game, '1-3');
        game.setScene(sc);
        sc.time = 9999;
        sc.clockStopped = true;
        sc.entities = sc.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
        let at = null;
        for (let ty = 0; ty < sc.h && !at; ty++) {
          for (let tx = 20; tx < sc.w - 20; tx++) {
            if (sc.grid[ty][tx] === '/') { at = { tx, ty }; break; }
          }
        }
        if (!at) return null;
        const p = sc.player;
        p.x = (at.tx - 14) * 16;
        p.y = (at.ty - 1) * 16;
        p.vx = 0; p.vy = 0;
        const inp = { held: {}, pressed: {}, released: {}, consume(a) { this.pressed[a] = false; } };
        let launched = -1;
        let peak = 0;
        let x0 = 0;
        let dist = 0;
        let topVx = 0;
        let flipped = false;
        for (let f = 0; f < 260; f++) {
          inp.held = { right: true, run: true };
          inp.pressed = {};
          const wasGround = p.onGround;
          if (launched >= 0 && f - launched === pressAt) {
            inp.pressed.jump = true;
            inp.held.jump = true;
          }
          if (launched >= 0 && p.vy < 0) inp.held.jump = true;
          sc.update(inp);
          topVx = Math.max(topVx, Math.abs(p.vx));
          if (p.flip > 0) flipped = true;
          if (launched < 0 && wasGround && !p.onGround && p.vy < 0) {
            launched = f; x0 = p.cx; peak = p.cy;
          }
          if (launched >= 0) {
            peak = Math.min(peak, p.cy);
            if (p.onGround && f > launched + 4) { dist = Math.round(p.cx - x0); break; }
          }
        }
        return { peak: Math.round(peak), dist, topVx: Math.round(topVx * 1000) / 1000, flipped };
      };
      return { none: runSlope(-1), timed: runSlope(3), late: runSlope(14), cap: MAX_P };
    });

    expect('rinteen huipulla ajoitettu painallus nousee korkeammalle ja kantaa pidemmälle',
      !!S.timed && S.timed.peak < S.none.peak - 10 && S.timed.dist > S.none.dist * 1.5,
      `ilman ${S.none.peak} px / ${S.none.dist} px, ajoissa ${S.timed.peak} px / ${S.timed.dist} px`);

    expect('ikkuna sulkeutuu: myöhässä painettu on sama kuin ei mitään',
      S.late.peak === S.none.peak && S.late.dist === S.none.dist,
      `myöhässä ${S.late.peak} px / ${S.late.dist} px, ilman ${S.none.peak} px / ${S.none.dist} px`);

    expect('katapultti on pystysuora: vaakanopeus ei ylitä P-kattoa',
      S.timed.topVx <= S.cap + 0.001 && S.none.topVx <= S.cap + 0.001,
      `ajoissa ${S.timed.topVx}, ilman ${S.none.topVx}, katto ${S.cap}`);

    expect('kuperkeikka pyörii vain ajoitetusta lähdöstä',
      S.timed.flipped && !S.none.flipped && !S.late.flipped,
      `ajoissa ${S.timed.flipped}, ilman ${S.none.flipped}, myöhässä ${S.late.flipped}`);
  }

  /* ------------------------ varalokeron kierto -------------------------- */
  /*
   * OSUMA EI OLE VAIHTO (19.8.2026).
   *
   * Omistaja pelasi 2-1:tä: *"hit the sun = lost tanooki power but instantly
   * gained some other skill, then hit the sun again = lost the powerup but
   * regained tanooki. It's like they're forever cycling?"*
   *
   * Ja niin ne olivat. Kaksi erikseen oikeaa sääntöä muodostivat silmukan:
   * osuma pudottaa varalokeron maahan, ja poimittu tehostus lokeroi sen jota
   * piti päällä. Yhdessä: lehti putoaa, poimit sen, kukka menee lokeroon,
   * seuraava osuma pudottaa kukan — pari ei kulunut koskaan, eli vahinko ei
   * maksanut mitään.
   *
   * Väite on siis se että **takaisin poimittu lokero on käytetty**. Mitataan
   * kierros kerrallaan: osuma, poiminta, ja lokeron on oltava tyhjä.
   */
  {
    const R = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const game = window.sfb3;
      game.state = { lives: 5, coins: 90, score: 0, power: { type: 'leaf', level: 2 },
        reserve: 'flower', world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
        secrets: {}, checks: {}, doors: {}, usedSaveState: false, continues: 0, bestTimes: {} };
      const sc = new LevelScene(game, '1-1');
      game.setScene(sc);
      sc.time = 9999;
      sc.clockStopped = true;
      const p = sc.player;
      const before = { type: p.power.type, level: p.power.level, reserve: game.state.reserve };

      p.hurt('test');
      const dropped = sc.entities.filter((e) => e.kind === 'item').map((e) => e.itemKind);
      const afterHit = { type: p.power.type, reserve: game.state.reserve };

      /* Poimitaan pudonnut: sama reitti kuin pelissä, `collect` lipun kanssa. */
      const item = sc.entities.find((e) => e.kind === 'item');
      if (item) {
        p.collect(item.itemKind, !!item.recovered);
        /* Sama kuin oikealla reitillä (`scenes/level.js`): poimittu katoaa.
         * Ilman tätä alla laskettaisiin sama esine uudelleen. */
        item.remove = true;
        sc.entities = sc.entities.filter((e) => !e.remove);
      }
      const afterPick = { type: p.power.type, reserve: game.state.reserve };

      /* Ja sama uudelleen: toinen osuma ei saa pudottaa mitään, koska lokero
       * on tyhjä — juuri tämä oli se ikuinen kierto. */
      p.invuln = 0;
      p.hurt('test');
      const secondDrop = sc.entities.filter((e) => e.kind === 'item').length;
      return { before, dropped, afterHit, afterPick, secondDrop };
    });

    expect('osuma pudottaa varalokeron, ja takaisin poimittu lokero on käytetty',
      R.dropped.join() === 'flower' && R.afterHit.reserve === null
      && R.afterPick.type === 'flower' && R.afterPick.reserve === null
      && R.secondDrop === 0,
      `lokerossa ${R.before.reserve}, osuma pudotti [${R.dropped.join()}],`
      + ` poiminnan jälkeen voima ${R.afterPick.type} ja lokero`
      + ` ${R.afterPick.reserve || 'tyhjä'}; toinen osuma pudotti ${R.secondDrop}`);
  }

  /* --------------------------- ketjun elämä ----------------------------- */
  /*
   * KETJUN ELÄMÄ TULEE VAIN KAKKOSEN POTENSSILLA (19.8.2026).
   *
   * Ennen tätä ehto oli *"tikapuut loppuivat"*: yhdeksäs tappo maksoi elämän
   * ja niin maksoi jokainen sen jälkeen, eli kahdentoista ketju antoi neljä.
   * Omistaja: *"chained kills give 1UP too easily."*
   */
  {
    const C = await page.evaluate(async () => {
      const { LevelScene } = await import('/src/scenes/level.js');
      const { CHAIN_LIFE } = await import('/src/core/points.js');
      const game = window.sfb3;
      game.state = { lives: 0, coins: 60, score: 0, power: { type: null, level: 0 },
        reserve: null, world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
        secrets: {}, checks: {}, doors: {}, usedSaveState: false, continues: 0, bestTimes: {} };
      const sc = new LevelScene(game, '1-1');
      game.setScene(sc);
      const owner = { chain: 0 };
      sc.chainOwner = owner;
      const lives = [];
      for (let k = 0; k < 40; k++) {
        const before = game.state.lives;
        sc.chainReward(256, sc.player.cx, sc.player.cy);
        if (game.state.lives > before) lives.push(k + 1);
      }
      return { lives, first: CHAIN_LIFE, score: game.state.score };
    });

    expect('ketju maksaa elämän vain kakkosen potenssilla, ensimmäisen kerran 16:lla',
      C.lives.join(',') === '16,32' && C.first === 16,
      `elämät ketjun pituuksilla ${C.lives.join(', ') || 'ei yhtään'}`);
  }

  expect('täysi mittari vie P-nopeuteen eikä mikään vie sen yli',
    P.ceiling <= P.max.P + 0.001 && P.ceiling > P.max.run,
    `nopein ${P.ceiling} px/frame, P-katto ${P.max.P}, juoksukatto ${P.max.run}`);

  expect('pohjassa pitäminen täyttää mittarin',
    P.hold.meter >= 112 && P.hold.vents === 0 && P.hold.frames < 200,
    `${P.hold.frames} framea, mittari ${P.hold.meter}, tyhjennyksiä ${P.hold.vents}`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- vauhtimittari: loppu ---- */
/* ---- rinne koskee muutakin kuin pelaajaa ---- */
/*
 * SE MIKÄ LIUKUU TAI VIERII TOTTELEE RINNETTÄ, SE MIKÄ KÄVELEE EI.
 *
 * ROADMAP kirjasi puuttuvan puoliskon rinteistä (v26.08.18.13): *"kuori
 * kiihtyy alamäkeen kuten pelaajakin, mutta kukaan ei ole vielä suunnitellut
 * sitä."* Suunnitelma on yksi lause, ja se on tässä mitattuna kolmesta
 * suunnasta — koska sen molemmat puolet ovat väitteitä ja kumpikin voi mennä
 * rikki hiljaa.
 *
 *   1  kuori      potkaistu kuori kiihtyy alamäkeen ja hidastuu ylämäkeen
 *   2  kävelijä   kävelijä ei tee kumpaakaan — sen vauhti on sen sopimus
 *   3  yksi laki  pelaaja ja kuori käyttävät samaa funktiota, eivät kopiota
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const S = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { Walker, ShellGuy } = await import('/src/entities/enemies.js');
    const { T } = await import('/src/gfx/tiles.js');
    const game = window.sfb3;
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    /*
     * Koeasetelma: tasainen kenttä johon kirjoitetaan alamäki. Rinne tehdään
     * käsin eikä etsitä kentästä, jotta mitattava asia on rinne eikä se mikä
     * sattuu olemaan sen vieressä.
     */
    const ramp = (down) => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      /* Kaistale tasamaata, ja sen keskellä neljän laatan pudotus tai nousu. */
      for (let tx = 2; tx < 40; tx++) {
        for (let ty = 7; ty < 14; ty++) s.setTile(tx, ty, T.EMPTY);
        s.setTile(tx, 14, T.GROUND);
        s.setTile(tx, 15, T.GROUND);
      }
      if (down !== 0) {
        for (let j = 0; j < 4; j++) {
          const tx = 10 + j;
          /* Alamäki kirjoitetaan `\\`:llä ja ylämäki `/`:llä; kummankin alla
           * on kiveä, koska rinne on maan pinta eikä kelluva viiva. */
          const top = down > 0 ? 10 + j : 13 - j;
          s.setTile(tx, top, down > 0 ? T.SLOPE_L : T.SLOPE_R);
          for (let ty = top + 1; ty < 14; ty++) s.setTile(tx, ty, T.GROUND);
        }
        if (down > 0) {
          for (let tx = 2; tx < 10; tx++) for (let ty = 10; ty < 14; ty++) s.setTile(tx, ty, T.GROUND);
        }
      }
      return s;
    };
    const run = (make, down) => {
      const s = ramp(down);
      const i = mkInput();
      const e = make(s);
      /*
       * Jalat pinnalle, ja vasta `make`n jälkeen. Kaksi mitattua syytä:
       *
       *   - **Keho ei ole se jonka koko konstruktori antaa.** `toShell`
       *     kutistaa kuoren 24 pikselistä 14:ään, joten konstruktorille
       *     annettu rivi ei kerro missä jalat ovat. Ilman tätä riviä kuori
       *     syntyi kahdeksan pikseliä lattian sisään, `moveX` luki lattian
       *     seinäksi ja kuori pomppi paikallaan koko kokeen ajan.
       *   - **Alamäessä pinta ei ole rivillä 14.** `ramp` nostaa ylätasanteen
       *     riville 10, koska rinne kulkee alaspäin eikä kentässä ole tilaa
       *     rivin 15 alapuolella. Riville 14 pantu kuori olisi kiven sisässä.
       */
      e.y = (down > 0 ? 10 : 14) * 16 - e.h;
      e.active = true;
      e.alwaysActive = true;
      s.entities.push(e);
      /*
       * Kolme lukua eikä yksi, ja `slope` on niistä se tärkein.
       *
       * Huippuvauhti yksin ei voi nähdä ylämäkeä lainkaan: potku antaa
       * lähtövauhdin, ja jarruttava rinne ei koskaan ylitä sitä. Ja kumpikaan
       * luku ei kerro *kävikö keho rinteessä* — juuri se oli tämän kokeen
       * ensimmäinen vika, ja se meni läpi vihreänä.
       */
      let top = 0;
      let low = Infinity;
      let slope = 0;
      for (let f = 0; f < 90; f++) {
        s.update(i);
        top = Math.max(top, Math.abs(e.vx));
        if (e.onSlope) { low = Math.min(low, Math.abs(e.vx)); slope++; }
      }
      const r = (v) => Math.round(v * 100) / 100;
      return { top: r(top), low: low === Infinity ? null : r(low), slope };
    };
    const shell = (s) => {
      const e = new ShellGuy(s, 6 * 16, 13 * 16);
      e.toShell();
      e.kick(1);
      return e;
    };
    /* Sarake 9 eikä 6, ja se on mitattu: kävelijä kulkee 0,55 px/frame, eli
     * yhdeksässäkymmenessä framessa 49 pikselia. Sarakkeesta 6 lähtenyt ei
     * yltänyt rinteen alkuun (sarake 10) lainkaan, joten koe vertasi kahta
     * tasamaata toisiinsa. Suunta pannaan käsin samasta syystä: vasemmalle
     * kääntynyt kävelijä kävelee poispäin rinteestä. */
    const walker = (s) => {
      const e = new Walker(s, 9 * 16, 13 * 16);
      e.facing = 1;
      e.vx = e.speed;
      return e;
    };
    const out = {
      shellFlat: run(shell, 0), shellDown: run(shell, 1), shellUp: run(shell, -1),
      walkFlat: run(walker, 0), walkDown: run(walker, 1),
    };
    const phys = await import('/src/level/physics.js');
    out.shared = typeof phys.slopePull === 'function';
    return out;
  });

  expect('potkaistu kuori kiihtyy alamäkeen',
    S.shellDown.slope > 0 && S.shellDown.top > S.shellFlat.top + 0.2,
    `tasamaalla ${S.shellFlat.top} px/frame, alamäkeen ${S.shellDown.top}`
    + ` (${S.shellDown.slope} framea rinteessä)`);

  /* Ja toinen puoli samasta lauseesta. Hitain vauhti rinteessä eikä nopein,
   * koska nopein on se jolla kuori saapui: ylämäki syö vauhtia eikä anna, ja
   * huippumittari ei näe sitä koskaan. */
  expect('potkaistu kuori hidastuu ylämäkeen',
    S.shellUp.slope > 0 && S.shellUp.low < S.shellFlat.top - 0.2,
    `tasamaalla ${S.shellFlat.top} px/frame, ylämäessä hitaimmillaan ${S.shellUp.low}`
    + ` (${S.shellUp.slope} framea rinteessä)`);

  /* `slope > 0` on tässä yhtä tärkeä kuin itse vertailu: kävelijä joka ei
   * koskaan astunut rinteeseen kävelee tietysti samaa vauhtia. */
  expect('kävelijä kävelee samaa vauhtia myös rinteessä',
    S.walkDown.slope > 0 && Math.abs(S.walkDown.top - S.walkFlat.top) < 0.05,
    `tasamaalla ${S.walkFlat.top} px/frame, alamäkeen ${S.walkDown.top}`
    + ` (${S.walkDown.slope} framea rinteessä)`);

  expect('rinteen sääntö on yksi funktio eikä kopio kehoa kohti',
    S.shared, `physics.js vie slopePullin ulos: ${S.shared}`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- rinne: loppu ---- */
/* ---- katamari: karvapallo kerää ---- */
/*
 * PALLO KERÄÄ SEN MINKÄ YLI SE VIERII.
 *
 * Omistaja 18.8.2026: *"muokkaa jotain vihollista niin, että se voi tarttua
 * yhteen toisen vihollisen kanssa ja liikkua yhdessä; niiden koko kasvaa
 * spiraalin muodossa … mutta siten, että vihollinen itse kasvattaa itsestään
 * isomman."*
 *
 * Tämä on ensimmäinen laki jossa **olio tarttuu olioon**, ja siksi se
 * mitataan neljästä suunnasta. Kolme ensimmäistä ovat sen omat väitteet;
 * neljäs on se raja jonka rikkoutuminen olisi hiljainen ja epäreilu.
 *
 *   1  kerää     pallo nappaa kävelijän, kasvaa, ja kyytiläisiä on katto
 *   2  spiraali  kyytiläiset ovat eri etäisyyksillä ja liikkuvat pallon mukana
 *   3  laina     puhjetessaan pallo päästää irti — kentästä ei katoa ketään
 *   4  reiluus   kyytiläinen ei satuta pelaajaa (laki 2: vain oma ketju)
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const K = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { Walker, Karvapallo } = await import('/src/entities/enemies.js');
    const { captureState, restoreState } = await import('/src/core/savestate.js');
    const game = window.sfb3;
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const scene = () => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, '1-1');
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      s.player.x = 8;
      return s;
    };
    const put = (s, e) => { e.active = true; e.alwaysActive = true; s.entities.push(e); return e; };
    const out = {};

    /* 1 + 2. Rivi kävelijöitä, pallo niiden päälle. */
    {
      const s = scene();
      const i = mkInput();
      const floor = 14;
      const walkers = [3, 5, 7, 9, 11, 13].map((tx) => {
        const w = put(s, new Walker(s, tx * 16, floor * 16 - 16));
        w.speed = 0;
        w.vx = 0;
        return w;
      });
      const ball = put(s, new Karvapallo(s, 2 * 16, floor * 16 - 12, 1));
      const w0 = ball.w;
      for (let f = 0; f < 260; f++) s.update(i);
      const riders = walkers.filter((w) => w.rolledBy === ball.id);
      const radii = riders.map((w) => Math.round(Math.hypot(w.cx - ball.cx, w.cy - ball.cy)));
      const before = riders.map((w) => `${Math.round(w.x)},${Math.round(w.y)}`);
      for (let f = 0; f < 12; f++) s.update(i);
      const moved = riders.filter((w, k) => `${Math.round(w.x)},${Math.round(w.y)}` !== before[k]);
      out.roll = {
        riders: riders.length, grew: ball.w - w0, size: ball.w,
        boxes: riders.map((w) => w.box.w),
        radii: [...new Set(radii)].sort((a, b) => a - b),
        moved: moved.length, gone: ball.remove,
      };
    }

    /* 3. Puhkeaminen päästää irti. */
    {
      const s = scene();
      const i = mkInput();
      const floor = 14;
      const walkers = [3, 5, 7].map((tx) => {
        const w = put(s, new Walker(s, tx * 16, floor * 16 - 16));
        w.speed = 0;
        w.vx = 0;
        return w;
      });
      const ball = put(s, new Karvapallo(s, 2 * 16, floor * 16 - 12, 1));
      for (let f = 0; f < 120 && !ball.remove; f++) s.update(i);
      const caught = walkers.filter((w) => w.rolledBy).length;
      ball.burst();
      for (let f = 0; f < 40; f++) s.update(i);
      out.release = {
        caught,
        alive: walkers.filter((w) => !w.remove).length,
        free: walkers.filter((w) => !w.rolledBy).length,
        boxed: walkers.filter((w) => w.box.w > 0).length,
      };
    }

    /* 4. Reiluus ja pikatallennus. */
    {
      const s = scene();
      const i = mkInput();
      const floor = 14;
      const w = put(s, new Walker(s, 5 * 16, floor * 16 - 16));
      w.speed = 0;
      w.vx = 0;
      const ball = put(s, new Karvapallo(s, 4 * 16, floor * 16 - 12, 1));
      for (let f = 0; f < 90 && !w.rolledBy; f++) s.update(i);
      /*
       * Laki 2: kyytiläinen ei satuta. Mitataan kahdesta suunnasta, koska
       * pelkkä "pelaaja kyytiläisen päälle" mittaisi **palloa** — kyytiläinen
       * kiertää pallon vieressä, joten sen kohdalla seisova osuu palloon,
       * ja pallo satuttaa aivan oikein. Siksi pallo siirretään ensin pois:
       * mitattava asia on se laatikko joka jää.
       */
      const p = s.player;
      const emptyBox = w.box.w === 0 && w.box.h === 0;
      ball.x = w.x + 4000;
      ball.y = w.y;
      p.x = w.x;
      p.y = w.y;
      p.invuln = 0;
      const powerBefore = p.power.level;
      s.collisions(i);
      out.fair = {
        caught: !!w.rolledBy, emptyBox, hurt: p.power.level !== powerBefore || p.dying,
      };

      captureState(game, 0);
      restoreState(game, 0);
      const back = game.scene.entities.find((e) => e.constructor.name === 'Walker');
      const ballBack = game.scene.entities.find((e) => e.constructor.name === 'Karvapallo');
      out.saved = {
        pairs: !!back && !!ballBack && back.rolledBy === ballBack.id,
        size: ballBack ? ballBack.w : 0,
      };
    }
    return out;
  });

  expect('karvapallo kerää kävelijöitä, kasvaa niiden mukana ja lopettaa kattoon',
    K.roll.riders > 1 && K.roll.riders <= 4 && K.roll.grew === K.roll.riders * 4,
    `${K.roll.riders} kyytiläistä, koko 12 → ${K.roll.size} px`);

  expect('kyytiläiset ovat spiraalilla: eri etäisyyksillä ja liikkeessä pallon mukana',
    K.roll.radii.length === K.roll.riders && K.roll.moved === K.roll.riders,
    `säteet ${K.roll.radii.join(' · ')} px, liikkui ${K.roll.moved}/${K.roll.riders}`);

  expect('puhjennut pallo päästää irti: kentästä ei katoa ketään',
    K.release.caught > 0 && K.release.alive === 3 && K.release.free === 3
    && K.release.boxed === 3,
    `keräsi ${K.release.caught}, elossa ${K.release.alive}/3, vapaana ${K.release.free},`
    + ` laatikko takaisin ${K.release.boxed}`);

  expect('kyytiläinen ei satuta pelaajaa — vain se ketju jonka pelaaja aloitti',
    K.fair.caught && K.fair.emptyBox && !K.fair.hurt,
    `kerätty: ${K.fair.caught}, laatikko tyhjä: ${K.fair.emptyBox}, satutti: ${K.fair.hurt}`);

  expect('kyyti kestää pikatallennuksen',
    K.saved.pairs && K.saved.size > 12,
    `pari säilyi: ${K.saved.pairs}, pallon koko ${K.saved.size}`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- katamari: loppu ---- */
/* ---- kuolema on oma kuvansa ---- */
/*
 * KUOLEMA EI OLE HYPPY.
 *
 * Omistaja 18.8.2026: *"tee pelaajahahmon kuolinanimaatioista
 * personallisempia … ehkä kaasu paisuu ja poksahtaa?"* Tähän asti
 * `Player.state()` palautti kuolevalle `'jump'`, eli kuolema oli hyppy jonka
 * fysiikka oli riisuttu — genren kuolema kirjaimellisesti.
 *
 * Neljä väitettä, ja ensimmäinen on se joka olisi muuten rapistunut hiljaa:
 *
 *   1  kuva       kuoleva ei näytä hyppäävältä, mitattuna pikseleistä
 *   2  vaiheet    jäykkä → paisuu → tyhjä kuori, kaikki kolme eri kuvaa
 *   3  poksahdus  tasan kerran, tasan `DEATH_POP`illa, ja siitä jää kaasua
 *   4  ikkuna     koko animaatio ehtii kulua ennen kuin kohtaus loppuu
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const D = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { drawPlayer, DEATH_SWELL, DEATH_POP } = await import('/src/gfx/sprites/player.js');
    const { Sfx } = await import('/src/core/audio.js');
    const game = window.sfb3;
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const out = { swellAt: DEATH_SWELL, popAt: DEATH_POP };

    /* 1 + 2. Kuvat. Sama keho, samat värit, vain `dead`/`deadT` vaihtuu. */
    const cv = document.createElement('canvas');
    cv.width = 64;
    cv.height = 64;
    const g = cv.getContext('2d');
    const shot = (extra) => {
      g.clearRect(0, 0, 64, 64);
      drawPlayer(g, 20, 20, {
        type: 'shroom', level: 1, facing: 1, frame: 0, state: 'jump', tick: 5, ...extra,
      });
      const d = g.getImageData(0, 0, 64, 64).data;
      let h = 2166136261;
      let ink = 0;
      for (let i = 0; i < d.length; i += 4) {
        if (d[i + 3] > 0) ink++;
        h ^= d[i] + d[i + 1] * 3 + d[i + 2] * 7 + d[i + 3] * 11;
        h = Math.imul(h, 16777619);
      }
      return { h: h >>> 0, ink };
    };
    const jump = shot({});
    const stiff = shot({ dead: true, deadT: 6 });
    const swell = shot({ dead: true, deadT: DEATH_POP - 2 });
    const husk = shot({ dead: true, deadT: DEATH_POP + 18 });
    out.pics = {
      jump: jump.h, stiff: stiff.h, swell: swell.h, husk: husk.h,
      /* Paisunut on leveämpi kuin jäykkä: se on koko keskimmäisen vaiheen
       * väite yhtenä lukuna. */
      wider: swell.ink > stiff.ink,
      /* Tyhjä kuori on litteämpi kuin jäykkä. */
      flatter: husk.ink < stiff.ink,
    };

    /* 3 + 4. Poksahdus oikeassa kentässä. */
    game.state = {
      lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
      world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
    };
    let done = null;
    game.finishLevel = (r) => { done = r; };
    const s = new LevelScene(game, '1-1');
    game.setScene(s);
    s.time = 9999;
    s.clockStopped = true;
    const heard = [];
    const real = Sfx.play;
    Sfx.play = (n) => { heard.push(n); };
    const i = mkInput();
    const puffs = () => s.entities.filter((e) => e.constructor.name === 'Puff').length;
    s.player.die('debug');
    const before = puffs();
    let popFrame = -1;
    let popPuffs = 0;
    let frames = 0;
    for (let f = 0; f < 200 && !done; f++) {
      const was = puffs();
      s.update(i);
      frames++;
      if (popFrame < 0 && puffs() > was) { popFrame = s.player.deathT; popPuffs = puffs() - was; }
    }
    Sfx.play = real;
    out.pop = {
      at: popFrame, puffs: popPuffs, before,
      sounds: heard.filter((n) => n === 'pop').length,
      /* Kuinka pitkälle kello ehti ennen kuin kohtaus antoi periksi. */
      reached: s.player.deathT, frames, ended: !!done,
    };
    return out;
  });

  const uniq = new Set([D.pics.jump, D.pics.stiff, D.pics.swell, D.pics.husk]);
  expect('kuoleva hahmo ei näytä hyppäävältä, eikä kolme vaihetta näytä toisiltaan',
    uniq.size === 4,
    `${uniq.size} eri kuvaa neljästä (hyppy, jäykkä, paisunut, kuori)`);

  expect('paisunut on leveämpi kuin jäykkä, ja tyhjä kuori litteämpi',
    D.pics.wider && D.pics.flatter,
    `paisunut leveämpi: ${D.pics.wider}, kuori litteämpi: ${D.pics.flatter}`);

  expect('kaasu poksahtaa tasan kerran ja tasan silloin kun sen pitää',
    D.pop.at === D.popAt && D.pop.puffs >= 6 && D.pop.sounds === 1,
    `poksahti kellolla ${D.pop.at} (odotettu ${D.popAt}), ${D.pop.puffs} kaasupilveä,`
    + ` ${D.pop.sounds} ääntä`);

  expect('koko animaatio ehtii kulua ennen kuin kohtaus loppuu',
    D.pop.ended && D.pop.reached > D.popAt + 20,
    `kello ehti ${D.pop.reached}, poksahdus ${D.popAt}, kohtaus kesti ${D.pop.frames} framea`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- kuolema: loppu ---- */
/* ---- kysymyslohkon kolikot ---- */
/*
 * LOHKO ANTAA 1…5 KOLIKKOA, JA SE ON SAMA LUKU IKUISESTI.
 *
 * Omistaja 18.8.2026: *"question mark block voisi antaa satunnaisen määrän
 * kolikoita, 1-5 ehkä?"* Satunnaisuus on tässä **kentän ominaisuus eikä ajon**,
 * ja se on pakko eikä makuasia: kolikot ovat aikaa (`updateTimer`), joten
 * `Math.random()` tekisi kentän aikabudjetista arpapelin ja `playable.mjs`
 * mittaisi joka ajolla eri kenttää.
 *
 * Kolme väitettä:
 *
 *   1  vaihtelu   pelin lohkot antavat eri määriä, ja kaikki 1…5 esiintyy
 *   2  pysyvyys   sama lohko antaa saman verran joka kerta
 *   3  yksi ääni  viisi kolikkoa on yksi kilahdus, ei viittä päällekkäin
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const Q = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { T } = await import('/src/gfx/tiles.js');
    const { levelIds, getLevel } = await import('/src/data/levels.js');
    const { Sfx } = await import('/src/core/audio.js');
    const game = window.sfb3;
    const scene = (id) => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    const out = { hist: [0, 0, 0, 0, 0, 0], blocks: 0 };

    /* 1. Koko pelin jakauma, luettuna samasta funktiosta jota peli käyttää. */
    const probe = scene('1-1');
    for (const id of levelIds()) {
      const rows = getLevel(id).rows;
      rows.forEach((row, ty) => {
        for (let tx = 0; tx < row.length; tx++) {
          if (row[tx] !== T.QCOIN) continue;
          out.blocks++;
          out.hist[probe.qcoinPayout(tx, ty)]++;
        }
      });
    }

    /* 2. Sama lohko, kaksi kertaa, kaksi eri kohtausta. */
    const find = (s) => {
      for (let ty = 0; ty < s.h; ty++) {
        for (let tx = 0; tx < s.w; tx++) if (s.rawTileAt(tx, ty) === T.QCOIN) return { tx, ty };
      }
      return null;
    };
    const punch = (s, spot) => {
      const before = s.game.state.coins;
      const heard = [];
      const real = Sfx.play;
      Sfx.play = (n) => { heard.push(n); };
      s.bumpTile(spot.tx, spot.ty, s.player);
      Sfx.play = real;
      return { got: s.game.state.coins - before, heard: heard.filter((n) => n === 'coin').length };
    };
    const a = scene('1-1');
    const spot = find(a);
    const first = punch(a, spot);
    const b = scene('1-1');
    const second = punch(b, spot);
    out.same = { at: `${spot.tx},${spot.ty}`, first: first.got, second: second.got };
    out.sound = first.heard;
    out.predicted = a.qcoinPayout(spot.tx, spot.ty);
    return out;
  });

  const seen = Q.hist.slice(1);
  expect('kysymyslohkot antavat 1…5 kolikkoa, ja jokainen määrä esiintyy pelissä',
    Q.blocks > 20 && seen.every((n) => n > 0),
    `${Q.blocks} lohkoa, jakauma ${seen.join(' · ')}`);

  expect('sama lohko antaa saman verran joka kerta',
    Q.same.first === Q.same.second && Q.same.first === Q.predicted
    && Q.same.first >= 1 && Q.same.first <= 5,
    `lohko ${Q.same.at}: ${Q.same.first} ja ${Q.same.second}, ennustettu ${Q.predicted}`);

  expect('monta kolikkoa on yksi kilahdus eikä monta päällekkäin',
    Q.sound === 1, `${Q.same.first} kolikkoa, ${Q.sound} ääntä`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- kysymyslohkon kolikot: loppu ---- */
/* ---- puu ja metsäpalo ---- */
/*
 * PUU ON MAISEMAA, JA METSÄPALO ON SE JOKA TEKEE MAISEMASTA PAIKAN.
 *
 * Puu (`T.TREE`) on pelin ensimmäinen laatta jonka koko olemus on ettei se ole
 * mitään: ei kiinteä, ei satuttava, ei jalansija. Juuri siksi sillä on tässä
 * portti — laatta jota mikään sääntö ei mittaa on laatta jonka voi sijoittaa
 * mihin tahansa, ja hiljainen virhe siitä olisi leijuva metsä.
 *
 * Ja metsäpalo on se yksi asia joka **muuttaa kenttää kesken kentän**, mikä on
 * ROADMAPin 10.8.2026 rajan reunalla. Se mahtuu rajan sisään kahdesta syystä
 * ja molemmat mitataan tässä: puu ei ole reitti (se ei ole kiinteä), ja palo
 * palautuu itsestään (puu kasvaa takaisin). Jos jompikumpi lakkaa olemasta
 * totta, kenttä voi muuttua läpäisemättömäksi ilman että mikään sanoo mitään.
 *
 *   1  maisema    puu ei ole kiinteä eikä satuttava, ja se seisoo jossakin
 *   2  leviäminen palo kulkee puusta puuhun ja **pysähtyy aukiolle**
 *   3  vahinko    palava puu satuttaa, hiili ei
 *   4  palautus   lopputila on lähtötila: ruudukko ennallaan, kirjanpito tyhjä
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const F = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { T, isSolid, isSemi, TILE_INFO } = await import('/src/gfx/tiles.js');
    const { levelIds, getLevel } = await import('/src/data/levels.js');
    const game = window.sfb3;
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const scene = (id) => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 1 }, reserve: null,
        world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, id);
      game.setScene(s);
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    const out = {};

    out.where = levelIds().filter((id) => getLevel(id).wildfire);
    out.planted = levelIds().filter((id) => getLevel(id).rows.some((r) => r.includes(T.TREE)));
    out.info = {
      solid: isSolid(T.TREE), semi: isSemi(T.TREE),
      flags: Object.keys(TILE_INFO[T.TREE] || {}),
    };

    const id = out.where[0] || '6-2';
    const s = scene(id);
    out.trees = s.treeList().length;
    /* Metsän muoto lukuina: tiheikkö, aukio ja reuna ovat kolme eri tiheyttä,
     * ja juuri se on se mitä palon on määrä lukea. */
    const cols = [...new Set(s.treeList().map((t) => t.tx))].sort((a, b) => a - b);
    out.spread = { cols: cols.length };

    /* --- 2. leviäminen ja aukio ----------------------------------------- */
    {
      const t = scene(id);
      const i = mkInput();
      const list = t.treeList();
      const first = list.reduce((m, x) => (x.tx < m.tx ? x : m), list[0]);
      t.burning.set(`${first.tx},${first.ty}`, { age: 0 });
      /* Pelaaja pois tieltä, jotta mitataan leviämistä eikä kuolemaa. */
      t.player.x = (first.tx + 60) * 16;
      let reach = first.tx;
      for (let f = 0; f < 900; f++) {
        t.update(i);
        for (const key of t.burning.keys()) {
          const tx = Number(key.split(',')[0]);
          if (tx > reach) reach = tx;
        }
      }
      /* Mihin sarakkeeseen palo pysähtyi, ja mikä on lähin puu sen takana:
       * jos väli on suurempi kuin ulottuvuus, aukio pysäytti sen. */
      const beyond = list.filter((x) => x.tx > reach).map((x) => x.tx);
      out.spread.from = first.tx;
      out.spread.reach = reach;
      out.spread.gap = beyond.length ? Math.min(...beyond) - reach : null;
      out.spread.left = beyond.length;
    }

    /* --- 3. vahinko: palava satuttaa, hiili ei -------------------------- */
    {
      const hurtAt = (age) => {
        const t = scene(id);
        const i = mkInput();
        const tree = t.treeList()[0];
        t.burning.set(`${tree.tx},${tree.ty}`, { age });
        t.player.x = tree.tx * 16;
        t.player.y = tree.ty * 16;
        t.player.invuln = 0;
        const before = t.player.powerLevel;
        t.burnPlayer();
        return { before, after: t.player.powerLevel, hurt: t.player.invuln > 0 };
      };
      out.hurt = { ablaze: hurtAt(10).hurt, ash: hurtAt(200).hurt };
    }

    /* --- 4. lopputila on lähtötila -------------------------------------- */
    {
      const t = scene(id);
      const i = mkInput();
      const before = t.grid.map((r) => r.join(''));
      const tree = t.treeList()[0];
      t.burning.set(`${tree.tx},${tree.ty}`, { age: 0 });
      t.player.x = (tree.tx + 90) * 16;
      let peak = 0;
      for (let f = 0; f < 2000; f++) {
        t.update(i);
        peak = Math.max(peak, t.burning.size);
        if (t.tick % 1200 === 1199) break;   // ennen seuraavaa syttymistä
      }
      for (let f = 0; f < 900; f++) {
        if (!t.burning.size) break;
        t.update(i);
      }
      const after = t.grid.map((r) => r.join(''));
      out.restore = {
        peak, left: t.burning.size,
        same: before.length === after.length && before.every((r, k) => r === after[k]),
      };
    }
    return out;
  });

  expect('puu on maisemaa: ei kiinteä, ei puolikiinteä, eikä satuttava lippu',
    !F.info.solid && !F.info.semi && F.info.flags.join(',') === 'tree',
    `kiinteä ${F.info.solid}, puolikiinteä ${F.info.semi}, liput [${F.info.flags.join(' ')}]`);

  expect('puita on istutettu kenttään, ja metsäpalo on tasan yhdessä',
    F.planted.length >= 1 && F.where.length === 1 && F.trees > 8,
    `puita kentissä ${F.planted.join(',') || '-'} (${F.trees} kpl), palo ${F.where.join(',') || '-'}`);

  expect('palo leviää puusta puuhun ja pysähtyy aukiolle',
    F.spread.reach > F.spread.from && F.spread.left > 0 && F.spread.gap > 2,
    `syttyi sarakkeesta ${F.spread.from}, eteni sarakkeeseen ${F.spread.reach},`
    + ` aukio ${F.spread.gap} saraketta, ${F.spread.left} puuta jäi palamatta`);

  expect('palava puu satuttaa, hiili ei',
    F.hurt.ablaze && !F.hurt.ash,
    `palava ${F.hurt.ablaze}, hiili ${F.hurt.ash}`);

  expect('metsäpalon lopputila on sen lähtötila',
    F.restore.peak > 1 && F.restore.left === 0 && F.restore.same,
    `korkeimmillaan ${F.restore.peak} puuta palamassa, jäljellä ${F.restore.left},`
    + ` ruudukko ennallaan: ${F.restore.same}`);

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- puu ja metsäpalo: loppu ---- */
/* ---- möykky kentissä ---- */
/*
 * MÖYKKY ON KENTISSÄ, JA SE ON TÄMÄN LOHKON KOKO AIHE.
 *
 * `T.LUMP` rakennettiin 10.8.2026 fysiikkoineen, kolmine portteineen ja
 * tallennuksineen, eikä sitä asetettu yhteenkään kenttään. Laatta jota ei ole
 * missään on koodia joka esittää ominaisuutta: jokainen edellinen väite siitä
 * on tosi tyhjästä joukosta, ja tyhjä joukko läpäisee mitä tahansa.
 *
 * Tämä lohko mittaa neljä asiaa jotka kaikki lakkasivat olemasta triviaaleja
 * sinä hetkenä kun ensimmäinen `C` kirjoitettiin palikkaan:
 *
 *   1. **niitä on.** Ei yhtään on eri asia kuin nolla ongelmaa.
 *   2. **rules.js:n kolme sääntöä kysytään pelin omilta möykyiltä.**
 *      `validateLevel` ajetaan generoiduille kentille; käsintehdyille se on
 *      DESIGN.md kohdan 5 mukaan suunnitteluohje. `checkFalling` ei ole
 *      suunnitteluohje vaan turvaehto, joten se luetaan täältä jokaisesta
 *      kentästä johon möykky on asetettu.
 *   3. **möykyn alla oleva tiili oikeasti hajoaa.** Tämä on se ehto jota
 *      `rules.js` **ei voi** kysyä eikä kysy, ja se on se joka olisi mennyt
 *      hiljaa pieleen: salaisuutta kätkevä tiili ei hajoa millään koolla
 *      (`bumpTile`) eikä potkaistulle kuorelle (`smashAhead`) — se muuttuu
 *      käytetyksi lohkoksi. Sen päällä möykky ei voi koskaan pudota, eli se
 *      olisi koriste. Mitattu 4-2:n omasta rivistä: neljästä tiilestä
 *      **yksi kätkee jotain**, joten oikeita sarakkeita on kolme.
 *   4. **kanonisointi lukee sen kiinteänä.** `tools/originality.mjs` taittaa
 *      tuntemattoman merkin ilmaksi, joten `C`:n sisältävä kenttä
 *      verrattaisiin korpukseen reikä keskellä. Väite on käyttäytymisestä eikä
 *      rivin sisällöstä: rakennetaan ikkuna jossa on yksi `C` ja kysytään
 *      osuuko se ikkunaan jossa samassa kohdassa on kiveä.
 *
 * Ja lopuksi kaksi mittausta moottorista, oikeista kentistä eikä koekentästä,
 * koska sijoituksen arvo on juuri siinä että se on kentässä: ensiesittely
 * jossa kuori tekee työn ja pelaaja katsoo vierestä (4-2), ja toinen
 * kohtaaminen jossa pelaaja tekee sen itse ja maksaa siitä jos jää seisomaan
 * (4-F). Jälkimmäinen on pari eikä yksi väite — sama puski, kaksi eri
 * jatkoa — koska "ehtii pois jos lähtee heti" ei tarkoita mitään ilman sitä
 * toista puoliskoa.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const { getLevel, levelIds } = await import('../src/data/levels.js');
  const { brickHides } = await import('../src/core/secrets.js');
  const { validateLevel } = await import('../src/data/rules.js');
  const jump = JSON.parse(await readFile(join(ROOT, 'tools/jump-budget.json'), 'utf8'));

  /* Jokainen möykky pelissä: kenttä, sarake, rivi ja se merkki jonka päällä se
   * seisoo. Luetaan kootusta ruudukosta eikä palikkatiedostosta, koska palikan
   * sarake ei ole kentän sarake ja ehto 3 on kentän sarakkeesta. */
  const lumps = [];
  for (const id of levelIds()) {
    const rows = getLevel(id).rows;
    for (let y = 0; y < rows.length; y++) {
      for (let x = 0; x < rows[y].length; x++) {
        if (rows[y][x] !== 'C') continue;
        lumps.push({
          id,
          x,
          y,
          below: y + 1 < rows.length ? rows[y + 1][x] : '#',
          above: y > 0 ? rows[y - 1][x] : ' ',
        });
      }
    }
  }
  const inLevels = [...new Set(lumps.map((l) => l.id))];

  expect('möykky on jossain kentässä',
    lumps.length > 0,
    lumps.length
      ? `${lumps.length} kpl ${inLevels.length} kentässä: `
        + lumps.map((l) => `${l.id}@${l.x},${l.y}`).join(' ')
      : `0 kpl ${levelIds().length} kentässä — laatta on olemassa muttei missään`);

  /* Ehdot 1-3 luetaan rules.js:n omasta koodista eikä kirjoiteta uudestaan:
   * `checkFalling`in huomautukset alkavat aina sanoilla "falling tile". */
  {
    const problems = [];
    for (const id of inLevels) {
      for (const p of validateLevel(getLevel(id).rows, jump)) {
        if (/falling tile/i.test(p)) problems.push(`${id}: ${p}`);
      }
    }
    expect('rules.js:n kolme sääntöä pitävät jokaisesta pelin möykystä',
      problems.length === 0,
      problems.length ? problems.join(' — ')
        : `${lumps.length} möykkyä, ${inLevels.length} kenttää, 0 huomautusta `
          + `(tuet: ${lumps.map((l) => JSON.stringify(l.below)).join(' ')})`);
  }

  /* Ehto 4: tuki on tiili joka hajoaa. `brickHides` on paikan puhdas funktio,
   * joten tämä on kentän sarakkeesta eikä palikan. */
  {
    const stuck = lumps.filter((l) => l.below === 'B' && brickHides(l.x, l.y + 1));
    const brickLumps = lumps.filter((l) => l.below === 'B');
    expect('möykyn alla oleva tiili on tiili joka oikeasti hajoaa',
      stuck.length === 0 && brickLumps.length > 0,
      stuck.length
        ? stuck.map((l) => `${l.id}@${l.x},${l.y}: tuki kätkee "${brickHides(l.x, l.y + 1)}"`).join(' — ')
        : brickLumps.length
          ? `${brickLumps.length}/${lumps.length} möykkyä tiilen päällä, 0 salaisuuden päällä`
          : 'yksikään möykky ei seiso tiilen päällä — mikään ei voi pudottaa sitä');
  }

  /* Ja se toinen puolisko samasta ehdosta: että mittaus osaisi huomata vian.
   * Punainen ilman että mitään rikotaan — luetaan sama rivi siitä kentästä
   * jossa möykky on, ja kysytään mitä sen muut tiilet kätkevät.
   *
   * **Kenttä vaihdettiin 4-F:stä 4-2:een, ja se on uudelleenmittaus eikä
   * maun muutos.** `brickSecret` on paikan hajautus, joten kun kootun kentän
   * rivimäärä kasvoi viidestätoista kuuteentoista, jokainen tiili sai uuden
   * arvan: 4-F:n möykkyrivillä oli ennen kolme kätkevää tiiltä neljästä ja
   * nyt niitä on nolla — koko kentässä ei ole yhtään. 4-2:n möykky seisoo
   * samanlaisella rivillä, ja siellä neljästä tiilestä yksi kätkee. Väite on
   * sama kuin ennen; vain se paikka josta se voidaan mitata siirtyi. */
  {
    const lump = lumps.find((l) => l.id === '4-2');
    const rows = getLevel('4-2').rows;
    const row = lump ? rows[lump.y + 1] : '';
    const bricks = [];
    for (let x = 0; x < row.length; x++) if (row[x] === 'B') bricks.push(x);
    const near = bricks.filter((x) => Math.abs(x - (lump ? lump.x : -99)) <= 4);
    const hiding = near.filter((x) => brickHides(x, lump.y + 1));
    expect('salaisuutta kätkevä tiili tunnistetaan, eli ehto ei ole tyhjä',
      !!lump && near.length > 1 && hiding.length > 0,
      lump
        ? `4-2 rivi ${lump.y + 1}: `
          + `${near.map((x) => `${x}=${brickHides(x, lump.y + 1) ? 'kätkee' : 'hajoaa'}`).join(' ')}`
          + ` — möykky on sarakkeessa ${lump.x}`
        : '4-2:ssa ei ole möykkyä');
  }

  /* Ehto 5: kanonisointi. Käyttäytyminen eikä rivin sisältö — rakennetaan
   * yksi 8 sarakkeen ikkuna jossa on möykky, ja korpuksen puolelta sama ikkuna
   * jossa samassa kohdassa on kiveä. Jos `C` taittuisi ilmaksi, avaimet eivät
   * osuisi ja luku olisi 0. */
  {
    const { hitsAgainst, WINDOW } = await import('./originality.mjs');
    const H = 14;
    /* Kolikko mukaan, ja se on `arrangement`-säännön takia: ikkuna jossa on
     * vain maata ja ilmaa ei ole sommitelma eikä sitä verrata lainkaan
     * (`originality.mjs`). Möykyn kanonisointia ei siis voi mitata pelkällä
     * möykyllä — ikkunassa on oltava jotain sijoitettua, ja kolikko on
     * kevyin mahdollinen. */
    const at = (ch) => {
      const rows = [];
      for (let y = 0; y < H; y++) {
        rows.push(y === 5 ? `   ${ch}  o ` : ' '.repeat(WINDOW));
      }
      return rows;
    };
    /* Korpuksen kanonisointi: kiinteä on 'X', kolikko 'o', kaikki muu '-'.
     * Avain on `windows()`in muoto — sarakkeet pystyssä, putkella eroteltuina. */
    const cols = [];
    for (let x = 0; x < WINDOW; x++) {
      let col = '';
      for (let y = 0; y < H; y++) {
        col += (y === 5 && x === 3) ? 'X' : (y === 5 && x === 6) ? 'o' : '-';
      }
      cols.push(col);
    }
    const index = { keys: new Set([cols.join('|')]), files: 1 };
    const solid = hitsAgainst(index, at('C'));
    const air = hitsAgainst(index, at(' '));
    expect('möykky kanonisoituu kiinteäksi eikä ilmaksi alkuperäisyystarkistuksessa',
      solid === 1 && air === 0,
      `möykyllä ${solid} osumaa, ilmalla ${air} — kiveä vastaan, ${WINDOW} sarakkeen ikkuna`);
  }

  /* Viisi kopiota `SOLID`ista, verrattuna merkkijonoina — sama järjestely kuin
   * `SINK`illa, ja tämä on se portti joka olisi huomannut aukon itse. Kopio
   * `generator.js`:ssä on nykyään kuollutta koodia (nimeä ei lueta siellä),
   * mikä tekee siitä puhtaan väitteen ja siis juuri sellaisen jota portin
   * kuuluu vahtia.
   *
   * **Kopioita oli viisi ja tämä luki kolme**, ja se on sama vika kuin se jota
   * tämän erän uusi portti korjaa: käsin kirjoitettu lista jonka ulkopuolella
   * on juuri se tapaus jolla on väliä. `tools/curriculum.mjs` oli päivitetty
   * mutta tarkistamaton, ja `tools/difficulty.mjs` ei ollut kumpaakaan — eli
   * vaikeusmittari luki möykyn *ei-kiinteänä*, ja lattiarivillä lepäävä möykky
   * olisi mitattu pohjattomana sarakkeena. Tänään se ei muuta yhdenkään kentän
   * lukua (kummankin möykyn rivi on 8, ja `lethalCol` lukee rivit 13-14),
   * mutta se on väärä vastaus joka odottaa oikeaa kysymystä. */
  {
    /* Koko rivi rivin alusta puolipisteeseen, eikä `[^\]]*` niin kuin `SINK`in
     * vieressä: `SOLID`in jäsenistä yksi **on** `']'`, joten hakasulkeen
     * kieltävä luokka katkaisee osuman kesken joukon ja vertaisi kahden
     * tiedoston alkupäitä toisiinsa. Se olisi vihreä portti joka ei mittaa
     * loppua — ja loppu on juuri se pää johon uusi merkki lisätään. */
    const line = /^const SOLID = new Set\(.+\);$/m;
    const read = async (f) => ((await readFile(join(ROOT, f), 'utf8')).match(line) || [])[0] || '';
    const files = ['src/data/rules.js', 'src/data/generator.js', 'tools/originality.mjs',
      'tools/curriculum.mjs', 'tools/difficulty.mjs'];
    const found = await Promise.all(files.map(read));
    const same = found.every((s) => s && s === found[0]);
    const missing = files.filter((f, i) => !found[i].includes("'C'"));
    expect('SOLIDin viisi kopiota ovat sanasanaisesti samat ja tuntevat möykyn',
      same && missing.length === 0,
      same && !missing.length
        ? `${files.length} kopiota, ${found[0].length} merkkiä, sisältää 'C'`
        : `${missing.length ? `'C' puuttuu: ${missing.join(', ')}` : ''}`
          + `${same ? '' : ` — rivit eroavat: ${files.filter((f, i) => found[i] !== found[0]).join(', ')}`}`);
  }

  /* --- ja sitten moottorista, oikeista kentistä --- */
  /*
   * KOLME MITTAUSTA, JA NE MITATAAN NIISTÄ KENTISTÄ JOTKA PELI TOIMITTAA.
   *
   * Koekenttä vastaa kysymykseen "toimiiko laatta". Tämä lohko kysyy
   * "toimiiko *sijoitus*", ja se on eri kysymys: se koskee sitä riviä, sitä
   * saraketta ja sitä lattiaa jonka pelaaja oikeasti kohtaa.
   */
  const M = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const { ShellGuy } = await import('/src/entities/enemies.js');
    const { MAX_WALK } = await import('/src/entities/player.js');
    const { T } = await import('/src/gfx/tiles.js');
    const game = window.sfb3;

    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const scene = (id, level) => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: level ? { type: 'shroom', level } : null,
        reserve: null, world: 3, node: 'w4-2', cleared: {}, worldsOpen: 8, cards: [],
      };
      game.finishLevel = () => {};
      const s = new LevelScene(game, id);
      game.setScene(s);
      /* Viholliset ja vaarat pois: mitattava on möykky eikä se mikä sattuu
       * seisomaan viereisessä sarakkeessa. */
      s.entities = s.entities.filter((e) => e.kind !== 'enemy' && e.kind !== 'hazard');
      s.time = 9999;
      s.clockStopped = true;
      return s;
    };
    const findLump = (s) => {
      for (let y = 0; y < s.h; y++) {
        for (let x = 0; x < s.w; x++) if (s.grid[y][x] === T.LUMP) return { x, y };
      }
      return null;
    };
    /* Lattiarivi luetaan ruudukosta eikä kirjoiteta tähän: kaksi kenttää, kaksi
     * eri riviä (4-2 on kolmikaistainen), ja sama koe molemmille. */
    const floorUnder = (s, at) => {
      let y = at.y + 1;
      while (y < s.h && !'#X'.includes(s.grid[y][at.x])) y++;
      return y;
    };
    const stand = (s, at, x) => {
      const p = s.player;
      p.x = x * 16;
      p.y = floorUnder(s, at) * 16 - p.h;
      p.vx = 0;
      p.vy = 0;
      return p;
    };
    const out = {};

    /* --- 1. ensiesittely 4-2: puski, putoaminen, paluu ------------------ */
    {
      const s = scene('4-2', 1);
      const i = mkInput();
      const at = findLump(s);
      const p = stand(s, at, at.x);
      const floor = floorUnder(s, at);
      s.bumpTile(at.x, at.y + 1, p);
      const broke = s.tileAt(at.x, at.y + 1) !== T.BRICK;
      let left = 0;
      let landed = 0;
      for (let n = 0; n < 120; n++) {
        s.update(i);
        if (!left && s.tileAt(at.x, at.y) !== T.LUMP) left = n + 1;
        if (!landed && s.tileAt(at.x, floor - 1) === T.LUMP) landed = n + 1;
      }
      let home = 0;
      for (let n = 0; n < 400 && !home; n++) {
        s.update(i);
        if (s.tileAt(at.x, at.y) === T.LUMP && s.tileAt(at.x, floor - 1) !== T.LUMP) home = n + 1;
      }
      out.intro = {
        at: `${at.x},${at.y}`, floor, broke, left, landed, home,
      };
    }

    /* --- 2. pieni pelaaja ei voi pudottaa sitä itselleen ---------------- */
    /* Tämä on koko ensiesittelyn turvaperuste rakenteena: `bumpTile` hajottaa
     * tiilen vain kun `player.big`, joten voimatasolla 0 möykky ei liiku, ja
     * osuma maksaa siis aina koon eikä koskaan henkeä. */
    {
      const s = scene('4-2', 0);
      const i = mkInput();
      const at = findLump(s);
      const p = stand(s, at, at.x);
      const big = !!p.big;
      s.bumpTile(at.x, at.y + 1, p);
      for (let n = 0; n < 90; n++) s.update(i);
      out.small = {
        big,
        power: p.powerLevel,
        brick: s.tileAt(at.x, at.y + 1),
        lump: s.tileAt(at.x, at.y),
      };
    }

    /* --- 3. toinen kohtaaminen 4-F: sama puski, kaksi jatkoa ------------ */
    /*
     * Ero näiden kahden ajon välillä on **yksi luku**: se vauhti jolla pelaaja
     * on lohkorivin alla sillä hetkellä kun tiili hajoaa. Nolla on se joka jää
     * seisomaan; `MAX_WALK` on pelin oma kävelykatto, eli hitain mahdollinen
     * "oli jo matkalla" — juoksukatto olisi tehnyt väitteestä helpomman.
     */
    {
      const bump = (vx) => {
        const s = scene('4-F', 1);
        const i = mkInput();
        const at = findLump(s);
        const p = stand(s, at, at.x);
        p.vx = vx;
        const before = p.powerLevel;
        s.bumpTile(at.x, at.y + 1, p);
        const broke = s.tileAt(at.x, at.y + 1) !== T.BRICK;
        for (let n = 0; n < 90; n++) {
          if (vx) {
            i.held = blank();
            i.held.right = true;
            i.pressed = blank();
          }
          s.update(i);
        }
        return {
          at: `${at.x},${at.y}`,
          broke,
          before,
          after: p.powerLevel,
          moved: Math.round((p.x / 16 - at.x) * 10) / 10,
        };
      };
      out.stay = bump(0);
      out.leave = bump(MAX_WALK);
      out.walk = MAX_WALK;
    }

    /* --- 4. potkaistun kuoren suunta, mitattuna ------------------------- */
    /*
     * Kolmas keino irrottaa möykky on potkaistu kuori, ja se on mitattu tässä
     * eikä oletettu. Koekenttä eikä kenttä: yhdessäkään toimitetussa
     * kentässä ei ole kuorta möykyn vieressä, ja syy siihen on tämän
     * mittauksen tulos.
     */
    {
      const dir = (d) => {
        const s = scene('4-2', 1);
        const i = mkInput();
        const at = findLump(s);
        const floor = floorUnder(s, at);
        /* Oma pilari kaukana kaikesta: tiili lattialla ja möykky sen päällä,
         * eli tasan se korkeus jolla liukuva kuori kulkee. */
        const px = at.x + 20;
        s.setTile(px, floor - 1, T.BRICK);
        s.setTile(px, floor - 2, T.LUMP);
        s.player.x = (px - 12 * d) * 16;
        s.player.y = (floor - 1) * 16 - s.player.h;
        const sh = new ShellGuy(s, (px - 6 * d) * 16, (floor - 1) * 16 - 24);
        sh.active = true;
        sh.alwaysActive = true;
        s.entities.push(sh);
        sh.kick(d);
        let broke = 0;
        for (let n = 0; n < 120; n++) {
          s.update(i);
          if (!broke && s.tileAt(px, floor - 1) !== T.BRICK) broke = n + 1;
        }
        return broke;
      };
      out.shell = { right: dir(1), left: dir(-1) };
    }
    return out;
  });

  expect('ensiesittely 4-2: tiili hajoaa, möykky lähtee ja se palaa kotiin',
    M.intro.broke && M.intro.left > 0 && M.intro.landed > 0 && M.intro.home > 0,
    `möykky ${M.intro.at}, lattia rivillä ${M.intro.floor}: tiili hajosi ${M.intro.broke}, `
    + `lähti framella ${M.intro.left}, laskeutui framella ${M.intro.landed}, `
    + `kotona ${M.intro.home} framea myöhemmin`);

  expect('voimatasolla 0 möykkyä ei saa liikkeelle, eli se ei voi maksaa henkeä',
    !M.small.big && M.small.brick === 'B' && M.small.lump === 'C' && M.small.power === 0,
    `pieni pelaaja: iso ${M.small.big}, tiili "${M.small.brick}", möykky "${M.small.lump}", `
    + `voima ${M.small.power} — 90 framea puskun jälkeen`);

  expect('toinen kohtaaminen 4-F: paikallaan jäänyt maksaa, jo liikkeellä ollut ei',
    M.stay.broke && M.stay.after < M.stay.before
      && M.leave.broke && M.leave.after === M.leave.before,
    `möykky ${M.stay.at}: paikallaan ${M.stay.before} → ${M.stay.after}, `
    + `kävelyvauhdissa (${M.walk} px/frame) ${M.leave.before} → ${M.leave.after} `
    + `ja ${M.leave.moved} laattaa sivuun`);

  /*
   * LÖYDETTY, EI KORJATTU — ja se on tässä numerona eikä muistiinpanona.
   *
   * `ShellGuy.smashAhead` lukee suuntansa `this.vx`:stä, mutta se kutsutaan
   * vasta kun `moveSideways()` on osunut seinään — ja `moveX` **nollaa
   * vauhdin osumassa** (`src/level/physics.js`, sama rivi jonka kimmokkeen
   * kommentti `enemies.js`:ssä jo mainitsee). Nolla ei ole suurempi kuin
   * nolla, joten haara on aina se vasen: oikealle liukuva kuori tutkii sen
   * sarakkeen josta se juuri tuli. Vasemmalle liukuva osuu oikeaan
   * sarakkeeseen vahingossa, koska `x - 1` on törmäyksen jälkeen seinän oma
   * sarake.
   *
   * Korjaus on yksi merkki `src/entities/enemies.js`:ssä (`this.facing`
   * `this.vx`:n sijaan), ja **se tiedosto kuuluu tässä erässä toiselle**.
   * Siksi tämä on väite siitä mitä mitattiin eikä siitä mitä toivotaan: se
   * pysyy vihreänä myös sen jälkeen kun oikea suunta alkaa toimia, ja
   * yksityiskohta kertoo kumpi suunta oli mitä.
   */
  expect('potkaistu kuori pudottaa möykyn, ja suunta on mitattu eikä oletettu',
    M.shell.left > 0 || M.shell.right > 0,
    `oikealle ${M.shell.right ? `framella ${M.shell.right}` : 'ei koskaan'}, `
    + `vasemmalle ${M.shell.left ? `framella ${M.shell.left}` : 'ei koskaan'} `
    + '— smashAhead lukee suunnan vx:stä, jonka moveX on juuri nollannut');

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- möykky kentissä: loppu ---- */

/*
 * JÄÄ MOOTTORISSA, JA SE SOLMU JOKA PITÄÄ SÄÄNNÖN TOTENA.
 *
 * `ICE_BRAKE` (`src/data/rules.js`) on luku joka on kopioitu mittauksesta:
 * `tools/measure-braking.mjs` sanoo että jäällä vastaan kääntyminen syö
 * P-nopeudesta 68 px eli 4,25 laattaa, ja sääntö pyöristää sen viiteen. Kopioitu
 * luku on luku joka voi vanhentua, ja tämä on se tarkistus joka ei anna sen
 * vanhentua hiljaa: jos joku säätää `SURFACES.ice.grip`iä, liukumatka muuttuu
 * moottorissa ja `ICE_BRAKE` lakkaa kattamasta sitä — **ja silloin kaatuu tämä
 * eikä kenttä.**
 *
 * Mitataan samalla runwaylla ja samalla vauhdinotolla kuin `measure-braking`,
 * koska kaksi eri tapaa mitata sama asia on kaksi eri lukua odottamassa
 * erkanemistaan. Voimataso 0, koska sillä on pienin kitka eli pisin liuku — se
 * on se tapaus jota säännön on katettava.
 */
{
  const ICE = await page.evaluate(async () => {
    const { LevelScene } = await import('/src/scenes/level.js');
    const game = window.sfb3;
    game.finishLevel = () => {};
    const blank = () => ({
      left: false, right: false, up: false, down: false, jump: false, run: false,
      start: false, mute: false, quicksave: false, quickload: false, slot: false,
    });
    const mkInput = () => ({
      held: blank(), pressed: blank(), released: blank(), consume(a) { this.pressed[a] = false; },
    });
    const step = (s, i) => { s.update(i); i.pressed = blank(); };

    /** Tasainen runway yhdestä merkistä, voimataso 0. */
    const runway = (floor) => {
      game.state = {
        lives: 5, coins: 0, score: 0, power: { type: null, level: 0 },
        reserve: null, world: 0, node: 'w1-1', cleared: {}, worldsOpen: 1, cards: [],
      };
      const s = new LevelScene(game, '1-1');
      for (let y = 0; y < s.h - 2; y++) s.grid[y] = s.grid[y].map(() => ' ');
      for (let y = s.h - 2; y < s.h; y++) s.grid[y] = s.grid[y].map(() => floor);
      s.entities = s.entities.filter((e) => e.kind === 'player');
      s.goal = null;
      s.time = 400;
      return s;
    };
    /** Vauhtiin, sitten `action`, ja kuinka pitkälle se vielä vei. */
    const brake = (floor, action, pSpeed) => {
      const s = runway(floor);
      const p = s.player;
      const i = mkInput();
      for (let f = 0; f < 40; f++) step(s, i);
      i.held.right = true;
      i.held.run = true;
      for (let f = 0; f < (pSpeed ? 420 : 90); f++) step(s, i);
      const v0 = p.vx;
      const x0 = p.x;
      i.held.right = false;
      i.held.run = false;
      if (action === 'reverse') i.held.left = true;
      let f = 0;
      while (p.vx > 0.0001 && f < 3000) { step(s, i); f++; }
      return { v0: +v0.toFixed(2), px: Math.round(p.x - x0) };
    };
    return {
      stoneRun: brake('#', 'release', false),
      iceRun: brake('I', 'release', false),
      iceReverseP: brake('I', 'reverse', true),
      stoneReverseP: brake('#', 'reverse', true),
    };
  });

  const { RULE_CONSTANTS } = await import('../src/data/rules.js');
  const brakeTiles = ICE.iceReverseP.px / 16;

  /* 1. Jää liu'uttaa oikeasti, eli laatta ei ole pelkkä kuva. */
  const slides = ICE.iceRun.px > ICE.stoneRun.px * 1.5;
  report.checks.push({
    name: 'jäälaatta liu\'uttaa pelaajaa, kivilaatta ei',
    ok: slides,
    detail: `voimataso 0, juoksuvauhti ${ICE.iceRun.v0}: jäällä ${ICE.iceRun.px} px, `
      + `kivellä ${ICE.stoneRun.px} px (${(ICE.iceRun.px / ICE.stoneRun.px).toFixed(1)}x)`,
  });
  if (!slides) report.failures.push('jäälaatan päällä liukuu yhtä vähän kuin kivellä');

  /* 2. Ja se luku jonka validaattori uskoo, kattaa sen mitä moottori tekee. */
  const covers = brakeTiles <= RULE_CONSTANTS.ICE_BRAKE;
  report.checks.push({
    name: 'ICE_BRAKE kattaa mitatun jarrutusmatkan jäällä',
    ok: covers,
    detail: `P-nopeudesta vastaan kääntyminen ${ICE.iceReverseP.px} px = `
      + `${brakeTiles.toFixed(2)} laattaa, ICE_BRAKE ${RULE_CONSTANTS.ICE_BRAKE}`,
  });
  if (!covers) {
    report.failures.push(`ICE_BRAKE ${RULE_CONSTANTS.ICE_BRAKE} on pienempi kuin mitattu `
      + `${brakeTiles.toFixed(2)} laattaa — aja tools/measure-braking.mjs ja korjaa rules.js`);
  }

  /* 3. Kiihdytys ei ole jäällä eri — se on `SURFACES`in `grip`in koko rajaus, ja
   *    se on se lause jonka varassa `tools/playable.mjs`:n todistus on. Mitataan
   *    siitä päästä josta se näkyy: vauhdinoton jälkeen vauhdin on oltava sama. */
  const sameSpeed = Math.abs(ICE.iceRun.v0 - ICE.stoneRun.v0) < 0.01;
  report.checks.push({
    name: 'jää ei hidasta kiihtymistä, vain pysähtymistä',
    ok: sameSpeed,
    detail: `90 framea oikeaa pohjassa: jäällä ${ICE.iceRun.v0}, kivellä ${ICE.stoneRun.v0}`,
  });
  if (!sameSpeed) {
    report.failures.push('jää muuttaa kiihtyvyyttä — hyppybudjetti ja botin todistus '
      + 'on mitoitettu sillä oletuksella ettei se muuta');
  }
}

/* ---- kuvaefektit: suunnattu tärinä ja palettisiirto ---- */
/*
 * Kaksi jonossa ollutta kuvaefektiä, ja ne ovat samassa erässä siksi että ne
 * ovat sama kysymys kahdessa muodossa: **mistä pelaaja tietää mitä juuri
 * tapahtui, silloin kun se tapahtuu koko ruudulle eikä yhdelle oliolle.**
 *
 * 1. **Tärinällä on suunta.** Yksi ympyrä kaikelle tarkoittaa että maahanisku,
 *    iskuaalto ja jättiläisen askel näyttävät samalta — ja kaksi samannäköistä
 *    "jotain tapahtui" -signaalia opettavat lukemaan väärää (DESIGN.md kohta 8,
 *    sama perustelu joka on jo kirjattu maahaniskun ja pomoäänten kohdalle).
 *    Pystyisku tärisyttää pystyyn, lattiaa pitkin lähtevä aalto sivuttain.
 * 2. **Palettisiirto on pelin puhetta, ei kuvaputken.** Siksi se ei asu
 *    varjostimessa vaan yhdessä `multiply`-vedossa jonka molemmat ajotiet
 *    piirtävät samalla koodilla — ja siksi se piirtyy myös kun kuvaefektit on
 *    kytketty pois. Efektin voi sammuttaa; tiedon ei.
 *
 * Väitteet alla on kirjoitettu niin että jokainen mittaa lukua eikä
 * olemassaoloa: "tärinä on pystysuuntainen" on `maxX === 0`, ja "tähti ei
 * välky" on kaksi lukua joilla on lähde — WCAG 2.3.1:n välähdyskynnys, alle
 * kolme välähdystä sekunnissa ja alle 10 % suhteellisen luminanssin muutos.
 * Se kynnys on tässä pelissä oikea kysymys eikä muodollisuus: peliä pelaa
 * lapsi, ja koko ruudun sykkiminen on juuri se asia jota kynnys koskee.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  /* --- 1. tärinän suunta, ja kuka sen valitsee --- */
  /*
   * Neljä mittausta yhdessä, koska suunta ilman valintasääntöä ei ole sääntö:
   * kaksi tärähdystä osuu samaan frameen aina kun pomo laskeutuu ja aalto
   * lähtee, ja silloin jonkun on voitettava. Sääntö on **kovempi ohjaa** —
   * sama järjestys jolla `shakeAmp` itse on aina valittu (`Math.max`) — ja
   * tasapeli palaa ympyrään, koska kaksi yhtä kovaa iskua eri suunnista *on*
   * ympyrä.
   */
  {
    const out = await page.evaluate(async () => {
      try {
        const { LevelScene } = await import('/src/scenes/level.js');
        const game = window.sfb3;
        game.state = {
          lives: 5, coins: 0, score: 0, power: { type: null, level: 0 }, reserve: null,
          world: 0, node: 'w1-1', cleared: {}, worldsOpen: 8, cards: [],
        };
        game.finishLevel = () => {};
        const scene = new LevelScene(game, '1-1');

        const sweep = (amount, axis) => {
          scene.shakeAmp = 0;
          scene.shakeAxis = 'both';
          scene.shake(amount, axis);
          let maxX = 0;
          let maxY = 0;
          for (let t = 0; t < 120; t++) {
            scene.tick = t;
            const o = scene.shakeOffset();
            maxX = Math.max(maxX, Math.abs(o.x));
            maxY = Math.max(maxY, Math.abs(o.y));
          }
          return { maxX, maxY };
        };
        const both = sweep(6, 'both');
        const up = sweep(6, 'y');
        const side = sweep(6, 'x');

        const set = (calls) => {
          scene.shakeAmp = 0;
          scene.shakeAxis = 'both';
          for (const [amount, axis] of calls) scene.shake(amount, axis);
          return scene.shakeAxis;
        };
        const louder = set([[2, 'y'], [5, 'x']]);
        const quieter = set([[5, 'x'], [1, 'y']]);
        const tie = set([[3, 'y'], [3, 'x']]);

        /* Ja kun tärinä on vaimennut, suunta on taas oletus: seuraava isku ei
         * peri edellisen suuntaa. Vaimeneminen tapahtuu `update`issa, joten se
         * ajetaan sitä kautta eikä nollaamalla kenttä käsin. */
        const blank = () => ({
          left: false, right: false, up: false, down: false, jump: false, run: false,
          start: false, mute: false, quicksave: false, quickload: false, slot: false,
        });
        const input = {
          held: blank(), pressed: blank(), released: blank(), consume() {},
        };
        game.setScene(scene);
        scene.shake(6, 'x');
        for (let i = 0; i < 40 && scene.shakeAmp > 0; i++) scene.update(input);
        const settled = { amp: scene.shakeAmp, axis: scene.shakeAxis };

        return { both, up, side, louder, quieter, tie, settled };
      } catch (e) { return { error: String(e && e.message || e) }; }
    });

    expect('pystyisku tärisyttää pystyyn eikä sivuun, ja sivuisku toisin päin',
      !out.error && out.up.maxX === 0 && out.up.maxY >= 5
      && out.side.maxY === 0 && out.side.maxX >= 5,
      out.error || `pysty ${out.up.maxX}x/${out.up.maxY}y, `
        + `sivu ${out.side.maxX}x/${out.side.maxY}y`);
    /* Vanha muoto on yhä oletus: leveämpi kuin korkea, koska se on se tärinä
     * jota kaikki nykyiset kutsupaikat ovat aina saaneet. */
    expect('suunnaton tärinä on yhä se leveä ympyrä jota se on aina ollut',
      !out.error && out.both.maxX > out.both.maxY && out.both.maxY > 0,
      out.error || `${out.both.maxX}x/${out.both.maxY}y`);
    expect('kovempi isku valitsee suunnan, heikompi ei käännä sitä, tasapeli on ympyrä',
      !out.error && out.louder === 'x' && out.quieter === 'x' && out.tie === 'both',
      out.error || `kovempi "${out.louder}", heikompi "${out.quieter}", tasapeli "${out.tie}"`);
    expect('vaimennut tärinä ei jätä suuntaansa seuraavalle iskulle',
      !out.error && out.settled.amp === 0 && out.settled.axis === 'both',
      out.error || `amp ${out.settled.amp}, suunta "${out.settled.axis}"`);
  }

  /* --- 2. mikä tärisee mihinkin suuntaan --- */
  /*
   * Suunta ilman kutsupaikkoja on vain parametri. Nämä kolme ovat ne jotka
   * ROADMAPissa nimettiin — maahanisku, pomon laskeutuminen ja iskuaalto — ja
   * kukin ajetaan sitä kautta josta se pelissäkin lähtee.
   *
   * Pomon laskeutuminen pakotetaan kentällä eikä odottamalla: hyppy tulee
   * ajastimesta ja putoamisnopeus painovoimasta, joten "odota kunnes se
   * sattuu" olisi testi joka mittaa satunnaislukugeneraattoria. Pakotettu on
   * `y`, `vy` ja `jumpTimer` — eli tasan se tila jossa pomo *on* juuri ennen
   * laskeutumista — ja loppu on pomon omaa koodia.
   */
  {
    const out = await page.evaluate(async () => {
      try {
        const { LevelScene } = await import('/src/scenes/level.js');
        const game = window.sfb3;
        const state = () => {
          game.state = {
            lives: 5, coins: 0, score: 0, power: { type: 'shroom', level: 3 }, reserve: null,
            world: 0, node: 'w1-1', cleared: {}, worldsOpen: 8, cards: [],
          };
          game.finishLevel = () => {};
        };
        const tap = (scene) => {
          const heard = [];
          scene.shake = function record(amount, axis = 'both') {
            heard.push({ amount, axis: axis });
            return LevelScene.prototype.shake.call(this, amount, axis);
          };
          return heard;
        };

        /* a) maahanisku: pystyisku, ja se on koko liikkeen nimi. */
        state();
        const l1 = new LevelScene(game, '1-1');
        game.setScene(l1);
        const p = l1.player;
        p.poundFromY = p.y - 120;
        const pound = tap(l1);
        l1.poundImpact(p, 1);

        /* b) pomon laskeutuminen: pystyyn, ja voimakkuus massasta.
         *
         * Pomo asetetaan ensin lattialle omalla painovoimallaan, ja vasta
         * sitten nostetaan ja pudotetaan. Se on tarkempi kuin arvattu lattian
         * korkeus — ja arvattu se olisi, koska pomo aloittaa ilmassa. */
        const drop = (id, scale) => {
          state();
          const scene = new LevelScene(game, id);
          game.setScene(scene);
          const boss = scene.entities.find((e) => e.constructor.name === 'Boss');
          if (!boss) return { missing: id, heard: [] };
          boss.scale = scale;
          boss.targetScale = scale;
          boss.jumpTimer = 999;       // hyppy tulee ajastimesta; tämä on pudotus
          boss.chargeTimer = 999;
          boss.spikeTimer = 99999;    // piikkien varoitus tärisyttää omansa
          const heard = tap(scene);
          for (let i = 0; i < 300 && !boss.onGround; i++) boss.update();
          heard.length = 0;
          boss.y -= 40;
          boss.onGround = false;
          boss.vy = 5.5;
          for (let i = 0; i < 40 && !boss.onGround; i++) boss.update();
          return { heard, landed: boss.onGround };
        };
        const small = drop('4-F', 1);
        const big = drop('4-F', 3);

        /* c) jättiläisen askel: matkaa, ei kelloa — ja vain kun massa on siellä.
         *
         * Piikkiajastin ja hyppy ovat poissa, joten kaikki mitä tässä kuuluu on
         * kävelyä. */
        const walk = (scale) => {
          state();
          const scene = new LevelScene(game, '4-F');
          game.setScene(scene);
          const boss = scene.entities.find((e) => e.constructor.name === 'Boss');
          boss.scale = scale;
          boss.targetScale = scale;
          boss.jumpTimer = 999999;
          boss.chargeTimer = 999999;
          boss.spikeTimer = 999999;
          for (let i = 0; i < 300 && !boss.onGround; i++) boss.update();
          const heard = tap(scene);
          let travel = 0;
          for (let i = 0; i < 240; i++) {
            const was = boss.x;
            boss.update();
            travel += Math.abs(boss.x - was);
          }
          return { heard, travel };
        };
        const heavy = walk(3);
        const light = walk(1);

        /* d) iskuaalto: luuranko hajoaa ja kaksi aaltoa lähtee lattiaa pitkin. */
        state();
        const l6 = new LevelScene(game, '6-F');
        game.setScene(l6);
        const skeleton = l6.entities.find((e) => e.constructor.name === 'Boss');
        const waveShakes = tap(l6);
        skeleton.invuln = 0;
        skeleton.stomp();
        const waves = l6.entities.filter((e) => e.constructor.name === 'Shockwave').length;

        return {
          pound, small, big, heavy, light, waveShakes, waves,
        };
      } catch (e) { return { error: String(e && e.message || e) }; }
    });

    const one = (heard) => (heard && heard.length === 1 ? heard[0] : null);
    const poundHit = one(out.pound);
    expect('maahanisku tärisyttää pystyyn',
      !out.error && !!poundHit && poundHit.axis === 'y' && poundHit.amount > 0,
      out.error || `${(out.pound || []).map((h) => `${h.amount} ${h.axis}`).join(', ') || 'ei tärinää'}`);

    const smallLand = out.error ? null : one(out.small.heard);
    const bigLand = out.error ? null : one(out.big.heard);
    expect('pomon laskeutuminen tärisyttää pystyyn, ja isompi pomo kovempaa',
      !!smallLand && !!bigLand && smallLand.axis === 'y' && bigLand.axis === 'y'
      && bigLand.amount > smallLand.amount,
      out.error || `koko 1 → ${smallLand ? `${smallLand.amount} ${smallLand.axis}` : 'ei tärinää'}, `
        + `koko 3 → ${bigLand ? `${bigLand.amount} ${bigLand.axis}` : 'ei tärinää'}`);

    const steps = out.error ? [] : out.heavy.heard;
    const lightSteps = out.error ? [] : out.light.heard;
    expect('jättiläisen askel tuntuu pystyssä, kevyen pomon askel ei tunnu lainkaan',
      !out.error && steps.length >= 3 && steps.every((h) => h.axis === 'y')
      && lightSteps.length === 0,
      out.error || `koko 3: ${steps.length} askelta ${Math.round(out.heavy.travel)} px:llä, `
        + `koko 1: ${lightSteps.length} askelta ${Math.round(out.light.travel)} px:llä`);
    /* Askel on pienempi kuin laskeutuminen. Sama olio, kaksi tapahtumaa, ja
     * jos ne olisivat yhtä kovia niin kävelevä jättiläinen huutaisi yhtä
     * lujaa kuin putoava. */
    expect('askel jää laskeutumista pienemmäksi',
      !out.error && !!bigLand && steps.length > 0
      && Math.max(...steps.map((h) => h.amount)) < bigLand.amount,
      out.error || `askel ${steps.length ? Math.max(...steps.map((h) => h.amount)) : '-'}, `
        + `laskeutuminen ${bigLand ? bigLand.amount : '-'}`);

    const wave = out.error ? null : one(out.waveShakes);
    expect('lattiaa pitkin lähtevä iskuaalto tärisyttää sivusuuntaan',
      !!wave && wave.axis === 'x' && out.waves >= 2,
      out.error || `${(out.waveShakes || []).map((h) => `${h.amount} ${h.axis}`).join(', ') || 'ei tärinää'}`
        + `, aaltoja ${out.waves}`);
  }

  /* --- 3. palettisiirto: yksi veto, yksi frame, ja HUD ulkopuolella --- */
  /*
   * Neljä väitettä samasta yhdestä vedosta:
   *
   *   - se **kertoo** kuvan värillä (`multiply`), eli punainen välähdys vie
   *     vihreän ja sinisen eikä lisää valoa. Palettisiirto on nimenomaan
   *     siirto: sama kuva toisessa värissä, ei toinen kuva.
   *   - se **ei koske HUDiin**, samasta syystä kuin hehku, kuumuus ja huurre
   *     eivät koske: numerot ovat pelin puhetta pelaajalle, ja punaiseksi
   *     värjätty pistelukema tarkoittaisi jotain mitä se ei tarkoita.
   *   - se **elää yhden framen**. Sama sääntö kuin maailman valoilla: jos
   *     siirto jäisi voimaan, niin edellisen kentän vahinkovälähdys palaisi
   *     seuraavan kentän ensimmäiselle framelle.
   *   - se **piirtyy vaikka kuvaefektit on pois**. Tämä on koko syy siihen
   *     ettei se ole varjostimessa: `7` sammuttaa kuvaputken, ja kuvaputken
   *     sammuttaminen ei saa sammuttaa sitä merkkiä joka kertoo osumasta.
   */
  {
    const out = await page.evaluate(async () => {
      try {
        const { PostFX } = await import('/src/gfx/postfx.js');
        const fx = Object.create(PostFX);
        const c = document.createElement('canvas');
        c.width = 320;
        c.height = 240;
        const g = c.getContext('2d');
        const paint = () => {
          g.fillStyle = '#808080';
          g.fillRect(0, 0, 320, 240);
        };
        paint();
        fx.source = c;
        fx.mode = '2d';
        fx.preset = 'pois';            // kuvaefektit pois: vain siirto saa näkyä
        const at = (x, y) => Array.from(g.getImageData(x, y, 1, 1).data).slice(0, 3);

        const set = fx.setTint(255, 64, 64, 0.5);
        fx.apply(g);
        const play = at(160, 100);
        const hud = at(160, 232);
        const left = fx.tint;
        const shown = fx.shownTint;

        /* Toinen frame ilman uutta siirtoa: kuvan pitää pysyä täsmälleen
         * siinä mihin se jäi, eikä värjäytyä toiseen kertaan. */
        fx.apply(g);
        const again = at(160, 100);

        /* Ja kolmas, jossa siirto asetetaan uudestaan: nyt sen pitää purra. */
        paint();
        fx.setTint(255, 64, 64, 0.5);
        fx.apply(g);
        const third = at(160, 100);

        /* Katto: pimeäksi ei värjätä, olipa pyyntö mikä tahansa. */
        paint();
        fx.setTint(0, 0, 0, 5);
        const clamped = fx.tint ? fx.tint.amount : null;
        fx.apply(g);
        const dark = at(160, 100);

        /* Ja nollan kokoinen siirto ei ole siirto. */
        fx.setTint(255, 0, 0, 0);
        const none = fx.tint;

        /* Toinen veto: lisäys. Sen on tuotava valoa myös sinne missä kuva on
         * tumma — juuri se mitä kerto ei voi tehdä. Tumma ruutu ja kirkas
         * ruutu samalla siirrolla, ja kummankin on noustava. */
        const litFrom = (v) => {
          g.fillStyle = `rgb(${v},${v},${v})`;
          g.fillRect(0, 0, 320, 240);
          fx.setTint(255, 40, 30, 0.42, 'screen');
          fx.apply(g);
          return at(160, 100);
        };
        const litDark = litFrom(32);
        const litBright = litFrom(200);
        /* Ja sama tumma ruutu kerrolla: se ei voi nousta, koska kerto ei tuo
         * valoa. Tässä on koko syy siihen että vetoja on kaksi. */
        g.fillStyle = 'rgb(32,32,32)';
        g.fillRect(0, 0, 320, 240);
        fx.setTint(255, 40, 30, 0.42);
        fx.apply(g);
        const mulDark = at(160, 100);

        /* Ja kolmas kysymys, joka syntyi vasta kun kuninkaan verho (#66) ja
         * tämä siirto tulivat samaan tiedostoon: **kaksi koko ruudun väriä on
         * kaksi merkkiä vain jos ne näyttävät erilaisilta.** Ero on muoto eikä
         * väri — verho on rengas jonka keskus jätetään koskematta, siirto on
         * tasainen. Mitataan keskeltä ja nurkasta. */
        const shape = (paint) => {
          g.fillStyle = '#808080';
          g.fillRect(0, 0, 320, 240);
          /* Verho elää omaa laskuriaan 20 framea, joten se on nollattava tai
           * se olisi mukana myös siinä kuvassa jota verrataan siihen. */
          fx.flashLeft = 0;
          paint();
          fx.apply(g);
          return { mid: at(160, 100), corner: at(4, 4) };
        };
        const curtain = shape(() => fx.flash([255, 80, 80], 20));
        const shifted = shape(() => fx.setTint(255, 40, 30, 0.42, 'screen'));

        return {
          set, play, hud, left, shown, again, third, clamped, dark, none,
          litDark, litBright, mulDark, curtain, shifted,
        };
      } catch (e) { return { error: String(e && e.message || e) }; }
    });

    const [r, gr, b] = out.play || [];
    expect('kertoveto vie vihreän ja sinisen, ei lisää valoa',
      !out.error && r === 128 && gr < 100 && gr > 60 && b === gr,
      out.error || `pelikenttä rgb(${(out.play || []).join(',')})`);
    /* Nauhaa ei enää ole, joten siirron kuuluu ulottua ruudun alalaitaan asti:
     * se on kuvaa siinä missä keskikin. Kertojan kerros on suojassa
     * piirtojärjestyksellä (`main.js`: `drawOverlay` `apply`n jälkeen), ja
     * sitä vartioi oma väitteensä. Tämä rivi kääntyi ympäri 17.8.2026 —
     * aiemmin se vaati alalaidalta muuttumatonta harmaata. */
    expect('palettisiirto ulottuu koko kuvaan, myös alalaitaan',
      !out.error && String(out.hud) === String(out.play),
      out.error || `alalaita rgb(${(out.hud || []).join(',')}),`
        + ` keskeltä rgb(${(out.play || []).join(',')})`);
    expect('siirto elää yhden framen: se kuluu piirtoon eikä jää voimaan',
      !out.error && out.left === null && !!out.shown
      && String(out.again) === String(out.play) && String(out.third) === String(out.play),
      out.error || `jäljelle ${JSON.stringify(out.left)}, toinen frame ${(out.again || []).join(',')}, `
        + `uudestaan asetettuna ${(out.third || []).join(',')}`);
    expect('siirto piirtyy vaikka kuvaefektit on kytketty pois',
      !out.error && String(out.play) !== '128,128,128',
      out.error || `esiasetus "pois", tulos rgb(${(out.play || []).join(',')})`);
    /* Kaksi vetoa, kaksi merkitystä: paikan väri viedään, tapahtuman väri
     * tuodaan. Väite on että tumma ruutu *nousee* lisäyksellä eikä kerrolla —
     * eli että toinen veto ei ole toisen makuversio. */
    expect('lisäysveto tuo valoa myös tummaan kuvaan, kerto ei voi',
      !out.error && out.litDark && out.mulDark
      && out.litDark[0] > 32 + 60 && out.litBright[0] > 200
      && out.mulDark[0] <= 32 && out.mulDark[1] < 32,
      out.error || `tumma 32 → lisäys rgb(${(out.litDark || []).join(',')}), `
        + `kerto rgb(${(out.mulDark || []).join(',')}); `
        + `kirkas 200 → lisäys rgb(${(out.litBright || []).join(',')})`);
    /* Verho ja siirto ovat kaksi eri merkkiä, ja se on nyt mitattu eikä
     * sovittu: verhon keskus on koskematon (rengas), siirron ei (tasainen). */
    expect('kuninkaan verho ja palettisiirto eivät voi näyttää samalta',
      !out.error && String(out.curtain.mid) === '128,128,128'
      && out.curtain.corner[0] > 128 + 20
      && out.shifted.mid[0] > 128 + 20
      && Math.abs(out.shifted.mid[0] - out.shifted.corner[0]) <= 1,
      out.error || `verho keskellä rgb(${(out.curtain.mid || []).join(',')}) `
        + `nurkassa rgb(${(out.curtain.corner || []).join(',')}) — `
        + `siirto keskellä rgb(${(out.shifted.mid || []).join(',')}) `
        + `nurkassa rgb(${(out.shifted.corner || []).join(',')})`);
    expect('siirrolla on katto, eikä nollan kokoinen siirto ole siirto',
      !out.error && out.clamped !== null && out.clamped <= 0.6 && out.clamped > 0
      && out.none === null && out.dark && out.dark[0] > 40,
      out.error || `katto ${out.clamped}, pimeimmillään rgb(${(out.dark || []).join(',')}), `
        + `nolla → ${JSON.stringify(out.none)}`);
  }

  /* --- 4. kolme tapahtumaa, ja niiden järjestys --- */
  /*
   * Kolme tapahtumaa jakaa yhden mekanismin, joten järjestys on osa
   * määrittelyä eikä sattuma: **uusin tieto voittaa.** Osuma on tapahtuma joka
   * kesti kymmenen framea, tähti on tila joka kestää yksitoista sekuntia ja
   * pomohuone on paikka joka kestää koko kentän — eli mitä lyhyempi, sitä
   * tuoreempi, ja sitä tärkeämpi juuri nyt.
   */
  {
    const out = await page.evaluate(async () => {
      try {
        const { LevelScene } = await import('/src/scenes/level.js');
        const { STAR_FRAMES, HURT_FLASH } = await import('/src/entities/player.js');
        const { PostFX } = await import('/src/gfx/postfx.js');
        const game = window.sfb3;
        const make = (id, power = { type: 'shroom', level: 3 }) => {
          game.state = {
            lives: 5, coins: 0, score: 0, power, reserve: null,
            world: 0, node: 'w1-1', cleared: {}, worldsOpen: 8, cards: [],
          };
          game.finishLevel = () => {};
          const scene = new LevelScene(game, id);
          game.setScene(scene);
          return scene;
        };

        /* a) vahinkovälähdys: osuma sytyttää sen, ja se sammuu itsestään. */
        const hurt = make('1-1');
        const clean = hurt.paletteShift();
        hurt.player.hurt('enemy');
        const lit = hurt.paletteShift();
        const trail = [];
        for (let i = 0; i <= HURT_FLASH + 4; i++) {
          const shift = hurt.paletteShift();
          trail.push(shift ? shift.amount : 0);
          if (hurt.player.hurtFlash > 0) hurt.player.hurtFlash--;
        }

        /* a2) välähdyksiä ei voi tulla peräkkäin nopeammin kuin osumia.
         *
         * Tämä on välähdyskynnyksen toinen puoli: yksi kirkastuva välähdys per
         * osuma on turvallinen vain jos osumia ei voi tulla kolmea sekunnissa.
         * Ne eivät voi, ja syy on vanha eikä tätä varten tehty —
         * kuolemattomuusframet osuman jälkeen. Mitataan yrittämällä. */
        const spam = make('1-1');
        let flashes = 0;
        let wasLit = false;
        for (let f = 0; f < 240; f++) {
          spam.player.hurt('enemy');       // joka frame, koko ajan
          const isLit = spam.player.hurtFlash > 0;
          if (isLit && !wasLit) flashes++;
          wasLit = isLit;
          if (spam.player.invuln > 0) spam.player.invuln--;
          if (spam.player.hurtFlash > 0) spam.player.hurtFlash--;
          if (spam.player.power.level === 0) spam.player.power = { type: 'shroom', level: 3 };
        }
        const spamHz = flashes / (240 / 60);

        /* b) tähti: sykkii, muttei välky. Kello on tähden oma laskuri, joten
         *    näyte otetaan sitä pitkin eikä seinäkellosta. */
        const star = make('1-1');
        star.player.star = STAR_FRAMES;
        const amounts = [];
        const lums = [];
        /* Nollaan asti, ja nolla mukaan: viimeinen näyte on se frame jolla
         * tähti loppuu, ja siirron on oltava silloin poissa eikä pienenä. */
        for (let f = 0; f <= STAR_FRAMES; f++) {
          star.player.star = STAR_FRAMES - f;
          const shift = star.paletteShift();
          const a = shift ? shift.amount : 0;
          amounts.push(a);
          const m = (v) => 1 - a * (1 - v / 255);
          lums.push(0.2126 * m(shift ? shift.r : 255)
            + 0.7152 * m(shift ? shift.g : 255)
            + 0.0722 * m(shift ? shift.b : 255));
        }
        /* Välähdys on huippu: nousu joka kääntyy laskuksi. */
        let peaks = 0;
        for (let i = 1; i < amounts.length - 1; i++) {
          if (amounts[i] > amounts[i - 1] && amounts[i] >= amounts[i + 1]) peaks++;
        }
        const hz = peaks / (STAR_FRAMES / 60);
        const swing = (Math.max(...lums) - Math.min(...lums)) / Math.max(...lums);
        const endsAtZero = amounts[amounts.length - 1];

        /* c) pomohuone: sävy niin kauan kuin tappelu on kesken. */
        const boss = make('1-F');
        boss.tick = 0;
        const atStart = boss.paletteShift();
        boss.tick = 120;
        const midFight = boss.paletteShift();
        boss.onBossDefeated();
        boss.tick += 200;
        const afterWin = boss.paletteShift();
        const plain = make('1-1').paletteShift();

        /* d) järjestys, kaikki kolme päällä yhtä aikaa. */
        const all = make('1-F');
        all.tick = 200;
        all.player.star = STAR_FRAMES;
        all.player.hurtFlash = HURT_FLASH;
        const first = all.paletteShift();
        all.player.hurtFlash = 0;
        const second = all.paletteShift();
        all.player.star = 0;
        const third = all.paletteShift();

        /* e) ja se päätyy oikeasti kuvalle: kentän piirto työntää sen PostFX:ään. */
        const drawn = make('1-1');
        drawn.player.hurtFlash = HURT_FLASH;
        PostFX.tint = null;
        const canvas = document.createElement('canvas');
        canvas.width = 320;
        canvas.height = 240;
        drawn.draw(canvas.getContext('2d'));
        const pushed = PostFX.tint ? { ...PostFX.tint } : null;
        PostFX.tint = null;

        return {
          clean, lit, trail, peaks, hz, swing, endsAtZero, maxAmount: Math.max(...amounts),
          flashes, spamHz,
          atStart, midFight, afterWin, plain,
          order: [first && first.reason, second && second.reason, third && third.reason],
          pushed,
        };
      } catch (e) { return { error: String(e && e.message || e) }; }
    });

    expect('osuma välähtää punaisena valona ja sammuu itsestään',
      !out.error && out.clean === null && !!out.lit && out.lit.reason === 'hurt'
      && out.lit.mode === 'screen'
      && out.lit.r > out.lit.g && out.lit.r > out.lit.b
      && out.trail[0] > 0 && out.trail[out.trail.length - 1] === 0
      && out.trail.every((v, i) => i === 0 || v <= out.trail[i - 1]),
      out.error || `${out.trail ? out.trail.map((v) => Math.round(v * 100) / 100).join(' → ') : '-'}`);
    expect('välähdyksiä ei voi tulla nopeammin kuin osumia, eli alle kolme sekunnissa',
      !out.error && out.spamHz > 0 && out.spamHz < 3,
      out.error || `${out.flashes} välähdystä 240 framessa = `
        + `${Math.round(out.spamHz * 100) / 100} Hz`);
    /* Kaksi lukua, yksi lähde: WCAG 2.3.1 yleinen välähdyskynnys. */
    expect('tähti sykkii muttei välky: alle kolme huippua sekunnissa ja alle 10 % luminanssia',
      !out.error && out.hz < 3 && out.swing < 0.1 && out.maxAmount > 0 && out.endsAtZero === 0,
      out.error || `${out.peaks} huippua = ${Math.round(out.hz * 100) / 100} Hz, `
        + `luminanssin heilahdus ${Math.round(out.swing * 1000) / 10} %, `
        + `suurin siirto ${Math.round(out.maxAmount * 100) / 100}`);
    expect('pomohuoneen sävy tulee tappelun mukana ja lähtee sen mukana',
      !out.error && out.atStart === null && !!out.midFight && out.midFight.reason === 'boss'
      && out.afterWin === null && out.plain === null,
      out.error || `alussa ${JSON.stringify(out.atStart)}, kesken ${out.midFight && out.midFight.reason}, `
        + `voiton jälkeen ${JSON.stringify(out.afterWin)}, tavallisessa kentässä ${JSON.stringify(out.plain)}`);
    expect('uusin tieto voittaa: osuma > tähti > huone',
      !out.error && String(out.order) === 'hurt,star,boss',
      out.error || `järjestys ${JSON.stringify(out.order)}`);
    expect('kentän piirto työntää siirron kuvaputkelle asti',
      !out.error && !!out.pushed && out.pushed.amount > 0,
      out.error || `PostFX:ssä ${JSON.stringify(out.pushed)}`);
  }

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- kuvaefektit: loppu ---- */

await browser.close();
server.close();

/* Every Sfx.play('x') / Music.play('x') in the source must name a real sound. */
const sourceFiles = [];
{
  const { readdir } = await import('node:fs/promises');
  const walk = async (dir) => {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) await walk(full);
      else if (entry.name.endsWith('.js')) sourceFiles.push(full);
    }
  };
  await walk(join(ROOT, 'src'));
}
const audioRefs = [];
for (const file of sourceFiles) {
  const text = await readFile(file, 'utf8');
  for (const [, name] of text.matchAll(/Sfx\.play\([^)]*?'([\w-]+)'/g)) {
    audioRefs.push({ kind: 'sfx', name, file });
  }
  for (const [, name] of text.matchAll(/Music\.play\([^)]*?'([\w-]+)'/g)) {
    audioRefs.push({ kind: 'music', name, file });
  }
}
const unknownAudio = audioRefs
  .filter((ref) => !report.audio[ref.kind].includes(ref.name))
  .map((ref) => `${ref.kind} '${ref.name}' in ${ref.file.slice(ROOT.length)}`);
report.checks.push({
  name: 'every sound the code asks for exists',
  ok: unknownAudio.length === 0,
  detail: unknownAudio.length ? unknownAudio.join(', ') : `${audioRefs.length} call sites`,
});
if (unknownAudio.length) report.failures.push(...unknownAudio);

/*
 * VAPAUTUNUT SÄVELMISTÖ ON NIMETTÄVÄ, JA TÄSSÄ SE EHTO ON AJETTAVA.
 *
 * DESIGN.md kohta 1 b (9.8.2026) päästää tekijänoikeudesta vapautuneen
 * sävellyksen sisään yhdellä ehdolla: **lähde nimetään**, sekä DESIGN.md:hen
 * että CHANGELOG.md:hen. Se ehto oli tähän asti lupaus, ja lupaus on juuri se
 * asia joka unohtuu kolmannella kerralla — kohta itse sanoo miksi tämä on
 * ankarampi kuin vanha sääntö: "kaikki on itse tehtyä" on väite jota kukaan ei
 * voi tarkistaa, ja nimetty teos on lause jonka kuka tahansa voi todentaa.
 *
 * Joten raita kantaa lähteensä mukanaan (`source` `TRACKS`-taulussa) ja tämä
 * tarkistaa, että sekä säveltäjä että teoksen nimi lukevat molemmissa
 * dokumenteissa. Raita ilman `source`-kenttää on omaa sävellystä eikä sitä
 * kysytä miltään — sääntö koskee lainattua, ei kaikkea.
 */
{
  const design = await readFile(join(ROOT, 'DESIGN.md'), 'utf8');
  const changelog = await readFile(join(ROOT, 'CHANGELOG.md'), 'utf8');
  /*
   * Luetaan **jokainen** `source`in kenttä eikä kahta nimettyä, ja se ero on
   * maailman 8 maksama oppi.
   *
   * *Yö Autiovuorella* tunnetaan lähes yksinomaan Rimski-Korsakovin
   * sovituksena, ja **sovitus on oma teoksensa omine suoja-aikoineen** — juuri
   * se on se kohta jossa "tämähän on vanhaa musiikkia" menee useimmiten
   * pieleen. Kun portti luki vain `composer`in ja `work`in, raita saattoi
   * kantaa `arranger`-kentän jota mikään ei tarkistanut: kenttä olisi ollut
   * koodissa, nimi olisi voinut puuttua molemmista dokumenteista, eikä mikään
   * olisi sanonut mitään. Portti joka kattaa osan tapauksista on huonompi kuin
   * puuttuva portti, koska se näyttää kattavan kaikki — sama havainto kuin
   * `cave`n kanssa, ja se on nyt tehty kahdesti.
   */
  const unnamed = [];
  for (const [track, source] of Object.entries(report.trackSources || {})) {
    const parts = Object.values(source).filter((v) => typeof v === 'string' && v.trim());
    if (!parts.length) unnamed.push(`${track}: lähde on tyhjä`);
    for (const part of parts) {
      if (!design.includes(part)) unnamed.push(`${track}: "${part}" puuttuu DESIGN.md:stä`);
      if (!changelog.includes(part)) unnamed.push(`${track}: "${part}" puuttuu CHANGELOG.md:stä`);
    }
  }
  const named = Object.keys(report.trackSources || {});
  report.checks.push({
    name: 'jokainen lainattu sävelmä on nimetty DESIGN.md:ssä ja muutoslokissa',
    ok: unnamed.length === 0,
    detail: unnamed.length ? unnamed.join('; ')
      : `${named.length} lainattua raitaa: ${named.join(', ') || 'ei yhtään'}`,
  });
  if (unnamed.length) report.failures.push(...unnamed);
}

/*
 * The map's difficulty numbers must be the ones the measurement produces today.
 *
 * `src/data/difficulty.js` is a carried copy: the tool is Node and reads
 * `tools/jump-budget.json` off disk, the game is a static page, so the numbers
 * cross in a data file the way `tools/pacing-stats.json` crosses to the
 * generator. A carried copy is the whole cost of doing it that way — edit one
 * chunk of one level and the map keeps promising yesterday's difficulty, which
 * is worse than showing none, because the player has no way to tell.
 *
 * So it is not trusted, it is re-derived. This imports the measurement itself
 * rather than a hash of the inputs: a hash would tell you something moved, this
 * tells you which level and by how much. Same lesson as the jump budget, and
 * for the same reason — the numbers are read by something that cannot recompute
 * them, so somebody else has to.
 */
/*
 * GENERAATTORI TUNTEE JOKAISEN TEEMAN EHDOT, JA NE ON KOETELTU RIKKINÄISELLÄ
 * KENTÄLLÄ.
 *
 * Maailmat 6, 7 ja 8 kirjoittivat itselleen rakennesäännön — luussa taivas on
 * auki eikä mikään roiku, pilvessä mikään ei seiso maassa eikä ohut pilvi ole
 * tyhjän päällä, linnakkeessa ei ole ulkopuolta eikä lippua — ja jokainen niistä
 * on portissa **palikkatiedostoa vasten**. Se riitti niin kauan kuin nuo
 * maailmat olivat käsintehtyjä: palikka on se paikka jossa käsi tekee virheen.
 *
 * Generoitu kenttä ei kuitenkaan kokoa palikoita vaan kirjoittaa ruudukon, joten
 * jokainen noista säännöistä menisi generaattorin ohi ilman että mikään sanoo
 * mitään. Sääntö joka koskee sisältöä mutta ei sen konetta on puolikas sääntö.
 *
 * Tämä portti kysyy siis kolme asiaa, ja kolmas on se joka tekee kahdesta
 * ensimmäisestä muuta kuin koristetta:
 *
 *   1  generaattori tuntee kaikki kahdeksan teemaa (ei seitsemää, ei yhdeksää —
 *      lista luetaan `THEMES`istä eikä kirjoiteta tänne käsin)
 *   2  jokainen generoitu kenttä läpäisee oman teemansa ehdon
 *   3  **jokainen teeman ehto hylkää sitä rikkovan koekentän.** Ilman tätä
 *      kohta 2 olisi tosi myös silloin kun tarkistus ei tarkista mitään — ja
 *      juuri niin kävisi, koska generaattori ei tällä hetkellä tuota yhtään
 *      kenttää luuhun, pilveen, tehtaaseen tai linnakkeeseen. Neljä ehtoa
 *      viidestä olisi tyhjä lupaus ilman rikkinäistä koekenttää.
 */
{
  let problems = [];
  let themeNames = [];
  let checked = 0;
  let fixturesRun = 0;
  try {
    const gen = await import('./gen-levels.mjs');
    const { GENERATED_LEVELS } = await import('../src/data/generated.js');
    const tiles = await readFile(join(ROOT, 'src/gfx/tiles.js'), 'utf8');
    const table = /export const THEMES = \{([\s\S]*?)\n\};/.exec(tiles);
    themeNames = table ? [...table[1].matchAll(/^ {2}(\w+): \{/gm)].map((m) => m[1]) : [];

    const missing = themeNames.filter((t) => !gen.THEME_RULES[t]);
    const extra = Object.keys(gen.THEME_RULES).filter((t) => !themeNames.includes(t));
    if (!themeNames.length) problems.push('THEMES-taulua ei löytynyt lähdetekstistä');
    problems.push(...missing.map((t) => `generaattori ei tunne teemaa ${t}`));
    problems.push(...extra.map((t) => `generaattori tuntee teeman ${t} jota ei ole`));

    for (const [id, def] of Object.entries(GENERATED_LEVELS)) {
      const bad = gen.themeProblems(def.theme, def.rows);
      checked++;
      problems.push(...bad.map((p) => `${id}: ${p}`));
    }

    /* Rikkinäinen koekenttä **sääntöä** kohti eikä teemaa kohti: sama pohja joka
     * kerta, yksi vika kerrallaan, ja teeman oma ehto on ainoa asia joka erottaa
     * ne. Pari per sääntö siksi että luussa, pilvessä ja linnakkeessa niitä on
     * kaksi, ja portti joka koettelee niistä toisen näyttää täsmälleen samalta
     * kuin portti joka koettelee molemmat. */
    for (const [theme, rule] of Object.entries(gen.THEME_RULES)) {
      if ((rule.fixtures || []).length !== rule.rules.length) {
        problems.push(`${theme}: ${rule.rules.length} sääntöä mutta `
          + `${(rule.fixtures || []).length} koekenttäparia`);
      }
      for (const make of rule.fixtures || []) {
        const { clean, broken } = make();
        fixturesRun++;
        if (gen.themeProblems(theme, clean).length) {
          problems.push(`${theme}: ehto hylkää oman kelvollisen koekenttänsä`);
        }
        if (!gen.themeProblems(theme, broken).length) {
          problems.push(`${theme}: ehto siunaa koekentän joka rikkoo sen`);
        }
      }
    }
  } catch (err) {
    problems.push(`teematarkistus ei päässyt ajoon: ${err && err.message}`);
  }
  report.checks.push({
    name: 'generaattori tuntee jokaisen teeman ehdot, ja ehdot hylkäävät rikkinäisen kentän',
    ok: problems.length === 0,
    detail: problems.length ? problems.slice(0, 5).join('; ')
      : `${themeNames.length} teemaa, ${checked} generoitua kenttää, ${fixturesRun} koekenttäparia`,
  });
  if (problems.length) report.failures.push(...problems);
}

/*
 * FEEDBACK MOVES THE GENERATOR, AND THE JUMP BUDGET STILL WINS.
 *
 * `tools/read-notes.mjs` lets a person drag a column range on the playtest desk
 * and say one of three things — *easier*, *harder*, *put a hill here* —
 * `planTuning` turns that into the two knobs the telemetry path already moved,
 * and `buildLevel` reads them. That is a straight line from a sentence somebody
 * typed to the geometry of a shipped level, and it is the first input this
 * generator has ever had that can ask for **more** difficulty rather than less.
 *
 * Which is the whole reason this block exists. Everything the tuner could do
 * before made pieces smaller, so every site could subtract and stop there. A
 * negative `ease` adds, and three expressions in `src/data/generator.js` —
 * `gap`, `corkGate`, `crumbleWalk` — clamped to the budget *before* subtracting.
 * Two "harder" notes over the same stretch would therefore have produced a hole
 * wider than the measured run-jump: a level nobody can finish, generated on
 * request, with the person who asked for it having no way to know that is what
 * they asked for. `withinBudget` re-applies the cap after the ease. This asks
 * whether it holds, and five other things.
 *
 * Six, because the path has six places to go wrong: the cap under pressure, the
 * cap when nobody asked for anything, what a note means, what a *broken* note
 * means, what happens when a note asks for something the world subtracted, and
 * whether the desk and the generator still agree on the list of shapes at all.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const gen = await import('./gen-levels.mjs');
  const { buildLevel, PIECES } = await import('../src/data/generator.js');
  const { validateLevel } = await import('../src/data/rules.js');
  const { readNotes, SHAPES } = await import('./read-notes.mjs');
  const { mkdtemp, writeFile, rm } = await import('node:fs/promises');
  const { tmpdir } = await import('node:os');
  const budget = JSON.parse(await readFile(join(ROOT, 'tools/jump-budget.json'), 'utf8'));

  /* A plan row, built on this block's own seeds. The tool's seed expression is
   * the tool's business — `gen-levels.mjs` explains at length why it cannot
   * move — so borrowing it here would tie this gate to a number that exists for
   * an unrelated reason. The rows themselves are borrowed, because a world's
   * gap cap and drop list are exactly the parts a made-up spec would get wrong. */
  const build = (spec, seed, tuning = null) => buildLevel({
    seed,
    theme: spec.theme,
    targetWidth: spec.width,
    intensity: spec.intensity || 1,
    enemiesPer100: spec.enemiesPer100 === undefined ? null : spec.enemiesPer100,
    maxGap: spec.maxGap === undefined ? null : spec.maxGap,
    drop: spec.drop || [],
    species: spec.species || null,
    minIntro: spec.minIntro || 0,
    tuning,
  });
  /* One row per theme the plan reaches, times four seeds — a spread and not a
   * level, because a cap that holds on one seed's pieces has not been asked
   * anything about the pieces that seed never drew. */
  const SPREAD = [...new Map(gen.PLAN.map((s) => [s.theme, s])).values()];
  const SEEDS = [1, 7, 4242, 90210];
  /* The same tuning on every set piece, however many the build ends up with.
   * `buildLevel` looks each index up and a miss is simply untuned, so the range
   * only has to outlast any level's piece count. */
  const everyPiece = (tune) => {
    const m = new Map();
    for (let i = 0; i < 512; i++) m.set(i, { ...tune });
    return m;
  };

  /*
   * 1. THE ONE THAT WOULD HAVE CAUGHT IT.
   *
   * `ease: -3` on every piece is three "harder" notes deep on every stretch of
   * every level, i.e. more than the desk will realistically produce and
   * therefore the right amount to ask for. The gaps and walls are measured by
   * the validator rather than counted here, so this asks the levels the exact
   * question the shipped ones are held to.
   *
   * The rows are read twice, and the second reading is `crumbleWalk`'s. `%` is
   * solid to the validator — deliberately: it is a floor until you stand on it
   * — so a deck stretched past the budget is invisible in the level as built.
   * Replacing the deck with air is the level a moment later, which is the state
   * that piece's own cap exists to survive.
   */
  {
    const wide = [];
    const spans = (rows) => validateLevel(rows, budget).filter((p) => /^(gap|wall) of /.test(p));
    for (const spec of SPREAD) {
      for (const seed of SEEDS) {
        const made = build(spec, seed, everyPiece({ restScale: 1, ease: -3 }));
        wide.push(...spans(made.rows).map((p) => `${spec.theme}/${seed}: ${p}`));
        wide.push(...spans(made.rows.map((r) => r.replaceAll('%', ' ')))
          .map((p) => `${spec.theme}/${seed} with the deck fallen: ${p}`));
      }
    }
    expect('a "harder" note cannot widen a hole past the measured jump budget',
      wide.length === 0,
      wide.length ? wide.slice(0, 3).join('; ')
        : `${SPREAD.length} themes x ${SEEDS.length} seeds at ease -3, every gap within `
          + `${budget.gapTiles} (${budget.softGapTiles} bridged) and every wall within `
          + `${budget.wallTiles}`);
  }

  /*
   * 2. AND THE ONE THAT SAYS THE CAP COST NOTHING.
   *
   * A cap re-applied after the ease is arithmetic that changes nothing whenever
   * the ease is zero or above, which is every build this repository has ever
   * made. That deserves a gate rather than a paragraph, because the feedback
   * path leans on it twice. `gen-levels.mjs` builds each level plain first and
   * resolves every note against *that* build's columns, so a neutral tuning
   * that quietly moved one tile would leave every note pointing at the wrong
   * piece; and `src/data/generated.js` is committed, so the same drift would
   * rewrite shipped levels on the next run for a reason nobody typed.
   *
   * Byte-identical rows, not "close enough": the two builds share a seed, so
   * there is no honest reason for a single character to differ.
   */
  {
    const drift = [];
    for (const spec of SPREAD) {
      for (const seed of SEEDS) {
        const plain = build(spec, seed).rows.join('\n');
        const neutral = build(spec, seed, everyPiece({ restScale: 1, ease: 0 })).rows.join('\n');
        if (plain !== neutral) {
          const at = [...plain].findIndex((ch, i) => ch !== neutral[i]);
          drift.push(`${spec.theme}/${seed} differs at character ${at}`);
        }
      }
    }
    expect('a neutral tuning builds the same level as no tuning at all',
      drift.length === 0,
      drift.length ? drift.slice(0, 3).join('; ')
        : `${SPREAD.length * SEEDS.length} levels, rows identical byte for byte`);
  }

  /*
   * 3. WHAT A NOTE MEANS, ON A TRACE SMALL ENOUGH TO READ.
   *
   * Three set pieces at known columns, because the thing under test is the
   * mapping from a range to a knob — against a real level's trace every
   * assertion below would instead be a claim about which piece that seed
   * happened to draw. `enemies` is in the trace on purpose: it is the piece
   * with no size to give, and the difference between "the calm moved" and "the
   * obstacle moved" is the one distinction `planTuning` makes that a reader
   * would not guess.
   */
  {
    const TRACE = [
      { name: 'gap', from: 30, to: 46 },
      { name: 'stairs', from: 46, to: 70 },
      { name: 'enemies', from: 70, to: 92 },
    ];
    /* Telemetry is optional and none is passed: a note is a judgement, and it
     * does not wait for a log to agree with it. */
    const plan = (from, to, want) => gen.planTuning(null, TRACE, [{
      from, to, want, shape: want.startsWith('shape:') ? want.slice('shape:'.length) : null,
    }]);
    const show = (r) => JSON.stringify([...r.tuning]);

    const easier = plan(32, 44, 'easier');
    const e0 = easier.tuning.get(0);
    expect('an "easier" note lowers the obstacle and lengthens the calm before it',
      easier.tuning.size === 1 && !!e0 && e0.ease === 1 && e0.restScale > 1, show(easier));

    const harder = plan(32, 44, 'harder');
    const h0 = harder.tuning.get(0);
    expect('a "harder" note widens the obstacle and shortens the calm before it',
      harder.tuning.size === 1 && !!h0 && h0.ease === -1 && h0.restScale < 1, show(harder));

    /* A dragged range is a sentence about the stretch, so it lands on every
     * piece it touches — but only the two with a height or a span can spend an
     * `ease`, and `enemies` has to come out with its calm moved and nothing
     * else. Without that half, "applied to every covered piece" and "invented a
     * knob on a piece that has none" look identical from outside. */
    const across = plan(30, 92, 'easier');
    const covered = [0, 1, 2].map((i) => across.tuning.get(i));
    expect('a note across three pieces moves all three calms and only the two sizes',
      across.tuning.size === 3 && covered.every((s) => s && s.restScale > 1)
      && covered[0].ease === 1 && covered[1].ease === 1 && covered[2].ease === 0,
      show(across));

    /* Asking for a hill is asking for one hill. The same range as above, so the
     * only thing between this and three hills is the rule itself. */
    const shaped = plan(30, 92, 'shape:hill');
    const s0 = shaped.tuning.get(0);
    expect('a "shape:" note lands on the first piece in the range and no other',
      shaped.tuning.size === 1 && !!s0 && s0.force === 'hill', show(shaped));

    /* Silence here would be indistinguishable from a note that worked. */
    const nowhere = plan(200, 240, 'easier');
    expect('a note outside every set piece changes nothing and says so',
      nowhere.tuning.size === 0 && nowhere.notes.length === 1
      && nowhere.notes[0].includes('outside any set piece'),
      `${nowhere.tuning.size} pieces tuned, ${nowhere.notes.join(' / ') || 'nothing reported'}`);
  }

  /*
   * 4. A BROKEN NOTE IS REFUSED BY NAME, AND ITS NEIGHBOURS SURVIVE IT.
   *
   * Both halves matter and the second is the easier one to lose: a parser that
   * throws the file away on the first typo turns one misspelt level id into an
   * evening of feedback nobody acted on. Six ways to be wrong inside a file,
   * plus the two that are wrong about the whole file and therefore throw.
   */
  {
    const dir = await mkdtemp(join(tmpdir(), 'sfb3-notes-'));
    const file = join(dir, 'notes.json');
    const write = (body) => writeFile(file, JSON.stringify(body));
    const problems = [];
    try {
      await write({
        game: 'sfb3',
        v: 1,
        notes: [
          { level: '1-4', from: 30, to: 46, want: 'easier' },        // sound
          { level: 'seiska', from: 30, to: 46, want: 'easier' },     // not a level id
          { level: '1-5', from: 46, to: 30, want: 'harder' },        // range runs backwards
          { level: '1-5', from: 10, to: 20, want: 'shape:banaani' }, // no such piece
          { level: '1-5', from: 10, to: 20, want: 'sivuttain' },     // no such direction
          { level: '1-6', from: 10, to: 40, want: 'easier' },        // contradiction, one half
          { level: '1-6', from: 30, to: 60, want: 'harder' },        // and the other
          { level: '1-6', from: 90, to: 99, want: 'harder' },        // sound, overlaps neither
        ],
      });
      const read = await readNotes(file);
      const named = (needle) => read.refused.some((r) => r.includes(needle));
      const byName = [
        ['a level id that is not one', named('not a level id')],
        ['a backwards column range', named('not a column range')],
        ['a shape the generator has never heard of', named('no such shape "banaani"')],
        ['a want that is neither direction nor shape', named('is neither easier, harder')],
        ['both sides of a contradiction',
          read.refused.filter((r) => r.includes('contradicts')).length === 2],
      ];
      for (const [what, ok] of byName) if (!ok) problems.push(`accepted ${what}`);
      if (read.refused.length !== 6) {
        problems.push(`${read.refused.length} refusals, expected 6`);
      }
      /* The two sound notes sit on different levels, and the second shares its
       * level with the refused pair — so this also asks that a level does not
       * lose its good notes along with its bad ones. */
      const kept = [...read.levels].map(([id, list]) => `${id}x${list.length}`).join(' ');
      if (kept !== '1-4x1 1-6x1') problems.push(`kept ${kept || 'nothing'}, expected 1-4x1 1-6x1`);

      const throws = async (body) => {
        await write(body);
        try { await readNotes(file); return false; } catch { return true; }
      };
      if (!await throws({ game: 'smb1', v: 1, notes: [] })) problems.push('read another game\'s file');
      if (!await throws({ game: 'sfb3', v: 2, notes: [] })) problems.push('read a version 2 file');
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
    expect('readNotes refuses every malformed note by name and keeps the sound ones',
      problems.length === 0,
      problems.join('; ') || '6 notes refused, 2 kept, 2 whole files refused');
  }

  /*
   * 5. A NOTE IS A REQUEST, AND THE WORLD MAY STILL SAY NO.
   *
   * `drop` is the mechanism by which world 1 stays as narrow as its first three
   * levels taught, and `gen-levels.mjs` records what it cost the day generated
   * levels handed those mechanics back. A `shape:` note is a way to hand one
   * back on purpose, so the refusal is the behaviour — and the *recorded*
   * refusal is the point, because a note that silently did nothing is the
   * failure mode the whole notes path is written against. The granted half is
   * here too: "never honoured" and "honoured only when allowed" produce the
   * same `honoured: false` on the case above.
   */
  {
    const spec = gen.PLAN.find((s) => (s.drop || [])
      .some((n) => gen.THEME_RULES[s.theme].weights[n]));
    const problems = [];
    if (!spec) {
      problems.push('no plan row drops a piece its own theme knows about');
    } else {
      const forbidden = spec.drop.find((n) => gen.THEME_RULES[spec.theme].weights[n]);
      const allowed = Object.keys(gen.THEME_RULES[spec.theme].weights)
        .find((n) => !spec.drop.includes(n));
      const forced = (name) => build(spec, 31337,
        new Map([[0, { restScale: 1, ease: 0, force: name }]])).trace;

      const no = forced(forbidden);
      if (!no.length) problems.push('the build produced no set pieces at all');
      else {
        if (no[0].asked !== forbidden) problems.push(`the request for ${forbidden} was not recorded`);
        if (no[0].honoured !== false) problems.push(`${forbidden} was recorded as honoured`);
        if (no.some((t) => t.name === forbidden)) problems.push(`${forbidden} was built anyway`);
      }
      const yes = forced(allowed);
      if (!yes.length || yes[0].name !== allowed || yes[0].honoured !== true) {
        problems.push(`${allowed} should have been honoured, got ${yes.length ? yes[0].name : 'nothing'}`);
      }
    }
    expect('a shape the world dropped is refused in the trace, not granted',
      problems.length === 0,
      problems.join('; ') || `${spec.id} drops ${spec.drop.join(', ')}`);
  }

  /*
   * 6. THE DESK'S PALETTE AND THE GENERATOR'S ARE ONE LIST, OR THEY ARE A BUG.
   *
   * `SHAPES` is what the playtest desk offers and what a refusal prints back at
   * somebody who typed a name wrong. It is derived from `PIECES` today, so this
   * costs nothing — and it is exactly the kind of derivation that gets replaced
   * by a hand-written list the first time the desk wants to hide one entry. On
   * that day the two drift apart in silence: a new set piece is a shape nobody
   * can ask for, and a renamed one is a shape the desk offers and the generator
   * refuses. Neither breaks anything, which is why nothing else would say so.
   */
  {
    const mine = Object.keys(PIECES).sort();
    const missing = mine.filter((n) => !SHAPES.includes(n));
    const extra = SHAPES.filter((n) => !mine.includes(n));
    expect('every shape the desk can ask for is a piece the generator can build',
      missing.length === 0 && extra.length === 0,
      missing.length || extra.length
        ? `not offered: ${missing.join(', ') || '-'}; not a piece: ${extra.join(', ') || '-'}`
        : `${SHAPES.length} pieces`);
  }

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- palaute generaattorille: loppu ---- */

/*
 * ALKUPERÄISYYSTARKISTUS: MITÄ ON MITATTU JA MITÄ EI, EIKÄ MITÄÄN SILTÄ VÄLILTÄ.
 *
 * DESIGN.md kohta 3 sanoo että generaattori hylkää kentän jos yksikään **8
 * sarakkeen ikkuna** osuu korpukseen, ja kohta 4 lisää käskyn: *aja generaattori
 * aina `VGLC_DIR` asetettuna*. Korpus ei ole repossa eikä saa olla, joten käsky
 * on ainoa mitä repo voi tehdä — ja käsky on juuri se muoto jonka kolmas tekijä
 * unohtaa.
 *
 * **Miksi tämä ei ole kaatava portti "tarkistamattomalle sisällölle".** Sellainen
 * portti olisi punainen jokaisessa ympäristössä jossa korpusta ei ole, eli tässä
 * repossa aina — ja tämä tiedosto sanoo itse muualla mitä pysyvästi punaiselle
 * portille tapahtuu: se sammutetaan. Pahempaa, se painostaisi merkitsemään
 * kentän tarkistetuksi jotta ajo menisi läpi, mikä on tasan se valhe jota vastaan
 * koko kohta 3 on kirjoitettu.
 *
 * Sen sijaan portti väittää **ympäristöstä ja tallenteesta yhdessä**, ja se on
 * kaatava molempiin suuntiin:
 *
 *   - `VGLC_DIR` asetettu → korpus luetaan tässä ja nyt, ja jokaisen generoidun
 *     kentän jokainen 8 sarakkeen ikkuna verrataan siihen. Yksikin osuma
 *     kaataa. Tämä on se "kyllä vai ei" jonka omistaja saa yhdellä komennolla.
 *   - `VGLC_DIR` asettamatta → tarkistusta ei voi tehdä, eikä sitä teeskennellä.
 *     Portti vaatii silloin että **jokainen generoitu kenttä kantaa merkinnän
 *     siitä ettei sitä ole tarkistettu**, ja kaataa ajon jos jokin kenttä
 *     väittää olevansa tarkistettu ilman että kukaan voi todentaa sitä.
 *
 * Eli: repo saa olla vihreä ilman korpusta, mutta se ei saa **väittää** mitään
 * ilman korpusta. Ero on koko kohta 3.
 */
{
  const problems = [];
  let detail = '';
  try {
    const { corpusHits, CORPUS_DIR } = await import('./originality.mjs');
    const { GENERATED_LEVELS } = await import('../src/data/generated.js');
    const levels = Object.entries(GENERATED_LEVELS);
    if (!levels.length) problems.push('yhtään generoitua kenttää ei löytynyt');

    if (CORPUS_DIR) {
      let hits = 0;
      let files = 0;
      for (const [id, def] of levels) {
        const r = await corpusHits(def.rows);
        files = r.files;
        hits += r.hits;
        if (r.hits) problems.push(`${id}: ${r.hits} kahdeksan sarakkeen ikkunaa osuu korpukseen`);
        if (def.origin !== 'checked') {
          problems.push(`${id}: korpus on käytettävissä mutta kenttä on generoitu ilman sitä `
            + '(merkintä "not checked") — aja: VGLC_DIR=… node tools/gen-levels.mjs');
        }
      }
      detail = `${levels.length} kenttää, ${files} korpustiedostoa, ${hits} osumaa`;
    } else {
      /*
       * ILMAN KORPUSTA MERKINTÄ LUETAAN, EI KIISTETÄ — ja tämä puolisko oli
       * väärin päin siihen asti kunnes tarkistus ensimmäisen kerran oikeasti
       * ajettiin.
       *
       * Tässä luki `def.origin !== 'not checked'` → kaatuu, perusteluna
       * *"tarkistusta ei ole tehty, joten se ei saa lukea tehdyksi"*. Se lause
       * on epätosi: `origin` on **tallenne siitä mitä generointiajossa
       * tapahtui**, ei väite tästä ajosta. Kun korpus 10.8.2026 saapui ja
       * kaikki 27 generoitua kenttää generoitiin `VGLC_DIR` asetettuna, tämä
       * ehto teki repostä punaisen jokaiselle joka **ei** omista korpusta —
       * mitattuna 27 kenttää, 27 kaatavaa riviä, eikä yksikään niistä ollut
       * valhe. Portti siis rankaisi työn tekemisestä, ja DESIGN.md kohdan 3 oma
       * lause *"repo saa olla vihreä ilman korpusta"* lakkasi olemasta totta
       * samalla hetkellä.
       *
       * Se mitä tämä haara *voi* mitata, se mittaa yhä: **jokainen kenttä
       * kantaa merkinnän, ja merkintä on toinen niistä kahdesta sanasta.**
       * Puuttuva tai tuntematon `origin` on kenttä jonka alkuperästä tiedosto
       * ei sano mitään, ja se on tarkistettavissa ilman korpusta. Sen sijaan
       * "onko tämä `checked` ansaittu" ei ole — ja portti joka ei voi mitata
       * väitettään ei saa esittää sitä.
       *
       * Sääntö kokonaisuudessaan on siis yhä kaksipuolinen, mutta oikein päin:
       * korpuksen kanssa jokainen ikkuna verrataan ja `not checked` kaataa;
       * ilman korpusta luetaan mitä tallenne sanoo ja tulostetaan se.
       */
      const WORDS = ['checked', 'not checked'];
      const mute = levels.filter(([, def]) => !WORDS.includes(def.origin));
      problems.push(...mute.map(([id, def]) => `${id}: alkuperämerkintä `
        + `${def.origin === undefined ? 'puuttuu' : `"${def.origin}"`} — pitää olla `
        + `"${WORDS.join('" tai "')}", generaattorin kirjoittamana`));
      const tally = WORDS.map((w) => `${levels.filter(([, d]) => d.origin === w).length} "${w}"`);
      detail = `${levels.length} kenttää: ${tally.join(', ')} — VGLC_DIR asettamatta, `
        + 'tarkistusta ei voi tehdä täällä: VGLC_DIR=… node tools/originality.mjs';
    }
  } catch (err) {
    problems.push(`alkuperäisyystarkistus ei päässyt ajoon: ${err && err.message}`);
  }
  report.checks.push({
    name: 'generoitu kenttä kantaa sen mitä sen alkuperästä on mitattu, ei enempää',
    ok: problems.length === 0,
    detail: problems.length ? problems.slice(0, 3).join('; ') : detail,
  });
  if (problems.length) report.failures.push(...problems);
}

/*
 * JOKAISELLA VIHOLLISMERKILLÄ ON HINTA VAIKEUSMITTARISSA.
 *
 * Piikkiukko lähti tuotantoon pisteillä **0**: se puuttui `ENEMY_COST`-taulusta
 * kokonaan, joten jokainen kenttä jossa niitä oli mittautui helpommaksi kuin
 * mitä se pelattuna oli — ja mittari on nykyään portti (maailman käyrän muoto),
 * eli väärä luku ei enää ole vain väärä raportti. Sama vika tehtiin melkein
 * uudestaan papuparoonin kanssa, ja se on merkki siitä että kyse ei ole
 * huolimattomuudesta vaan puuttuvasta tarkistuksesta.
 *
 * Merkit luetaan `ENEMY_CHARS`in lähdetekstistä eikä moduulista, koska tämä
 * puoli ajaa Nodessa eikä selaimessa — sama tekniikka kuin äänien nimien
 * tarkistuksessa yllä.
 */
{
  const { ENEMY_COST } = await import('./difficulty.mjs');
  const text = await readFile(join(ROOT, 'src/entities/enemies.js'), 'utf8');
  const table = /export const ENEMY_CHARS = \{([\s\S]*?)\n\};/.exec(text);
  const marks = table ? [...table[1].matchAll(/^\s{2}(\w):/gm)].map((m) => m[1]) : [];
  const priceless = marks.filter((ch) => ENEMY_COST[ch] === undefined);
  report.checks.push({
    name: 'jokaisella vihollismerkillä on hinta vaikeusmittarissa',
    ok: marks.length > 0 && priceless.length === 0,
    detail: priceless.length
      ? `hinnaton merkki: ${priceless.join(' ')} — lisää ENEMY_COST-tauluun`
      : `${marks.length} merkkiä: ${marks.join(' ')}`,
  });
  if (marks.length === 0) report.failures.push('ENEMY_CHARS-taulua ei löytynyt lähdetekstistä');
  if (priceless.length) {
    report.failures.push(...priceless.map((ch) => `'${ch}' puuttuu ENEMY_COST-taulusta`));
  }
}

/*
 * PISTEET OVAT KAKKOSEN POTENSSEJA, JA NE OVAT YHDESSÄ PAIKASSA.
 *
 * Kaksi väitettä, ja kumpikin vartioi eri puolta samasta päätöksestä
 * (`src/core/points.js`):
 *
 *   1. **Jokainen luku on kakkosen potenssi.** Myös kertoimet, koska tulo on
 *      potenssi vain jos molemmat tekijät ovat — ketjun kahdeksas tappo kulkee
 *      kahden kertoimen läpi ennen kuin se pomppaa ruudulle.
 *   2. **Lähdekoodissa ei ole yhtään pistelukua.** Tämä on se puoli joka
 *      rapistuu itsestään: uusi vihollinen kirjoitetaan vanhan vieressä, ja
 *      `this.score = 200` on juuri se rivi joka kopioituu. Portti lukee
 *      `src/`:n tekstinä eikä moduuleina, koska väite koskee kirjoitusasua.
 *
 * Väite 1 oli 17.8.2026 alkaen "kokonaisluvun neliö", ja omistaja osoitti
 * 18.8.2026 miksi se ei riittänyt: **100 on neliö**, ja niin ovat 400 ja 900 —
 * eli neliöllisyys salli täsmälleen ne genren pyöreät luvut joita vastaan koko
 * sääntö kirjoitettiin. Potenssi ei salli.
 */
{
  const pts = await import(join(ROOT, 'src/core/points.js'));
  /* Bittitesti eikä logaritmi: `Math.log2` on liukuluku, ja liukuluku joka on
   * "melkein kokonaisluku" on juuri se tapa jolla tämä portti siunaisi
   * hiljaa väärän arvon. `n & (n - 1)` on nolla tasan potensseille. */
  const power = (n) => Number.isInteger(n) && n > 0 && (n & (n - 1)) === 0;
  const table = [
    ...Object.entries(pts.PTS).map(([k, v]) => [`PTS.${k}`, v]),
    ['COIN', pts.COIN],
    ['TIME_SECOND', pts.TIME_SECOND],
    ['POP_BONUS', pts.POP_BONUS],
    ...pts.GOAL_STEPS.map((v, i) => [`GOAL_STEPS[${i}]`, v]),
    ...pts.CHAIN.map((v, i) => [`CHAIN[${i}]`, v]),
    ...Array.from({ length: 8 }, (_, v) => [`bossPoints(${v})`, pts.bossPoints(v)]),
  ];
  const crooked = table.filter(([, v]) => !power(v));
  /* Nousevuus on osa väitettä: portaikko joka ei nouse ei ole portaikko, ja
   * potenssillisuus yksin sallisi sellaisen. */
  const climbs = (list) => list.every((v, i) => i === 0 || v > list[i - 1]);
  const rising = climbs(pts.GOAL_STEPS) && climbs(pts.CHAIN)
    && climbs(Array.from({ length: 8 }, (_, v) => pts.bossPoints(v)));
  report.checks.push({
    name: 'jokainen pistearvo on kakkosen potenssi ja portaikot nousevat',
    ok: crooked.length === 0 && rising,
    detail: crooked.length
      ? `ei potenssi: ${crooked.map(([k, v]) => `${k} = ${v}`).join(', ')}`
      : `${table.length} arvoa, eksponentit ${table.map(([, v]) => Math.round(Math.log2(v))).join(' ')}`
        + `${rising ? '' : ' — MUTTA portaikko ei nouse'}`,
  });
  if (crooked.length) {
    report.failures.push(...crooked.map(([k, v]) => `${k} = ${v} ei ole kakkosen potenssi`));
  }
  if (!rising) report.failures.push('pisteportaikko ei nouse');

  const SRC = [
    'src/scenes/level.js', 'src/entities/enemies.js', 'src/entities/player.js',
    'src/entities/effects.js', 'src/entities/items.js',
  ];
  const loose = [];
  for (const f of SRC) {
    const text = await readFile(join(ROOT, f), 'utf8');
    text.split('\n').forEach((line, i) => {
      if (/awardScore\(\s*\d/.test(line) || /\bthis\.score = [1-9]/.test(line)) {
        loose.push(`${f}:${i + 1} ${line.trim()}`);
      }
    });
  }
  report.checks.push({
    name: 'pistelukuja ei kirjoiteta muualle kuin pistetaulukkoon',
    ok: loose.length === 0,
    detail: loose.length ? loose.join(' | ') : `${SRC.length} tiedostoa luettu`,
  });
  if (loose.length) report.failures.push(...loose.map((l) => `irtonainen pisteluku: ${l}`));
}

/* ---- laattavaarojen hinta ---- */
/*
 * JA SAMA SÄÄNTÖ SILLE PUOLELLE JOKA EI OLE VIHOLLINEN.
 *
 * Portti yllä kävelee **vihollistaulun**, ja juuri se on syy siihen ettei se
 * voinut huomata möykkyä. `T.LUMP` (`'C'`) asetettiin 4-2:een ja 4-F:ään
 * 10.8.2026, se voi viedä pelaajalta voimatason — ja `src/data/difficulty.js`
 * ei muuttunut yhdeltäkään riviltä.
 *
 * Syitä on kaksi ja jälkimmäinen on se oikea:
 *
 *   1. `tools/difficulty.mjs` ei tuntenut merkkiä `'C'`.
 *   2. **Tarkistus jonka piti huomata se katsoi väärää taulua.** Vaara joka on
 *      laatta on `ENEMY_CHARS`in ulkopuolella, joten mikään ei ollut koskaan
 *      huomaamassa tätä. Piikkiukon vika, siirrettynä yhden luokan sivuun.
 *
 * Pelkän möykyn hinnoittelu jättäisi reiän auki seuraavalle vaaralaatalle, eli
 * korjaisi sen tapauksen joka jo tiedetään. Siksi tämä portti kysyy kaikilta.
 *
 * LISTA JOHDETAAN, EI KIRJOITETA — koska käsin kirjoitettu lista on tasan se
 * mikä tässä petti. Satuttavat merkit luetaan `TILE_INFO`sta, samasta taulusta
 * jota peli itse lukee (`info`, `isSolid`, `LevelScene.playerTiles`). Se
 * importoidaan eikä lueta lähdetekstinä niin kuin `ENEMY_CHARS` yllä, ja ero
 * on tiedostossa eikä periaatteessa: `src/gfx/tiles.js` importoituu Nodeen
 * sellaisenaan, `enemies.js` ei.
 *
 * Lippu kerrallaan, ja luokittelu on koko homman ydin:
 *
 *   SATUTTAA
 *     `hazard`     kosketus vie voimatason tai hengen — piikki, laava.
 *     `quicksand`  ei satuta kosketuksesta vaan kellosta: uppoaminen hukuttaa.
 *     `falls`      putoaa päälle ja osuu — `LevelScene.lumpImpact` → `p.hurt`.
 *
 *   EI SATUTA
 *     `solid` `semi` `breakable` `bumpable` `question` `note` `pipe` `warp`
 *     `climb` `coin` `goal` `door` `switch` — maastoa, palkintoja ja ovia.
 *     `crumble` ja `surface` ovat näistä ne joiden kohdalla on jotain
 *     sanottavaa, ja sanottava on sama. Mureneva lauta ei satuta, se vie
 *     jalansijan — ja se hinta on jo mittarissa kuiluina ja tarkkuutena
 *     (`stands` ei lue sitä maaksi, `precision` kertoo sen 1,5:llä). Jää ei
 *     satuta, se vie *tähtäyksen*, ja sekin hinta on jo tarkkuudessa
 *     (`aimWidth` nostaa "riittävän leveän" jalansijan kolmesta laatasta
 *     viiteen). Kahteen kertaan laskettu vaara on yhtä väärin kuin laskematta
 *     jätetty.
 *
 *     Jää olisi vaaralistalla lisäksi mekaanisesti väärässä paikassa:
 *     `HAZARD_COST` luetaan sarakkeen **pahimpana** (`Math.max`), joten jään ja
 *     piikin jakava sarake hinnoittelisi vain piikin — eli jää olisi ilmaista
 *     tasan siellä missä se maksaa eniten.
 *
 * **Ja luokittelu itse on portti.** Jos `TILE_INFO`iin ilmestyy lippu jota
 * kumpikaan lista ei tunne, tämä kaatuu ja kysyy kummalle listalle se kuuluu.
 * Ilman sitä ehtoa lista olisi taas käsin kirjoitettu — vain kauempana siitä
 * paikasta jossa uusi laatta syntyy, mikä on huonompi eikä parempi.
 *
 * Väite mitataan eikä muisteta: kaksi identtistä koekenttää joissa on yhden
 * merkin ero, ja luvun on noustava. Sama tekniikka kuin tarkistuksessa
 * `vaikeusmittari näkee juoksuhiekan`, nyt jokaiselle satuttavalle laatalle
 * kerralla ja johdetusta listasta. Koekenttä on tasamaata, joten ainoa termi
 * joka voi liikkua on `hazards` — kuilut, kuilu% ja tarkkuus eivät näe
 * yhtäkään lisättyä merkkiä.
 */
{
  const checks = [];
  const failures = [];
  const expect = (name, ok, detail = '') => {
    checks.push({ name, ok, detail });
    if (!ok) failures.push(`${name}${detail ? ` (${detail})` : ''}`);
  };

  const { TILE_INFO } = await import('../src/gfx/tiles.js');
  const { scoreRows } = await import('./difficulty.mjs');

  const HURTS = ['hazard', 'quicksand', 'falls'];
  /* `spring` on vaarattomien listalla, ja se on väite eikä oletus: laatta
   * heittää pelaajaa ylöspäin eikä koske häneen. Se voi tietysti heittää
   * jonnekin ikävään, mutta niin voi lauttakin — vaara on siinä mihin
   * laskeudutaan, ja sen mittaa jo kuilu- ja piikkihinnoittelu. */
  const HARMLESS = ['solid', 'semi', 'breakable', 'bumpable', 'question', 'note',
    'pipe', 'warp', 'climb', 'crumble', 'switch', 'coin', 'goal', 'door', 'surface',
    'spring',
    /* Kaasulyhty ja sen liekki. Vaaraton on tässä vahvempi väite kuin
     * "koriste": lyhty ei ole kiinteä eikä sen läpi kävelemisestä seuraa
     * mitään muuta kuin tarkistuspiste — liekki on kuva, ei laji tulta. Jos
     * jonain päivänä palava lyhty polttaa, se rivi kuuluu `HURTS`iin ja
     * `playerTiles`iin, ei tänne. */
    'lamp', 'lit',
    /* Rinne, ja tämä on vaarattomien listalla vahvana väitteenä eikä
     * oletuksena: rinne on maata jonka pinta on vinossa, ja maa ei satuta.
     * Se ei ole `solid` (keho kulkee sen läpi vaakasuunnassa, ks.
     * `T.SLOPE_R`), joten se tarvitsee oman lippunsa — ja `standable` on se
     * mikä siitä seuraa: sen päällä seistään. Jos rinteestä joskus tehdään
     * liukas tai satuttava, se rivi kuuluu `HURTS`iin. */
    'slope', 'standable',
    /* Pieruhylly. Vaaraton, ja se on rakenteellista eikä toiveajattelua: hylly
     * on puolikiinteä, eli sen läpi mennään alhaalta ja sen päälle
     * laskeudutaan. Se ei voi sulkea käytävää eikä puristaa ketään. */
    'shelf',
    /* Puu. Vaaraton, ja se on koko sen olemassaolon ehto: puu ei ole kiinteä
     * eikä satuttava, sen läpi kävellään ja se piirtyy pelaajan takana (ks.
     * `T.TREE`). Palava puu satuttaa, mutta palaminen on kohtauksen
     * kirjanpitoa (`LevelScene.burning`) eikä tämän laatan lippu — jos siitä
     * joskus tehdään merkki, se merkki kuuluu `HURTS`iin. */
    'tree'];

  /* Kattavuus ensin: mikään lippu ei saa jäädä luokittelematta. */
  const unknownIn = (table) => [...new Set(Object.values(table).flatMap((i) => Object.keys(i)))]
    .filter((f) => !HURTS.includes(f) && !HARMLESS.includes(f));
  const unclassified = unknownIn(TILE_INFO);
  const flags = HURTS.length + HARMLESS.length;
  expect('jokainen TILE_INFOn lippu on luokiteltu satuttavaksi tai vaarattomaksi',
    unclassified.length === 0,
    unclassified.length
      ? `luokittelematon lippu: ${unclassified.join(' ')} — satuttaako se pelaajaa?`
      : `${flags} lippua luokiteltu, ${HURTS.length} satuttavaa: ${HURTS.join(' ')}`);

  /* Ja se toinen puolisko: että kattavuus osaisi huomata puuttuvan. Punainen
   * ilman että mitään rikotaan — sama tapa kuin `a stale difficulty table is
   * detected, not blessed` -tarkistuksessa. */
  const invented = unknownIn({ ...TILE_INFO, Z: { solid: true, murskaa: true } });
  expect('luokittelematon lippu huomataan, ei siunata',
    invented.length === 1 && invented[0] === 'murskaa',
    `keksitty laatta lipulla "murskaa": ${invented.length ? invented.join(' ') : 'ei huomattu'}`);

  /*
   * Koekenttä: 32 saraketta tasamaata, aloitus, tehostus ensimmäisellä
   * neljänneksellä ja maali. Sama pohja joka merkille, yksi merkki kerrallaan
   * sarakkeeseen 16 lattian päälle — eli sinne mihin pelaaja astuu.
   */
  const W = 32;
  const fixture = (ch) => {
    const rows = Array.from({ length: 16 }, () => ' '.repeat(W));
    const put = (y, s) => { rows[y] = s.padEnd(W, ' ').slice(0, W); };
    put(10, '      !');
    put(13, '  1                         F   ');
    put(14, '#'.repeat(W));
    put(15, '#'.repeat(W));
    rows[13] = `${rows[13].slice(0, 16)}${ch}${rows[13].slice(17)}`;
    return rows;
  };

  const empty = scoreRows(fixture(' '));
  const hurting = Object.entries(TILE_INFO)
    .filter(([, info]) => HURTS.some((f) => info[f]))
    .map(([ch, info]) => ({
      ch,
      why: HURTS.filter((f) => info[f]).join('+'),
      delta: scoreRows(fixture(ch)) - empty,
    }));
  const free = hurting.filter((t) => t.delta <= 0.05);
  const shown = hurting.map((t) => `'${t.ch}' ${t.why} ${t.delta > 0 ? '+' : ''}${t.delta.toFixed(1)}`);
  expect('jokaisella satuttavalla laatalla on hinta vaikeusmittarissa',
    hurting.length > 0 && free.length === 0,
    hurting.length
      ? `sama koekenttä ${empty.toFixed(1)}, yhden merkin erolla: ${shown.join(', ')}`
        + `${free.length ? ` — hinnaton: ${free.map((t) => `'${t.ch}'`).join(' ')}` : ''}`
      : 'TILE_INFOssa ei ole yhtään satuttavaa laattaa — lista on tyhjä, ei vihreä');
  if (free.length) {
    failures.push(...free.map((t) => `'${t.ch}' (${t.why}) maksaa vaikeusmittarissa nollan`));
  }

  report.checks.push(...checks);
  report.failures.push(...failures);
}
/* ---- laattavaarojen hinta: loppu ---- */

{
  const { difficultyTable, compareTable } = await import('./difficulty.mjs');
  const { DIFFICULTY } = await import('../src/data/difficulty.js');
  const measured = difficultyTable();
  const drift = compareTable(DIFFICULTY, measured);
  report.checks.push({
    name: 'the map difficulty table is what the tool measures now',
    ok: drift.length === 0,
    detail: drift.length
      ? `${drift.slice(0, 3).join('; ')} — aja: node tools/difficulty.mjs --write`
      : `${Object.keys(measured).length} kenttää`,
  });
  if (drift.length) {
    report.failures.push(...drift.map((d) => `vaikeustaulu vanhentunut — ${d}`),
      'korjaus: node tools/difficulty.mjs --write');
  }

  /* Red before green: the comparison has to notice all three ways a copy goes
   * stale, or the check above is a decoration that always passes. Built off the
   * measurement rather than off the file, so this stays a test of the
   * comparison even on a run where the file is the thing that is wrong. */
  const first = Object.keys(measured)[0];
  const nudged = { ...measured, [first]: measured[first] + 5 };
  const dropped = { ...measured };
  delete dropped[first];
  const extra = { ...measured, '9-9': 1 };
  report.checks.push({
    name: 'a stale difficulty table is detected, not blessed',
    ok: compareTable(nudged, measured).length === 1
      && compareTable(dropped, measured).length === 1
      && compareTable(extra, measured).length === 1
      && compareTable(measured, measured).length === 0,
    detail: `muutettu ${compareTable(nudged, measured).length}, puuttuva `
      + `${compareTable(dropped, measured).length}, ylimääräinen `
      + `${compareTable(extra, measured).length}`,
  });
  if (!(compareTable(nudged, measured).length === 1
    && compareTable(dropped, measured).length === 1
    && compareTable(extra, measured).length === 1)) {
    report.failures.push('vaikeustaulun vertailu ei huomaa vanhentumista');
  }
}

/*
 * YKSI RUUTU, YKSI UUSI ASIA — opetusjärjestyksen ainoa portti.
 *
 * `tools/curriculum.mjs` mittaa kolmea ehtoa (POHJA, SEURA, YKSIN) ja on
 * raportti eikä portti. Omistaja päätti 9.8.2026 nostaa niistä *yhden*
 * portiksi, koska vain se osoitti toistuvan ja korjattavan vian: YKSIN hylkäsi
 * kuusi ensiesittelyä 26:sta, ja hylätyt tulivat kolmena parina — kolme kenttää
 * joissa kaksi uutta asiaa esitellään samalla ruudulla. POHJA hylkäsi nolla ja
 * SEURA kaksi, eikä kumpikaan kelpaa portiksi ilman että ne ensin korjataan.
 *
 * **Mitä "ensiesittely" tarkoittaa, kun kartta haarautuu.** Maailma 2 haarautuu
 * 2-2:ssa, joten yhdellä ominaisuudella on kolme eri vastausta siihen missä se
 * kohdataan ensin: *earliest* (aikaisin kenttä jollain reitillä), *guaranteed*
 * (kenttä johon mennessä jokainen reitti on sen kohdannut) ja *branch-only*
 * (vain toisella haaralla esiintyvä). **Tämä portti väittää `earliest`istä**,
 * ja syy on että se on pahin tapaus: se on ensimmäinen paikka jossa kukaan voi
 * kohdata asian, ja jos kaksi asiaa on siellä samalla ruudulla, ne ovat samalla
 * ruudulla jollekulle. `guaranteed` sallisi tungoksen niin kauan kuin *toinen*
 * reitti on jo opettanut toisen niistä, mikä on lupaus väärälle pelaajalle.
 *
 * Kulkua ei kävellä täällä uudestaan: `curriculum.mjs` kävelee graafin samoilla
 * säännöillä kuin `worldProblems` (linkit suunnattuja, reitti päättyy
 * linnakkeeseen, talot kävellään läpi), ja tämä tiedosto lukee sen tuloksen.
 * Toinen kävely olisi toinen totuus.
 *
 * Ruutu on 20 laattaa = 320 px, eli canvasin leveys jaettuna laatalla. Se on
 * oikea yksikkö siksi että kysymys ei ole siitä kuinka kaukana kaksi esittelyä
 * on toisistaan tiedostossa vaan siitä näkyvätkö ne yhtä aikaa.
 */
{
  const { CURRICULUM_ROWS, CURRICULUM_INTRO, SCREEN_COLS } = await import('./curriculum.mjs');
  const measured = CURRICULUM_ROWS.filter((r) => r.enc && !r.feature.core);
  const crowded = measured.filter((r) => !r.safety.yksin);
  const where = (r) => `${r.feature.key}@${r.enc.earliest}:${r.inst.x0}`;
  report.checks.push({
    name: `kahta ensiesittelyä ei ole saman ${SCREEN_COLS} laatan ruudun sisällä`,
    ok: crowded.length === 0,
    detail: crowded.length
      ? `${crowded.length}/${measured.length}: ${crowded.map(where).join(' ')}`
      : `${measured.length} ensiesittelyä, väljin pakka ${SCREEN_COLS} laattaa`,
  });
  if (crowded.length) {
    report.failures.push(...crowded.map((r) => `ensiesittely ruudun sisällä toisesta: ${where(r)}`));
  }

  /*
   * JA SAMAN ASIAN TOINEN PUOLI: montako uutta asiaa yksi kenttä esittelee.
   *
   * YKSIN mittaa etäisyyttä, tämä lukumäärää, ja ne eivät ole sama väite. Kenttä
   * voi levittää seitsemän ensiesittelyä 400 sarakkeelle ja läpäistä YKSINin
   * moitteetta — juuri niin 1-2 teki kaikkien muiden paitsi yhden parin osalta —
   * ja silti pyytää pelaajaa oppimaan seitsemän asiaa yhdessä kentässä. 1-2 oli
   * pelin toinen kenttä, mikä on huonoin mahdollinen paikka sille.
   *
   * Raja on **kolme**, eikä se ole pyöristys: kolme oli pelin *seuraavaksi*
   * pahin kenttä ennen tätä korjausta (1-1 ja 1-3, kumpikin kolme), joten raja
   * on mitattu pelistä eikä valittu. Se sanoo "1-2 ei saa olla poikkeus", ei
   * "kolme on oikea luku". Perussanasto ei ole mukana samasta syystä kuin
   * työkalussa: ensimmäisen ruudun aakkosia ei voi aikatauluttaa.
   *
   * MITÄ RAJA LASKEE (17.8.2026). Omistaja kysyi voisiko uusia ominaisuuksia
   * ripotella varhaisiin kenttiin niin että esittelyidea säilyy, ja vastaus
   * löytyi tästä rivistä: raja laski **maaston samaan lukuun vihollisen
   * kanssa**, ja siksi maailman 1 kolme käsintehtyä kenttää olivat "täynnä"
   * yhdeksällä esittelyllä joista kuusi ei ollut kenellekään vaarallinen.
   *
   * Nyt kolmen raja koskee sitä mitä pelaaja voi **hävitä**: vihollisia ja
   * vaaroja. Maasto ja työkalut — rinne, puulava, pavunvarsi, warp-putki,
   * tähtilohko, ponnahduslauta — eivät kuluta samaa budjettia, ja perustelu on
   * se mikä erottaa ne toisistaan: uusi vihollinen on kysymys jonka väärä
   * vastaus maksaa hengen, ja uusi maastonmuoto on kysymys jonka väärä vastaus
   * maksaa sekunnin. Ne eivät ole sama oppimiskustannus, joten niiden ei kuulu
   * jakaa samaa kolmea.
   *
   * **Mikään ei löystynyt siltä puolelta joka mittaa turvallisuutta.** YKSIN
   * (20 laatan väli) koskee yhä jokaista esittelyä lajista riippumatta, ja
   * `tools/curriculum.mjs`:n turvallisuusehdot (lattia alla, tilaa väistää)
   * pätevät maastoon täsmälleen kuten ennenkin. Löysempi on vain se yksi luku
   * joka kysyi "montako uutta asiaa", ja se kysyy nyt "montako uutta tapaa
   * kuolla".
   */
  const risky = (l) => l.features.filter((f) => f.feature.hazard
    || f.feature.key.startsWith('enemy_') || f.feature.key === 'bosscycle');
  const over = CURRICULUM_INTRO.filter((l) => risky(l).length > 3);
  const busiest = CURRICULUM_INTRO.reduce((a, b) => (risky(b).length > risky(a).length ? b : a));
  report.checks.push({
    name: 'yksikään kenttä ei esittele yli kolmea uutta vaaraa',
    ok: over.length === 0,
    detail: over.length
      ? over.map((l) => `${l.id} ${risky(l).length}: ${risky(l).map((f) => f.feature.key).join(' ')}`).join(' — ')
      : `eniten ${busiest.id} ${risky(busiest).length} vaaraa`
        + ` (${busiest.features.length} esittelyä kaikkiaan)`,
  });
  if (over.length) {
    report.failures.push(...over.map((l) => `${l.id} esittelee ${risky(l).length} uutta vaaraa kerralla`));
  }
}

/*
 * LUULINNAKE EI OLE PILVILINNAKE — JOKAISELLA MAAILMALLA ON OMA LINNAKESANASTO.
 *
 * `tools/variety.mjs` mittasi 10.8.2026 sen mitä kukaan ei ollut etsimässä.
 * Kentän uutuus on niiden kahdeksan sarakkeen ikkunoiden osuus, joita peli ei
 * ollut vielä näyttänyt, ja linnakkeissa se luku oli tämä:
 *
 *     6-F 0,0 %   7-F 0,0 %   8-F 0,0 %   3-F 3,0 %
 *
 * Puolet pelin linnakkeista ei siis tuonut peliin yhtään uutta muotoa. Syy oli
 * yhdessä mitassa: `fort_gap` oli **20 paikassa seitsemässä maailmassa** ja
 * `fort_power` kaikissa kahdeksassa, eli maailmojen linnakkeet olivat saman
 * kourallisen palikoita eri järjestyksessä. Omistajan ratkaisu 10.8.2026 oli
 * että jokainen maailma saa oman linnakesanastonsa — maailma 8 oli jo tehnyt
 * sen (`chunks/keep.js`), ja se on tämän muutoksen ennakkotapaus.
 *
 * **Tämä ei ole nahkaväite vaan muotoväite.** Omistaja sanoi saman päivän
 * aikana suoraan ettei teemakohtaisia laattamuotoja tarvita, koska nykyinen
 * värjäys riittää. Sama pohjapiirros toisella värillä mittaisi täsmälleen
 * saman luvun kuin ennen, joten se mitä tässä vaaditaan on **järjestys**: missä
 * kuilut ovat, mitä niiden yllä on, mitä huone pyytää tekemään.
 *
 * Kaksi väitettä, ja ne mittaavat eri asiaa tarkoituksella:
 *
 *   1. **Sanastot ovat olemassa ja ne ovat erillisiä.** Tämä on väite
 *      `chunks/fortresses.js`:n datasta eikä soittolistoista: kahdeksan
 *      maailmaa, jokaisella oma nimetty palikkajoukko, eikä yksikään palikka
 *      kuulu kahteen. Sanasto johdetaan yhdestä taulusta jotta kaksi listaa ei
 *      voi olla eri mieltä.
 *   2. **Linnake ei sekoita kahden maailman sanastoa.** Vanha jaettu
 *      `fort_*`-käytävä on yhä olemassa ja yhä käytössä niissä linnakkeissa
 *      joita ei ole vielä johdotettu, ja se on sallittua — kiellettyä on
 *      rakentaa maailman 7 linnake maailman 6 palikoista, mikä on juuri se
 *      virhe jonka viiden soittolistan liittäminen myöhemmin voi tehdä.
 *
 * Ja yksi luku joka on portti eikä raportti: **montako linnaketta on rakennettu
 * kokonaan oman maailmansa sanastosta.** Se on tässä ratkaisussa se numero joka
 * liikkuu, ja raja on kolme koska kolme on se mihin tämä muutos sen nostaa
 * (1-F, 3-F, 8-F); loput viisi soittolistaa nostavat sen kahdeksaan kun ne
 * liitetään. Rajan tarkoitus on estää paluu taaksepäin, ja sen viereen
 * tulostetaan jokaisen kahdeksan linnakkeen osuus, jotta kesken oleva työ näkyy
 * portin tulosteessa eikä muistilapussa.
 *
 * Aloituspalikka ei ole sanastoa eikä sitä lasketa: jokainen kenttä alkaa
 * aloitusmerkillä, ja `keep_start` on maailman 8 oma vain siksi että jaetun
 * `start`in yllä on taivasta. Pomoareenat eivät myöskään: areena on areena,
 * ja se on nimenomaan se osa jonka jakaminen kannattaa.
 */
{
  const problems = [];
  let detail = '';
  try {
    const { FORTRESS_VOCAB } = await import('../src/data/chunks/fortresses.js');
    const { CHUNKS } = await import('../src/data/chunks.js');
    const { getLevel, levelIds } = await import('../src/data/levels.js');

    const ARENAS = new Set(['boss_arena', 'boss_arena_big', 'baron_arena']);
    const worlds = Object.keys(FORTRESS_VOCAB);
    const owner = new Map();
    for (const w of worlds) {
      for (const name of Object.keys(FORTRESS_VOCAB[w])) {
        if (owner.has(name)) {
          problems.push(`${name} kuuluu sekä maailmalle ${owner.get(name)} että ${w}`);
        }
        owner.set(name, w);
        if (!CHUNKS[name]) problems.push(`${w}: ${name} ei ole pelin palikkataulussa`);
      }
    }
    if (worlds.length !== 8) {
      problems.push(`linnakesanastoja ${worlds.length}, maailmoja 8`);
    }
    for (const w of worlds) {
      const n = Object.keys(FORTRESS_VOCAB[w]).length;
      if (n < 4) problems.push(`${w}: sanastossa ${n} palikkaa, alle neljä ei ole sanasto`);
    }

    const forts = levelIds().filter((id) => id.endsWith('-F'));
    const shares = forts.map((id) => {
      const world = `w${id[0]}`;
      /* Aloituspalikka on ensimmäinen, areenat nimeltä — kumpikaan ei ole sanastoa. */
      const body = (getLevel(id).chunks || []).slice(1).filter((c) => !ARENAS.has(c));
      const own = body.filter((c) => owner.get(c) === world).length;
      const alien = [...new Set(body.filter((c) => owner.has(c) && owner.get(c) !== world))];
      return { id, world, n: body.length, own, alien };
    });
    for (const s of shares) {
      if (s.alien.length) {
        problems.push(`${s.id} käyttää maailman ${owner.get(s.alien[0])} palikoita: ${s.alien.join(' ')}`);
      }
    }
    const pure = shares.filter((s) => s.n > 0 && s.own === s.n);
    if (pure.length < 3) {
      problems.push(`omasta sanastostaan rakennettuja linnakkeita ${pure.length}, vaadittu 3`);
    }
    detail = `${pure.length}/8 linnaketta omasta sanastostaan — `
      + shares.map((s) => `${s.id} ${s.n ? Math.round((s.own / s.n) * 100) : 0} %`).join(', ');
  } catch (err) {
    problems.push(`linnakesanastoja ei päästy lukemaan: ${err && err.message}`);
  }
  report.checks.push({
    name: 'jokaisella maailmalla on oma linnakesanasto eikä linnake sekoita kahta',
    ok: problems.length === 0,
    detail: problems.length ? problems.slice(0, 4).join('; ') : detail,
  });
  if (problems.length) report.failures.push(...problems);
}

/*
 * JUOKSUHIEKKA KOLMESSA PAIKASSA, JA MITÄ VÄÄRÄ LUKUTAPA MAKSAA.
 *
 * ROADMAP kirjaa ansan: uusi ruutumerkki on kolme paikkaa eikä yksi. `TILE_INFO`
 * kertoo mitä merkki *on*, `src/data/rules.js` mitä validaattori siitä ajattelee
 * ja `tools/gen-levels.mjs` mitä generaattori siitä ajattelee — ja kaksi
 * jälkimmäistä ovat kopioita, koska validaattori ei saa importoida generaattoria
 * eikä toisin päin. Kopio on halvempi kuin sidos vain niin kauan kuin joku
 * tarkistaa että kopiot ovat samat, ja tämä on se tarkistus.
 *
 * Väärä lukutapa ei kaada mitään, se vain valehtelee. Hiekka kuiluna hylkäisi
 * kelvollisia kenttiä ja pakottaisi astinkiven paikkaan jossa sellaista ei
 * tarvita; hiekka tavallisena maana siunaisi lammikon jolla ei ole pohjaa, eli
 * pohjattoman kuilun jonka päälle on maalattu hiekkaa. Molemmat testataan
 * rikkinäisellä koekentällä, koska sääntö jota on koeteltu vain toimivalla
 * sisällöllä ei ole koeteltu millään.
 */
{
  const { validateLevel, RULE_CONSTANTS } = await import('../src/data/rules.js');
  const { scoreRows } = await import('./difficulty.mjs');
  const budget = JSON.parse(await readFile(join(ROOT, 'tools/jump-budget.json'), 'utf8'));

  /* Yksi koekenttä, 32 saraketta: tasamaata, keskellä yhden ruudun korkuinen
   * hiekkatörmä ja siihen kaivettu kahden ruudun syvyinen lammikko. Sama pohja
   * joka vialle, yksi vika kerrallaan. */
  const fixture = (over = {}) => {
    const rows = Array.from({ length: 16 }, () => ' '.repeat(32));
    const put = (y, s) => { rows[y] = s.padEnd(32, ' ').slice(0, 32); };
    put(10, '      !');
    put(13, '  1             XXX~~~XXXX  F   ');
    put(14, '################XXX~~~XXXX######');
    put(15, '################################');
    for (const [y, s] of Object.entries(over)) put(Number(y), s);
    return rows;
  };

  const clean = validateLevel(fixture(), budget);
  const sandProblems = (list) => list.filter((p) => /hiekk|quicksand/i.test(p));

  report.checks.push({
    name: 'kelvollinen hiekkalammikko ei ole validaattorille ongelma',
    ok: clean.length === 0,
    detail: clean.length ? clean.join('; ') : '32 saraketta, 3 ruutua hiekkaa, ei huomautuksia',
  });
  if (clean.length) report.failures.push(...clean.map((p) => `hiekkakoekenttä: ${p}`));

  /* Pohjaton lammikko: hiekka maalattu kuilun päälle. Tämä on se tapaus jossa
   * "hiekka on tavallista maata" menisi hiljaa läpi. */
  const noFloor = validateLevel(fixture({
    14: '################XXX~~~XXXX######',
    15: '###################   ##########',
  }), budget);
  report.checks.push({
    name: 'pohjaton hiekkalammikko raportoidaan, ei siunata maana',
    ok: sandProblems(noFloor).length > 0,
    detail: sandProblems(noFloor)[0] || `ei huomautusta hiekasta (${noFloor.join('; ') || 'ei mitään'})`,
  });
  if (!sandProblems(noFloor).length) {
    report.failures.push('validaattori ei huomaa hiekkaa pohjattoman kuilun päällä');
  }

  /* Yhdeksän saraketta hiekkaa on leveämpi kuin hyppybudjetti kantaa — ja silti
   * ei kuilu, koska hiekasta noustaan pintaan ja kahlataan yli. Jos tämä alkaa
   * raportoida "gap of 9", validaattori on alkanut lukea hiekkaa kuiluna. */
  const wide = validateLevel(fixture({
    13: '  1          XXX~~~~~~~~~XXX F  ',
    14: '#############XXX~~~~~~~~~XXX####',
  }), budget);
  report.checks.push({
    name: 'leveä hiekkalammikko ei ole kuilu',
    ok: !wide.some((p) => p.startsWith('gap of')),
    detail: wide.some((p) => p.startsWith('gap of'))
      ? wide.filter((p) => p.startsWith('gap of')).join('; ')
      : `9 saraketta hiekkaa, hyppybudjetti ${budget.gapTiles} — ei kuiluhuomautusta`,
  });
  if (wide.some((p) => p.startsWith('gap of'))) {
    report.failures.push('validaattori lukee hiekkalammikon kuiluna');
  }

  /* Ja kuoppa jonka reunalle ei nousta. Varoaika tekee sijoittelusta koko työn:
   * hiekka aukealla on säikähdys, hiekka kaivossa on ansa. */
  const walled = validateLevel(fixture({
    7: '                XXX   XXXX      ',
    8: '                XXX   XXXX      ',
    9: '                XXX   XXXX      ',
    10: '      !         XXX   XXXX      ',
    11: '                XXX   XXXX      ',
    12: '                XXX   XXXX      ',
    13: '                XXX   XXXX      ',
    14: '  1             XXX~~~XXXX  F   ',
  }), budget);
  report.checks.push({
    name: 'hiekkakuoppa jonka reunalle ei nousta raportoidaan',
    ok: sandProblems(walled).some((p) => /reuna|rim/i.test(p)),
    detail: sandProblems(walled)[0] || 'ei huomautusta seinien sisään kaivetusta kuopasta',
  });
  if (!sandProblems(walled).some((p) => /reuna|rim/i.test(p))) {
    report.failures.push('validaattori ei huomaa hiekkakuoppaa josta ei pääse ulos');
  }

  /* Sama virhe jonka piikkikävelijä teki tänä aamuna: uhka jota mittari ei näe.
   * Kaksi identtistä kenttää, toisessa hiekkaa — jos luku ei nouse, maailman 2
   * käyrä on väärä ja `verify.mjs`:n muototarkistus mittaa väärää kenttää. */
  const withSand = scoreRows(fixture());
  const withoutSand = scoreRows(fixture({
    13: '  1             XXXXXXXXXX  F   ',
    14: '################XXXXXXXXXX######',
  }));
  report.checks.push({
    name: 'vaikeusmittari näkee juoksuhiekan',
    ok: withSand > withoutSand + 0.5,
    detail: `sama kenttä hiekalla ${withSand.toFixed(1)}, ilman ${withoutSand.toFixed(1)} `
      + `(+${(withSand - withoutSand).toFixed(1)})`,
  });
  if (!(withSand > withoutSand + 0.5)) {
    report.failures.push('vaikeusmittari pisteyttää juoksuhiekan nollaksi');
  }

  /*
   * KEINUVA VIHOLLINEN, JA SE MIKSI TÄMÄ SÄÄNTÖ ON OLEMASSA.
   *
   * Ruskean pilven merkki on sen keinun keskiviiva eikä ruutu johon se jää, ja
   * ero on kokonainen laatta alaspäin (`STINK_BOB_ROWS`). 7-P:ssä se maksoi
   * juuri sen mitä tällaiset erot maksavat: pilvi rivillä 42 lattian ollessa
   * 43 oli seinän sisällä aina kun arvottu vaihe osui alaspäin, eli noin 43 %
   * ajoista. Portti *näki* sen — mutta satunnaisesti, ja satunnaisesti näkevä
   * portti opettaa ajamaan uudestaan.
   *
   * Kaksi koetta samasta pohjasta, koska laukeaminen ilman ei-laukeamista ei
   * mittaa sääntöä vaan sen olemassaoloa: rivi ylempänä on puhdas, lattian
   * päällä raportoidaan. Se yhden rivin ero **on** koko sääntö.
   */
  /** Tasamaata, lattia rivillä 13, ja yksi pilvi rivillä `y` sarakkeessa 12. */
  const cloudFix = (y) => {
    const rows = Array.from({ length: 16 }, () => ' '.repeat(32));
    const put = (ty, s) => { rows[ty] = s.padEnd(32, ' ').slice(0, 32); };
    put(10, '      !');
    put(13, '  1                         F   ');
    put(14, '################################');
    put(15, '################################');
    put(y, `${rows[y].slice(0, 12)}r${rows[y].slice(13)}`);
    return rows;
  };
  const bobProblems = (list) => list.filter((p) => /bobs into/.test(p));

  const highCloud = validateLevel(cloudFix(12), budget);
  report.checks.push({
    name: 'lattian yläpuolella keinuva pilvi ei ole validaattorille ongelma',
    ok: bobProblems(highCloud).length === 0,
    detail: bobProblems(highCloud)[0]
      || `merkki rivillä 12, lattia rivillä 14 — keinu yltää riville ${12 + RULE_CONSTANTS.STINK_BOB_ROWS}`,
  });
  if (bobProblems(highCloud).length) {
    report.failures.push(...bobProblems(highCloud).map((p) => `pilvikoekenttä: ${p}`));
  }

  const lowCloud = validateLevel(cloudFix(13), budget);
  report.checks.push({
    name: 'lattiaan asti keinuva pilvi raportoidaan, ei siunata ilmaksi',
    ok: bobProblems(lowCloud).length > 0,
    detail: bobProblems(lowCloud)[0]
      || `ei huomautusta keinusta (${lowCloud.join('; ') || 'ei mitään'})`,
  });
  if (!bobProblems(lowCloud).length) {
    report.failures.push('validaattori ei huomaa pilveä joka keinuu lattian sisään');
  }

  /*
   * JÄÄ, JA SE MITÄ SEN SÄÄNTÖ EI SANO.
   *
   * `checkIce` on tarkoituksella kapea: yksi asetelma, ei reunasääntöä. Kapea
   * sääntö on helppo koetella väärin — jos testataan vain että se laukeaa, ei
   * ole mitattu mitään siitä ettei se laukea joka paikassa. Siksi tässä on
   * kolme koetta eikä yksi, ja keskimmäinen on se tärkein:
   *
   *   1. tavallinen jäätasanko kiinteän maan päällä on puhdas
   *   2. **riittävän leveä kelluva jäälautta on puhdas** — eli sääntö ei ole
   *      "jää kuilun päällä on kielletty" vaan "sen päällä on mahduttava
   *      pysähtymään", ja se ero on koko sääntö
   *   3. liian kapea kelluva jäälautta raportoidaan
   */
  {
    const iceFix = (over = {}) => {
      const rows = Array.from({ length: 16 }, () => ' '.repeat(32));
      const put = (y, s) => { rows[y] = s.padEnd(32, ' ').slice(0, 32); };
      put(10, '      !');
      put(13, '  1                         F   ');
      put(14, '#########IIIIIIII###############');
      put(15, '################################');
      for (const [y, s] of Object.entries(over)) put(Number(y), s);
      return rows;
    };
    const iceProblems = (list) => list.filter((p) => /ice island/i.test(p));

    const flat = validateLevel(iceFix(), budget);
    report.checks.push({
      name: 'jäätasanko kiinteän maan päällä ei ole validaattorille ongelma',
      ok: flat.length === 0,
      detail: flat.length ? flat.join('; ') : '32 saraketta, 8 laattaa jäätä, ei huomautuksia',
    });
    if (flat.length) report.failures.push(...flat.map((p) => `jääkoekenttä: ${p}`));

    /* Viiden laatan lautta kuilun päällä: tasan `ICE_BRAKE`, eli se saa mennä
     * läpi. Jos tämä alkaa raportoida, sääntö on lakannut olemasta mitta ja
     * muuttunut kielloksi. */
    const wideRaft = validateLevel(iceFix({
      14: '######   IIIII   ###############',
      15: '######   #####   ###############',
    }), budget);
    report.checks.push({
      name: 'kyllin leveä kelluva jäälautta kelpaa — sääntö on mitta eikä kielto',
      ok: iceProblems(wideRaft).length === 0,
      detail: iceProblems(wideRaft)[0]
        || `5 laattaa jäätä kuilun päällä, ICE_BRAKE ${RULE_CONSTANTS.ICE_BRAKE} — ei huomautusta`,
    });
    if (iceProblems(wideRaft).length) {
      report.failures.push('validaattori hylkää jäälautan joka on kyllin leveä pysähtyä');
    }

    /* Kolmen laatan lautta: sille laskeudutaan kaaressa eikä sen päällä ehdi
     * pysähtyä, ja se on tasan se asetelma jota mikään muu sääntö ei näe. */
    const narrowRaft = validateLevel(iceFix({
      14: '######   III     ###############',
      15: '######   ###     ###############',
    }), budget);
    report.checks.push({
      name: 'liian kapea kelluva jäälautta raportoidaan',
      ok: iceProblems(narrowRaft).length > 0,
      detail: iceProblems(narrowRaft)[0]
        || `ei huomautusta (${narrowRaft.join('; ') || 'ei mitään'})`,
    });
    if (!iceProblems(narrowRaft).length) {
      report.failures.push('validaattori siunaa jäälautan jolta liu\'utaan kuiluun');
    }

    /* Ja sama koe kuin hiekalla ja piikkikävelijällä: uhka jota mittari ei näe
     * on uhka joka vääristää maailman käyrän. Jään hinta on tarkkuudessa, joten
     * vertailukenttä on sama tasanko kivenä. */
    const withIce = scoreRows(iceFix({
      14: '######   IIIII   ###############',
      15: '######   #####   ###############',
    }));
    const withoutIce = scoreRows(iceFix({
      14: '######   #####   ###############',
      15: '######   #####   ###############',
    }));
    report.checks.push({
      name: 'vaikeusmittari näkee jään',
      ok: withIce > withoutIce + 0.5,
      detail: `sama lautta jäänä ${withIce.toFixed(1)}, kivenä ${withoutIce.toFixed(1)} `
        + `(+${(withIce - withoutIce).toFixed(1)})`,
    });
    if (!(withIce > withoutIce + 0.5)) {
      report.failures.push('vaikeusmittari pisteyttää jään nollaksi');
    }
  }

  /*
   * PYSTYKENTTÄ, JA KOLME TYÖKALUA JOTKA EIVÄT TIENNEET ETTÄ YLÖS ON SUUNTA.
   *
   * Sama kuria kuin hiekalla yllä: yksi koekenttä, yksi vika kerrallaan, ja
   * sama kenttä ilman vikoja on puhdas. Ero on siinä että tässä koekenttä on
   * kokonaan uusi *muoto* eikä uusi ruutumerkki — 20 saraketta (yksi ruutu,
   * ks. `VERTICAL_COLS`) ja 48 riviä, kolmentoista lankun tikkaat kolmen
   * ruudun välein, tehostuspalikka alimmassa neljänneksessä, kallio pohjalla
   * koska putoaminen on takaisku eikä kuolema, lippu ylhäällä.
   *
   * **Rivimäärä on kolme kokonaista kaistaa eikä pyöreä luku**, ja se on ehto
   * eikä maku: vaakalukija paloittelee korkean kentän `ROWS`:n mittaisiin
   * kaistoihin, joten ruudukko joka ei jakaudu tasan ei ole sille korkea kenttä
   * vaan sekava. Kaistan kasvettua viidestätoista kuuteentoista riviin tämä
   * koekenttä oli yhä 45-rivinen — kolme vanhaa kaistaa — ja vaakaluku romahti
   * yhteen huomautukseen ("cannot tell which band is the route", eli punainen
   * lakkasi olemasta se punainen jonka se väittää olevansa). Nyt 48 riviä, ja
   * jokainen rivinumero alla siirtyi kolmella.
   *
   * **Punainen sanoi ensin tämän**, ja se on kirjattu koska se on koko syy
   * siihen että pystykäsittely on olemassa: sama ruudukko vaakasuoraan luettuna
   * raportoi seitsemän ongelmaa joista yksikään ei ole totta —
   * `no power-up in the first quarter`, neljä kertaa `platform at … leads to
   * nothing`, ja kahdesti `nothing leads into the sky band`. Vaikeusmittari
   * lukee samasta ruudukosta **80.5** pistettä (jaettuna sarakeleveydellä 20)
   * kun oikea, riveinä luettu luku on **108.4**; ensimmäinen pystyversio antoi
   * aikanaan 1920.5. Kaikki nämä luvut on mitattu uudelleen 48 riville.
   */
  {
    const W = 20;
    const H = 48;
    const climb = (over = {}) => {
      const rows = Array.from({ length: H }, () => ' '.repeat(W));
      const put = (y, s) => { rows[y] = s.padEnd(W, ' ').slice(0, W); };
      put(6, '              F     ');
      [7, 10, 13, 16, 19, 22, 25, 28, 31, 34, 37, 40, 43].forEach((y, i) => {
        /* Ei jaettua saraketta, ks. `checkClimbTraverse`. Tämä koekenttä oli
         * kirjoitettu samalla päällekkäisellä lankulla kuin 7-T, ja kun sääntö
         * tuli, se kaatoi molemmat — mikä on juuri se mitä koekentän kuuluu
         * tehdä: se on kelvollisen kiipeilyn määritelmä, joten sen on täytettävä
         * jokainen sääntö jonka kelvollisen kiipeilyn on täytettävä. */
        put(y, i % 2 === 0 ? '          --------- ' : ' ---------          ');
      });
      put(42, '     !              ');
      put(45, '  1                 ');
      put(46, '####################');
      put(47, '####################');
      for (const [y, s] of Object.entries(over)) put(Number(y), s);
      return rows;
    };
    const vert = (over) => validateLevel(climb(over), budget, { vertical: true });

    const clean = vert();
    report.checks.push({
      name: 'kelvollinen pystykenttä ei ole validaattorille ongelma',
      ok: clean.length === 0,
      detail: clean.length ? clean.join('; ') : '20 saraketta, 48 riviä, 13 lankkua, ei huomautuksia',
    });
    if (clean.length) report.failures.push(...clean.map((p) => `pystykoekenttä: ${p}`));

    /* Sama ruudukko vaakasääntöjen läpi: tämä on se punainen, ja se on tässä
     * väitteenä eikä muistiinpanona — jos joku joskus poistaa `opts.vertical`
     * -haaran, tämä rivi kertoo mitä sen tilalle tulee. */
    const asFlat = validateLevel(climb(), budget);
    report.checks.push({
      name: 'vaakasäännöt lukevat pystykentän väärin — siksi haara on olemassa',
      ok: asFlat.length >= 5 && clean.length === 0,
      detail: `vaakana ${asFlat.length} huomautusta (${asFlat[0]}), pystynä ${clean.length}`,
    });
    if (!(asFlat.length >= 5)) {
      report.failures.push('vaakasäännöt eivät enää eroa pystysäännöistä koekentällä');
    }

    /* Neljä vikaa, yksi kerrallaan. Jokainen on pystyakselin vastine jollekin
     * vaakasäännölle, ja jokaisen pitää löytyä nimeltä eikä sivutuotteena. */
    const faults = [
      ['liian korkea loikka raportoidaan', { 37: '                    ' }, /the climb stops at/],
      ['pohjaton sarake raportoidaan', { 46: '########  ##########', 47: '########  ##########' },
        /has no floor at the bottom/],
      ['piikit putoamisen päässä raportoidaan', { 45: '  1     ^^^^        ' },
        /lands you on "\^"/],
      ['tehostus alkuneljänneksen ulkopuolella raportoidaan', { 42: '                    ' },
        /first quarter of the climb/],
      ['umpiperä jonka päällä ei ole mitään raportoidaan', { 24: '               ---- ' },
        /stairway to nothing/],
    ];
    for (const [name, over, re] of faults) {
      const got = vert(over);
      const hit = got.find((p) => re.test(p));
      report.checks.push({ name, ok: !!hit, detail: hit || `ei huomautusta (${got.join('; ') || 'ei mitään'})` });
      if (!hit) report.failures.push(`pystyvalidaattori ei huomaa: ${name}`);
    }

    /* Leveys ei ole enimmäismäärä vaan leveys: 21 saraketta antaisi kiipeilylle
     * vaakavierivän kameran, joka on tasan se mitä muodossa ei saa olla. */
    const wide = validateLevel(climb().map((r) => `${r} `), budget, { vertical: true });
    report.checks.push({
      name: 'yhtä saraketta liian leveä pystykenttä raportoidaan',
      ok: wide.some((p) => /columns wide/.test(p)),
      detail: wide.find((p) => /columns wide/.test(p)) || 'ei huomautusta leveydestä',
    });
    if (!wide.some((p) => /columns wide/.test(p))) {
      report.failures.push('pystyvalidaattori hyväksyy näyttöä leveämmän kiipeilyn');
    }

    /* Ja mittari. Kaksi lukua samasta ruudukosta: vaakana se on hölynpölyä
     * (jaettuna 20 sarakkeella eikä 48 rivillä), pystynä se on maailman 1
     * tason luokkaa. Väitetään haarukkana eikä tarkkana lukuna, koska tarkka
     * luku olisi tämän koekentän ominaisuus eikä mittarin. */
    const upScore = scoreRows(climb(), { vertical: true });
    const flatScore = scoreRows(climb());
    report.checks.push({
      name: 'vaikeusmittari mittaa kiipeilyn riveinä eikä sarakkeina',
      ok: upScore > 60 && upScore < 200 && Math.abs(upScore - flatScore) > 20,
      detail: `pystynä ${upScore.toFixed(1)}, vaakana luettuna ${flatScore.toFixed(1)}`,
    });
    if (!(upScore > 60 && upScore < 200)) {
      report.failures.push(`vaikeusmittari antaa kiipeilylle ${upScore.toFixed(1)} pistettä`);
    }

    /* Ja se että mittari näkee kiipeilyn vaikeuden: kaksi identtistä tikapuuta,
     * toisen askel yhtä ruutua korkeampi. Sama vika jonka piikkikävelijä teki. */
    const steeper = scoreRows(climb({ 37: '                    ', 36: '         ---------- ' }), { vertical: true });
    report.checks.push({
      name: 'vaikeusmittari näkee korkeamman askelman',
      ok: steeper > upScore + 0.5,
      detail: `kolmen ruudun askel ${upScore.toFixed(1)}, neljän ${steeper.toFixed(1)} `
        + `(+${(steeper - upScore).toFixed(1)})`,
    });
    if (!(steeper > upScore + 0.5)) {
      report.failures.push('vaikeusmittari pisteyttää neljän ruudun askelman kuin kolmen');
    }

    /* Kaksi kopiota, kuten hiekalla: ruudun leveys on `src/scenes/level.js`:ssä
     * ja `src/data/rules.js`:ssä, eikä validaattori saa importoida kohtausta. */
    const camSrc = await readFile(join(ROOT, 'src/scenes/level.js'), 'utf8');
    const viewW = Number((camSrc.match(/export const VIEW_W = (\d+)/) || [])[1]);
    const tilePx = Number((await readFile(join(ROOT, 'src/gfx/tiles.js'), 'utf8'))
      .match(/export const TILE = (\d+)/)[1]);
    report.checks.push({
      name: 'pystykentän leveys on sama luku kuin ruudun leveys',
      ok: viewW / tilePx === RULE_CONSTANTS.VERTICAL_COLS,
      detail: `VIEW_W ${viewW} / TILE ${tilePx} = ${viewW / tilePx}, `
        + `rules.js sanoo ${RULE_CONSTANTS.VERTICAL_COLS}`,
    });
    if (viewW / tilePx !== RULE_CONSTANTS.VERTICAL_COLS) {
      report.failures.push('VERTICAL_COLS ei vastaa ruudun leveyttä');
    }

    /*
     * JA SAMA KORKEUDELLE, ja tämä portti on olemassa siksi että sen puuttuminen
     * maksoi jo kerran.
     *
     * `tools/difficulty.mjs`in `SCREEN_ROWS` oli 13 (= vanha `VIEW_H` 208 / 16)
     * vielä sen jälkeen kun HUD-nauha purettiin 17.8.2026 ja ikkuna kasvoi
     * 240:een. Luku ei kaada mitään eikä näy missään — se vain lukee
     * kiipeilykentän putoamiset **kaksi laattaa liian aikaisin** kuvan
     * ulkopuolelle vieviksi, eli kolmen kentän vaikeusluku oli mitattu
     * ruudulla jota ei ole. Leveydellä oli portti ja korkeudella ei; nyt on.
     */
    const diffSrc = await readFile(join(ROOT, 'tools/difficulty.mjs'), 'utf8');
    const viewH = Number((camSrc.match(/export const VIEW_H = (\d+)/) || [])[1]);
    const screenRows = Number((diffSrc.match(/const SCREEN_ROWS = (\d+)/) || [])[1]);
    report.checks.push({
      name: 'vaikeusmittarin ruutukorkeus on sama luku kuin ruudun korkeus',
      ok: !!viewH && viewH / tilePx === screenRows,
      detail: `VIEW_H ${viewH} / TILE ${tilePx} = ${viewH / tilePx}, `
        + `difficulty.mjs sanoo ${screenRows}`,
    });
    if (!viewH || viewH / tilePx !== screenRows) {
      report.failures.push('SCREEN_ROWS ei vastaa ruudun korkeutta');
    }
  }

  /* Kolme paikkaa, ja kaksi niistä on tarkoituksellisia kopioita. Verrataan
   * merkkijonoina: se on ainoa tapa huomata että toinen kopio jäi päivittämättä. */
  const src = {
    tiles: await readFile(join(ROOT, 'src/gfx/tiles.js'), 'utf8'),
    rules: await readFile(join(ROOT, 'src/data/rules.js'), 'utf8'),
    /* Kopio on siellä missä se koodi jota se palvelee: `SOLID`, `SINK` ja
     * `ENEMY` seurasivat `validateGenerated`ia `src/data/generator.js`:ään kun
     * generaattorin ydin siirrettiin selaimen ulottuville. Sama väite, uusi
     * osoite — ja osoite luetaan tässä eikä muistista juuri siksi. */
    gen: await readFile(join(ROOT, 'src/data/generator.js'), 'utf8'),
    diff: await readFile(join(ROOT, 'tools/difficulty.mjs'), 'utf8'),
    orig: await readFile(join(ROOT, 'tools/originality.mjs'), 'utf8'),
  };
  const sinkLine = /const SINK = new Set\(\[[^\]]*\]\);/;
  const inRules = (src.rules.match(sinkLine) || [])[0];
  const inGen = (src.gen.match(sinkLine) || [])[0];
  const inOrig = (src.orig.match(sinkLine) || [])[0];
  const places = [
    ['src/gfx/tiles.js', /QUICKSAND: '~'/.test(src.tiles) && /\[T\.QUICKSAND\]:/.test(src.tiles)],
    ['src/data/rules.js', !!inRules && inRules.includes("'~'")],
    ['src/data/generator.js', !!inGen && inGen === inRules],
    /* A FOURTH COPY APPEARED, and this line is what stops it from being the one
     * that rots. `tools/originality.mjs` folds every character it does not
     * recognise into air before comparing against the corpus, so a tile missing
     * from its sets is compared as if the level had a hole where the tile is —
     * exactly the failure the comment in rules.js describes, one module further
     * out. The comment in generator.js says the fourth copy is the moment to
     * move the set into `src/gfx/tiles.js`; that is still true and still not
     * done, so until it is, the copy is checked as a string like the others. */
    ['tools/originality.mjs', !!inOrig && inOrig === inRules],
    ['tools/difficulty.mjs', /QUICKSAND_COST|'~'/.test(src.diff)],
  ];
  const missing = places.filter(([, ok]) => !ok).map(([f]) => f);
  report.checks.push({
    name: 'uusi ruutumerkki on kaikissa paikoissa joissa sen pitää olla',
    ok: missing.length === 0,
    detail: missing.length ? `puuttuu: ${missing.join(', ')}`
      : `${places.length} paikkaa, rules.js ja generator.js sanasanaisesti samat`,
  });
  if (missing.length) report.failures.push(...missing.map((f) => `~ puuttuu tiedostosta ${f}`));

  /*
   * DESIGN.md kohta 8: kuva ja ääni yhdessä, eikä kumpikaan saa lukea väärin.
   * Äänen väärä lukutapa on laava tai vesi, ja ne molemmat ovat pyyhkäisyjä —
   * yksi suodin joka liukuu. Hiekka on rakeita: monta lyhyttä purskausta
   * peräkkäin. Sitä ei voi mitata korvalla testissä, mutta rakenteen voi lukea,
   * ja rakenne on juuri se päätös joka muuten kumoutuisi hiljaa.
   */
  const audio = await readFile(join(ROOT, 'src/core/audio.js'), 'utf8');
  const body = (name) => {
    const at = audio.indexOf(`\n  ${name}: () => {`);
    if (at < 0) return '';
    return audio.slice(at, audio.indexOf('\n  },', at));
  };
  const sink = body('upota');
  // Rakeita voi olla kirjoitettuna joko peräkkäisinä kutsuina tai silmukkana;
  // väite koskee niiden lukumäärää, ei kirjoitusasua.
  const loop = sink.match(/i < (\d+); i\+\+/);
  const grains = Math.max((sink.match(/noise\(/g) || []).length,
    loop && sink.includes('noise(') ? Number(loop[1]) : 0);
  report.checks.push({
    name: 'hiekan ääni on rakeita eikä pyyhkäisy, eikä se ole märkä',
    ok: grains >= 4 && !sink.includes('farty('),
    detail: sink ? `${grains} rakeista purskausta, farty: ${sink.includes('farty(') ? 'on' : 'ei'}`
      : 'ääntä upota ei ole',
  });
  if (!(grains >= 4 && !sink.includes('farty('))) {
    report.failures.push('juoksuhiekan ääni ei erotu laavasta ja vedestä rakenteeltaan');
  }
}

/* ------------------------------ päivän pieru ----------------------------- */
/*
 * Selaimessa generoitu kenttä, ja ne kaksi lupausta jotka se ei voi itse pitää.
 *
 * Päivän pieru rakentaa kenttänsä sivulla, samoista tilastoista ja samoilla
 * säännöillä kuin `tools/gen-levels.mjs`. Kaksi asiaa ei kulje mukana selaimeen
 * eikä kumpaakaan voi teeskennellä:
 *
 *   **alkuperäisyys** (DESIGN.md kohta 3) vaatii korpuksen, jota ei ole
 *   repossa eikä julkaisussa. Selaimessa generoitu kenttä olisi siis
 *   rakenteeltaan `not checked`.
 *
 *   **maareitti voimatasolla 0** (DESIGN.md kohta 5) todistetaan botilla
 *   (`tools/playable.mjs`), eikä botti aja pelaajan selaimessa.
 *
 * Vastaus on `src/data/daily-origin.js`: **siemenavaruus on äärellinen ja
 * lueteltavissa**, koska päivän kenttä on funktio päivämäärästä. Joten se
 * luetellaan etukäteen — `tools/daily-origin.mjs` generoi jokaisen päivän
 * kentän, vertaa sen korpukseen ja pelaa sen botilla läpi voimatasolla 0 — ja
 * repoon jää **pelkkä tuomio**, ei korpusta eikä kenttiä.
 *
 * Tuomio on kuitenkin tuomio *jostakin*, ja tässä mitataan mistä: sormenjälki
 * on niistä tiedostoista jotka määräävät mitä kenttä on. Jos generaattori,
 * rytmiluvut, hyppybudjetti tai päivän oma resepti muuttuu, tuomio koskee eri
 * kenttiä kuin ne jotka pelaaja saa — ja tämä portti punastuu silloin ja vain
 * silloin. Kalenteri ei punasta sitä: umpeutuva ikkuna on varoitus, koska
 * pysyvästi punainen portti sammutetaan.
 */
{
  const { createHash } = await import('node:crypto');
  const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);

  /* 1. Kannettu kopio on sama kuin mittaus. */
  {
    const statsJson = JSON.parse(await readFile(join(ROOT, 'tools/pacing-stats.json'), 'utf8'));
    const budgetJson = JSON.parse(await readFile(join(ROOT, 'tools/jump-budget.json'), 'utf8'));
    let mirror = null;
    try {
      mirror = await import(join(ROOT, 'src/data/pacing.js'));
    } catch (err) {
      mirror = { error: err.message };
    }
    const statsOk = !!mirror.PACING_STATS && eq(mirror.PACING_STATS, statsJson);
    const budgetOk = !!mirror.JUMP_BUDGET && eq(mirror.JUMP_BUDGET, budgetJson);
    const detail = mirror.error ? mirror.error
      : `pacing ${statsOk ? 'sama' : 'ERI'}, hyppybudjetti ${budgetOk ? 'sama' : 'ERI'}`
        + ` (gapTiles ${budgetJson.gapTiles}, wallTiles ${budgetJson.wallTiles})`;
    report.checks.push({
      name: 'selaimen kopio rytmiluvuista on sama kuin mitattu',
      ok: statsOk && budgetOk,
      detail,
    });
    if (!(statsOk && budgetOk)) {
      report.failures.push('src/data/pacing.js ei vastaa mitattua — aja: node tools/mirror-pacing.mjs');
    }
  }

  const daily = await import(join(ROOT, 'src/core/daily.js'));
  const { DAILY_ORIGIN } = await import(join(ROOT, 'src/data/daily-origin.js'));
  const today = daily.dayNumber();

  /* 2. Todistus on tuomio NÄISTÄ kentistä.
   *
   * Sormenjälki lasketaan uudestaan ikkunan jokaisen päivän riveistä. Se on
   * ainoa tapa huomata se hiljainen vika jota vastaan koko rakenne on: joku
   * muuttaa generaattoria, rytmilukuja tai päivän reseptiä, pelaaja saa eri
   * kentät kuin ne jotka tarkistettiin, eikä mikään sano mitään. */
  {
    const hash = createHash('sha256');
    let attemptsOk = true;
    for (let day = DAILY_ORIGIN.from; day <= DAILY_ORIGIN.to; day++) {
      const cert = daily.dailyCertificate(day);
      if (!cert) { attemptsOk = false; break; }
      const { def, problems } = daily.dailyBuild(day, cert.attempt);
      if (problems.length) { attemptsOk = false; break; }
      hash.update(`${day}:${cert.attempt}\n${def.rows.join('\n')}\n`);
    }
    const mine = hash.digest('hex').slice(0, 16);
    const ok = attemptsOk && mine === DAILY_ORIGIN.fingerprint;
    const span = DAILY_ORIGIN.to - DAILY_ORIGIN.from + 1;
    report.checks.push({
      name: 'päivän kenttien todistus koskee juuri niitä kenttiä jotka peli rakentaa',
      ok,
      detail: ok ? `${span} päivää, sormenjälki ${mine}, merkintä "${DAILY_ORIGIN.origin}"`
        : `todistus ${DAILY_ORIGIN.fingerprint}, kentät ${mine}`,
    });
    if (!ok) {
      report.failures.push('src/data/daily-origin.js on vanhentunut — aja: '
        + 'VGLC_DIR="…" node tools/daily-origin.mjs');
    }
  }

  /* 3. Ikkuna kattaa tämän päivän.
   *
   * Varoitus eikä kaatava portti, ja se on DESIGN.md kohdan 3 oma perustelu:
   * pysyvästi punainen portti sammutetaan. Kalenteri ei ole vika kenessäkään,
   * mutta umpeutuva ikkuna on asia joka pitää nähdä ajoissa — ja pelaajan
   * puolella se ei ole hiljainen, koska tila kieltäytyy tarjoamasta kenttää. */
  {
    const left = DAILY_ORIGIN.to - today + 1;
    report.checks.push({
      name: 'päivän pierun ikkuna kattaa tämän päivän',
      ok: today >= DAILY_ORIGIN.from && today <= DAILY_ORIGIN.to,
      detail: `${left} päivää jäljellä (${daily.dayLabel(DAILY_ORIGIN.from)} … `
        + `${daily.dayLabel(DAILY_ORIGIN.to)})`,
    });
    if (today > DAILY_ORIGIN.to || today < DAILY_ORIGIN.from) {
      console.log('\n  HUOM: päivän pierun tarkistusikkuna ei kata tätä päivää.');
      console.log('  Tila ei tarjoa kenttää ennen kuin ikkuna uusitaan:');
      console.log('    VGLC_DIR="…" node tools/daily-origin.mjs\n');
    } else if (left < 90) {
      console.log(`\n  HUOM: päivän pierun ikkunaa on jäljellä ${left} päivää.\n`);
    }
  }

  /* 4. Korpuksen kanssa: tuomio tarkistetaan otoksella eikä uskota.
   *
   * Sama muoto kuin `originality.mjs`illa toimitetuille kentille — ilman
   * korpusta ei väitetä mitään, korpuksen kanssa väite mitataan. Otos eikä
   * kaikki 1096, koska tämä on portti jota ajetaan joka muutoksella;
   * `tools/daily-origin.mjs` on se joka kysyy koko ikkunalta. */
  if (process.env.VGLC_DIR) {
    const { corpusIndex, hitsAgainst } = await import(join(ROOT, 'tools/originality.mjs'));
    const index = await corpusIndex();
    const sample = [DAILY_ORIGIN.from, today, Math.floor((today + DAILY_ORIGIN.to) / 2),
      DAILY_ORIGIN.to].filter((d, i, a) => a.indexOf(d) === i && daily.dailyCertificate(d));
    let hits = 0;
    for (const day of sample) {
      const cert = daily.dailyCertificate(day);
      hits += hitsAgainst(index, daily.dailyBuild(day, cert.attempt).def.rows);
    }
    report.checks.push({
      name: 'päivän kentät ovat yhä puhtaita korpusta vasten',
      ok: hits === 0,
      detail: `${sample.length} päivää otoksena, ${index.files} korpustiedostoa, ${hits} osumaa`,
    });
    if (hits > 0) report.failures.push(`päivän kentissä ${hits} osumaa korpukseen`);
  } else {
    report.checks.push({
      name: 'päivän kenttien alkuperäisyys: merkintä luettu, ei väitetty',
      ok: DAILY_ORIGIN.origin === 'checked' || DAILY_ORIGIN.origin === 'not checked',
      detail: `merkintä "${DAILY_ORIGIN.origin}", VGLC_DIR asettamatta`,
    });
  }
}


/* --------------------------------- output -------------------------------- */
const pad = (s, n) => String(s).padEnd(n);
console.log(`\nKaasuvoima — verify   (${report.worlds} worlds, ${report.levels.length} levels)\n`);
console.log(`  ${pad('LEVEL', 8)}${pad('BOT', 10)}${pad('REACH', 8)}STOPPED BY`);
for (const l of report.levels) {
  console.log(`  ${pad(l.id, 8)}${pad(l.result, 10)}${pad(`${l.progress ?? '-'}%`, 8)}${l.cause || ''}`);
}
console.log('');
for (const c of report.checks) console.log(`  ${c.ok ? 'ok  ' : 'FAIL'} ${c.name}${c.detail ? `  [${c.detail}]` : ''}`);

if (report.ruleReport.length) {
  console.log('\nSUUNNITTELUSAANNOT — korjattavaa:');
  for (const level of report.ruleReport) {
    const counts = {};
    for (const p of level.problems) {
      const kind = p.replace(/ at column \d+.*| at \d+,\d+.*| of \d+/g, '');
      counts[kind] = (counts[kind] || 0) + 1;
    }
    const summary = Object.entries(counts).map(([k, n]) => `${n}x ${k}`).join(', ');
    console.log(`  ${level.id.padEnd(6)} ${summary}`);
  }
}

const hardFailures = [...report.failures, ...(booted ? [] : ['game did not boot']), ...errors];
console.log('');
if (hardFailures.length) {
  console.log('FAILURES:');
  for (const f of hardFailures) console.log(`  - ${f}`);
  process.exit(1);
}
console.log('All checks passed, no page errors.\n');
